#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48

#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_AIN0_GND 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080

#define MLX91219_SENSITIVITY 0.040f
#define SUPPLY_VOLTAGE 3.3f
#define ZERO_CURRENT_OFFSET (SUPPLY_VOLTAGE / 2.0f)

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int ads1115_write_config(uint16_t config) {
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;
    return i2cWriteI2CBlockData(i2c_handle, ADS1115_REG_CONFIG, buf + 1, 2);
}

static int ads1115_read_conversion(uint16_t *raw) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, ADS1115_REG_CONVERSION, buf, 2) != 2) {
        return -1;
    }
    *raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int read_current(float *current) {
    uint16_t raw;
    if (ads1115_write_config(ADS1115_CONFIG_OS_SINGLE |
                             ADS1115_CONFIG_MUX_AIN0_GND |
                             ADS1115_CONFIG_PGA_4_096V |
                             ADS1115_CONFIG_MODE_SINGLE |
                             ADS1115_CONFIG_DR_128SPS) < 0) {
        return -1;
    }
    if (ads1115_read_conversion(&raw) < 0) {
        return -1;
    }
    int16_t signed_raw = (int16_t)raw;
    float voltage = (float)signed_raw * 4.096f / 32768.0f;
    *current = (voltage - ZERO_CURRENT_OFFSET) / MLX91219_SENSITIVITY;
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, ADS1115_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX91219 Current Sensor Reader (ADS1115 via I2C)\n");
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        float current;
        if (read_current(&current) == 0) {
            printf("Current: %.3f A\n", current);
        } else {
            fprintf(stderr, "Error reading current sensor\n");
        }
        gpioDelay(500000);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

