#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define HEAT_SENSOR_ADC_CHANNEL 0
#define BUZZER_PIN 27
#define I2C_BUS 1
#define I2C_ADDR 0x48
#define LOG_FILE "fire_log.txt"
#define DEBOUNCE_DELAY_US 50000
#define POLL_INTERVAL_US 100000
#define BUZZER_DURATION_US 2000000
#define TEMP_THRESHOLD 60.0
#define ADC_GAIN 4.096
#define ADC_MAX 32767.0
#define ADC_VREF 3.3
#define ADC_MIN 0.0
#define TEMP_MIN 20.0
#define TEMP_MAX 80.0

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t flame_event = 0;
static volatile uint32_t last_flame_tick = 0;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void flame_isr(int gpio, int level, uint32_t tick, void *userdata);
static int read_temperature(float *temperature);
static void log_event(const char *message);
static void activate_buzzer(int duration_us);
static void cleanup(void);
static void signal_handler(int sig);

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set flame sensor pin mode.\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on flame sensor pin.\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set buzzer pin mode.\n");
        gpioTerminate();
        return 1;
    }
    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize buzzer pin state.\n");
        gpioTerminate();
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    if (gpioSetISRFuncEx(FLAME_SENSOR_PIN, FALLING_EDGE, 0, flame_isr, NULL) != 0) {
        fprintf(stderr, "Error: failed to register flame sensor ISR.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: failed to open log file '%s'.\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    printf("Fire detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        if (flame_event) {
            flame_event = 0;
            uint32_t now = gpioTick();
            if ((now - last_flame_tick) >= DEBOUNCE_DELAY_US) {
                last_flame_tick = now;
                float temperature = 0.0;
                if (read_temperature(&temperature) == 0) {
                    if (temperature > TEMP_THRESHOLD) {
                        log_event("Fire detected! Temperature: 60.0C");
                        activate_buzzer(BUZZER_DURATION_US);
                    } else {
                        log_event("Flame detected!");
                        activate_buzzer(500000);
                    }
                } else {
                    log_event("Error: failed to read temperature.");
                }
            }
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    cleanup();
    return 0;
}

static void flame_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)userdata;
    flame_event = 1;
}

static int read_temperature(float *temperature) {
    if (i2c_handle < 0) return -1;

    char config[3];
    config[0] = 0x01;
    config[1] = 0x80 | (HEAT_SENSOR_ADC_CHANNEL << 4);
    config[2] = 0x83;

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "Error: failed to write ADC configuration.\n");
        return -1;
    }

    gpioDelay(10000);

    char reg = 0x00;
    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error: failed to set ADC register pointer.\n");
        return -1;
    }

    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error: failed to read ADC data.\n");
        return -1;
    }

    int16_t raw = (data[0] << 8) | data[1];
    if (raw == 0x8000) {
        fprintf(stderr, "Error: ADC returned invalid data (0x8000).\n");
        return -1;
    }

    float voltage = ((float)raw / ADC_MAX) * ADC_VREF;
    *temperature = (voltage / ADC_GAIN) * (TEMP_MAX - TEMP_MIN) + TEMP_MIN;
    return 0;
}

static void log_event(const char *message) {
    if (log_file == NULL) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

static void activate_buzzer(int duration_us) {
    if (gpioWrite(BUZZER_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to activate buzzer.\n");
        return;
    }
    gpioDelay(duration_us);
    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to deactivate buzzer.\n");
    }
}

static void cleanup(void) {
    gpioWrite(BUZZER_PIN, 0);
    gpioSetISRFuncEx(FLAME_SENSOR_PIN, FALLING_EDGE, 0, NULL, NULL);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

