#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define DEFAULT_SENSITIVITY 0.1f
#define DEFAULT_THRESHOLD 5.0f
#define DEFAULT_SPI_DEVICE "/dev/spidev0.0"
#define DEFAULT_SPI_SPEED 1000000
#define DEFAULT_GPIO_CHIP "gpiochip4"
#define DEFAULT_FAN_PIN 18
#define LOG_FILE "current_log.txt"
#define SAMPLE_INTERVAL_US 1000000
#define ADC_MAX 1023
#define ADC_VREF 3.3f

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *fan_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(const char *device, uint32_t speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", device, strerror(errno));
        return -1;
    }
    uint8_t mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    uint8_t bits = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int read_adc(int fd, uint16_t *value) {
    uint8_t tx[3] = {0x01, 0x80, 0x00};
    uint8_t rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 0,
        .bits_per_word = 0,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    *value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static float adc_to_voltage(int adc_value) {
    return (float)adc_value * ADC_VREF / (float)(ADC_MAX + 1);
}

static float voltage_to_current(float voltage, float sensitivity) {
    return voltage / sensitivity;
}

static int log_data(float current, float threshold, int fan_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s, Current: %.2f A, Threshold: %.2f A, Fan: %s\n",
                timestamp, current, threshold, fan_state ? "ON" : "OFF");
    } else {
        fprintf(fp, "(timestamp error), Current: %.2f A, Threshold: %.2f A, Fan: %s\n",
                current, threshold, fan_state ? "ON" : "OFF");
    }
    fclose(fp);
    return 0;
}

static void cleanup(void) {
    if (fan_line) {
        gpiod_line_set_value(fan_line, 0);
        gpiod_line_release(fan_line);
        fan_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(int argc, char *argv[]) {
    float sensitivity = DEFAULT_SENSITIVITY;
    float threshold = DEFAULT_THRESHOLD;
    const char *spi_device = DEFAULT_SPI_DEVICE;
    uint32_t spi_speed = DEFAULT_SPI_SPEED;
    const char *gpio_chip = DEFAULT_GPIO_CHIP;
    int fan_pin = DEFAULT_FAN_PIN;

    int opt;
    while ((opt = getopt(argc, argv, "s:t:d:r:p:h")) != -1) {
        switch (opt) {
            case 's':
                sensitivity = atof(optarg);
                if (sensitivity <= 0.0f) {
                    fprintf(stderr, "Invalid sensitivity value\n");
                    return 1;
                }
                break;
            case 't':
                threshold = atof(optarg);
                if (threshold <= 0.0f) {
                    fprintf(stderr, "Invalid threshold value\n");
                    return 1;
                }
                break;
            case 'd':
                spi_device = optarg;
                break;
            case 'r':
                spi_speed = (uint32_t)atol(optarg);
                break;
            case 'p':
                fan_pin = atoi(optarg);
                break;
            case 'h':
            default:
                fprintf(stderr, "Usage: %s [-s sensitivity_mV_per_A] [-t threshold_A] [-d spi_device] [-r spi_speed_hz] [-p fan_gpio_pin]\n", argv[0]);
                return 1;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting signal handler: %s\n", strerror(errno));
        return 1;
    }

    spi_fd = spi_init(spi_device, spi_speed);
    if (spi_fd < 0) {
        return 1;
    }

    chip = gpiod_chip_open_by_name(gpio_chip);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", gpio_chip, strerror(errno));
        close(spi_fd);
        return 1;
    }

    fan_line = gpiod_chip_get_line(chip, fan_pin);
    if (!fan_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", fan_pin, strerror(errno));
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    if (gpiod_line_request_output(fan_line, "fan_control", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", fan_pin, strerror(errno));
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    printf("Monitoring current. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t adc_value = 0;
        if (read_adc(spi_fd, &adc_value) < 0) {
            fprintf(stderr, "ADC read failed, retrying...\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        if (adc_value == 0 || adc_value == ADC_MAX) {
            fprintf(stderr, "Warning: ADC saturated (value=%u). Sensor absent or wiring fault.\n", adc_value);
        }

        float voltage = adc_to_voltage(adc_value);
        float current = voltage_to_current(voltage, sensitivity);

        int fan_state = (current > threshold) ? 1 : 0;
        if (gpiod_line_set_value(fan_line, fan_state) < 0) {
            fprintf(stderr, "Error setting fan GPIO: %s\n", strerror(errno));
        }

        if (log_data(current, threshold, fan_state) < 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        printf("Current: %.2f A, Fan: %s\n", current, fan_state ? "ON" : "OFF");

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

