    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s, Current: %.2f A, Threshold: %.2f A, Fan: %s\n",
                timestamp, current, threshold, fan_state ? "ON" : "OFF");
    } else {
        fprintf(fp, "(timestamp error), Current: %.2f A, Threshold: %.2f A, Fan: %s\n",
                current, threshold, fan_state ? "ON" : "OFF");
    }
    fclose(fp);
    return 0;
}

static void cleanup(void) {
    if (fan_line) {
        gpiod_line_set_value(fan_line, 0);
        gpiod_line_release(fan_line);
        fan_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(int argc, char *argv[]) {
    float sensitivity = DEFAULT_SENSITIVITY;
    float threshold = DEFAULT_THRESHOLD;
    const char *spi_device = DEFAULT_SPI_DEVICE;
    uint32_t spi_speed = DEFAULT_SPI_SPEED;
    const char *gpio_chip = DEFAULT_GPIO_CHIP;
    int fan_pin = DEFAULT_FAN_PIN;

    int opt;
    while ((opt = getopt(argc, argv, "s:t:d:r:p:h")) != -1) {
        switch (opt) {
            case 's':
                sensitivity = atof(optarg);
                if (sensitivity <= 0.0f) {
                    fprintf(stderr, "Invalid sensitivity value\n");
                    return 1;
                }
                break;
            case 't':
                threshold = atof(optarg);
                if (threshold <= 0.0f) {
                    fprintf(stderr, "Invalid threshold value\n");
                    return 1;
                }
                break;
            case 'd':
                spi_device = optarg;
                break;
            case 'r':
                spi_speed = (uint32_t)atol(optarg);
                break;
            case 'p':
                fan_pin = atoi(optarg);
                break;
            case 'h':
            default:
                fprintf(stderr, "Usage: %s [-s sensitivity_mV_per_A] [-t threshold_A] [-d spi_device] [-r spi_speed_hz] [-p fan_gpio_pin]\n", argv[0]);
                return 1;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting signal handler: %s\n", strerror(errno));
        return 1;
    }

    spi_fd = spi_init(spi_device, spi_speed);
    if (spi_fd < 0) {
        return 1;
    }

    chip = gpiod_chip_open_by_name(gpio_chip);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", gpio_chip, strerror(errno));
        close(spi_fd);
        return 1;
    }

    fan_line = gpiod_chip_get_line(chip, fan_pin);
    if (!fan_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", fan_pin, strerror(errno));
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    if (gpiod_line_request_output(fan_line, "fan_control", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", fan_pin, strerror(errno));
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    printf("Monitoring current. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t adc_value = 0;
        if (read_adc(spi_fd, &adc_value) < 0) {
            fprintf(stderr, "ADC read failed, retrying...\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        if (adc_value == 0 || adc_value == ADC_MAX) {
            fprintf(stderr, "Warning: ADC saturated (value=%u). Sensor absent or wiring fault.\n", adc_value);
        }

        float voltage = adc_to_voltage(adc_value);
        float current = voltage_to_current(voltage, sensitivity);

        int fan_state = (current > threshold) ? 1 : 0;
        if (gpiod_line_set_value(fan_line, fan_state) < 0) {
            fprintf(stderr, "Error setting fan GPIO: %s\n", strerror(errno));
        }

        if (log_data(current, threshold, fan_state) < 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        printf("Current: %.2f A, Fan: %s\n", current, fan_state ? "ON" : "OFF");

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

