#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define LOG_FILE "co_log.txt"
#define SAMPLE_INTERVAL_SEC 5

/* Calibration parameters for MICS-4514 CO sensor */
#define CO_A 0.1
#define CO_B 0.5
#define CO_C 0.0

/* Simulated ADC: 16-bit signed, 0-32767 range */
#define ADC_MAX 32767.0

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

static int read_co_raw(int handle, int *raw_out) {
    char buf[2];
    int bytes = i2cReadDevice(handle, buf, 2);
    if (bytes != 2) {
        return -1;
    }
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *raw_out = raw;
    return 0;
}

static double calculate_co_ppm(int raw) {
    if (raw <= 0) {
        return 0.0;
    }
    double resistance = (double)raw / ADC_MAX * 10000.0;
    if (resistance <= 0.0) {
        return 0.0;
    }
    double ppm = CO_A * pow(resistance, CO_B) + CO_C;
    if (ppm < 0.0) {
        ppm = 0.0;
    }
    return ppm;
}

static void log_co_ppm(double ppm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, CO: %.2f PPM\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, ppm);
    }
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X on bus %d\n", I2C_ADDR, I2C_BUS);
        gpioTerminate();
        return 1;
    }

    printf("CO sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int raw;
        if (read_co_raw(i2c_handle, &raw) != 0) {
            fprintf(stderr, "I2C read error (sensor absent or bus error)\n");
        } else {
            double ppm = calculate_co_ppm(raw);
            log_co_ppm(ppm);
            printf("CO: %.2f PPM (raw=%d)\n", ppm, raw);
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

