#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDR 0x48 // MICS-4514 default I2C address
#define CO_THRESHOLD 25.0 // PPM
#define LOG_FILE "co_log.txt"
#define ALERT_FILE "alert_log.txt"
#define READ_INTERVAL 5 // seconds
#define MAX_RETRIES 3

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_i2c();
int read_sensor_data(unsigned short *co, unsigned short *no2);
float calculate_co_ppm(unsigned short co_raw);
void log_co_data(float co_ppm);
void check_threshold_and_alert(float co_ppm);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

// Initializes the I2C interface
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %d\n", I2C_ADDR, i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Reads sensor data from the MICS-4514
int read_sensor_data(unsigned short *co, unsigned short *no2) {
    char buffer[4];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        int bytes_read = i2cReadDevice(i2c_handle, buffer, 4);
        if (bytes_read == 4) {
            // MICS-4514 sends 16-bit data in little-endian format
            *co = (unsigned short)((buffer[1] << 8) | buffer[0]);
            *no2 = (unsigned short)((buffer[3] << 8) | buffer[2]);
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d/%d): %d\n", retries + 1, MAX_RETRIES, bytes_read);
            retries++;
            gpioDelay(100000); // 100ms delay before retrying
        }
    }

