#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <math.h>

#define I2C_BUS 1
#define I2C_ADDR_1 0x48
#define I2C_ADDR_2 0x49
#define ADC_REG 0x00
#define SAMPLE_INTERVAL_US 100000
#define NUM_SAMPLES 10
#define SENSITIVITY_DBV_PER_PA -38.0
#define REFERENCE_PRESSURE 20e-6
#define ERROR_VALUE -999.0

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static double read_imp23absu(int handle) {
    char buf[2];
    int bytes = i2cReadI2CBlockData(handle, ADC_REG, buf, 2);
    if (bytes != 2) {
        return ERROR_VALUE;
    }
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    double voltage = (double)raw * 3.3 / 65535.0;
    double pressure = voltage / SENSITIVITY_DBV_PER_PA;
    return 20.0 * log10(pressure / REFERENCE_PRESSURE);
}

static double average_spl(double s1, double s2) {
    return (s1 + s2) / 2.0;
}

static void log_data(double spl) {
    FILE *fp = fopen("audio_log.txt", "a");
    if (!fp) {
        perror("fopen audio_log.txt");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, spl);
    }
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int handle1 = i2cOpen(I2C_BUS, I2C_ADDR_1, 0);
    if (handle1 < 0) {
        fprintf(stderr, "Failed to open I2C device 1 (0x%02X): %d\n", I2C_ADDR_1, handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int handle2 = i2cOpen(I2C_BUS, I2C_ADDR_2, 0);
    if (handle2 < 0) {
        fprintf(stderr, "Failed to open I2C device 2 (0x%02X): %d\n", I2C_ADDR_2, handle2);
        i2cClose(handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        double s1 = read_imp23absu(handle1);
        double s2 = read_imp23absu(handle2);

        if (s1 == ERROR_VALUE || s2 == ERROR_VALUE) {
            fprintf(stderr, "Error reading sensor data. Logging error value.\n");
            log_data(ERROR_VALUE);
        } else {
            double avg = average_spl(s1, s2);
            log_data(avg);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    i2cClose(handle1);
    i2cClose(handle2);
    gpioTerminate();
    return EXIT_SUCCESS;
}

