#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>
#include <unistd.h>

// Define GPIO pins for SPI (BCM numbering)
#define SPI_CE0 8
#define SPI_CE1 9
#define SPI_MISO 9
#define SPI_MOSI 10
#define SPI_CLK 11

// Define LED pin
#define LED_PIN 27

// Define sampling parameters
#define SAMPLE_INTERVAL_US 1000  // 1 ms
#define NUM_SAMPLES 100          // 100 samples per channel
#define THRESHOLD 0.7            // 70% of normalized scale

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int read_adc(int channel);
double calculate_rms(int *samples, int num_samples);
void log_data(double mic1_rms, double mic2_rms);
void signal_handler(int signal);
void cleanup();

// Function to read ADC value from MCP3008 via SPI
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format for single-ended mode:
    // Byte 0: Start bit (0x01)
    // Byte 1: SGL/DIFF=1, D2 D1 D0 = channel, padded to upper bits
    // Byte 2: Dummy byte for clocking out data
    unsigned char spi_tx_buf[3] = {0x01, (0x08 | channel) << 4, 0x00};
    unsigned char spi_rx_buf[3] = {0};

    int spi_handle = spiOpen(0, 1000000, 0); // SPI channel 0, 1 MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel: %d\n", spi_handle);
        return -1;
    }

    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    spiClose(spi_handle);

    if (result < 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract 10-bit ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to calculate RMS value from an array of samples
double calculate_rms(int *samples, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum_of_squares += (double)samples[i] * samples[i];
    }
    return sqrt(sum_of_squares / num_samples);
}

// Function to log data to a CSV file
void log_data(double mic1_rms, double mic2_rms) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.4f,%.4f\n", timestamp, mic1_rms, mic2_rms);
        fflush(log_file); // Ensure data is written to file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open log file in append mode
    log_file = fopen("audio_events.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int *mic1_samples = (int *)malloc(NUM_SAMPLES * sizeof(int));
    int *mic2_samples = (int *)malloc(NUM_SAMPLES * sizeof(int));

    if (mic1_samples == NULL || mic2_samples == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        free(mic1_samples);
        free(mic2_samples);
        cleanup();
        return 1;
    }

    printf("Audio event detection started. Press Ctrl+C to exit.\n");

    while (running) {
        // Sample audio from both microphones
        for (int i = 0; i < NUM_SAMPLES; i++) {
            int mic1_value = read_adc(0); // ADC channel 0
            int mic2_value = read_adc(1); // ADC channel 1

            if (mic1_value < 0 || mic2_value < 0) {
                fprintf(stderr, "Error reading ADC values\n");
                break; // Exit loop if SPI read fails
            }

            mic1_samples[i] = mic1_value;
            mic2_samples[i] = mic2_value;

            gpioDelay(SAMPLE_INTERVAL_US); // Delay for 1 ms
        }

        if (!running) break;

        // Calculate RMS values
        double mic1_rms = calculate_rms(mic1_samples, NUM_SAMPLES);
        double mic2_rms = calculate_rms(mic2_samples, NUM_SAMPLES);

        // Log data
        log_data(mic1_rms, mic2_rms);

        // Check if threshold is exceeded
        if (mic1_rms > THRESHOLD || mic2_rms > THRESHOLD) {
            gpioWrite(LED_PIN, 1); // Turn on LED
            gpioDelay(500000);     // Wait for 500 ms
            gpioWrite(LED_PIN, 0); // Turn off LED
        }

        // Delay for the remaining time to maintain a 100 ms window
        gpioDelay(90000); // 90 ms delay
    }

    free(mic1_samples);
    free(mic2_samples);
    cleanup();

    return 0;
}

