#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define LED_GPIO 17
#define CURRENT_THRESHOLD 50.0f
#define BUFFER_SIZE 100
#define SAMPLE_RATE_HZ 10
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)
#define VREF 5.0f
#define ADC_MAX 32767.0f
#define ADC_V_PER_UNIT (VREF / ADC_MAX)
#define SENSOR_V_MIN 0.5f
#define SENSOR_V_MAX 4.5f
#define SENSOR_I_MIN 0.0f
#define SENSOR_I_MAX 100.0f

// ADS1115 Registers
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

// ADS1115 Config: A0 single-ended, +/-4.096V, 128 SPS, continuous
#define ADS1115_CONFIG_BASE 0x4003

// Global variables
static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static float current_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

// Function prototypes
static float read_current_sensor(void);
static void update_circular_buffer(float current);
static float calculate_average_current(void);
static void control_led(float average_current);
static void signal_handler(int signal);
static int init_i2c(void);
static void cleanup(void);

// Signal handler for graceful shutdown
static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

// Initialize I2C and configure ADS1115
static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, ADS1115_ADDR, i2c_handle);
        return -1;
    }

    // Write config: A0 single-ended, +/-4.096V, 128 SPS, continuous
    uint16_t config = ADS1115_CONFIG_BASE | 0x8000; // Start single conversion
    char config_buf[3];
    config_buf[0] = ADS1115_REG_CONFIG;
    config_buf[1] = (config >> 8) & 0xFF;
    config_buf[2] = config & 0xFF;
    if (i2cWriteDevice(i2c_handle, config_buf, 3) < 0) {
        fprintf(stderr, "Error writing ADS1115 config\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    // Wait for first conversion to complete (~8ms at 128 SPS)
    gpioDelay(10000);
    return 0;
}

// Cleanup resources
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

// Read current from the sensor via ADS1115
static float read_current_sensor(void) {
    char reg_buf[1] = {ADS1115_REG_CONVERSION};
    char data_buf[2];

    // Point to conversion register
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) < 0) {
        fprintf(stderr, "Error selecting ADS1115 conversion register\n");
        return -1.0f;
    }

    // Read 2 bytes of conversion data
    if (i2cReadDevice(i2c_handle, data_buf, 2) != 2) {
        fprintf(stderr, "Error reading ADS1115 conversion data\n");
        return -1.0f;
    }

    int16_t raw = (data_buf[0] << 8) | data_buf[1];
    // Convert to voltage, then to current
    float voltage = (raw * ADC_V_PER_UNIT);
    float current = (voltage - SENSOR_V_MIN) / (SENSOR_V_MAX - SENSOR_V_MIN) * (SENSOR_I_MAX - SENSOR_I_MIN) + SENSOR_I_MIN;
    return current;
}

// Update the circular buffer with the current reading
static void update_circular_buffer(float current) {
    current_buffer[buffer_index] = current;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

// Calculate the average current from the buffer
static float calculate_average_current(void) {
    if (buffer_count == 0) {
        return 0.0f;
    }
    float sum = 0.0f;
    for (int i = 0; i < buffer_count; i++) {
        sum += current_buffer[i];
    }
    return sum / buffer_count;
}

// Control the warning LED based on the average current
static void control_led(float average_current) {
    if (average_current > CURRENT_THRESHOLD) {
        gpioWrite(LED_GPIO, 1);
    } else {
        gpioWrite(LED_GPIO, 0);
    }
}

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    // Initialize I2C and ADS1115
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        float current = read_current_sensor();
        if (current < 0) {
            fprintf(stderr, "Error reading current sensor, retrying...\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        update_circular_buffer(current);
        float average_current = calculate_average_current();
        control_led(average_current);

        printf("Current: %.2f A, Average: %.2f A\n", current, average_current);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Cleanup
    cleanup();
    printf("\nExiting gracefully.\n");
    return 0;
}

