#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TCS34725_ADDRESS 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_ID 0x12
#define TCS34725_CONTROL 0x0F
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A
#define TCS34725_ID_VALUE 0x44

#define I2C_BUS 1
#define LOG_FILE "color_log.csv"
#define MAX_CONSECUTIVE_ERRORS 3

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, TCS34725_COMMAND_BIT | reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C register 0x%02X: %d\n", reg, result);
    }
    return result;
}

static int i2c_read_word(int handle, uint8_t reg, uint16_t *value) {
    int result = i2cReadWordData(handle, TCS34725_COMMAND_BIT | reg);
    if (result < 0) {
        fprintf(stderr, "Error reading from I2C register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint16_t)result;
    return 0;
}

static int initialize_sensor(int handle) {
    int id = i2cReadByteData(handle, TCS34725_COMMAND_BIT | TCS34725_ID);
    if (id < 0) {
        fprintf(stderr, "Error reading ID register: %d\n", id);
        return -1;
    }
    if ((id & 0xF0) != TCS34725_ID_VALUE) {
        fprintf(stderr, "Invalid ID: 0x%02X (expected 0x%02X)\n", id, TCS34725_ID_VALUE);
        return -1;
    }

    if (i2c_write_byte(handle, TCS34725_ATIME, 0xFF) < 0) return -1;
    if (i2c_write_byte(handle, TCS34725_CONTROL, 0x01) < 0) return -1;
    if (i2c_write_byte(handle, TCS34725_ENABLE, 0x01 | 0x02) < 0) return -1;

    gpioDelay(3000);
    return 0;
}

static int read_color_data(int handle, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    if (i2c_read_word(handle, TCS34725_CDATA, clear) < 0) return -1;
    if (i2c_read_word(handle, TCS34725_RDATA, red) < 0) return -1;
    if (i2c_read_word(handle, TCS34725_GDATA, green) < 0) return -1;
    if (i2c_read_word(handle, TCS34725_BDATA, blue) < 0) return -1;
    return 0;
}

static void log_color_data(FILE *file, uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(file, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue);
    fflush(file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    uint16_t clear, red, green, blue;
    int consecutive_errors = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (initialize_sensor(i2c_handle) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Clear,Red,Green,Blue\n");
        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (program_running) {
        if (read_color_data(i2c_handle, &clear, &red, &green, &blue) == 0) {
            log_color_data(log_file, clear, red, green, blue);
            consecutive_errors = 0;
        } else {
            consecutive_errors++;
            fprintf(stderr, "Error reading color data (consecutive: %d)\n", consecutive_errors);
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                fprintf(stderr, "Max consecutive errors reached, exiting.\n");
                break;
            }
        }
        gpioDelay(1000000);
    }

    cleanup();
    return 0;
}

