#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x40
#define PRESSURE_REG   0x00
#define MAX_RETRIES    3
#define SAMPLE_PERIOD  1.0
#define MAX_READ_ERRORS 10

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: pigpio error %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_pressure(uint16_t *raw_out) {
    int result = i2cReadWordData(i2c_handle, PRESSURE_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading pressure register 0x%02X: pigpio error %d\n",
                PRESSURE_REG, result);
        return -1;
    }
    *raw_out = (uint16_t)result;
    return 0;
}

static float convert_to_kpa(uint16_t raw) {
    return ((float)raw / 65535.0f) * 500.0f;
}

static int get_timestamp(char *buf, size_t len) {
    time_t now = time(NULL);
    if (now == (time_t)-1) return -1;
    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) return -1;
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) return -1;
    return 0;
}

static int log_data(const char *timestamp, float pressure) {
    if (log_file == NULL) {
        log_file = fopen("pressure_log.csv", "a");
        if (log_file == NULL) {
            perror("Error opening pressure_log.csv");
            return -1;
        }
        if (ftell(log_file) == 0) {
            fprintf(log_file, "timestamp,pressure_kPa\n");
        }
    }
    if (fprintf(log_file, "%s,%.2f\n", timestamp, pressure) < 0) {
        perror("Error writing to pressure_log.csv");
        return -1;
    }
    if (fflush(log_file) != 0) {
        perror("Error flushing pressure_log.csv");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    uint16_t raw;
    char timestamp[32];
    int consecutive_errors = 0;

    while (!terminate) {
        if (read_pressure(&raw) == 0) {
            consecutive_errors = 0;
            float pressure = convert_to_kpa(raw);
            if (get_timestamp(timestamp, sizeof(timestamp)) == 0) {
                if (log_data(timestamp, pressure) != 0) {
                    fprintf(stderr, "Error logging data\n");
                }
            } else {
                fprintf(stderr, "Error getting timestamp\n");
            }
        } else {
            consecutive_errors++;
            if (consecutive_errors >= MAX_READ_ERRORS) {
                fprintf(stderr, "Max consecutive read errors (%d) reached. Sensor may be absent or bus fault.\n",
                        MAX_READ_ERRORS);
                break;
            }
        }
        time_sleep(SAMPLE_PERIOD);
    }

    cleanup();
    return EXIT_SUCCESS;
}

