#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <math.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48

#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

#define LED_GPIO 17
#define PRESSURE_THRESHOLD 105.0f

#define ADC_VREF 6.144f
#define ADC_MAX 32767.0f

#define PRESSURE_MIN_KPA 0.0f
#define PRESSURE_MAX_KPA 400.0f
#define PRESSURE_V_MIN 0.0f
#define PRESSURE_V_MAX 5.0f

#define TEMP_MIN_C 0.0f
#define TEMP_MAX_C 100.0f
#define TEMP_V_MIN 1.0f
#define TEMP_V_MAX 2.0f

#define RETRY_COUNT 3
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int16_t read_ads1115_reg(int handle, uint8_t reg) {
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading ADS1115 reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return (int16_t)rc;
}

static int write_ads1115_reg(int handle, uint8_t reg, uint16_t val) {
    int rc = i2cWriteWordData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "Error writing ADS1115 reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int read_ads1115_conversion(int handle, int16_t *raw) {
    int16_t v = read_ads1115_reg(handle, ADS1115_REG_CONVERSION);
    if (v < 0) return -1;
    *raw = v;
    return 0;
}

static int configure_ads1115(int handle) {
    /* Config: single-shot, AIN0 vs GND, gain 2/3, 128 SPS, no comparator */
    uint16_t cfg = 0x4000 | 0x4000 | 0x0000 | 0x0080 | 0x0080 | 0x0003;
    return write_ads1115_reg(handle, ADS1115_REG_CONFIG, cfg);
}

static int read_adc_voltage(int handle, float *voltage) {
    int16_t raw;
    for (int attempt = 0; attempt < RETRY_COUNT; attempt++) {
        if (read_ads1115_conversion(handle, &raw) == 0) {
            *voltage = ((float)raw / ADC_MAX) * ADC_VREF;
            return 0;
        }
        gpioDelay(10000);
    }
    return -1;
}

static float voltage_to_pressure(float v) {
    if (v <= PRESSURE_V_MIN) return PRESSURE_MIN_KPA;
    if (v >= PRESSURE_V_MAX) return PRESSURE_MAX_KPA;
    return PRESSURE_MIN_KPA + (v - PRESSURE_V_MIN) * (PRESSURE_MAX_KPA - PRESSURE_MIN_KPA) / (PRESSURE_V_MAX - PRESSURE_V_MIN);
}

static float voltage_to_temperature(float v) {
    if (v <= TEMP_V_MIN) return TEMP_MIN_C;
    if (v >= TEMP_V_MAX) return TEMP_MAX_C;
    return TEMP_MIN_C + (v - TEMP_V_MIN) * (TEMP_MAX_C - TEMP_MIN_C) / (TEMP_V_MAX - TEMP_V_MIN);
}

static void set_led(int state) {
    if (gpioWrite(LED_GPIO, state) < 0) {
        fprintf(stderr, "Warning: failed to write LED GPIO %d\n", LED_GPIO);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n", I2C_BUS, ADS1115_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (configure_ads1115(i2c_handle) < 0) {
        fprintf(stderr, "Failed to configure ADS1115\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED GPIO %d as output\n", LED_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    set_led(0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX90834 Pressure Sensor Reader (via ADS1115)\n");
    printf("Pressure threshold: %.1f kPa | LED on GPIO%d\n", PRESSURE_THRESHOLD, LED_GPIO);
    printf("Press Ctrl+C to exit.\n\n");

    while (running) {
        float pressure_voltage = 0.0f, temperature_voltage = 0.0f;
        int ok = 1;

        if (read_adc_voltage(i2c_handle, &pressure_voltage) < 0) {
            fprintf(stderr, "ADC read failed after %d retries\n", RETRY_COUNT);
            ok = 0;
        } else if (read_adc_voltage(i2c_handle, &temperature_voltage) < 0) {
            fprintf(stderr, "ADC read failed after %d retries\n", RETRY_COUNT);
            ok = 0;
        }

        if (ok) {
            float pressure_kpa = voltage_to_pressure(pressure_voltage);
            float temp_c = voltage_to_temperature(temperature_voltage);

            printf("Pressure: %7.2f kPa | Temperature: %6.2f °C\n", pressure_kpa, temp_c);

            if (pressure_kpa > PRESSURE_THRESHOLD) {
                set_led(1);
            } else {
                set_led(0);
            }
        } else {
            set_led(0);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    set_led(0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

