#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* Configuration */
#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0 */
#define ADC_MAX_VALUE  1023       /* 10-bit ADC */
#define VREF           3.3        /* Reference voltage */
#define OVERCURRENT_THRESHOLD 10.0  /* Amperes */
#define SHUTDOWN_GPIO   27        /* GPIO pin to assert on overcurrent */
#define LOG_FILE       "current_log.txt"
#define SAMPLE_DELAY_US 100000    /* 100 ms */

/* MLX91209 parameters */
#define ZERO_CURRENT_MIDPOINT_V 1.65  /* Vcc/2 at 3.3V */
#define SENSITIVITY_MV_PER_A    66.0  /* 66 mV/A */

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Read 10-bit value from MCP3008 single-ended channel */
static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

