#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* mode 0, active-low CE */
#define ADC_CHANNEL 0
#define MAX_PPM     5000.0f
#define THRESHOLD   1000.0f
#define LOG_FILE    "methane_log.txt"
#define SAMPLE_US   1000000  /* 1 second */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended sample from the MCP3008.
 * Returns 0-1023 on success, -1 on SPI transfer failure.
 */
static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  (SGL/DIFF=1, D2 D1 D0 = channel)
     *   Byte 2: 0x00  (dummy, clocks out low 2 bits)
     * Result: ((rx[1] & 0x03) << 8) | rx[2]
     */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "spiXfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float calculate_ppm(int adc_value)
{
    return (float)adc_value / 1023.0f * MAX_PPM;
}

static void log_data(FILE *fp, int adc_value, float ppm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);
    fprintf(fp, "%s, ADC: %d, Methane: %.2f PPM\n", timestamp, adc_value, ppm);
    fflush(fp);
}

static void check_threshold(float ppm)
{
    if (ppm > THRESHOLD) {
        fprintf(stderr, "ALARM: Methane concentration exceeds threshold (%.2f PPM > %.2f PPM)!\n",
                ppm, THRESHOLD);
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (pigpio error %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Methane monitoring started. Logging to %s. Press Ctrl+C to exit.\n", LOG_FILE);

    while (g_running) {
        int adc_value = read_mcp3008(g_spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
        } else {
            float ppm = calculate_ppm(adc_value);
            log_data(fp, adc_value, ppm);
            check_threshold(ppm);
        }
        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down gracefully...\n");

    if (fclose(fp) != 0) {
        perror("fclose");
    }
    if (spiClose(g_spi_handle) < 0) {
        fprintf(stderr, "spiClose failed\n");
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

