#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_US 1000000 // 1 second
#define PRESSURE_MIN 0.0
#define PRESSURE_MAX 100.0

// ADS1115 Registers
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

// ADS1115 Config: AIN0 single-ended, 4.096V gain, 128 SPS, continuous mode
#define ADS1115_CONFIG_BASE 0x4000 // MUX[14:12]=100 (AIN0), PGA[11:9]=001 (4.096V)
#define ADS1115_CONFIG_OS 0x8000    // Operational status / single-shot bit
#define ADS1115_CONFIG_DR_128 0x0080 // Data rate 128 SPS
#define ADS1115_CONFIG_CQUE_NONE 0x0003 // Disable comparator

// Global variables
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_ads1115(int16_t *raw_value);
float convert_to_pressure(int16_t raw_value);
int log_pressure(float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

// Initialize I2C and ADS1115
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n", I2C_BUS, ADS1115_ADDR, strerror(errno));
        return -1;
    }

    // Configure ADS1115: continuous conversion, 128 SPS, AIN0 single-ended, 4.096V gain
    uint16_t config = ADS1115_CONFIG_BASE | ADS1115_CONFIG_OS | ADS1115_CONFIG_DR_128 | ADS1115_CONFIG_CQUE_NONE;
    char config_buf[3];
    config_buf[0] = ADS1115_REG_CONFIG;
    config_buf[1] = (config >> 8) & 0xFF;
    config_buf[2] = config & 0xFF;

    if (i2cWriteDevice(i2c_handle, config_buf, 3) != 0) {
        fprintf(stderr, "Error writing ADS1115 config: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    return 0;
}

// Read raw ADC value from ADS1115
int read_ads1115(int16_t *raw_value) {
    char reg_buf[1] = {ADS1115_REG_CONVERSION};
    char data_buf[2];

    // Point to conversion register
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) != 0) {
        fprintf(stderr, "Error setting ADS1115 conversion register: %s\n", strerror(errno));
        return -1;
    }

    // Read 2 bytes
    if (i2cReadDevice(i2c_handle, data_buf, 2) != 2) {
        fprintf(stderr, "Error reading ADS1115 conversion: %s\n", strerror(errno));
        return -1;
    }

    *raw_value = (int16_t)((data_buf[0] << 8) | data_buf[1]);
    return 0;
}

// Convert raw ADC value to pressure (kPa)
float convert_to_pressure(int16_t raw_value) {
    // Convert raw ADC value to voltage (0-4.096V)
    float voltage = (float)raw_value * 4.096f / 32768.0f;

    // Linear conversion: 0.5V at 0 kPa, 1.5V at 100 kPa
    float pressure = (voltage - 0.5f) / 1.0f * 100.0f;

    return pressure;
}

// Log pressure data to file
int log_pressure(float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s, %.2f kPa\n", timestamp, pressure) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    fflush(log_file);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Initialize I2C and ADS1115
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Pressure monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int16_t raw_value;
        if (read_ads1115(&raw_value) == 0) {
            float pressure = convert_to_pressure(raw_value);

            if (pressure >= PRESSURE_MIN && pressure <= PRESSURE_MAX) {
                if (log_pressure(pressure) != 0) {
                    fprintf(stderr, "Error logging pressure.\n");
                }
            } else {
                fprintf(stderr, "Pressure out of range: %.2f kPa\n", pressure);
            }
        } else {
            fprintf(stderr, "Error reading ADC value.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

