#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3208_CHANNEL_HUMIDITY 0
#define MCP3208_CHANNEL_THERMISTOR 1
#define ADC_RESOLUTION 4095.0
#define VREF 5.0
#define R0 10000.0
#define BETA 3950.0
#define ALERT_THRESHOLD 80.0
#define LOG_FILE "humidity_log.txt"
#define EMAIL_RECIPIENT "recipient@example.com"

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_adc(int channel) {
    if (channel < 0 || channel > 7) return -1;
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    if (spiXfer(spi_handle, tx, rx, 3) != 3) return -1;
    return ((rx[1] & 0x0F) << 8) | rx[2];
}

float calculate_humidity(float vout) {
    if (vout < 0.0f) return -1.0f;
    float rh = (vout - 0.824f) / 0.0315f;
    if (rh < 0.0f) rh = 0.0f;
    if (rh > 100.0f) rh = 100.0f;
    return rh;
}

float calculate_temperature(float vout) {
    if (vout < 0.0f) return -1.0f;
    float r_thermistor = (VREF / vout) - 1.0f;
    if (r_thermistor <= 0.0f) return -1.0f;
    float inv_t = 1.0f / (BETA * logf(r_thermistor / R0));
    return 1.0f / inv_t - 25.0f;
}

void send_email_alert(float humidity, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    char command[512];
    snprintf(command, sizeof(command),
             "echo \"Subject: Humidity Alert\n\nHumidity: %.2f%%, Temperature: %.2fC\" | ssmtp %s",
             humidity, temperature, EMAIL_RECIPIENT);
    FILE *pipe = popen(command, "w");
    if (!pipe) {
        fprintf(stderr, "Failed to execute ssmtp\n");
        return;
    }
    int status = pclose(pipe);
    if (status != 0) {
        fprintf(stderr, "ssmtp exited with status %d\n", status);
    }
}

void log_data(float humidity, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
    fflush(log_file);
}

void cleanup() {
    if (spi_handle >= 0) spiClose(spi_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    printf("Humidity monitoring started. Press Ctrl+C to exit.\n");
    while (running) {
        int raw_humidity = read_adc(MCP3208_CHANNEL_HUMIDITY);
        int raw_thermistor = read_adc(MCP3208_CHANNEL_THERMISTOR);
        if (raw_humidity < 0 || raw_thermistor < 0) {
            fprintf(stderr, "SPI transfer error\n");
            sleep(5);
            continue;
        }
        float vout_humidity = (float)raw_humidity / ADC_RESOLUTION * VREF;
        float vout_thermistor = (float)raw_thermistor / ADC_RESOLUTION * VREF;
        float humidity = calculate_humidity(vout_humidity);
        float temperature = calculate_temperature(vout_thermistor);
        if (humidity < 0.0f || temperature < -40.0f) {
            fprintf(stderr, "Invalid sensor data\n");
            sleep(5);
            continue;
        }
        log_data(humidity, temperature);
        if (humidity > ALERT_THRESHOLD) {
            send_email_alert(humidity, temperature);
        }
        printf("Humidity: %.2f%%, Temperature: %.2fC\n", humidity, temperature);
        sleep(5);
    }
    cleanup();
    return 0;
}

