#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

/* Configuration */
#define SPI_CHANNEL 0          /* CE0 / GPIO8 */
#define SPI_SPEED   1000000    /* 1 MHz */
#define SPI_FLAGS   0          /* Mode 0, active-low CS handled by pigpio */

#define ADC_CHANNELS 3
#define ADC_MAX_VALUE 1023     /* 10-bit ADC */

/* ADXL335 parameters (3.3V supply) */
#define V_SUPPLY 3.3f
#define V_ZERO_G 1.65f         /* 0g output voltage */
#define SENSITIVITY 0.3f       /* 300 mV/g */

#define IMPACT_THRESHOLD 2.0f  /* g */
#define SAMPLE_RATE_HZ 100
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)

#define LOG_FILE "impact_log.txt"

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a single-ended channel from the MCP3008                        */
/* Returns 0-1023 on success, -1 on error.                             */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: 3-byte transfer
     *   tx[0] = 0x01  (start bit)
     *   tx[1] = (0x08 | channel) << 4  (single-ended + channel)
     *   tx[2] = 0x00  (don't care)
     * Result: bits 9..0 in ((rx[1] & 0x03) << 8) | rx[2]
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    if (spiXfer(g_spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d\n", channel);
        return -1;
    }

    int value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    if (value < 0 || value > ADC_MAX_VALUE) {
        fprintf(stderr, "ADC value out of range on channel %d: %d\n", channel, value);
        return -1;
    }
    return value;
}

/* ------------------------------------------------------------------ */
/* Convert raw ADC value to acceleration in g                         */
/* ------------------------------------------------------------------ */
static float adc_to_g(int adc_value)
{
    float voltage = (float)adc_value * V_SUPPLY / (float)(ADC_MAX_VALUE + 1);
    return (voltage - V_ZERO_G) / SENSITIVITY;
}

/* ------------------------------------------------------------------ */
/* Log one sample line                                                   */
/* ------------------------------------------------------------------ */
static void log_sample(int x, int y, int z, float mag, int impact)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log_file, "%s,%d,%d,%d,%.3f,%s\n",
            ts, x, y, z, mag, impact ? "IMPACT DETECTED" : "OK");
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                       */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI0 CE0 at 1 MHz, Mode 0 */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, speed %d): %d\n",
                SPI_CHANNEL, SPI_SPEED, g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,x,y,z,acceleration_g,impact\n");
        fflush(g_log_file);
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADXL335 impact logger started. Logging to %s at %d Hz.\n",
           LOG_FILE, SAMPLE_RATE_HZ);
    printf("Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        int x = read_mcp3008(0);
        int y = read_mcp3008(1);
        int z = read_mcp3008(2);

        if (x < 0 || y < 0 || z < 0) {
            fprintf(stderr, "ADC read error; skipping sample\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float mag = sqrtf((float)x * x + (float)y * y + (float)z * z);
        int impact = (mag > IMPACT_THRESHOLD) ? 1 : 0;

        log_sample(x, y, z, mag, impact);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

