#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SI1172_I2C_ADDR 0x49
#define I2C_BUS 1
#define LOG_FILE "biometric_log.csv"
#define SAMPLE_INTERVAL_US 1000000
#define MAX_RETRIES 3

/* Si1172 command register (0xC0) and data registers (0xC1-0xC4) */
#define SI1172_REG_COMMAND 0xC0
#define SI1172_REG_RESPONSE 0xC1
#define SI1172_REG_FIFO_DATA 0xC2
#define SI1172_REG_FIFO_COUNT 0xC3
#define SI1172_REG_IRQ_STATUS 0xC4

/* Si1172 command codes */
#define SI1172_CMD_RESET 0x01
#define SI1172_CMD_START 0x02
#define SI1172_CMD_STOP 0x03
#define SI1172_CMD_ALS_FORCE 0x0A

/* Globals for signal handler cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    int hr;
    int spo2;
    int error;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %d\n", reg, value, rc);
    }
    return rc;
}

static int i2c_read_byte(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C block read failed (reg=0x%02X, expected=%u, got=%d)\n", reg, len, rc);
        return -1;
    }
    return 0;
}

static int si1172_reset(int handle) {
    if (i2c_write_byte(handle, SI1172_REG_COMMAND, SI1172_CMD_RESET) < 0) return -1;
    gpioDelay(10000); /* 10 ms reset delay */
    return 0;
}

static int si1172_start(int handle) {
    if (i2c_write_byte(handle, SI1172_REG_COMMAND, SI1172_CMD_START) < 0) return -1;
    gpioDelay(10000); /* 10 ms startup delay */
    return 0;
}

static int si1172_read_fifo(int handle, uint8_t *buf, uint32_t len) {
    uint8_t count;
    if (i2c_read_byte(handle, SI1172_REG_FIFO_COUNT, &count) < 0) return -1;
    if (count > len) count = len;
    if (i2c_read_block(handle, SI1172_REG_FIFO_DATA, buf, count) < 0) return -1;
    return (int)count;
}

static sensor_data_t read_sensor_data(int handle) {
    sensor_data_t data = {0, 0, 0};
    uint8_t buf[32];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (si1172_read_fifo(handle, buf, sizeof(buf)) > 0) {
            /* Proxy HR and SpO2 from raw IR and RED ADC samples */
            data.hr = (int)(buf[0] + buf[1]);
            data.spo2 = (int)(buf[2] + buf[3]);
            data.error = 0;
            return data;
        }
        retries++;
        gpioDelay(10000); /* 10 ms backoff before retry */
    }

    data.error = 1;
    return data;
}

static void log_data(FILE *fp, sensor_data_t data) {
    time_t now = time(NULL);
    fprintf(fp, "%ld,%d,%d,%d\n", (long)now, data.hr, data.spo2, data.error);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1172_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, SI1172_I2C_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Probe: try a reset to confirm the sensor is present */
    if (si1172_reset(i2c_handle) < 0) {
        fprintf(stderr, "Si1172 not responding at 0x%02X — check wiring and sensor presence\n", SI1172_I2C_ADDR);
        cleanup();
        return 1;
    }

    if (si1172_start(i2c_handle) < 0) {
        fprintf(stderr, "Failed to start Si1172\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    fprintf(log_file, "timestamp,HR_bpm,SpO2_percent,error_flag\n");
    fflush(log_file);

    printf("Logging Si1172 data to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (!terminate) {
        sensor_data_t data = read_sensor_data(i2c_handle);
        log_data(log_file, data);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

