#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL_1 0
#define ADC_CHANNEL_2 1
#define NUM_SAMPLES 100
#define GAIN_DEFAULT 1.0f

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx[3] = {0x01, (char)((0x08 | channel) << 4), 0x00};
    char rx[3] = {0};

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

int main(int argc, char *argv[]) {
    float gain = GAIN_DEFAULT;

    if (argc > 1) {
        gain = atof(argv[1]);
        if (gain <= 0.0f) {
            fprintf(stderr, "Warning: Invalid gain value, using default %.2f\n", GAIN_DEFAULT);
            gain = GAIN_DEFAULT;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Timestamp,Audio1,Audio2,NoiseCancled\n");

    while (running) {
        int audio1 = read_adc(ADC_CHANNEL_1);
        int audio2 = read_adc(ADC_CHANNEL_2);

        if (audio1 < 0 || audio2 < 0) {
            fprintf(stderr, "Error: ADC read failed, exiting\n");
            break;
        }

        float noise_canceled = (audio1 - audio2) * gain;
        printf("%d,%d,%.2f\n", 0, audio1, noise_canceled);
        fflush(stdout);

        gpioDelay(100000);
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

