#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define BUZZER_GPIO_LINE 18
#define BUZZER_CONSUMER "flame-buzzer"
#define LOG_FILE "flame_log.txt"
#define AMBIENT_TEMP_FILE "ambient_temp.txt"
#define SAMPLE_INTERVAL_US 500000
#define MAX_RETRIES 3
#define VOLTAGE_THRESHOLD 1.0
#define TEMP_COEFFICIENT 0.001

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *buzzer_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_ambient_temperature(void) {
    FILE *fp = fopen(AMBIENT_TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open %s: %s\n", AMBIENT_TEMP_FILE, strerror(errno));
        return -1;
    }
    float temp;
    if (fscanf(fp, "%f", &temp) != 1) {
        fprintf(stderr, "Warning: invalid temperature in %s\n", AMBIENT_TEMP_FILE);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return (int)(temp + 0.5f);
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error: SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float calculate_voltage(int adc_value, float temperature) {
    float voltage = (float)adc_value * 3.3f / 1023.0f;
    return voltage + (temperature - 25.0f) * TEMP_COEFFICIENT;
}

static void log_data(int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_fp, "%s,%d,%.3f,%.3f,%.1f,%d\n",
            timestamp, raw_adc, voltage, compensated_voltage, temperature, flame_detected);
    fflush(log_fp);
}

static void cleanup(void) {
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
        buzzer_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log");
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI");
        fclose(log_fp);
        return 1;
    }
    unsigned char mode = SPI_MODE_0;
    unsigned char bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("SPI_IOC_WR_MODE");
        cleanup();
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        cleanup();
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &(unsigned int){SPI_SPEED}) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        perror("gpiod_chip_open");
        cleanup();
        return 1;
    }
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_GPIO_LINE);
    if (!buzzer_line) {
        perror("gpiod_chip_get_line");
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(buzzer_line, BUZZER_CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output");
        cleanup();
        return 1;
    }

    int ambient_temp = read_ambient_temperature();
    if (ambient_temp < 0) {
        fprintf(stderr, "Using default ambient temperature: 25.0°C\n");
        ambient_temp = 25;
    }
    printf("Ambient temperature: %.1f°C\n", ambient_temp);

    while (running) {
        int raw_adc = -1;
        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            raw_adc = read_mcp3008(MCP3008_CHANNEL);
