        perror("gpiod_chip_open");
        cleanup();
        return 1;
    }
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_GPIO_LINE);
    if (!buzzer_line) {
        perror("gpiod_chip_get_line");
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(buzzer_line, BUZZER_CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output");
        cleanup();
        return 1;
    }

    int ambient_temp = read_ambient_temperature();
    if (ambient_temp < 0) {
        fprintf(stderr, "Using default ambient temperature: 25.0°C\n");
