        if (raw_adc < 0 || raw_adc > 1023) {
            fprintf(stderr, "Error: ADC read failed after %d attempts, skipping iteration\n", MAX_RETRIES);
            gpiod_line_set_value(buzzer_line, 0);
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }
        float voltage = (float)raw_adc * 3.3f / 1023.0f;
        float compensated_voltage = voltage + (ambient_temp - 25.0f) * TEMP_COEFFICIENT;
        int flame_detected = (compensated_voltage > VOLTAGE_THRESHOLD) ? 1 : 0;
        gpiod_line_set_value(buzzer_line, flame_detected ? 1 : 0);
        log_data(raw_adc, voltage, compensated_voltage, ambient_temp, flame_detected);
        printf("Raw: %d, Voltage: %.3fV, Compensated: %.3fV, Temp: %.1f°C, Flame: %s\n",
               raw_adc, voltage, compensated_voltage, ambient_temp, flame_detected ? "YES" : "NO");
