#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define LED_GPIO    17
#define WATER_LEVEL_THRESHOLD_HIGH 75.0
#define WATER_LEVEL_THRESHOLD_LOW  70.0
#define LOG_FILE    "water_levels.json"
#define SAMPLE_INTERVAL_US 5000000
#define SPI_RETRY_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)(0x80 | (channel << 4)), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float calculate_water_level_percentage(int adc_value) {
    if (adc_value < 0) return 0.0f;
    if (adc_value > 1023) return 100.0f;
    return (float)adc_value / 1023.0f * 100.0f;
}

static void log_water_level(float percentage) {
    if (!log_file) return;

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[40];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp),
             ".%03ldZ", ts.tv_nsec / 1000000);

    fprintf(log_file, "  {\"timestamp\": \"%s\", \"water_level\": %.2f},\n",
            timestamp, percentage);
    fflush(log_file);
}

static void control_led(float percentage) {
    static int led_state = 0;
    if (percentage > WATER_LEVEL_THRESHOLD_HIGH && led_state == 0) {
        gpioWrite(LED_GPIO, 1);
        led_state = 1;
    } else if (percentage < WATER_LEVEL_THRESHOLD_LOW && led_state == 1) {
        gpioWrite(LED_GPIO, 0);
        led_state = 0;
    }
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    if (log_file) {
        fprintf(log_file, "]\n");
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "r+");
    if (!log_file) {
        log_file = fopen(LOG_FILE, "w");
        if (!log_file) {
            fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
            spiClose(spi_handle);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        fprintf(log_file, "[\n");
        fflush(log_file);
    } else {
        fseek(log_file, 0, SEEK_END);
        long file_size = ftell(log_file);
        if (file_size <= 2) {
            fseek(log_file, 0, SEEK_SET);
            fprintf(log_file, "[\n");
            fflush(log_file);
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            gpioDelay(SPI_RETRY_DELAY_US);
            continue;
        }

        float percentage = calculate_water_level_percentage(adc_value);
        printf("Water level: %.2f%% (ADC: %d)\n", percentage, adc_value);

        log_water_level(percentage);
        control_led(percentage);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

