#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0       // SPI0 CE0
#define SPI_SPEED 1000000   // 1 MHz
#define ADC_CHANNEL 0       // MCP3008 Channel 0
#define VREF 3.3            // Reference voltage
#define ADC_RESOLUTION 1024 // 10-bit ADC
#define SAMPLE_INTERVAL_US 100000 // 100ms

// Global variables
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_adc(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_lpm(float voltage);
int log_data(float voltage, float lpm);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

// Function to read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format for single-ended mode:
    // Byte 0: 0x01 (Start bit)
    // Byte 1: (0x08 | channel) << 4 (Single-ended mode + channel selection)
    // Byte 2: 0x00 (Don't care)
    char spi_tx_buf[3] = {0x01, (char)((0x08 | channel) << 4), 0x00};
    char spi_rx_buf[3] = {0};

    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    // Extract 10-bit ADC value from response
    // rx_buf[1] contains the two most significant bits in its lower 2 bits
    // rx_buf[2] contains the 8 least significant bits
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) | (spi_rx_buf[2] & 0xFF);
    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return ((float)adc_value / (float)(ADC_RESOLUTION - 1)) * VREF;
}

// Function to convert voltage to flow rate (LPM)
float voltage_to_lpm(float voltage) {
    // Placeholder linear conversion. Replace with actual sensor calibration curve.
    // AWM7300V: 0.5V to 4.5V corresponds to 0 to 200 LPM.
    if (voltage < 0.5f) return 0.0f;
    if (voltage > 4.5f) return 200.0f;
    return (voltage - 0.5f) * (200.0f / 3.0f);
}

// Function to log data to CSV file
int log_data(float voltage, float lpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: Failed to get local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.3f,%.3f\n", timestamp, voltage, lpm) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
        return -1;
    }
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file in append mode
    log_file = fopen("airflow_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Voltage (V),Flow Rate (LPM)\n");
        fflush(log_file);
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        // Convert ADC value to voltage and flow rate
