        float voltage = adc_to_voltage(adc_value);
        float lpm = voltage_to_lpm(voltage);

        // Log data
        if (log_data(voltage, lpm) != 0) {
            fprintf(stderr, "Error: Failed to log data\n");
        }

        // Wait for the next sample interval
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    // Cleanup
    cleanup();
    printf("Airflow monitoring stopped.\n");
    return 0;
}

