#define DEFAULT_MAX_RAW 700
#define DEFAULT_MOISTURE_THRESHOLD 30.0
#define DEFAULT_LOGGING_FREQUENCY 60
#define DEFAULT_EMAIL_RECIPIENT "recipient@example.com"
#define DEFAULT_MSMTP_CONFIG "/etc/msmtprc"

#define MAX_EMAIL_RECIPIENTS 10
#define MAX_EMAIL_RECIPIENT_LENGTH 100
#define MAX_MSMTP_CONFIG_PATH 256

typedef struct {
    int spi_channel;
    int adc_channel;
    int min_raw;
    int max_raw;
    float moisture_threshold;
    int logging_frequency;
    char email_recipient[MAX_EMAIL_RECIPIENTS][MAX_EMAIL_RECIPIENT_LENGTH];
    int num_recipients;
    char msmtp_config_path[MAX_MSMTP_CONFIG_PATH];
} Config;

static Config config;
static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void parse_arguments(int argc, char *argv[]) {
    config.spi_channel = DEFAULT_SPI_CHANNEL;
    config.adc_channel = DEFAULT_ADC_CHANNEL;
    config.min_raw = DEFAULT_MIN_RAW;
    config.max_raw = DEFAULT_MAX_RAW;
    config.moisture_threshold = DEFAULT_MOISTURE_THRESHOLD;
    config.logging_frequency = DEFAULT_LOGGING_FREQUENCY;
    config.num_recipients = 0;
    strncpy(config.msmtp_config_path, DEFAULT_MSMTP_CONFIG, sizeof(config.msmtp_config_path) - 1);
    config.msmtp_config_path[sizeof(config.msmtp_config_path) - 1] = '\0';

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--spi_channel") == 0 && i + 1 < argc) {
            config.spi_channel = atoi(argv[++i]);
        } else if (strcmp(argv[i], "--adc_channel") == 0 && i + 1 < argc) {
            config.adc_channel = atoi(argv[++i]);
        } else if (strcmp(argv[i], "--min_raw") == 0 && i + 1 < argc) {
            config.min_raw = atoi(argv[++i]);
        } else if (strcmp(argv[i], "--max_raw") == 0 && i + 1 < argc) {
            config.max_raw = atoi(argv[++i]);
        } else if (strcmp(argv[i], "--moisture_threshold") == 0 && i + 1 < argc) {
            config.moisture_threshold = atof(argv[++i]);
        } else if (strcmp(argv[i], "--logging_frequency") == 0 && i + 1 < argc) {
            config.logging_frequency = atoi(argv[++i]);
        } else if (strcmp(argv[i], "--email_recipient") == 0 && i + 1 < argc) {
            if (config.num_recipients < MAX_EMAIL_RECIPIENTS) {
                strncpy(config.email_recipient[config.num_recipients], argv[++i], MAX_EMAIL_RECIPIENT_LENGTH - 1);
                config.email_recipient[config.num_recipients][MAX_EMAIL_RECIPIENT_LENGTH - 1] = '\0';
                config.num_recipients++;
            } else {
                fprintf(stderr, "Error: Maximum number of email recipients reached (%d)\n", MAX_EMAIL_RECIPIENTS);
            }
        } else if (strcmp(argv[i], "--msmtprc") == 0 && i + 1 < argc) {
            strncpy(config.msmtp_config_path, argv[++i], sizeof(config.msmtp_config_path) - 1);
            config.msmtp_config_path[sizeof(config.msmtp_config_path) - 1] = '\0';
        } else {
            fprintf(stderr, "Error: Unknown argument '%s'. Use --help for usage.\n", argv[i]);
            exit(EXIT_FAILURE);
        }
    }
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float calculate_moisture_percentage(int raw_value, int min_raw, int max_raw) {
    if (max_raw <= min_raw) {
        fprintf(stderr, "Error: max_raw (%d) must be greater than min_raw (%d)\n", max_raw, min_raw);
        return -1.0f;
    }
    float percentage = 100.0f - ((float)(raw_value - min_raw) / (float)(max_raw - min_raw)) * 100.0f;
    if (percentage < 0.0f) percentage = 0.0f;
    if (percentage > 100.0f) percentage = 100.0f;
    return percentage;
}

static int log_data(float moisture_percentage) {
    FILE *fp = fopen("plant_data.txt", "a");
    if (fp == NULL) {
        perror("Error opening plant_data.txt");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f\n", timestamp, moisture_percentage);
    fclose(fp);
    return 0;
}

static int send_email_alert(float moisture_percentage) {
    if (moisture_percentage < config.moisture_threshold) {
        char command[512];
        snprintf(command, sizeof(command),
                 "echo \"Subject: Plant Moisture Alert\n\nMoisture level is below threshold: %.2f%%\" | msmtp --file=%s %s",
                 moisture_percentage, config.msmtp_config_path,
                 (config.num_recipients == 1) ? config.email_recipient[0] : "");

        FILE *fp = popen(command, "r");
        if (fp == NULL) {
            perror("Error executing msmtp");
            return -1;
        }

        int status = pclose(fp);
        if (status != 0) {
            fprintf(stderr, "Error: msmtp exited with status %d\n", status);
            return -1;
        }
    }
    return 0;
}

static void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    parse_arguments(argc, argv);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(config.spi_channel, 500000, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (channel %d)\n", config.spi_channel);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Plant monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int raw_value = read_mcp3008(config.adc_channel);
        if (raw_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value, retrying in %d seconds...\n", config.logging_frequency);
            sleep(config.logging_frequency);
            continue;
        }

        float moisture_percentage = calculate_moisture_percentage(raw_value, config.min_raw, config.max_raw);
        if (moisture_percentage < 0.0f) {
            fprintf(stderr, "Error: Invalid moisture percentage calculation\n");
            sleep(config.logging_frequency);
            continue;
        }

        if (log_data(moisture_percentage) != 0) {
            fprintf(stderr, "Warning: Failed to log data\n");
        }

        if (send_email_alert(moisture_percentage) != 0) {
            fprintf(stderr, "Warning: Failed to send email alert\n");
        }

        printf("Moisture: %.2f%%\n", moisture_percentage);

        for (int i = 0; i < config.logging_frequency && !terminate; i++) {
            sleep(1);
        }
    }

    cleanup();
    printf("Plant monitoring stopped.\n");
    return EXIT_SUCCESS;
}

