#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Configuration
#define SPI_CHANNEL 0       // SPI0 CE0 (GPIO8)
#define SPI_SPEED 1000000   // 1 MHz
#define ADC_CHANNEL 0       // MCP3008 CH0
#define VREF 3.3            // Reference voltage for MCP3008
#define ADC_MAX 1023        // 10-bit ADC
#define SAMPLE_INTERVAL 1   // Seconds
#define SENSOR_MIN_VOLTAGE 0.5 // Minimum voltage for valid sensor reading
#define SENSOR_MAX_VOLTAGE 4.5 // Maximum voltage for valid sensor reading
#define PRESSURE_MIN_KPA 10.0 // Minimum pressure in kPa
#define PRESSURE_MAX_KPA 150.0 // Maximum pressure in kPa

// Global variables
static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
double adc_to_voltage(int adc_value);
double voltage_to_pressure(double voltage);
void log_pressure(double pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

// Function to read from MCP3008 ADC via SPI
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format for single-ended mode:
    // Byte 0: Start bit (0x01)
    // Byte 1: SGL/DIFF=1 (single-ended) + D2 D1 D0 (channel) + padding
    // Byte 2: Don't care (0x00)
    unsigned char tx_buf[3] = {0x01, (unsigned char)(0x80 | (channel << 4)), 0x00};
    unsigned char rx_buf[3] = {0};

    int result = spiXfer(spi_handle, (char *)tx_buf, (char *)rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    // Extract 10-bit ADC value from response
    // rx_buf[1] contains bits 9-2, rx_buf[2] contains bits 1-0
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to voltage
double adc_to_voltage(int adc_value) {
    return ((double)adc_value / (double)ADC_MAX) * VREF;
}

// Function to convert voltage to pressure (kPa)
double voltage_to_pressure(double voltage) {
    // Clamp voltage to valid sensor range to detect sensor-absent conditions
    if (voltage < SENSOR_MIN_VOLTAGE) {
        return -1.0; // Sensor absent or shorted
    }
    if (voltage > SENSOR_MAX_VOLTAGE) {
        return -1.0; // Sensor absent or open
    }

    // Linear mapping: 0.5V -> 10 kPa, 4.5V -> 150 kPa
    return PRESSURE_MIN_KPA + (voltage - SENSOR_MIN_VOLTAGE) * 
           (PRESSURE_MAX_KPA - PRESSURE_MIN_KPA) / 
           (SENSOR_MAX_VOLTAGE - SENSOR_MIN_VOLTAGE);
}

// Function to log pressure readings with ISO-8601 timestamp
void log_pressure(double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (pressure < 0) {
        printf("%s - Error: Invalid pressure reading (sensor absent or out of range)\n", timestamp);
    } else {
        printf("%s - Pressure: %.2f kPa\n", timestamp, pressure);
    }
    fflush(stdout);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX90823 Pressure Sensor Reader\n");
    printf("Reading every %d second(s). Press Ctrl+C to exit.\n", SAMPLE_INTERVAL);

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            log_pressure(-1.0);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        double voltage = adc_to_voltage(adc_value);
        double pressure = voltage_to_pressure(voltage);

        if (pressure < 0) {
            fprintf(stderr, "Warning: Sensor reading out of valid range (V=%.3f)\n", voltage);
        }

        log_pressure(pressure);
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    cleanup();
    printf("\nProgram terminated gracefully.\n");
    return 0;
}

