    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (pressure < 0) {
        printf("%s - Error: Invalid pressure reading (sensor absent or out of range)\n", timestamp);
    } else {
        printf("%s - Pressure: %.2f kPa\n", timestamp, pressure);
    }
    fflush(stdout);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX90823 Pressure Sensor Reader\n");
    printf("Reading every %d second(s). Press Ctrl+C to exit.\n", SAMPLE_INTERVAL);

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            log_pressure(-1.0);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        double voltage = adc_to_voltage(adc_value);
        double pressure = voltage_to_pressure(voltage);

        if (pressure < 0) {
            fprintf(stderr, "Warning: Sensor reading out of valid range (V=%.3f)\n", voltage);
        }

        log_pressure(pressure);
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    cleanup();
    printf("\nProgram terminated gracefully.\n");
    return 0;
}

