#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_BITS_PER_WORD 8
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int setup_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int spi_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", device, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int read_mcp3008(int fd, uint8_t channel) {
    if (channel > 7) {
        fprintf(stderr, "Invalid ADC channel %u\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: 3-byte transfer
     * Byte 0: 0x01 (start bit)
     * Byte 1: (0x08 | channel) << 4 (single-ended + channel select)
     * Byte 2: 0x00 (don't care, clocked out to read low byte)
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS_PER_WORD;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    /* 10-bit result: lower 2 bits of rx[1] + 8 bits of rx[2] */
    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float calculate_moisture_percentage(int adc_value) {
    if (adc_value < 0) return 0.0f;
    if (adc_value > 1023) return 100.0f;
    return (float)adc_value / 1023.0f * 100.0f;
}

int main(void) {
    if (setup_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    int fd = spi_init(SPI_DEVICE);
    if (fd < 0) {
        return EXIT_FAILURE;
    }

    printf("Soil Moisture Sensor Reading (MCP3008 on %s, channel %d)\n", SPI_DEVICE, ADC_CHANNEL);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_value = read_mcp3008(fd, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying in %d seconds...\n", SAMPLE_INTERVAL_SEC);
        } else {
            float moisture = calculate_moisture_percentage(adc_value);
            printf("Moisture: %.2f%% (ADC: %d)\n", moisture, adc_value);
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nExiting...\n");
    if (close(fd) == -1) {
        fprintf(stderr, "Error closing SPI device: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}

