        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nExiting...\n");
    if (close(fd) == -1) {
        fprintf(stderr, "Error closing SPI device: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}

