#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define PUMP_GPIO 17
#define MOISTURE_LOW_THRESHOLD 300
#define MOISTURE_HIGH_THRESHOLD 600
#define BUFFER_SIZE 20
#define SAMPLE_INTERVAL_US 5000000

#define MCP3008_CHANNEL 0

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static int pump_state = 0;
static int buffer_index = 0;
static int buffer_count = 0;
static int buffer_filled = 0;
static int buffer_capacity = BUFFER_SIZE;
static int moisture_readings[BUFFER_SIZE];
static int pump_states[BUFFER_SIZE];
static time_t timestamps[BUFFER_SIZE];

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void add_to_buffer(int moisture, int pump_state) {
    time_t now = time(NULL);
    timestamps[buffer_index] = now;
    moisture_readings[buffer_index] = moisture;
    pump_states[buffer_index] = pump_state;
    buffer_index = (buffer_index + 1) % buffer_capacity;
    if (buffer_count < buffer_capacity) buffer_count++;
}

static void print_buffer(void) {
    printf("\n--- Log Buffer ---\n");
    int start = (buffer_count < buffer_capacity) ? 0 : buffer_index;
    for (int i = 0; i < buffer_count; i++) {
        int idx = (start + i) % buffer_capacity;
        char time_str[32];
        struct tm *tm_info = localtime(&timestamps[idx]);
        if (tm_info) {
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
        } else {
            strncpy(time_str, "UNKNOWN", sizeof(time_str));
        }
        printf("[%s] Moisture: %d, Pump: %s\n", time_str, moisture_readings[idx], pump_states[idx] ? "ON" : "OFF");
    }
    printf("--- End of Log Buffer ---\n\n");
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) return -1;
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0, 0, 0};
    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) return -1;
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static void control_pump(int moisture) {
    if (moisture < MOISTURE_LOW_THRESHOLD && pump_state == 0) {
        if (gpioWrite(PUMP_GPIO, 1) == 0) {
            pump_state = 1;
            add_to_buffer(moisture, pump_state);
            printf("Moisture %d below threshold %d. Pump ON.\n", moisture, MOISTURE_LOW_THRESHOLD);
        } else {
            fprintf(stderr, "Error: Failed to write GPIO %d\n", PUMP_GPIO);
        }
    } else if (moisture > MOISTURE_HIGH_THRESHOLD && pump_state == 1) {
        if (gpioWrite(PUMP_GPIO, 0) == 0) {
            pump_state = 0;
            add_to_buffer(moisture, pump_state);
            printf("Moisture %d above threshold %d. Pump OFF.\n", moisture, MOISTURE_HIGH_THRESHOLD);
        } else {
            fprintf(stderr, "Error: Failed to write GPIO %d\n", PUMP_GPIO);
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, speed %d)\n", SPI_CHANNEL, SPI_SPEED);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PUMP_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    gpioWrite(PUMP_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Soil Moisture Monitoring System started. Press Ctrl+C to exit.\n");

    while (running) {
        int moisture = read_mcp3008(MCP3008_CHANNEL);
        if (moisture < 0) {
            fprintf(stderr, "SPI transfer error on channel %d\n", MCP3008_CHANNEL);
        } else {
            printf("Moisture level: %d\n", moisture);
            control_pump(moisture);
            add_to_buffer(moisture, pump_state);
            print_buffer();
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(PUMP_GPIO, 0);
    spiClose(spi_handle);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return 0;
}

