#define REG_INTR_ENABLE_2 0x03
#define REG_FIFO_WR_PTR 0x04
#define REG_OVERFLOW_CTR 0x05
#define REG_FIFO_RD_PTR 0x06
#define REG_FIFO_DATA 0x07
#define REG_FIFO_CONFIG 0x08
#define REG_MODE_CONFIG 0x09
#define REG_SPO2_CONFIG 0x0A
#define REG_LED1_PA 0x0C
#define REG_LED2_PA 0x0D
#define REG_PART_ID 0xFF

#define EXPECTED_PART_ID 0x15
#define SPO2_THRESHOLD 95.0
#define HR_THRESHOLD 100.0
#define SAMPLE_INTERVAL_US 1000000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(uint8_t reg, uint8_t val) {
    char buf[2] = { (char)reg, (char)val };
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing reg 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

static int read_reg(uint8_t reg, uint8_t *val) {
    char buf[1] = { (char)reg };
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error setting read reg 0x%02X\n", reg);
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, 1) != 1) {
        fprintf(stderr, "Error reading reg 0x%02X\n", reg);
        return -1;
    }
    *val = (uint8_t)buf[0];
    return 0;
}

static int read_fifo(uint32_t *red, uint32_t *ir) {
    char buf[6];
    if (i2cWriteDevice(i2c_handle, (char *)&REG_FIFO_DATA, 1) != 0) {
        fprintf(stderr, "Error setting FIFO read pointer\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, 6) != 6) {
