    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int control_buzzer(int state) {
    if (gpioWrite(BUZZER_GPIO, state) != 0) {
        fprintf(stderr, "Error: Failed to write GPIO %d\n", BUZZER_GPIO);
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", BUZZER_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (control_buzzer(0) != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler\n");
    }

    int buzzer_on = 0;

    while (running) {
        int gas_value = read_mcp3008(ADC_CHANNEL);
        if (gas_value < 0) {
            fprintf(stderr, "Error: Failed to read gas sensor\n");
            break;
        }

        printf("Gas value: %d\n", gas_value);

        if (gas_value >= GAS_THRESHOLD && !buzzer_on) {
            if (control_buzzer(1) == 0) {
                buzzer_on = 1;
                printf("Buzzer ON\n");
            }
        } else if (gas_value < GAS_THRESHOLD && buzzer_on) {
            if (control_buzzer(0) == 0) {
                buzzer_on = 0;
                printf("Buzzer OFF\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    control_buzzer(0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

