#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48
#define ADS1115_REG_CONV 0x00
#define ADS1115_REG_CFG  0x01

#define RELAY_PIN      17
#define REED_PIN       27

#define NUM_BASELINE_SAMPLES 10
#define BASELINE_DELAY_MS   50
#define POLL_DELAY_MS       200
#define RELAY_HOLD_MS       3000
#define THRESHOLD_PCT       80.0f

#define LOG_FILE "/var/log/door_events.log"

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_line = NULL;
static struct gpiod_line *reed_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    if (write(fd, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *out) {
    if (write(fd, &reg, 1) != 1) return -1;
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) return -1;
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int read_adc(int fd, int16_t *raw) {
    uint16_t cfg = 0x8000 | 0x4000 | 0x0000 | 0x0003; /* AIN0, single-shot, 4.096V, 128 SPS */
    if (i2c_write16(fd, ADS1115_REG_CFG, cfg) < 0) return -1;
    usleep(10000);
    uint16_t conv;
    if (i2c_read16(fd, ADS1115_REG_CONV, &conv) < 0) return -1;
    *raw = (int16_t)conv;
    return 0;
}

static int calibrate_sensor(int fd, float *threshold) {
    int64_t sum = 0;
    int valid = 0;
    for (int i = 0; i < NUM_BASELINE_SAMPLES; i++) {
        int16_t raw;
        if (read_adc(fd, &raw) < 0) {
            fprintf(stderr, "Calibration failed: I2C read error at sample %d\n", i);
            return -1;
        }
        sum += raw;
        usleep(BASELINE_DELAY_MS * 1000);
        valid++;
    }
    if (valid == 0) return -1;
    float avg = (float)sum / valid;
    *threshold = avg * (100.0f - THRESHOLD_PCT) / 100.0f;
    printf("Calibration complete. Baseline: %.2f, Threshold: %.2f\n", avg, *threshold);
    return 0;
}

static void log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) { perror("fopen log"); return; }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm;
    localtime_r(&ts.tv_sec, &tm);
    char tbuf[64];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s.%03ld: %s\n", tbuf, ts.tv_nsec / 1000000, msg);
    fclose(fp);
}

static void cleanup(void) {
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
        relay_line = NULL;
    }
    if (reed_line) {
        gpiod_line_release(reed_line);
        reed_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) { perror("open i2c"); return 1; }
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("ioctl I2C_SLAVE"); cleanup(); return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) { perror("gpiod_chip_open"); cleanup(); return 1; }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    reed_line = gpiod_chip_get_line(chip, REED_PIN);
    if (!relay_line || !reed_line) {
        perror("gpiod_chip_get_line"); cleanup(); return 1;
    }
    if (gpiod_line_request_output(relay_line, "door_lock", 0) < 0) {
        perror("relay request"); cleanup(); return 1;
    }
    if (gpiod_line_request_input(reed_line, "door_sensor") < 0) {
        perror("reed request"); cleanup(); return 1;
    }

    float threshold = 0.0f;
    if (calibrate_sensor(i2c_fd, &threshold) < 0) {
        fprintf(stderr, "Calibration failed. Check wiring and sensor.\n");
        cleanup(); return 1;
    }

    printf("Monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int16_t raw;
        if (read_adc(i2c_fd, &raw) < 0) {
            fprintf(stderr, "ADC read error: %s\n", strerror(errno));
            log_event("ADC read error");
            usleep(POLL_DELAY_MS * 1000);
            continue;
        }

        float distance = (float)raw;
        int below = (distance < threshold) ? 1 : 0;

        if (below) {
            printf("Distance below threshold. Releasing lock.\n");
            if (gpiod_line_set_value(relay_line, 1) < 0) {
                perror("relay on");
            }
            for (int i = 0; i < RELAY_HOLD_MS / 10 && running; i++) {
                usleep(10000);
            }
            if (gpiod_line_set_value(relay_line, 0) < 0) {
                perror("relay off");
            }
            int door_open = (gpiod_line_get_value(reed_line) == 0);
            if (door_open) {
                log_event("door opened");
                printf("Door opened.\n");
            } else {
                log_event("door not opened");
                printf("Door not opened.\n");
            }
        }
        usleep(POLL_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

