#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PUMP_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define MCP3008_CHANNEL 0
#define LOG_FILE "irrigation.log"
#define MAX_RETRIES 3
#define DRY_RAW 200
#define WET_RAW 800

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static int pump_active = 0;

static void log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fclose(fp);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) return -1;
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
        if (ret == 3) {
            return ((rx[1] & 0x03) << 8) | rx[2];
        }
        log_event("SPI transfer failed, retrying...");
        gpioDelay(100000);
    }
    log_event("SPI transfer failed after retries.");
    return -1;
}

static int read_moisture_percent(void) {
    int raw = read_mcp3008(MCP3008_CHANNEL);
    if (raw < 0) return -1;
    int pct = 100 - ((int)(((float)(raw - DRY_RAW) / (WET_RAW - DRY_RAW)) * 100));
    if (pct < 0) pct = 0;
    if (pct > 100) pct = 100;
    return pct;
}

static void control_pump(int on) {
    if (gpioWrite(PUMP_GPIO, on ? 1 : 0) < 0) {
        log_event("Failed to write pump GPIO.");
        return;
    }
    pump_active = on;
    char msg[64];
    snprintf(msg, sizeof(msg), "Pump %s", on ? "activated" : "deactivated");
    log_event(msg);
}

static void cleanup(void) {
    control_pump(0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int threshold = 30;
    int duration = 10;
    int sleep_interval = 60;
    int opt;
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't': threshold = atoi(optarg); break;
            case 'd': duration = atoi(optarg); break;
            case 's': sleep_interval = atoi(optarg); break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration] [-s sleep_interval]\n", argv[0]);
                return 1;
        }
    }
    if (threshold < 0 || threshold > 100 || duration <= 0 || sleep_interval <= 0) {
        fprintf(stderr, "Invalid configuration values.\n");
        return 1;
    }
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return 1;
    }
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set pump GPIO mode.\n");
        gpioTerminate();
        return 1;
    }
    control_pump(0);
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed.\n");
        control_pump(0);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    log_event("Irrigation system started.");
    while (running) {
        int pct = read_moisture_percent();
        if (pct < 0) {
            log_event("Sensor read failed, skipping cycle.");
        } else {
            char msg[128];
            snprintf(msg, sizeof(msg), "Moisture: %d%%", pct);
            log_event(msg);
            if (pct < threshold && !pump_active) {
                log_event("Moisture below threshold, activating pump.");
                control_pump(1);
                gpioDelay(duration * 1000000);
                control_pump(0);
            }
        }
        for (int i = 0; i < sleep_interval && running; i++) {
            gpioDelay(1000000);
        }
    }
    log_event("Shutting down...");
    cleanup();
    return 0;
}

