    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double calculate_ema(double current, double previous) {
    return (EMA_ALPHA * current) + ((1.0 - EMA_ALPHA) * previous);
}

static void log_event(int value) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    if (fprintf(log_file, "%s - Peak detected: %d\n", timestamp, value) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
    } else {
        fflush(log_file);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    double ema = 0.0;
    int consecutive_errors = 0;

    while (running) {
        int raw = read_mcp3008(ADC_CHANNEL);
        if (raw < 0) {
            consecutive_errors++;
            if (consecutive_errors > 10) {
                fprintf(stderr, "Too many SPI errors, aborting\n");
                break;
            }
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }
        consecutive_errors = 0;

        double current_ema = calculate_ema((double)raw, ema);
        ema = current_ema;

        if (raw > (ema * (1.0 + PEAK_THRESHOLD / 100.0))) {
            log_event(raw);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (log_file) {
        fclose(log_file);
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

