#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define ADS1115_REG_CONV 0x00
#define ADS1115_REG_CFG  0x01

/* Config: single-shot, AIN0 single-ended, +/-4.096 V, 128 SPS, continuous */
#define ADS1115_CFG_BASE 0x8483

#define GPIO_SHUTDOWN  27
#define BUFFER_SIZE    10
#define SAMPLE_HZ      1
#define SAMPLE_US      (1000000 / SAMPLE_HZ)
#define VCC            3.3f
#define ZERO_GAUSS_V   2.5f
#define SENSITIVITY    0.0014f  /* 1.4 mV/Gauss */
#define THRESHOLD_GAUSS 500.0f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void cb_init(CircularBuffer *cb) {
    cb->head  = 0;
    cb->count = 0;
}

static void cb_push(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static float cb_average(const CircularBuffer *cb) {
    if (cb->count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++) sum += cb->buffer[i];
    return sum / (float)cb->count;
}

/*
 * Read one sample from the ADS1115.
 * Returns 0 on success and stores raw 16-bit signed value in *raw_out.
 * Returns -1 on I2C error.
 */
static int ads1115_read_raw(int handle, int16_t *raw_out) {
    char cfg[3];
    cfg[0] = ADS1115_REG_CFG;
    cfg[1] = (ADS1115_CFG_BASE >> 8) & 0xFF;
    cfg[2] = ADS1115_CFG_BASE & 0xFF;

    if (i2cWriteDevice(handle, cfg, 3) < 0) return -1;
    gpioDelay(10000); /* 10 ms conversion wait */

    char reg = ADS1115_REG_CONV;
    if (i2cWriteDevice(handle, &reg, 1) < 0) return -1;

    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) return -1;

    *raw_out = (int16_t)(((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1]);
    return 0;
}

static float voltage_to_gauss(float voltage) {
    return (voltage - ZERO_GAUSS_V) / SENSITIVITY;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(GPIO_SHUTDOWN, 0);
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog("hall_sensor_monitor", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_SHUTDOWN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as output", GPIO_SHUTDOWN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_SHUTDOWN, 0);

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus %d addr 0x%02X: %d", I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    CircularBuffer gauss_buffer;
    cb_init(&gauss_buffer);

    syslog(LOG_INFO, "Hall sensor monitoring started (ADS1115 @ 0x%02X, GPIO%d)", I2C_ADDR, GPIO_SHUTDOWN);

    while (g_running) {
        int16_t raw;
        if (ads1115_read_raw(g_i2c_handle, &raw) < 0) {
            syslog(LOG_ERR, "I2C/ADC read error");
            gpioDelay(SAMPLE_US);
            continue;
        }

        /* ADS1115 +/-4.096 V range: 1 bit = 125 uV */
        float voltage = (raw * 0.000125f) * (VCC * 1000.0f);
        if (voltage < 0.0f || voltage > VCC * 1000.0f) {
            syslog(LOG_ERR, "Voltage out of range: %.3f mV", voltage);
            gpioDelay(SAMPLE_US);
            continue;
        }

        float gauss = voltage_to_gauss(voltage / 1000.0f);
        cb_push(&gauss_buffer, gauss);

        float avg = cb_average(&gauss_buffer);
        syslog(LOG_INFO, "Gauss: %.2f | Avg: %.2f | Buffer: %d/%d",
               gauss, avg, gauss_buffer.count, BUFFER_SIZE);

        if (avg > THRESHOLD_GAUSS) {
            syslog(LOG_WARNING, "Threshold exceeded (%.2f > %.2f). Shutting down motor.", avg, THRESHOLD_GAUSS);
            gpioWrite(GPIO_SHUTDOWN, 1);
        }

        gpioDelay(SAMPLE_US);
    }

    syslog(LOG_INFO, "Shutting down gracefully.");
    cleanup();
    return EXIT_SUCCESS;
}

