#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define LED_GPIO       17
#define ADS1115_REG_CONV 0x00
#define ADS1115_REG_CFG  0x01
#define ADS1115_CFG_OS   0x8000
#define ADS1115_CFG_MUX0 0x4000
#define ADS1115_CFG_PGA  0x0200
#define ADS1115_CFG_MODE 0x0100
#define ADS1115_CFG_DR   0x0080
#define ADS1115_PGA_4_096 4.096f
#define ADS1115_MAX 32767.0f
#define DEFAULT_THRESHOLD 100.0f
#define SAMPLE_INTERVAL_US 100000
#define BLINK_DURATION_US 1000000
#define BLINK_HALF_US 50000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_ads1115(int handle, float *voltage_out) {
    char cfg[3];
    char reg;
    char data[2];
    int16_t raw;
    float voltage;

    cfg[0] = ADS1115_REG_CFG;
    cfg[1] = (char)(ADS1115_CFG_OS | ADS1115_CFG_MUX0 | ADS1115_CFG_PGA |
                    ADS1115_CFG_MODE | ADS1115_CFG_DR);
    cfg[2] = 0x00;
    if (i2cWriteDevice(handle, cfg, 3) < 0) {
        fprintf(stderr, "I2C write config failed: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(10000);

    reg = ADS1115_REG_CONV;
    if (i2cWriteDevice(handle, &reg, 1) < 0) {
        fprintf(stderr, "I2C write pointer failed: %s\n", strerror(errno));
        return -1;
    }
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "I2C read conversion failed: %s\n", strerror(errno));
        return -1;
    }
    raw = (int16_t)((data[0] << 8) | data[1]);
    voltage = (raw / ADS1115_MAX) * ADS1115_PGA_4_096;
    *voltage_out = voltage;
    return 0;
}

static float voltage_to_gauss(float voltage) {
    return (voltage - 1.65f) / 0.001f;
}

static void blink_led(int gpio, int duration_us) {
    int half = duration_us / 2;
    while (running && half > 0) {
        gpioWrite(gpio, 1);
        gpioDelay(half);
        gpioWrite(gpio, 0);
        gpioDelay(half);
    }
}

int main(int argc, char *argv[]) {
    float threshold = DEFAULT_THRESHOLD;
    int opt;

    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold_gauss]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d addr 0x%02X: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

