#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define RELAY_GPIO 17
#define MOISTURE_THRESHOLD 30.0
#define MOISTURE_HYSTERESIS 35.0
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "soil_moisture"
#define MQTT_CLIENT_ID "rpi_soil_moisture"
#define SAMPLE_INTERVAL 60

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static MQTTClient mqtt_client;
static MQTTClient_connectOptions mqtt_opts;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel: %d", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        syslog(LOG_ERR, "SPI transfer failed");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static float adc_to_moisture(int adc_value) {
    if (adc_value < 0) return -1.0f;
    return 100.0f - ((float)adc_value / 1023.0f) * 100.0f;
}

static int control_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) != 0) {
        syslog(LOG_ERR, "Failed to write relay GPIO %d", RELAY_GPIO);
        return -1;
    }
    syslog(LOG_INFO, "Relay set to %s", state ? "ON" : "OFF");
    return 0;
}

static void mqtt_connect_callback(MQTTClient client, void *userdata, int reason) {
    (void)client; (void)userdata;
    if (reason == MQTTCLIENT_CONNECT_SUCCESS) {
        syslog(LOG_INFO, "MQTT connected");
        MQTTClient_subscribe(mqtt_client, "pump_control", 0);
    } else {
        syslog(LOG_ERR, "MQTT connect failed: %s", MQTTClient_strerror(reason));
    }
}

static void mqtt_message_callback(MQTTClient client, char *topic, int topicLen, MQTTClient_message *message) {
    (void)client; (void)topic; (void)topicLen;
    if (message->payloadlen <= 0) {
        syslog(LOG_WARNING, "Empty MQTT message");
        MQTTClient_freeMessage(&message);
        MQTTClient_free(topic);
        return;
    }
    char payload[32];
    int plen = message->payloadlen < (int)sizeof(payload) - 1 ? message->payloadlen : (int)sizeof(payload) - 1;
    memcpy(payload, message->payload, plen);
    payload[plen] = '\0';
    syslog(LOG_INFO, "Received MQTT command: %s", payload);

    if (strcmp(payload, "pump_on") == 0) {
        if (control_relay(1) == 0) {
            MQTTClient_publishMessage(mqtt_client, MQTT_TOPIC, (char *)"ON", 2);
        }
    } else if (strcmp(payload, "pump_off") == 0) {
        if (control_relay(0) == 0) {
            MQTTClient_publishMessage(mqtt_client, MQTT_TOPIC, (char *)"OFF", 3);
        }
    } else {
        syslog(LOG_WARNING, "Unknown MQTT command: %s", payload);
    }
    MQTTClient_freeMessage(&message);
    MQTTClient_free(topic);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    control_relay(0);
    if (mqtt_client) {
        MQTTClient_disconnect(mqtt_client, 1000);
        MQTTClient_destroy(&mqtt_client);
    }
    MQTTClient_destroy(&mqtt_opts);
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog("soil_moisture_monitor", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set relay GPIO %d as output", RELAY_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    control_relay(0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI open failed: %s", pigpio_error(spi_handle));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    MQTTClient_create(&mqtt_client, MQTT_BROKER, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    mqtt_opts.keepAliveInterval = 60;
    mqtt_opts.cleansession = 1;
    MQTTClient_setCallbacks(mqtt_client, NULL, mqtt_connect_callback, mqtt_message_callback, NULL);

    int rc = MQTTClient_connect(mqtt_client, &mqtt_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect failed: %s", MQTTClient_strerror(rc));
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    syslog(LOG_INFO, "Soil moisture monitoring started");

    int pump_on = 0;
    while (running) {
        int adc = read_mcp3008(MCP3008_CHANNEL);
        if (adc < 0) {
            syslog(LOG_ERR, "Failed to read ADC");
            sleep(5);
            continue;
        }

        float moisture = adc_to_moisture(adc);
        if (moisture < 0.0f) {
            syslog(LOG_ERR, "Sensor absent or out of range (ADC=%d)", adc);
            sleep(5);
            continue;
        }

        syslog(LOG_INFO, "Moisture: %.2f%%", moisture);

        if (moisture < MOISTURE_THRESHOLD && !pump_on) {
            if (control_relay(1) == 0) {
                pump_on = 1;
                syslog(LOG_INFO, "Moisture below threshold, pump ON");
            }
        } else if (moisture > MOISTURE_HYSTERESIS && pump_on) {
            if (control_relay(0) == 0) {
                pump_on = 0;
                syslog(LOG_INFO, "Moisture above hysteresis, pump OFF");
            }
        }

        MQTTClient_publishMessage(mqtt_client, MQTT_TOPIC, (char *)"", 0);
        sleep(SAMPLE_INTERVAL);
    }

    syslog(LOG_INFO, "Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

