    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGTERM handler: %s\n", strerror(errno));
    }

    printf("Starting data logging. Press Ctrl+C to stop.\n");

    while (running) {
        int adc[NUM_CHANNELS];
        double voltage[NUM_CHANNELS];

        for (int i = 0; i < NUM_CHANNELS; i++) {
            adc[i] = read_mcp3008(i);
            if (adc[i] < 0) {
                fprintf(stderr, "Error: Failed to read channel %d\n", i);
                continue;
            }
            voltage[i] = adc_to_voltage(adc[i]);
        }

        if (log_data(voltage[0], voltage[1], voltage[2]) != 0) {
            fprintf(stderr, "Error: Failed to log data\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL && running; i++) {
            gpioSleep(PI_TIME_RELATIVE, 1, 0);
        }
    }

    printf("\nShutting down...\n");

    if (spi_handle >= 0) {
        if (spiClose(spi_handle) != 0) {
            fprintf(stderr, "Warning: spiClose failed\n");
        }
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

