    }
    if (gpioSetPWMrange(MOTOR2_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", MOTOR2_PIN);
        cleanup();
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        cleanup();
        return 1;
    }

    unsigned char mode = SPI_MODE_0;
    unsigned char bits = 8;
    unsigned int speed = SPI_SPEED;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        cleanup();
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        cleanup();
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        cleanup();
        return 1;
    }

    printf("Vibration motor control started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(spi_fd, 0);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed, skipping iteration\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (adc_value > NOISE_THRESHOLD) {
            int duty_cycle = (int)(((float)adc_value / 1023.0f) * PWM_RANGE);
            set_motor_pwm(MOTOR1_PIN, duty_cycle);
            set_motor_pwm(MOTOR2_PIN, duty_cycle);
            char log_msg[128];
            snprintf(log_msg, sizeof(log_msg), "Noise detected: ADC=%d, Duty=%d", adc_value, duty_cycle);
            log_event(log_msg);
        } else {
            set_motor_pwm(MOTOR1_PIN, 0);
            set_motor_pwm(MOTOR2_PIN, 0);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

