#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define VALVE_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define NUM_SENSORS 3
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define LOG_FILE "irrigation.log"
#define SAMPLE_INTERVAL 5

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0, 0, 0};
    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d (ret=%d)\n", channel, ret);
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float calculate_average(int *values, int n) {
    if (n <= 0) return 0.0f;
    float sum = 0.0f;
    int count = 0;
    for (int i = 0; i < n; i++) {
        int v = values[i];
        if (v >= 0) {
            sum += v;
            count++;
        }
    }
    return (count > 0) ? (sum / count) : 0.0f;
}

static int map_value(int input, int input_min, int input_max, int output_min, int output_max) {
    if (input_min == input_max) return output_min;
    if (output_min == output_max) return output_min;
    return (input - input_min) * (output_max - output_min) / (input_max - input_min) + output_min;
}

static void log_data(FILE *fp, int *values, float avg, int pos) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, ADC: %d, %d, %d, Avg: %.2f, Valve: %d%%\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            values[0], values[1], values[2], avg, pos);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(VALVE_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", VALVE_GPIO);
        gpioTerminate();
        return 1;
    }
    gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(VALVE_GPIO, PWM_RANGE);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int sensor_values[NUM_SENSORS];
    float avg;
    int valve_position;

    while (!terminate) {
        avg = 0.0f;
        int valid_count = 0;
        for (int i = 0; i < NUM_SENSORS; i++) {
            sensor_values[i] = read_mcp3008(i);
            if (sensor_values[i] >= 0) {
                avg += sensor_values[i];
                valid_count++;
            } else {
                fprintf(stderr, "Error reading sensor %d\n", i);
            }
        }
        avg /= valid_count;

        valve_position = map_value((int)avg, 0, 1023, 0, 100);
        gpioPWM(VALVE_GPIO, valve_position);

        log_data(log_file, sensor_values, avg, valve_position);

        for (int i = 0; i < SAMPLE_INTERVAL && !terminate; i++) {
            sleep(1);
        }
    }

    gpioPWM(VALVE_GPIO, 0);
    spiClose(spi_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

