#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18

#define MIN_FREQ 220
#define MAX_FREQ 880
#define PWM_PERIOD_NS 1000000
#define PWM_DUTY_MAX 1000000000

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_BITS 8

#define CONFIG_FILE "theremin_config.txt"

volatile sig_atomic_t running = 1;
static float last_valid_freq = 440.0;
static float last_valid_volume = 0.5;
static float last_valid_distance = 100.0;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_config(const char *filename, float *freq_min, float *freq_max, float *vol_min, float *vol_max) {
    FILE *fp = fopen(filename, "r");
    if (!fp) return -1;
    if (fscanf(fp, "%f %f %f %f", freq_min, freq_max, vol_min, vol_max) != 4) {
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

int write_config(const char *filename, float freq_min, float freq_max, float vol_min, float vol_max) {
    FILE *fp = fopen(filename, "w");
    if (!fp) return -1;
    fprintf(fp, "%f %f %f %f", freq_min, freq_max, vol_min, vol_max);
    fclose(fp);
    return 0;
}

int read_mcp3008(int spi_fd, int channel) {
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) return -1;
    return ((rx[1] & 0x03) << 8) | rx[2];
}

float read_ldr_value(int spi_fd) {
    int val = read_mcp3008(spi_fd, 0);
    if (val < 0) return -1.0;
    return (float)val / 1023.0;
}

float read_distance(int spi_fd) {
    struct gpiod_line *trig = gpiod_line_get(spi, TRIG_PIN);
    struct gpiod_line *echo = gpiod_line_get(spi, ECHO_PIN);
    if (!trig || !echo) return -1.0;
    if (gpiod_line_request_output(trig, "theremin", 0) < 0) return -1.0;
    if (gpiod_line_request_input(echo, "theremin") < 0) return -1.0;
    gpiod_line_set_value(trig, 1);
    usleep(10);
    gpiod_line_set_value(trig, 0);
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);
    int timeout = 0;
    while (gpiod_line_get_value(echo) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        if (end.tv_sec - start.tv_sec > 0.1) return -1.0;
        timeout++;
        if (timeout > 1000) return -1.0;
        usleep(1);
    }
    clock_gettime(CLOCK_MONOTONIC, &start);
    timeout = 0;
    while (gpiod_line_get_value(echo) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        if (end.tv_sec - start.tv_sec > 0.1) return -1.0;
        timeout++;
        if (timeout > 1000) return -1.0;
        usleep(1);
    }
    clock_gettime(CLOCK_MONOTONIC, &end);
    float time = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1000000000.0;
    if (time <= 0) return -1.0;
    return (time * 34300.0) / 2.0;
}

float map_distance_to_freq(float distance) {
    if (distance < 2.0) return MAX_FREQ;
    if (distance > 400.0) return MIN_FREQ;
    return MIN_FREQ + (MAX_FREQ - MIN_FREQ) * (1.0 - distance / 400.0);
}

float map_ldr_to_volume(float ldr) {
    if (ldr < 0.1) return 0.0;
    if (ldr > 1.0) return 1.0;
    return 1.0 - ldr;
}

int set_pwm_freq(int spi_fd, float freq) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/export");
    int pwm_num = 0;
    FILE *fp = fopen(path, "r");
    if (fp) {
        fscanf(fp, "%d", &pwm_num);
        fclose(fp);
    }
    if (pwm_num < 0) pwm_num = 0;
    if (pwm_num >= 8) return -1;
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm%d/period", pwm_num);
    int period = (int)(1000000000.0 / freq);
    if (period < 1000) period = 1000;
    if (period > PWM_PERIOD_NS) period = PWM_PERIOD_NS;
    FILE *fp2 = fopen(path, "w");
    if (!fp2) return -1;
    fprintf(fp2, "%d", period);
    fclose(fp2);
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm%d/duty_cycle", pwm_num);
    FILE *fp3 = fopen(path, "w");
    if (!fp3) return -1;
    fprintf(fp3, "0");
    fclose(fp3);
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm%d/enable", pwm_num);
    FILE *fp4 = fopen(path, "w");
    if (!fp4) return -1;
    fprintf(fp4, "1");
    fclose(fp4);
    return pwm_num;
}

int set_pwm_duty(int spi_fd, int pwm_num, float duty) {
    if (duty < 0.0) duty = 0.0;
    if (duty > 1.0) duty = 1.0;
    int duty_ns = (int)(PWM_PERIOD_NS * duty);
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm%d/duty_cycle", pwm_num);
    FILE *fp = fopen(path, "w");
    if (!fp) return -1;
    fprintf(fp, "%d", duty_ns);
    fclose(fp);
    return 0;
}

int main() {
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }
    struct gpiod_line *trig = gpiod_line_get(chip, TRIG_PIN);
    struct gpiod_line *echo = gpiod_line_get(chip, ECHO_PIN);
    struct gpiod_line *ldr = gpiod_line_get(chip, PWM_PIN);
    if (!trig || !echo || !ldr) {
        perror("gpiod_line_get");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(trig, "theremin", 0) < 0 ||
        gpiod_line_request_input(echo, "theremin") < 0 ||
        gpiod_line_request_input(ldr, "theremin") < 0) {
        perror("gpiod_line_request");
        gpiod_chip_close(chip);
        return 1;
    }
    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open spi");
        gpiod_chip_close(chip);
        return 1;
    }
    unsigned char mode = SPI_MODE_0;
    unsigned char bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &(int){SPI_SPEED}) < 0) {
        perror("spi config");
        close(spi_fd);
        gpiod_chip_close(chip);
        return 1;
    }
    signal(SIGINT, signal_handler);
    float freq_min = MIN_FREQ, freq_max = MAX_FREQ, vol_min = 0.0, vol_max = 1.0;
    if (read_config(CONFIG_FILE, &freq_min, &freq_max, &vol_min, &vol_max) != 0) {
        write_config(CONFIG_FILE, MIN_FREQ, MAX_FREQ, 0.0, 1.0);
    }
    while (running) {
        float distance = read_distance(spi_fd);
        if (distance < 0) {
            fprintf(stderr, "Distance read error\n");
            usleep(100000);
            continue;
        }
        float freq = map_distance_to_freq(distance);
        if (freq < freq_min) freq = freq_min;
        if (freq > freq_max) freq = freq_max;
        int pwm_num = set_pwm_freq(spi_fd, freq);
        if (pwm_num < 0) {
            fprintf(stderr, "PWM export failed\n");
            usleep(100000);
            continue;
        }
        float ldr = read_ldr_value(spi_fd);
        if (ldr < 0) {
            fprintf(stderr, "LDR read error\n");
            ldr = last_valid_volume;
        }
        float volume = map_ldr_to_volume(ldr);
        if (volume < vol_min) volume = vol_min;
        if (volume > vol_max) volume = vol_max;
        set_pwm_duty(spi_fd, pwm_num, volume);
        last_valid_freq = freq;
        last_valid_volume = volume;
        last_valid_distance = distance;
        usleep(10000);
    }
    set_pwm_duty(spi_fd, pwm_num, 0.0);
    close(spi_fd);
    gpiod_chip_close(chip);
    return 0;
}

