#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <math.h>

// Motor 1 Pins
#define MOTOR1_ENABLE 18
#define MOTOR1_DIRECTION 23

// Motor 2 Pins
#define MOTOR2_ENABLE 24
#define MOTOR2_DIRECTION 25

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// MCP3008 ADC Channels
#define POT1_CHANNEL 0
#define POT2_CHANNEL 1

// PWM Range
#define PWM_RANGE 255

// Global variables for cleanup
int spi_handle = -1;
volatile sig_atomic_t running = 1;

// Function prototypes
int read_adc(int channel);
int map_pot_to_speed(int pot_value);
void set_motor_speed(int motor, int speed);
void set_motor_direction(int motor, int direction);
void move_forward(int motor1_speed, int motor2_speed);
void move_backward(int motor1_speed, int motor2_speed);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

// Function to read from MCP3008 ADC
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message for MCP3008
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to map potentiometer value to speed (0-255)
int map_pot_to_speed(int pot_value) {
    // Logarithmic mapping for finer control at lower speeds
    double speed = log10((double)pot_value + 1) * 100.0; // Scale factor
    if (speed < 0) speed = 0;
    if (speed > 255) speed = 255;
    return (int)speed;
}

// Function to set motor speed using PWM
void set_motor_speed(int motor, int speed) {
    if (speed < 0) speed = 0;
    if (speed > PWM_RANGE) speed = PWM_RANGE;
    gpioPWM(motor, speed);
}

// Function to set motor direction
void set_motor_direction(int motor, int direction) {
    gpioWrite(motor, direction);
}

// Function to move motor forward
void move_forward(int motor1_speed, int motor2_speed) {
    set_motor_direction(MOTOR1_DIRECTION, 1);
    set_motor_direction(MOTOR2_DIRECTION, 0);
    set_motor_speed(MOTOR1_ENABLE, motor1_speed);
    set_motor_speed(MOTOR2_ENABLE, motor2_speed);
}

// Function to move motor backward
void move_backward(int motor1_speed, int motor2_speed) {
    set_motor_direction(MOTOR1_DIRECTION, 0);
    set_motor_direction(MOTOR2_DIRECTION, 1);
    set_motor_speed(MOTOR1_ENABLE, motor1_speed);
    set_motor_speed(MOTOR2_ENABLE, motor2_speed);
}

// Cleanup function
void cleanup() {
    // Stop motors
    set_motor_speed(MOTOR1_ENABLE, 0);
    set_motor_speed(MOTOR2_ENABLE, 0);

    // Close SPI
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIRECTION, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIRECTION, PI_OUTPUT);

    // Set PWM range
    gpioSetPWMrange(MOTOR1_ENABLE, PWM_RANGE);
    gpioSetPWMrange(MOTOR2_ENABLE, PWM_RANGE);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read potentiometer values
        int pot1_value = read_adc(POT1_CHANNEL);
        int pot2_value = read_adc(POT2_CHANNEL);

        if (pot1_value < 0 || pot2_value < 0) {
            fprintf(stderr, "Error: Failed to read potentiometer values\n");
            break;
        }

        // Map potentiometer values to speed
        int motor1_speed = map_pot_to_speed(pot1_value);
        int motor2_speed = map_pot_to_speed(pot2_value);

        // Move forward
        move_forward(motor1_speed, motor2_speed);
        printf("Moving forward: Motor 1 speed = %d, Motor 2 speed = %d\n", motor1_speed, motor2_speed);

        // Hold for 2 seconds
        sleep(2);

        // Stop
        set_motor_speed(MOTOR1_ENABLE, 0);
        set_motor_speed(MOTOR2_ENABLE, 0);
        printf("Stopped\n");

        // Pause for 5 seconds
        sleep(5);

        // Move backward
        move_backward(motor1_speed, motor2_speed);
        printf("Moving backward: Motor 1 speed = %d, Motor 2 speed = %d\n", motor1_speed, motor2_speed);

        // Hold for 2 seconds
        sleep(2);

        // Stop
        set_motor_speed(MOTOR1_ENABLE, 0);
        set_motor_speed(MOTOR2_ENABLE, 0);
        printf("Stopped\n");

        // Pause for 5 seconds
        sleep(5);
    }

    // Cleanup
    cleanup();
    return 0;
}

