#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define LED_PIN 17
#define DEBOUNCE_DELAY_US 10000
#define SAMPLE_INTERVAL_US 10000
#define CALIBRATION_DURATION_S 5
#define NOISE_THRESHOLD_PERCENT 10

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (ret=%d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Calibrating for %d seconds...\n", CALIBRATION_DURATION_S);
    double ambient_sum = 0.0;
    int sample_count = 0;
    uint32_t start_tick = gpioTick();

    while (running && (gpioTick() - start_tick) < (uint32_t)(CALIBRATION_DURATION_S * 1000000)) {
        int sample = read_mcp3008(0);
        if (sample < 0) {
            fprintf(stderr, "Error reading ADC during calibration\n");
            cleanup();
            return EXIT_FAILURE;
        }
        ambient_sum += sample;
        sample_count++;
        gpioDelay(1000);
    }

    if (!running) {
        cleanup();
        return EXIT_SUCCESS;
    }

    if (sample_count == 0) {
        fprintf(stderr, "Calibration failed: no samples taken\n");
        cleanup();
        return EXIT_FAILURE;
    }

    double ambient_avg = ambient_sum / sample_count;
    double threshold = ambient_avg * (NOISE_THRESHOLD_PERCENT / 100.0);

    printf("Calibration complete. Ambient avg: %.2f, threshold: %.2f\n", ambient_avg, threshold);

    uint32_t last_led_tick = 0;

    while (running) {
        int sample = read_mcp3008(0);
        if (sample < 0) {
            fprintf(stderr, "Error reading ADC\n");
            break;
        }

        if (sample > threshold) {
            uint32_t now = gpioTick();
            if (now - last_led_tick >= DEBOUNCE_DELAY_US) {
                gpioWrite(LED_PIN, 1);
                last_led_tick = now;
            }
        } else {
            gpioWrite(LED_PIN, 0);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

