#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define VREF 3.3
#define ADC_MAX 1023.0
#define PPM_SCALE 1000.0
#define LOG_FILE "gas_log.txt"
#define RETRY_DELAY_MS 100

static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0, 0, 0};
    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double voltage_to_ppm(double voltage) {
    return voltage * PPM_SCALE;
}

static void log_data(double voltage, double ppm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Voltage: %.3f V, PPM: %.3f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, voltage, ppm);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }
    signal(SIGINT, signal_handler);
    printf("Propane leak detector started. Press Ctrl+C to exit.\n");
    while (!terminate) {
        int adc = read_mcp3008(0);
        if (adc < 0) {
            gpioDelay(RETRY_DELAY_MS * 1000);
            continue;
        }
        double voltage = (adc / ADC_MAX) * VREF;
        double ppm = voltage_to_ppm(voltage);
        log_data(voltage, ppm);
        printf("Voltage: %.3f V, PPM: %.3f\n", voltage, ppm);
        gpioDelay(1000000);
    }
    spiClose(spi_handle);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

