#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define REFERENCE_VOLTAGE 3.3
#define ADXL335_SENSITIVITY 0.3 // 300 mV/g
#define ADXL335_ZERO_G_BIAS 1.5 // 1.5V
#define SAMPLE_RATE_HZ 10
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)

// MCP3008 Channels
#define X_CHANNEL 0
#define Y_CHANNEL 1
#define Z_CHANNEL 2

// Kalman Filter Parameters
#define Q_ANGLE 0.001
#define Q_GYRO 0.003
#define R_MEASUREMENT 0.03
#define DT 0.1 // Sample period in seconds

// Global variables
static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

// Kalman filter state
typedef struct {
    double angle;
    double angle_dot;
    double P00;
    double P01;
    double P10;
    double P11;
} kalman_state_t;

kalman_state_t x_state = {0, 0, 1, 0, 0, 1};
kalman_state_t y_state = {0, 0, 1, 0, 0, 1};
kalman_state_t z_state = {0, 0, 1, 0, 0, 1};

// Function prototypes
int read_mcp3008(int channel);
double convert_to_g(int adc_value);
void kalman_filter(kalman_state_t *state, double measurement);
void signal_handler(int signal);
int initialize();
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Function to read from MCP3008 ADC via SPI
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format for single-ended mode:
    // Byte 0: 0x01 (Start bit)
    // Byte 1: (0x08 | channel) << 4 (Single-ended mode + channel selection)
    // Byte 2: 0x00 (Don't care)
    char tx_buffer[3] = {0x01, (char)((0x08 | channel) << 4), 0x00};
    char rx_buffer[3] = {0};

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    // Extract 10-bit ADC value
    // rx_buffer[1] contains the two most significant bits in its lower 2 bits
    // rx_buffer[2] contains the 8 least significant bits
    int adc_value = ((rx_buffer[1] & 0x03) << 8) | (rx_buffer[2] & 0xFF);
    return adc_value;
}

// Function to convert ADC value to acceleration in g
double convert_to_g(int adc_value) {
    double voltage = (adc_value / 1023.0) * REFERENCE_VOLTAGE;
    double acceleration = (voltage - ADXL335_ZERO_G_BIAS) / ADXL335_SENSITIVITY;
    return acceleration;
}

// Kalman filter function
void kalman_filter(kalman_state_t *state, double measurement) {
    double y = measurement - state->angle;
    double S = state->P00 + state->P11 + R_MEASUREMENT;
    if (S <= 0) S = 0.001; // Avoid division by zero

    double K0 = state->P00 / S;
    double K1 = state->P10 / S;

    state->angle = state->angle + (K0 * y);
    state->angle_dot = state->angle_dot + (K1 * y);

    double P00_new = (1 - K0) * state->P00;
    double P01_new = (1 - K0) * state->P01 - K1 * state->P00;
    double P10_new = (1 - K1) * state->P10;
    double P11_new = (1 - K1) * state->P11 - K1 * state->P10;

    state->P00 = P00_new + Q_ANGLE;
    state->P01 = P01_new + Q_ANGLE;
    state->P10 = P10_new + Q_ANGLE;
    state->P11 = P11_new + Q_GYRO;
}

int main() {
    // Initialize pigpio
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    // Set up signal handling for Ctrl+C and termination
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting ADXL335 data acquisition (Kalman filter)...\n");

    // Main loop
    while (!terminate) {
        // Read ADC values from MCP3008
        int x_adc = read_mcp3008(X_CHANNEL);
        int y_adc = read_mcp3008(Y_CHANNEL);
        int z_adc = read_mcp3008(Z_CHANNEL);

        if (x_adc < 0 || y_adc < 0 || z_adc < 0) {
            fprintf(stderr, "Error reading ADC values. Retrying...\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        // Convert ADC values to acceleration in g
        double x_accel = convert_to_g(x_adc);
        double y_accel = convert_to_g(y_adc);
        double z_accel = convert_to_g(z_adc);

        // Apply Kalman filter
        kalman_filter(&x_state, x_accel);
