#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define SENSOR3_GPIO 27
#define VCC 3.3
#define QUIESCENT_VOLTAGE (VCC / 2.0)
#define SENSITIVITY 0.025
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL_US 100000
#define MAX_MILLITESLA 100.0
#define MIN_MILLITESLA -100.0

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static double calculate_magnetic_field(int gpio_value) {
    double voltage = (double)gpio_value * VCC;
    double magnetic_field = (voltage - QUIESCENT_VOLTAGE) / SENSITIVITY;
    return magnetic_field;
}

static int log_data(FILE *fp, double sensor1_mT, double sensor2_mT, double sensor3_mT) {
    if (fprintf(fp, "%.4f,%.4f,%.4f\n", sensor1_mT, sensor2_mT, sensor3_mT) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL, *line3 = NULL;
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, SENSOR1_GPIO);
    line2 = gpiod_chip_get_line(chip, SENSOR2_GPIO);
    line3 = gpiod_chip_get_line(chip, SENSOR3_GPIO);
    if (!line1 || !line2 || !line3) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(line1, "drv5055va_sensor1") < 0) {
        fprintf(stderr, "Failed to request GPIO %d as input: %s\n", SENSOR1_GPIO, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(line2, "drv5055va_sensor2") < 0) {
        fprintf(stderr, "Failed to request GPIO %d as input: %s\n", SENSOR2_GPIO, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(line3, "drv5055va_sensor3") < 0) {
        fprintf(stderr, "Failed to request GPIO %d as input: %s\n", SENSOR3_GPIO, strerror(errno));
        goto cleanup;
    }

    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("Starting magnetic field monitoring. Press Ctrl+C to exit.\n");

    while (program_running) {
        int gpio_val1 = gpiod_line_get_value(line1);
        int gpio_val2 = gpiod_line_get_value(line2);
        int gpio_val3 = gpiod_line_get_value(line3);

        if (gpio_val1 < 0 || gpio_val2 < 0 || gpio_val3 < 0) {
            fprintf(stderr, "Error reading GPIO values: %s\n", strerror(errno));
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        double sensor1_mT = calculate_magnetic_field(gpio_val1);
        double sensor2_mT = calculate_magnetic_field(gpio_val2);
        double sensor3_mT = calculate_magnetic_field(gpio_val3);

        if (sensor1_mT < MIN_MILLITESLA || sensor1_mT > MAX_MILLITESLA ||
            sensor2_mT < MIN_MILLITESLA || sensor2_mT > MAX_MILLITESLA ||
            sensor3_mT < MIN_MILLITESLA || sensor3_mT > MAX_MILLITESLA) {
            fprintf(stderr, "Warning: Magnetic field reading out of range: S1=%.4f mT, S2=%.4f mT, S3=%.4f mT\n",
                    sensor1_mT, sensor2_mT, sensor3_mT);
        }

        if (log_data(fp, sensor1_mT, sensor2_mT, sensor3_mT) < 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nExiting gracefully.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fp) fclose(fp);
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (line3) gpiod_line_release(line3);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

