#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_MODE 0
#define LOG_FILE "watering.log"
#define ADC_CHANNEL 0
#define MAX_ADC_VALUE 1023
#define MIN_ADC_VALUE 0

// Global variables
static volatile int running = 1;
static int spi_handle = -1;

// Function prototypes
int read_soil_moisture(int channel);
void control_pump(int state);
void log_event(const char *message);
void signal_handler(int signal);

// Function to read soil moisture from MCP3008 ADC
int read_soil_moisture(int channel) {
    if (channel < 0 || channel > 7) {
        log_event("Error: Invalid ADC channel");
        return -1;
    }

    // MCP3008 SPI command: start bit (1), single-ended mode (1), channel select (3 bits), then don't care
    unsigned char tx_buf[3] = {1, (8 + channel) << 4, 0};
    unsigned char rx_buf[3] = {0, 0, 0};

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 0) {
        log_event("Error: SPI transfer failed");
        return -1;
    }

    // Extract 10-bit ADC value from response
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

// Function to control the water pump relay
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
    log_event(state ? "Pump turned ON" : "Pump turned OFF");
}

// Function to log events to a file
void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "[%s] %s\n", timestamp, message);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_event("Received signal, shutting down...");
    control_pump(0); // Ensure pump is off
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is off initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        log_event("Error: SPI open failed");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Watering system started");

    // Main loop
    while (running) {
        int moisture_level = read_soil_moisture(ADC_CHANNEL);
        if (moisture_level < 0) {
            log_event("Error reading moisture level, skipping cycle");
        } else {
            // Convert ADC value to percentage (0-100)
            int percentage = (moisture_level * 100) / MAX_ADC_VALUE;

            char log_message[128];
            snprintf(log_message, sizeof(log_message), "Moisture level: %d%%", percentage);
            log_event(log_message);

            if (percentage < MOISTURE_THRESHOLD) {
                control_pump(1); // Turn pump on
            } else {
                control_pump(0); // Turn pump off
            }
        }

        // Wait 60 seconds
        sleep(60);
    }

    // Cleanup (should not reach here if signal handler works)
    control_pump(0);
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

