            return -1;
        }
        fprintf(log_file, "Timestamp,Channel0,Channel1,Channel2\n");
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, ch0, ch1, ch2);
    fflush(log_file);
    return 0;
}

