        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        int ch0 = read_mcp3008(0);
        int ch1 = read_mcp3008(1);
        int ch2 = read_mcp3008(2);

        if (ch0 < 0 || ch1 < 0 || ch2 < 0) {
            fprintf(stderr, "Error reading ADC channels\n");
            break;
        }

        if (log_data(ch0, ch1, ch2) < 0) {
            break;
        }

        sleep(LOG_INTERVAL_SEC);
    }

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }

    printf("Soil moisture monitoring stopped.\n");
    return 0;
}

