#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <cjson/cJSON.h>

#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define LED_GPIO 17
#define MAX_RECONNECT_DELAY 60
#define JSON_KEY "led_state"

static struct mosquitto *mosq = NULL;
static volatile sig_atomic_t running = 1;

static void log_error(const char *msg) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] ERROR: %s\n", ts, msg);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void led_control(int state) {
    if (gpioWrite(LED_GPIO, state) != 0) {
        log_error("Failed to write to GPIO17");
    }
}

static void on_connect(struct mosquitto *m, void *userdata, int result) {
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        printf("Connected to MQTT broker\n");
        int rc = mosquitto_subscribe(m, NULL, MQTT_TOPIC, 0);
        if (rc != MOSQ_ERR_SUCCESS) {
            log_error("Subscribe failed");
        }
    } else {
        log_error("Connection failed");
    }
}

static void on_disconnect(struct mosquitto *m, void *userdata, int rc) {
    (void)m; (void)userdata;
    if (rc != 0) {
        log_error("Unexpected disconnection");
    }
}

static void on_message(struct mosquitto *m, void *userdata, const struct mosquitto_message *msg) {
    (void)m; (void)userdata;
    if (msg->payloadlen <= 0) {
        log_error("Empty message received");
        return;
    }
    char *payload = malloc(msg->payloadlen + 1);
    if (!payload) {
        log_error("Memory allocation failed");
        return;
    }
    memcpy(payload, msg->payload, msg->payloadlen);
    payload[msg->payloadlen] = '\0';

    cJSON *json = cJSON_Parse(payload);
    if (!json) {
        const char *err = cJSON_GetErrorPtr();
        if (err) {
            fprintf(stderr, "JSON parse error: %s\n", err);
        } else {
            fprintf(stderr, "JSON parse error (unknown)\n");
        }
        free(payload);
        return;
    }
    free(payload);

    cJSON *led_state = cJSON_GetObjectItemCaseSensitive(json, JSON_KEY);
    if (!cJSON_IsTrue(led_state)) {
        log_error("Invalid JSON format");
        cJSON_Delete(json);
        return;
    }

    led_control(led_state->valueint);
    cJSON_Delete(json);
}

static void cleanup(void) {
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
    }
    mosquitto_lib_cleanup();
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    led_control(0);

    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_error("mosquitto_new failed");
        gpioTerminate();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    mosquitto_message_callback_set(mosq, on_message);

    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_error("mosquitto_connect failed");
        mosquitto_destroy(mosq);
        mosq = NULL;
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    rc = mosquitto_loop_start(mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_error("mosquitto_loop_start failed");
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    printf("LED control node started. Press Ctrl+C to exit.\n");

    int reconnect_delay = 1;
    while (running) {
        rc = mosquitto_loop(mosq, reconnect_delay * 1000, 0);
        if (rc != MOSQ_ERR_SUCCESS) {
            log_error("mosquitto_loop error");
            if (reconnect_delay < MAX_RECONNECT_DELAY) {
                reconnect_delay *= 2;
            }
        } else {
            reconnect_delay = 1;
        }
        sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

