#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define BUFFER_SIZE 120
#define LOG_FILE "temp_log.dat"
#define VREF 3.3
#define LM35_SCALE 0.01

static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static float temperature_buffer[BUFFER_SIZE];
static int buffer_index = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = {0x01, (unsigned char)(0x80 | (channel << 4)), 0x00};
    unsigned char rx[3] = {0, 0, 0};
    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float read_temperature(void) {
    int adc_value = read_mcp3008(MCP3008_CHANNEL);
    if (adc_value < 0) return -999.0f;
    float voltage = (adc_value * VREF) / 1023.0f;
    return voltage / LM35_SCALE;
}

static void add_to_buffer(float temp) {
    temperature_buffer[buffer_index] = temp;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static int write_buffer_to_file(void) {
    FILE *fp = fopen(LOG_FILE, "wb+");
    if (!fp) {
        perror("fopen");
        return -1;
    }
    size_t written = fwrite(temperature_buffer, sizeof(float), BUFFER_SIZE, fp);
    if (written != BUFFER_SIZE) {
        fprintf(stderr, "Short write to file: %zu of %d\n", written, BUFFER_SIZE);
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (!terminate) {
        float temp = read_temperature();
        if (temp > -900.0f) {
            printf("Temperature: %.2f °C\n", temp);
            add_to_buffer(temp);
        } else {
            fprintf(stderr, "Failed to read temperature\n");
        }
        sleep(5);
    }

    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

