#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

/* Configuration */
#define SPI_CHANNEL    0
#define SPI_SPEED      500000
#define SPI_FLAGS      0
#define MCP3008_CHANNEL 0
#define I2C_BUS        1
#define I2C_ADDR       0x62
#define DAC_MAX        3.3f
#define TEMP_MIN       0.0f
#define TEMP_MAX       50.0f
#define LOG_FILE       "temperature_log.txt"
#define SAMPLE_US      500000
#define MAX_RETRIES    3

static int spi_handle = -1;
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int ret = spiXfer(spi_handle, tx, rx, 3);
        if (ret == 3) {
            return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
        }
        fprintf(stderr, "Warning: SPI transfer failed (attempt %d/%d), ret=%d\n",
                attempt + 1, MAX_RETRIES, ret);
        gpioDelay(10000);
    }
    return -1;
}

static float adc_to_temperature(int adc_value) {
    return (adc_value * (TEMP_MAX - TEMP_MIN)) / 1023.0f + TEMP_MIN;
}

static int write_mcp4725(int i2c_handle, float voltage) {
    if (voltage < 0.0f) voltage = 0.0f;
    if (voltage > DAC_MAX) voltage = DAC_MAX;

    uint16_t value = (uint16_t)((voltage / DAC_MAX) * 4095.0f);
    char buf[3] = { 0x40, (char)(value >> 8), (char)(value & 0xFF) };

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int ret = i2cWriteDevice(i2c_handle, buf, 3);
        if (ret == 0) return 0;
        fprintf(stderr, "Warning: I2C write failed (attempt %d/%d), ret=%d\n",
                attempt + 1, MAX_RETRIES, ret);
        gpioDelay(10000);
    }
    return -1;
}

static void log_data(int adc_value, float temperature, float dac_voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ADC: %d, Temp: %.2f C, DAC: %.3f V\n",
            timestamp, adc_value, temperature, dac_voltage);
    fflush(log_file);
    printf("%s, ADC: %d, Temp: %.2f C, DAC: %.3f V\n",
           timestamp, adc_value, temperature, dac_voltage);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d)\n", i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Cannot open log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Could not install SIGINT handler\n");
    }

    printf("Temperature control started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value after %d retries\n", MAX_RETRIES);
            gpioDelay(SAMPLE_US);
            continue;
        }

        float temperature = adc_to_temperature(adc_value);
        if (write_mcp4725(i2c_handle, temperature) != 0) {
            fprintf(stderr, "Error: Failed to write DAC value after %d retries\n", MAX_RETRIES);
        }

        log_data(adc_value, temperature, temperature);
        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

