#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

/* BCM GPIO pins for the four Songle SRD-05VDC-SL relays */
#define RELAY1_PIN 17
#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24

#define CONSUMER "relay-seq"
#define NUM_RELAYS 4
#define RELAY_ON_TIME_US 1000000  /* 1 second */
#define RELAY_GAP_TIME_US 1000000 /* 1 second between relays */

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_lines[NUM_RELAYS];
static int relay_pins[NUM_RELAYS] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};

static volatile sig_atomic_t keep_running = 1;

static void cleanup_and_exit(int signum) {
    (void)signum;
    keep_running = 0;
}

static void deactivate_all_relays(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (relay_lines[i]) {
            gpiod_line_set_value(relay_lines[i], 0);
            gpiod_line_release(relay_lines[i]);
            relay_lines[i] = NULL;
        }
    }
}

int main(void) {
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on RPi 3B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Request each relay line as output, initially LOW (inactive) */
    for (int i = 0; i < NUM_RELAYS; i++) {
        relay_lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!relay_lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d\n", relay_pins[i]);
            deactivate_all_relays();
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(relay_lines[i], CONSUMER, 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %d as output\n", relay_pins[i]);
            deactivate_all_relays();
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    printf("Relay sequencer started. Press Ctrl+C to exit.\n");

    /* Main loop: sequence relays indefinitely until signal received */
    while (keep_running) {
        for (int i = 0; i < NUM_RELAYS && keep_running; i++) {
            /* Activate relay */
            if (gpiod_line_set_value(relay_lines[i], 1) < 0) {
