#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* GPIO pin assignments */
#define MOTOR_IN1 17
#define MOTOR_IN2 18
#define MOTOR_ENA 27

/* SPI configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* mode 0, active-low CS */

/* Rain sensor ADC channel (MCP3008 single-ended) */
#define RAIN_ADC_CHANNEL 0

/* Motor PWM parameters */
#define PWM_RANGE 255
#define PWM_DUTY  150

/* Rain threshold (0-10 scale) */
#define RAIN_THRESHOLD 5

/* Motor run duration (seconds) */
#define MOTOR_RUN_DURATION 3

/* Polling interval (seconds) */
#define POLL_INTERVAL 1

/* Log file path */
#define LOG_FILE "rain_log.txt"

/* Global state */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

/* Function prototypes */
static int  read_mcp3008(int channel);
static int  calculate_rain_level(int adc_value);
static void close_window(void);
static void open_window(void);
static void log_rain_data(int rain_level);
static void signal_handler(int signal);
static void cleanup(void);

/* Read a single-ended channel from the MCP3008 via SPI.
 * Returns 0-1023 on success, -1 on error. */
static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: 3-byte transfer.
     * tx[0] = 0x01 (start bit)
     * tx[1] = (0x08 | channel) << 4  (single-ended + channel, upper nibble)
     * tx[2] = 0x00 (don't care, clocks out low 2 bits + 8 bits)
     * Result: 10-bit value in rx[1] low 2 bits and rx[2] 8 bits.
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* Convert ADC value (0-1023) to rain level (0-10).
 * Grove rain sensor: higher voltage = drier air.
 * So ADC 1023 (max) -> rain level 0 (dry), ADC 0 -> rain level 10 (heaviest).
 */
static int calculate_rain_level(int adc_value) {
    if (adc_value < 0) adc_value = 0;
    if (adc_value > 1023) adc_value = 1023;
    return 10 - (int)((float)adc_value / 1023.0f * 10.0f);
}

/* Drive motor forward to close window. */
static void close_window(void) {
    gpioWrite(MOTOR_IN1, 1);
    gpioWrite(MOTOR_IN2, 0);
    gpioPWM(MOTOR_ENA, PWM_DUTY);
    printf("Closing window...\n");
}

/* Drive motor reverse to open window. */
static void open_window(void) {
    gpioWrite(MOTOR_IN1, 0);
    gpioWrite(MOTOR_IN2, 1);
    gpioPWM(MOTOR_ENA, PWM_DUTY);
    printf("Opening window...\n");
}

/* Append a timestamped rain reading to the log file. */
static void log_rain_data(int rain_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "localtime() failed\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        if (fprintf(log_file, "%s, Rain Level: %d\n", timestamp, rain_level) < 0) {
            fprintf(stderr, "Error writing to log file\n");
        } else {
            fflush(log_file);
        }
    } else {
        fprintf(stderr, "Log file not open\n");
    }
}

/* Signal handler for graceful shutdown. */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Release all resources. */
static void cleanup(void) {
    /* Stop motor */
    gpioWrite(MOTOR_IN1, 0);
    gpioWrite(MOTOR_IN2, 0);
    gpioPWM(MOTOR_ENA, 0);

    /* Close SPI */
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }

    /* Close log file */
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    /* Terminate pigpio */
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure motor GPIOs */
    if (gpioSetMode(MOTOR_IN1, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_IN2, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_ENA, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set motor GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM range and initial duty cycle to 0 */
    if (gpioSetPWMrange(MOTOR_ENA, PWM_RANGE) != 0 ||
        gpioPWM(MOTOR_ENA, 0) != 0) {
        fprintf(stderr, "Failed to configure PWM on GPIO %d\n", MOTOR_ENA);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open SPI */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s'\n", LOG_FILE);
        spiClose(spi_handle);
        spi_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    /* Ensure window is open at start */
    open_window();
    gpioDelay(1000000);  /* 1 second settle */

    /* Main loop */
    while (program_running) {
        int adc_value = read_mcp3008(RAIN_ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading rain sensor, retrying...\n");
            gpioDelay(POLL_INTERVAL * 1000000);
            continue;
        }

        int rain_level = calculate_rain_level(adc_value);
        log_rain_data(rain_level);

        printf("Rain Level: %d\n", rain_level);

        if (rain_level >= RAIN_THRESHOLD) {
            close_window();
            gpioDelay(MOTOR_RUN_DURATION * 1000000);
            if (!program_running) break;
            open_window();
            gpioDelay(MOTOR_RUN_DURATION * 1000000);
        } else {
            gpioDelay(POLL_INTERVAL * 1000000);
        }
    }

    /* Graceful shutdown */
    cleanup();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

