        spi_handle = -1;
    }

    /* Close log file */
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    /* Terminate pigpio */
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure motor GPIOs */
    if (gpioSetMode(MOTOR_IN1, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_IN2, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_ENA, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set motor GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM range and initial duty cycle to 0 */
    if (gpioSetPWMrange(MOTOR_ENA, PWM_RANGE) != 0 ||
        gpioPWM(MOTOR_ENA, 0) != 0) {
        fprintf(stderr, "Failed to configure PWM on GPIO %d\n", MOTOR_ENA);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open SPI */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s'\n", LOG_FILE);
        spiClose(spi_handle);
        spi_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    /* Ensure window is open at start */
    open_window();
    gpioDelay(1000000);  /* 1 second settle */

    /* Main loop */
    while (program_running) {
        int adc_value = read_mcp3008(RAIN_ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading rain sensor, retrying...\n");
            gpioDelay(POLL_INTERVAL * 1000000);
            continue;
        }

        int rain_level = calculate_rain_level(adc_value);
        log_rain_data(rain_level);

        printf("Rain Level: %d\n", rain_level);

        if (rain_level >= RAIN_THRESHOLD) {
            close_window();
            gpioDelay(MOTOR_RUN_DURATION * 1000000);
            if (!program_running) break;
            open_window();
            gpioDelay(MOTOR_RUN_DURATION * 1000000);
        } else {
            gpioDelay(POLL_INTERVAL * 1000000);
        }
    }

    /* Graceful shutdown */
    cleanup();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

