#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define MIC_PIN 26
#define LED_PIN 16
#define THRESHOLD 700
#define DEBOUNCE_MS 50
#define LED_ON_MS 500
#define SAMPLE_DELAY_US 100
#define ADC_MAX 1023

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_adc(int pin) {
    int value = 0;
    for (int i = 0; i < 10; i++) {
        if (gpioWrite(pin, 1) < 0) return -1;
        gpioDelay(1);
        value += gpioRead(pin);
        if (gpioWrite(pin, 0) < 0) return -1;
        gpioDelay(1);
    }
    return value;
}

static void log_detection(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] Clap detected!\n", timestamp);
    fflush(stdout);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MIC_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set MIC_PIN %d as input.\n", MIC_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set LED_PIN %d as output.\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize LED_PIN %d to LOW.\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler.\n");
    }

    printf("Clap detector running. Press Ctrl+C to exit.\n");
    fflush(stdout);

    uint32_t last_trigger_tick = 0;

    while (running) {
        int adc_value = read_adc(MIC_PIN);
        if (adc_value < 0) {
            fprintf(stderr, "Error: ADC read failed on GPIO%d.\n", MIC_PIN);
            break;
        }

        if (adc_value > THRESHOLD) {
            uint32_t now = gpioTick();
            if (now - last_trigger_tick > DEBOUNCE_MS * 1000) {
                log_detection();
                if (gpioWrite(LED_PIN, 1) < 0) {
                    fprintf(stderr, "Error: failed to turn on LED.\n");
                    break;
                }
                gpioDelay(LED_ON_MS * 1000);
                if (gpioWrite(LED_PIN, 0) < 0) {
                    fprintf(stderr, "Error: failed to turn off LED.\n");
                    break;
                }
                last_trigger_tick = now;
            }
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

