#include <errno.h>

#define GPIO_PIN 17
#define DISTANCE_THRESHOLD 200
#define LOG_FILE "distance_log.txt"
#define A 26.0
#define B -6.0
#define VOLTAGE_HIGH 3.3
#define VOLTAGE_LOW 0.0

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int gpio_export(int pin) {
    char buf[64];
    FILE *fp = fopen("/sys/class/gpio/export", "w");
    if (!fp) {
        fprintf(stderr, "Error opening /sys/class/gpio/export: %s\n", strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%d", pin) < 0) {
        fprintf(stderr, "Error writing to /sys/class/gpio/export: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int gpio_unexport(int pin) {
    char buf[64];
    FILE *fp = fopen("/sys/class/gpio/unexport", "w");
    if (!fp) {
        fprintf(stderr, "Error opening /sys/class/gpio/unexport: %s\n", strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%d", pin) < 0) {
        fprintf(stderr, "Error writing to /sys/class/gpio/unexport: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    FILE *fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%s", direction) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int gpio_read(int pin) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    FILE *fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    int value = -1;
    if (fscanf(fp, "%d", &value) != 1) {
        fprintf(stderr, "Error reading from %s\n", path);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return value;
}

static float calculate_distance(int digital_value) {
    float voltage = (digital_value == 1) ? VOLTAGE_HIGH : VOLTAGE_LOW;
    return (A / voltage) + B;
}

static void log_distance(float distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    if (tm) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %.2f mm\n",
                tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
                tm->tm_hour, tm->tm_min, tm->tm_sec, distance);
    }
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpio_export(GPIO_PIN) == -1) {
        return 1;
    }
    usleep(100000);

    if (gpio_set_direction(GPIO_PIN, "in") == -1) {
        gpio_unexport(GPIO_PIN);
        return 1;
    }

    printf("Pet feeder system started. Press Ctrl+C to exit.\n");

    while (running) {
        int digital_value = gpio_read(GPIO_PIN);
        if (digital_value == -1) {
            fprintf(stderr, "Error reading GPIO %d, retrying in 1 second...\n", GPIO_PIN);
            sleep(1);
            continue;
        }

        float distance = calculate_distance(digital_value);
        log_distance(distance);

        if (distance < DISTANCE_THRESHOLD) {
            printf("Feeder Activated\n");
        } else {
            printf("Feeder Idle\n");
        }

        sleep(1);
    }

    gpio_unexport(GPIO_PIN);
    printf("Pet feeder system stopped.\n");
    return 0;
}

