#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define VCC 3.3
#define LED_GPIO 21
#define THRESHOLD 10.0
#define SENSITIVITY_MV_PER_MT 1.65
#define VCC_DIV_2 (VCC / 2.0)
#define ADC_MAX 1023.0
#define DELAY_MS 100

static int spi_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };
    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double adc_to_voltage(int adc_value) {
    return (adc_value / ADC_MAX) * VCC;
}

static double voltage_to_magnetic_field(double voltage) {
    return (voltage - VCC_DIV_2) * 1000.0 / SENSITIVITY_MV_PER_MT;
}

static int log_data(double magnetic_field) {
    FILE *fp = fopen("magnetic_log.txt", "a");
    if (!fp) {
        perror("fopen magnetic_log.txt");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, magnetic_field);
    } else {
        fprintf(fp, "timestamp, %.2f\n", magnetic_field);
    }
    fclose(fp);
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
