#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>

/*
 * Raspberry Pi Zero W – MLX91211 current sensor via MCP3008 SPI ADC
 *
 * Wiring:
 *   MCP3008 VDD/VREF -> Pi 5V (pin 2/4)
 *   MCP3008 AGND/DGND -> Pi GND (pin 6/9/14)
 *   MCP3008 CLK  -> Pi GPIO11 (SCLK)
 *   MCP3008 DOUT -> Pi GPIO9  (MISO)
 *   MCP3008 DIN  -> Pi GPIO10 (MOSI)
 *   MCP3008 CS   -> Pi GPIO8  (CE0)
 *   MCP3008 CH0  -> MLX91211 VOUT
 *   MLX91211 VDD -> Pi 5V
 *   MLX91211 GND -> Pi GND
 *
 * MLX91211 is ratiometric: 2.5 V -> 0 A, 5.0 V -> +50 A.
 */

#define SPI_CHANNEL    0          /* CE0 on GPIO8 */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0 */
#define ADC_MAX        1023       /* 10-bit ADC */
#define VREF           5.0        /* MCP3008 VREF tied to 5V */
#define VOUT_MIN       2.5        /* MLX91211 0 A   -> 2.5 V */
#define VOUT_MAX       5.0        /* MLX91211 +50 A -> 5.0 V */
#define CURRENT_MAX    50.0       /* +50 A full-scale */
#define SAMPLE_US      100000     /* 100 ms between samples */
#define LOG_FILE       "current_log.txt"

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0-1023 on success, -1 on SPI transfer error.
 */
static int read_mcp3008(int spi_handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = 0x80 | (channel << 4)      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: bits 9..0 in ((rx[1] & 0x03) << 8) | rx[2]
     */
    char tx[3] = { 0x01, (char)(0x80 | (channel << 4)), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "spiXfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
}

static float raw_to_voltage(int raw)
{
    return (float)raw * VREF / (float)ADC_MAX;
}

static float voltage_to_current(float v)
{
    if (v < VOUT_MIN) v = VOUT_MIN;
    if (v > VOUT_MAX) v = VOUT_MAX;
    return (v - VOUT_MIN) * (CURRENT_MAX / (VOUT_MAX - VOUT_MIN));
}

static void log_current(FILE *fp, float current)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d %.2f A\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, current);
    fflush(fp);
}

int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI open --- */
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- open log file --- */
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MLX91211 current logging started. Press Ctrl+C to stop.\n");

    /* --- main loop --- */
    while (g_running) {
        int raw = read_mcp3008(spi_handle, ADC_CHANNEL);
        if (raw < 0) {
            gpioDelay(SAMPLE_US);
            continue;
        }

        float voltage = raw_to_voltage(raw);
        float current = voltage_to_current(voltage);

        if (voltage < 0.0f || voltage > VREF) {
            fprintf(stderr, "Warning: voltage %.3f V out of range [0, %.1f] – skipping\n",
                    voltage, VREF);
            gpioDelay(SAMPLE_US);
            continue;
        }

        log_current(fp, current);
        gpioDelay(SAMPLE_US);
    }

    /* --- cleanup --- */
    fclose(fp);
    spiClose(spi_handle);
    gpioTerminate();

    printf("\nProgram terminated cleanly.\n");
    return EXIT_SUCCESS;
}

