#include <errno.h>
#include <pigpio.h>

#define PIR_PIN 17
#define IMAGE_WIDTH 1280
#define IMAGE_HEIGHT 720
#define DEBOUNCE_DELAY_US 200000
#define POLL_DELAY_US 50000
#define CAPTURE_DIR "/home/pi/security_cam"
#define TIMESTAMP_FORMAT "%Y%m%d_%H%M%S"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int capture_image(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char filename[256];
    char command[512];
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        syslog(LOG_ERR, "localtime failed: %s", strerror(errno));
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), TIMESTAMP_FORMAT, timeinfo);

    snprintf(filename, sizeof(filename), "%s/%s.jpg", CAPTURE_DIR, timestamp);
    snprintf(command, sizeof(command),
             "libcamera-still -o '%s' --width %d --height %d --encoding jpg",
             filename, IMAGE_WIDTH, IMAGE_HEIGHT);

    pid_t pid = fork();
    if (pid < 0) {
        syslog(LOG_ERR, "fork failed: %s", strerror(errno));
        return -1;
    }

    if (pid == 0) {
        execlp("libcamera-still", "libcamera-still", "-o", filename,
               "--width", "1280", "--height", "720", "--encoding", "jpg", (char *)NULL);
        _exit(127);
    }

    int status = 0;
    while (waitpid(pid, &status, 0) < 0) {
        if (errno == EINTR) {
            if (!program_running) {
                syslog(LOG_INFO, "Interrupted by signal during capture.");
                return -1;
            }
            continue;
        }
        syslog(LOG_ERR, "waitpid failed: %s", strerror(errno));
        return -1;
    }

    if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
        syslog(LOG_INFO, "Image captured successfully: %s", filename);
        return 0;
    }

    syslog(LOG_ERR, "libcamera-still failed (exit status %d)", WEXITSTATUS(status));
    return -1;
}

