    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed: %s", strerror(errno));
        closelog();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed: %s", strerror(errno));
        closelog();
        return 1;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as input", PIR_PIN);
        gpioTerminate();
        closelog();
        return 1;
    }

    if (gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN) < 0) {
        syslog(LOG_ERR, "Failed to set pull-down on GPIO%d", PIR_PIN);
        gpioTerminate();
        closelog();
        return 1;
    }

    if (mkdir(CAPTURE_DIR, 0755) == -1 && errno != EEXIST) {
        syslog(LOG_ERR, "mkdir(%s) failed: %s", CAPTURE_DIR, strerror(errno));
        gpioTerminate();
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Security camera started (PIR on BCM GPIO%d, capture in %s)",
           PIR_PIN, CAPTURE_DIR);

    int last_state = gpioRead(PIR_PIN);
    if (last_state < 0) {
        syslog(LOG_ERR, "Initial gpioRead failed on GPIO%d", PIR_PIN);
        gpioTerminate();
        closelog();
        return 1;
    }

    while (program_running) {
        int current_state = gpioRead(PIR_PIN);
        if (current_state < 0) {
            syslog(LOG_ERR, "gpioRead failed on GPIO%d", PIR_PIN);
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (current_state != last_state) {
            gpioDelay(DEBOUNCE_DELAY_US);
            int confirmed_state = gpioRead(PIR_PIN);
            if (confirmed_state < 0) {
                syslog(LOG_ERR, "gpioRead failed during debounce on GPIO%d", PIR_PIN);
                last_state = current_state;
                gpioDelay(POLL_DELAY_US);
                continue;
            }
            if (confirmed_state == current_state) {
                last_state = confirmed_state;
                syslog(LOG_INFO, "Motion detected on GPIO%d", PIR_PIN);
                if (capture_image() != 0) {
                    syslog(LOG_ERR, "Failed to capture image");
                }
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    syslog(LOG_INFO, "Security camera shutting down.");
    gpioTerminate();
    closelog();
    return 0;
}

