#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define DEFAULT_DEVICE "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define NUM_BUFFERS 1
#define CAPTURE_TIMEOUT_SEC 2

static volatile sig_atomic_t stop_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    stop_flag = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(int *fd, char *device) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    enum v4l2_buf_type type;
    unsigned int n_buffers = 0;
    int ret = -1;

    *fd = open(device, O_RDWR);
    if (*fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", device, strerror(errno));
        return -1;
    }

    if (xioctl(*fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        goto cleanup;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_GREY;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(*fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        goto cleanup;
    }

    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_GREY) {
        fprintf(stderr, "Device does not support grayscale format\n");
        goto cleanup;
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(*fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        goto cleanup;
    }

    n_buffers = req.count;

    for (unsigned int i = 0; i < n_buffers; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(*fd, VIDIOC_QUERYBUF, &buf) < 0) {
            fprintf(stderr, "Error querying buffer %u: %s\n", i, strerror(errno));
            goto cleanup;
        }

        buf.length = buf.bytesize;
        buf.m.offset = buf.length;

        if (mmap(&buf.m.start, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, *fd, buf.m.offset) < 0) {
            fprintf(stderr, "Error mapping buffer %u: %s\n", i, strerror(errno));
            goto cleanup;
        }
    }

    for (unsigned int i = 0; i < n_buffers; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(*fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "Error queuing buffer %u: %s\n", i, strerror(errno));
            goto cleanup;
        }
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(*fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        goto cleanup;
    }

    ret = 0;

cleanup:
    return ret;
}

static int capture_frame(int fd, unsigned char *buffer, int buffer_size) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = CAPTURE_TIMEOUT_SEC;
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        if (errno == EINTR) return -1;
        fprintf(stderr, "Error during select: %s\n", strerror(errno));
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        return -1;
    }

    memset(&buffer, 0, buffer_size);

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        return -1;
    }

    if (buf.index >= n_buffers) {
        fprintf(stderr, "Invalid buffer index: %u\n", buf.index);
        return -1;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Error re-queuing buffer: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int save_image(const char *filename, unsigned char *data, int width, int height) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    fprintf(fp, "P5\n%d %d\n255\n", width, height);
    size_t written = fwrite(data, 1, width * height, fp);
    if (written != (size_t)(width * height)) {
        fprintf(stderr, "Error writing image data: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    return 0;
}

int main(int argc, char *argv[]) {
    int fd = -1;
    char *device = DEFAULT_DEVICE;
    if (argc > 1) {
        device = argv[1];
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_camera(&fd, device) < 0) {
        return 1;
    }

    int image_number = 1;
    while (!stop_flag) {
        unsigned char *buffer = mmap(NULL, IMAGE_WIDTH * IMAGE_HEIGHT, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
        if (buffer == MAP_FAILED) {
            fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
            break;
        }

        if (capture_frame(fd, buffer, IMAGE_WIDTH * IMAGE_HEIGHT) < 0) {
            if (stop_flag) break;
            fprintf(stderr, "Error capturing frame %d\n", image_number);
            munmap(buffer, IMAGE_WIDTH * IMAGE_HEIGHT);
            continue;
        }

        char filename[64];
        snprintf(filename, sizeof(filename), "image_%04d.pgm", image_number);
        if (save_image(filename, buffer, IMAGE_WIDTH, IMAGE_HEIGHT) < 0) {
            fprintf(stderr, "Error saving image %d\n", image_number);
        } else {
            printf("Saved image %d: %s\n", image_number, filename);
        }

        image_number++;

        munmap(buffer, IMAGE_WIDTH * IMAGE_HEIGHT);
    }

    if (fd >= 0) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
            fprintf(stderr, "Error stopping stream: %s\n", strerror(errno));
        }
    }

    if (fd >= 0) {
        close(fd);
    }

    printf("Program finished.\n");
    return 0;
}

