        if (mmap(&buf.m.start, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, *fd, buf.m.offset) < 0) {
            fprintf(stderr, "Error mapping buffer %u: %s\n", i, strerror(errno));
            goto cleanup;
        }
    }

    for (unsigned int i = 0; i < n_buffers; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(*fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "Error queuing buffer %u: %s\n", i, strerror(errno));
            goto cleanup;
        }
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(*fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        goto cleanup;
    }

    ret = 0;

cleanup:
    return ret;
}

static int capture_frame(int fd, unsigned char *buffer, int buffer_size) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = CAPTURE_TIMEOUT_SEC;
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        if (errno == EINTR) return -1;
        fprintf(stderr, "Error during select: %s\n", strerror(errno));
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        return -1;
    }

    memset(&buffer, 0, buffer_size);

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        return -1;
    }

    if (buf.index >= n_buffers) {
        fprintf(stderr, "Invalid buffer index: %u\n", buf.index);
        return -1;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Error re-queuing buffer: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int save_image(const char *filename, unsigned char *data, int width, int height) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    fprintf(fp, "P5\n%d %d\n255\n", width, height);
    size_t written = fwrite(data, 1, width * height, fp);
    if (written != (size_t)(width * height)) {
        fprintf(stderr, "Error writing image data: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    return 0;
}

int main(int argc, char *argv[]) {
    int fd = -1;
    char *device = DEFAULT_DEVICE;
    if (argc > 1) {
        device = argv[1];
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_camera(&fd, device) < 0) {
        return 1;
    }

    int image_number = 1;
    while (!stop_flag) {
        unsigned char *buffer = mmap(NULL, IMAGE_WIDTH * IMAGE_HEIGHT, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
        if (buffer == MAP_FAILED) {
            fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
            break;
        }

        if (capture_frame(fd, buffer, IMAGE_WIDTH * IMAGE_HEIGHT) < 0) {
            if (stop_flag) break;
            fprintf(stderr, "Error capturing frame %d\n", image_number);
            munmap(buffer, IMAGE_WIDTH * IMAGE_HEIGHT);
            continue;
        }

        char filename[64];
        snprintf(filename, sizeof(filename), "image_%04d.pgm", image_number);
        if (save_image(filename, buffer, IMAGE_WIDTH, IMAGE_HEIGHT) < 0) {
            fprintf(stderr, "Error saving image %d\n", image_number);
        } else {
            printf("Saved image %d: %s\n", image_number, filename);
        }

        image_number++;

        munmap(buffer, IMAGE_WIDTH * IMAGE_HEIGHT);
    }

    if (fd >= 0) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
            fprintf(stderr, "Error stopping stream: %s\n", strerror(errno));
        }
    }

    if (fd >= 0) {
        close(fd);
    }

    printf("Program finished.\n");
    return 0;
}

