    parm.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    parm.parm.capture.timeperframe.numerator = 1;
    parm.parm.capture.timeperframe.denominator = 30;
    if (xioctl(fd, VIDIOC_S_PARM, &parm) == -1) {
        perror("VIDIOC_S_PARM");
        goto cleanup;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    for (int i = 0; i < NUM_BUFFERS; i++) {
        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            perror("VIDIOC_QUERYBUF");
            goto cleanup;
        }
        buf_sizes[i] = buf.length;
        buffers[i] = malloc(buf.length);
        if (!buffers[i]) {
            fprintf(stderr, "malloc failed for buffer %d\n", i);
            goto cleanup;
        }
        if (mmap(&((unsigned char *)buffers[i])[buf.offset], buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset) == MAP_FAILED) {
            perror("mmap");
            free(buffers[i]);
            buffers[i] = NULL;
            goto cleanup;
        }
        mapped++;
    }

    for (int i = 0; i < NUM_BUFFERS; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;
        if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("VIDIOC_QBUF");
            goto cleanup;
        }
    }

