    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("VIDIOC_DQBUF");
        goto cleanup;
    }
    if (buf.bytesused == 0) {
        fprintf(stderr, "No data in frame\n");
        goto cleanup;
    }

    fp = fopen(JPEG_FILE, "wb");
    if (!fp) {
        perror("fopen(" JPEG_FILE ")");
        goto cleanup;
    }

    size_t written = fwrite(buffers[buf.index], 1, buf.bytesused, fp);
    if (written != buf.bytesused) {
        fprintf(stderr, "Short write to JPEG file\n");
        goto cleanup;
    }

    if (fflush(fp) != 0) {
        perror("fflush");
        goto cleanup;
    }

    printf("Saved %zu bytes to %s\n", written, JPEG_FILE);
    ret = EXIT_SUCCESS;

cleanup:
    if (fp) {
        fclose(fp);
    }
    if (mapped) {
        for (int i = 0; i < NUM_BUFFERS; i++) {
            if (buffers[i]) {
                munmap(buffers[i], buf_sizes[i]);
                buffers[i] = NULL;
            }
        }
    }
    if (fd != -1) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        close(fd);
    }
    return ret;
