/*
 * Pan-tilt camera control using libgpiod (modern GPIO API).
 *
 * Pan servo: GPIO4  (software PWM on a dedicated output line)
 * Tilt servo: GPIO5 (software PWM on a dedicated output line)
 * Buttons (active-low, internal pull-ups):
 *   GPIO6 - tilt up
 *   GPIO7 - tilt down
 *   GPIO8 - pan left
 *   GPIO9 - pan right
 *
 * Build: gcc -O2 -Wall -o pan_tilt pan_tilt.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define PAN_GPIO        4
#define TILT_GPIO       5
#define TILT_UP_GPIO    6
#define TILT_DOWN_GPIO  7
#define PAN_LEFT_GPIO   8
#define PAN_RIGHT_GPIO  9

#define PWM_PERIOD_NS   20000000L   /* 20 ms  -> 50 Hz */
#define PWM_DUTY_MIN    50          /* ~1 ms   */
#define PWM_DUTY_MAX    100         /* ~2 ms   */
#define PWM_DUTY_MID    75          /* ~1.5 ms */
#define STEP_SIZE       5
#define MIN_POSITION    25
#define MAX_POSITION    125
#define POLL_DELAY_MS   50

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Software PWM on a single GPIO line using libgpiod.                 */
/* ------------------------------------------------------------------ */

/*
 * Generate one PWM cycle on the given line.  The libgpiod API does not
 * support explicit PWM periods; we drive the line HIGH for duty_ns and
 * then LOW for the remainder of the period.  This is a simple software
 * PWM that is sufficient for hobby servos but may not be suitable for
 * high-precision audio or motor control.
 */
static int pwm_write(struct gpiod_line *line, int duty)
{
    if (duty < 0) duty = 0;
    if (duty > 100) duty = 100;

    struct timespec high = {0, (long)duty * PWM_PERIOD_NS / 100};
    struct timespec low  = {0, (long)(100 - duty) * PWM_PERIOD_NS / 100};

    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "PWM set HIGH failed: %s\n", strerror(errno));
        return -1;
    }
    if (nanosleep(&high, NULL) < 0 && errno != EINTR) {
        fprintf(stderr, "PWM HIGH sleep failed: %s\n", strerror(errno));
        return -1;
    }
    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "PWM set LOW failed: %s\n", strerror(errno));
        return -1;
    }
    if (nanosleep(&low, NULL) < 0 && errno != EINTR) {
        fprintf(stderr, "PWM LOW sleep failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int servo_write(struct gpiod_line *line, int position)
{
    if (position < MIN_POSITION) position = MIN_POSITION;
    if (position > MAX_POSITION) position = MAX_POSITION;

    int duty = (position - MIN_POSITION) * (PWM_DUTY_MAX - PWM_DUTY_MIN) /
               (MAX_POSITION - MIN_POSITION) + PWM_DUTY_MIN;
    return pwm_write(line, duty);
}

static int move_servo(struct gpiod_line *line, int *position, int delta)
{
    *position += delta;
    if (*position < MIN_POSITION) *position = MIN_POSITION;
    if (*position > MAX_POSITION) *position = MAX_POSITION;
    return servo_write(line, *position);
}

/* ------------------------------------------------------------------ */
/* Button polling                                                     */
/* ------------------------------------------------------------------ */

static int read_button(struct gpiod_line *line, int *prev)
{
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        fprintf(stderr, "Button read failed: %s\n", strerror(errno));
        return -1;
    }
    /* Active-low: 0 means pressed */
    if (val == 0 && *prev == 1) {
        *prev = 0;
        return 1;
    }
    if (val == 1 && *prev == 0) {
        *prev = 1;
        return 0;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pan_line = NULL;
    struct gpiod_line *tilt_line = NULL;
    struct gpiod_line *tilt_up_line = NULL;
    struct gpiod_line *tilt_down_line = NULL;
    struct gpiod_line *pan_left_line = NULL;
    struct gpiod_line *pan_right_line = NULL;
    int tilt_pos = PWM_DUTY_MID;
    int pan_pos  = PWM_DUTY_MID;
    int tilt_up_prev = 1, tilt_down_prev = 1;
    int pan_left_prev = 1, pan_right_prev = 1;
    int ret = EXIT_FAILURE;

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip ---- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Get lines ---- */
    pan_line  = gpiod_chip_get_line(chip, PAN_GPIO);
    tilt_line = gpiod_chip_get_line(chip, TILT_GPIO);
    tilt_up_line  = gpiod_chip_get_line(chip, TILT_UP_GPIO);
    tilt_down_line = gpiod_chip_get_line(chip, TILT_DOWN_GPIO);
    pan_left_line  = gpiod_chip_get_line(chip, PAN_LEFT_GPIO);
    pan_right_line = gpiod_chip_get_line(chip, PAN_RIGHT_GPIO);

    if (!pan_line || !tilt_line || !tilt_up_line || !tilt_down_line ||
        !pan_left_line || !pan_right_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    /* ---- Request output lines for PWM ---- */
    if (gpiod_line_request_output(pan_line, "pan_tilt", 0) < 0) {
        fprintf(stderr, "Request pan line failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(tilt_line, "pan_tilt", 0) < 0) {
        fprintf(stderr, "Request tilt line failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* ---- Request input lines with pull-ups ---- */
    if (gpiod_line_request_input_flags(tilt_up_line, "pan_tilt",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Request tilt_up line failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input_flags(tilt_down_line, "pan_tilt",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Request tilt_down line failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input_flags(pan_left_line, "pan_tilt",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Request pan_left line failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input_flags(pan_right_line, "pan_tilt",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Request pan_right line failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* ---- Start at mid-position ---- */
    if (servo_write(pan_line, pan_pos) < 0 ||
        servo_write(tilt_line, tilt_pos) < 0) {
        fprintf(stderr, "Initial servo write failed\n");
        goto cleanup;
    }

    printf("Pan-tilt control ready.  Press Ctrl+C to exit.\n");
    printf("  Tilt up: GPIO6  Tilt down: GPIO7  Pan left: GPIO8  Pan right: GPIO9\n");

    /* ---- Main loop ---- */
    while (g_running) {
        int tu = read_button(tilt_up_line, &tilt_up_prev);
        int td = read_button(tilt_down_line, &tilt_down_prev);
        int pl = read_button(pan_left_line, &pan_left_prev);
        int pr = read_button(pan_right_line, &pan_right_prev);

        if (tu < 0 || td < 0 || pl < 0 || pr < 0) {
            /* Button read error — back off briefly and retry */
            usleep(POLL_DELAY_MS * 1000);
            continue;
        }

        if (tu)  move_servo(tilt_line, &tilt_pos,  STEP_SIZE);
        if (td)  move_servo(tilt_line, &tilt_pos, -STEP_SIZE);
        if (pl)  move_servo(pan_line,  &pan_pos,  -STEP_SIZE);
        if (pr)  move_servo(pan_line,  &pan_pos,   STEP_SIZE);

        usleep(POLL_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (pan_line)  gpiod_line_release(pan_line);
    if (tilt_line) gpiod_line_release(tilt_line);
    if (tilt_up_line)  gpiod_line_release(tilt_up_line);
    if (tilt_down_line) gpiod_line_release(tilt_down_line);
    if (pan_left_line)  gpiod_line_release(pan_left_line);
    if (pan_right_line) gpiod_line_release(pan_right_line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

