        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip ---- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Get lines ---- */
    pan_line  = gpiod_chip_get_line(chip, PAN_GPIO);
    tilt_line = gpiod_chip_get_line(chip, TILT_GPIO);
    tilt_up_line  = gpiod_chip_get_line(chip, TILT_UP_GPIO);
    tilt_down_line = gpiod_chip_get_line(chip, TILT_DOWN_GPIO);
    pan_left_line  = gpiod_chip_get_line(chip, PAN_LEFT_GPIO);
    pan_right_line = gpiod_chip_get_line(chip, PAN_RIGHT_GPIO);

    if (!pan_line || !tilt_line || !tilt_up_line || !tilt_down_line ||
        !pan_left_line || !pan_right_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    /* ---- Request output lines for PWM ---- */
    if (gpiod_line_request_output(pan_line, "pan_tilt", 0) < 0) {
        fprintf(stderr, "Request pan line failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(tilt_line, "pan_tilt", 0) < 0) {
        fprintf(stderr, "Request tilt line failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* ---- Request input lines with pull-ups ---- */
    if (gpiod_line_request_input_flags(tilt_up_line, "pan_tilt",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Request tilt_up line failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input_flags(tilt_down_line, "pan_tilt",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Request tilt_down line failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input_flags(pan_left_line, "pan_tilt",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Request pan_left line failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input_flags(pan_right_line, "pan_tilt",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Request pan_right line failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* ---- Start at mid-position ---- */
    if (servo_write(pan_line, pan_pos) < 0 ||
        servo_write(tilt_line, tilt_pos) < 0) {
        fprintf(stderr, "Initial servo write failed\n");
        goto cleanup;
    }

    printf("Pan-tilt control ready.  Press Ctrl+C to exit.\n");
    printf("  Tilt up: GPIO6  Tilt down: GPIO7  Pan left: GPIO8  Pan right: GPIO9\n");

    /* ---- Main loop ---- */
    while (g_running) {
        int tu = read_button(tilt_up_line, &tilt_up_prev);
        int td = read_button(tilt_down_line, &tilt_down_prev);
        int pl = read_button(pan_left_line, &pan_left_prev);
        int pr = read_button(pan_right_line, &pan_right_prev);

        if (tu < 0 || td < 0 || pl < 0 || pr < 0) {
            /* Button read error — back off briefly and retry */
            usleep(POLL_DELAY_MS * 1000);
            continue;
        }

        if (tu)  move_servo(tilt_line, &tilt_pos,  STEP_SIZE);
        if (td)  move_servo(tilt_line, &tilt_pos, -STEP_SIZE);
        if (pl)  move_servo(pan_line,  &pan_pos,  -STEP_SIZE);
        if (pr)  move_servo(pan_line,  &pan_pos,   STEP_SIZE);

        usleep(POLL_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (pan_line)  gpiod_line_release(pan_line);
    if (tilt_line) gpiod_line_release(tilt_line);
    if (tilt_up_line)  gpiod_line_release(tilt_up_line);
    if (tilt_down_line) gpiod_line_release(tilt_down_line);
    if (pan_left_line)  gpiod_line_release(pan_left_line);
    if (pan_right_line) gpiod_line_release(pan_right_line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

