#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <jpeglib.h>
#include <time.h>
#include <errno.h>
#include <signal.h>

#define CAMERA_DEVICE "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define BLUR_SIZE 5
#define JPEG_QUALITY 75

static volatile sig_atomic_t stop_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    stop_flag = 1;
}

typedef struct {
    int fd;
    void *buffer;
    size_t buffer_size;
    unsigned int n_buffers;
} camera_t;

static int xioctl(int fd, int request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static void cleanup_camera(camera_t *cam) {
    if (cam->fd >= 0) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (xioctl(cam->fd, VIDIOC_STREAMOFF, &type) == -1) {
            perror("VIDIOC_STREAMOFF");
        }
        if (cam->buffer && cam->buffer != MAP_FAILED) {
            if (munmap(cam->buffer, cam->buffer_size) == -1) {
                perror("munmap");
            }
        }
        if (cam->fd >= 0) {
            close(cam->fd);
            cam->fd = -1;
        }
    }
}

static int init_camera(camera_t *cam) {
    cam->fd = open(CAMERA_DEVICE, O_RDWR | O_NONBLOCK, 0);
    if (cam->fd == -1) {
        perror("Error opening device");
        return -1;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(cam->fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        close(cam->fd);
        cam->fd = -1;
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(cam->fd);
        cam->fd = -1;
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        close(cam->fd);
        cam->fd = -1;
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(cam->fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        close(cam->fd);
        cam->fd = -1;
        return -1;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 4;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(cam->fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        close(cam->fd);
        cam->fd = -1;
        return -1;
    }

    cam->n_buffers = req.count;
    cam->buffer_size = fmt.fmt.pix.sizeimage;
    cam->buffer = mmap(NULL, cam->buffer_size, PROT_READ | PROT_WRITE, MAP_SHARED, cam->fd, 0);
    if (cam->buffer == MAP_FAILED) {
        perror("mmap");
        cam->buffer = NULL;
        close(cam->fd);
        cam->fd = -1;
        return -1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(cam->fd, VIDIOC_QUERYBUF, &buf) == -1) {
        perror("VIDIOC_QUERYBUF");
        munmap(cam->buffer, cam->buffer_size);
        cam->buffer = NULL;
        close(cam->fd);
        cam->fd = -1;
        return -1;
    }

    cam->buffer = mmap(NULL, cam->buffer_size, PROT_READ | PROT_WRITE, MAP_SHARED, cam->fd, buf.m.offset);
    if (cam->buffer == MAP_FAILED) {
        perror("mmap");
        cam->buffer = NULL;
        close(cam->fd);
        cam->fd = -1;
        return -1;
    }

    if (xioctl(cam->fd, VIDIOC_QBUF, &buf) == -1) {
        perror("VIDIOC_QBUF");
        munmap(cam->buffer, cam->buffer_size);
        cam->buffer = NULL;
        close(cam->fd);
        cam->fd = -1;
        return -1;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(cam->fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON");
        munmap(cam->buffer, cam->buffer_size);
        cam->buffer = NULL;
        close(cam->fd);
        cam->fd = -1;
        return -1;
    }

    return 0;
}

static int capture_frame(camera_t *cam) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(cam->fd, &fds);

    tv.tv_sec = 2;
    tv.tv_usec = 0;

    r = select(cam->fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        if (errno == EINTR) return -1;
        perror("select");
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "select timeout\n");
        return -1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(cam->fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("VIDIOC_DQBUF");
        return -1;
    }

    if (buf.index == -1) {
        fprintf(stderr, "Invalid buffer index\n");
        return -1;
    }

    return 0;
}

static void *yuyv_to_rgb24(void *yuyv, int width, int height) {
    unsigned char *yuyv_data = (unsigned char *)yuyv;
    unsigned char *rgb_data = (unsigned char *)malloc((size_t)width * height * 3);
    if (!rgb_data) return NULL;

    for (int i = 0; i < height; i++) {
        for (int j = 0; j < width; j++) {
            int idx = (i * width + j) * 2;
            unsigned char y = yuyv_data[idx];
            unsigned char u = yuyv_data[idx + 1];
            unsigned char v = yuyv_data[idx + 2];
            unsigned char y2 = yuyv_data[idx + 3];

            int c_u = u - 128;
            int c_v = v - 128;
            int r = y + 1.402 * c_v;
            int g = y - 0.34414 * c_u - 0.71414 * c_v;
            int b = y + 1.772 * c_u;

            if (r > 255) r = 255; if (r < 0) r = 0;
            if (g > 255) g = 255; if (g < 0) g = 0;
            if (b > 255) b = 255; if (b < 0) b = 0;

            rgb_data[(i * width + j) * 3 + 0] = (unsigned char)r;
            rgb_data[(i * width + j) * 3 + 1] = (unsigned char)g;
            rgb_data[(i * width + j) * 3 + 2] = (unsigned char)b;
        }
    }
    return rgb_data;
}

static void blur_image(unsigned char *image, int width, int height) {
    int kernel_size = BLUR_SIZE * 2 + 1;
    unsigned char *blurred = (unsigned char *)malloc((size_t)width * height * 3);
    if (!blurred) return;

    for (int i = 0; i < height; i++) {
        for (int j = 0; j < width; j++) {
            int sum_r = 0, sum_g = 0, sum_b = 0;
            for (int m = -BLUR_SIZE; m <= BLUR_SIZE; m++) {
                for (int n = -BLUR_SIZE; n <= BLUR_SIZE; n++) {
                    int x = j + n;
                    int y = i + m;
                    if (x < 0 || x >= width || y < 0 || y >= height) continue;
                    int idx = (y * width + x) * 3;
                    sum_r += image[idx];
                    sum_g += image[idx + 1];
                    sum_b += image[idx + 2];
                }
            }
            blurred[(i * width + j) * 3 + 0] = (unsigned char)(sum_r / kernel_size);
            blurred[(i * width + j) * 3 + 1] = (unsigned char)(sum_g / kernel_size);
            blurred[(i * width + j) * 3 + 2] = (unsigned char)(sum_b / kernel_size);
        }
    }
    memcpy(image, blurred, (size_t)width * height * 3);
    free(blurred);
}

static int save_jpeg(const unsigned char *image, int width, int height, const char *filename) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);

    FILE *outfile = fopen(filename, "wb");
    if (!outfile) {
        perror("fopen");
        jpeg_destroy_compress(&cinfo);
        return -1;
    }

    jpeg_stdio_dest(&cinfo, outfile);

    cinfo.image_width = width;
    cinfo.image_height = height;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, JPEG_QUALITY, TRUE);
    jpeg_start_compress(&cinfo, TRUE);

    JSAMPROW row_pointer[1];
    int row_stride = width * 3;

    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = &image[cinfo.next_scanline * row_stride];
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }

    jpeg_finish_compress(&cinfo);
    fclose(outfile);
    jpeg_destroy_compress(&cinfo);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    camera_t cam;
    memset(&cam, 0, sizeof(cam));
    cam.fd = -1;

    if (init_camera(&cam) == -1) {
        fprintf(stderr, "Failed to initialize camera\n");
        return 1;
    }

    if (stop_flag) {
        fprintf(stderr, "Interrupted before capture\n");
        cleanup_camera(&cam);
        return 1;
    }

    if (capture_frame(&cam) == -1) {
        fprintf(stderr, "Failed to capture frame\n");
        cleanup_camera(&cam);
        return 1;
    }

    unsigned char *rgb_image = yuyv_to_rgb24(cam.buffer, IMAGE_WIDTH, IMAGE_HEIGHT);
    if (!rgb_image) {
        fprintf(stderr, "Failed to convert YUYV to RGB\n");
        cleanup_camera(&cam);
        return 1;
    }

    blur_image(rgb_image, IMAGE_WIDTH, IMAGE_HEIGHT);

    time_t rawtime;
    struct tm *timeinfo;
    char filename[64];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(filename, sizeof(filename), "capture_%Y%m%d_%H%M%S.jpg", timeinfo);

    if (save_jpeg(rgb_image, IMAGE_WIDTH, IMAGE_HEIGHT, filename) == -1) {
        fprintf(stderr, "Failed to save JPEG\n");
        free(rgb_image);
        cleanup_camera(&cam);
        return 1;
    }

    printf("Saved blurred image: %s\n", filename);

    free(rgb_image);
    cleanup_camera(&cam);
    return 0;
}

