#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"

static void print_error(const char *msg) {
    fprintf(stderr, "Error: %s (errno %d: %s)\n", msg, errno, strerror(errno));
}

static int query_capability(int fd, struct v4l2_capability *cap) {
    if (ioctl(fd, VIDIOC_QUERYCAP, cap) < 0) {
        print_error("VIDIOC_QUERYCAP");
        return -1;
    }
    return 0;
}

static int enumerate_frame_sizes(int fd, unsigned int index, struct v4l2_frmsizeenum *size) {
    memset(size, 0, sizeof(*size));
    size->index = index;
    if (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, size) < 0) {
        print_error("VIDIOC_ENUM_FRAMESIZES");
        return -1;
    }
    return 0;
}

static int enumerate_frame_intervals(int fd, unsigned int index, struct v4l2_frmivalenum *ival) {
    memset(ival, 0, sizeof(*ival));
    ival->index = index;
    if (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, ival) < 0) {
        print_error("VIDIOC_ENUM_FRAMEINTERVALS");
        return -1;
    }
    return 0;
}

static int query_control(int fd, unsigned int idx, struct v4l2_queryctrl *qctrl) {
    memset(qctrl, 0, sizeof(*qctrl));
    qctrl->type = idx;
    if (ioctl(fd, VIDIOC_QUERYCTRL, qctrl) < 0) {
        print_error("VIDIOC_QUERYCTRL");
        return -1;
    }
    return 0;
}

static void print_summary(const struct v4l2_capability *cap,
                          const struct v4l2_frmsizeenum *sizes,
                          const struct v4l2_frmivalenum *ivals,
                          int autofocus) {
    printf("Camera Summary:\n");
    printf("  Driver: %s\n", cap->driver);
    printf("  Card: %s\n", cap->card);
    printf("  Bus info: %s\n", cap->bus_info);
    printf("  Version: %u.%u.%u\n",
           (cap->version >> 16) & 0xFF,
           (cap->version >> 8) & 0xFF,
           cap->version & 0xFF);
    printf("  Capabilities: 0x%08x\n", cap->capabilities);
    printf("  Supported Resolutions:\n");
    for (unsigned int i = 0; sizes[i].pixel_format != V4L2_PIX_FMT_NONE; i++) {
        printf("    [%u] %c%c%c%c (%ux%u)\n",
               i,
               (sizes[i].pixel_format >> 0) & 0xFF,
               (sizes[i].pixel_format >> 8) & 0xFF,
               (sizes[i].pixel_format >> 16) & 0xFF,
               (sizes[i].pixel_format >> 24) & 0xFF,
               sizes[i].width, sizes[i].height);
    }
    printf("  Supported Frame Rates:\n");
    for (unsigned int i = 0; ival[i].pixel_format != V4L2_PIX_FMT_NONE; i++) {
        printf("    [%u] %c%c%c%c (%u/%u)\n",
               i,
               (ivals[i].pixel_format >> 0) & 0xFF,
               (ivals[i].pixel_format >> 8) & 0xFF,
               (ivals[i].pixel_format >> 16) & 0xFF,
               (ivals[i].pixel_format >> 24) & 0xFF,
               ivals[i].numerator, ival[i].denominator);
    }
    printf("  Autofocus: %s\n", autofocus ? "yes" : "no");
}

int main(void) {
    int fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        print_error("open(" DEVICE_NAME ")");
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    if (query_capability(fd, &cap) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_frmsizeenum sizes[64];
    struct v4l2_frmivalenum  ival[64];
    int sz_count = 0;
    int ival_count = 0;

    for (unsigned int i = 0; i < sizeof(sizes)/sizeof(sizes[0]); i++) {
        if (enumerate_frame_sizes(fd, i, &sizes[i]) < 0) {
            break;
        }
        if (sizes[i].pixel_format == V4L2_PIX_FMT_NONE) {
            break;
        }
        sz_count++;
    }

    for (unsigned int i = 0; i < sizeof(ival)/sizeof(ival[0]); i++) {
        if (enumerate_frame_intervals(fd, i, &ival[i]) < 0) {
            break;
        }
        if (ival[i].pixel_format == V4L2_PIX_FMT_NONE) {
            break;
        }
        ival_count++;
    }

    struct v4l2_queryctrl autofocus_ctrl;
    int autofocus = 0;
    if (query_control(fd, V4L2_CID_FOCUS_AUTO, &autofocus_ctrl) == 0) {
        autofocus = 1;
    }

    print_summary(&cap, sizes, ival, autofocus);

    close(fd);
    return EXIT_SUCCESS;
}

