#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_BUTTON_PIN 6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

#define SERVO_MIN_PULSEWIDTH 1000
#define SERVO_MAX_PULSEWIDTH 2000
#define SERVO_CENTER_PULSEWIDTH 1500
#define PULSEWIDTH_STEP 10
#define LOOP_DELAY_US 50000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", PAN_SERVO_PIN);
        return -1;
    }
    if (gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", TILT_SERVO_PIN);
        return -1;
    }
    if (gpioSetMode(UP_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", UP_BUTTON_PIN);
        return -1;
    }
    if (gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", DOWN_BUTTON_PIN);
        return -1;
    }
    if (gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", LEFT_BUTTON_PIN);
        return -1;
    }
    if (gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", RIGHT_BUTTON_PIN);
        return -1;
    }

    if (gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", UP_BUTTON_PIN);
        return -1;
    }
    if (gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", DOWN_BUTTON_PIN);
        return -1;
    }
    if (gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", LEFT_BUTTON_PIN);
        return -1;
    }
    if (gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", RIGHT_BUTTON_PIN);
        return -1;
    }

    return 0;
}

static int set_servo_pulsewidth(int pin, int pulsewidth) {
    if (pulsewidth < SERVO_MIN_PULSEWIDTH || pulsewidth > SERVO_MAX_PULSEWIDTH) {
        fprintf(stderr, "Error: pulsewidth %d out of range [%d, %d].\n",
                pulsewidth, SERVO_MIN_PULSEWIDTH, SERVO_MAX_PULSEWIDTH);
        return -1;
    }
    if (gpioServo(pin, pulsewidth) < 0) {
        fprintf(stderr, "Error: gpioServo failed on GPIO%d.\n", pin);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() < 0) {
        return EXIT_FAILURE;
    }

    if (set_servo_pulsewidth(PAN_SERVO_PIN, SERVO_CENTER_PULSEWIDTH) < 0 ||
        set_servo_pulsewidth(TILT_SERVO_PIN, SERVO_CENTER_PULSEWIDTH) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Pan-tilt camera control started.\n");
    printf("  Pan servo: GPIO%d\n", PAN_SERVO_PIN);
    printf("  Tilt servo: GPIO%d\n", TILT_SERVO_PIN);
    printf("  UP: GPIO%d | DOWN: GPIO%d | LEFT: GPIO%d | RIGHT: GPIO%d\n",
           UP_BUTTON_PIN, DOWN_BUTTON_PIN, LEFT_BUTTON_PIN, RIGHT_BUTTON_PIN);
    printf("  Center: %d us. Press Ctrl+C to exit.\n", SERVO_CENTER_PULSEWIDTH);

    int pan_pulsewidth = SERVO_CENTER_PULSEWIDTH;
    int tilt_pulsewidth = SERVO_CENTER_PULSEWIDTH;

    while (g_running) {
        int up_pressed = (gpioRead(UP_BUTTON_PIN) == 0);
        int down_pressed = (gpioRead(DOWN_BUTTON_PIN) == 0);
        int left_pressed = (gpioRead(LEFT_BUTTON_PIN) == 0);
        int right_pressed = (gpioRead(RIGHT_BUTTON_PIN) == 0);

        if (up_pressed) {
            pan_pulsewidth += PULSEWIDTH_STEP;
            if (pan_pulsewidth > SERVO_MAX_PULSEWIDTH) pan_pulsewidth = SERVO_MAX_PULSEWIDTH;
            if (set_servo_pulsewidth(PAN_SERVO_PIN, pan_pulsewidth) < 0) break;
        }
        if (down_pressed) {
            pan_pulsewidth -= PULSEWIDTH_STEP;
            if (pan_pulsewidth < SERVO_MIN_PULSEWIDTH) pan_pulsewidth = SERVO_MIN_PULSEWIDTH;
            if (set_servo_pulsewidth(PAN_SERVO_PIN, pan_pulsewidth) < 0) break;
        }
        if (left_pressed) {
            tilt_pulsewidth -= PULSEWIDTH_STEP;
            if (tilt_pulsewidth < SERVO_MIN_PULSEWIDTH) tilt_pulsewidth = SERVO_MIN_PULSEWIDTH;
            if (set_servo_pulsewidth(TILT_SERVO_PIN, tilt_pulsewidth) < 0) break;
        }
        if (right_pressed) {
            tilt_pulsewidth += PULSEWIDTH_STEP;
            if (tilt_pulsewidth > SERVO_MAX_PULSEWIDTH) tilt_pulsewidth = SERVO_MAX_PULSEWIDTH;
            if (set_servo_pulsewidth(TILT_SERVO_PIN, tilt_pulsewidth) < 0) break;
        }

        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

