static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int ensure_directory(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode)) {
            return 0;
        }
        fprintf(stderr, "Error: '%s' exists but is not a directory\n", path);
        return -1;
    }
    if (mkdir(path, 0755) != 0) {
        perror("mkdir");
        return -1;
    }
    return 0;
}

static int capture_image(const char *filename) {
    char command[MAX_COMMAND_LENGTH];
    int needed = snprintf(command, sizeof(command),
        "libcamera-still -o '%s' --width %d --height %d --quality %d --nopreview 2>>/dev/null",
        filename, IMAGE_WIDTH, IMAGE_HEIGHT, IMAGE_QUALITY);
    if (needed < 0 || (size_t)needed >= sizeof(command)) {
        fprintf(stderr, "Error: command buffer too small\n");
        return -1;
    }
    int status = system(command);
    if (status == -1) {
        perror("system");
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Error: libcamera-still failed (status=0x%04x)\n", status);
        return -1;
    }
    return 0;
}

static int send_data(const char *filename, const char *timestamp, int motion_status, int gpio_pin) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Error: curl_easy_init() failed\n");
        return -1;
    }
    char json_string[MAX_FILENAME_LENGTH + 256];
    int needed = snprintf(json_string, sizeof(json_string),
        "{\"filename\":\"%s\",\"timestamp\":\"%s\",\"motion_status\":%d,\"gpio_pin\":%d}",
        filename, timestamp, motion_status, gpio_pin);
    if (needed < 0 || (size_t)needed >= sizeof(json_string)) {
        fprintf(stderr, "Error: JSON buffer too small\n");
        curl_easy_cleanup(curl);
        return -1;
    }
    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        fprintf(stderr, "Error: curl_slist_append() failed\n");
        curl_easy_cleanup(curl);
        return -1;
    }
    curl_easy_setopt(curl, CURLOPT_URL, "http://");
    curl_easy_setopt(curl, CURLOPT_URL, curl_easy_setopt(curl, CURLOPT_URL, "http://<server_ip>:<server_port>/upload"));
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
