        fprintf(stderr, "Error: gpioSetPullUpDown(%d, PI_PUD_DOWN) failed\n", PIR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ensure_directory("motion_captures") != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    curl_global_init(CURL_GLOBAL_ALL);

    printf("Motion detection started on GPIO%d. Press Ctrl+C to exit.\n", PIR_GPIO);

