        snprintf(err_msg, sizeof(err_msg),
                 "Error: libcamera-still exited with status %d.", WEXITSTATUS(status));
        log_message(err_msg);
        return -1;
    }
    return 0;
}

static int generate_filename(char *filename, size_t size) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", &tm);
    int min = tm.tm_min;
    snprintf(filename, size, "%s/%s_%03d.jpg", IMAGE_DIR, timestamp, min);
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pir_line = NULL;
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        log_message("Error: Failed to open GPIO chip.");
        return 1;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        perror("gpiod_chip_get_line");
        log_message("Error: Failed to get GPIO line.");
        goto cleanup;
    }

    if (gpiod_line_request_falling_edge_events(pir_line, "motion-capture") < 0) {
        perror("gpiod_line_request_falling_edge_events");
        log_message("Error: Failed to request falling edge events on PIR pin.");
        goto cleanup;
    }

    log_message("Motion capture program started.");

    while (program_running) {
        struct timespec ts = { 0, POLL_TIMEOUT_MS * 1000000L };
        int ev = gpiod_line_event_wait(pir_line, &ts);

        if (ev < 0) {
            if (errno == EINTR) continue;
            perror("gpiod_line_event_wait");
            log_message("Error: Failed to wait for GPIO event.");
            break;
        }

        if (ev == 0) {
            continue;
        }

        struct gpiod_line_event event;
        if (gpiod_line_event_read(pir_line, &event) < 0) {
            perror("gpiod_line_event_read");
            log_message("Error: Failed to read GPIO event.");
            continue;
        }

        if (event.event_type != GPIOD_LINE_EVENT_FALLING_EDGE) {
            continue;
        }

        usleep(DEBOUNCE_MS * 1000);

        if (!program_running) break;

        char filename[256];
        if (generate_filename(filename, sizeof(filename)) != 0) {
            log_message("Error: Failed to generate filename.");
            continue;
        }

        if (capture_image(filename) == 0) {
            char msg[256];
            snprintf(msg, sizeof(msg), "Image saved: %s", filename);
            log_message(msg);
        } else {
            log_message("Error: Failed to capture image.");
        }
    }

    log_message("Motion capture program exiting.");
    ret = 0;

cleanup:
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

