#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define CROP_X 100
#define CROP_Y 50
#define CROP_WIDTH 200
#define CROP_HEIGHT 150
#define NUM_BUFFERS 1
#define CAPTURE_TIMEOUT_SEC 2

static volatile sig_atomic_t stop_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    stop_flag = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

int main(void) {
    int fd = -1;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    void *buffers[NUM_BUFFERS];
    size_t buf_size = 0;
    unsigned char *frame = NULL;
    unsigned char *cropped_frame = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd == -1) {
        perror("open(" DEVICE_NAME ")");
        return EXIT_FAILURE;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        goto cleanup;
    }

    if (fmt.fmt.pix.width != WIDTH || fmt.fmt.pix.height != HEIGHT) {
        fprintf(stderr, "Warning: driver chose %ux%u instead of %ux%u\n",
                fmt.fmt.pix.width, fmt.fmt.pix.height, WIDTH, HEIGHT);
    }
    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Warning: driver chose pixel format 0x%08x (expected YUYV)\n",
                fmt.fmt.pix.pixelformat);
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        goto cleanup;
    }
    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory on device\n");
        goto cleanup;
    }

    for (unsigned int i = 0; i < req.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;
        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            perror("VIDIOC_QUERYBUF");
            goto cleanup;
        }
        buffers[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[i] == MAP_FAILED) {
            perror("mmap");
            buffers[i] = NULL;
            goto cleanup;
        }
        buf_size = buf.length;
    }

    for (unsigned int i = 0; i < req.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;
        if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("VIDIOC_QBUF");
            goto cleanup;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON");
        goto cleanup;
    }

    fd_set fds;
    struct timeval tv;
    int r;
    do {
        FD_ZERO(&fds);
        FD_SET(fd, &fds);
        tv.tv_sec = CAPTURE_TIMEOUT_SEC;
        tv.tv_usec = 0;
        r = select(fd + 1, &fds, NULL, NULL, &tv);
        if (r == -1) {
            if (errno == EINTR) continue;
            perror("select");
            goto cleanup;
        }
        if (r == 0) {
            fprintf(stderr, "select timeout: no frame captured within %d seconds\n", CAPTURE_TIMEOUT_SEC);
            goto cleanup;
        }
    } while (stop_flag);

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("VIDIOC_DQBUF");
        goto cleanup;
    }

    if (buf.bytesused < (size_t)(WIDTH * HEIGHT * 2)) {
        fprintf(stderr, "Warning: captured %u bytes, expected %u for %ux%u\n",
                buf.bytesused, WIDTH * HEIGHT * 2, WIDTH, HEIGHT);
    }

    frame = malloc(buf.bytesused);
    if (!frame) {
        perror("malloc");
        goto cleanup;
    }
    memcpy(frame, buffers[buf.index], buf.bytesused);

    cropped_frame = malloc(CROP_WIDTH * CROP_HEIGHT * 2);
    if (!cropped_frame) {
        perror("malloc");
        goto cleanup;
    }

    for (int y = 0; y < CROP_HEIGHT; y++) {
        for (int x = 0; x < CROP_WIDTH; x++) {
            int src_x = CROP_X + x;
            int src_y = CROP_Y + y;
            int dst_idx = (y * CROP_WIDTH + x) * 2;
            size_t src_row = src_y * WIDTH * 2;
            unsigned char *src = frame + src_row + src_x * 2;
            cropped_frame[dst_idx]     = src[0];
            cropped_frame[dst_idx + 1] = src[1];
            src += 2;
            dst_idx += 2;
            cropped_frame[dst_idx]     = src[0];
            cropped_frame[dst_idx + 1] = src[1];
            src += 2;
        }
    }

    FILE *fp = fopen("cropped.yuv", "wb");
    if (!fp) {
        perror("fopen(cropped.yuv)");
        goto cleanup;
    }
    size_t written = fwrite(cropped_frame, 1, CROP_WIDTH * CROP_HEIGHT * 2, fp);
    if (written != (size_t)(CROP_WIDTH * CROP_HEIGHT * 2)) {
        perror("fwrite");
        goto cleanup;
    }
    if (fclose(fp) != 0) {
        perror("fclose");
        goto cleanup;
    }

    printf("Cropped frame saved as cropped.yuv (%dx%d)\n", CROP_WIDTH, CROP_HEIGHT);
    ret = EXIT_SUCCESS;

cleanup:
    if (fd != -1) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        for (unsigned int i = 0; i < req.count; i++) {
            if (buffers[i] != NULL && buffers[i] != MAP_FAILED) {
                munmap(buffers[i], buf_size);
                buffers[i] = NULL;
            }
        }
        close(fd);
    }
    free(frame);
    free(cropped_frame);
    return ret;
}

