#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_GPIO 17
#define TILT_GPIO 18
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define NEUTRAL_ANGLE 90
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define STEP_SIZE 5
#define DELAY_MS 100

static volatile int keep_running = 1;

void handle_sigint(int sig) {
    (void)sig;
    keep_running = 0;
}

int angle_to_pulse(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle %d out of range [%d, %d]\n", angle, MIN_ANGLE, MAX_ANGLE);
        return -1;
    }
    return MIN_PULSE_WIDTH + (angle * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH)) / (MAX_ANGLE - MIN_ANGLE);
}

int set_servo_angle(int gpio, int angle) {
    int pulse = angle_to_pulse(angle);
    if (pulse < 0) return -1;
    if (gpioServo(gpio, pulse) != 0) {
        fprintf(stderr, "Error: gpioServo failed for GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(PAN_GPIO, PI_OUTPUT);
    gpioSetMode(TILT_GPIO, PI_OUTPUT);

    signal(SIGINT, handle_sigint);

    int pan_angle = NEUTRAL_ANGLE;
    int tilt_angle = NEUTRAL_ANGLE;

    while (keep_running) {
        printf("Enter command (W/A/S/D/Up/Down/Left/Right/q): ");
        fflush(stdout);

        char input[10];
        if (fgets(input, sizeof(input), stdin) == NULL) {
            break;
        }

        if (input[0] == 'q' || input[0] == 'Q') {
            set_servo_angle(PAN_GPIO, NEUTRAL_ANGLE);
            set_servo_angle(TILT_GPIO, NEUTRAL_ANGLE);
            printf("Servos set to neutral.\n");
            break;
        }

        int pan_change = 0, tilt_change = 0;
        if (input[0] == 'w' || input[0] == 'W') tilt_change = -STEP_SIZE;
        else if (input[0] == 's' || input[0] == 'S') tilt_change = STEP_SIZE;
        else if (input[0] == 'a' || input[0] == 'A') pan_change = -STEP_SIZE;
        else if (input[0] == 'd' || input[0] == 'D') pan_change = STEP_SIZE;
        else if (input[0] == 'u' || input[0] == 'U') tilt_change = STEP_SIZE;
        else if (input[0] == 'd' || input[0] == 'D') tilt_change = -STEP_SIZE;
        else if (input[0] == 'l' || input[0] == 'L') pan_change = -STEP_SIZE;
        else if (input[0] == 'r' || input[0] == 'R') pan_change = STEP_SIZE;

        if (pan_change != 0) {
            pan_angle += pan_change;
            if (pan_angle < MIN_ANGLE) pan_angle = MIN_ANGLE;
            if (pan_angle > MAX_ANGLE) pan_angle = MAX_ANGLE;
            if (set_servo_angle(PAN_GPIO, pan_angle) != 0) {
                fprintf(stderr, "Error: Failed to set pan servo\n");
            }
        }
        if (tilt_change != 0) {
            tilt_angle += tilt_change;
            if (tilt_angle < MIN_ANGLE) tilt_angle = MIN_ANGLE;
            if (tilt_angle > MAX_ANGLE) tilt_angle = MAX_ANGLE;
            if (set_servo_angle(TILT_GPIO, tilt_angle) != 0) {
                fprintf(stderr, "Error: Failed to set tilt servo\n");
            }
        }

        printf("Pan: %d, Tilt: %d\n", pan_angle, tilt_angle);
        usleep(DELAY_MS * 1000);
    }

    gpioServo(PAN_GPIO, 0);
    gpioServo(TILT_GPIO, 0);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

