#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLOW_SENSOR_GPIO 17
#define PULSES_PER_LITER 450.0
#define LCD_I2C_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_CHR 1
#define LCD_CMD 0
#define LCD_LINE_1 0x80
#define LCD_LINE_2 0xC0
#define E_DELAY_US 500
#define E_PULSE_US 500
#define I2C_BUS 1

static volatile sig_atomic_t running = 1;
static volatile uint32_t pulse_count = 0;
static double total_volume = 0.0;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void pulse_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    pulse_count++;
}

static void lcd_byte(int bits, int mode) {
    int high = mode | (bits & 0xF0) | 0x04;
    int low = mode | ((bits << 4) & 0xF0) | 0x04;
    gpioWrite(18, 0);
    gpioWrite(23, 0);
    gpioWrite(24, 0);
    gpioWrite(17, high);
    gpioDelay(E_DELAY_US);
    gpioWrite(17, 0);
    gpioDelay(E_PULSE_US);
    gpioWrite(17, high);
    gpioWrite(18, 1);
    gpioDelay(E_DELAY_US);
    gpioWrite(17, 0);
    gpioDelay(E_PULSE_US);
    gpioWrite(17, high);
    gpioWrite(23, 1);
    gpioDelay(E_DELAY_US);
    gpioWrite(17, 0);
    gpioDelay(E_PULSE_US);
    gpioWrite(17, high);
    gpioWrite(24, 1);
    gpioDelay(E_DELAY_US);
    gpioWrite(17, 0);
    gpioDelay(E_PULSE_US);
    gpioWrite(17, low);
    gpioDelay(E_DELAY_US);
    gpioWrite(17, 0);
    gpioDelay(E_PULSE_US);
    gpioWrite(17, low);
    gpioDelay(E_DELAY_US);
    gpioWrite(17, 0);
    gpioDelay(E_PULSE_US);
    gpioWrite(17, low);
    gpioWrite(18, 1);
    gpioDelay(E_DELAY_US);
    gpioWrite(17, 0);
    gpioDelay(E_PULSE_US);
    gpioWrite(17, low);
    gpioWrite(23, 1);
    gpioDelay(E_DELAY_US);
    gpioWrite(17, 0);
    gpioDelay(E_PULSE_US);
    gpioWrite(17, low);
    gpioWrite(24, 1);
    gpioDelay(E_DELAY_US);
    gpioWrite(17, 0);
    gpioDelay(E_PULSE_US);
}

static void lcd_init(void) {
    gpioSetMode(18, PI_OUTPUT);
    gpioSetMode(23, PI_OUTPUT);
    gpioSetMode(24, PI_OUTPUT);
    gpioSetMode(17, PI_OUTPUT);
    gpioWrite(18, 0);
    gpioWrite(23, 0);
    gpioWrite(24, 0);
    gpioWrite(17, 0);
    gpioDelay(50000);
    lcd_byte(0x33, LCD_CMD);
    gpioDelay(5000);
    lcd_byte(0x32, LCD_CMD);
    gpioDelay(5000);
    lcd_byte(0x28, LCD_CMD);
    gpioDelay(5000);
    lcd_byte(0x0C, LCD_CMD);
    gpioDelay(5000);
    lcd_byte(0x06, LCD_CMD);
    gpioDelay(5000);
    lcd_byte(0x01, LCD_CMD);
    gpioDelay(5000);
}

static void lcd_clear(void) {
    lcd_byte(0x01, LCD_CMD);
    gpioDelay(5000);
}

static void lcd_print(int line, const char *text) {
    if (i2c_handle >= 0) return;
    lcd_byte(line, LCD_CMD);
    for (int i = 0; text[i] != '\0' && i < LCD_WIDTH; i++) {
        lcd_byte(text[i], LCD_CHR);
    }
}

static void lcd_update(void) {
    char buffer[17];
    snprintf(buffer, sizeof(buffer), "Flow: %.2f L/min", pulse_count / PULSES_PER_LITER / 60.0);
    lcd_print(LCD_LINE_1, buffer);
    snprintf(buffer, sizeof(buffer), "Vol: %.2f L", total_volume);
    lcd_print(LCD_LINE_2, buffer);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP);
    if (gpioSetAlertFuncEx(FLOW_SENSOR_GPIO, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set alert function on GPIO %d.\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, LCD_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, LCD_I2C_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    lcd_init();
    lcd_clear();

    while (running) {
        sleep(1);
        if (!running) break;
        double flow_rate = pulse_count / PULSES_PER_LITER / 60.0;
        total_volume += flow_rate;
        pulse_count = 0;
        printf("Flow Rate: %.2f L/min, Total Volume: %.2f L\n", flow_rate, total_volume);
        lcd_update();
    }

    cleanup();
    return EXIT_SUCCESS;
}

