#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <string.h>
#include <errno.h>

#define FLOW_SENSOR_GPIO 17
#define I2C_BUS 1
#define I2C_ADDR 0x27
#define PULSES_PER_LITER 7.5
#define DISPLAY_WIDTH 16
#define DISPLAY_LINE1 0x80
#define DISPLAY_LINE2 0xC0
#define DISPLAY_CLEAR 0x01
#define DISPLAY_HOME 0x02
#define DISPLAY_BACKLIGHT 0x08
#define DISPLAY_ENABLE 0x0C
#define DISPLAY_4BIT 0xF0

static volatile sig_atomic_t running = 1;
static volatile int pulse_count = 0;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void pulse_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    (void)tick;
    if (level == 1) {
        pulse_count++;
    }
}

static int lcd_write_nibble(int handle, uint8_t nibble) {
    if (i2cWriteByteData(handle, nibble | DISPLAY_ENABLE | DISPLAY_BACKLIGHT, 0) < 0) {
        return -1;
    }
    gpioDelay(1000);
    if (i2cWriteByteData(handle, nibble | DISPLAY_ENABLE | DISPLAY_BACKLIGHT | DISPLAY_4BIT, 0) < 0) {
        return -1;
    }
    gpioDelay(1000);
    return 0;
}

static int lcd_send_command(int handle, uint8_t cmd) {
    if (lcd_write_nibble(handle, cmd & 0xF0) < 0) return -1;
    if (lcd_write_nibble(handle, (cmd << 4) & 0xF0) < 0) return -1;
    if (cmd == DISPLAY_CLEAR || cmd == DISPLAY_HOME) {
        gpioDelay(2000);
    }
    return 0;
}

static int lcd_send_data(int handle, uint8_t data) {
    if (lcd_write_nibble(handle, data & 0xF0) < 0) return -1;
    if (lcd_write_nibble(handle, (data << 4) & 0xF0) < 0) return -1;
    return 0;
}

static int lcd_init(int handle) {
    gpioDelay(50000);
    if (lcd_send_command(handle, DISPLAY_CLEAR) < 0) return -1;
    if (lcd_send_command(handle, DISPLAY_HOME) < 0) return -1;
    if (lcd_send_command(handle, 0x28) < 0) return -1;
    if (lcd_send_command(handle, 0x0C) < 0) return -1;
    if (lcd_send_command(handle, 0x06) < 0) return -1;
    if (lcd_send_command(handle, 0x01) < 0) return -1;
    gpioDelay(2000);
    return 0;
}

static int lcd_print_string(int handle, const char *str) {
    for (int i = 0; str[i] != '\0'; i++) {
        if (lcd_send_data(handle, (uint8_t)str[i]) < 0) return -1;
    }
    return 0;
}

static int lcd_set_cursor(int handle, int line) {
    uint8_t addr = (line == 0) ? DISPLAY_LINE1 : DISPLAY_LINE2;
    if (lcd_send_command(handle, addr) < 0) return -1;
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        lcd_send_command(i2c_handle, DISPLAY_CLEAR);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(FLOW_SENSOR_GPIO, pulse_callback) < 0) {
        fprintf(stderr, "Failed to set alert function on GPIO%d\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (lcd_init(i2c_handle) < 0) {
        fprintf(stderr, "LCD initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (lcd_set_cursor(i2c_handle, 0) < 0) {
        fprintf(stderr, "Failed to set cursor position\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (lcd_print_string(i2c_handle, "Flow Rate:") < 0) {
        fprintf(stderr, "Failed to print header\n");
        cleanup();
        return EXIT_FAILURE;
    }

    time_t last_pulse_time = time(NULL);
    int zero_pulse_count = 0;

    while (running) {
        time_t current_time = time(NULL);
        if (difftime(current_time, last_pulse_time) >= 1.0) {
            double flow_rate = (double)pulse_count / PULSES_PER_LITER * 60.0;
            char buffer[17];
            snprintf(buffer, sizeof(buffer), "%.2f L/min", flow_rate);

            if (lcd_set_cursor(i2c_handle, 1) < 0) {
                fprintf(stderr, "Failed to set cursor position\n");
                break;
            }
            if (lcd_print_string(i2c_handle, buffer) < 0) {
                fprintf(stderr, "Failed to print flow rate\n");
                break;
            }

            pulse_count = 0;
            last_pulse_time = current_time;
            zero_pulse_count = 0;
        } else {
            zero_pulse_count++;
            if (zero_pulse_count > 10) {
                fprintf(stderr, "Warning: No pulses detected for 10 seconds. Sensor may be absent or disconnected.\n");
                zero_pulse_count = 0;
            }
        }
        gpioDelay(100000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

