#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L3CX_ADDR 0x29

/* VL53L3CX ULD register addresses */
#define VL53L3CX_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L3CX_REG_SYSTEM_MODE_START_STOP 0x0000
#define VL53L3CX_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L3CX_REG_RESULT_DISTANCE 0x0096

#define EXPECTED_MODEL_ID 0xEA
#define MAX_TARGETS 4

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_reg16(uint8_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)value;
    return i2cWriteDevice(i2c_handle, buf, 2);
}

static int i2c_read_reg16(uint8_t reg, uint8_t *buf, uint32_t len) {
    char cmd[1] = {(char)reg};
    if (i2cWriteDevice(i2c_handle, cmd, 1) != 0) return -1;
    return i2cReadDevice(i2c_handle, (char *)buf, len);
}

static int vl53l3cx_init(void) {
    uint8_t model_id = 0;
    uint8_t status = 0;

    if (i2c_read_reg16(VL53L3CX_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) != 1) {
        fprintf(stderr, "Error: Failed to read model ID from sensor.\n");
        return -1;
    }

    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "Error: Invalid model ID 0x%02X (expected 0x%02X). Sensor not present?\n",
                model_id, EXPECTED_MODEL_ID);
        return -1;
    }

    printf("VL53L3CX detected (Model ID: 0x%02X)\n", model_id);

    /* Stubbed proprietary initialization sequence.
     * In a real implementation, this would download and execute the ST ULD firmware
     * via I2C, configure the sensor, and start ranging. */
    printf("Stubbed initialization: setting mode to Ranging.\n");
    if (i2c_write_reg16(VL53L3CX_REG_SYSTEM_MODE_START_STOP, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to set sensor mode.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    return 0;
}

static int vl53l3cx_read_distance(uint8_t *distances, int max_targets) {
    uint8_t status = 0;
    uint8_t data[2 * MAX_TARGETS];

    if (i2c_read_reg16(VL53L3CX_REG_RESULT_RANGE_STATUS, &status, 1) != 1) {
        fprintf(stderr, "Error: Failed to read range status.\n");
        return -1;
    }

    if ((status & 0x07) == 0) {
        return 0; /* No new data available */
    }

    if (i2c_read_reg16(VL53L3CX_REG_RESULT_DISTANCE, data, 2 * MAX_TARGETS) != (int)(2 * MAX_TARGETS)) {
        fprintf(stderr, "Error: Failed to read distance data.\n");
        return -1;
    }

    for (int i = 0; i < max_targets; i++) {
        distances[i] = (data[2 * i] << 8) | data[2 * i + 1];
    }

    return 1;
}

static void log_data(const uint8_t *distances, int num_targets) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    printf("%s - Targets: %d", timestamp, num_targets);
    for (int i = 0; i < num_targets; i++) {
        printf(" | Target %d: %u mm", i, distances[i]);
    }
    printf("\n");
    fflush(stdout);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L3CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X on bus %d.\n", VL53L3CX_ADDR, I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l3cx_init() != 0) {
        fprintf(stderr, "Error: VL53L3CX initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint8_t distances[MAX_TARGETS];
    int num_targets;

    while (!terminate) {
        int ret = vl53l3cx_read_distance(distances, MAX_TARGETS);
        if (ret < 0) {
            fprintf(stderr, "Error: Failed to read distance data.\n");
        } else if (ret > 0) {
            num_targets = 0;
            for (int i = 0; i < MAX_TARGETS; i++) {
                if (distances[i] > 0) {
                    num_targets++;
                }
            }
            log_data(distances, num_targets);
        }
        gpioDelay(100000); /* 100 ms */
    }

    printf("\nShutting down...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

