#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define SENSOR_PIN  4
#define LED_PIN     17
#define LOG_FILE    "proximity.log"
#define POLL_MS     100
#define BLINK_MS    100

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(void) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (gmtime_r(&t, &tm) == NULL) {
        perror("gmtime_r");
        fclose(fp);
        return -1;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }
    if (fprintf(fp, "%s Object detected\n", ts) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction SIGINT");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction SIGTERM");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    struct gpiod_line *sensor = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor) {
        perror("gpiod_chip_get_line sensor");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct gpiod_line *led = gpiod_chip_get_line(chip, LED_PIN);
    if (!led) {
        perror("gpiod_chip_get_line led");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(sensor, "e18-d50nk") < 0) {
        perror("gpiod_line_request_input sensor");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led, "e18-d50nk-led", 0) < 0) {
        perror("gpiod_line_request_output led");
        gpiod_line_release(sensor);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int prev = 1;  /* assume no object at startup (HIGH) */
    int first_read = 1;

    while (running) {
        int val = gpiod_line_get_value(sensor);
        if (val < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        if (val == 0 && (first_read || prev == 1)) {
            /* Falling edge: object just entered range */
            if (log_event() == 0) {
                printf("Object detected, logged.\n");
            } else {
                fprintf(stderr, "Failed to log event.\n");
            }
            /* Blink LED */
            if (gpiod_line_set_value(led, 1) < 0) {
                perror("gpiod_line_set_value led ON");
                break;
            }
            usleep(BLINK_MS * 1000);
            if (gpiod_line_set_value(led, 0) < 0) {
                perror("gpiod_line_set_value led OFF");
                break;
            }
            usleep(BLINK_MS * 1000);
        }

        prev = val;
        first_read = 0;
        usleep(POLL_MS * 1000);
    }

    gpiod_line_set_value(led, 0);
    gpiod_line_release(sensor);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

