#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SI1145_ADDR 0x60
#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_MEAS_RATE0 0x08
#define SI1145_REG_MEAS_RATE1 0x09
#define SI1145_REG_PS_RATE0 0x0A
#define SI1145_REG_PS_RATE1 0x0B
#define SI1145_REG_ALS_RATE0 0x0C
#define SI1145_REG_ALS_RATE1 0x0D
#define SI1145_REG_PS1_DATA0 0x18
#define SI1145_REG_PS1_DATA1 0x19
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_COMMAND 0x30
#define SI1145_REG_CH_LIST 0x4F
#define SI1145_PART_ID 0x45
#define SI1145_HW_KEY_VAL 0x17
#define SI1145_CMD_ALS_FORCE 0x06
#define SI1145_CMD_PS_FORCE 0x07

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed: reg=0x%02X val=0x%02X rc=%d\n", reg, val, rc);
    }
    return rc;
}

static int read_reg(uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed: reg=0x%02X rc=%d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int init_si1145(void) {
    uint8_t part_id = 0;
    if (read_reg(SI1145_REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Cannot read PART_ID - sensor absent or bus error\n");
        return -1;
    }
    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n", part_id, SI1145_PART_ID);
        return -1;
    }

    if (write_reg(SI1145_REG_HW_KEY, SI1145_HW_KEY_VAL) < 0) return -1;
    if (write_reg(SI1145_REG_CH_LIST, 0x01) < 0) return -1;
    if (write_reg(SI1145_REG_MEAS_RATE0, 0x00) < 0) return -1;
    if (write_reg(SI1145_REG_MEAS_RATE1, 0x00) < 0) return -1;
    if (write_reg(SI1145_REG_PS_RATE0, 0x00) < 0) return -1;
    if (write_reg(SI1145_REG_PS_RATE1, 0x00) < 0) return -1;
    if (write_reg(SI1145_REG_ALS_RATE0, 0x00) < 0) return -1;
    if (write_reg(SI1145_REG_ALS_RATE1, 0x00) < 0) return -1;

    return 0;
}

static int read_proximity(uint16_t *prox) {
    uint8_t lo = 0, hi = 0;
    if (read_reg(SI1145_REG_PS1_DATA0, &lo) < 0) return -1;
    if (read_reg(SI1145_REG_PS1_DATA1, &hi) < 0) return -1;
    *prox = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int read_ambient_light(uint16_t *als) {
    uint8_t lo = 0, hi = 0;
    if (read_reg(SI1145_REG_ALS_VIS_DATA0, &lo) < 0) return -1;
    if (read_reg(SI1145_REG_ALS_VIS_DATA1, &hi) < 0) return -1;
    *als = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int log_data(uint16_t prox, uint16_t als) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "localtime failed: %s\n", strerror(errno));
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%u,%u\n", timestamp, prox, als) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_si1145() < 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("biometric_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si1145 logging started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        uint16_t prox = 0, als = 0;

        if (write_reg(SI1145_REG_COMMAND, SI1145_CMD_ALS_FORCE) < 0) {
            fprintf(stderr, "ALS_FORCE failed\n");
            break;
        }
        if (write_reg(SI1145_REG_COMMAND, SI1145_CMD_PS_FORCE) < 0) {
            fprintf(stderr, "PS_FORCE failed\n");
            break;
        }

        gpioDelay(10000);

        if (read_proximity(&prox) < 0) {
            fprintf(stderr, "Proximity read failed\n");
            break;
        }
        if (read_ambient_light(&als) < 0) {
            fprintf(stderr, "Ambient light read failed\n");
            break;
        }

        if (log_data(prox, als) < 0) {
            fprintf(stderr, "Logging failed\n");
            break;
        }

        printf("Proximity: %u, Ambient Light: %u\n", prox, als);
        gpioDelay(1000000);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

