#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define SPEED_OF_SOUND 34300.0
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define WATERING_THRESHOLD 15.0
#define LOG_FILE "distance_log.txt"
#define POLL_INTERVAL 60
#define TIMEOUT_NS 30000000L  /* 30 ms */
#define TRIGGER_PULSE_US 10
#define CONSUMER "plant-watering"

static volatile sig_atomic_t program_running = 1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_message(const char *msg) {
    if (!log_fp) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(log_fp, "%s %s\n", ts, msg);
    fflush(log_fp);
}

static int trigger_sensor(struct gpiod_line *trig) {
    if (gpiod_line_set_value(trig, 1) < 0) {
        log_message("ERROR: trigger high failed");
        return -1;
    }
    usleep(TRIGGER_PULSE_US);
    if (gpiod_line_set_value(trig, 0) < 0) {
        log_message("ERROR: trigger low failed");
        return -1;
    }
    return 0;
}

static float measure_distance(struct gpiod_line *trig, struct gpiod_line *echo) {
    struct timespec t0, t1, now;
    int val;
    long elapsed_ns;

    if (trigger_sensor(trig) < 0) return -1.0;

    /* Wait for echo rising edge (timeout) */
    clock_gettime(CLOCK_MONOTONIC, &t0);
    do {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            log_message("ERROR: echo read failed");
            return -1.0;
        }
        clock_gettime(CLOCK_MONOTONIC, &now);
        elapsed_ns = (now.tv_sec - t0.tv_sec) * 1000000000L + (now.tv_nsec - t0.tv_nsec);
        if (elapsed_ns > TIMEOUT_NS) {
            log_message("ERROR: echo rising-edge timeout (sensor absent?)");
            return -1.0;
        }
    } while (val == 0);

    /* Measure echo high duration (timeout) */
    clock_gettime(CLOCK_MONOTONIC, &t0);
    do {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            log_message("ERROR: echo read failed");
            return -1.0;
        }
        clock_gettime(CLOCK_MONOTONIC, &now);
        elapsed_ns = (now.tv_sec - t0.tv_sec) * 1000000000L + (now.tv_nsec - t0.tv_nsec);
        if (elapsed_ns > TIMEOUT_NS) {
            log_message("ERROR: echo high timeout (stuck high?)");
            return -1.0;
        }
    } while (val == 1);

    clock_gettime(CLOCK_MONOTONIC, &t1);
    float pulse_s = (t1.tv_sec - t0.tv_sec) + (t1.tv_nsec - t0.tv_nsec) / 1e9;
    float distance = (pulse_s * SPEED_OF_SOUND) / 2.0;

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        log_message("ERROR: distance out of range");
        return -1.0;
    }
    return distance;
}

static void check_watering(float distance) {
    if (distance < WATERING_THRESHOLD) {
        log_message("Time to water the plant!");
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL;
    int ret = EXIT_FAILURE;

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_message("ERROR: gpiod_chip_open failed");
        goto cleanup;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        log_message("ERROR: gpiod_chip_get_line failed");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, CONSUMER, 0) < 0) {
        log_message("ERROR: request trigger output failed");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, CONSUMER) < 0) {
        log_message("ERROR: request echo input failed");
        goto cleanup;
    }

    log_message("Plant watering system started");

    while (program_running) {
        float dist = measure_distance(trig, echo);
        if (dist >= 0.0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Distance: %.2f cm", dist);
            log_message(msg);
            check_watering(dist);
        }
        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL && program_running; i++) {
            sleep(1);
        }
    }

    log_message("Plant watering system stopped");
    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    if (log_fp) fclose(log_fp);
    return ret;
}

