#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define APDS9960_I2C_ADDR 0x39

#define APDS9960_ENABLE 0x80
#define APDS9960_ATIME 0x81
#define APDS9960_WTIME 0x83
#define APDS9960_PPULSE 0x8E
#define APDS9960_CONTROL 0xF1
#define APDS9960_CONFIG2 0x90
#define APDS9960_ID 0x92
#define APDS9960_STATUS 0x93
#define APDS9960_CDATAL 0x96
#define APDS9960_CDATAH 0x97
#define APDS9960_RDATAL 0x98
#define APDS9960_RDATAH 0x99
#define APDS9960_GDATAL 0x9A
#define APDS9960_GDATAH 0x9B
#define APDS9960_PDATAL 0x9C
#define APDS9960_PDATAH 0x9D

#define APDS9960_ID_VALUE 0xAB
#define PROXIMITY_THRESHOLD 200
#define LOG_FILE "color_proximity_log.csv"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to reg 0x%02X (rc=%d)\n", value, reg, rc);
    }
    return rc;
}

static int i2c_read_byte(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X (rc=%d)\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int i2c_read_word(int handle, uint8_t reg, uint16_t *value) {
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading word reg 0x%02X (rc=%d)\n", reg, rc);
        return -1;
    }
    *value = (uint16_t)rc;
    return 0;
}

static int apds9960_init(int handle) {
    uint8_t id = 0;
    if (i2c_read_byte(handle, APDS9960_ID, &id) < 0) return -1;
    if (id != APDS9960_ID_VALUE) {
        fprintf(stderr, "Unexpected ID 0x%02X (expected 0x%02X)\n", id, APDS9960_ID_VALUE);
        return -1;
    }

    if (i2c_write_byte(handle, APDS9960_ENABLE, 0x03) < 0) return -1;
    if (i2c_write_byte(handle, APDS9960_ATIME, 0xDB) < 0) return -1;
    if (i2c_write_byte(handle, APDS9960_WTIME, 0xF6) < 0) return -1;
    if (i2c_write_byte(handle, APDS9960_PPULSE, 0x87) < 0) return -1;
    if (i2c_write_byte(handle, APDS9960_CONTROL, 0x03) < 0) return -1;
    if (i2c_write_byte(handle, APDS9960_CONFIG2, 0x01) < 0) return -1;

    return 0;
}

static int read_color_data(int handle, uint16_t *red, uint16_t *green, uint16_t *blue) {
    if (i2c_read_word(handle, APDS9960_RDATAL, red) < 0) return -1;
    if (i2c_read_word(handle, APDS9960_GDATAL, green) < 0) return -1;
    if (i2c_read_word(handle, APDS9960_BDATAL, blue) < 0) return -1;
    return 0;
}

static int read_proximity_data(int handle, uint8_t *proximity) {
    return i2c_read_byte(handle, APDS9960_PDATAL, proximity);
}

static void log_data(FILE *fp, uint16_t red, uint16_t green, uint16_t blue, uint8_t proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%u,%u,%u,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            red, green, blue, proximity);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, APDS9960_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n", I2C_BUS, APDS9960_I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (apds9960_init(i2c_handle) < 0) {
        fprintf(stderr, "APDS9960 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Red,Green,Blue,Proximity\n");
        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint16_t red = 0, green = 0, blue = 0;
    uint8_t proximity = 0;

