#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1182_ADDR    0x5A
#define SI1182_PART_ID 0x00
#define SI1182_CMD     0x47
#define SI1182_MEAS_RATE0 0x08
#define SI1182_PS_DATA0  0x24
#define SI1182_PS_DATA1  0x25

#define EXPECTED_PART_ID 0x82
#define SAMPLE_PERIOD_MS 100
#define CSV_FILENAME     "heartrate.csv"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (i2c_smbus_write_byte(fd, reg) < 0) return -1;
    int v = i2c_smbus_read_byte(fd);
    if (v < 0) return -1;
    *val = (uint8_t)v;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    return i2c_smbus_write_byte_data(fd, reg, val);
}

static int read_si1182_part_id(int fd, uint8_t *id) {
    if (i2c_read_reg8(fd, SI1182_PART_ID, id) < 0) {
        fprintf(stderr, "Error reading PART_ID: %s\n", strerror(errno));
        return -1;
    }
    if (*id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n", *id, EXPECTED_PART_ID);
        return -1;
    }
    return 0;
}

static int init_si1182(int fd) {
    uint8_t part_id;
    if (read_si1182_part_id(fd, &part_id) < 0) return -1;
    printf("Si1182 PART_ID: 0x%02X\n", part_id);

    if (i2c_write_reg8(fd, SI1182_MEAS_RATE0, 0x0A) < 0) {
        fprintf(stderr, "Error writing MEAS_RATE0: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_write_reg8(fd, SI1182_CMD, 0x01) < 0) {
        fprintf(stderr, "Error writing COMMAND: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_proximity(int fd, uint16_t *prox) {
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, SI1182_PS_DATA0, &lo) < 0) return -1;
    if (i2c_read_reg8(fd, SI1182_PS_DATA1, &hi) < 0) return -1;
    *prox = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int log_bpm(FILE *fp, int bpm) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return -1;
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    if (fprintf(fp, "%s,%d\n", ts, bpm) < 0) return -1;
    fflush(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", SI1182_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (init_si1182(fd) < 0) {
        fprintf(stderr, "Si1182 initialization failed.\n");
        close(fd);
        return 1;
    }

    FILE *fp = fopen(CSV_FILENAME, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", CSV_FILENAME, strerror(errno));
        close(fd);
        return 1;
    }

    printf("Logging heart rate to %s. Press Ctrl+C to stop.\n", CSV_FILENAME);

    while (running) {
        uint16_t prox;
        if (read_proximity(fd, &prox) < 0) {
            fprintf(stderr, "Warning: I2C read error: %s\n", strerror(errno));
            usleep(SAMPLE_PERIOD_MS * 1000);
            continue;
        }

        int bpm = 60 + (prox * 10) / 1000;
        if (log_bpm(fp, bpm) < 0) {
            fprintf(stderr, "Warning: CSV write error: %s\n", strerror(errno));
        }
        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    printf("\nShutting down cleanly.\n");
    fclose(fp);
    close(fd);
    return 0;
}

