#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VL53L0X_ADDR             0x29
#define GPIO_PIN                 17
#define I2C_BUS                  1
#define LOG_FILE                 "distance_log.txt"
#define MEASUREMENT_TIMEOUT_MS   100
#define POLL_TIMEOUT_MS          50

/* VL53L0X register addresses */
#define REG_SYSRANGE_START       0x00
#define REG_SYSTEM_INTERRUPT_CLEAR 0x0B
#define REG_RESULT_INTERRUPT_STATUS 0x13
#define REG_RESULT_RANGE_STATUS   0x14
#define REG_IDENTIFICATION_MODEL_ID 0x010F
#define REG_IDENTIFICATION_REVISION_ID 0x0110

#define EXPECTED_MODEL_ID        0xEA
#define EXPECTED_REVISION_ID     0x00

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Low-level I2C helpers                                               */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error: i2cWriteDevice failed for reg 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(handle, reg_buf, 1) != 1) {
        fprintf(stderr, "Error: i2cWriteDevice (reg select) failed for reg 0x%02X\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len) {
        fprintf(stderr, "Error: i2cReadDevice failed for reg 0x%02X (%u bytes)\n", reg, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int init_vl53l0x(int handle)
{
    uint8_t model_id = 0, revision_id = 0;
    uint8_t buf[2];

    /* Verify sensor presence by reading MODEL_ID */
    if (i2c_read_block(handle, REG_IDENTIFICATION_MODEL_ID, buf, 2) != 0)
        return -1;
    model_id = buf[0];

    /* Read REVISION_ID */
    if (i2c_read_block(handle, REG_IDENTIFICATION_REVISION_ID, buf, 2) != 0)
        return -1;
    revision_id = buf[0];

    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "Error: Unexpected MODEL_ID 0x%02X (expected 0x%02X)\n",
                model_id, EXPECTED_MODEL_ID);
        return -1;
    }
    if (revision_id != EXPECTED_REVISION_ID) {
        fprintf(stderr, "Warning: Unexpected REVISION_ID 0x%02X (expected 0x%02X)\n",
                revision_id, EXPECTED_REVISION_ID);
    }

    /* Clear any pending interrupt */
    if (i2c_write_byte(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Single-shot measurement                                            */
/* ------------------------------------------------------------------ */
static int read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status = 0;
    uint8_t data[14];
    uint32_t elapsed = 0;

    /* Start a single measurement */
    if (i2c_write_byte(handle, REG_SYSRANGE_START, 0x01) != 0)
        return -1;

    /* Poll RESULT_INTERRUPT_STATUS bit 0 until data ready */
    do {
        if (i2c_read_block(handle, REG_RESULT_INTERRUPT_STATUS, &status, 1) != 0)
            return -1;
        if (status & 0x01)
            break;
        gpioDelay(1000); /* 1 ms */
        elapsed++;
    } while (elapsed < MEASUREMENT_TIMEOUT_MS);

    if (!(status & 0x01)) {
        fprintf(stderr, "Error: Measurement timeout (%u ms)\n", MEASUREMENT_TIMEOUT_MS);
        return -1;
    }

    /* Read 14-byte result block: 2 bytes each for distance, peak, SD, ... */
    if (i2c_read_block(handle, REG_RESULT_RANGE_STATUS, data, 14) != 0)
        return -1;

    /* Distance is 16-bit, big-endian, bytes 10-11 */
    *distance_mm = ((uint16_t)data[10] << 8) | data[11];

    /* Clear the interrupt so the next measurement can be triggered */
    if (i2c_write_byte(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_distance(FILE *fp, uint16_t distance_mm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(fp, "%s,%u\n", timestamp, distance_mm);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
