                }
            } else {
                fprintf(stderr, "Warning: failed to generate timestamp\n");
            }
        } else {
            fprintf(stderr, "Warning: I2C read failed, skipping sample\n");
        }

        /* Sleep for the remainder of the 200 ms sample interval. */
        gpioDelay(SAMPLE_US);
    }

    /* Graceful cleanup. */
    printf("\nShutting down...\n");
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

