#define SI1182_ADDR 0x60
#define PROXIMITY_DATA_REG 0x18
#define AMBIENT_LIGHT_REG 0x16
#define LOG_FILE "biometric_log.txt"
#define MAX_RETRIES 3

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static int read_register(int handle, uint8_t reg, uint16_t *value) {
    int result;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        result = i2cReadWordData(handle, reg);
        if (result >= 0) {
            *value = (uint16_t)result;
            return 0;
        }
        retries++;
        if (retries < MAX_RETRIES) {
            gpioDelay(10000);
        }
    }
    return -1;
}

static int log_data(FILE *file, uint16_t proximity, uint16_t ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

