    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(file, "%s, Proximity: %u, Ambient Light: %u\n", timestamp, proximity, ambient_light) < 0) {
        return -1;
    }
    fflush(file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    uint16_t proximity_data, ambient_light_data;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %d\n", SI1182_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        if (read_register(i2c_handle, PROXIMITY_DATA_REG, &proximity_data) != 0) {
            fprintf(stderr, "Failed to read proximity data after %d retries\n", MAX_RETRIES);
        } else if (read_register(i2c_handle, AMBIENT_LIGHT_REG, &ambient_light_data) != 0) {
            fprintf(stderr, "Failed to read ambient light data after %d retries\n", MAX_RETRIES);
        } else {
            if (log_data(log_file, proximity_data, ambient_light_data) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        }
        gpioDelay(500000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

