            tm.tm_hour, tm.tm_min, tm.tm_sec, distance);
    fclose(fp);
}

static void control_led(uint16_t distance, int threshold) {
    if (distance < threshold) {
        gpioWrite(LED_GPIO, 1);
    } else {
        gpioWrite(LED_GPIO, 0);
    }
}

int main(int argc, char *argv[]) {
    int threshold = 100;
    if (argc > 1) {
        threshold = atoi(argv[1]);
        if (threshold <= 0) {
            fprintf(stderr, "Invalid threshold value. Using default (100 mm).\n");
            threshold = 100;
        }
    }
    printf("Using threshold: %d mm\n", threshold);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t who_am_i = 0;
    if (read_register(i2c_handle, WHO_AM_I_REG, &who_am_i) != 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "Sensor not detected. WHO_AM_I = 0x%02X (expected 0x%02X)\n", who_am_i, WHO_AM_I_VAL);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting distance measurements. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t distance = 0;
        if (read_distance(i2c_handle, &distance) == 0) {
            log_data(distance);
            control_led(distance, threshold);
            printf("Distance: %u mm\n", distance);
        } else {
            fprintf(stderr, "Error reading distance\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nCleaning up...\n");
    gpioWrite(LED_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

