#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDRESS 0x50
#define LOG_FILE "intrusion_log.txt"
#define DISTANCE_THRESHOLD 1000
#define SAMPLE_COUNT 10
#define SAMPLE_DELAY_MS 100
#define MEASUREMENT_DELAY_MS 10
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, const uint8_t *cmd, size_t len) {
    if (write(fd, cmd, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_distance(int fd, uint16_t *distance_mm) {
    uint8_t cmd[4] = {0x50, 0x0A, 0x00, 0x01};
    uint8_t resp[15];

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_write_cmd(fd, cmd, sizeof(cmd)) != 0) {
            usleep(10000);
            continue;
        }
        usleep(MEASUREMENT_DELAY_MS * 1000);

        if (i2c_read_data(fd, resp, sizeof(resp)) != 0) {
            usleep(10000);
            continue;
        }

        if (resp[0] != 0x50) {
            fprintf(stderr, "Invalid response header: 0x%02X\n", resp[0]);
            usleep(10000);
            continue;
        }

        *distance_mm = ((uint16_t)resp[11] << 8) | resp[12];
        return 0;
    }

    fprintf(stderr, "Failed to read distance after %d attempts\n", MAX_RETRIES);
    return -1;
}

static void log_intrusion(uint16_t distance_mm) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_fp) {
        fprintf(log_fp, "%s - Intrusion detected! Distance: %u mm\n", timestamp, distance_mm);
        fflush(log_fp);
    } else {
        fprintf(stderr, "Log file not open.\n");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SENSOR_ADDRESS, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    printf("Intrusion detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t total_distance = 0;
        int valid_samples = 0;

        for (int i = 0; i < SAMPLE_COUNT; i++) {
            uint16_t distance;
            if (read_distance(i2c_fd, &distance) == 0) {
                total_distance += distance;
                valid_samples++;
            }
            usleep(SAMPLE_DELAY_MS * 1000);
        }

        if (valid_samples > 0) {
            uint16_t avg_distance = total_distance / valid_samples;
            if (avg_distance < DISTANCE_THRESHOLD) {
                log_intrusion(avg_distance);
            }
        }

        usleep(SAMPLE_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    if (log_fp) {
        fclose(log_fp);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return 0;
}

