#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L0X_ADDR   0x29
#define POLL_TIMEOUT_MS 100
#define SAMPLE_PERIOD_US 500000

/* VL53L0X register addresses */
#define REG_SYSRANGE_START          0x00
#define REG_SYSTEM_INTERRUPT_CLEAR  0x0B
#define REG_RESULT_INTERRUPT_STATUS 0x13
#define REG_RESULT_RANGE_STATUS     0x14
#define REG_IDENTIFICATION_MODEL_ID 0xC0

#define EXPECTED_MODEL_ID 0xEE

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write one byte to a register; returns 0 on success, -1 on error. */
static int vl53l0x_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read one byte from a register; returns 0 on success, -1 on error. */
static int vl53l0x_read_byte(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* Read a 16-bit little-endian value from two consecutive registers. */
static int vl53l0x_read_word(int handle, uint8_t reg, uint16_t *out)
{
    uint8_t lo, hi;
    if (vl53l0x_read_byte(handle, reg, &lo) < 0) return -1;
    if (vl53l0x_read_byte(handle, (uint8_t)(reg + 1), &hi) < 0) return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int vl53l0x_init(int handle)
{
    uint8_t model_id = 0;
    if (vl53l0x_read_byte(handle, REG_IDENTIFICATION_MODEL_ID, &model_id) < 0)
        return -1;
    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "Unexpected model ID 0x%02X (expected 0x%02X) - wrong sensor?\n",
                model_id, EXPECTED_MODEL_ID);
        return -1;
    }
    printf("VL53L0X detected (model ID 0x%02X)\n", model_id);
    return 0;
}

static int vl53l0x_read_distance(int handle, uint16_t *distance_mm)
{
    /* Start a single-shot measurement */
    if (vl53l0x_write_byte(handle, REG_SYSRANGE_START, 0x01) < 0)
        return -1;

    /* Poll RESULT_INTERRUPT_STATUS until bit 0 is set (data ready) */
    uint8_t status = 0;
    for (int i = 0; i < POLL_TIMEOUT_MS; i++) {
        if (vl53l0x_read_byte(handle, REG_RESULT_INTERRUPT_STATUS, &status) < 0)
            return -1;
        if (status & 0x01)
            break;
        gpioDelay(1000); /* 1 ms */
    }
    if (!(status & 0x01)) {
        fprintf(stderr, "Timeout waiting for VL53L0X measurement\n");
        return -1;
    }

    /* Read 16-bit distance (little-endian) */
    if (vl53l0x_read_word(handle, REG_RESULT_RANGE_STATUS, distance_mm) < 0)
        return -1;

    /* Clear the interrupt so the next measurement can signal */
    if (vl53l0x_write_byte(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0)
        return -1;

    return 0;
}

static void print_timestamp(void)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char buf[32];
    localtime_r(&now, &tm_info);
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info);
    printf("%s ", buf);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus %d, addr 0x%02X): %s\n",
                I2C_BUS, VL53L0X_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (vl53l0x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "VL53L0X initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Starting VL53L0X distance readings (Ctrl+C to stop)...\n");

    while (g_running) {
        uint16_t distance = 0;
        if (vl53l0x_read_distance(g_i2c_handle, &distance) == 0) {
            print_timestamp();
            printf("Distance: %u mm\n", distance);
            fflush(stdout);
        } else {
            fprintf(stderr, "Warning: distance read failed, retrying...\n");
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return 0;
}

