#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX75030_ADDR  0x4C
#define DIST_REG       0x00
#define SCALE_FACTOR   0.125f   /* mm per count */
#define POLL_MS        500

static volatile sig_atomic_t g_running = 1;

static void sighandler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    uint8_t buf[2];
    ssize_t n;

    buf[0] = reg;
    n = write(fd, buf, 1);
    if (n < 0) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) short write: %zd bytes\n",
                reg, n);
        return -1;
    }

    n = read(fd, buf, 2);
    if (n < 0) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (n != 2) {
        fprintf(stderr, "I2C read (reg 0x%02X) short read: %zd bytes\n",
                reg, n);
        return -1;
    }

    *out = (int16_t)((uint16_t)buf[0] | ((uint16_t)buf[1] << 8));
    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    if (install_signal_handlers() < 0)
        return EXIT_FAILURE;

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MLX75030_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                MLX75030_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Probe: try a register read to confirm the sensor is present. */
    int16_t probe;
    if (i2c_read_reg16(fd, DIST_REG, &probe) < 0) {
        fprintf(stderr, "MLX75030 not responding at 0x%02X — check wiring and "
                        "that the sensor is connected.\n", MLX75030_ADDR);
        goto cleanup;
    }

    struct timespec ts = { 0, POLL_MS * 1000000L };
    while (g_running) {
        int16_t raw;
        if (i2c_read_reg16(fd, DIST_REG, &raw) < 0) {
            fprintf(stderr, "Read error — will retry next cycle.\n");
        } else {
            float distance_mm = (float)raw * SCALE_FACTOR;
            printf("Distance: %.2f mm\n", distance_mm);
            fflush(stdout);
        }
        nanosleep(&ts, NULL);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);
    return rc;
}

