#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define OPT3101_ADDR 0x44
#define I2C_BUS 1

// OPT3101 Register Addresses (from datasheet)
#define REG_DEVICE_ID 0x00
#define REG_RESULT_STATUS 0x01
#define REG_RESULT_DISTANCE_CH0 0x02
#define REG_RESULT_AMBIENT_LIGHT 0x04
#define REG_COMMAND 0x08
#define REG_MODE 0x09
#define REG_RANGE_CONFIG 0x0A
#define REG_INT_CONFIG 0x0B

#define EXPECTED_DEVICE_ID 0x3101

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

int opt3101_write_reg(uint8_t reg, uint16_t value) {
    char buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    return i2cWriteDevice(i2c_handle, buf, 3);
}

int opt3101_read_reg(uint8_t reg, uint16_t *value) {
    char buf[2];
    if (i2cWriteDevice(i2c_handle, (char *)&reg, 1) != 0) {
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        return -1;
    }
    *value = ((uint16_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

int opt3101_init() {
    uint16_t device_id;
    if (opt3101_read_reg(REG_DEVICE_ID, &device_id) != 0) {
        fprintf(stderr, "Error: Failed to read Device ID (sensor absent or bus error)\n");
        return -1;
    }
    if (device_id != EXPECTED_DEVICE_ID) {
        fprintf(stderr, "Error: Incorrect Device ID: 0x%04X (expected 0x%04X)\n", device_id, EXPECTED_DEVICE_ID);
        return -1;
    }
    printf("OPT3101 detected (Device ID: 0x%04X)\n", device_id);

    // Reset the device
    if (opt3101_write_reg(REG_COMMAND, 0x0001) != 0) {
        fprintf(stderr, "Error: Failed to reset device\n");
        return -1;
    }
    gpioDelay(10000); // 10ms delay for reset

    // Configure mode: Start measurement
    if (opt3101_write_reg(REG_MODE, 0x0001) != 0) {
        fprintf(stderr, "Error: Failed to set mode\n");
        return -1;
    }

    // Configure range: 1 meter
    if (opt3101_write_reg(REG_RANGE_CONFIG, 0x0001) != 0) {
        fprintf(stderr, "Error: Failed to set range config\n");
        return -1;
    }

    // Configure interrupt: Disable interrupts
    if (opt3101_write_reg(REG_INT_CONFIG, 0x0000) != 0) {
        fprintf(stderr, "Error: Failed to set interrupt config\n");
        return -1;
    }

    return 0;
}

int opt3101_read_data(uint16_t *distance, uint16_t *ambient_light, uint16_t *error_flags) {
    uint16_t dist, ambient, status;

    if (opt3101_read_reg(REG_RESULT_DISTANCE_CH0, &dist) != 0) {
        fprintf(stderr, "Error: Failed to read distance\n");
        *error_flags |= (1 << 0);
        return -1;
    }

    if (opt3101_read_reg(REG_RESULT_AMBIENT_LIGHT, &ambient) != 0) {
        fprintf(stderr, "Error: Failed to read ambient light\n");
        *error_flags |= (1 << 1);
        return -1;
    }

    if (opt3101_read_reg(REG_RESULT_STATUS, &status) != 0) {
        fprintf(stderr, "Error: Failed to read status\n");
        *error_flags |= (1 << 2);
        return -1;
    }

    *distance = dist;
    *ambient_light = ambient;
    *error_flags = status & 0x07; // Only mask the first 3 error flags
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, OPT3101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (opt3101_init() != 0) {
        fprintf(stderr, "Error: OPT3101 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    uint16_t distance, ambient_light, error_flags;
    while (!terminate) {
        if (opt3101_read_data(&distance, &ambient_light, &error_flags) == 0) {
            printf("Distance: %u, Ambient Light: %u, Error Flags: 0x%02X\n", distance, ambient_light, error_flags);
        } else {
            fprintf(stderr, "Error: Failed to read data\n");
        }
        gpioDelay(500000); // 500ms delay
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return 0;
}

