    if (opt3101_write_reg(REG_INT_CONFIG, 0x0000) != 0) {
        fprintf(stderr, "Error: Failed to set interrupt config\n");
        return -1;
    }

    return 0;
}

int opt3101_read_data(uint16_t *distance, uint16_t *ambient_light, uint16_t *error_flags) {
    uint16_t dist, ambient, status;

    if (opt3101_read_reg(REG_RESULT_DISTANCE_CH0, &dist) != 0) {
        fprintf(stderr, "Error: Failed to read distance\n");
        *error_flags |= (1 << 0);
        return -1;
    }

    if (opt3101_read_reg(REG_RESULT_AMBIENT_LIGHT, &ambient) != 0) {
        fprintf(stderr, "Error: Failed to read ambient light\n");
        *error_flags |= (1 << 1);
        return -1;
    }

    if (opt3101_read_reg(REG_RESULT_STATUS, &status) != 0) {
        fprintf(stderr, "Error: Failed to read status\n");
        *error_flags |= (1 << 2);
        return -1;
    }

    *distance = dist;
    *ambient_light = ambient;
    *error_flags = status & 0x07; // Only mask the first 3 error flags
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, OPT3101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (opt3101_init() != 0) {
        fprintf(stderr, "Error: OPT3101 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    uint16_t distance, ambient_light, error_flags;
    while (!terminate) {
        if (opt3101_read_data(&distance, &ambient_light, &error_flags) == 0) {
            printf("Distance: %u, Ambient Light: %u, Error Flags: 0x%02X\n", distance, ambient_light, error_flags);
        } else {
            fprintf(stderr, "Error: Failed to read data\n");
        }
        gpioDelay(500000); // 500ms delay
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return 0;
}

