/*
 * HC-SR04 Ultrasonic Distance Sensor - Raspberry Pi 3 Model B+
 * Library: pigpio (http://abyz.me.uk/rpi/pigpio/)
 *
 * Wiring:
 *   HC-SR04 VCC -> 5V (Pin 2)
 *   HC-SR04 GND -> GND (Pin 6)
 *   HC-SR04 TRIG -> GPIO 17 (Pin 11)
 *   HC-SR04 ECHO -> GPIO 18 (Pin 12) via 1kOhm resistor
 *
 * NOTE: The HC-SR04 operates at 5V. The Raspberry Pi GPIO pins are only
 * 3.3V tolerant. A 1kOhm series resistor on the echo line protects the
 * Pi from the HC-SR04's 5V echo pulse.
 *
 * Build: gcc -Wall -Wextra -O2 -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:   sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18

#define TRIGGER_PULSE_US 10          /* 10 us trigger pulse            */
#define ECHO_TIMEOUT_US  200000      /* 200 ms timeout for echo rising/falling */
#define MAX_PULSE_US     38000       /* 38 ms max round-trip for 4 m    */
#define SAMPLE_PERIOD_S  1           /* 1 second between readings       */

static volatile sig_atomic_t g_terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Read distance from HC-SR04. Returns -1.0 on error.                   */
/* ------------------------------------------------------------------ */
static float read_distance(void)
{
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t timeout_tick;

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write trigger low.\n");
        return -1.0f;
    }
    gpioDelay(5);  /* settle */

    /* Send 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to write trigger high.\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write trigger low.\n");
        return -1.0f;
    }

    /* Wait for echo rising edge (timeout after 200 ms) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if (g_terminate)
            return -1.0f;
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: timeout waiting for echo rising edge.\n");
            return -1.0f;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout after 200 ms) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if (g_terminate)
            return -1.0f;
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: timeout waiting for echo falling edge.\n");
            return -1.0f;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;

    /* Validate pulse duration */
    if (pulse_us == 0 || pulse_us > MAX_PULSE_US) {
        fprintf(stderr, "Error: invalid pulse duration (%u us).\n", pulse_us);
        return -1.0f;
    }

    /* distance = (pulse_us * 0.0343) / 2  (cm) */
    return (float)pulse_us * 0.0343f / 2.0f;
}

/* ------------------------------------------------------------------ */
/* Log distance with timestamp                                         */
/* ------------------------------------------------------------------ */
static void log_distance(float distance)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("[%s] Distance: %.2f cm\n", timestamp, distance);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(1000);  /* let sensor settle */

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("HC-SR04 distance sensor started. Press Ctrl+C to exit.\n");

    while (!g_terminate) {
        float distance = read_distance();
        if (distance >= 0.0f)
            log_distance(distance);
        else
            fprintf(stderr, "Warning: read failed, will retry next cycle.\n");

        /* Sleep for 1 second (microseconds) */
        gpioDelay(SAMPLE_PERIOD_S * 1000000);
    }

    /* Cleanup */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

