#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/serial0"
#define GPIO_LED 17
#define RANGE_RESOLUTION 0.0486f
#define INTRUSION_THRESHOLD 1.0f
#define LED_ON_TIME 2
#define DATA_BUFFER_SIZE 128
#define MAGIC_WORD_SIZE 8
#define FRAME_SIZE (MAGIC_WORD_SIZE + DATA_BUFFER_SIZE)
#define NUM_RANGE_BINS 64

static const uint8_t MAGIC_WORD[MAGIC_WORD_SIZE] = {0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07};

static volatile sig_atomic_t running = 1;
static int uart_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int uart_init(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, B115200);
    cfsetispeed(&tty, B115200);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_iflag &= ~IGNBRK;
    tty.c_lflag = 0;
    tty.c_oflag = 0;
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 5;

    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int uart_read_exact(int fd, uint8_t *buf, size_t len) {
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("UART read error");
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "UART read timeout\n");
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

static int process_frame(const uint8_t *frame, int frame_len) {
    if (frame_len < FRAME_SIZE) {
        fprintf(stderr, "Frame too short: %d bytes\n", frame_len);
        return -1;
    }

    for (int i = 0; i < NUM_RANGE_BINS; i++) {
        int16_t val = (int16_t)((frame[MAGIC_WORD_SIZE + i * 2] << 8) | frame[MAGIC_WORD_SIZE + i * 2 + 1]);
        float distance = val * RANGE_RESOLUTION;
        if (distance < INTRUSION_THRESHOLD) {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[32];
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

            if (log_file) {
                fprintf(log_file, "%s,%.3f\n", timestamp, distance);
                fflush(log_file);
            } else {
                fprintf(stderr, "Log file not open\n");
            }
            return 1;
        }
    }
    return 0;
}

static void cleanup(void) {
    if (uart_fd >= 0) {
        close(uart_fd);
        uart_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(GPIO_LED, PI_OUTPUT);
    gpioWrite(GPIO_LED, 0);

    uart_fd = uart_init(UART_DEVICE);
    if (uart_fd < 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen("intrusion_log.csv", "a");
    if (!log_file) {
        perror("Error opening log file");
        close(uart_fd);
        gpioTerminate();
        return 1;
    }

    uint8_t buffer[FRAME_SIZE];
    int no_data_count = 0;

    while (running) {
        if (uart_read_exact(uart_fd, buffer, FRAME_SIZE) == 0) {
            no_data_count = 0;
            if (process_frame(buffer, FRAME_SIZE) == 1) {
                gpioWrite(GPIO_LED, 1);
                gpioDelay(LED_ON_TIME * 1000000);
                gpioWrite(GPIO_LED, 0);
            }
        } else {
            no_data_count++;
            if (no_data_count > 10) {
                fprintf(stderr, "Sensor absent or bus error after %d attempts\n", no_data_count);
                break;
            }
        }
        gpioDelay(10000);
    }

    cleanup();
    return 0;
}

