#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define SENSOR_PIN 17
#define BUZZER_PIN 18
#define LOG_FILE "obstacle_log.txt"
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_event(const char *event) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s: %s\n", timestamp, event);
    } else {
        fprintf(fp, "(unknown time): %s\n", event);
    }

    fclose(fp);
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor_line = NULL;
    struct gpiod_line *buzzer_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        fprintf(stderr, "Failed to get sensor line %d: %s\n", SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Failed to get buzzer line %d: %s\n", BUZZER_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(sensor_line, "obstacle_sensor") < 0) {
        fprintf(stderr, "Failed to request sensor line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(buzzer_line, "obstacle_buzzer", 0) < 0) {
        fprintf(stderr, "Failed to request buzzer line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    int last_state = -1;
    int buzzer_active = 0;

    while (program_running) {
        int sensor_value = gpiod_line_get_value(sensor_line);
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor: %s\n", strerror(errno));
            usleep(POLL_INTERVAL_US);
            continue;
        }

        int obstacle_detected = (sensor_value == 0);

        if (obstacle_detected && !buzzer_active) {
            if (gpiod_line_set_value(buzzer_line, 1) < 0) {
                fprintf(stderr, "Error activating buzzer: %s\n", strerror(errno));
            } else {
                buzzer_active = 1;
            }
        } else if (!obstacle_detected && buzzer_active) {
            if (gpiod_line_set_value(buzzer_line, 0) < 0) {
                fprintf(stderr, "Error deactivating buzzer: %s\n", strerror(errno));
            } else {
                buzzer_active = 0;
            }
        }

        if (obstacle_detected != last_state) {
            if (log_event(obstacle_detected ? "Obstacle detected" : "Obstacle removed") < 0) {
                fprintf(stderr, "Failed to log event\n");
            }
            last_state = obstacle_detected;
        }

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
    }
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return ret;
}

