#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS        1
#define I2C_ADDR       0x69
#define ALERT_PIN      17
#define DIST_REG_HIGH  0x31
#define DIST_REG_LOW   0x32
#define DIST_THRESHOLD 10.0f
#define SAMPLE_US      100000
#define LOG_FILE       "distance_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_i2c(void) {
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_distance(float *distance) {
    int hi = i2cReadByteData(g_i2c_handle, DIST_REG_HIGH);
    if (hi < 0) {
        fprintf(stderr, "I2C read error (high reg 0x%02X): %s\n",
                DIST_REG_HIGH, strerror(errno));
        return -1;
    }
    int lo = i2cReadByteData(g_i2c_handle, DIST_REG_LOW);
    if (lo < 0) {
        fprintf(stderr, "I2C read error (low reg 0x%02X): %s\n",
                DIST_REG_LOW, strerror(errno));
        return -1;
    }
    uint16_t raw = ((uint16_t)(hi & 0xFF) << 8) | (uint16_t)(lo & 0xFF);
    *distance = (float)raw / 10.0f;
    return 0;
}

static int log_distance(float distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }
    if (fprintf(fp, "%s, Distance: %.2f cm\n", ts, distance) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void trigger_alert(float distance) {
    if (distance < DIST_THRESHOLD) {
        gpioWrite(ALERT_PIN, 1);
        gpioDelay(100000);
        gpioWrite(ALERT_PIN, 0);
    }
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(ALERT_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ALERT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", ALERT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(ALERT_PIN, 0);

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Ultrasonic distance sensor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance;
        if (read_distance(&distance) == 0) {
            if (log_distance(distance) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
            trigger_alert(distance);
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }
        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

