#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L1X_ADDR   0x29
#define LOG_FILE       "distance_log.csv"
#define POLL_TIMEOUT_MS 100
#define LOOP_DELAY_US  100000

/* VL53L1X register addresses (16-bit, big-endian on bus) */
#define REG_SOFT_RESET              0x0000
#define REG_SYSTEM_MODE_START       0x007F
#define REG_SYSRANGE_START          0x0000
#define REG_RESULT_INTERRUPT_STATUS 0x0130
#define REG_SYSTEM_INTERRUPT_CLEAR  0x0140
#define REG_RESULT_RANGE_STATUS     0x0080
#define REG_IDENTIFICATION_MODEL_ID 0x010F

#define EXPECTED_MODEL_ID 0xEA
#define DISTANCE_THRESHOLD_LOW  300
#define DISTANCE_THRESHOLD_MED   600
#define DISTANCE_THRESHOLD_HIGH  1200

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Low-level I2C helpers                                               */
/* ------------------------------------------------------------------ */
static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr, 2) < 0)
        return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

/* ------------------------------------------------------------------ */
/* VL53L1X driver                                                      */
/* ------------------------------------------------------------------ */
static int vl53l1x_init(int handle)
{
    uint8_t model_id = 0;

    /* Verify sensor identity */
    if (i2c_read_reg16(handle, REG_IDENTIFICATION_MODEL_ID, &model_id, 1) < 0) {
        fprintf(stderr, "Error: failed to read model ID register\n");
        return -1;
    }
    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "Error: unexpected model ID 0x%02X (expected 0x%02X)\n",
                model_id, EXPECTED_MODEL_ID);
        return -1;
    }

    /* Software reset */
    if (i2c_write_reg16(handle, REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write soft-reset register\n");
        return -1;
    }
    gpioDelay(2000); /* 2 ms */

    /* Start continuous back-to-back ranging */
    if (i2c_write_reg16(handle, REG_SYSTEM_MODE_START, 0x01) < 0) {
        fprintf(stderr, "Error: failed to start ranging\n");
        return -1;
    }

    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status = 0;
    uint8_t data[2] = {0};
    int elapsed = 0;

    /* Poll SYSRANGE_START bit 0 until measurement completes */
    while (elapsed < POLL_TIMEOUT_MS) {
        if (i2c_read_reg16(handle, REG_SYSRANGE_START, &status, 1) < 0) {
            fprintf(stderr, "Error: failed to read SYSRANGE_START\n");
            return -1;
        }
        if ((status & 0x01) == 0)
            break;
        gpioDelay(1000); /* 1 ms */
        elapsed++;
    }
    if (elapsed >= POLL_TIMEOUT_MS) {
        fprintf(stderr, "Warning: ranging timeout\n");
        return -1;
    }

    /* Read 16-bit distance from RESULT_RANGE_STATUS + 10 (0x0080 + 10 = 0x0090) */
    if (i2c_read_reg16(handle, REG_RESULT_RANGE_STATUS + 10, data, 2) < 0) {
        fprintf(stderr, "Error: failed to read distance data\n");
        return -1;
    }
    *distance_mm = ((uint16_t)data[0] << 8) | data[1];

    /* Clear interrupt */
    if (i2c_write_reg16(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
        fprintf(stderr, "Warning: failed to clear interrupt\n");
        /* non-fatal: continue */
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_open(const char *filename)
{
    /* Check if file already exists to decide on header */
    int need_header = (access(filename, F_OK) != 0);
    g_log_file = fopen(filename, "a");
    if (!g_log_file) {
        perror("Error opening log file");
        return -1;
    }
    if (need_header)
        fprintf(g_log_file, "timestamp,distance_mm\n");
    return 0;
}

static void log_distance(uint16_t distance_mm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_file, "%s,%u\n", timestamp, distance_mm);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Parking guidance                                                    */
/* ------------------------------------------------------------------ */
static void parking_guidance(uint16_t distance_mm)
{
    if (distance_mm < DISTANCE_THRESHOLD_LOW)
        printf("STOP\n");
    else if (distance_mm < DISTANCE_THRESHOLD_MED)
        printf("APPROACH\n");
    else if (distance_mm < DISTANCE_THRESHOLD_HIGH)
        printf("SLOW\n");
    else
        printf("CLEAR\n");
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at addr 0x%02X\n",
                I2C_BUS, VL53L1X_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (log_open(LOG_FILE) < 0) {
        fprintf(stderr, "Error: logging failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Parking assistance system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t distance = 0;
        if (vl53l1x_read_distance(g_i2c_handle, &distance) == 0) {
