#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* CH201 I2C default address (7-bit) */
#define CH201_ADDR 0x45

/* CH201 register addresses */
#define CH201_REG_PRODUCT_ID 0x00
#define CH201_REG_DISTANCE 0x04

/* GPIO pin for LED (with 330 Ohm resistor to 3.3V) */
#define LED_PIN 18

/* I2C bus on Raspberry Pi 4 Model B */
#define I2C_BUS 1

/* Sampling interval in microseconds (100 ms) */
#define SAMPLE_INTERVAL_US 100000

/* Retry parameters */
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers with retry                                              */
/* ------------------------------------------------------------------ */
static int i2c_read_register(int handle, uint8_t reg, uint8_t *value)
{
    int rc;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        rc = i2cReadByteData(handle, reg);
        if (rc >= 0) {
            *value = (uint8_t)rc;
            return 0;
        }
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int i2c_write_register(int handle, uint8_t reg, uint8_t value)
{
    int rc;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        rc = i2cWriteByteData(handle, reg, value);
        if (rc == 0)
            return 0;
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* CH201 driver                                                        */
/* ------------------------------------------------------------------ */
static int ch201_init(int handle)
{
    uint8_t product_id;
    if (i2c_read_register(handle, CH201_REG_PRODUCT_ID, &product_id) != 0) {
        fprintf(stderr, "Error: failed to read CH201 product ID (sensor absent or bus error)\n");
        return -1;
    }
    printf("CH201 product ID: 0x%02X\n", product_id);
    return 0;
}

static int ch201_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t lo, hi;
    if (i2c_read_register(handle, CH201_REG_DISTANCE, &lo) != 0) {
        fprintf(stderr, "Error: failed to read CH201 distance low byte\n");
        return -1;
    }
    if (i2c_read_register(handle, CH201_REG_DISTANCE + 1, &hi) != 0) {
        fprintf(stderr, "Error: failed to read CH201 distance high byte\n");
        return -1;
    }
    *distance_mm = ((uint16_t)hi << 8) | lo;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Distance-to-blink-frequency mapping                                  */
/* ------------------------------------------------------------------ */
static float distance_to_frequency(uint16_t distance_mm)
{
    if (distance_mm < 50)
        return 10.0f;
    if (distance_mm > 500)
        return 1.0f;
    return 10.0f - ((float)distance_mm - 50.0f) * 9.0f / 450.0f;
}

/* ------------------------------------------------------------------ */
/* LED control                                                          */
/* ------------------------------------------------------------------ */
static void led_set_frequency(float frequency)
{
    int half_period_us = (int)(500000.0f / frequency / 2.0f);
    if (half_period_us < 10)
        half_period_us = 10;
    gpioWrite(LED_PIN, 1);
    gpioDelay(half_period_us);
    gpioWrite(LED_PIN, 0);
    gpioDelay(half_period_us);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                              */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                 */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED pin as output */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, CH201_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at address 0x%02X\n",
                I2C_BUS, CH201_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (ch201_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: CH201 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("CH201 distance monitor running. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        uint16_t distance_mm;
        if (ch201_read_distance(g_i2c_handle, &distance_mm) == 0) {
            float frequency = distance_to_frequency(distance_mm);
            led_set_frequency(frequency);
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
            printf("[%s] Distance: %u mm  ->  Blink: %.2f Hz\n",
                   ts, distance_mm, frequency);
        } else {
            fprintf(stderr, "Warning: I2C read failed, retrying next cycle\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

