#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define I2C_BUS 1
#define MLX75030_ADDR 0x4C
#define RETRY_COUNT 3
#define RETRY_DELAY_US 10000
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X on bus %d (pigpio error %d).\n",
                MLX75030_ADDR, I2C_BUS, i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_distance(uint16_t *distance) {
    char buf[2];
    int retries = 0;

    while (retries < RETRY_COUNT) {
        int result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
            *distance = ((uint16_t)(buf[0] & 0xFF) << 8) | (uint16_t)(buf[1] & 0xFF);
            return 0;
        }

        fprintf(stderr, "Warning: I2C read failed (attempt %d/%d, pigpio error %d).\n",
                retries + 1, RETRY_COUNT, result);
        retries++;
        if (retries < RETRY_COUNT) {
            gpioDelay(RETRY_DELAY_US);
        }
    }

    fprintf(stderr, "Error: Failed to read distance after %d retries.\n", RETRY_COUNT);
    return -1;
}

static void log_distance(uint16_t distance) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    printf("%s Distance: %u mm\n", timestamp, distance);
    fflush(stdout);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        return EXIT_FAILURE;
    }

    printf("MLX75030 ToF sensor reader started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t distance;
        if (read_distance(&distance) == 0) {
            log_distance(distance);
        } else {
            fprintf(stderr, "Error: Failed to read distance. Continuing...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

