#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define VL53L4CX_ADDR 0x29
#define I2C_BUS 1

/* VL53L4CX register addresses (exact 16-bit values) */
#define REG_SOFT_RESET              0x7FFF
#define REG_SYSTEM_START            0x0009
#define REG_INT_STATUS              0x0046
#define REG_RESULT_DISTANCE_HI      0x0096
#define REG_RESULT_DISTANCE_LO      0x0097

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len) {
    char cmd[2];
    cmd[0] = (reg >> 8) & 0xFF;
    cmd[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, cmd, 2) < 0) return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int init_sensor(int handle) {
    if (i2c_write_reg16(handle, REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write soft reset register\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    if (i2c_write_reg16(handle, REG_SYSTEM_START, 0x00) < 0) {
        fprintf(stderr, "Error: failed to start ranging\n");
        return -1;
    }
    return 0;
}

static int read_distance(int handle, uint16_t *distance_mm) {
    uint8_t status = 0;
    if (i2c_read_reg16(handle, REG_INT_STATUS, &status, 1) < 0) {
        fprintf(stderr, "Error: failed to read interrupt status\n");
        return -1;
    }
    if (!(status & 0x01)) {
        return 1; /* no new data yet */
    }

    uint8_t data[2];
    if (i2c_read_reg16(handle, REG_RESULT_DISTANCE_HI, data, 2) < 0) {
        fprintf(stderr, "Error: failed to read distance registers\n");
        return -1;
    }
    *distance_mm = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

static void log_distance(uint16_t distance) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    printf("Timestamp: %s.%06ld, Distance: %u mm\n",
           timestamp, ts.tv_nsec / 1000, (unsigned)distance);
    fflush(stdout);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L4CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at addr 0x%02X\n",
                I2C_BUS, VL53L4CX_ADDR);
        gpioTerminate();
        return 1;
    }

    if (init_sensor(i2c_handle) < 0) {
        fprintf(stderr, "Error: sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L4CX ranging started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t distance = 0;
        int rc = read_distance(i2c_handle, &distance);
        if (rc == 0) {
            log_distance(distance);
        } else if (rc < 0) {
            fprintf(stderr, "Warning: I2C read error, continuing...\n");
        }
        gpioDelay(500000); /* 500 ms */
    }

    printf("\nShutting down...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

