static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, int len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) < 0) return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int vl53l1x_init(int handle) {
    uint8_t model_id = 0;
    if (i2c_read_reg16(handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) < 0) {
        fprintf(stderr, "Error reading model ID: %s\n", strerror(errno));
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Invalid model ID: 0x%02X (expected 0xEA)\n", model_id);
        return -1;
    }

    if (i2c_write_reg16(handle, 0x0000, 0x00) < 0) {
        fprintf(stderr, "Error writing reset command 0x00: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(2000);
    if (i2c_write_reg16(handle, 0x0000, 0x01) < 0) {
        fprintf(stderr, "Error writing reset command 0x01: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(2000);

    if (i2c_write_reg16(handle, 0x0014, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, 0x0015, 0x00) < 0) return -1;
