#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    27
#define BUZZER_PIN  22

#define SPEED_OF_SOUND_CM_S  34300.0
#define MIN_DISTANCE_CM      2.0
#define MAX_DISTANCE_CM      400.0
#define BUZZER_THRESHOLD_CM  30.0
#define ECHO_TIMEOUT_US      30000   /* 30 ms max echo wait */
#define LOOP_DELAY_US        100000 /* 100 ms between readings */
#define TRIGGER_PULSE_US     10

static volatile sig_atomic_t g_running = 1;
static volatile uint32_t    g_start_tick = 0;
static volatile uint32_t    g_end_tick   = 0;
static volatile int         g_echo_done  = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        g_start_tick = tick;
        g_echo_done  = 0;
    } else if (level == 0) {
        g_end_tick = tick;
        g_echo_done = 1;
    }
}

static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static double calculate_distance_cm(uint32_t start, uint32_t end)
{
    /* pigpio ticks are 32-bit microseconds; handle wraparound */
    uint32_t elapsed = end - start; /* correct for wraparound */
    if (elapsed == 0)
        return -1.0;

    /* distance = (time * speed) / 2  (round trip) */
    return ((double)elapsed / 1000000.0) * SPEED_OF_SOUND_CM_S / 2.0;
}

static void control_buzzer(double distance)
{
    static int buzzer_on = 0;

    if (distance < BUZZER_THRESHOLD_CM && !buzzer_on) {
        gpioWrite(BUZZER_PIN, 1);
        buzzer_on = 1;
        printf("[ALERT] Object within %.1f cm — buzzer ON\n", distance);
    } else if (distance >= BUZZER_THRESHOLD_CM && buzzer_on) {
        gpioWrite(BUZZER_PIN, 0);
        buzzer_on = 0;
        printf("[INFO] Clear — buzzer OFF\n");
    }
}

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO modes --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set BUZZER_PIN %d as output.\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Ensure known initial states --- */
    gpioWrite(TRIGGER_PIN, 0);
    gpioWrite(BUZZER_PIN, 0);

    /* --- Register echo alert callback --- */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: failed to register alert on ECHO_PIN %d.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handler for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Parking sensor started. TRIG=GPIO%d, ECHO=GPIO%d, BUZZER=GPIO%d\n",
           TRIGGER_PIN, ECHO_PIN, BUZZER_PIN);
    printf("Threshold: %.1f cm. Press Ctrl+C to exit.\n", BUZZER_THRESHOLD_CM);

    /* --- Main measurement loop --- */
    while (g_running) {
        g_echo_done = 0;
        g_start_tick = 0;
        g_end_tick   = 0;

        trigger_sensor();

        /* Wait for echo with timeout */
        uint32_t waited = 0;
        while (!g_echo_done && g_running && waited < ECHO_TIMEOUT_US) {
            gpioDelay(100); /* 100 us granularity */
            waited += 100;
        }

        if (!g_running)
            break;

        if (!g_echo_done) {
            fprintf(stderr, "Warning: echo timeout — sensor absent or wiring fault.\n");
            gpioWrite(BUZZER_PIN, 0);
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        uint32_t start = g_start_tick;
        uint32_t end   = g_end_tick;
        double distance = calculate_distance_cm(start, end);

        if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
            fprintf(stderr, "Warning: invalid reading %.2f cm (out of range %d–%d).\n",
                    distance, (int)MIN_DISTANCE_CM, (int)MAX_DISTANCE_CM);
            gpioWrite(BUZZER_PIN, 0);
        } else {
            printf("Distance: %.2f cm\n", distance);
            control_buzzer(distance);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* --- Clean shutdown --- */
    gpioWrite(BUZZER_PIN, 0);
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

