#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define DISTANCE_THRESHOLD 20
#define LOG_FILE "gate_log.txt"
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "gate_control"
#define MQTT_CLIENT_ID "gate_control_rpi"

#define VL53L1X_REG_SOFT_RESET 0x000B
#define VL53L1X_REG_VHV_CONFIG 0x000C
#define VL53L1X_REG_PHASECAL_CONFIG 0x0010
#define VL53L1X_REG_RANGE_CONFIG 0x0011
#define VL53L1X_REG_INTERMEASUREMENT 0x0012
#define VL53L1X_REG_SYSTEM_MODE 0x0013
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_DISTANCE 0x0016

static int i2c_handle = -1;
static FILE *log_file = NULL;
static MQTTClient mqtt_client = NULL;
static volatile sig_atomic_t running = 1;

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

static int i2c_write_reg16(uint8_t reg, uint8_t value) {
    char buf[3] = {(char)(reg & 0xFF), (char)(reg >> 8), (char)value};
    return i2cWriteDevice(i2c_handle, buf, 3);
}

static int i2c_read_reg16(uint8_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[2] = {(char)(reg & 0xFF), (char)(reg >> 8)};
    if (i2cWriteDevice(i2c_handle, reg_buf, 2) != 0) return -1;
    return i2cReadDevice(i2c_handle, (char *)buf, len);
}

static int vl53l1x_init(void) {
    if (i2c_write_reg16(VL53L1X_REG_SOFT_RESET, 0x00) != 0) return -1;
    gpioDelay(10000);
    if (i2c_write_reg16(VL53L1X_REG_SOFT_RESET, 0x01) != 0) return -1;
    gpioDelay(10000);
    if (i2c_write_reg16(VL53L1X_REG_VHV_CONFIG, 0x01) != 0) return -1;
    if (i2c_write_reg16(VL53L1X_REG_PHASECAL_CONFIG, 0x0A) != 0) return -1;
    if (i2c_write_reg16(VL53L1X_REG_RANGE_CONFIG, 0x0A) != 0) return -1;
    if (i2c_write_reg16(VL53L1X_REG_INTERMEASUREMENT, 0x00) != 0) return -1;
    if (i2c_write_reg16(VL53L1X_REG_SYSTEM_MODE, 0x40) != 0) return -1;
    return 0;
}

static int vl53l1x_read_distance(uint16_t *distance) {
    uint8_t status;
    if (i2c_read_reg16(VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) != 1) return -1;
    if ((status & 0x01) == 0) return 1;
    uint8_t data[2];
    if (i2c_read_reg16(VL53L1X_REG_RESULT_DISTANCE, data, 2) != 2) return -1;
    *distance = (data[0] << 8) | data[1];
    if (i2c_write_reg16(VL53L1X_REG_SYSTEM_MODE, 0x00) != 0) return -1;
    return 0;
}

static void control_servo(int angle) {
    int pulse_width = 500 + (angle * 2000 / 180);
    gpioServo(SERVO_PIN, pulse_width);
}

static void open_gate(void) {
    control_servo(90);
    log_event("Gate opened");
}

static void close_gate(void) {
    control_servo(0);
    log_event("Gate closed");
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void mqtt_connect_callback(MQTTClient client, void *userdata, int reason) {
    (void)client; (void)userdata;
    if (reason == MQTTCONNECTED) {
        MQTTClient_message *msg = malloc(MQTT_MAX_PAYLOAD_SIZE);
        if (msg) {
            char payload[128];
            snprintf(payload, sizeof(payload), "Connected to broker");
            MQTTClient_message_set_payload(msg, payload, strlen(payload));
            MQTTClient_deliveryToken_t token;
            MQTTClient_publishMessage(client, MQTT_TOPIC, msg, &token);
            free(msg);
        }
    }
}

static void mqtt_message_callback(MQTTClient client, void *userdata, char *topicName, int topicLen, MQTTClient_message *message) {
    (void)client; (void)userdata; (void)topicLen;
    if (message->payloadlen > 0) {
        char payload[128];
        int plen = message->payloadlen < (int)sizeof(payload) - 1 ? message->payloadlen : (int)sizeof(payload) - 1;
        memcpy(payload, message->payload, plen);
        payload[plen] = '\0';
        printf("Received: %s\n", payload);
        if (strcmp(payload, "force_open") == 0) {
            open_gate();
        } else if (strcmp(payload, "force_close") == 0) {
            close_gate();
        } else if (strcmp(payload, "status_request") == 0) {
            char status[128];
            snprintf(status, sizeof(status), "Gate is %s", (i2c_handle >= 0) ? "open" : "closed");
            MQTTClient_message *resp = malloc(MQTT_MAX_PAYLOAD_SIZE);
            if (resp) {
                snprintf(status, sizeof(status), "Gate is %s", (i2c_handle >= 0) ? "open" : "closed");
                MQTTClient_message_set_payload(resp, status, strlen(status));
                MQTTClient_deliveryToken_t token;
                MQTTClient_publishMessage(client, MQTT_TOPIC, resp, &token);
                free(resp);
            }
        }
    }
}

static void mqtt_disconnect_callback(MQTTClient client, void *userdata, int reason) {
    (void)client; (void)userdata;
    fprintf(stderr, "MQTT disconnected (reason %d)\n", reason);
}

static int mqtt_init(void) {
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;
    conn_opts.connectTimeout = 10;
    conn_opts.reconnectTimeout = 5;
    conn_opts.assignClientID = MQTTClient_assignClientID_default;
    conn_opts.clientID = MQTT_CLIENT_ID;

    if (MQTTClient_create(&mqtt_client, MQTT_BROKER, &conn_opts, NULL) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create MQTT client\n");
        return -1;
    }
    MQTTClient_setCallbacks(mqtt_client, NULL, mqtt_disconnect_callback, mqtt_message_callback, mqtt_connect_callback);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (mqtt_client) {
        MQTTClient_destroy(&mqtt_client);
        mqtt_client = NULL;
    }
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed\n");
        log_event("I2C open failed");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init() != 0) {
        fprintf(stderr, "VL53L1X init failed\n");
        log_event("VL53L1X init failed");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    control_servo(0);

    if (mqtt_init() != 0) {
        log_event("MQTT init failed");
        cleanup();
        return 1;
    }

    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;
    conn_opts.connectTimeout = 10;
    conn_opts.reconnectTimeout = 5;
    conn_opts.assignClientID = MQTTClient_assignClientID_default;
    conn_opts.clientID = MQTT_CLIENT_ID;

    if (MQTTClient_connect(mqtt_client, &conn_opts) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "MQTT connect failed\n");
        log_event("MQTT connect failed");
        cleanup();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("System started");

    while (running) {
        uint16_t distance;
        int ret = vl53l1x_read_distance(&distance);
        if (ret == 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Distance: %u mm", distance);
            log_event(msg);
            if (distance < DISTANCE_THRESHOLD * 10) {
                open_gate();
            } else {
                close_gate();
            }
        } else if (ret < 0) {
            log_event("I2C read error");
            gpioDelay(1000000);
        }
        gpioDelay(100000);
    }

