/*
 * HC-SR04 Ultrasonic Distance Measurement on Raspberry Pi 4 Model B
 * Library: pigpio (C API)
 *
 * Wiring:
 *   TRIG -> GPIO 23 (physical pin 16, BCM 23, output)
 *   ECHO -> GPIO 24 (physical pin 18, BCM 24, input with pull-down)
 *
 * NOTE: The HC-SR04 ECHO pin outputs 5V, which exceeds the Pi's 3.3V
 *       GPIO tolerance. A voltage divider (e.g., 1k/2k) MUST be used
 *       on the ECHO line before connecting to the Pi.
 *
 * Build: gcc -Wall -Wextra -O2 -o distance distance.c -lpigpio -lrt
 * Run:   sudo ./distance
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24

#define SPEED_OF_SOUND   0.0343          /* cm/us at 20 C */
#define MIN_PULSE_WIDTH  100             /* us - noise floor */
#define MAX_PULSE_WIDTH  30000           /* us - timeout / no object */
#define MEASURE_INTERVAL 200             /* ms between measurements */
#define ECHO_TIMEOUT_US  60000           /* 60 ms max echo wait */
#define TRIGGER_PULSE_US 10              /* 10 us trigger pulse */
#define LOG_FILE         "distance_log.txt"

/* ------------------------------------------------------------------ */
/* Shared state between callback and main thread                      */
/* ------------------------------------------------------------------ */

static volatile uint32_t g_rising_tick = 0;
static volatile uint32_t g_falling_tick = 0;
static volatile bool     g_echo_received = false;
static volatile bool     g_new_reading   = false;

static FILE *g_log_fp = NULL;
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback (runs in pigpio thread)                        */
/* ------------------------------------------------------------------ */

static void echo_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;

    if (level == 1) {
        /* Rising edge - start of echo pulse */
        g_rising_tick = tick;
        g_echo_received = false;
    } else if (level == 0) {
        /* Falling edge - end of echo pulse */
        g_falling_tick = tick;
        g_echo_received = true;
        g_new_reading   = true;
    }
    /* level == 2 indicates a watchdog timeout; ignored here */
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

/*
 * Compute (b - a) with 32-bit wraparound handling.
 * pigpio ticks are uint32_t microseconds and wrap every ~72 min.
 */
static uint32_t tick_diff(uint32_t a, uint32_t b)
{
    return b - a;  /* unsigned subtraction wraps correctly */
}

static float calculate_distance(uint32_t pulse_width_us)
{
    return (float)pulse_width_us * SPEED_OF_SOUND / 2.0f;
}

static void log_distance(float distance_cm)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        snprintf(ts, sizeof(ts), "UNKNOWN");
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    }

    printf("[%s] Distance: %.2f cm\n", ts, distance_cm);

    if (g_log_fp != NULL) {
        fprintf(g_log_fp, "%s,%.2f\n", ts, distance_cm);
        fflush(g_log_fp);
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        fprintf(stderr, "       Is the pigpio daemon running? Stop it first.\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO pins ---- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: cannot set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Enable internal pull-down on ECHO so the line reads LOW when idle */
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Warning: cannot set pull-down on ECHO_PIN %d.\n", ECHO_PIN);
    }

    /* Ensure trigger starts LOW */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50);  /* let line settle */

    /* ---- Register alert callback ---- */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: cannot register alert callback on ECHO_PIN %d.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("  TRIG: GPIO %d | ECHO: GPIO %d | Log: %s\n",
           TRIGGER_PIN, ECHO_PIN, LOG_FILE);
    printf("  Press Ctrl+C to exit.\n\n");

    /* ---- Main measurement loop ---- */
    while (g_running) {
        g_echo_received = false;
        g_new_reading   = false;

        trigger_sensor();

        /* Wait for echo with timeout */
        uint32_t wait_start = gpioTick();
        while (!g_echo_received && g_running) {
            if (tick_diff(wait_start, gpioTick()) > ECHO_TIMEOUT_US) {
                break;
            }
            gpioDelay(100);  /* poll every 100 us */
        }

        if (!g_running) {
            break;
        }

        if (!g_echo_received) {
            /* No echo received within timeout - warn and retry */
            fprintf(stderr, "Warning: Echo timeout - no object detected or sensor absent.\n");
            if (g_log_fp != NULL) {
                fprintf(g_log_fp, "WARNING: Echo timeout\n");
                fflush(g_log_fp);
            }
            gpioDelay(MEASURE_INTERVAL * 1000);
            continue;
        }

        if (!g_new_reading) {
            /* Spurious edge without valid reading - skip */
            gpioDelay(MEASURE_INTERVAL * 1000);
            continue;
        }

        uint32_t pulse_width = tick_diff(g_rising_tick, g_falling_tick);

        if (pulse_width < MIN_PULSE_WIDTH) {
            fprintf(stderr, "Warning: Pulse width %u us below noise floor (%d us).\n",
                    pulse_width, MIN_PULSE_WIDTH);
            if (g_log_fp != NULL) {
                fprintf(g_log_fp, "WARNING: Pulse too short\n");
                fflush(g_log_fp);
            }
            gpioDelay(MEASURE_INTERVAL * 1000);
            continue;
        }

        if (pulse_width > MAX_PULSE_WIDTH) {
            fprintf(stderr, "Warning: Pulse width %u us exceeds max (%d us) - possible timeout or no object.\n",
                    pulse_width, MAX_PULSE_WIDTH);
            if (g_log_fp != NULL) {
                fprintf(g_log_fp, "WARNING: Pulse too long\n");
                fflush(g_log_fp);
            }
            gpioDelay(MEASURE_INTERVAL * 1000);
            continue;
        }

        float distance = calculate_distance(pulse_width);
        log_distance(distance);

        gpioDelay(MEASURE_INTERVAL * 1000);  /* 5 Hz */
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");

    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

