#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_OPEN_PIN 18
#define GATE_CLOSE_PIN 19
#define DISTANCE_THRESHOLD_MM 200
#define LOG_FILE "gate_events.log"
#define POLL_DELAY_US 500000

/* VL53L1X 16-bit register addresses */
#define VL53L1X_SOFT_RESET 0x0000
#define VL53L1X_VHV_CONFIG 0x0001
#define VL53L1X_PHASECAL_CONFIG 0x0002
#define VL53L1X_RANGE_CONFIG_A 0x0003
#define VL53L1X_RANGE_CONFIG_B 0x0004
#define VL53L1X_INTERMEASUREMENT 0x0005
#define VL53L1X_SYSTEM_INTERMEASUREMENT 0x0006
#define VL53L1X_SYSTEM_CONFIG 0x0007
#define VL53L1X_GPIO_HV_MUX 0x0030
#define VL53L1X_GPIO_TIO_HV_STATUS 0x0031
#define VL53L1X_SYSTEM_INTERRUPT_CLEAR 0x0086
#define VL53L1X_RESULT_INTERRUPT_STATUS 0x0088
#define VL53L1X_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_RESULT_DISTANCE 0x0096

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteI2CBlockData(handle, buf[0], &buf[1], 2);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteI2CBlockData(handle, reg_buf[0], &reg_buf[1], 1) < 0) {
        return -1;
    }
    return i2cReadI2CBlockData(handle, reg_buf[0], (char *)buf, len);
}

static int vl53l1x_init(int handle) {
    uint8_t id = 0;
    if (i2c_read_reg16(handle, VL53L1X_SOFT_RESET, &id, 1) < 0) {
        fprintf(stderr, "Error: Failed to read VL53L1X soft reset register.\n");
        return -1;
    }
    if (id != 0x00) {
        fprintf(stderr, "Warning: VL53L1X soft reset value 0x%02X (expected 0x00).\n", id);
    }

    if (i2c_write_reg16(handle, VL53L1X_SOFT_RESET, 0x00) < 0) return -1;
    gpioDelay(10000);

    if (i2c_write_reg16(handle, VL53L1X_SOFT_RESET, 0x01) < 0) return -1;
    gpioDelay(10000);

    if (i2c_write_reg16(handle, VL53L1X_VHV_CONFIG, 0x01) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_PHASECAL_CONFIG, 0x0B) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_RANGE_CONFIG_A, 0x0F) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_RANGE_CONFIG_B, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_INTERMEASUREMENT, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_SYSTEM_INTERMEASUREMENT, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_SYSTEM_CONFIG, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_GPIO_HV_MUX, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) return -1;

    return 0;
}

static int vl53l1x_start_ranging(int handle) {
    if (i2c_write_reg16(handle, VL53L1X_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_SYSTEM_CONFIG, 0x04) < 0) return -1;
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm) {
    uint8_t status = 0;
    uint8_t dist_buf[2] = {0};

    if (i2c_read_reg16(handle, VL53L1X_RESULT_INTERRUPT_STATUS, &status, 1) < 0) {
        return -1;
    }
    if ((status & 0x07) == 0) {
        return 1; /* No new data yet */
    }

    if (i2c_read_reg16(handle, VL53L1X_RESULT_RANGE_STATUS, &status, 1) < 0) {
        return -1;
    }
    if ((status & 0x01) == 0) {
        return 1; /* Data not ready */
    }

    if (i2c_read_reg16(handle, VL53L1X_RESULT_DISTANCE, dist_buf, 2) < 0) {
        return -1;
    }

    *distance_mm = (dist_buf[0] << 8) | dist_buf[1];
    if (i2c_write_reg16(handle, VL53L1X_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
        return -1;
    }
    return 0;
}

static void log_event(const char *event) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(GATE_OPEN_PIN, 0);
    gpioWrite(GATE_CLOSE_PIN, 0);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'.\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, VL53L1X_ADDR);
        log_event("Error: I2C bus open failed.");
        cleanup();
        return 1;
    }

    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed.\n");
        log_event("Error: VL53L1X initialization failed.");
        cleanup();
        return 1;
    }

    if (vl53l1x_start_ranging(i2c_handle) < 0) {
        fprintf(stderr, "Error: Failed to start ranging on VL53L1X.\n");
        log_event("Error: Failed to start ranging.");
        cleanup();
        return 1;
    }

    gpioSetMode(GATE_OPEN_PIN, PI_OUTPUT);
    gpioSetMode(GATE_CLOSE_PIN, PI_OUTPUT);
    gpioWrite(GATE_OPEN_PIN, 0);
    gpioWrite(GATE_CLOSE_PIN, 0);

    log_event("Gate control system started.");

    while (running) {
        uint16_t distance = 0;
        int ret = vl53l1x_read_distance(i2c_handle, &distance);

        if (ret < 0) {
            fprintf(stderr, "Error: I2C read failure from VL53L1X.\n");
            log_event("Error: I2C read failure.");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (ret == 0) {
            if (distance < DISTANCE_THRESHOLD_MM) {
                gpioWrite(GATE_OPEN_PIN, 1);
                gpioWrite(GATE_CLOSE_PIN, 0);
                log_event("Gate opened.");
            } else {
                gpioWrite(GATE_OPEN_PIN, 0);
                gpioWrite(GATE_CLOSE_PIN, 1);
                log_event("Gate closed.");
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    log_event("Gate control system shutting down.");
    cleanup();
    return 0;
}

