#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define TRIGGER_PIN 24
#define MOTOR_FORWARD_PIN 17
#define MOTOR_BACKWARD_PIN 18
#define DISTANCE_THRESHOLD_LOW 100
#define DISTANCE_THRESHOLD_HIGH 300
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) < 0) return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int vl53l1x_init(int handle) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2c_write_reg16(handle, 0x0000, 0x00) == 0) break;
        retries++;
        gpioDelay(1000 << retries);
    }
    if (retries >= MAX_RETRIES) return -1;
    gpioDelay(1000);
    retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2c_write_reg16(handle, 0x0000, 0x01) == 0) return 0;
        retries++;
        gpioDelay(1000 << retries);
    }
    return -1;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2c_write_reg16(handle, 0x0089, 0x00) == 0) break;
        retries++;
        gpioDelay(1000 << retries);
    }
    if (retries >= MAX_RETRIES) return -1;
    retries = 0;
    uint8_t status = 0;
    while (retries < MAX_RETRIES) {
        if (i2c_read_reg16(handle, 0x0089, &status, 1) == 1) break;
        retries++;
        gpioDelay(1000 << retries);
    }
    if (retries >= MAX_RETRIES) return -1;
    if (!(status & 0x01)) return -1;
    uint8_t data[2];
    retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2c_read_reg16(handle, 0x0096, data, 2) == 2) break;
        retries++;
        gpioDelay(1000 << retries);
    }
    if (retries >= MAX_RETRIES) return -1;
    *distance = (data[0] << 8) | data[1];
    return 0;
}

static void motor_forward(void) {
    gpioWrite(MOTOR_FORWARD_PIN, 1);
    gpioWrite(MOTOR_BACKWARD_PIN, 0);
}

static void motor_backward(void) {
    gpioWrite(MOTOR_FORWARD_PIN, 0);
    gpioWrite(MOTOR_BACKWARD_PIN, 1);
}

static void motor_stop(void) {
    gpioWrite(MOTOR_FORWARD_PIN, 0);
    gpioWrite(MOTOR_BACKWARD_PIN, 0);
}

static void trigger_callback(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    uint16_t distance = 0;
    if (vl53l1x_read_distance(i2c_handle, &distance) == 0) {
        printf("Distance: %u mm\n", distance);
        if (distance < DISTANCE_THRESHOLD_LOW) {
            motor_forward();
            printf("Motor: Forward\n");
        } else if (distance > DISTANCE_THRESHOLD_HIGH) {
            motor_backward();
            printf("Motor: Backward\n");
        } else {
            motor_stop();
            printf("Motor: Stop\n");
        }
    } else {
