    gpioSetMode(MOTOR_BACKWARD_PIN, PI_OUTPUT);
    motor_stop();
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    if (gpioSetISRFuncEx(TRIGGER_PIN, RISING_EDGE, 0, trigger_callback, NULL) != 0) {
        fprintf(stderr, "Error setting ISR\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
