#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define MPR121_ADDR 0x5A
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "touch_log.txt"

#define LED_PIN_1 17
#define LED_PIN_2 18
#define LED_PIN_3 27
#define LED_PIN_4 22

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_SOFTRESET 0x80
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_NHDF 0x2F
#define MPR121_NCLF 0x30
#define MPR121_FDLF 0x31
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_ELECTRODE_CONFIG0 0x5E
#define MPR121_ELECTRODE_CONFIG1 0x5F
#define MPR121_AUTOCONFIG0 0x7B
#define MPR121_AUTOCONFIG1 0x7C
#define MPR121_USL 0x7D
#define MPR121_LSL 0x7E
#define MPR121_TL 0x7F

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_lines[4] = {NULL};
static const int led_pins[4] = {LED_PIN_1, LED_PIN_2, LED_PIN_3, LED_PIN_4};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpr121_init(int fd) {
    if (i2c_write_reg8(fd, MPR121_SOFTRESET, 0x63) < 0) return -1;
    usleep(10000);

    uint8_t whoami = 0;
    if (i2c_read_reg8(fd, MPR121_AUTOCONFIG0, &whoami) < 0) return -1;
    if (whoami != 0x01) {
        fprintf(stderr, "MPR121 not detected (WHO_AM_I = 0x%02X)\n", whoami);
        return -1;
    }

    if (i2c_write_reg8(fd, MPR121_MHDR, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NHDR, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NCLR, 0x0E) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_FDLR, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NHDF, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NCLF, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_FDLF, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_DEBOUNCE, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_CONFIG1, 0x10) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_CONFIG2, 0x20) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECTRODE_CONFIG1, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_USL, 0x0B) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_LSL, 0xC8) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_TL, 0x82) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_E0TTH, 0x0B) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_E0RTH, 0xB4) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECTRODE_CONFIG0, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECTRODE_CONFIG1, 0x0C) < 0) return -1;

    return 0;
}

static void log_event(int electrode) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    if (log_fp) {
        fprintf(log_fp, "%s - Electrode %d touched\n", ts, electrode);
        fflush(log_fp);
    }
    printf("%s - Electrode %d touched\n", ts, electrode);
}

static void set_led_pattern(int pattern) {
    for (int i = 0; i < 4; i++) {
        int val = (pattern >> i) & 1;
        if (led_lines[i]) {
            if (gpiod_line_set_value(led_lines[i], val) < 0) {
                fprintf(stderr, "Failed to set LED line %d: %s\n", led_pins[i], strerror(errno));
            }
        }
    }
}

static void clear_leds(void) {
    for (int i = 0; i < 4; i++) {
        if (led_lines[i]) {
            gpiod_line_set_value(led_lines[i], 0);
        }
    }
}

static void cleanup(void) {
    clear_leds();
    for (int i = 0; i < 4; i++) {
        if (led_lines[i]) {
            gpiod_line_release(led_lines[i]);
            led_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        cleanup();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPR121_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (mpr121_init(i2c_fd) < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    for (int i = 0; i < 4; i++) {
        led_lines[i] = gpiod_chip_get_line(chip, led_pins[i]);
        if (!led_lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d: %s\n", led_pins[i], strerror(errno));
            cleanup();
            return 1;
        }
        if (gpiod_line_request_output(led_lines[i], "mpr121_leds", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", led_pins[i], strerror(errno));
            cleanup();
            return 1;
        }
    }

    printf("MPR121 initialized. Monitoring electrodes (Ctrl+C to exit).\n");

    while (running) {
        uint8_t low = 0, high = 0;
        if (i2c_read_reg8(i2c_fd, MPR121_TOUCHSTATUS_L, &low) < 0 ||
            i2c_read_reg8(i2c_fd, MPR121_TOUCHSTATUS_H, &high) < 0) {
            fprintf(stderr, "Error reading touch status, retrying...\n");
            usleep(100000);
            continue;
        }

        uint16_t status = ((uint16_t)high << 8) | low;
        bool any_active = false;

        if (status & 0x0FFF) {
            for (int i = 0; i < 12; i++) {
                if (status & (1 << i)) {
                    log_event(i);
                    any_active = true;
                    set_led_pattern(i + 1);
                }
            }
        } else {
            if (!any_active) {
                printf("No electrodes active\n");
            }
            clear_leds();
        }

        usleep(50000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

