        i2c_fd = -1;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        cleanup();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPR121_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (mpr121_init(i2c_fd) < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    for (int i = 0; i < 4; i++) {
        led_lines[i] = gpiod_chip_get_line(chip, led_pins[i]);
        if (!led_lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d: %s\n", led_pins[i], strerror(errno));
            cleanup();
            return 1;
        }
        if (gpiod_line_request_output(led_lines[i], "mpr121_leds", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", led_pins[i], strerror(errno));
            cleanup();
            return 1;
        }
    }

    printf("MPR121 initialized. Monitoring electrodes (Ctrl+C to exit).\n");

    while (running) {
        uint8_t low = 0, high = 0;
        if (i2c_read_reg8(i2c_fd, MPR121_TOUCHSTATUS_L, &low) < 0 ||
            i2c_read_reg8(i2c_fd, MPR121_TOUCHSTATUS_H, &high) < 0) {
            fprintf(stderr, "Error reading touch status, retrying...\n");
            usleep(100000);
            continue;
        }

        uint16_t status = ((uint16_t)high << 8) | low;
        bool any_active = false;

        if (status & 0x0FFF) {
            for (int i = 0; i < 12; i++) {
                if (status & (1 << i)) {
                    log_event(i);
                    any_active = true;
                    set_led_pattern(i + 1);
                }
            }
        } else {
            if (!any_active) {
                printf("No electrodes active\n");
            }
            clear_leds();
        }

        usleep(50000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

