#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_MHD_RISING 0x2B
#define MPR121_NHD_RISING 0x2C
#define MPR121_NCL_RISING 0x2D
#define MPR121_FDL_RISING 0x2E
#define MPR121_MHD_FALLING 0x2F
#define MPR121_NHD_FALLING 0x30
#define MPR121_NCL_FALLING 0x31
#define MPR121_FDL_FALLING 0x32
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_ECR 0x5E
#define MPR121_SOFTRESET 0x80

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write_reg(uint8_t reg, uint8_t val) {
    if (i2cWriteByteData(i2c_handle, reg, val) < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %s\n", reg, pigpio_error(i2c_handle));
        return -1;
    }
    return 0;
}

static int mpr121_init(void) {
    if (mpr121_write_reg(MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(10000);

    if (mpr121_write_reg(MPR121_ECR, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_CONFIG2, 0x20) < 0) return -1;
    if (mpr121_write_reg(MPR121_CONFIG1, 0x10) < 0) return -1;
    if (mpr121_write_reg(MPR121_DEBOUNCE, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_E0TTH, 0x0A) < 0) return -1;
    if (mpr121_write_reg(MPR121_E0RTH, 0x05) < 0) return -1;
    if (mpr121_write_reg(MPR121_MHD_RISING, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHD_RISING, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCL_RISING, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDL_RISING, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_MHD_FALLING, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHD_FALLING, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCL_FALLING, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDL_FALLING, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_ELECTRODE_CONFIG, 0x0C) < 0) return -1;
    if (mpr121_write_reg(MPR121_ECR, 0x8C) < 0) return -1;
    return 0;
}

static int read_touch_status(uint16_t *status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2) != 2) {
        fprintf(stderr, "Error reading touch status\n");
        return -1;
    }
    *status = (uint16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static void log_proximity(void) {
    FILE *fp = fopen("proximity.log", "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s - Proximity detected on electrode 0\n", s);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", pigpio_error(i2c_handle));
        gpioTerminate();
        return 1;
    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 init failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Proximity detection started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t status;
        if (read_touch_status(&status) == 0) {
            if (status & 0x01) {
                printf("Proximity detected!\n");
                gpioWrite(LED_GPIO, 1);
                log_proximity();
                gpioDelay(1000000);
                gpioWrite(LED_GPIO, 0);
            }
        }
        gpioDelay(10000);
    }

    gpioWrite(LED_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Exiting.\n");
    return 0;
}

