#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define LOG_FILE    "distance_log.txt"
#define SPEED_OF_SOUND 0.0343  /* cm/us */
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define TIMEOUT_US 30000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
}

static void log_reading(FILE *fp, const char *ts, float distance)
{
    fprintf(fp, "%s, Distance: %.2f cm\n", ts, distance);
    fflush(fp);
}

static void log_error(FILE *fp, const char *ts, const char *msg)
{
    fprintf(fp, "%s, ERROR: %s\n", ts, msg);
    fflush(fp);
}

/*
 * Measure distance using HC-SR04.
 * Returns distance in cm on success, or -1.0 on timeout/error.
 */
static float measure_distance(struct gpiod_line *trig, struct gpiod_line *echo)
{
    struct timespec ts_start, ts_now;
    long elapsed_us;
    int val;

    /* Ensure trigger starts low */
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
        return -1.0;
    }
    usleep(5);

    /* 10 us trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        fprintf(stderr, "Failed to set trigger high: %s\n", strerror(errno));
        return -1.0;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
        return -1.0;
    }

    /* Wait for echo rising edge (timeout 30 ms) */
    clock_gettime(CLOCK_MONOTONIC, &ts_start);
    do {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            fprintf(stderr, "Failed to read echo: %s\n", strerror(errno));
            return -1.0;
        }
        clock_gettime(CLOCK_MONOTONIC, &ts_now);
        elapsed_us = (ts_now.tv_sec - ts_start.tv_sec) * 1000000L +
                     (ts_now.tv_nsec - ts_start.tv_nsec) / 1000L;
        if (elapsed_us > TIMEOUT_US) {
            return -1.0;  /* echo never rose — sensor absent or not responding */
        }
    } while (val == 0);

    /* Measure echo pulse width (timeout 30 ms) */
    clock_gettime(CLOCK_MONOTONIC, &ts_start);
    do {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            fprintf(stderr, "Failed to read echo: %s\n", strerror(errno));
            return -1.0;
        }
        clock_gettime(CLOCK_MONOTONIC, &ts_now);
        elapsed_us = (ts_now.tv_sec - ts_start.tv_sec) * 1000000L +
                     (ts_now.tv_nsec - ts_start.tv_nsec) / 1000L;
        if (elapsed_us > TIMEOUT_US) {
            return -1.0;  /* echo stuck high — timeout */
        }
    } while (val == 1);

    /* Calculate distance: pulse width in us * 0.0343 / 2 */
    return (float)elapsed_us * SPEED_OF_SOUND / 2.0f;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open GPIO chip 0 (gpiochip0 on Pi Zero W) */
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request trigger as output, initial value low */
    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        fprintf(stderr, "Failed to request trigger line: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request echo as input */
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        fprintf(stderr, "Failed to request echo line: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Open log file */
    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (program_running) {
        char ts[32];
        float distance;

        get_timestamp(ts, sizeof(ts));
        distance = measure_distance(trig, echo);

        if (distance < 0.0f) {
            log_error(fp, ts, "Measurement failed (timeout or sensor absent)");
        } else if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            log_error(fp, ts, "Distance out of range");
        } else {
            log_reading(fp, ts, distance);
        }

        sleep(1);
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fp) fclose(fp);
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

