#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18

#define TRIGGER_PULSE_US  10
#define MEASUREMENT_PERIOD_S 1
#define LOG_FILE_NAME     "distance_log.txt"

#define MIN_PULSE_US  58   /* ~1 cm round-trip */
#define MAX_PULSE_US  25000 /* ~4 m round-trip */

static volatile uint32_t g_pulse_start = 0;
static volatile uint32_t g_pulse_end   = 0;
static volatile int      g_echo_seen   = 0;
static volatile int      g_running     = 1;

static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* ISR callback — runs in pigpio thread, keep it short                  */
/* ------------------------------------------------------------------ */
static void echo_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        /* Rising edge: echo pulse starts */
        g_pulse_start = tick;
        g_echo_seen   = 0;
    } else if (level == 0) {
        /* Falling edge: echo pulse ends */
        g_pulse_end = tick;
        g_echo_seen = 1;
    }
    /* level == 2 indicates a watchdog timeout; ignore here */
}

/* ------------------------------------------------------------------ */
/* Compute (b - a) with correct unsigned 32-bit wraparound             */
/* ------------------------------------------------------------------ */
static uint32_t tick_diff(uint32_t a, uint32_t b)
{
    return b - a;  /* unsigned subtraction wraps correctly */
}

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can clean up                */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Append one distance reading to the log file                         */
/* ------------------------------------------------------------------ */
static void log_distance(float distance)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(g_log_file, "%s, %.2f\n", timestamp, distance) < 0) {
        perror("fprintf to log file failed");
    } else {
        fflush(g_log_file);
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- GPIO configuration ----------------------------------------- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: cannot set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50);  /* let line settle */

    /* --- ISR registration ------------------------------------------ */
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_isr, NULL) < 0) {
        fprintf(stderr, "Error: cannot register ISR on ECHO_PIN %d.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --------------------------------------------- */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers ------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("TRIGGER: GPIO%d | ECHO: GPIO%d | Log: %s\n",
           TRIGGER_PIN, ECHO_PIN, LOG_FILE_NAME);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main measurement loop ------------------------------------- */
    while (g_running) {
        /* Fire 10 us trigger pulse */
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(TRIGGER_PULSE_US);
        gpioWrite(TRIGGER_PIN, 0);

        /* Wait for echo with timeout (1 s max) */
        uint32_t wait_start = gpioTick();
        int got_echo = 0;
        while (!got_echo && g_running) {
            if (tick_diff(wait_start, gpioTick()) > 1000000) {
                break;  /* timeout */
            }
            gpioDelay(1000);  /* 1 ms poll */
            got_echo = g_echo_seen;
        }

        if (!g_running) {
            break;
        }
        if (!got_echo) {
            /* No echo received — sensor may be absent or disconnected */
            fprintf(stderr, "Warning: no echo received on GPIO%d.\n", ECHO_PIN);
            sleep(MEASUREMENT_PERIOD_S);
            continue;
        }

        /* Compute pulse width with wraparound handling */
        uint32_t pulse_us = tick_diff(g_pulse_start, g_pulse_end);

        /* Sanity-check against known physical limits */
        if (pulse_us < MIN_PULSE_US || pulse_us > MAX_PULSE_US) {
            fprintf(stderr, "Warning: pulse %u us out of range [%.0f, %.0f] us.\n",
                    pulse_us, MIN_PULSE_US, MAX_PULSE_US);
            sleep(MEASUREMENT_PERIOD_S);
            continue;
        }

        /* distance = pulse_us * 343 m/s / 2e6 */
        float distance = (float)pulse_us * 343.0f / 2000000.0f;

        printf("Distance: %.2f m  (pulse %u us)\n", distance, pulse_us);
        log_distance(distance);

        /* Sleep for the remainder of the measurement period */
        sleep(MEASUREMENT_PERIOD_S);
    }

    /* --- Cleanup ---------------------------------------------------- */
    printf("\nShutting down...\n");

    /* Disable ISR before tearing down pigpio */
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

