#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x29
#define TRIGGER_PIN    27
#define POLL_DELAY_US  100000  /* 100 ms */

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define REG_SYSTEM_START      0x0018
#define REG_SYSTEM_TIMEOUT    0x0019
#define REG_RESULT_DISTANCE   0x0014
#define REG_RESULT_STATUS     0x0016
#define REG_SYSTEM_RANGE_START 0x0020

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a single byte to a 16-bit register address */
static int vl53l1x_write_byte(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

/* Read N bytes from a 16-bit register address */
static int vl53l1x_read_bytes(int handle, uint16_t reg, uint8_t *data, uint8_t len)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr, 2) < 0)
        return -1;
    return i2cReadDevice(handle, (char *)data, len);
}

static int init_sensor(int handle)
{
    if (vl53l1x_write_byte(handle, REG_SYSTEM_START, 0x00) < 0) {
        syslog(LOG_ERR, "Failed to set continuous mode");
        return -1;
    }
    if (vl53l1x_write_byte(handle, REG_SYSTEM_TIMEOUT, 0x00) < 0) {
        syslog(LOG_ERR, "Failed to set no timeout");
        return -1;
    }
    if (vl53l1x_write_byte(handle, REG_SYSTEM_RANGE_START, 0x01) < 0) {
        syslog(LOG_ERR, "Failed to start ranging");
        return -1;
    }
    return 0;
}

static int read_distance(int handle, uint8_t *distance, uint8_t *status)
{
    uint8_t data[2];
    if (vl53l1x_read_bytes(handle, REG_RESULT_DISTANCE, data, 2) < 0) {
        syslog(LOG_ERR, "Failed to read distance register");
        return -1;
    }
    *distance = data[0];  /* little-endian: low byte first */
    if (vl53l1x_read_bytes(handle, REG_RESULT_STATUS, data, 1) < 0) {
        syslog(LOG_ERR, "Failed to read status register");
        return -1;
    }
    *status = data[0];
    return 0;
}

int main(void)
{
    openlog("vl53l1x_app", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device at bus %d addr 0x%02X", I2C_BUS, I2C_ADDR);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (init_sensor(g_i2c_handle) < 0) {
        syslog(LOG_ERR, "Sensor initialisation failed");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as output", TRIGGER_PIN);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    gpioWrite(TRIGGER_PIN, 1);  /* enable sensor (active low) */

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    syslog(LOG_INFO, "VL53L1X ranging started (bus %d, addr 0x%02X, trigger GPIO%d)",
           I2C_BUS, I2C_ADDR, TRIGGER_PIN);

    while (g_running) {
        uint8_t distance = 0, status = 0;
        if (read_distance(g_i2c_handle, &distance, &status) == 0) {
            time_t now = time(NULL);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", localtime(&now));
            syslog(LOG_INFO, "%s - Distance: %u mm, Status: 0x%02X",
                   ts, distance, status);
        } else {
            syslog(LOG_ERR, "Read failed; continuing");
        }
        gpioDelay(POLL_DELAY_US);
    }

    syslog(LOG_INFO, "Shutting down");
    gpioWrite(TRIGGER_PIN, 0);
    i2cClose(g_i2c_handle);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

