        syslog(LOG_ERR, "Sensor initialisation failed");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as output", TRIGGER_PIN);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    gpioWrite(TRIGGER_PIN, 1);  /* enable sensor (active low) */

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
