    while (g_running) {
        uint8_t distance = 0, status = 0;
        if (read_distance(g_i2c_handle, &distance, &status) == 0) {
            time_t now = time(NULL);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", localtime(&now));
            syslog(LOG_INFO, "%s - Distance: %u mm, Status: 0x%02X",
                   ts, distance, status);
        } else {
            syslog(LOG_ERR, "Read failed; continuing");
        }
        gpioDelay(POLL_DELAY_US);
    }

    syslog(LOG_INFO, "Shutting down");
    gpioWrite(TRIGGER_PIN, 0);
    i2cClose(g_i2c_handle);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

