#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_GPIO 24
#define DISTANCE_THRESHOLD_CM 20.0f
#define POLL_DELAY_US 100000
#define LOG_FILE "gate_log.txt"

/* VL53L1X register addresses */
#define REG_MODEL_ID 0x010F
#define REG_SYS_RANGE_START 0x0015
#define REG_SYS_RANGE_CONFIG 0x0021
#define REG_RESULT_DISTANCE_HI 0x0089
#define REG_RESULT_DISTANCE_LO 0x008A

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_event(const char *msg) {
    if (!g_log_file) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;
    fprintf(g_log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fflush(g_log_file);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint16_t *out) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) != 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint16_t val) {
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (val >> 8) & 0xFF;
    buf[3] = val & 0xFF;
    return (i2cWriteDevice(handle, buf, 4) == 0) ? 0 : -1;
}

static int vl53l1x_init(int handle) {
    uint16_t model_id = 0;
    if (i2c_read_reg16(handle, REG_MODEL_ID, &model_id) != 0) {
        log_event("Error: failed to read model ID");
        return -1;
    }
    if (model_id != 0xEA) {
        char msg[64];
        snprintf(msg, sizeof(msg), "Error: unexpected model ID 0x%04X (expected 0xEA)", model_id);
        log_event(msg);
        return -1;
    }
    if (i2c_write_reg16(handle, REG_SYS_RANGE_CONFIG, 0x00) != 0) {
        log_event("Error: failed to set ranging mode");
        return -1;
    }
    if (i2c_write_reg16(handle, REG_SYS_RANGE_START, 0x01) != 0) {
        log_event("Error: failed to start ranging");
        return -1;
    }
    return 0;
}

static int vl53l1x_read_distance(int handle, float *distance_cm) {
    uint16_t hi = 0, lo = 0;
    if (i2c_read_reg16(handle, REG_RESULT_DISTANCE_HI, &hi) != 0) return -1;
    if (i2c_read_reg16(handle, REG_RESULT_DISTANCE_LO, &lo) != 0) return -1;
    uint16_t raw = ((uint16_t)(uint8_t)hi << 8) | (uint8_t)lo;
    *distance_cm = (float)raw / 10.0f;
    return 0;
}

static void control_gate(int gpio, int open) {
    if (gpioWrite(gpio, open ? 1 : 0) != 0) {
        log_event("Error: failed to write gate GPIO");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen log");
        gpioTerminate();
        return 1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        log_event("Error: i2cOpen failed");
        fclose(g_log_file);
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init(g_i2c_handle) != 0) {
        log_event("Error: VL53L1X initialisation failed");
        i2cClose(g_i2c_handle);
        fclose(g_log_file);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GATE_GPIO, PI_OUTPUT) != 0) {
        log_event("Error: gpioSetMode failed");
        i2cClose(g_i2c_handle);
        fclose(g_log_file);
        gpioTerminate();
        return 1;
    }
    control_gate(GATE_GPIO, 0);

    log_event("System started");

    while (g_running) {
        float distance = 0.0f;
        if (vl53l1x_read_distance(g_i2c_handle, &distance) != 0) {
            log_event("Error: distance read failed");
        } else {
            char msg[64];
            snprintf(msg, sizeof(msg), "Distance: %.2f cm", distance);
            log_event(msg);

            int new_state = (distance < DISTANCE_THRESHOLD_CM) ? 1 : 0;
            if (gpioRead(GATE_GPIO) != new_state) {
                control_gate(GATE_GPIO, new_state);
                snprintf(msg, sizeof(msg), "Gate %s", new_state ? "OPENED" : "CLOSED");
                log_event(msg);
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    log_event("Shutting down");
    control_gate(GATE_GPIO, 0);
    if (g_i2c_handle >= 0) i2cClose(g_i2c_handle);
    if (g_log_file) fclose(g_log_file);
    gpioTerminate();
    return 0;
}

