#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   18

#define SPEED_OF_SOUND 34300.0
#define MIN_DISTANCE   2.0
#define MAX_DISTANCE   400.0
#define MIN_ANGLE      0.0
#define MAX_ANGLE      180.0
#define SERVO_MIN_US   500
#define SERVO_MAX_US   2500
#define MOVING_AVG_SIZE 5
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US 30000
#define LOOP_DELAY_US   100000

static volatile sig_atomic_t running = 1;
static volatile uint32_t g_start_tick = 0;
static volatile uint32_t g_end_tick   = 0;
static volatile int       g_echo_done  = 0;
static volatile int       g_pulse_ok   = 0;
static volatile uint32_t  g_pulse_us   = 0;

static double distance_history[MOVING_AVG_SIZE];
static int    hist_idx = 0;
static int    hist_filled = 0;
static double distance_sum = 0.0;

static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 1) {
        g_start_tick = tick;
        g_echo_done  = 0;
        g_pulse_ok   = 0;
    } else if (level == 0) {
        g_end_tick = tick;
        g_echo_done = 1;
        g_pulse_ok  = 1;
    }
}

static double moving_average(void) {
    distance_sum -= distance_history[hist_idx];
    distance_history[hist_idx] = 0.0;
    distance_sum += distance_history[(hist_idx = (hist_idx + 1) % MOVING_AVG_SIZE)];
    if (hist_filled < MOVING_AVG_SIZE) {
        hist_filled++;
    }
    return distance_sum / (double)hist_filled;
}

static double calculate_distance(uint32_t pulse_us) {
    double dist = (double)pulse_us * SPEED_OF_SOUND / 2000000.0;
    if (dist < MIN_DISTANCE) dist = MIN_DISTANCE;
    if (dist > MAX_DISTANCE) dist = MAX_DISTANCE;
    return dist;
}

static int set_servo_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    int pw = SERVO_MIN_US + (int)((double)angle / 180.0 * (SERVO_MAX_US - SERVO_MIN_US));
    if (gpioServo(SERVO_PIN, pw) < 0) {
        fprintf(stderr, "gpioServo failed for angle %d\n", angle);
        return -1;
    }
    return 0;
}

static void log_data(double distance, int angle) {
    if (log_file == NULL) return;
    fprintf(log_file, "%.3f,%d\n", distance, angle);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set echo pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set servo pin mode\n");
        gpioTerminate();
        return 1;
    }

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(1000);

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Failed to register echo callback\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen("distance_log.csv", "w");
    if (log_file == NULL) {
        perror("Failed to open distance_log.csv");
        gpioTerminate();
        return 1;
    }
    fprintf(log_file, "Distance,Angle\n");
    fflush(log_file);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    for (int i = 0; i < MOVING_AVG_SIZE; i++) {
        distance_history[i] = 0.0;
    }

    while (running) {
        g_echo_done = 0;
        g_pulse_ok  = 0;
        g_start_tick = 0;
        g_end_tick   = 0;

        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(TRIGGER_PULSE_US);
        gpioWrite(TRIGGER_PIN, 0);

        uint32_t wait_start = gpioTick();
        while (!g_echo_done && running) {
            if ((gpioTick() - wait_start) > ECHO_TIMEOUT_US) {
                fprintf(stderr, "Echo timeout\n");
                break;
            }
            gpioDelay(100);
        }

        if (!running) break;

        if (g_pulse_ok) {
            uint32_t pw = g_pulse_us;
            double dist = calculate_distance(pw);
            distance_history[hist_idx] = dist;
            double avg = moving_average();

            int angle = (int)(log10(avg + 0.1) * 50.0 + 90.0);
            if (angle < 0) angle = 0;
            if (angle > 180) angle = 180;

            if (set_servo_angle(angle) == 0) {
                log_data(avg, angle);
            }
        } else {
            fprintf(stderr, "No echo received\n");
            log_data(-1.0, 90);
            set_servo_angle(90);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    gpioServo(SERVO_PIN, 0);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    return 0;
}

