    fprintf(log_file, "Distance,Angle\n");
    fflush(log_file);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    for (int i = 0; i < MOVING_AVG_SIZE; i++) {
        distance_history[i] = 0.0;
    }

    while (running) {
        g_echo_done = 0;
        g_pulse_ok  = 0;
        g_start_tick = 0;
        g_end_tick   = 0;

        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(TRIGGER_PULSE_US);
        gpioWrite(TRIGGER_PIN, 0);

        uint32_t wait_start = gpioTick();
        while (!g_echo_done && running) {
            if ((gpioTick() - wait_start) > ECHO_TIMEOUT_US) {
                fprintf(stderr, "Echo timeout\n");
                break;
            }
            gpioDelay(100);
        }

        if (!running) break;

        if (g_pulse_ok) {
            uint32_t pw = g_pulse_us;
            double dist = calculate_distance(pw);
            distance_history[hist_idx] = dist;
            double avg = moving_average();

            int angle = (int)(log10(avg + 0.1) * 50.0 + 90.0);
            if (angle < 0) angle = 0;
            if (angle > 180) angle = 180;

            if (set_servo_angle(angle) == 0) {
                log_data(avg, angle);
            }
        } else {
            fprintf(stderr, "No echo received\n");
            log_data(-1.0, 90);
            set_servo_angle(90);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    gpioServo(SERVO_PIN, 0);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    return 0;
}

