#define REG_SOFT_RESET              0x0003
#define REG_I2C_SLAVE_DEVICE_ID     0x010F
#define REG_SYSTEM_MODE_START       0x0000
#define REG_SYSTEM_INTERRUPT_CLEAR  0x0086
#define REG_RESULT_INTERRUPT_STATUS 0x0044
#define REG_RESULT_FINAL_CROSSTALK  0x0096
#define REG_RESULT_FINAL_RANGE_MM   0x009E

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char cmd[2];
    cmd[0] = (reg >> 8) & 0xFF;
    cmd[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, cmd, 2) < 0)
        return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

