#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

#define I2C_BUS 1
#define GPIO_PIN 27
#define PROXIMITY_HIGH_REG 0x08
#define PROXIMITY_LOW_REG 0x09
#define DEFAULT_THRESHOLD 1000
#define LOG_FILE "proximity.log"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;
static volatile sig_atomic_t proximity_event = 0;
static volatile int proximity_value = 0;
static volatile int threshold = DEFAULT_THRESHOLD;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio;
    (void)level;
    (void)tick;
    (void)user_data;
    proximity_event = 1;
}

static int read_proximity(int handle, int *out_value) {
    int high = i2cReadByteData(handle, PROXIMITY_HIGH_REG);
    if (high < 0) {
        fprintf(stderr, "Error reading proximity high byte: %s\n", strerror(errno));
        return -1;
    }
    int low = i2cReadByteData(handle, PROXIMITY_LOW_REG);
    if (low < 0) {
        fprintf(stderr, "Error reading proximity low byte: %s\n", strerror(errno));
        return -1;
    }
    *out_value = (high << 8) | low;
    return 0;
}

static void log_proximity(FILE *file, int proximity, int threshold) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    const char *status = "SAFE";
    if (proximity > threshold) {
        status = "ALERT";
    }

    fprintf(file, "%s, Proximity: %d, Status: %s\n", timestamp, proximity, status);
    fflush(file);
}

int main(int argc, char *argv[]) {
    int opt;
    char *endptr;

    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                threshold = strtol(optarg, &endptr, 0);
                if (*endptr != '\0' && *endptr != '\n' && *endptr != '\r') {
                    fprintf(stderr, "Invalid I2C address: %s\n", optarg);
                    return 1;
                }
                break;
            case 't':
                threshold = strtol(optarg, &endptr, 0);
                if (*endptr != '\0' && *endptr != '\n' && *endptr != '\r') {
                    fprintf(stderr, "Invalid threshold: %s\n", optarg);
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, 0x60, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d mode\n", GPIO_PIN);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting ISR for GPIO %d\n", GPIO_PIN);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, NULL, NULL);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    printf("Proximity monitoring started. Threshold: %d\n", threshold);

    while (program_running) {
        if (proximity_event) {
            proximity_event = 0;
            if (read_proximity(i2c_handle, &proximity_value) == 0) {
                log_proximity(log_file, proximity_value, threshold);
            }
        }
        gpioDelay(100000);
    }

    printf("Cleaning up...\n");
    gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, NULL, NULL);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Exiting.\n");
    return 0;
}

