#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define PWM_PIN     18

#define MIN_DISTANCE_CM  2.0f
#define MAX_DISTANCE_CM  200.0f
#define MIN_FREQUENCY_HZ 200
#define MAX_FREQUENCY_HZ 2000
#define PWM_DUTY_CYCLE   128  /* 50% of 255 */

#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  200000  /* 200 ms */
#define LOOP_DELAY_US    10000   /* 10 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Measure distance using the HC-SR04.
 * Returns distance in cm, or -1.0 on timeout/error.
 */
static float measure_distance(void) {
    /* Ensure trigger is low for at least 10 us before pulse */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) return -1.0f;
    gpioDelay(10);

    /* 10 us trigger pulse */
    if (gpioTrigger(TRIGGER_PIN, TRIGGER_PULSE_US, 1) < 0) return -1.0f;

    /* Wait for echo to go high (start of pulse) */
    uint32_t start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - start_tick) > ECHO_TIMEOUT_US) return -1.0f;
    }

    uint32_t echo_start = gpioTick();

    /* Wait for echo to go low (end of pulse) */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - echo_start) > ECHO_TIMEOUT_US) return -1.0f;
    }

    uint32_t echo_end = gpioTick();
    uint32_t pulse_width = echo_end - echo_start;

    /* Speed of sound = 343 m/s = 0.0343 cm/us; round trip / 2 */
    float distance = (float)pulse_width * 0.0343f / 2.0f;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) return -1.0f;

    return distance;
}

/*
 * Map distance to frequency using a logarithmic curve.
 * Returns frequency in Hz, or MIN_FREQUENCY_HZ if distance is out of range.
 */
static int map_distance_to_frequency(float distance) {
    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        return MIN_FREQUENCY_HZ;
    }

    /* Logarithmic mapping: f = 200 * exp(distance / 50) */
    float freq = 200.0f * expf((float)(distance - MIN_DISTANCE_CM) / 50.0f);
    return (int)freq;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set PWM_PIN mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize TRIGGER_PIN low.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start PWM on GPIO18 (hardware PWM0) */
    if (gpioHardwarePWM(PWM_PIN, 0, PWM_DUTY_CYCLE) < 0) {
        fprintf(stderr, "Error: failed to start hardware PWM on GPIO%d.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to install signal handlers.\n");
        gpioHardwarePWM(PWM_PIN, 0, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Theremin started. Move your hand near the sensor to change pitch.\n");
    printf("Press Ctrl+C to exit.\n");

    int current_freq = MIN_FREQUENCY_HZ;

    while (running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            /* Timeout or error: keep current frequency */
            printf("Error: echo timeout or out of range.\n");
        } else {
            int new_freq = map_distance_to_frequency(distance);
            if (new_freq != current_freq) {
                if (gpioHardwarePWM(PWM_PIN, new_freq, PWM_DUTY_CYCLE) < 0) {
                    fprintf(stderr, "Error: gpioHardwarePWM failed for frequency %d.\n", new_freq);
                } else {
                    current_freq = new_freq;
                    printf("Distance: %.1f cm -> Frequency: %d Hz\n", distance, current_freq);
                }
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    gpioHardwarePWM(PWM_PIN, 0, 0);  /* Stop PWM */
    gpioWrite(TRIGGER_PIN, 0);       /* Ensure trigger is low */
    gpioTerminate();

    return EXIT_SUCCESS;
}

