    float freq = 200.0f * expf((float)(distance - MIN_DISTANCE_CM) / 50.0f);
    return (int)freq;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set PWM_PIN mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize TRIGGER_PIN low.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start PWM on GPIO18 (hardware PWM0) */
    if (gpioHardwarePWM(PWM_PIN, 0, PWM_DUTY_CYCLE) < 0) {
        fprintf(stderr, "Error: failed to start hardware PWM on GPIO%d.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to install signal handlers.\n");
        gpioHardwarePWM(PWM_PIN, 0, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Theremin started. Move your hand near the sensor to change pitch.\n");
    printf("Press Ctrl+C to exit.\n");

    int current_freq = MIN_FREQUENCY_HZ;

    while (running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            /* Timeout or error: keep current frequency */
            printf("Error: echo timeout or out of range.\n");
        } else {
            int new_freq = map_distance_to_frequency(distance);
            if (new_freq != current_freq) {
                if (gpioHardwarePWM(PWM_PIN, new_freq, PWM_DUTY_CYCLE) < 0) {
                    fprintf(stderr, "Error: gpioHardwarePWM failed for frequency %d.\n", new_freq);
                } else {
                    current_freq = new_freq;
                    printf("Distance: %.1f cm -> Frequency: %d Hz\n", distance, current_freq);
                }
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    gpioHardwarePWM(PWM_PIN, 0, 0);  /* Stop PWM */
    gpioWrite(TRIGGER_PIN, 0);       /* Ensure trigger is low */
    gpioTerminate();

    return EXIT_SUCCESS;
}

