#define MIN_FREQ 200
#define MAX_FREQ 2000
#define MIN_DIST 5.0
#define MAX_DIST 50.0
#define TIMEOUT_US 100000
#define LOOP_DELAY_US 10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set trigger pin mode\n");
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set echo pin mode\n");
        return -1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set buzzer pin mode\n");
        return -1;
    }

    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on echo pin\n");
        return -1;
    }

    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise trigger pin low\n");
        return -1;
    }

    return 0;
}

static double read_distance(void) {
    uint32_t start_tick, end_tick, timeout_tick;

    if (gpioWrite(TRIGGER_PIN, 1) != 0) {
        fprintf(stderr, "Failed to set trigger high\n");
        return -1.0;
    }
    gpioDelay(10);
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Failed to set trigger low\n");
        return -1.0;
    }

    start_tick = gpioTick();
    timeout_tick = start_tick + TIMEOUT_US;

    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Timeout waiting for echo start\n");
            return -1.0;
        }
    }

    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Timeout waiting for echo end\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_width = end_tick - start_tick;
    double distance = (double)pulse_width * 0.0343 / 2.0;
    return distance;
}

static int set_frequency(int frequency) {
    if (frequency < MIN_FREQ) frequency = MIN_FREQ;
    if (frequency > MAX_FREQ) frequency = MAX_FREQ;

    if (gpioHardwarePWM(BUZZER_PIN, frequency, 500000) != 0) {
        fprintf(stderr, "Failed to set hardware PWM on GPIO%d\n", BUZZER_PIN);
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    double last_distance = 0.0;
    int last_frequency = 0;

    while (running) {
        double distance = read_distance();

        if (distance < 0) {
            fprintf(stderr, "Sensor read failed, using last valid distance: %.2f cm\n", last_distance);
            distance = last_distance;
        } else {
            last_distance = distance;
        }

        int frequency = MIN_FREQ + (int)((MAX_FREQ - MIN_FREQ) * (MAX_DIST - distance) / (MAX_DIST - MIN_DIST));
        if (frequency < MIN_FREQ) frequency = MIN_FREQ;
        if (frequency > MAX_FREQ) frequency = MAX_FREQ;

        if (set_frequency(frequency) != 0) {
            fprintf(stderr, "Failed to set frequency, continuing with last: %d Hz\n", last_frequency);
            frequency = last_frequency;
        } else {
            last_frequency = frequency;
        }

        printf("Distance: %.2f cm, Frequency: %d Hz\n", distance, frequency);
        gpioDelay(LOOP_DELAY_US);
    }

    gpioHardwarePWM(BUZZER_PIN, 0, 0);
    gpioTerminate();
    printf("\nProgram terminated cleanly.\n");
    return 0;
}

