#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define CS_PIN 8

#define REG_MODE 0x01
#define REG_RANGE 0x02
#define REG_DATA_LOW 0x0C
#define REG_DATA_HIGH 0x0D

#define MODE_CONTINUOUS 0x01
#define RANGE_5M 0x00

#define MIN_DISTANCE 200
#define MAX_DISTANCE 5000
#define READ_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_write_register(uint8_t reg, uint8_t value) {
    char tx[2] = { (char)(reg & 0x7F), (char)value };
    char rx[2] = {0};
    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI write to register 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

static int spi_read_register(uint8_t reg, uint8_t *value) {
    char tx[2] = { (char)(reg | 0x80), 0x00 };
    char rx[2] = {0};
    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI read from register 0x%02X failed\n", reg);
        return -1;
    }
    *value = (uint8_t)rx[1];
    return 0;
}

static int initialize_sensor(void) {
    if (spi_write_register(REG_MODE, MODE_CONTINUOUS) != 0) return -1;
    if (spi_write_register(REG_RANGE, RANGE_5M) != 0) return -1;
    if (spi_write_register(REG_MODE, 0x01) != 0) return -1;
    return 0;
}

static int read_distance(uint16_t *distance) {
    uint8_t low = 0, high = 0;
    if (spi_read_register(REG_DATA_LOW, &low) != 0) return -1;
    if (spi_read_register(REG_DATA_HIGH, &high) != 0) return -1;
    *distance = ((uint16_t)high << 8) | low;
    return 0;
}

static void log_distance(uint16_t distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%u\n", timestamp, distance);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, (1 << 8) | SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialisation failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("distance_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        uint16_t distance;
        if (read_distance(&distance) == 0) {
            if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
                log_distance(distance);
            } else {
                fprintf(stderr, "Distance out of range: %u mm\n", distance);
            }
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }
        gpioDelay(READ_DELAY_US);
    }

    if (log_file) fclose(log_file);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

