#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI1175_I2C_ADDR 0x60
#define SI1175_ALS_VIS_DATA0 0x22
#define SI1175_ALS_VIS_DATA1 0x23
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "proximity_log.csv"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        return -1;
    }
    return 0;
}

static int read_ambient_light(int fd, uint16_t *als) {
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, SI1175_ALS_VIS_DATA0, &lo) < 0) {
        return -1;
    }
    if (i2c_read_reg8(fd, SI1175_ALS_VIS_DATA1, &hi) < 0) {
        return -1;
    }
    *als = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int log_data(FILE *fp, uint16_t als) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        return -1;
    }

    if (fprintf(fp, "%s,%u\n", timestamp, als) < 0) {
        return -1;
    }
    if (fflush(fp) != 0) {
        return -1;
    }
    return 0;
}

int main(void) {
    int fd = -1;
    FILE *fp = NULL;
    int ret_code = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        goto cleanup;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open(" I2C_BUS ")");
        goto cleanup;
    }

    if (ioctl(fd, I2C_SLAVE, SI1175_I2C_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        goto cleanup;
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        goto cleanup;
    }

    if (fprintf(fp, "timestamp,als_visible\n") < 0) {
        perror("fprintf(header)");
        goto cleanup;
    }
    if (fflush(fp) != 0) {
        perror("fflush(header)");
        goto cleanup;
    }

    printf("Si1175 ambient light logger started. Logging to %s every %d seconds.\n",
           LOG_FILE, POLL_INTERVAL_SEC);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t als = 0;
        int read_ok = (read_ambient_light(fd, &als) == 0);

        if (read_ok) {
            if (log_data(fp, als) < 0) {
                fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
            } else {
                printf("ALS Visible: %u\n", als);
            }
        } else {
            fprintf(stderr, "Error reading ambient light data: %s\n", strerror(errno));
        }

        if (running) {
            sleep(POLL_INTERVAL_SEC);
        }
    }

    printf("\nExiting gracefully...\n");
    ret_code = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        if (fclose(fp) != 0) {
            perror("fclose");
            ret_code = EXIT_FAILURE;
        }
    }
    if (fd >= 0) {
        if (close(fd) != 0) {
            perror("close");
            ret_code = EXIT_FAILURE;
        }
    }
    return ret_code;
}

