#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SI1120_ADDR        0x60
#define SI1120_REG_PART_ID 0x00
#define SI1120_REG_RESET   0x30
#define SI1120_REG_ALS_DATA0 0x22
#define SI1120_REG_ALS_DATA1 0x23
#define SI1120_REG_PS1_DATA0 0x18
#define SI1120_REG_PS1_DATA1 0x19
#define SI1120_PART_ID     0x41
#define I2C_BUS            1
#define LOG_FILE           "si1120_log.txt"
#define SAMPLE_INTERVAL_US 500000
#define MAX_RETRIES        3
#define RETRY_DELAY_US     10000

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteByteData(handle, reg, value);
        if (rc == 0)
            return 0;
        fprintf(stderr, "I2C write to reg 0x%02X failed (attempt %d/%d, rc=%d)\n",
                reg, attempt + 1, MAX_RETRIES, rc);
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int i2c_read_byte(int handle, uint8_t reg, uint8_t *out)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cReadByteData(handle, reg);
        if (rc >= 0) {
            *out = (uint8_t)rc;
            return 0;
        }
        fprintf(stderr, "I2C read from reg 0x%02X failed (attempt %d/%d, rc=%d)\n",
                reg, attempt + 1, MAX_RETRIES, rc);
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int i2c_read_word(int handle, uint8_t reg_low, uint16_t *out)
{
    uint8_t lo, hi;
    if (i2c_read_byte(handle, reg_low, &lo) != 0)
        return -1;
    if (i2c_read_byte(handle, reg_low + 1, &hi) != 0)
        return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int initialize_sensor(int handle)
{
    if (i2c_write_byte(handle, SI1120_REG_RESET, 0x01) != 0) {
        fprintf(stderr, "Error: failed to reset Si1120\n");
        return -1;
    }
    gpioDelay(10000);

    uint8_t part_id = 0;
    if (i2c_read_byte(handle, SI1120_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Error: failed to read Si1120 part ID\n");
        return -1;
    }
    if (part_id != SI1120_PART_ID) {
        fprintf(stderr, "Error: unexpected part ID 0x%02X (expected 0x%02X)\n",
                part_id, SI1120_PART_ID);
        return -1;
    }
    printf("Si1120 detected (part ID 0x%02X)\n", part_id);
    return 0;
}

static void log_data(FILE *fp, uint16_t als, uint16_t ps1)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, ALS: %u, PS1: %u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, als, ps1);
    fflush(fp);
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SI1120_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (rc=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (initialize_sensor(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: sensor initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging Si1120 data to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (g_running) {
        uint16_t als = 0, ps1 = 0;
        if (i2c_read_word(g_i2c_handle, SI1120_REG_ALS_DATA0, &als) != 0) {
            fprintf(stderr, "Warning: ALS read failed, skipping sample\n");
        } else if (i2c_read_word(g_i2c_handle, SI1120_REG_PS1_DATA0, &ps1) != 0) {
            fprintf(stderr, "Warning: PS1 read failed, skipping sample\n");
        } else {
            log_data(g_log_file, als, ps1);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

