#define SI1182_I2C_ADDR 0x39
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "biometric_log.txt"
#define SAMPLE_INTERVAL_MS 100

/* Si1182-A-GM register addresses */
#define REG_PART_ID      0x00
#define REG_MEAS_RATE    0x08
#define REG_ALS_DATA0    0x22
#define REG_ALS_DATA1    0x23
#define REG_PS_DATA0     0x24
#define REG_PS_DATA1     0x25

#define EXPECTED_PART_ID 0x82

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg 0x%02X, val 0x%02X) failed: %s\n", reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_sensor(int fd) {
    uint8_t part_id = 0;
    if (i2c_read_reg8(fd, REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Cannot read part ID - sensor may be absent or bus error.\n");
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected part ID: 0x%02X (expected 0x%02X). Wrong sensor?\n", part_id, EXPECTED_PART_ID);
        return -1;
    }
    printf("Si1182 detected (part ID 0x%02X).\n", part_id);

    if (i2c_write_reg8(fd, REG_MEAS_RATE, 0x07) != 0) {
        fprintf(stderr, "Failed to configure measurement rate.\n");
        return -1;
    }
    return 0;
}

static int read_sensor_data(int fd, float *lux, int *proximity) {
    uint8_t als_low = 0, als_high = 0, ps_low = 0, ps_high = 0;

    if (i2c_read_reg8(fd, REG_ALS_DATA0, &als_low) != 0) return -1;
    if (i2c_read_reg8(fd, REG_ALS_DATA1, &als_high) != 0) return -1;
    if (i2c_read_reg8(fd, REG_PS_DATA0, &ps_low) != 0) return -1;
    if (i2c_read_reg8(fd, REG_PS_DATA1, &ps_high) != 0) return -1;

    uint16_t als_raw = (uint16_t)((als_high << 8) | als_low);
    uint16_t ps_raw  = (uint16_t)((ps_high << 8) | ps_low);

    *lux = (float)als_raw * 0.1f;
    *proximity = (int)ps_raw;
    return 0;
}

static void log_data(FILE *fp, float lux, int proximity) {
    struct timespec ts;
    struct tm tm_info;
    char timestamp[32];

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    fprintf(fp, "%s,%.2f,%d\n", timestamp, lux, proximity);
    fflush(fp);
    printf("%s,%.2f,%d\n", timestamp, lux, proximity);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1182_I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n", SI1182_I2C_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (init_sensor(g_i2c_fd) != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("Logging to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (g_running) {
        float lux = 0.0f;
        int proximity = 0;
        if (read_sensor_data(g_i2c_fd, &lux, &proximity) == 0) {
            log_data(g_log_fp, lux, proximity);
        } else {
            fprintf(stderr, "Sensor read error - continuing.\n");
        }
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    if (g_log_fp) fclose(g_log_fp);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return EXIT_SUCCESS;
}

