#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SI1145_ADDR 0x60
#define I2C_BUS 1

/* Si1145 register addresses */
#define REG_HW_KEY          0x07
#define REG_MEAS_RATE       0x06
#define REG_IRQ_ENABLE      0x01
#define REG_IRQ_MODE1       0x02
#define REG_IRQ_MODE2       0x03
#define REG_ALS_VIS_ADC_COUNTER 0x21
#define REG_ALS_VIS_ADC_GAIN   0x24
#define REG_PS_ADC_COUNTER     0x22
#define REG_PS_LED21          0x0C
#define REG_PS_LED3           0x0F
#define REG_PS_ADC_MISC       0x11
#define REG_PS_ADC_GAIN       0x0D
#define REG_COMMAND          0x80
#define REG_PS1_DATA0        0x16
#define REG_PS1_DATA1        0x17

#define HW_KEY_VAL 0x03
#define CMD_PS_FORCE 0x03

#define MAX_RETRIES 3
#define RETRY_DELAY_US 1000000
#define LOOP_DELAY_US  100000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed: reg=0x%02X, val=0x%02X, rc=%d\n", reg, val, rc);
    }
    return rc;
}

static int init_si1145(int handle) {
    int rc;

    rc = write_reg(handle, REG_HW_KEY, HW_KEY_VAL);
    if (rc < 0) return -1;

    rc = write_reg(handle, REG_MEAS_RATE, 0x02);
    if (rc < 0) return -1;

    rc = write_reg(handle, REG_IRQ_ENABLE, 0x00);
    if (rc < 0) return -1;

    rc = write_reg(handle, REG_IRQ_MODE1, 0x00);
    if (rc < 0) return -1;

    rc = write_reg(handle, REG_IRQ_MODE2, 0x00);
    if (rc < 0) return -1;

    rc = write_reg(handle, REG_ALS_VIS_ADC_COUNTER, 0x0B);
    if (rc < 0) return -1;

    rc = write_reg(handle, REG_ALS_VIS_ADC_GAIN, 0x00);
    if (rc < 0) return -1;

    rc = write_reg(handle, REG_PS_ADC_COUNTER, 0x49);
    if (rc < 0) return -1;

    rc = write_reg(handle, REG_PS_LED21, 0x03);
    if (rc < 0) return -1;

    rc = write_reg(handle, REG_PS_LED3, 0x0F);
    if (rc < 0) return -1;

    rc = write_reg(handle, REG_PS_ADC_MISC, 0x03);
    if (rc < 0) return -1;

    rc = write_reg(handle, REG_PS_ADC_GAIN, 0x07);
    if (rc < 0) return -1;

    rc = write_reg(handle, REG_COMMAND, CMD_PS_FORCE);
    if (rc < 0) return -1;

    return 0;
}

static int read_proximity(int handle, uint16_t *prox) {
    int lo = i2cReadByteData(handle, REG_PS1_DATA0);
    if (lo < 0) {
        fprintf(stderr, "I2C read failed: reg=0x%02X, rc=%d\n", REG_PS1_DATA0, lo);
        return -1;
    }
    int hi = i2cReadByteData(handle, REG_PS1_DATA1);
    if (hi < 0) {
        fprintf(stderr, "I2C read failed: reg=0x%02X, rc=%d\n", REG_PS1_DATA1, hi);
        return -1;
    }
    *prox = (uint16_t)((hi << 8) | lo);
    return 0;
}

static void log_data(FILE *fp, uint16_t prox) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Proximity: %u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, prox);
    fflush(fp);
}

static void log_error(FILE *fp, const char *msg) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, ERROR: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_si1145(i2c_handle) != 0) {
        fprintf(stderr, "Si1145 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        perror("fopen");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Si1145 proximity logger started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        uint16_t prox = 0;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && !terminate; attempt++) {
            if (read_proximity(i2c_handle, &prox) == 0) {
                ok = 1;
                break;
            }
            if (attempt < MAX_RETRIES - 1) {
                gpioDelay(RETRY_DELAY_US);
            }
        }

        if (ok) {
            log_data(log_file, prox);
        } else {
            log_error(log_file, "Proximity read failed after retries");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    printf("Done.\n");
    return 0;
}

