#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27
#define DISTANCE_THRESHOLD_CM 20.0
#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define TRIGGER_PULSE_US 10
#define MEASUREMENT_TIMEOUT_US 30000

static volatile int running = 1;
static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_received = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;
    if (level == 1) {
        start_tick = tick;
        echo_received = 0;
    } else if (level == 0 && start_tick != 0) {
        end_tick = tick;
        echo_received = 1;
    }
}

static int initialize_gpio(void) {
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output\n", TRIGGER_PIN);
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input\n", ECHO_PIN);
        return -1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set BUZZER_PIN %d as output\n", BUZZER_PIN);
        return -1;
    }
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to reset TRIGGER_PIN %d low\n", TRIGGER_PIN);
        return -1;
    }
    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to reset BUZZER_PIN %d low\n", BUZZER_PIN);
        return -1;
    }
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: failed to register alert callback on ECHO_PIN %d\n", ECHO_PIN);
        return -1;
    }
    return 0;
}

static void trigger_sensor(void) {
    if (gpioWrite(TRIGGER_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d high\n", TRIGGER_PIN);
        return;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d low\n", TRIGGER_PIN);
    }
}

static float measure_distance(void) {
    start_tick = 0;
    end_tick = 0;
    echo_received = 0;
    trigger_sensor();
    uint32_t elapsed = 0;
    while (!echo_received && elapsed < MEASUREMENT_TIMEOUT_US) {
        gpioDelay(100);
        elapsed += 100;
    }
    if (!echo_received) {
        fprintf(stderr, "Warning: echo timeout - sensor may be disconnected\n");
        return -1.0f;
    }
    uint32_t pulse_width = end_tick - start_tick;
    return (float)pulse_width * SPEED_OF_SOUND_CM_PER_US / 2.0f;
}

static void control_buzzer(float distance) {
    if (distance < DISTANCE_THRESHOLD_CM) {
        if (gpioWrite(BUZZER_PIN, 1) != 0) {
            fprintf(stderr, "Error: failed to set BUZZER_PIN %d high\n", BUZZER_PIN);
        }
    } else {
        if (gpioWrite(BUZZER_PIN, 0) != 0) {
            fprintf(stderr, "Error: failed to set BUZZER_PIN %d low\n", BUZZER_PIN);
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    if (initialize_gpio() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to register SIGINT handler\n");
    }
    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");
    while (running) {
        float distance = measure_distance();
        if (distance >= 0.0f) {
            printf("Distance: %.2f cm\n", distance);
            control_buzzer(distance);
        } else {
            fprintf(stderr, "Error: failed to measure distance\n");
        }
        sleep(1);
    }
    printf("\nShutting down...\n");
    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

