#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

#define SPEED_OF_SOUND 34300.0
#define MIN_DISTANCE 20.0
#define MAX_DISTANCE 110.0
#define MIN_SERVO_PULSE 500
#define MAX_SERVO_PULSE 2500
#define ECHO_TIMEOUT_US 30000
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static double measure_distance(void) {
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(2);
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);

    uint32_t start_tick = 0, end_tick = 0;
    int timeout = 0;

    while (gpioRead(ECHO_PIN) == 0) {
        if (timeout++ > ECHO_TIMEOUT_US) return -1.0;
        gpioDelay(1);
    }
    start_tick = gpioTick();

    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1) {
        if (timeout++ > ECHO_TIMEOUT_US) return -1.0;
        gpioDelay(1);
    }
    end_tick = gpioTick();

    double pulse_duration = (double)(end_tick - start_tick);
    double distance = (pulse_duration * SPEED_OF_SOUND) / 2000.0;
    return distance;
}

static int set_servo_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    int pulse_width = MIN_SERVO_PULSE + (angle * (MAX_SERVO_PULSE - MIN_SERVO_PULSE)) / 180;
    gpioServo(SERVO_PIN, pulse_width);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    while (running) {
        double distance = measure_distance();
        if (distance < 0) {
            fprintf(stderr, "Error: sensor timeout or out of range\n");
        } else {
            int angle = (int)((distance - MIN_DISTANCE) * (180.0 / (MAX_DISTANCE - MIN_DISTANCE)));
            if (angle < 0) angle = 0;
            if (angle > 180) angle = 180;
            set_servo_angle(angle);
            printf("Distance: %.2f cm, Angle: %d degrees\n", distance, angle);
        }
        gpioDelay(LOOP_DELAY_US);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    return 0;
}

