#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7005_ADDR 0x40
#define TEMP_REG 0x01
#define HUM_REG 0x02
#define CONFIG_REG 0x03
#define CONFIG_VALUE 0x00

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, SI7005_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int configure_sensor(void) {
    if (i2cWriteByteData(i2c_handle, CONFIG_REG, CONFIG_VALUE) < 0) {
        fprintf(stderr, "Error writing CONFIG register 0x%02X\n", CONFIG_REG);
        return -1;
    }
    gpioDelay(10000); /* 10 ms */
    return 0;
}

static int read_register(uint8_t reg, uint16_t *value) {
    int raw = i2cReadWordData(i2c_handle, reg);
    if (raw < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, raw);
        return -1;
    }
    *value = (uint16_t)raw;
    return 0;
}

static int read_sensor(float *temperature, float *humidity) {
    uint16_t raw_temp, raw_hum;

    if (read_register(TEMP_REG, &raw_temp) < 0) return -1;
    if (read_register(HUM_REG, &raw_hum) < 0) return -1;

    *temperature = (175.72f * (float)raw_temp) / 65536.0f - 46.85f;
    *humidity = (125.0f * (float)raw_hum) / 65536.0f - 6.0f;

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_i2c() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (configure_sensor() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        float temperature, humidity;

        if (read_sensor(&temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Sensor read failed; attempting I2C recovery...\n");
            if (init_i2c() < 0) {
                fprintf(stderr, "Recovery failed; exiting.\n");
                break;
            }
            if (configure_sensor() < 0) {
                fprintf(stderr, "Recovery failed; exiting.\n");
                break;
            }
        }

        gpioDelay(2000000); /* 2 seconds */
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

