#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define MPU6050_WHO_AM_I    0x75
#define MPU6050_WHO_AM_I_VAL 0x68
#define MPU6050_PWR_MGMT_1  0x6B
#define MPU6050_SMPLRT_DIV  0x19
#define MPU6050_CONFIG     0x1A
#define MPU6050_GYRO_CONFIG 0x1B
#define MPU6050_ACCEL_CONFIG 0x1C
#define MPU6050_ACCEL_XOUT_H 0x3B

/* Globals for signal handler */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Write one byte to an MPU-6050 register; returns 0 on success, -1 on error */
static int mpu_write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X (rc=%d)\n", value, reg, rc);
        return -1;
    }
    return 0;
}

/* Read one byte from an MPU-6050 register; returns value >= 0 on success, -1 on error */
static int mpu_read_reg(int handle, uint8_t reg) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X (rc=%d)\n", reg, rc);
        return -1;
    }
    return rc;
}

/* Read a 16-bit big-endian value from two consecutive registers; returns 0 on success, -1 on error */
static int mpu_read_word(int handle, uint8_t reg) {
    int hi = mpu_read_reg(handle, reg);
    if (hi < 0) return -1;
    int lo = mpu_read_reg(handle, reg + 1);
    if (lo < 0) return -1;
    return (hi << 8) | (lo & 0xFF);
}

/* Initialise the MPU-6050; returns 0 on success, -1 on error */
static int mpu6050_init(int handle) {
    /* Verify device identity */
    int who = mpu_read_reg(handle, MPU6050_WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Cannot read WHO_AM_I - sensor may be absent\n");
        return -1;
    }
    if (who != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who, MPU6050_WHO_AM_I_VAL);
        return -1;
    }

    /* Reset the device */
    if (mpu_write_reg(handle, MPU6050_PWR_MGMT_1, 0x80) < 0) return -1;
    gpioDelay(100000); /* 100 ms reset wait */

    /* Wake up: clear sleep bit, use internal 8 MHz oscillator */
    if (mpu_write_reg(handle, MPU6050_PWR_MGMT_1, 0x00) < 0) return -1;
    gpioDelay(10000); /* 10 ms stabilise */

    /* Sample rate divider = 7 -> 1 kHz / (1 + 7) = 125 Hz */
    if (mpu_write_reg(handle, MPU6050_SMPLRT_DIV, 0x07) < 0) return -1;

    /* DLPF config = 0 -> bandwidth 256 Hz, delay 0 */
    if (mpu_write_reg(handle, MPU6050_CONFIG, 0x00) < 0) return -1;

    /* Gyro full scale ±250 deg/s */
    if (mpu_write_reg(handle, MPU6050_GYRO_CONFIG, 0x00) < 0) return -1;

    /* Accel full scale ±2 g */
    if (mpu_write_reg(handle, MPU6050_ACCEL_CONFIG, 0x00) < 0) return -1;

    return 0;
}

/* Read accelerometer and gyroscope data; returns 0 on success, -1 on error */
static int mpu6050_read_data(int handle, int16_t *ax, int16_t *ay, int16_t *az,
                             int16_t *gx, int16_t *gy, int16_t *gz) {
    char buf[14];
    int rc = i2cReadI2CBlockData(handle, MPU6050_ACCEL_XOUT_H, buf, 14);
    if (rc != 14) {
        fprintf(stderr, "Error reading data block (rc=%d)\n", rc);
        return -1;
    }

    *ax = (int16_t)((buf[0]  << 8) | (uint8_t)buf[1]);
    *ay = (int16_t)((buf[2]  << 8) | (uint8_t)buf[3]);
    *az = (int16_t)((buf[4]  << 8) | (uint8_t)buf[5]);
    /* buf[6..7] = temperature (skipped) */
    *gx = (int16_t)((buf[8]  << 8) | (uint8_t)buf[9]);
    *gy = (int16_t)((buf[10] << 8) | (uint8_t)buf[11]);
    *gz = (int16_t)((buf[12] << 8) | (uint8_t)buf[13]);
    return 0;
}

int main(void) {
    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the MPU-6050 address */
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X (rc=%d)\n", MPU6050_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialise the sensor */
    if (mpu6050_init(i2c_handle) < 0) {
        fprintf(stderr, "MPU-6050 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MPU-6050 initialised on I2C bus 1, address 0x%02X. Reading every 100 ms (Ctrl+C to stop).\n",
           MPU6050_ADDR);

    /* Main sampling loop */
    while (!terminate) {
        int16_t ax, ay, az, gx, gy, gz;

        if (mpu6050_read_data(i2c_handle, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
            printf("Accel: X=%6d Y=%6d Z=%6d  |  Gyro: X=%6d Y=%6d Z=%6d\n",
                   ax, ay, az, gx, gy, gz);
        } else {
            fprintf(stderr, "Read failed - continuing\n");
        }

        gpioDelay(100000); /* 100 ms */
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

