#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define STS30_ADDR 0x4A
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"
#define SAMPLE_INTERVAL_SEC 5
#define MEASUREMENT_DELAY_US 20000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_fp = NULL;
static FILE *error_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *msg) {
    if (!error_fp) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(error_fp, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fflush(error_fp);
}

static int read_temperature(float *temp) {
    char cmd[2] = {0x36, 0x2F};
    char buf[3];

    if (i2cWriteDevice(i2c_handle, cmd, 2) != 0) {
        log_error("I2C write failed (sensor absent or bus error)");
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_US);

    if (i2cReadDevice(i2c_handle, buf, 3) != 3) {
        log_error("I2C read failed (sensor absent or bus error)");
        return -1;
    }

    int16_t raw = (buf[0] << 8) | buf[1];
    *temp = (float)raw / 200.0f;
    return 0;
}

static void log_temperature(float temp) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_fp, "[%d-%02d-%02d %02d:%02d:%02d] Temperature: %.2f C\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, temp);
    fflush(log_fp);
}

int main(void) {
