        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Smart Greenhouse Monitor started. Logging to %s every %d seconds.\n", LOG_FILE, POLL_INTERVAL_S);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        float temperature, humidity;
        if (read_sht40(fd, &temperature, &humidity) == 0) {
            log_data(fp, temperature, humidity);
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }
        sleep(POLL_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    fclose(fp);
    close(fd);
    return EXIT_SUCCESS;
}

