#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x28
#define LOG_FILE       "airflow.log"
#define SAMPLE_US      100000   /* 100 ms */
#define MEAS_DELAY_US  1000     /* 1 ms  */
#define MAX_RETRIES    3
#define RETRY_BASE_US  10000    /* 10 ms */

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Sensirion CRC-8 polynomial 0x31, init 0xFF */
static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int trigger_measurement(void) {
    uint8_t cmd[2] = {0x21, 0x96};
    int retries = 0;
    int delay = RETRY_BASE_US;

    while (retries < MAX_RETRIES) {
        int rc = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
        if (rc == 0)
            return 0;
        fprintf(stderr, "I2C write failed (attempt %d/%d): %d\n",
                retries + 1, MAX_RETRIES, rc);
        retries++;
        gpioDelay(delay);
        delay = (delay * 2 > 1000000) ? 1000000 : delay * 2;
    }
    return -1;
}

static int read_sensor_data(sensor_data_t *data) {
    uint8_t buf[6];
    int retries = 0;
    int delay = RETRY_BASE_US;

    while (retries < MAX_RETRIES) {
        if (trigger_measurement() != 0) {
            retries++;
            gpioDelay(delay);
            delay = (delay * 2 > 1000000) ? 1000000 : delay * 2;
            continue;
        }

        gpioDelay(MEAS_DELAY_US);

        int rc = i2cReadDevice(i2c_handle, (char *)buf, 6);
        if (rc == 6)
            break;

        fprintf(stderr, "I2C read failed (attempt %d/%d): %d\n",
                retries + 1, MAX_RETRIES, rc);
        retries++;
        gpioDelay(delay);
        delay = (delay * 2 > 1000000) ? 1000000 : delay * 2;
    }

    if (retries >= MAX_RETRIES) {
        fprintf(stderr, "Max retries reached for sensor read.\n");
        return -1;
    }

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Pressure CRC mismatch.\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Temperature CRC mismatch.\n");
        return -1;
    }

    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);

    data->pressure = (float)raw_pressure / 60.0f;
    data->temperature = (float)raw_temperature / 200.0f;
    return 0;
}

static int log_data(const sensor_data_t *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "localtime failed.\n");
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data->pressure, data->temperature) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return 1;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            if (log_data(&sensor_data) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }
        gpioDelay(SAMPLE_US);
    }

    cleanup();
    return 0;
}

