#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI7015_ADDR    0x40
#define CMD_TEMP       0xF3
#define CMD_HUMID      0xF5
#define LOG_FILE       "sensor_data.txt"
#define SAMPLE_US      5000000  /* 5 seconds */
#define MEAS_TIMEOUT   20000    /* 20 ms max wait for a single measurement */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Read a 16-bit raw value from the Si7015 in No Hold Master mode.
 * Returns 0 on success, -1 on I2C error. */
static int read_raw(int handle, uint8_t cmd, uint16_t *raw)
{
    char buf[2];
    int  rc;

    /* Send the measurement command (no register, just the command byte). */
    rc = i2cWriteByte(handle, cmd);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X): %s\n",
                cmd, pigpio_error(rc));
        return -1;
    }

    /* Poll until the sensor is ready (data is valid). */
    for (int elapsed = 0; elapsed < MEAS_TIMEOUT; elapsed += 1000) {
        gpioDelay(1000); /* 1 ms */

        rc = i2cReadDevice(handle, buf, 2);
        if (rc == 2) {
            *raw = ((uint16_t)(buf[0] << 8)) | (uint8_t)buf[1];
            return 0;
        }
        if (rc < 0) {
            fprintf(stderr, "I2C read failed (cmd 0x%02X): %s\n",
                    cmd, pigpio_error(rc));
            return -1;
        }
        /* rc == 0 means no data yet — keep polling. */
    }

    fprintf(stderr, "Si7015 measurement timeout (cmd 0x%02X)\n", cmd);
    return -1;
}

static float convert_temperature(uint16_t raw)
{
    return (175.72f * (float)raw / 65536.0f) - 46.85f;
}

static float convert_humidity(uint16_t raw)
{
    float rh = (125.0f * (float)raw / 65536.0f) - 6.0f;
    if (rh < 0.0f)   rh = 0.0f;
    if (rh > 100.0f) rh = 100.0f;
    return rh;
}

static void log_data(float temperature, float humidity)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Temperature: %.2f C, Humidity: %.2f %%RH\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                temperature, humidity);
    } else {
        fprintf(fp, "Timestamp error, Temperature: %.2f C, Humidity: %.2f %%RH\n",
                temperature, humidity);
    }

    if (fclose(fp) != 0)
        fprintf(stderr, "Error closing %s: %s\n", LOG_FILE, strerror(errno));
}

int main(void)
{
    /* Install signal handler for clean shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SI7015_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, SI7015_ADDR, pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si7015 sensor logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t raw_temp = 0, raw_hum = 0;
        int ok = 1;

        if (read_raw(g_i2c_handle, CMD_TEMP, &raw_temp) != 0) {
            fprintf(stderr, "Temperature read failed; retrying next cycle.\n");
            ok = 0;
        }

        if (ok && read_raw(g_i2c_handle, CMD_HUMID, &raw_hum) != 0) {
            fprintf(stderr, "Humidity read failed; retrying next cycle.\n");
            ok = 0;
        }

        if (ok) {
            float temperature = convert_temperature(raw_temp);
            float humidity    = convert_humidity(raw_hum);
            log_data(temperature, humidity);
            printf("Temperature: %.2f C, Humidity: %.2f %%RH\n",
                   temperature, humidity);
        }

        /* Sleep in 100 ms slices so SIGINT is caught promptly. */
        for (int i = 0; i < 50 && g_running; i++)
            gpioDelay(100000);
    }

    /* Clean shutdown. */
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

