#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define STS30_ADDR 0x4A
#define MEASURE_CMD_HIGH_REP 0x2C06
#define CONVERSION_DELAY_US 15000
#define SAMPLE_INTERVAL_S 5
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (!fp) {
        perror("Failed to open error log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s - ERROR: %s\n", timestamp, message);
    fclose(fp);
}

static int initialize_i2c(void) {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int read_temperature(float *temperature) {
    char cmd[2] = {(MEASURE_CMD_HIGH_REP >> 8) & 0xFF, MEASURE_CMD_HIGH_REP & 0xFF};
    if (i2cWriteDevice(i2c_handle, cmd, 2) != 0) {
        log_error("Failed to write measurement command to I2C device");
        return -1;
    }
    gpioDelay(CONVERSION_DELAY_US);
    char buffer[3];
    if (i2cReadDevice(i2c_handle, buffer, 3) != 3) {
        log_error("Failed to read 3 bytes from I2C device");
        return -1;
    }
    unsigned int raw = ((unsigned int)(buffer[0] << 8) | (unsigned int)buffer[1]) & 0xFFFF;
    unsigned char crc = 0xFF;
    for (int i = 0; i < 2; i++) {
        crc ^= (unsigned char)buffer[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    if (crc != (unsigned char)buffer[2]) {
        log_error("CRC mismatch on temperature data");
        return -1;
    }
    *temperature = -45.0f + (175.0f * (float)raw / 65535.0f);
    return 0;
}

static void log_temperature(float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        log_error("Failed to open log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s - Temperature: %.2f C\n", timestamp, temperature);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }
    if (initialize_i2c() != 0) {
        return 1;
    }
    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");
    while (!terminate) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            log_temperature(temperature);
            printf("Temperature: %.2f C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }
        sleep(SAMPLE_INTERVAL_S);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Temperature monitoring stopped.\n");
    return 0;
}

