#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define FAN_GPIO 18
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define BUFFER_SIZE 60
#define MEASUREMENT_DELAY_US 10000
#define MAX_RETRIES 3
#define RETRY_DELAY_US 1000

#define CMD_TEMP_HOLD 0xE3
#define CMD_HUMID_HOLD 0xE5

typedef struct {
    time_t timestamp;
    float temperature;
    float humidity;
} SensorData;

typedef struct {
    SensorData data[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static int i2c_handle = -1;
static CircularBuffer buffer;
static volatile sig_atomic_t running = 1;

static void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

static void add_to_buffer(CircularBuffer *cb, SensorData data) {
    cb->data[cb->head] = data;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static void log_data(SensorData data) {
    char timestamp_str[32];
    struct tm *tm_info = localtime(&data.timestamp);
    if (tm_info) {
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", tm_info);
        printf("%s - Temperature: %.2f C, Humidity: %.2f %%\n",
               timestamp_str, data.temperature, data.humidity);
    } else {
        printf("(timestamp error) - Temperature: %.2f C, Humidity: %.2f %%\n",
               data.temperature, data.humidity);
    }
}

static int read_sensor_data(uint8_t cmd, uint16_t *raw_value) {
    char buf[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteByte(i2c_handle, cmd) != 0) {
            fprintf(stderr, "Error: Failed to write command 0x%02X (attempt %d/%d)\n",
                    cmd, retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_US);

        if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
            fprintf(stderr, "Error: Failed to read 2 bytes for command 0x%02X (attempt %d/%d)\n",
                    cmd, retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        *raw_value = ((uint16_t)(buf[0] << 8)) | (uint8_t)buf[1];
        return 0;
    }

    fprintf(stderr, "Error: Failed to read sensor data for command 0x%02X after %d retries\n",
            cmd, MAX_RETRIES);
    return -1;
}

static float convert_temperature(uint16_t raw_temp) {
    return (175.72f * (float)raw_temp / 65536.0f) - 46.85f;
}

static float convert_humidity(uint16_t raw_hum) {
    return (125.0f * (float)raw_hum / 65536.0f) - 6.0f;
}

static void control_fan(float temperature) {
    static int fan_on = 0;

    if (temperature > TEMP_THRESHOLD_HIGH && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = 1;
            printf("Fan turned ON (Temperature: %.2f C)\n", temperature);
        } else {
            fprintf(stderr, "Error: Failed to turn fan ON\n");
        }
    } else if (temperature < TEMP_THRESHOLD_LOW && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_on = 0;
            printf("Fan turned OFF (Temperature: %.2f C)\n", temperature);
        } else {
            fprintf(stderr, "Error: Failed to turn fan OFF\n");
        }
    }
}

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(FAN_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X (code: %d)\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as output\n", FAN_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    init_circular_buffer(&buffer);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler\n");
    }

    printf("Si7021 monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t raw_temp = 0, raw_hum = 0;

        if (read_sensor_data(CMD_TEMP_HOLD, &raw_temp) != 0) {
            fprintf(stderr, "Sensor absent or unresponsive (temperature read failed)\n");
            gpioDelay(2000000);
            continue;
        }

        if (read_sensor_data(CMD_HUMID_HOLD, &raw_hum) != 0) {
            fprintf(stderr, "Sensor absent or unresponsive (humidity read failed)\n");
            gpioDelay(2000000);
            continue;
        }

        SensorData data;
        data.timestamp = time(NULL);
        data.temperature = convert_temperature(raw_temp);
        data.humidity = convert_humidity(raw_hum);

        add_to_buffer(&buffer, data);
        log_data(data);
        control_fan(data.temperature);

        gpioDelay(2000000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

