#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SCD40_ADDR 0x62
#define I2C_BUS 1
#define LOG_FILE "air_quality.log"
#define POLL_INTERVAL_US 5000000
#define MEASUREMENT_DELAY_US 1000000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int send_command(uint16_t command) {
    uint8_t buf[2] = { (command >> 8) & 0xFF, command & 0xFF };
    int result = i2cWriteDevice(i2c_handle, (char *)buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error sending command 0x%04X: %d\n", command, result);
        return -1;
    }
    return 0;
}

static int read_data(uint8_t *data, int len) {
    int result = i2cReadDevice(i2c_handle, (char *)data, len);
    if (result != len) {
        fprintf(stderr, "Error reading data: expected %d bytes, got %d\n", len, result);
        return -1;
    }
    return 0;
}

static int is_data_ready(void) {
    if (send_command(0xE4B8) != 0) return -1;
    gpioDelay(10000);
    uint8_t buf[3];
    if (read_data(buf, 3) != 0) return -1;
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC error in data-ready response\n");
        return -1;
    }
    uint16_t status = (buf[0] << 8) | buf[1];
    return (status & 0x07FF) != 0;
}

static int read_sensor_data(sensor_data_t *data) {
    if (send_command(0xEC05) != 0) return -1;
    gpioDelay(10000);
    uint8_t buf[9];
    if (read_data(buf, 9) != 0) return -1;

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC error in CO2 data\n");
        return -1;
    }
    if (crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "CRC error in temperature data\n");
        return -1;
    }
    if (crc8(buf + 6, 2) != buf[8]) {
        fprintf(stderr, "CRC error in humidity data\n");
        return -1;
    }

    data->co2 = (buf[0] << 8) | buf[1];
    uint16_t temp_raw = (buf[3] << 8) | buf[4];
    uint16_t hum_raw = (buf[6] << 8) | buf[7];
    data->temperature = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
    data->humidity = 100.0f * (float)hum_raw / 65535.0f;
    return 0;
}

static void log_data(const sensor_data_t *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%.2f,%.2f\n", timestamp, data->co2, data->temperature, data->humidity);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        send_command(0x3F86);
        gpioDelay(100000);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (send_command(0x21B1) != 0) {
        fprintf(stderr, "Error starting periodic measurement\n");
        cleanup();
        return 1;
    }
    gpioDelay(MEASUREMENT_DELAY_US);

    sensor_data_t sensor_data;
    while (!terminate) {
        int ready = is_data_ready();
        if (ready < 0) {
            fprintf(stderr, "Error checking data readiness\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }
        if (ready == 0) {
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (read_sensor_data(&sensor_data) == 0) {
            log_data(&sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    cleanup();
    return 0;
}

