    uint8_t buf[3];
    if (i2c_read_data(handle, buf, 3) != 0) return -1;
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on data-ready word\n");
        return -1;
    }
    uint16_t word = (buf[0] << 8) | buf[1];
    *ready = (word & 0x07FF) != 0;
    return 0;
}

static int scd40_read_measurement(int handle, uint16_t *co2, float *temp, float *hum) {
    if (i2c_write_cmd(handle, CMD_READ_MEASUREMENT) != 0) return -1;
    gpioDelay(2000);
    uint8_t buf[9];
    if (i2c_read_data(handle, buf, 9) != 0) return -1;

    for (int i = 0; i < 3; i++) {
        if (crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "CRC mismatch on word %d\n", i);
            return -1;
        }
    }

    *co2 = (buf[0] << 8) | buf[1];
    uint16_t t_raw = (buf[3] << 8) | buf[4];
    uint16_t h_raw = (buf[6] << 8) | buf[7];
    *temp = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *hum  = 100.0f * (float)h_raw / 65535.0f;
    return 0;
}

static void control_led(int gpio, float co2) {
    gpioWrite(gpio, (co2 > CO2_THRESHOLD) ? 1 : 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, I2C_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    buffer_init(&buffer);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (scd40_start_periodic(i2c_handle) != 0) {
        fprintf(stderr, "Failed to start periodic measurement\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("SCD40 periodic measurement started. Waiting for first data...\n");

    while (!terminate) {
        bool ready = false;
        if (scd40_data_ready(i2c_handle, &ready) != 0) {
            fprintf(stderr, "Error checking data-ready status\n");
            gpioDelay(MEASUREMENT_INTERVAL_S * 1000000);
            continue;
        }
        if (!ready) {
            gpioDelay(100000);
            continue;
        }

        uint16_t co2;
        float temp, hum;
        if (scd40_read_measurement(i2c_handle, &co2, &temp, &hum) != 0) {
            fprintf(stderr, "Error reading measurement\n");
            gpioDelay(MEASUREMENT_INTERVAL_S * 1000000);
            continue;
        }

        sensor_data_t d = { .co2 = co2, .temperature = temp, .humidity = hum };
        buffer_add(&buffer, d);
        control_led(LED_GPIO, (float)co2);

        printf("CO2: %u ppm, Temp: %.2f C, Hum: %.2f %%\n", co2, temp, hum);
        fflush(stdout);

        gpioDelay(MEASUREMENT_INTERVAL_S * 1000000);
    }

    printf("\nShutting down...\n");
    scd40_stop_periodic(i2c_handle);
    gpioWrite(LED_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

