#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define GPIO_PIN 4
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_US 5000000  /* 5 seconds */
#define TH_TIMEOUT_US 50000          /* 50 ms timeout for TH measurement */
#define TL_TIMEOUT_US 50000          /* 50 ms timeout for TL measurement */
#define MAX_CONSECUTIVE_ERRORS 3
#define MIN_TEMP -40.0
#define MAX_TEMP 150.0

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Read temperature from TMP05 via busy-wait polling.
 * Returns 0 on success, -1 on timeout/error. */
static int read_temperature(int gpio_pin, double *temperature) {
    uint32_t start_tick, end_tick, th_start, th_end, tl_start, tl_end;
    uint32_t th_width, tl_width;
    int level;

    /* Wait for a rising edge (start of a new cycle) */
    level = gpioRead(gpio_pin);
    if (level < 0) {
        fprintf(stderr, "gpioRead failed on GPIO %d: %s\n", gpio_pin, strerror(errno));
        return -1;
    }
    if (level == 1) {
        /* Pin is already high; sensor may be absent or stuck high */
        return -1;
    }

    /* Wait for line to go high (start of TH) */
    start_tick = gpioTick();
    while (gpioRead(gpio_pin) == 0) {
        if ((gpioTick() - start_tick) > TH_TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for TH start on GPIO %d\n", gpio_pin);
            return -1;
        }
    }
    th_start = gpioTick();

    /* Wait for line to go low (end of TH) */
    while (gpioRead(gpio_pin) == 1) {
        if ((gpioTick() - th_start) > TH_TIMEOUT_US) {
            fprintf(stderr, "Timeout measuring TH on GPIO %d\n", gpio_pin);
            return -1;
        }
    }
    th_end = gpioTick();
    th_width = th_end - th_start;

    /* Wait for line to go high again (end of TL) */
    while (gpioRead(gpio_pin) == 0) {
        if ((gpioTick() - th_end) > TL_TIMEOUT_US) {
            fprintf(stderr, "Timeout measuring TL on GPIO %d\n", gpio_pin);
            return -1;
        }
    }
    tl_start = gpioTick();

    /* Wait for line to go low (end of TL) */
    while (gpioRead(gpio_pin) == 1) {
        if ((gpioTick() - tl_start) > TL_TIMEOUT_US) {
            fprintf(stderr, "Timeout measuring TL on GPIO %d\n", gpio_pin);
            return -1;
        }
    }
    tl_end = gpioTick();
    tl_width = tl_end - tl_start;

    if (tl_width == 0) {
        fprintf(stderr, "TL measurement invalid (0 us) on GPIO %d\n", gpio_pin);
        return -1;
    }

    /* TMP05 conversion: Temperature = 4215 - (2143 * TH / TL) */
    *temperature = 4215.0 - (2143.0 * (double)th_width / (double)tl_width);

    return 0;
}

/* Log temperature reading with ISO-8601 timestamp */
static void log_temperature(double temperature, const char *status) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    if (log_file != NULL) {
        if (strcmp(status, "OK") == 0) {
            fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
        } else {
            fprintf(log_file, "%s,ERROR,%s\n", timestamp, status);
        }
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

int main(void) {
    double temperature;
    int consecutive_errors = 0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Set GPIO pin as input */
    gpioSetMode(GPIO_PIN, PI_INPUT);

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature monitoring started on GPIO %d. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (program_running) {
        if (read_temperature(GPIO_PIN, &temperature) == 0) {
            if (temperature >= MIN_TEMP && temperature <= MAX_TEMP) {
                log_temperature(temperature, "OK");
                printf("Temperature: %.2f °C\n", temperature);
                consecutive_errors = 0;
            } else {
                log_temperature(temperature, "OUT_OF_RANGE");
                printf("Temperature out of range: %.2f °C\n", temperature);
                consecutive_errors = 0;
            }
        } else {
            log_temperature(0.0, "SENSOR_READ_ERROR");
            printf("Error reading temperature.\n");
            consecutive_errors++;
        }

        if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
            log_temperature(0.0, "SENSOR MALFUNCTION");
            printf("Sensor malfunction detected. Logging SENSOR MALFUNCTION.\n");
            consecutive_errors = 0;
        }

        /* Sleep for sample interval (5 seconds) */
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Clean up */
    printf("\nCleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Temperature monitoring stopped.\n");

    return EXIT_SUCCESS;
}

