#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SHT35_ADDR     0x44
#define MEASURE_CMD    0x2400  /* single-shot, high repeatability, clock stretching disabled */
#define MEASURE_DELAY  20000   /* microseconds (20 ms) — datasheet: typ 12.1 ms, max 15 ms */
#define SAMPLE_PERIOD  5       /* seconds */
#define CSV_FILE       "environment.csv"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- CRC-8 (Sensirion: poly 0x31, init 0xFF, no final XOR) ---- */
static uint8_t sht35_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int ensure_csv_header(void)
{
    FILE *fp = fopen(CSV_FILE, "r");
    if (fp) {
        fseek(fp, 0, SEEK_END);
        if (ftell(fp) > 0)
            fclose(fp);
        else {
            fclose(fp);
            fp = fopen(CSV_FILE, "w");
            if (!fp) {
                perror("fopen(CSV, w)");
                return -1;
            }
            fprintf(fp, "timestamp,temperature_c,humidity_pct\n");
            fclose(fp);
        }
    } else {
        fp = fopen(CSV_FILE, "w");
        if (!fp) {
            perror("fopen(CSV, w)");
            return -1;
        }
        fprintf(fp, "timestamp,temperature_c,humidity_pct\n");
        fclose(fp);
    }
    return 0;
}

static int read_sht35(int handle, float *temperature, float *humidity)
{
    uint8_t cmd[2] = { (uint8_t)(MEASURE_CMD >> 8), (uint8_t)(MEASURE_CMD & 0xFF) };
    uint8_t data[6];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: i2cWriteDevice failed\n");
        return -1;
    }

    gpioDelay(MEASURE_DELAY);

    if (i2cReadDevice(handle, (char *)data, 6) != 6) {
        fprintf(stderr, "Error: i2cReadDevice failed (expected 6 bytes)\n");
        return -1;
    }

    if (sht35_crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "Error: temperature CRC mismatch\n");
        return -1;
    }
    if (sht35_crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "Error: humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = ((uint16_t)data[0] << 8) | data[1];
    uint16_t h_raw = ((uint16_t)data[3] << 8) | data[4];

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity    = 100.0f * (float)h_raw / 65535.0f;

    return 0;
}

static int log_data(const char *timestamp, float temperature, float humidity)
{
    FILE *fp = fopen(CSV_FILE, "a");
    if (!fp) {
        perror("fopen(CSV, a)");
        return -1;
    }
    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ensure_csv_header() != 0) {
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SHT35-DIS-B logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float temperature, humidity;

        if (read_sht35(g_i2c_handle, &temperature, &humidity) == 0) {
            time_t now = time(NULL);
            struct tm tm_buf;
            char timestamp[32];
            localtime_r(&now, &tm_buf);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_buf);

            if (log_data(timestamp, temperature, humidity) != 0)
                fprintf(stderr, "Warning: failed to log data\n");

            printf("%s  T=%.2f C  RH=%.2f %%\n", timestamp, temperature, humidity);
        } else {
            fprintf(stderr, "Warning: sensor read failed\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++)
            gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

