#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define FAN_GPIO 18
#define PWM_FREQ 25000
#define PWM_RANGE 255
#define SAMPLE_INTERVAL_US 100000
#define LOG_FILE "flow_log.txt"

#define RAW_MIN 1638
#define RAW_MAX 14745
#define FLOW_MIN 0.0
#define FLOW_MAX 10.0

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int handle, int16_t *raw_out) {
    char buf[2];
    int bytes = i2cReadDevice(handle, buf, 2);
    if (bytes != 2) {
        fprintf(stderr, "I2C read failed (got %d bytes): %s\n", bytes, strerror(errno));
        return -1;
    }
    uint16_t word = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *raw_out = (int16_t)(word >> 2);
    return 0;
}

static float raw_to_flow(int16_t raw) {
    if (raw < RAW_MIN) raw = RAW_MIN;
    if (raw > RAW_MAX) raw = RAW_MAX;
    return (float)(raw - RAW_MIN) / (float)(RAW_MAX - RAW_MIN) * (FLOW_MAX - FLOW_MIN) + FLOW_MIN;
}

static void set_fan_speed(float flow_rate) {
    int duty = (int)((flow_rate / FLOW_MAX) * PWM_RANGE);
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    gpioPWM(FAN_GPIO, duty);
}

static void log_flow(float pressure) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s,%.2f\n", ts, pressure);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ);
    gpioSetPWMrange(FAN_GPIO, PWM_RANGE);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting airflow monitoring. Press Ctrl+C to exit.\n");

    while (running) {
        int16_t raw;
        if (read_sensor(i2c_handle, &raw) == 0) {
            float flow = raw_to_flow(raw);
            set_fan_speed(flow);
            log_flow(flow);
            printf("Flow: %.2f SLPM, Fan: %d/255\n", flow, gpioGetPWMdutycycle(FAN_GPIO));
        } else {
            fprintf(stderr, "Sensor read error; continuing.\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioPWM(FAN_GPIO, 0);
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

