#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define LPS33HW_ADDR 0x5D
#define WHO_AM_I 0x0F
#define WHO_AM_I_VAL 0xB1
#define CTRL_REG1 0x10
#define PRESS_OUT_XL 0x28
#define TEMP_OUT_L 0x2B
#define LOG_FILE "environmental_data.txt"
#define SAMPLE_INTERVAL_US 1000000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_error(const char *msg) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "%s ERROR: %s\n", ts, msg);
    if (log_file) {
        fprintf(log_file, "%s ERROR: %s\n", ts, msg);
        fflush(log_file);
    }
}

static int read_register(int handle, uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        log_error("I2C read byte failed");
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t val) {
    if (i2cWriteByteData(handle, reg, val) < 0) {
        log_error("I2C write byte failed");
        return -1;
    }
    return 0;
}

static int read_pressure(int handle, float *pressure) {
    uint8_t xl, l, h;
    if (read_register(handle, PRESS_OUT_XL, &xl) < 0) return -1;
    if (read_register(handle, PRESS_OUT_XL + 1, &l) < 0) return -1;
    if (read_register(handle, PRESS_OUT_XL + 2, &h) < 0) return -1;
    int32_t raw = ((int32_t)h << 16) | ((int32_t)l << 8) | (int32_t)xl;
    if (raw & 0x800000) raw |= 0xFF000000;
    *pressure = (float)raw / 4096.0f;
    return 0;
}

static int read_temperature(int handle, float *temp) {
    uint8_t l, h;
    if (read_register(handle, TEMP_OUT_L, &l) < 0) return -1;
    if (read_register(handle, TEMP_OUT_L + 1, &h) < 0) return -1;
    int16_t raw = (int16_t)((h << 8) | l);
    *temp = 42.5f + (float)raw / 480.0f;
    return 0;
}

static void log_data(float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n",
            ts, pressure, temperature);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t who;
    if (read_register(i2c_handle, WHO_AM_I, &who) < 0 || who != WHO_AM_I_VAL) {
        fprintf(stderr, "LPS33HW not detected (WHO_AM_I=0x%02X, expected 0x%02X)\n",
                who, WHO_AM_I_VAL);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (write_register(i2c_handle, CTRL_REG1, 0xB0) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("LPS33HW logging started. Press Ctrl+C to stop.\n");

    while (program_running) {
        float pressure, temperature;
        if (read_pressure(i2c_handle, &pressure) == 0 &&
            read_temperature(i2c_handle, &temperature) == 0) {
            log_data(pressure, temperature);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

