        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t who;
    if (read_register(i2c_handle, WHO_AM_I, &who) < 0 || who != WHO_AM_I_VAL) {
        fprintf(stderr, "LPS33HW not detected (WHO_AM_I=0x%02X, expected 0x%02X)\n",
                who, WHO_AM_I_VAL);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (write_register(i2c_handle, CTRL_REG1, 0xB0) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("LPS33HW logging started. Press Ctrl+C to stop.\n");

    while (program_running) {
        float pressure, temperature;
        if (read_pressure(i2c_handle, &pressure) == 0 &&
            read_temperature(i2c_handle, &temperature) == 0) {
            log_data(pressure, temperature);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

