#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define TEMP_REG       0x00
#define LED_GPIO       17
#define TEMP_THRESHOLD 28.0f
#define BUFFER_SIZE    10
#define SAMPLE_PERIOD  1.0

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static float temperature_buffer[BUFFER_SIZE];
static int   buffer_index = 0;
static int   buffer_count = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static float read_temperature(void)
{
    int raw = i2cReadWordData(g_i2c_handle, TEMP_REG);
    if (raw < 0) {
        fprintf(stderr, "Error reading temperature register: %d\n", raw);
        return -1000.0f;
    }

    /* pigpio returns little-endian word; swap bytes to get the 16-bit
     * two's-complement value the STLM75 provides. */
    uint16_t swapped = ((uint16_t)(raw & 0xFF) << 8) | ((uint16_t)(raw >> 8) & 0xFF);

    /* STLM75: 9-bit resolution, sign bit in bit 15, data in bits 14:6.
     * Right-shift by 7 to get the 9-bit signed value, then divide by 2. */
    int16_t temp9 = (int16_t)(swapped >> 7);
    return (float)temp9 / 2.0f;
}

static void update_buffer(float temperature)
{
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE)
        buffer_count++;
}

static float calculate_average(void)
{
    if (buffer_count == 0)
        return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < buffer_count; i++)
        sum += temperature_buffer[i];
    return sum / (float)buffer_count;
}

static void control_led(float average_temperature)
{
    if (average_temperature > TEMP_THRESHOLD)
        gpioWrite(LED_GPIO, 1);
    else
        gpioWrite(LED_GPIO, 0);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", LED_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float temperature = read_temperature();
        if (temperature > -999.0f) {
            update_buffer(temperature);
            float average = calculate_average();
            control_led(average);
            printf("Temperature: %.2f C, Average: %.2f C\n", temperature, average);
        } else {
            fprintf(stderr, "Skipping sample due to read error.\n");
        }
        time_sleep(SAMPLE_PERIOD);
    }

    /* Clean shutdown */
    gpioWrite(LED_GPIO, 0);
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    printf("Temperature monitoring stopped.\n");
    return EXIT_SUCCESS;
}

