#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD30_I2C_ADDR 0x61
#define I2C_BUS 1
#define LOG_FILE "air_quality.log"
#define CO2_THRESHOLD_HIGH 1200
#define CO2_THRESHOLD_LOW 800
#define MEASUREMENT_INTERVAL_SEC 2

#define CMD_START_PERIODIC_MEASUREMENT 0x0010
#define CMD_STOP_PERIODIC_MEASUREMENT 0x0104
#define CMD_GET_DATA_READY 0x0202
#define CMD_READ_MEASUREMENT 0x0300

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    unsigned int co2;
    float temperature;
    float humidity;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t scd30_crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int scd30_write_command(int handle, uint16_t command) {
    uint8_t buf[2] = { (uint8_t)(command >> 8), (uint8_t)(command & 0xFF) };
    int result = i2cWriteDevice(handle, (char *)buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing command 0x%04X: %d\n", command, result);
        return -1;
    }
    return 0;
}

static int scd30_write_command_with_args(int handle, uint16_t command, uint16_t arg) {
    uint8_t buf[5];
    buf[0] = (uint8_t)(command >> 8);
    buf[1] = (uint8_t)(command & 0xFF);
    buf[2] = (uint8_t)(arg >> 8);
    buf[3] = (uint8_t)(arg & 0xFF);
    buf[4] = scd30_crc8(&buf[2], 2);
    int result = i2cWriteDevice(handle, (char *)buf, 5);
    if (result != 0) {
        fprintf(stderr, "Error writing command 0x%04X with arg: %d\n", command, result);
        return -1;
    }
    return 0;
}

static int scd30_read_data(int handle, uint16_t command, uint8_t *data, int len) {
    if (scd30_write_command(handle, command) != 0) {
        return -1;
    }
    gpioDelay(10000);
    int result = i2cReadDevice(handle, (char *)data, len);
    if (result != len) {
        fprintf(stderr, "Error reading data for command 0x%04X: %d\n", command, result);
        return -1;
    }
    return 0;
}

static int scd30_init(int handle) {
    if (scd30_write_command_with_args(handle, CMD_START_PERIODIC_MEASUREMENT, 2) != 0) {
        return -1;
    }
    gpioDelay(100000);
    return 0;
}

static int scd30_data_ready(int handle) {
    uint8_t data[3];
    if (scd30_read_data(handle, CMD_GET_DATA_READY, data, 3) != 0) {
        return -1;
    }
    if (scd30_crc8(data, 2) != data[2]) {
        fprintf(stderr, "CRC mismatch on data-ready response\n");
        return -1;
    }
    uint16_t ready = (data[0] << 8) | data[1];
    return (ready & 0x07FF) != 0;
}

static int scd30_read_measurement(int handle, sensor_data_t *data) {
    uint8_t data_buf[18];
    if (scd30_read_data(handle, CMD_READ_MEASUREMENT, data_buf, 18) != 0) {
        return -1;
    }
    if (scd30_crc8(&data_buf[0], 2) != data_buf[2]) {
        fprintf(stderr, "CRC mismatch on CO2 data\n");
        return -1;
    }
    if (scd30_crc8(&data_buf[3], 2) != data_buf[5]) {
        fprintf(stderr, "CRC mismatch on temperature data\n");
        return -1;
    }
    if (scd30_crc8(&data_buf[6], 2) != data_buf[8]) {
        fprintf(stderr, "CRC mismatch on humidity data\n");
        return -1;
    }
    unsigned int co2 = (data_buf[0] << 8) | data_buf[1];
    int16_t temp_raw = (data_buf[3] << 8) | data_buf[4];
    int16_t hum_raw = (data_buf[6] << 8) | data_buf[7];
    data->co2 = co2;
    data->temperature = temp_raw / 100.0f;
    data->humidity = hum_raw / 1000.0f;
    return 0;
}

static void log_data(FILE *fp, sensor_data_t *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];
    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    fprintf(fp, "%s,%u,%.2f,%.2f\n", timestamp, data->co2, data->temperature, data->humidity);
    fflush(fp);
}

static void control_ventilation(int co2_level) {
    if (co2_level < CO2_THRESHOLD_LOW) {
        printf("CO2 level low (%d ppm). Ventilation: OFF\n", co2_level);
    } else if (co2_level < CO2_THRESHOLD_HIGH) {
        printf("CO2 level moderate (%d ppm). Ventilation: LOW\n", co2_level);
    } else {
        printf("CO2 level high (%d ppm). Ventilation: HIGH\n", co2_level);
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        scd30_write_command(i2c_handle, CMD_STOP_PERIODIC_MEASUREMENT);
        gpioDelay(100000);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 0;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD30_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, SCD30_I2C_ADDR, i2c_handle);
        gpioTerminate();
        return 0;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 0;
    }

    if (scd30_init(i2c_handle) != 0) {
        fprintf(stderr, "SCD30 initialization failed\n");
        cleanup();
        return 0;
    }

    sensor_data_t sensor_data;
    while (!terminate) {
        int ready = scd30_data_ready(i2c_handle);
        if (ready < 0) {
            fprintf(stderr, "Error checking data ready status\n");
            gpioDelay(1000000);
            continue;
        }
        if (ready == 0) {
            gpioDelay(100000);
            continue;
        }
        if (scd30_read_measurement(i2c_handle, &sensor_data) == 0) {
            log_data(log_file, &sensor_data);
            control_ventilation(sensor_data.co2);
        } else {
            fprintf(stderr, "Error reading measurement data\n");
        }
        gpioDelay(MEASUREMENT_INTERVAL_SEC * 1000000);
    }

    cleanup();
    return 0;
}

