#define MEAS_CMD_MSB 0x36
#define MEAS_CMD_LSB 0x2F

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float pressure;
    float temperature;
    int valid;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int start_measurement(int handle) {
    uint8_t cmd[2] = {MEAS_CMD_MSB, MEAS_CMD_LSB};
    int rc = i2cWriteDevice(handle, (char *)cmd, 2);
    if (rc < 0) {
        fprintf(stderr, "Error: failed to send continuous-measurement command (pigpio rc=%d)\n", rc);
        return -1;
    }
    return 0;
}

static sensor_data_t read_sdp32(int handle) {
    sensor_data_t data = {0.0f, 0.0f, 0};
    uint8_t buf[READ_LEN];

    int bytes_read = i2cReadDevice(handle, (char *)buf, READ_LEN);
    if (bytes_read != READ_LEN) {
        fprintf(stderr, "Error: I2C read failed (expected %d bytes, got %d)\n", READ_LEN, bytes_read);
        return data;
    }

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: pressure CRC mismatch\n");
        return data;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: temperature CRC mismatch\n");
        return data;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "Error: scale-factor CRC mismatch\n");
        return data;
    }

    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);
    int16_t scale_factor = (int16_t)((buf[6] << 8) | buf[7]);

