    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at address 0x%02X (pigpio rc=%d)\n", I2C_BUS, SDP32_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (start_measurement(i2c_handle) != 0) {
        fprintf(stderr, "Error: sensor may not be connected at 0x%02X. Check wiring and I2C address.\n", SDP32_ADDR);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SDP32 differential pressure sensor reader started. Sampling every %d ms. Press Ctrl+C to exit.\n", interval_ms);

    while (!terminate) {
        sensor_data_t data = read_sdp32(i2c_handle);

        if (data.valid) {
            log_data(data.pressure, data.temperature);
        } else {
            fprintf(stderr, "Warning: invalid sensor reading, skipping log\n");
        }

        gpioDelay(interval_ms * 1000);
    }

    printf("\nExiting gracefully...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

