#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define HDC1000_ADDR 0x40
#define I2C_BUS "/dev/i2c-1"
#define TEMP_REG 0x00
#define CONFIG_REG 0x02
#define CONFIG_MEASURE_BOTH 0x1000  /* bit 12: T_EN | H_EN, 14-bit resolution */
#define CONVERSION_DELAY_MS 20

static volatile sig_atomic_t g_running = 1;
static int g_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(value >> 8);
    buf[2] = (uint8_t)(value & 0xFF);
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg16(0x%02X, 0x%04X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    uint8_t reg_buf = reg;
    if (write(fd, &reg_buf, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16: write pointer 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t data[2];
    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "i2c_read_reg16: read from 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

static int init_hdc1000(int fd) {
    if (i2c_write_reg16(fd, CONFIG_REG, CONFIG_MEASURE_BOTH) != 0) {
        return -1;
    }
    return 0;
}

static int read_hdc1000(int fd, float *temperature, float *humidity) {
    uint16_t raw_temp, raw_hum;
    if (i2c_read_reg16(fd, TEMP_REG, &raw_temp) != 0) {
        return -1;
    }
    if (i2c_read_reg16(fd, TEMP_REG, &raw_hum) != 0) {
        return -1;
    }
    *temperature = ((float)raw_temp / 65536.0f) * 165.0f - 40.0f;
    *humidity = ((float)raw_hum / 65536.0f) * 100.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    g_fd = open(I2C_BUS, O_RDWR);
    if (g_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                HDC1000_ADDR, strerror(errno));
        close(g_fd);
        return EXIT_FAILURE;
    }

    if (init_hdc1000(g_fd) != 0) {
        fprintf(stderr, "HDC1000 initialization failed (sensor may be absent).\n");
        close(g_fd);
        return EXIT_FAILURE;
    }

    printf("HDC1000 initialized. Reading every 5 seconds. Press Ctrl+C to exit.\n");

    while (g_running) {
        float temperature, humidity;
        if (read_hdc1000(g_fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read temperature and humidity.\n");
        }
        sleep(5);
    }

    if (g_fd >= 0) {
        close(g_fd);
        g_fd = -1;
    }
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

