#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS 1
#define SI7051_ADDR 0x40
#define MEASURE_TEMP_CMD 0xE3
#define READ_TEMP_CMD 0xE0
#define CONVERSION_DELAY_US 75000
#define POLL_INTERVAL_S 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(int handle, float *temperature) {
    char buf[2];
    int result;

    result = i2cWriteByte(handle, MEASURE_TEMP_CMD);
    if (result < 0) {
        fprintf(stderr, "Error: Failed to send measure temperature command (pigpio error %d)\n", result);
        return -1;
    }

    gpioDelay(CONVERSION_DELAY_US);

    result = i2cReadDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error: Failed to read temperature data (read %d bytes, expected 2)\n", result);
        return -1;
    }

    uint16_t raw = ((uint16_t)(buf[0] & 0x7F) << 8) | (uint8_t)buf[1];
    *temperature = (175.72f * raw / 65536.0f) - 46.85f;
    return 0;
}

int main(void) {
    float temperature;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register SIGTERM handler");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7051_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X (pigpio error %d)\n", SI7051_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        if (read_temperature(i2c_handle, &temperature) == 0) {
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            printf("%s Temperature: %.2f C\n", timestamp, temperature);
            fflush(stdout);
        } else {
            fprintf(stderr, "Warning: Failed to read temperature. Retrying in %d seconds...\n", POLL_INTERVAL_S);
        }
        sleep(POLL_INTERVAL_S);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("\nClean shutdown complete.\n");
    return 0;
}

