#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS 1
#define MLX90833_ADDR 0x60
#define READ_INTERVAL_US 500000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

static int read_pressure(int handle, float *pressure) {
    char cmd[1] = {0x00};
    char data[2] = {0};

    if (i2cWriteDevice(handle, cmd, 1) != 0) {
        fprintf(stderr, "Error: I2C write failed: %s\n", strerror(errno));
        return -1;
    }

    gpioDelay(10000);

    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error: I2C read failed: %s\n", strerror(errno));
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    *pressure = (float)raw / 100.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX90833_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X: %s\n", MLX90833_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        float pressure = 0.0f;
        int retries = 0;

        while (retries < MAX_RETRIES && running) {
            if (read_pressure(i2c_handle, &pressure) == 0) {
                time_t now = time(NULL);
                struct tm *tm_info = localtime(&now);
                char ts[32];
                strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
                printf("[%s] Pressure: %.2f hPa\n", ts, pressure);
                fflush(stdout);
                break;
            }
            retries++;
            gpioDelay(100000);
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Error: Failed to read pressure after %d retries\n", MAX_RETRIES);
        }

        if (running) {
            gpioDelay(READ_INTERVAL_US);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

