#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define ICP10101_ADDR  0x63
#define MEASURE_CMD    0x40
#define OTP_READ_CMD   0x50
#define READ_LEN       6
#define MEASURE_DELAY_US 7000
#define SAMPLE_PERIOD_S 5

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    uint16_t scale_factor_lut;
    uint16_t scale_factor_h;
    uint16_t scale_factor_p;
    uint16_t scale_factor_t;
} icp10101_cal_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_calibration(icp10101_cal_t *cal) {
    char cmd = OTP_READ_CMD;
    char buf[8];

    if (i2cWriteDevice(i2c_handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: failed to write OTP read command\n");
        return -1;
    }
    gpioDelay(2000);

    if (i2cReadDevice(i2c_handle, buf, 8) != 8) {
        fprintf(stderr, "Error: failed to read 8 bytes of OTP data\n");
        return -1;
    }

    cal->scale_factor_lut = (uint16_t)((buf[0] << 8) | buf[1]);
    cal->scale_factor_h   = (uint16_t)((buf[2] << 8) | buf[3]);
    cal->scale_factor_p   = (uint16_t)((buf[4] << 8) | buf[5]);
    cal->scale_factor_t   = (uint16_t)((buf[6] << 8) | buf[7]);

    return 0;
}

static int read_sensor_data(int handle, float *temperature, float *pressure) {
    char cmd = MEASURE_CMD;
    char buf[READ_LEN];

    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: failed to write measurement command\n");
        return -1;
    }
    gpioDelay(MEASURE_DELAY_US);

    if (i2cReadDevice(handle, buf, READ_LEN) != READ_LEN) {
        fprintf(stderr, "Error: failed to read 6 bytes of sensor data\n");
        return -1;
    }

    uint16_t raw_t = (uint16_t)((buf[0] << 8) | buf[1]);
    uint32_t raw_p = ((uint32_t)(buf[2] & 0xFF) << 16) |
                     ((uint32_t)(buf[3] & 0xFF) << 8)  |
                     ((uint32_t)(buf[4] & 0xFF));

    if (raw_p == 0xFFFFF || raw_t == 0xFFFF) {
        fprintf(stderr, "Error: sensor returned all-1s data (0xFFFF) - check wiring/address\n");
        return -1;
    }

    float t = (float)raw_t / 65535.0f;
    float p = (float)raw_p / 65535.0f;

    *temperature = t;
    *pressure    = p;

    return 0;
}

static void convert_data(float t, float p, const icp10101_cal_t *cal,
                         float *celsius, float *pascals) {
    float t_comp = t * cal->scale_factor_t;
    float p_comp = p * cal->scale_factor_p;

    *celsius = t_comp * 100.0f + 40.0f;
    *pascals  = p_comp * 100.0f + 45000.0f;
}

static void log_data(float temperature, float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n",
           timestamp, temperature, pressure);
    fflush(stdout);
}

int main(void) {
    icp10101_cal_t cal;
    float temperature, pressure;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, ICP10101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at addr 0x%02X\n",
                I2C_BUS, ICP10101_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (read_calibration(&cal) != 0) {
        fprintf(stderr, "Error: failed to read calibration data - sensor may be absent\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (!terminate) {
        if (read_sensor_data(i2c_handle, &temperature, &pressure) == 0) {
            convert_data(temperature, pressure, &cal, &temperature, &pressure);
            log_data(temperature, pressure);
        } else {
            fprintf(stderr, "Warning: sensor read failed, retrying in %d s\n",
                    SAMPLE_PERIOD_S);
        }
        sleep(SAMPLE_PERIOD_S);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

