#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX90819_ADDR  0x60
#define PRESS_MSB_REG  0xAA
#define PRESS_LSB_REG  0xAB
#define SCALE_FACTOR   0.1f
#define SAMPLE_PERIOD  1  /* seconds */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_pressure_raw(int fd, int16_t *raw_out) {
    uint8_t msb, lsb;
    if (i2c_read_byte(fd, PRESS_MSB_REG, &msb) < 0) return -1;
    if (i2c_read_byte(fd, PRESS_LSB_REG, &lsb) < 0) return -1;
    *raw_out = (int16_t)((msb << 8) | lsb);
    return 0;
}

static void log_pressure(float pressure_kPa) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] Pressure: %.2f kPa\n", ts, pressure_kPa);
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MLX90819_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                MLX90819_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("MLX90819 pressure sensor reader started on %s (addr 0x%02X).\n",
           I2C_BUS, MLX90819_ADDR);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        int16_t raw;
        if (read_pressure_raw(fd, &raw) < 0) {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        } else {
            float pressure = (float)raw * SCALE_FACTOR;
            log_pressure(pressure);
        }
        sleep(SAMPLE_PERIOD);
    }

    printf("\nExiting cleanly.\n");
    close(fd);
    return EXIT_SUCCESS;
}

