#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x40
#define PRESSURE_REG   0x00
#define SCALE_FACTOR   0.01f
#define SAFE_MIN_KPA   200.0f
#define SAFE_MAX_KPA   250.0f
#define LOG_FILE       "pressure_log.csv"
#define READ_INTERVAL  1.0
#define MAX_RETRIES    2

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_i2c(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (pigpio error %d)\n", g_i2c_handle);
        return -1;
    }
    return 0;
}

static int read_pressure(float *pressure_kpa)
{
    uint8_t buf[2];
    int rc;

    rc = i2cReadI2CBlockData(g_i2c_handle, PRESSURE_REG, (char *)buf, 2);
    if (rc != 2) {
        fprintf(stderr, "Error: i2cReadI2CBlockData returned %d\n", rc);
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *pressure_kpa = (float)raw * SCALE_FACTOR;
    return 0;
}

static void log_pressure(float pressure_kpa)
{
    time_t now = time(NULL);
    struct tm tm_utc;
    char ts[32];

    gmtime_r(&now, &tm_utc);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    fprintf(g_log_file, "%s,%.2f\n", ts, pressure_kpa);
    fflush(g_log_file);
}

static void check_pressure(float pressure_kpa)
{
    if (pressure_kpa < SAFE_MIN_KPA || pressure_kpa > SAFE_MAX_KPA) {
        fprintf(stderr, "WARNING: Pressure %.2f kPa outside safe range [%.0f, %.0f] kPa\n",
                pressure_kpa, SAFE_MIN_KPA, SAFE_MAX_KPA);
    }
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "Error: cannot open %s for append\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,pressure_kPa\n");
        fflush(g_log_file);
    }

    while (g_running) {
        float pressure_kpa;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_pressure(&pressure_kpa) == 0) {
                ok = 1;
                break;
            }
            if (attempt < MAX_RETRIES - 1) {
                fprintf(stderr, "Retrying I2C read (%d/%d)...\n", attempt + 1, MAX_RETRIES);
                time_sleep(0.1);
                if (init_i2c() != 0) {
                    fprintf(stderr, "Failed to re-open I2C after retry %d\n", attempt + 1);
                }
            }
        }

        if (ok) {
            log_pressure(pressure_kpa);
            check_pressure(pressure_kpa);
        } else {
            fprintf(stderr, "Error: pressure read failed after %d attempts; continuing\n", MAX_RETRIES);
        }

        if (g_running) {
            time_sleep(READ_INTERVAL);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

