#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HIH6130_ADDR 0x27
#define I2C_BUS 1
#define LOG_FILE "environmental_data.log"
#define MAX_LOG_SIZE (1024 * 1024)
#define SAMPLE_INTERVAL 5
#define MEASUREMENT_DELAY_US 40000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

static int rotate_log_file(void) {
    if (log_file == NULL) return 0;
    long pos = ftell(log_file);
    if (pos < 0) {
        fclose(log_file);
        log_file = NULL;
        return 0;
    }
    if (pos >= MAX_LOG_SIZE) {
        fclose(log_file);
        log_file = NULL;
        return 1;
    }
    return 0;
}

static int log_data(float temperature, float humidity) {
    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    if (rotate_log_file() != 0) {
        fprintf(stderr, "Log file rotated.\n");
    }

    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);

    if (fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n",
                timestamp, temperature, humidity) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static int read_hih6130(float *temperature, float *humidity) {
    unsigned char data[4];
    int result;

    /* Trigger a measurement by writing 0x00 to the sensor */
    result = i2cWriteByte(i2c_handle, 0x00);
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_US);

    /* Read 4 bytes of data */
    result = i2cReadDevice(i2c_handle, (char *)data, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading data: expected 4 bytes, got %d\n", result);
        return -1;
    }

    /* Check status bits (bits 7 and 6 of byte 2) */
    if ((data[2] & 0xC0) != 0x00) {
        fprintf(stderr, "Sensor status error: 0x%02X\n", data[2] & 0xC0);
        return -1;
    }

    /* Convert raw data to temperature and humidity */
    unsigned int humidity_raw = ((unsigned int)data[0] << 8) | data[1];
    unsigned int temperature_raw = ((unsigned int)data[2] << 8) | data[3];

    *humidity = (float)humidity_raw * 100.0f / 16383.0f;
    *temperature = (float)temperature_raw * 165.0f / 16383.0f - 40.0f;

    return 0;
}

int main(void) {
    float temperature, humidity;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return 1;
    }

    printf("Starting environmental monitoring. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_hih6130(&temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            if (log_data(temperature, humidity) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        /* Sleep in 100 ms increments to allow prompt signal handling */
        for (int i = 0; i < SAMPLE_INTERVAL * 10 && running; i++) {
            gpioDelay(100000);
        }
    }

    printf("\nExiting gracefully.\n");
    cleanup();
    return 0;
}

