    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return 1;
    }

    printf("Starting environmental monitoring. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_hih6130(&temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            if (log_data(temperature, humidity) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        /* Sleep in 100 ms increments to allow prompt signal handling */
        for (int i = 0; i < SAMPLE_INTERVAL * 10 && running; i++) {
            gpioDelay(100000);
        }
    }

    printf("\nExiting gracefully.\n");
    cleanup();
    return 0;
}

