#define GPIO_PIN 4
#define TICK_TIME_US 3
#define SYNC_PULSES 56
#define NIBBLES 5
#define MIN_NIBBLE_TICKS 12
#define MAX_NIBBLE_TICKS 271
#define LOG_FILE "pressure_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_gpio_level(int gpio, int tick) {
    int level = gpioRead(gpio);
    if (level < 0) {
        fprintf(stderr, "Error: gpioRead failed on GPIO %d (tick %d)\n", gpio, tick);
        return -1;
    }
    return level;
}

static int read_gpio_level_with_timeout(int gpio, int tick, int timeout_us) {
    int level = read_gpio_level(gpio, tick);
    if (level < 0) return -1;
    if (level == 0) return 0;
    int elapsed = 0;
    while (read_gpio_level(gpio, tick + elapsed) == 1) {
        elapsed += TICK_TIME_US;
        if (elapsed > timeout_us) return -1;
    }
    return 1;
}

static int read_nibble(int gpio, int tick, int *nibble_value) {
    int level = read_gpio_level_with_timeout(gpio, tick, 1000);
    if (level < 0) return -1;
    if (level == 0) return 0;
    int width = 0;
    while (read_gpio_level(gpio, tick + width) == 1) {
        width += TICK_TIME_US;
        if (width > 1000) return -1;
    }
    *nibble_value = (width / TICK_TIME_US) - 12;
    if (*nibble_value < 0 || *nibble_value > 15) return -1;
    return 0;
}

static int read_sent_data(int gpio, int tick, int *raw_pressure) {
    int nibbles[NIBBLES];
    int valid = 1;
    int sync_ok = 0;

    for (int i = 0; i < SYNC_PULSES; i++) {
        if (read_gpio_level_with_timeout(gpio, tick + i, 1000) != 1) {
            valid = 0;
            break;
        }
    }
    if (!valid) return -1;

    for (int i = 0; i < NIBBLES; i++) {
        if (read_nibble(gpio, tick + (i * 12), &nibbles[i]) != 0) {
            valid = 0;
            break;
        }
    }

    if (!valid) return -1;

    int sum = nibbles[0] + nibbles[1] + nibbles[2] + nibbles[3];
    if ((sum % 16) != nibbles[4]) {
