        return -2;
    }

    *raw_pressure = (nibbles[1] << 8) | (nibbles[2] << 4) | nibbles[3];
    return 0;
}

static float convert_to_pressure(int raw_pressure) {
    return (float)raw_pressure * 0.1f + 0.0f;
}

static void log_pressure(float pressure) {
