    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Pressure sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int raw_pressure = 0;
        int ret = read_sent_data(GPIO_PIN, 0, &raw_pressure);

        if (ret == 0) {
            float pressure = convert_to_pressure(raw_pressure);
            log_pressure(pressure);
            printf("Pressure: %.2f Pa\n", pressure);
        } else if (ret == -1) {
            fprintf(stderr, "Error: Sensor absent or timeout\n");
        } else if (ret == -2) {
            fprintf(stderr, "Error: Checksum error\n");
        }

        gpioDelay(100000);
    }

    gpioTerminate();
    printf("Pressure sensor monitoring stopped.\n");
    return 0;
}

