#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define TMP117_ADDR    0x48
#define TEMP_REG       0x00
#define RESOLUTION     0.0078125f
#define BUFFER_SIZE    100
#define SAMPLE_PERIOD  5
#define LOG_FILE       "temperature_log.dat"

typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void buffer_init(CircularBuffer *cb) {
    cb->head  = 0;
    cb->count = 0;
}

static void buffer_add(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static int buffer_write_to_file(const CircularBuffer *cb, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("fopen");
        return -1;
    }
    size_t written = fwrite(cb->buffer, sizeof(float), cb->count, fp);
    if (written != (size_t)cb->count) {
        fprintf(stderr, "Short write to %s: %zu of %d\n", filename, written, cb->count);
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

