    char reg = (char)TEMP_REG;
    char data[2];

    if (i2cWriteDevice(handle, &reg, 1) != 0) {
        fprintf(stderr, "I2C write error (reg 0x%02X)\n", TEMP_REG);
        return -1;
    }
    gpioDelay(1000); /* 1 ms conversion settle */

    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "I2C read error (reg 0x%02X)\n", TEMP_REG);
        return -1;
    }

    int16_t raw = ((int16_t)data[0] << 8) | (uint8_t)data[1];
    *out_temp = (float)raw * RESOLUTION;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus %d, addr 0x%02X): %d\n", I2C_BUS, TMP117_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    CircularBuffer temp_buffer;
    buffer_init(&temp_buffer);

    while (g_running) {
        float temperature;
        if (read_temperature(g_i2c_handle, &temperature) == 0) {
            buffer_add(&temp_buffer, temperature);
            if (buffer_write_to_file(&temp_buffer, LOG_FILE) != 0) {
                fprintf(stderr, "Failed to write buffer to %s\n", LOG_FILE);
            }
        } else {
            fprintf(stderr, "Temperature read failed; skipping sample\n");
        }
        sleep(SAMPLE_PERIOD);
    }

    /* Graceful shutdown */
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

