    *raw_field = (buffer[0] << 8) | buffer[1];
    *raw_temp = (buffer[1] << 8) | buffer[0];
    return 0;
}

static float convert_field(int raw_field) {
    return (float)raw_field * 0.1f;
}

static float convert_temperature(int raw_temp) {
    return (float)raw_temp * 0.01f - 25.0f;
}

static int log_data(float field, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
            return -1;
        }
        fseek(log_file, 0, SEEK_END);
        long file_size = ftell(log_file);
        if (file_size == 0) {
            fprintf(log_file, "Timestamp,Field (Gauss),Temperature (Celsius)\n");
        }
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, field, temperature);
    fflush(log_file);
    return 0;
}

static void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,ERROR,%s\n", timestamp, message);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Si7202 sensor logging started. Press Ctrl+C to stop.\n");

    while (program_running) {
        int raw_field = 0, raw_temp = 0;

        if (read_sensor_data(&raw_field, &raw_temp) == 0) {
            float field = convert_field(raw_field);
            float temperature = convert_temperature(raw_temp);

            if (log_data(field, temperature) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            log_error("Sensor read failed");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

