    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n",
                strerror(errno));
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int consecutive_failures = 0;

    while (running) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            consecutive_failures = 0;
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
        } else {
            consecutive_failures++;
            fprintf(stderr, "Read failed (%d consecutive)\n", consecutive_failures);
            if (consecutive_failures >= MAX_RETRIES) {
                fprintf(stderr, "Max retries reached; exiting.\n");
                break;
            }
            if (init_i2c() != 0) {
                consecutive_failures++;
                if (consecutive_failures >= MAX_RETRIES) {
                    fprintf(stderr, "Max retries reached; exiting.\n");
                    break;
                }
            }
        }
        gpioSleep(PI_TIME_RELATIVE, 1, 0);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

