#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DHT11_GPIO 4
#define DHT11_READ_INTERVAL_US 2000000
#define DHT11_START_LOW_US 20000
#define DHT11_START_HIGH_US 40
#define DHT11_RESP_LOW_US 80
#define DHT11_RESP_HIGH_US 80
#define DHT11_BIT_LOW_US 50
#define DHT11_TIMEOUT_US 1000
#define DHT11_MAX_RETRIES 5

#define DHT11_OK 0
#define DHT11_ERROR_CHECKSUM -1
#define DHT11_ERROR_TIMEOUT -2
#define DHT11_ERROR_SENSOR_ABSENT -3
#define DHT11_ERROR_GPIO -4

typedef struct {
    float temperature;
    float humidity;
    int status;
} DHT11Data;

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(FILE *fp, int status, const char *msg) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d, Status: %d, Error: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, status, msg);
    fflush(fp);
}

static int wait_level(int gpio, int level, uint32_t timeout_us) {
    uint32_t start = gpioTick();
    while (gpioRead(gpio) != level) {
        if ((gpioTick() - start) > timeout_us) return -1;
    }
    return 0;
}

static int read_dht11(DHT11Data *data) {
    uint8_t data_bytes[5] = {0, 0, 0, 0, 0};
    int i, bit;

    data->status = DHT11_OK;

    if (gpioSetMode(DHT11_GPIO, PI_OUTPUT) != 0) {
        log_error(stderr, DHT11_ERROR_GPIO, "Failed to set GPIO mode to output");
        return DHT11_ERROR_GPIO;
    }
    gpioWrite(DHT11_GPIO, 0);
    gpioDelay(DHT11_START_LOW_US);
    gpioWrite(DHT11_GPIO, 1);
    gpioDelay(DHT11_START_HIGH_US);
    gpioSetMode(DHT11_GPIO, PI_INPUT);

    if (wait_level(DHT11_GPIO, 0, DHT11_TIMEOUT_US) != 0) {
        log_error(stderr, DHT11_ERROR_TIMEOUT, "Timeout waiting for sensor response low");
        return DHT11_ERROR_TIMEOUT;
    }
