#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADPD105_ADDR_1 0x64
#define ADPD105_ADDR_2 0x65
#define ADPD105_REG_DEVICE_ID 0x00
#define ADPD105_REG_RED 0x64
#define ADPD105_REG_GREEN 0x66
#define ADPD105_REG_BLUE 0x68
#define ADPD105_DEVICE_ID 0x2A
#define LOG_FILE "cct_log.csv"
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_handle_1 = -1;
static int i2c_handle_2 = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int adpd105_read_reg16(int handle, uint8_t reg, uint16_t *out) {
    char buf[2];
    int rc = i2cReadI2CBlockData(handle, reg, buf, 2);
    if (rc != 2) {
        return -1;
    }
    *out = (uint16_t)((uint8_t)buf[1] << 8) | (uint8_t)buf[0];
    return 0;
}

static int adpd105_write_reg8(int handle, uint8_t reg, uint8_t val) {
    return i2cWriteByteData(handle, reg, val);
}

static int adpd105_init(int handle) {
    uint16_t device_id = 0;
    if (adpd105_read_reg16(handle, ADPD105_REG_DEVICE_ID, &device_id) != 0) {
        fprintf(stderr, "Error: Failed to read device ID from I2C handle %d\n", handle);
        return -1;
    }
    if (device_id != ADPD105_DEVICE_ID) {
        fprintf(stderr, "Error: Device ID mismatch (got 0x%04X, expected 0x%04X) on handle %d\n",
                device_id, ADPD105_DEVICE_ID, handle);
        return -1;
    }
    return 0;
}

static int adpd105_read_cct(int handle, float *cct_out) {
    uint16_t red = 0, green = 0, blue = 0;
    if (adpd105_read_reg16(handle, ADPD105_REG_RED, &red) != 0) {
        fprintf(stderr, "Error: Failed to read red channel from handle %d\n", handle);
        return -1;
    }
    if (adpd105_read_reg16(handle, ADPD105_REG_GREEN, &green) != 0) {
        fprintf(stderr, "Error: Failed to read green channel from handle %d\n", handle);
        return -1;
    }
    if (adpd105_read_reg16(handle, ADPD105_REG_BLUE, &blue) != 0) {
        fprintf(stderr, "Error: Failed to read blue channel from handle %d\n", handle);
        return -1;
    }
    float r = (float)red / 65535.0f;
    float g = (float)green / 65535.0f;
    float b = (float)blue / 65535.0f;
    float n = r * 0.312453f + g * 0.329016f + b * 0.358429f;
    if (n <= 0.0f) {
        fprintf(stderr, "Error: Division by zero in CCT calculation (n = %.6f)\n", n);
        return -1;
    }
    float cct = 449.0f * n - 9.0f * n * n;
    *cct_out = cct;
    return 0;
}

static void log_data(float cct1, float cct2, float avg_cct) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(log_file, "%s,%.2f\n", timestamp, avg_cct);
    fflush(log_file);
    printf("Logged: %s, Average CCT: %.2f\n", timestamp, avg_cct);
}

static void cleanup(void) {
    if (i2c_handle_1 >= 0) {
        i2cClose(i2c_handle_1);
        i2c_handle_1 = -1;
    }
    if (i2c_handle_2 >= 0) {
        i2cClose(i2c_handle_2);
        i2c_handle_2 = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

