}

static int adpd105_read_reg16(int handle, uint8_t reg, uint16_t *out) {
    char buf[2];
    int rc = i2cReadI2CBlockData(handle, reg, buf, 2);
    if (rc != 2) {
        return -1;
    }
    *out = (uint16_t)((uint8_t)buf[1] << 8) | (uint8_t)buf[0];
    return 0;
}

static int adpd105_write_reg8(int handle, uint8_t reg, uint8_t val) {
    return i2cWriteByteData(handle, reg, val);
}

static int adpd105_init(int handle) {
    uint16_t device_id = 0;
    if (adpd105_read_reg16(handle, ADPD105_REG_DEVICE_ID, &device_id) != 0) {
        fprintf(stderr, "Error: Failed to read device ID from I2C handle %d\n", handle);
        return -1;
    }
    if (device_id != ADPD105_DEVICE_ID) {
        fprintf(stderr, "Error: Device ID mismatch (got 0x%04X, expected 0x%04X) on handle %d\n",
                device_id, ADPD105_DEVICE_ID, handle);
        return -1;
    }
    return 0;
}

static int adpd105_read_cct(int handle, float *cct_out) {
    uint16_t red = 0, green = 0, blue = 0;
    if (adpd105_read_reg16(handle, ADPD105_REG_RED, &red) != 0) {
        fprintf(stderr, "Error: Failed to read red channel from handle %d\n", handle);
        return -1;
    }
    if (adpd105_read_reg16(handle, ADPD105_REG_GREEN, &green) != 0) {
        fprintf(stderr, "Error: Failed to read green channel from handle %d\n", handle);
        return -1;
    }
    if (adpd105_read_reg16(handle, ADPD105_REG_BLUE, &blue) != 0) {
        fprintf(stderr, "Error: Failed to read blue channel from handle %d\n", handle);
        return -1;
    }
    float r = (float)red / 65535.0f;
    float g = (float)green / 65535.0f;
    float b = (float)blue / 65535.0f;
    float n = r * 0.312453f + g * 0.329016f + b * 0.358429f;
