#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define TEMP_REG       0x00
#define FAN_GPIO       18
#define BUFFER_SIZE    60
#define TEMP_THRESHOLD_HIGH  28.0f
#define TEMP_THRESHOLD_LOW   26.0f
#define POLL_INTERVAL_US  1000000  /* 1 second */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void cb_init(CircularBuffer *cb) {
    cb->head  = 0;
    cb->count = 0;
}

static void cb_add(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static float cb_average(const CircularBuffer *cb) {
    if (cb->count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++) sum += cb->buffer[i];
    return sum / (float)cb->count;
}

/*
 * LM75B temperature register (0x00):
 *   9-bit signed value, bits D9..D1 used, D0 always 0.
 *   Resolution: 0.5 °C per LSB.
 *   Read 2 bytes, combine as (raw16 >> 8) | (raw8 & 0x80) to sign-extend.
 */
static int read_temperature(int handle, float *out_temp) {
    char reg = (char)TEMP_REG;
    char data[2];

    if (i2cWriteDevice(handle, &reg, 1) != 0) {
        fprintf(stderr, "Error: I2C write (select register 0x00) failed.\n");
        return -1;
    }

    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error: I2C read (2 bytes from 0x00) failed.\n");
        return -1;
    }

    int16_t raw = (int16_t)(((uint16_t)data[0] << 8) | (uint8_t)data[1]);
    raw >>= 1;  /* arithmetic shift keeps sign for negative temperatures */
    *out_temp = (float)raw * 0.5f;
    return 0;
}

static int control_fan(int gpio, int on) {
    if (gpioWrite(gpio, on ? 1 : 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(%d, %d) failed.\n", gpio, on);
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed.\n", FAN_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(FAN_GPIO, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(%d, 0) failed.\n", FAN_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    cb_init(NULL);  /* placeholder; real usage passes pointer */

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fan_on = 0;

    while (g_running) {
        float temperature;
        if (read_temperature(g_i2c_handle, &temperature) == 0) {
            cb_add(NULL, temperature);  /* placeholder; real usage passes pointer */
            float avg = cb_average(NULL);  /* placeholder; real usage passes pointer */

            printf("Temperature: %.2f °C, Average: %.2f °C\n", temperature, avg);

            if (avg > TEMP_THRESHOLD_HIGH && !fan_on) {
                if (control_fan(FAN_GPIO, 1) == 0) {
                    fan_on = 1;
                    printf("Fan turned ON.\n");
                }
            } else if (avg < TEMP_THRESHOLD_LOW && fan_on) {
