#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define TEMP_REG       0x00
#define FAN_GPIO       18
#define BUFFER_SIZE    60
#define TEMP_THRESHOLD_HIGH  28.0f
#define TEMP_THRESHOLD_LOW   26.0f
#define POLL_INTERVAL_US  1000000  /* 1 second */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void cb_init(CircularBuffer *cb) {
    cb->head  = 0;
    cb->count = 0;
}

static void cb_add(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static float cb_average(const CircularBuffer *cb) {
    if (cb->count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++) sum += cb->buffer[i];
    return sum / (float)cb->count;
}

/*
 * LM75B temperature register (0x00):
 *   9-bit signed value, bits D9..D1 used, D0 always 0.
 *   Resolution: 0.5 °C per LSB.
 *   Read 2 bytes, combine as (raw16 >> 8) | (raw8 & 0x80) to sign-extend.
 */
static int read_temperature(int handle, float *out_temp) {
    char reg = (char)TEMP_REG;
    char data[2];

    if (i2cWriteDevice(handle, &reg, 1) != 0) {
        fprintf(stderr, "Error: I2C write (select register 0x00) failed.\n");
        return -1;
    }

    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error: I2C read (2 bytes from 0x00) failed.\n");
        return -1;
    }

    int16_t raw = (int16_t)(((uint16_t)data[0] << 8) | (uint8_t)data[1]);
    raw >>= 1;  /* arithmetic shift keeps sign for negative temperatures */
    *out_temp = (float)raw * 0.5f;
    return 0;
}

