#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x25
#define MEASURE_CMD    0x362F
#define PRESSURE_SCALE 60.0f
#define TEMP_SCALE     200.0f
#define PRESSURE_THRESHOLD 5.0f
#define LOG_FILE      "airflow.log"
#define READ_DELAY_US 45000   /* 45 ms first-measurement wait */
#define LOOP_DELAY_US  1000000 /* 1 s between samples */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ---- Sensirion CRC-8 (poly 0x31, init 0xFF) ---- */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ---- Read one 9-byte measurement frame ---- */
static int read_sensor_data(int handle, float *pressure, float *temperature)
{
    uint8_t cmd[2] = {
        (uint8_t)((MEASURE_CMD >> 8) & 0xFF),
        (uint8_t)(MEASURE_CMD & 0xFF)
    };
    uint8_t buf[9];

    /* Send continuous-measurement command */
    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "[ERROR] I2C write failed\n");
        return -1;
    }

    /* Wait for first conversion */
    gpioDelay(READ_DELAY_US);

    /* Read 9 bytes: pressure(2)+crc, temp(2)+crc, status(2)+crc */
    if (i2cReadDevice(handle, (char *)buf, 9) != 9) {
        fprintf(stderr, "[ERROR] I2C read failed (sensor absent or bus error)\n");
        return -1;
    }

    /* CRC validation */
    if (sensirion_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[ERROR] Pressure CRC mismatch\n");
        return -1;
    }
    if (sensirion_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch\n");
        return -1;
    }
    if (sensirion_crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "[ERROR] Status CRC mismatch\n");
        return -1;
    }

    /* Parse big-endian signed 16-bit values */
    int16_t raw_pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);

    *pressure    = (float)raw_pressure    / PRESSURE_SCALE;
    *temperature = (float)raw_temperature / TEMP_SCALE;

    return 0;
}

/* ---- Log one CSV line ---- */
static int log_data(FILE *fp, float pressure, float temperature)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        return -1;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log failed\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "[FATAL] Cannot open %s\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("HVAC airflow monitor started. Logging to %s\n", LOG_FILE);

    while (g_running) {
        float pressure = 0.0f, temperature = 0.0f;

        if (read_sensor_data(g_i2c_handle, &pressure, &temperature) == 0) {
            if (log_data(g_log_file, pressure, temperature) != 0) {
                fprintf(stderr, "[WARN] Logging failed\n");
            }

            if (pressure > PRESSURE_THRESHOLD) {
                fprintf(stderr,
                        "[WARN] Pressure %.2f Pa exceeds threshold %.2f Pa\n",
                        pressure, PRESSURE_THRESHOLD);
            }
        } else {
            fprintf(stderr, "[WARN] Sensor read failed; will retry next cycle\n");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

