    return (float)raw / 16.0f;
}

int main(void)
{
    int fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, STTS2004_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n", STTS2004_ADDR, strerror(errno));
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s) failed: %s\n", GPIO_CHIP, strerror(errno));
        goto cleanup;
    }

    line = gpiod_chip_get_line(chip, GPIO_OFFSET);
    if (!line) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n", GPIO_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "stts2004-led", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output failed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("STTS2004 temperature monitor started. Press Ctrl+C to exit.\n");

    int led_state = 0;
    int consecutive_errors = 0;

    while (g_running) {
        int16_t raw;
        if (i2c_read_reg16(fd, STTS2004_REG_TEMP, &raw) == 0) {
            consecutive_errors = 0;
            float temp = convert_temp(raw);
            printf("Temperature: %.2f C\n", temp);

            if (temp > TEMP_HIGH && led_state == 0) {
                if (gpiod_line_set_value(line, 1) < 0) {
                    fprintf(stderr, "gpiod_line_set_value(1) failed: %s\n", strerror(errno));
                } else {
                    led_state = 1;
                }
            } else if (temp < TEMP_LOW && led_state == 1) {
                if (gpiod_line_set_value(line, 0) < 0) {
                    fprintf(stderr, "gpiod_line_set_value(0) failed: %s\n", strerror(errno));
                } else {
                    led_state = 0;
                }
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "Temperature read failed (consecutive: %d)\n", consecutive_errors);
            if (consecutive_errors >= 10) {
                fprintf(stderr, "Too many I2C errors, exiting.\n");
                goto cleanup;
            }
        }

        sleep(POLL_INTERVAL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_set_value(line, 0);
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

