#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define MEASURE_CMD 0x362F
#define READ_LEN 9
#define CRC_POLY 0x31
#define CRC_INIT 0xFF
#define LOG_FILE "flow_data.txt"
#define MEAS_DELAY_US 45000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float differential_pressure;
    float temperature;
} sensor_data_t;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, SDP800_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int send_command(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    int result = i2cWriteDevice(i2c_handle, (char *)buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing command 0x%04X: %d\n", cmd, result);
        return -1;
    }
    return 0;
}

static int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, READ_LEN);
    if (result != READ_LEN) {
        fprintf(stderr, "Error reading sensor data: expected %d bytes, got %d\n", READ_LEN, result);
        return -1;
    }
    return 0;
}

static int validate_data(const uint8_t *data) {
    if (crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    return 0;
}

static sensor_data_t convert_data(const uint8_t *data) {
    sensor_data_t result;
    int16_t scale_factor = (int16_t)((data[6] << 8) | data[7]);
    if (scale_factor == 0) {
        fprintf(stderr, "Invalid scale factor (0)\n");
        result.differential_pressure = 0.0f;
        result.temperature = 0.0f;
        return result;
    }
    int16_t raw_pressure = (int16_t)((data[0] << 8) | data[1]);
    int16_t raw_temperature = (int16_t)((data[3] << 8) | data[4]);
    result.differential_pressure = (float)raw_pressure / (float)scale_factor;
    result.temperature = (float)raw_temperature / 200.0f;
    return result;
}

static int log_data(const sensor_data_t *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    if (fprintf(log_file, "%s, %.2f Pa, %.2f C\n", timestamp, data->differential_pressure, data->temperature) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    while (!terminate) {
        if (send_command(MEASURE_CMD) != 0) {
            fprintf(stderr, "Failed to send measurement command\n");
            break;
        }
        gpioDelay(MEAS_DELAY_US);

        uint8_t data[READ_LEN];
        if (read_sensor_data(data) != 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            break;
        }

        if (validate_data(data) != 0) {
            fprintf(stderr, "Data validation failed\n");
            break;
        }

        sensor_data_t sensor_data = convert_data(data);
        if (log_data(&sensor_data) != 0) {
            fprintf(stderr, "Failed to log data\n");
            break;
        }

        gpioDelay(1000000);
    }

    cleanup();
    return 0;
}

