    if (si7021_read_raw(handle, 0xF3, &raw) != 0) return -1;
    *temp_c = (175.72f * (float)raw / 65536.0f) - 46.85f;
    return 0;
}

static int si7021_read_humidity(int handle, float *rh_pct)
{
    uint16_t raw;
    if (si7021_read_raw(handle, 0xF5, &raw) != 0) return -1;
    *rh_pct = (125.0f * (float)raw / 65536.0f) - 6.0f;
    if (*rh_pct < 0.0f)   *rh_pct = 0.0f;
    if (*rh_pct > 100.0f) *rh_pct = 100.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor presence check                                               */
/* ------------------------------------------------------------------ */
static int si7021_check_present(int handle)
{
    uint8_t id[8];
    if (i2c_read_bytes(handle, id, 8) != 0) {
        log_message("Si7021 not responding on I2C bus 1, addr 0x40");
        return -1;
    }
    /* Byte 0 of the electronic ID block should be 0x0D for a Si7021 */
    if ((uint8_t)id[0] != 0x0D) {
        char msg[128];
        snprintf(msg, sizeof(msg),
                 "Si7021 electronic ID mismatch: 0x%02X (expected 0x0D)", (uint8_t)id[0]);
        log_message(msg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- sensor presence check --- */
    if (si7021_check_present(g_i2c_handle) != 0) {
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("Si7021 monitoring started");

    /* --- main loop --- */
    while (g_running) {
        float temperature, humidity;

        if (si7021_read_temperature(g_i2c_handle, &temperature) == 0 &&
            si7021_read_humidity(g_i2c_handle, &humidity) == 0) {
            time_t t = time(NULL);
            struct tm tm;
            localtime_r(&t, &tm);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

            FILE *fp = fopen(LOG_FILE, "a");
            if (fp) {
                fprintf(fp, "%s,%.2f,%.2f\n", ts, temperature, humidity);
                fflush(fp);
                fclose(fp);
            }
            printf("%s,%.2f,%.2f\n", ts, temperature, humidity);
        } else {
            log_message("Sensor read failed");
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++)
            sleep(1);
    }

    /* --- cleanup --- */
    if (g_i2c_handle >= 0) i2cClose(g_i2c_handle);
    gpioTerminate();
    log_message("Si7021 monitoring stopped");
    return EXIT_SUCCESS;
}

