#define CONFIG_14BIT 0x60  /* 14-bit temp + 14-bit humidity */
#define CONVERSION_DELAY_US 20000  /* 20 ms for 14-bit resolution */
#define LOG_INTERVAL_S 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_hdc1080(int handle) {
    /* Configure: 14-bit temp, 14-bit humidity, heater off, mode = measure */
    if (i2cWriteByteData(handle, CONFIG_REG, CONFIG_14BIT) < 0) {
        fprintf(stderr, "Error: Failed to write HDC1080 config register.\n");
        return -1;
    }
    return 0;
}

static int read_hdc1080(int handle, float *temperature, float *humidity) {
    char buf[4];

    /* Trigger measurement by pointing to register 0x00 */
    if (i2cWriteByte(handle, TEMP_REG) < 0) {
        fprintf(stderr, "Error: Failed to trigger measurement.\n");
        return -1;
    }

    gpioDelay(CONVERSION_DELAY_US);

