#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

#define SCD40_I2C_ADDR 0x62
#define I2C_BUS 1
#define BUFFER_SIZE 100
#define LOGGING_INTERVAL 60
#define LOG_FILE_DIR "/var/log/scd40_data/"
#define ERROR_LOG_FILE "/var/log/scd40_error.log"
#define MAX_RETRIES 3

typedef struct {
    time_t timestamp;
    int co2;
    float temperature;
    float humidity;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;
static circular_buffer_t buffer;
static pthread_t logging_thread;

static void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (!fp) {
        perror("Failed to open error log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int init_i2c(void) {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int start_periodic_measurement(void) {
    char cmd[2] = {0x21, 0xB1};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        log_error("Failed to start periodic measurement");
        return -1;
    }
    return 0;
}

static int read_scd40_data(int *co2, float *temperature, float *humidity) {
    char cmd[2] = {0xE0, 0x00};
    char buffer[9];
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        log_error("Failed to send read command");
        return -1;
    }

    gpioDelay(10000);

    result = i2cReadDevice(i2c_handle, buffer, 9);
    if (result != 9) {
        log_error("Failed to read 9 bytes from SCD40");
        return -1;
    }

    if (crc8((uint8_t *)buffer, 2) != (uint8_t)buffer[2]) {
        log_error("CO2 CRC check failed");
        return -1;
    }
    if (crc8((uint8_t *)buffer + 3, 2) != (uint8_t)buffer[5]) {
        log_error("Temperature CRC check failed");
        return -1;
    }
    if (crc8((uint8_t *)buffer + 6, 2) != (uint8_t)buffer[8]) {
        log_error("Humidity CRC check failed");
        return -1;
    }

    int co2_raw = (buffer[0] << 8) | buffer[1];
    int temp_raw = (buffer[3] << 8) | buffer[4];
    int hum_raw = (buffer[6] << 8) | buffer[7];

    *co2 = co2_raw;
    *temperature = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
    *humidity = 100.0f * (float)hum_raw / 65535.0f;

    return 0;
}

static void add_to_buffer(circular_buffer_t *buffer, time_t timestamp, int co2, float temperature, float humidity) {
    pthread_mutex_lock(&buffer->mutex);
    buffer->data[buffer->head].timestamp = timestamp;
    buffer->data[buffer->head].co2 = co2;
    buffer->data[buffer->head].temperature = temperature;
    buffer->data[buffer->head].humidity = humidity;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
    buffer->tail = (buffer->head + BUFFER_SIZE - buffer->count) % BUFFER_SIZE;
    pthread_mutex_unlock(&buffer->mutex);
}

static void *logging_thread_func(void *arg) {
    (void)arg;
    while (running) {
        sleep(LOGGING_INTERVAL);
        if (!running) break;

        FILE *fp = fopen(LOG_FILE_DIR "scd40_data.csv", "w");
        if (!fp) {
            log_error("Failed to open data log file for writing");
            continue;
        }
        fprintf(fp, "Timestamp,CO2 (ppm),Temperature (C),Humidity (%%)\n");

        pthread_mutex_lock(&buffer.mutex);
        int start = buffer.tail;
        for (int i = 0; i < buffer.count; i++) {
            int index = (start + i) % BUFFER_SIZE;
            fprintf(fp, "%ld,%d,%.2f,%.2f\n",
                    (long)buffer.data[index].timestamp,
                    buffer.data[index].co2,
                    buffer.data[index].temperature,
                    buffer.data[index].humidity);
        }
        pthread_mutex_unlock(&buffer.mutex);
        fclose(fp);
    }
    return NULL;
}

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cWriteDevice(i2c_handle, (char *){0x3F, 0x86}, 2);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();

    pthread_mutex_lock(&buffer.mutex);
    pthread_mutex_destroy(&buffer.mutex);
    pthread_mutex_unlock(&buffer.mutex);

    pthread_join(logging_thread, NULL);
}

int main(void) {
    if (pthread_mutex_init(&buffer.mutex, NULL) != 0) {
        log_error("Failed to initialize mutex");
        return 1;
    }
    buffer.head = 0;
    buffer.tail = 0;
    buffer.count = 0;

    if (init_i2c() != 0) {
        return 1;
    }

    if (start_periodic_measurement() != 0) {
        cleanup();
        return 1;
    }

    if (mkdir(LOG_FILE_DIR, 0755) == -1 && errno != EEXIST) {
        log_error("Failed to create log directory");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (pthread_create(&logging_thread, NULL, logging_thread_func, NULL) != 0) {
        log_error("Failed to create logging thread");
        cleanup();
        return 1;
    }

    int co2, temp, hum;
    while (running) {
        if (read_scd40_data(&co2, &temp, &hum) == 0) {
            time_t now = time(NULL);
            add_to_buffer(&buffer, now, co2, temp, hum);
        }
        sleep(5);
    }

    cleanup();
    return 0;
}

