#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define ICP10110_ADDR 0x63
#define WHO_AM_I_REG 0x08
#define WHO_AM_I_VAL 0x08
#define MEAS_CMD_REG 0x00
#define MEAS_CMD_VAL 0x00
#define DATA_REG 0x00
#define DATA_LEN 6
#define CALIB_LEN 4
#define SAMPLE_INTERVAL_US 5000000
#define MEAS_DELAY_US 10000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_calibration(int handle, uint16_t calib[CALIB_LEN]) {
    char buf[CALIB_LEN * 2];
    if (i2cReadI2CBlockData(handle, 0x05, buf, sizeof(buf)) != (int)sizeof(buf)) {
        fprintf(stderr, "Error: Failed to read calibration data\n");
        return -1;
    }
    for (int i = 0; i < CALIB_LEN; i++) {
        calib[i] = ((uint16_t)(uint8_t)buf[2 * i] << 8) | (uint8_t)buf[2 * i + 1];
    }
    return 0;
}

static int read_sensor_data(int handle, float *pressure, float *temperature) {
    char cmd = MEAS_CMD_VAL;
    char data[DATA_LEN];

    if (i2cWriteI2CBlockData(handle, MEAS_CMD_REG, &cmd, 1) != 1) {
        fprintf(stderr, "Error: Failed to trigger measurement\n");
        return -1;
    }
    gpioDelay(MEAS_DELAY_US);

    if (i2cReadI2CBlockData(handle, DATA_REG, data, DATA_LEN) != DATA_LEN) {
        fprintf(stderr, "Error: Failed to read sensor data\n");
        return -1;
    }

    uint32_t raw_pressure = ((uint32_t)(uint8_t)data[0] << 16) |
                           ((uint32_t)(uint8_t)data[1] << 8)  |
                           (uint32_t)(uint8_t)data[2];
    uint32_t raw_temperature = ((uint32_t)(uint8_t)data[3] << 16) |
                              ((uint32_t)(uint8_t)data[4] << 8)  |
                              (uint32_t)(uint8_t)data[5];

    uint16_t calib[4];
    if (read_calibration(handle, calib) != 0) {
        return -1;
    }

    float c0 = (float)calib[0] / 8.0f;
    float c1 = (float)calib[1] / 16384.0f;
    float c2 = (float)calib[2] / 16384.0f;
    float c3 = (float)calib[3] / 8192.0f;

    float p_comp = c0 + c1 * raw_pressure + c2 * raw_temperature + c3 * raw_pressure * raw_temperature;
    *pressure = p_comp / 100.0f;
    *temperature = (float)raw_temperature / 65536.0f * 100.0f;

    return 0;
}

static void log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(fp);
    printf("%s,%.2f,%.2f\n", timestamp, pressure, temperature);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ICP10110_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device at 0x%02X\n", ICP10110_ADDR);
        gpioTerminate();
        return 1;
    }

    int who = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n", who, WHO_AM_I_VAL);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("environmental_data.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    float pressure, temperature;
    while (!terminate) {
        if (read_sensor_data(i2c_handle, &pressure, &temperature) == 0) {
            log_data(log_file, pressure, temperature);
        } else {
            fprintf(stderr, "Warning: Sensor read failed, skipping sample\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

