#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define ICP10125_ADDR  0x63
#define LED_PIN        17
#define PRESSURE_THRESHOLD 95000.0f

/* ICP-10125 commands */
#define CMD_READ_ID        0xEF
#define CMD_READ_CALIB     0x66
#define CMD_MEASURE        0x4011  /* high-accuracy mode */

/* Measurement result register */
#define REG_RESULT        0x00

/* Timing */
#define MEASURE_DELAY_MS  20
#define POLL_INTERVAL_MS  1000
#define LED_HALF_PERIOD_MS 250

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* CRC-8 polynomial 0x31, init 0x00 (InvenSense standard) */
static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    uint8_t buf[1] = { cmd };
    if (write(fd, buf, 1) != 1) {
        fprintf(stderr, "I2C write cmd 0x%02X failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_calibration(int fd, uint16_t cal[4]) {
    if (i2c_write_cmd(fd, CMD_READ_CALIB) < 0)
        return -1;
    usleep(2000);

    uint8_t buf[8];
    if (i2c_read_bytes(fd, buf, sizeof(buf)) < 0)
        return -1;

    for (int i = 0; i < 4; i++) {
        cal[i] = (uint16_t)((buf[2 * i] << 8) | buf[2 * i + 1]);
    }
    return 0;
}

static int read_measurement(int fd, const uint16_t cal[4],
                            float *pressure, float *temperature) {
    if (i2c_write_cmd(fd, CMD_MEASURE) < 0)
        return -1;
    usleep(MEASURE_DELAY_MS * 1000);

    uint8_t buf[6];
    if (i2c_read_bytes(fd, buf, sizeof(buf)) < 0)
        return -1;

    /* Verify CRC over pressure (2 bytes) + temperature (2 bytes) */
    if (crc8(buf, 4) != buf[4]) {
        fprintf(stderr, "CRC mismatch on measurement data\n");
        return -1;
    }

    int16_t raw_p = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_t = (int16_t)((buf[3] << 8) | buf[4]);

    /* InvenSense ICP-10125 conversion formulas */
    float p = (float)raw_p;
    float t = (float)raw_t;
    float t_fine = t / 5.0f;

    float c0 = (float)cal[0];
    float c1 = (float)cal[1];
    float c00 = (float)cal[2];
    float c10 = (float)cal[3];

    float p_comp = c0 * 2.0f + c1 * t_fine;
    float p_pa = c00 + p_comp * c10;

    *pressure = p_pa;
    *temperature = t_fine;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, ICP10125_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                ICP10125_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    /* Probe sensor by reading ID register */
    if (i2c_write_cmd(fd, CMD_READ_ID) < 0) {
        fprintf(stderr, "Sensor not responding at 0x%02X\n", ICP10125_ADDR);
        close(fd);
        return 1;
    }
    uint8_t id_buf[2];
    if (i2c_read_bytes(fd, id_buf, 2) < 0) {
        fprintf(stderr, "Sensor not responding at 0x%02X\n", ICP10125_ADDR);
        close(fd);
        return 1;
    }

    /* Read calibration coefficients */
    uint16_t cal[4];
    if (read_calibration(fd, cal) < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(fd);
        return 1;
    }

    /* Open GPIO chip and request LED line */
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        /* Fallback for older kernel naming */
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "Cannot open GPIO chip: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    struct gpiod_line *led = gpiod_chip_get_line(chip, LED_PIN);
    if (!led) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        close(fd);
        return 1;
    }

    if (gpiod_line_request_output(led, "icp10125-led", 0) < 0) {
        fprintf(stderr, "Cannot request GPIO line %d as output: %s\n",
                LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        close(fd);
        return 1;
    }

    printf("ICP-10125 initialized. Reading every %d ms. Press Ctrl+C to exit.\n",
           POLL_INTERVAL_MS);

    while (g_running) {
        float pressure, temperature;
        if (read_measurement(fd, cal, &pressure, &temperature) < 0) {
            fprintf(stderr, "Measurement read error; retrying next cycle.\n");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);

        int led_freq = (pressure < PRESSURE_THRESHOLD) ? 5 : 1;
        int half_period_us = (led_freq > 0) ? (LED_HALF_PERIOD_MS * 1000 / led_freq) : 0;
        int on_us = half_period_us;
        int off_us = half_period_us;

        while (g_running) {
            if (gpiod_line_set_value(led, 1) < 0) {
                fprintf(stderr, "Failed to set LED high: %s\n", strerror(errno));
                break;
            }
            usleep(on_us);
            if (!g_running)
                break;

