#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x44
#define PORT 8080
#define MEASUREMENT_CMD 0xFD
#define MEASUREMENT_DELAY_US 10000
#define MAX_RETRIES 3
#define RETRY_DELAY_US 1000
#define HTML_BUFFER_SIZE 1024

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int server_fd = -1;

void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

int read_sht40(int handle, float *temperature, float *humidity) {
    unsigned char cmd = MEASUREMENT_CMD;
    unsigned char buf[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(handle, &cmd, 1) != 0) {
            fprintf(stderr, "I2C write error (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_US);

        if (i2cReadDevice(handle, buf, 6) != 6) {
            fprintf(stderr, "I2C read error (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        unsigned int raw_temperature = (buf[0] << 8) | buf[1];
        unsigned int raw_humidity = (buf[3] << 8) | buf[4];

        *temperature = -45.0f + (175.0f * (float)raw_temperature / 65535.0f);
        *humidity = -6.0f + (125.0f * (float)raw_humidity / 65535.0f);

        if (*humidity < 0.0f) *humidity = 0.0f;
        if (*humidity > 100.0f) *humidity = 100.0f;

        return 0;
    }

    fprintf(stderr, "Failed to read SHT40 after %d retries.\n", MAX_RETRIES);
    return -1;
}

int format_html(char *buffer, size_t buffer_size, float temperature, float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    snprintf(buffer, buffer_size,
             "HTTP/1.1 200 OK\r\n"
             "Content-Type: text/html\r\n"
             "Connection: close\r\n"
             "\r\n"
             "<!DOCTYPE html>\r\n"
             "<html>\r\n"
             "<head>\r\n"
             "<title>SHT40 Sensor Data</title>\r\n"
             "<meta http-equiv=\"refresh\" content=\"5\">\r\n"
             "</head>\r\n"
             "<body>\r\n"
             "<h1>SHT40 Sensor Data</h1>\r\n"
             "<p>Timestamp: %s</p>\r\n"
             "<p>Temperature: %.2f &deg;C</p>\r\n"
             "<p>Humidity: %.2f %%</p>\r\n"
             "</body>\r\n"
             "</html>\r\n",
             timestamp, temperature, humidity);
    return 0;
}

int send_data(int fd, const char *data, size_t data_len) {
    size_t sent = 0;
    while (sent < data_len) {
        ssize_t bytes = send(fd, data + sent, data_len - sent, 0);
        if (bytes < 0) {
            if (errno == EINTR) continue;
            perror("send() failed");
            return -1;
        }
        sent += (size_t)bytes;
    }
    return 0;
}

int main() {
    struct sockaddr_in address;
    int opt = 1;
    socklen_t addrlen = sizeof(address);
    char html_buffer[HTML_BUFFER_SIZE];
    float temperature, humidity;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d, addr 0x%02X: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("socket() failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt() failed");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind() failed");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        perror("listen() failed");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Server listening on port %d...\n", PORT);

    while (running) {
        int client_fd = accept(server_fd, (struct sockaddr *)&address, &addrlen);
        if (client_fd < 0) {
            if (errno == EINTR) continue;
            perror("accept() failed");
            continue;
        }

        if (read_sht40(i2c_handle, &temperature, &humidity) == 0) {
            format_html(html_buffer, sizeof(html_buffer), temperature, humidity);
            if (send_data(client_fd, html_buffer, strlen(html_buffer)) < 0) {
                close(client_fd);
            } else {
                close(client_fd);
            }
        } else {
            const char *error_page =
                "HTTP/1.1 500 Internal Server Error\r\n"
                "Content-Type: text/html\r\n"
                "Connection: close\r\n"
                "\r\n"
                "<!DOCTYPE html>\r\n"
                "<html>\r\n"
                "<head>\r\n"
                "<title>Error</title>\r\n"
                "</head>\r\n"
                "<body>\r\n"
                "<h1>Error</h1>\r\n"
                "<p>Failed to read sensor data.</p>\r\n"
                "</body>\r\n"
                "</html>\r\n";
            send_data(client_fd, error_page, strlen(error_page));
            close(client_fd);
        }
    }

    if (server_fd >= 0) close(server_fd);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();

    printf("Server shut down cleanly.\n");
    return 0;
}

