#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HDC2010_ADDR 0x40
#define TEMP_REG 0x00
#define HUM_REG 0x02
#define MEAS_CONFIG_REG 0x0E
#define CONFIG_REG 0x0F
#define MEAS_CONFIG_TRIGGER 0x01
#define MEAS_CONFIG_POLL_TIMEOUT_MS 500
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to reg 0x%02X (pigpio rc=%d)\n", value, reg, rc);
    }
    return rc;
}

static int read_reg(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X (pigpio rc=%d)\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int trigger_measurement(void) {
    if (write_reg(MEAS_CONFIG_REG, MEAS_CONFIG_TRIGGER) < 0) return -1;
    for (int i = 0; i < MEAS_CONFIG_POLL_TIMEOUT_MS; i++) {
        uint8_t cfg;
        if (read_reg(MEAS_CONFIG_REG, &cfg) < 0) return -1;
        if ((cfg & MEAS_CONFIG_TRIGGER) == 0) return 0;
        gpioDelay(1000);
    }
    fprintf(stderr, "Measurement timeout: MEAS_CONFIG_REG did not clear\n");
    return -1;
}

static int read_temperature(float *temp) {
    uint8_t t_msb, t_lsb;
    if (read_reg(TEMP_REG, &t_msb) < 0) return -1;
    if (read_reg(TEMP_REG + 1, &t_lsb) < 0) return -1;
    uint16_t raw = ((uint16_t)t_msb << 8) | t_lsb;
    *temp = ((float)raw / 65536.0f) * 165.0f - 40.0f;
    return 0;
}

static int read_humidity(float *hum) {
    uint8_t h_msb, h_lsb;
    if (read_reg(HUM_REG, &h_msb) < 0) return -1;
    if (read_reg(HUM_REG + 1, &h_lsb) < 0) return -1;
    uint16_t raw = ((uint16_t)h_msb << 8) | h_lsb;
    *hum = ((float)raw / 65536.0f) * 100.0f;
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, HDC2010_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at 0x%02X (pigpio rc=%d)\n", HDC2010_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint8_t config;
    if (read_reg(CONFIG_REG, &config) < 0) {
        fprintf(stderr, "Sensor not responding (CONFIG read failed) - check wiring and address\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int ok = 0;
        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            if (trigger_measurement() == 0) {
                float temp, hum;
                if (read_temperature(&temp) == 0 && read_humidity(&hum) == 0) {
                    printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, hum);
                    fflush(stdout);
                    ok = 1;
                    break;
                }
            }
            gpioDelay(100000);
        }

        if (!ok) {
            fprintf(stderr, "Failed to read sensor after %d attempts\n", MAX_RETRIES);
        }

        for (int s = 0; s < 5 && running; s++) {
            sleep(1);
        }
    }

    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

