#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x25
#define MEASURE_CMD    0x362F
#define READ_LEN       6
#define POLL_DELAY_US  500000  /* 500 ms */
#define MEASURE_DELAY_US 45000 /* 45 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* CRC-8 with polynomial 0x31, initial value 0xFF (Sensirion spec) */
static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_sdp800(int handle, int16_t *pressure, int16_t *temperature) {
    uint8_t cmd[2] = {
        (uint8_t)((MEASURE_CMD >> 8) & 0xFF),
        (uint8_t)(MEASURE_CMD & 0xFF)
    };
    uint8_t buf[READ_LEN];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: failed to write measurement command to I2C device.\n");
        return -1;
    }

    gpioDelay(MEASURE_DELAY_US);

    if (i2cReadDevice(handle, (char *)buf, READ_LEN) != READ_LEN) {
        fprintf(stderr, "Error: failed to read 6 bytes from I2C device.\n");
        return -1;
    }

    /* Verify CRC for pressure word (bytes 0-1, CRC byte 2) */
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: pressure CRC mismatch (calc=0x%02X, got=0x%02X).\n",
                crc8(buf, 2), buf[2]);
        return -1;
    }

    /* Verify CRC for temperature word (bytes 3-4, CRC byte 5) */
    if (crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "Error: temperature CRC mismatch (calc=0x%02X, got=0x%02X).\n",
                crc8(buf + 3, 2), buf[5]);
        return -1;
    }

    *pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature = (int16_t)((buf[3] << 8) | buf[4]);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at address 0x%02X (handle=%d).\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SDP800-500Pa differential pressure sensor reader\n");
