#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_MODE 0
#define GPIO_CHIP "gpiochip0"
#define SSR_PIN 17
#define LOG_FILE "reflow_log.csv"
#define PROFILE_FILE "profile.txt"
#define SAMPLE_INTERVAL_SEC 1
#define MAX_SPI_RETRIES 3

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *ssr_line = NULL;

typedef struct {
    double Kp, Ki, Kd;
    double integral, prev_error;
} PIDController;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }
    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }
    return 0;
}

static int gpio_init(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }
    ssr_line = gpiod_chip_get_line(chip, SSR_PIN);
    if (!ssr_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", SSR_PIN, strerror(errno));
        gpiod_chip_close(chip); chip = NULL; return -1;
    }
    if (gpiod_line_request_output(ssr_line, "reflow-ssr", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", SSR_PIN, strerror(errno));
        gpiod_chip_close(chip); chip = NULL; ssr_line = NULL; return -1;
    }
    return 0;
}

static int read_max6675(int16_t *temp_raw) {
    uint8_t tx[3] = {0x00, 0x00, 0x00};
    uint8_t rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    for (int attempt = 0; attempt < MAX_SPI_RETRIES; attempt++) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) >= 0) {
            uint16_t word = ((uint16_t)rx[1] << 8) | rx[2];
            if (word & 0x0004) {
                fprintf(stderr, "MAX6675 open-circuit detected (word=0x%04X)\n", word);
                return -1;
            }
            *temp_raw = (int16_t)(word >> 3);
            return 0;
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d): %s\n", attempt + 1, MAX_SPI_RETRIES, strerror(errno));
        usleep(10000);
    }
    fprintf(stderr, "SPI communication failed after %d retries\n", MAX_SPI_RETRIES);
    return -1;
}

static double convert_temp(int16_t raw) {
    return (double)raw * 0.25;
}

static double pid_control(PIDController *pid, double setpoint, double actual) {
    double error = setpoint - actual;
    pid->integral += error;
    double output = pid->Kp * error + pid->Ki * pid->integral + pid->Kd * (error - pid->prev_error);
    pid->prev_error = error;
    if (output < 0.0) output = 0.0;
    if (output > 1.0) output = 1.0;
    return output;
}

static void set_ssr_duty(double duty) {
    if (duty < 0.0) duty = 0.0;
    if (duty > 1.0) duty = 1.0;
    int val = (int)(duty * 255.0);
    if (gpiod_line_set_value(ssr_line, val > 0 ? 1 : 0) < 0) {
        fprintf(stderr, "Error setting SSR GPIO value: %s\n", strerror(errno));
    }
}

static void log_data(double temp, double setpoint, double duty) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", ts, temp, setpoint, duty);
    fflush(log_file);
}

static void load_profile(double **times, double **temps, int *n) {
    FILE *fp = fopen(PROFILE_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening profile file %s: %s\n", PROFILE_FILE, strerror(errno));
        *n = 0;
        return;
    }
    int count = 0;
    char line[256];
    while (fgets(line, sizeof(line), fp) && count < 100) {
        double t, T;
        if (sscanf(line, "%lf,%lf", &t, &T) == 2) {
            if (t >= 0.0 && t <= 300.0 && T >= 150.0 && T <= 300.0) {
                if (count == 0) {
                    *times = (double*)malloc(count * sizeof(double));
                    *temps = (double*)malloc(count * sizeof(double));
                } else {
                    double *t_ptr = (double*)realloc(*times, (count + 1) * sizeof(double));
                    double *T_ptr = (double*)realloc(*temps, (count + 1) * sizeof(double));
                    if (t_ptr && T_ptr) {
                        *times = t_ptr;
                        *temps = T_ptr;
                        *times[count] = t;
                        *temps[count] = T;
                        count++;
                    } else {
                        fprintf(stderr, "Memory reallocation failed\n");
                        break;
                    }
                }
            }
        }
    }
    fclose(fp);
    *n = count;
    if (*n == 0) {
        fprintf(stderr, "No valid profile data found\n");
    }
}

static void cleanup(void) {
    if (ssr_line) {
        gpiod_line_set_value(ssr_line, 0);
        gpiod_line_release(ssr_line);
        ssr_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (spi_init() < 0) { cleanup(); return 1; }
    if (gpio_init() < 0) { cleanup(); return 1; }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup(); return 1;
    }
    fprintf(log_file, "# timestamp,temperature_celsius,target_celsius,ssr_duty_percent\n");
    fflush(log_file);

    double times[100], temps[100];
    int n = 0;
    load_profile(&times, &temps, &n);

    PIDController pid = {0.1, 0.001, 0.01, 0.0, 0.0};
    double setpoint = temps[0];
    int idx = 0;

    while (running) {
        int16_t raw;
        if (read_max6675(&raw) < 0) {
            fprintf(stderr, "Sensor read error, skipping cycle\n");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }
        double temp = convert_temp(raw);
        double duty = pid_control(&pid, setpoint, temp);
        set_ssr_duty(duty);
        log_data(temp, setpoint, duty);

        if (idx < n - 1) {
            setpoint = temps[idx + 1];
        } else {
            setpoint = temps[n - 1];
        }
        idx++;

        sleep(SAMPLE_INTERVAL_SEC);
    }

    cleanup();
    return 0;
}

