#define GPIO_CHIP "gpiochip0"
#define HEATER_ENABLE_PIN 17
#define PWM_PIN 18
#define LOG_FILE "greenhouse.log"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *enable_line = NULL;
static struct gpiod_line *pwm_line = NULL;

typedef struct {
    float Kp;
    float Ki;
    float Kd;
    float integral;
    float previous_error;
} PIDController;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(float *temp) {
    char path[256];
    char buf[256];
    FILE *fp;
    int ret;

    snprintf(path, sizeof(path), "%s/%s/w1_slave", SENSOR_DIR, getenv("W1_SLAVE_ID"));
    fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    ret = fscanf(fp, "%255s %255s", buf, buf);
