#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define AHT20_ADDR     0x38
#define GPIO_CHIP       "gpiochip4"
#define GPIO_LINE       17
#define HUMIDITY_HIGH  60.0f
#define HUMIDITY_LOW   55.0f
#define MAX_RETRIES    3
#define RETRY_DELAY_MS 10
#define POLL_INTERVAL_S 5
#define MEAS_DELAY_MS  80

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_ms(unsigned int ms) {
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

static int i2c_write(int fd, const uint8_t *buf, size_t len) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        ssize_t n = write(fd, buf, len);
        if (n == (ssize_t)len) return 0;
        if (n < 0) {
            fprintf(stderr, "I2C write error (attempt %d): %s\n", attempt + 1, strerror(errno));
        } else {
            fprintf(stderr, "I2C short write (attempt %d): %zd/%zu\n", attempt + 1, n, len);
        }
        sleep_ms(RETRY_DELAY_MS);
    }
    return -1;
}

static int i2c_read(int fd, uint8_t *buf, size_t len) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        ssize_t n = read(fd, buf, len);
        if (n == (ssize_t)len) return 0;
        if (n < 0) {
            fprintf(stderr, "I2C read error (attempt %d): %s\n", attempt + 1, strerror(errno));
        } else {
            fprintf(stderr, "I2C short read (attempt %d): %zd/%zu\n", attempt + 1, n, len);
        }
        sleep_ms(RETRY_DELAY_MS);
    }
    return -1;
}

static int aht20_init(int fd) {
    uint8_t init_cmd[] = {0xBE, 0x08, 0x00};
    if (i2c_write(fd, init_cmd, sizeof(init_cmd)) != 0) {
        fprintf(stderr, "AHT20 init failed after %d retries\n", MAX_RETRIES);
        return -1;
    }
    sleep_ms(20);
    return 0;
}

static int aht20_read_humidity(int fd, float *humidity) {
    uint8_t trigger_cmd[] = {0xAC, 0x33, 0x00};
    if (i2c_write(fd, trigger_cmd, sizeof(trigger_cmd)) != 0) {
        fprintf(stderr, "AHT20 trigger failed after %d retries\n", MAX_RETRIES);
        return -1;
    }
    sleep_ms(MEAS_DELAY_MS);

    uint8_t data[6];
    if (i2c_read(fd, data, sizeof(data)) != 0) {
        fprintf(stderr, "AHT20 read failed after %d retries\n", MAX_RETRIES);
        return -1;
    }

    if (data[0] & 0x80) {
        fprintf(stderr, "AHT20 busy or not calibrated (status=0x%02X)\n", data[0]);
        return -1;
    }

    uint32_t raw_humidity = ((uint32_t)data[1] << 12) |
                           ((uint32_t)data[2] << 4)  |
                           ((uint32_t)data[3] >> 4);
    *humidity = (float)raw_humidity / 1048576.0f * 100.0f;
    return 0;
}

static void control_dehumidifier(struct gpiod_line *line, float humidity) {
    int val = (humidity > HUMIDITY_HIGH) ? 1 : 0;
    if (gpiod_line_set_value(line, val) < 0) {
        fprintf(stderr, "Failed to set GPIO %d: %s\n", GPIO_LINE, strerror(errno));
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", AHT20_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (aht20_init(i2c_fd) != 0) {
        fprintf(stderr, "AHT20 sensor not detected or init failed\n");
        close(i2c_fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    struct gpiod_line *relay = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!relay) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(relay, "dehumidifier", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO %d as output: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    printf("Dehumidifier control started. Press Ctrl+C to exit.\n");

    while (running) {
        float humidity;
        if (aht20_read_humidity(i2c_fd, &humidity) == 0) {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
            printf("[%s] Humidity: %.2f%%\n", ts, humidity);
            control_dehumidifier(relay, humidity);
        } else {
            fprintf(stderr, "Sensor read failed; continuing...\n");
        }
        sleep(POLL_INTERVAL_S);
    }

    gpiod_line_set_value(relay, 0);
    gpiod_line_release(relay);
    gpiod_chip_close(chip);
    close(i2c_fd);
    printf("\nExiting cleanly.\n");
    return 0;
}

