#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <syslog.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <time.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define I2C_DEVICE "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define TRIGGER_TEMP_MEASURE_NO_HOLD 0xE3
#define TRIGGER_HUMID_MEASURE_NO_HOLD 0xE5
#define MEASURE_DELAY_MS 50
#define POST_INTERVAL_SEC 60
#define API_ENDPOINT "http://api.example.com/humidity"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_bytes(int fd, unsigned char *buf, int len) {
    int retries = 3;
    while (retries > 0) {
        if (read(fd, buf, len) == len) {
            return 0;
        }
        syslog(LOG_ERR, "I2C read failed: %s, retries left: %d", strerror(errno), retries - 1);
        retries--;
        usleep(100000);
    }
    syslog(LOG_ERR, "I2C read failed after retries: %s", strerror(errno));
    return -1;
}

static int i2c_write_byte(int fd, unsigned char cmd) {
    int retries = 3;
    while (retries > 0) {
        if (write(fd, &cmd, 1) == 1) {
            return 0;
        }
        syslog(LOG_ERR, "I2C write failed: %s, retries left: %d", strerror(errno), retries - 1);
        retries--;
        usleep(100000);
    }
    syslog(LOG_ERR, "I2C write failed after retries: %s", strerror(errno));
    return -1;
}

static int read_raw_temperature(int fd, int16_t *raw_temp) {
    if (i2c_write_byte(fd, TRIGGER_TEMP_MEASURE_NO_HOLD) != 0) {
        return -1;
    }
    usleep(MEASURE_DELAY_MS * 1000);

    unsigned char buf[3];
    if (i2c_read_bytes(fd, buf, 3) != 0) {
        return -1;
    }

    *raw_temp = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_humidity(int fd, int16_t *raw_hum) {
    if (i2c_write_byte(fd, TRIGGER_HUMID_MEASURE_NO_HOLD) != 0) {
        return -1;
    }
    usleep(MEASURE_DELAY_MS * 1000);

    unsigned char buf[3];
    if (i2c_read_bytes(fd, buf, 3) != 0) {
        return -1;
    }

    *raw_hum = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static float convert_temperature(int16_t raw_temp) {
    return -46.85 + 175.72 * (float)raw_temp / 65536.0;
}

static float convert_humidity(int16_t raw_hum) {
    float humidity = -6.0 + 125.0 * (float)raw_hum / 65536.0;
    if (humidity < 0.0) humidity = 0.0;
    if (humidity > 100.0) humidity = 100.0;
    return humidity;
}

static int post_humidity(float humidity) {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        syslog(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        return -1;
    }

    struct sockaddr_in servaddr;
    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(80);

    if (inet_pton(AF_INET, "8.8.8.8", &servaddr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address/ Address not supported: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    if (connect(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        syslog(LOG_ERR, "Connection failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    char body[128];
    snprintf(body, sizeof(body), "humidity=%.2f", humidity);

    char request[512];
    snprintf(request, sizeof(request),
             "POST %s HTTP/1.1\r\n"
             "Host: api.example.com\r\n"
             "Content-Type: application/json\r\n"
             "Content-Length: %zu\r\n"
             "Connection: close\r\n"
             "\r\n"
             "%s",
             API_ENDPOINT, strlen(body), body);

    if (write(sockfd, request, strlen(request)) < 0) {
        syslog(LOG_ERR, "HTTP write failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    char response[1024];
    ssize_t bytes = read(sockfd, response, sizeof(response) - 1);
    if (bytes > 0) {
        response[bytes] = '\0';
        syslog(LOG_INFO, "HTTP response: %s", response);
    } else {
        syslog(LOG_ERR, "HTTP read failed: %s", strerror(errno));
    }

    close(sockfd);
    return 0;
}

int main(void) {
    openlog("htu21d_poster", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open %s: %s", I2C_DEVICE, strerror(errno));
        closelog();
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address 0x%02X: %s", HTU21D_ADDR, strerror(errno));
        close(fd);
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "HTU21D poster started");

    while (running) {
        int16_t raw_temp, raw_hum;

        if (read_raw_temperature(fd, &raw_temp) != 0) {
            syslog(LOG_ERR, "Failed to read temperature");
        } else if (read_raw_humidity(fd, &raw_hum) != 0) {
            syslog(LOG_ERR, "Failed to read humidity");
        } else {
            float temp = convert_temperature(raw_temp);
            float hum = convert_humidity(raw_hum);
            syslog(LOG_INFO, "Temperature: %.2f C, Humidity: %.2f %%", temp, hum);

            if (post_humidity(hum) != 0) {
                syslog(LOG_ERR, "Failed to post humidity data");
            }
        }

        for (int i = 0; i < POST_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    syslog(LOG_INFO, "HTU21D poster shutting down");
    close(fd);
    closelog();
    return 0;
}

