#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_REG_CHIP_ID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_CALIB 0x88
#define BMP280_CHIP_ID 0x58
#define BMP280_RESET_CMD 0xB6

#define PRESSURE_HIGH_THRESHOLD 1020.0
#define PRESSURE_LOW_THRESHOLD 980.0
#define SAMPLE_INTERVAL_SEC 2
#define MAX_RETRIES 3

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_t;

static bmp280_calib_t calib;
static int32_t t_fine;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "I2C read block failed (reg 0x%02X, len %u): %d\n", reg, len, rc);
        return -1;
    }
    if ((uint32_t)rc != len) {
        fprintf(stderr, "I2C read block short read (reg 0x%02X): got %d, expected %u\n", reg, rc, len);
        return -1;
    }
    return 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write byte failed (reg 0x%02X, val 0x%02X): %d\n", reg, val, rc);
        return -1;
    }
    return 0;
}

static int bmp280_init(void) {
    uint8_t chip_id;
    if (i2c_read_block(i2c_handle, BMP280_REG_CHIP_ID, &chip_id, 1) != 0) {
        return -1;
    }
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Chip ID mismatch: got 0x%02X, expected 0x%02X\n", chip_id, BMP280_CHIP_ID);
        return -1;
    }
    printf("BMP280 detected (chip ID 0x%02X)\n", chip_id);

    uint8_t calib_buf[24];
    if (i2c_read_block(i2c_handle, BMP280_REG_CALIB, calib_buf, 24) != 0) {
        return -1;
    }

    calib.dig_T1 = (uint16_t)(calib_buf[0] | (calib_buf[1] << 8));
    calib.dig_T2 = (int16_t)(calib_buf[2] | (calib_buf[3] << 8));
    calib.dig_T3 = (int16_t)(calib_buf[4] | (calib_buf[5] << 8));
    calib.dig_P1 = (uint16_t)(calib_buf[6] | (calib_buf[7] << 8));
    calib.dig_P2 = (int16_t)(calib_buf[8] | (calib_buf[9] << 8));
    calib.dig_P3 = (int16_t)(calib_buf[10] | (calib_buf[11] << 8));
    calib.dig_P4 = (int16_t)(calib_buf[12] | (calib_buf[13] << 8));
    calib.dig_P5 = (int16_t)(calib_buf[14] | (calib_buf[15] << 8));
    calib.dig_P6 = (int16_t)(calib_buf[16] | (calib_buf[17] << 8));
    calib.dig_P7 = (int16_t)(calib_buf[18] | (calib_buf[19] << 8));
    calib.dig_P8 = (int16_t)(calib_buf[20] | (calib_buf[21] << 8));
    calib.dig_P9 = (int16_t)(calib_buf[22] | (calib_buf[23] << 8));

    if (i2c_write_byte(i2c_handle, BMP280_REG_CONFIG, 0x00) != 0) return -1;
    if (i2c_write_byte(i2c_handle, BMP280_REG_CTRL_MEAS, 0x27) != 0) return -1;

    return 0;
}

static int bmp280_read_raw(int32_t *raw_temp, int32_t *raw_press) {
    if (i2c_write_byte(i2c_handle, BMP280_REG_CTRL_MEAS, 0x27) != 0) return -1;
    gpioDelay(10000);

    uint8_t data[6];
    if (i2c_read_block(i2c_handle, BMP280_REG_PRESS_MSB, data, 6) != 0) return -1;

    *raw_press = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | ((int32_t)data[2] >> 4);
    *raw_temp = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | ((int32_t)data[5] >> 4);
    return 0;
}

static double bmp280_compensate_temperature(int32_t raw_temp) {
    int32_t var1, var2;
    var1 = ((((raw_temp >> 3) - ((int32_t)calib.dig_T1 << 1))) * ((int32_t)calib.dig_T2)) >> 11;
    var2 = (((((raw_temp >> 4) - ((int32_t)calib.dig_T1)) * ((raw_temp >> 4) - ((int32_t)calib.dig_T1))) >> 12) * ((int32_t)calib.dig_T3)) >> 14;
    t_fine = var1 + var2;
    return (t_fine * 5 + 128) >> 8;
}

static double bmp280_compensate_pressure(int32_t raw_press) {
    int64_t var1, var2, p;
    var1 = ((int64_t)t_fine) - 128000;
    var2 = var1 * var1 * (int64_t)calib.dig_P6;
    var2 = var2 + ((var1 * (int64_t)calib.dig_P5) << 17);
    var2 = var2 + (((int64_t)calib.dig_P4) << 35);
    var1 = ((var1 * var1 * (int64_t)calib.dig_P3) >> 8) + ((var1 * (int64_t)calib.dig_P2) << 12);
    var1 = (((((int64_t)1) << 47) + var1)) * ((int64_t)calib.dig_P1) >> 33;
    if (var1 == 0) return 0.0;
    p = 1048576 - raw_press;
    p = (((p << 31) - var2) * 3125) / var1;
    var1 = (((int64_t)calib.dig_P9) * (p >> 13) * (p >> 13)) >> 25;
    var2 = (((int64_t)calib.dig_P8) * p) >> 19;
    p = ((p + var1 + var2) >> 8) + (((int64_t)calib.dig_P7) << 4);
    return (double)p / 25600.0;
}

static void log_pressure_breach(double pressure) {
    FILE *fp = fopen("pressure_log.txt", "a");
    if (!fp) {
        perror("fopen pressure_log.txt");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s - Pressure: %.2f hPa\n", ts, pressure);
    fclose(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (bmp280_init() != 0) {
        fprintf(stderr, "BMP280 init failed\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Monitoring pressure (threshold %.1f - %.1f hPa). Ctrl+C to exit.\n", PRESSURE_LOW_THRESHOLD, PRESSURE_HIGH_THRESHOLD);

    while (!terminate) {
        int32_t raw_t, raw_p;
        if (bmp280_read_raw(&raw_t, &raw_p) != 0) {
            fprintf(stderr, "Read failed, retrying...\n");
            for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
                gpioDelay(100000);
                if (bmp280_init() == 0) break;
                if (attempt == MAX_RETRIES - 1) {
                    fprintf(stderr, "Init failed after %d retries\n", MAX_RETRIES);
                    break;
                }
            }
            continue;
        }

        double temp = bmp280_compensate_temperature(raw_t) / 100.0;
        double press = bmp280_compensate_pressure(raw_p);

        printf("T: %.2f C, P: %.2f hPa\n", temp, press);

