#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <stdint.h>
#include <gpiod.h>

#define TMP117_ADDR 0x48
#define AHT20_ADDR 0x38
#define PIR_PIN 17
#define I2C_BUS "/dev/i2c-1"
#define GPIO_CHIP "gpiochip4"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_S 1

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *pir_line = NULL;
static char current_log_file[64] = "logger.log";

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write(int fd, uint8_t *buf, size_t len) {
    if (write(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t *buf, size_t len) {
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int read_tmp117(int fd, float *temp) {
    uint8_t cmd[2] = {0x00, 0x00};
    uint8_t data[2];
    int retries = RETRY_COUNT;

    while (retries > 0) {
        if (i2c_write(fd, cmd, 2) == 0) {
            usleep(5000);
            if (i2c_read(fd, data, 2) == 0) {
                int16_t raw = (data[0] << 8) | data[1];
                *temp = raw * 0.0078125f;
                return 0;
            }
        }
        retries--;
        if (retries > 0) usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

int read_aht20(int fd, float *temp, float *hum) {
    uint8_t init_cmd[] = {0xBE, 0x08, 0x00};
    uint8_t measure_cmd[] = {0xAC, 0x33, 0x00};
    uint8_t data[7];
    int retries = RETRY_COUNT;

    while (retries > 0) {
        if (i2c_write(fd, init_cmd, 3) == 0) {
            usleep(80000);
            if (i2c_write(fd, measure_cmd, 3) == 0) {
                usleep(80000);
                if (i2c_read(fd, data, 7) == 0) {
                    if (data[0] & 0x80) {
                        usleep(20000);
                        if (i2c_read(fd, data, 7) == 0) {
                            uint32_t raw_hum = ((uint32_t)data[1] << 12) | ((uint32_t)data[2] << 4) | (data[3] >> 4);
                            uint32_t raw_temp = ((uint32_t)(data[3] & 0x0F) << 16) | ((uint32_t)data[4] << 8) | data[5];
                            *hum = (float)raw_hum / 1048576.0f * 100.0f;
                            *temp = (float)raw_temp / 1048576.0f * 200.0f - 50.0f;
                            return 0;
                        }
                    }
                }
            }
        }
        retries--;
        if (retries > 0) usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

int read_pir(struct gpiod_line *line) {
    return gpiod_line_get_value(line);
}

void get_timestamp(char *buf, size_t len) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", tm_info);
}

int log_data(const char *ts, float temp, float hum, int motion) {
    FILE *fp = fopen(current_log_file, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return -1;
    }
    fprintf(fp, "%s,%.2f,%.2f,%d\n", ts, temp, hum, motion);
    fclose(fp);
    return 0;
}

void cleanup(void) {
    if (pir_line) gpiod_line_release(pir_line);
    if (chip) gpiod_chip_close(chip);
    if (i2c_fd >= 0) close(i2c_fd);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }
    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", PIR_PIN, strerror(errno));
        cleanup();
        return 1;
    }
    if (gpiod_line_request_input(pir_line, "pir_logger") < 0) {
        fprintf(stderr, "Failed to request GPIO line as input: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, TMP117_ADDR) < 0) {
        fprintf(stderr, "Failed to set TMP117 I2C address: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "Failed to set AHT20 I2C address: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    while (running) {
        float temp = 0.0f, hum = 0.0f;
        int motion = 0;
        char ts[32];

        get_timestamp(ts, sizeof(ts));

        if (read_tmp117(i2c_fd, &temp) != 0) {
            fprintf(stderr, "%s - Error reading TMP117\n", ts);
        }

        if (read_aht20(i2c_fd, &temp, &hum) != 0) {
            fprintf(stderr, "%s - Error reading AHT20\n", ts);
        }

        motion = read_pir(pir_line);

        if (log_data(ts, temp, hum, motion) != 0) {
            fprintf(stderr, "%s - Error logging data\n", ts);
        }

        sleep(SAMPLE_INTERVAL_S);
    }

    cleanup();
    return 0;
}

