#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENABLE_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

#define POLL_INTERVAL_SEC 2
#define MOTOR_RUN_TIME_SEC 5

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
    fflush(stdout);
}

static int set_motor(struct gpiod_line *enable, struct gpiod_line *in1, struct gpiod_line *in2, int enable_val, int in1_val, int in2_val) {
    if (gpiod_line_set_value(enable, enable_val) < 0) {
        fprintf(stderr, "Error setting enable line value: %s\n", strerror(errno));
        return -1;
    }
    if (gpiod_line_set_value(in1, in1_val) < 0) {
        fprintf(stderr, "Error setting IN1 line value: %s\n", strerror(errno));
        return -1;
    }
    if (gpiod_line_set_value(in2, in2_val) < 0) {
        fprintf(stderr, "Error setting IN2 line value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(struct gpiod_line *enable, struct gpiod_line *in1, struct gpiod_line *in2) {
    if (enable) gpiod_line_set_value(enable, 0);
    if (in1) gpiod_line_set_value(in1, 0);
    if (in2) gpiod_line_set_value(in2, 0);
    if (enable) gpiod_line_release(enable);
    if (in1) gpiod_line_release(in1);
    if (in2) gpiod_line_release(in2);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *rain_line = NULL;
    struct gpiod_line *enable_line = NULL;
    struct gpiod_line *in1_line = NULL;
    struct gpiod_line *in2_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip4: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    rain_line = gpiod_chip_get_line(chip, RAIN_SENSOR_PIN);
    enable_line = gpiod_chip_get_line(chip, MOTOR_ENABLE_PIN);
    in1_line = gpiod_chip_get_line(chip, MOTOR_IN1_PIN);
    in2_line = gpiod_chip_get_line(chip, MOTOR_IN2_PIN);

    if (!rain_line || !enable_line || !in1_line || !in2_line) {
        fprintf(stderr, "Error getting GPIO lines: %s\n", strerror(errno));
        goto cleanup_exit;
    }

    if (gpiod_line_request_input(rain_line, "rain_sensor") < 0) {
        fprintf(stderr, "Error requesting rain sensor line as input: %s\n", strerror(errno));
        goto cleanup_exit;
    }

    if (gpiod_line_request_output(enable_line, "motor_enable", 0) < 0) {
        fprintf(stderr, "Error requesting motor enable line as output: %s\n", strerror(errno));
        goto cleanup_exit;
    }

    if (gpiod_line_request_output(in1_line, "motor_in1", 0) < 0) {
        fprintf(stderr, "Error requesting motor IN1 line as output: %s\n", strerror(errno));
        goto cleanup_exit;
    }

    if (gpiod_line_request_output(in2_line, "motor_in2", 0) < 0) {
        fprintf(stderr, "Error requesting motor IN2 line as output: %s\n", strerror(errno));
        goto cleanup_exit;
    }

    log_event("Rain sensor monitoring started.");

    while (program_running) {
        int rain_value = gpiod_line_get_value(rain_line);
        if (rain_value < 0) {
            fprintf(stderr, "Error reading rain sensor: %s\n", strerror(errno));
            break;
        }

        if (rain_value == 0) {
            log_event("Rain detected! Closing window.");
            if (set_motor(enable_line, in1_line, in2_line, 1, 1, 0) < 0) {
                log_event("Error setting motor direction. Exiting.");
                break;
            }
            sleep(MOTOR_RUN_TIME_SEC);
            if (set_motor(enable_line, in1_line, in2_line, 0, 0, 0) < 0) {
                log_event("Error stopping motor. Exiting.");
                break;
            }
            log_event("Window closed.");
        } else {
            sleep(POLL_INTERVAL_SEC);
        }
    }

    ret = EXIT_SUCCESS;

cleanup_exit:
    cleanup(enable_line, in1_line, in2_line);
    if (rain_line) gpiod_line_release(rain_line);
    if (chip) gpiod_chip_close(chip);
    log_event("Program terminated.");
    return ret;
}

