#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

#define PWM_RANGE 255
#define SAMPLE_INTERVAL_US 500000  /* 500 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Read the current CPU load as a percentage. */
static float read_cpu_load(void)
{
    static unsigned long long user_prev = 0, nice_prev = 0, system_prev = 0,
                            idle_prev = 0, iowait_prev = 0,
                            irq_prev = 0, softirq_prev = 0, steal_prev = 0,
                            guest_prev = 0, guest_nice_prev = 0;

    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal,
                       guest, guest_nice;

    FILE *fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        perror("fopen(/proc/stat)");
        return -1.0f;
    }

    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal,
               &guest, &guest_nice) != 10) {
        fprintf(stderr, "fscanf(/proc/stat) failed\n");
        fclose(fp);
        return -1.0f;
    }

    fclose(fp);

    unsigned long long prev_idle = idle_prev + iowait_prev;
    unsigned long long curr_idle = idle + iowait;

    unsigned long long prev_non_idle = user_prev + nice_prev + system_prev +
                                       irq_prev + softirq_prev + steal_prev;
    unsigned long long curr_non_idle = user + nice + system + irq + softirq + steal;

    unsigned long long prev_total = prev_idle + prev_non_idle;
    unsigned long long curr_total = curr_idle + curr_non_idle;

    unsigned long long totald = curr_total - prev_total;
    unsigned long long idled = curr_idle - prev_idle;

    if (totald == 0) {
        return 0.0f;
    }

    float load = (float)(totald - idled) / (float)totald;

    user_prev = user;
    nice_prev = nice;
    system_prev = system;
    idle_prev = idle;
    iowait_prev = iowait;
    irq_prev = irq;
    softirq_prev = softirq;
    steal_prev = steal;
    guest_prev = guest;
    guest_nice_prev = guest_nice;

    return load;
}

/* Map CPU load (0-100) to RGB values for a common-anode LED. */
static void map_load_to_color(float load, int *r, int *g, int *b)
{
    if (load < 0.0f) load = 0.0f;
    if (load > 100.0f) load = 100.0f;

    if (load < 50.0f) {
        *r = (int)(load * 2.0f);
        *g = (int)(255.0f - (load * 2.0f));
        *b = 0;
    } else {
        *r = 255;
        *g = 0;
        *b = (int)((load - 50.0f) * 2.0f);
    }
}

/* Set RGB values for the common-anode LED. */
static void set_led_color(int r, int g, int b)
{
    /* Common-anode: 0 = full on, 255 = off */
    gpioPWM(RED_PIN,   PWM_RANGE - r);
    gpioPWM(GREEN_PIN, PWM_RANGE - g);
    gpioPWM(BLUE_PIN,  PWM_RANGE - b);
}

/* Turn the LED off (full brightness for common-anode). */
static void led_off(void)
{
    gpioPWM(RED_PIN,   PWM_RANGE);
    gpioPWM(GREEN_PIN, PWM_RANGE);
    gpioPWM(BLUE_PIN,  PWM_RANGE);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(BLUE_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "gpioSetPWMrange failed\n");
        gpioTerminate();
        return 1;
    }

    led_off();

    while (g_running) {
        float load = read_cpu_load();
        if (load < 0.0f) {
            /* Sensor error: turn LED to a safe (non-red) color. */
            set_led_color(0, 255, 0);
        } else {
            int r, g, b;
            map_load_to_color(load, &r, &g, &b);
            set_led_color(r, g, b);
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    led_off();
    gpioTerminate();
    return 0;
}

