#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>

#define FAN_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_MODE 0
#define BUFFER_SIZE 20
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255

#define TEMP_LOW 25.0
#define TEMP_MED 40.0
#define TEMP_HIGH 60.0

#define FAULT_OC 0x01
#define FAULT_SCV 0x02
#define FAULT_SCG 0x04

typedef struct {
    time_t timestamp;
    float temperature;
    int pwm_duty;
} log_entry_t;

static log_entry_t log_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int spi_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_max31855(int handle, float *temperature) {
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};

    int ret = spiXfer(handle, tx, rx, 4);
    if (ret != 4) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] << 8)  |
                   ((uint32_t)(uint8_t)rx[3]);

    if (raw & 0x00010000) {
        fprintf(stderr, "MAX31855 fault detected (raw=0x%08X)\n", raw);
        if (raw & FAULT_OC) fprintf(stderr, "  Open circuit\n");
        if (raw & FAULT_SCV) fprintf(stderr, "  Short to VCC\n");
        if (raw & FAULT_SCG) fprintf(stderr, "  Short to GND\n");
        return -1;
    }

    int16_t temp_raw = (int16_t)((raw >> 18) & 0x3FFF);
    if (temp_raw & 0x2000) temp_raw |= 0xC000;
    *temperature = temp_raw * 0.25f;
    return 0;
}

static int calculate_pwm_duty(float temperature) {
    if (temperature < TEMP_LOW) return 0;
    if (temperature < TEMP_MED) return (int)((temperature - TEMP_LOW) * 50.0f / (TEMP_MED - TEMP_LOW));
    if (temperature < TEMP_HIGH) return (int)((temperature - TEMP_MED) * 150.0f / (TEMP_HIGH - TEMP_MED));
    return PWM_RANGE;
}

static void add_to_buffer(float temperature, int pwm_duty) {
    log_buffer[buffer_index].timestamp = time(NULL);
    log_buffer[buffer_index].temperature = temperature;
    log_buffer[buffer_index].pwm_duty = pwm_duty;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static void print_buffer(void) {
    printf("\n--- Log Buffer Contents ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (buffer_index + i) % BUFFER_SIZE;
        char ts[32];
        struct tm *tm = localtime(&log_buffer[idx].timestamp);
        if (tm) strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
        else snprintf(ts, sizeof(ts), "unknown");
        printf("[%s] Temp: %.2f C, PWM: %d\n", ts, log_buffer[idx].temperature, log_buffer[idx].pwm_duty);
    }
    printf("---------------------------\n");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", FAN_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO%d\n", FAN_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO%d\n", FAN_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    printf("Fan control started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature;
        if (read_max31855(spi_handle, &temperature) == 0) {
            int pwm_duty = calculate_pwm_duty(temperature);
            if (gpioPWM(FAN_GPIO, pwm_duty) != 0) {
                fprintf(stderr, "Failed to set PWM duty on GPIO%d\n", FAN_GPIO);
            } else {
                add_to_buffer(temperature, pwm_duty);
                printf("Temp: %.2f C, PWM: %d\n", temperature, pwm_duty);
            }
        } else {
            fprintf(stderr, "Skipping fan update due to sensor fault\n");
        }
        sleep(1);
    }

    printf("\nShutting down...\n");
    gpioPWM(FAN_GPIO, 0);
    spiClose(spi_handle);
    print_buffer();
    gpioTerminate();
    return 0;
}

