#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE
#define BMP180_OSS 3
#define BMP180_TEMP_CMD 0x2E
#define BMP180_PRESSURE_CMD 0x34

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_word(int handle, uint8_t reg, int16_t *out) {
    int hi = i2cReadByteData(handle, reg);
    if (hi < 0) return -1;
    int lo = i2cReadByteData(handle, reg + 1);
    if (lo < 0) return -1;
    *out = (int16_t)((hi << 8) | lo);
    return 0;
}

static int read_ushort(int handle, uint8_t reg, uint16_t *out) {
    int hi = i2cReadByteData(handle, reg);
    if (hi < 0) return -1;
    int lo = i2cReadByteData(handle, reg + 1);
    if (lo < 0) return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int read_calibration_data(int handle) {
    if (read_word(handle, BMP180_REG_CAL_AC1, &ac1) < 0) return -1;
    if (read_word(handle, BMP180_REG_CAL_AC2, &ac2) < 0) return -1;
    if (read_word(handle, BMP180_REG_CAL_AC3, &ac3) < 0) return -1;
    if (read_ushort(handle, BMP180_REG_CAL_AC4, &ac4) < 0) return -1;
    if (read_ushort(handle, BMP180_REG_CAL_AC5, &ac5) < 0) return -1;
    if (read_ushort(handle, BMP180_REG_CAL_AC6, &ac6) < 0) return -1;
    if (read_word(handle, BMP180_REG_CAL_B1, &b1) < 0) return -1;
    if (read_word(handle, BMP180_REG_CAL_B2, &b2) < 0) return -1;
    if (read_word(handle, BMP180_REG_CAL_MB, &mb) < 0) return -1;
    if (read_word(handle, BMP180_REG_CAL_MC, &mc) < 0) return -1;
    if (read_word(handle, BMP180_REG_CAL_MD, &md) < 0) return -1;
    return 0;
}

static int read_raw_temperature(int handle, int32_t *ut) {
    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, BMP180_TEMP_CMD) < 0) return -1;
    gpioDelay(5000);
    int32_t raw = i2cReadWordData(handle, BMP180_REG_MSB);
    if (raw < 0) return -1;
    *ut = (int32_t)raw;
    return 0;
}

static int read_raw_pressure(int handle, int32_t *up) {
    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, BMP180_PRESSURE_CMD + (BMP180_OSS << 6)) < 0) return -1;
    gpioDelay(2000 + (3000 << BMP180_OSS));
    int msb = i2cReadByteData(handle, BMP180_REG_MSB);
    if (msb < 0) return -1;
    int lsb = i2cReadByteData(handle, BMP180_REG_LSB);
    if (lsb < 0) return -1;
    int xlsb = i2cReadByteData(handle, BMP180_REG_XLSB);
    if (xlsb < 0) return -1;
    *up = ((msb << 16) | (lsb << 8) | xlsb) >> (8 - BMP180_OSS);
    return 0;
}

static int32_t compute_b5(int32_t ut) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    return x1 + x2;
}

static int32_t calculate_temperature(int32_t ut) {
    int32_t b5 = compute_b5(ut);
    return (b5 + 8) >> 4;
}

static int32_t calculate_pressure(int32_t up, int32_t ut) {
    int32_t b5 = compute_b5(ut);
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << BMP180_OSS) + 2) >> 2;
    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> BMP180_OSS);
    int32_t p;
    if (b7 < 0x80000000) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return p;
}

static void log_data(FILE *fp, int32_t temp, int32_t press) {
    time_t rawtime;
    struct tm *timeinfo;
    char ts[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(fp, "%s,%d,%d\n", ts, temp, press);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed\n");
        gpioTerminate();
        return 1;
    }
    if (read_calibration_data(i2c_handle) < 0) {
        fprintf(stderr, "Calibration read failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    log_file = fopen("altitude_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "File open failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(2, PI_INPUT);
    gpioSetPullUpDown(2, PI_PUD_UP);
    gpioSetAlertFunc(2, (gpioAlertFunc_t)log_data_toggle);
    signal(SIGINT, signal_handler);
    int logging = 0;
    while (running) {
        if (logging) {
            int32_t ut, up;
            if (read_raw_temperature(i2c_handle, &ut) == 0 && read_raw_pressure(i2c_handle, &up) == 0) {
                int32_t t = calculate_temperature(ut);
                int32_t p = calculate_pressure(up, ut);
                log_data(log_file, t, p);
            } else {
                fprintf(stderr, "Sensor read error\n");
            }
        }
        gpioDelay(1000000);
    }
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

static void log_data_toggle(int gpio, int level, uint32_t tick) {
    (void)gpio; (void)tick;
    if (level == 0) {
        logging = !logging;
        printf("Logging %s\n", logging ? "ON" : "OFF");
    }
}

