#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define LOG_FILE "rtd_log.csv"
#define GPIO_CHIP "gpiochip4"
#define CS_PIN 8
#define SPI_SPEED_HZ 1000000
#define SAMPLE_INTERVAL_SEC 5

#define MAX31865_CONFIG_REG 0x00
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_FAULT_REG 0x03

#define MAX31865_CONFIG_3WIRE_RTD 0x00
#define MAX31865_CONFIG_BIAS_EN 0x80
#define MAX31865_CONFIG_DEFAULT (MAX31865_CONFIG_3WIRE_RTD | MAX31865_CONFIG_BIAS_EN)

#define MAX31865_RTD_RESOLUTION 0.25
#define MAX31865_RTD_NOMINAL 100.0
#define MAX31865_RTD_A 0.0039083
#define MAX31865_RTD_B -0.0000005775
#define MAX31865_RTD_C 0.000000000004827

static volatile sig_atomic_t program_running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        return -1;
    }
    return 0;
}

static int max31865_write_reg(uint8_t reg, uint8_t value) {
    uint8_t tx[2] = {reg & 0x7F, value};
    uint8_t rx[2] = {0};
    return spi_transfer(tx, rx, 2);
}

static int max31865_read_reg(uint8_t reg, uint8_t *value) {
    uint8_t tx[2] = {reg | 0x80, 0x00};
    uint8_t rx[2] = {0};
    if (spi_transfer(tx, rx, 2) < 0) {
        return -1;
    }
    *value = rx[1];
    return 0;
}

static int max31865_init(void) {
    if (max31865_write_reg(MAX31865_CONFIG_REG, MAX31865_CONFIG_DEFAULT) < 0) {
        fprintf(stderr, "Error writing config register: %s\n", strerror(errno));
        return -1;
    }
    usleep(10000);
    return 0;
}

static int read_rtd_raw(uint16_t *rtd_raw) {
    uint8_t msb = 0, lsb = 0;
    if (max31865_read_reg(MAX31865_RTD_MSB_REG, &msb) < 0) {
        return -1;
    }
    if (max31865_read_reg(MAX31865_RTD_LSB_REG, &lsb) < 0) {
        return -1;
    }
    *rtd_raw = ((uint16_t)msb << 8) | lsb;
    return 0;
}

static int read_fault_status(uint8_t *fault) {
    return max31865_read_reg(MAX31865_FAULT_REG, fault);
}

static float calculate_temperature(uint16_t rtd_raw) {
    float rtd_resistance = (float)rtd_raw * MAX31865_RTD_RESOLUTION;
    if (rtd_resistance <= 0.0f) {
        return -1000.0f;
    }
    float z = 1.0f / rtd_resistance;
    float a = MAX31865_RTD_A;
    float b = MAX31865_RTD_B;
    float c = MAX31865_RTD_C;
    float t = (a + b * z + c * z * z) / (1.0f + b * z + c * z * z);
    return t;
}

static void log_data(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file);
}

static void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,ERROR,%s\n", timestamp, message);
    fflush(log_file);
}

static void cleanup(void) {
    if (cs_line) {
        gpiod_line_set_value(cs_line, 1);
        gpiod_line_release(cs_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
