#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR 0x77
#define I2C_BUS 1
#define LOG_FILE "bmp180_log.txt"
#define SAMPLE_INTERVAL_US 500000

#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA

#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE0 0x34

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

typedef struct {
    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

static bmp180_cal_t cal;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int handle, uint8_t reg, uint8_t *val) {
    if (i2cWriteByte(handle, reg) < 0) return -1;
    int b = i2cReadByte(handle);
    if (b < 0) return -1;
    *val = (uint8_t)b;
    return 0;
}

static int i2c_read_reg16(int handle, uint8_t reg, int16_t *val) {
    uint8_t msb, lsb;
    if (i2c_read_reg8(handle, reg, &msb) < 0) return -1;
    if (i2c_read_reg8(handle, reg + 1, &lsb) < 0) return -1;
    *val = (int16_t)((msb << 8) | lsb);
    return 0;
}

static int i2c_read_reg16u(int handle, uint8_t reg, uint16_t *val) {
    uint8_t msb, lsb;
    if (i2c_read_reg8(handle, reg, &msb) < 0) return -1;
    if (i2c_read_reg8(handle, reg + 1, &lsb) < 0) return -1;
    *val = (uint16_t)((msb << 8) | lsb);
    return 0;
}

static int read_calibration(int handle, bmp180_cal_t *c) {
    if (i2c_read_reg16(handle, 0xAA, &c->ac1) < 0) return -1;
    if (i2c_read_reg16(handle, 0xAC, &c->ac2) < 0) return -1;
    if (i2c_read_reg16(handle, 0xAE, &c->ac3) < 0) return -1;
    if (i2c_read_reg16u(handle, 0xB0, &c->ac4) < 0) return -1;
    if (i2c_read_reg16u(handle, 0xB2, &c->ac5) < 0) return -1;
    if (i2c_read_reg16u(handle, 0xB4, &c->ac6) < 0) return -1;
    if (i2c_read_reg16(handle, 0xB6, &c->b1) < 0) return -1;
    if (i2c_read_reg16(handle, 0xB8, &c->b2) < 0) return -1;
    if (i2c_read_reg16(handle, 0xBA, &c->mb) < 0) return -1;
    if (i2c_read_reg16(handle, 0xBC, &c->mc) < 0) return -1;
    if (i2c_read_reg16(handle, 0xBE, &c->md) < 0) return -1;
    return 0;
}

static int read_raw_temp(int handle, int32_t *ut) {
    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP) < 0) return -1;
