#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "fan_log.txt"
#define PWM_FREQ 25000
#define PWM_RANGE 255
#define MIN_TEMP 40.0f
#define MAX_TEMP 70.0f
#define SLEEP_SEC 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_cpu_temp(float *temp_out) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        perror("fopen temperature");
        return -1;
    }
    int temp_raw;
    if (fscanf(fp, "%d", &temp_raw) != 1) {
        fprintf(stderr, "Failed to parse temperature\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    *temp_out = (float)temp_raw / 1000.0f;
    return 0;
}

static int set_fan_speed(int duty) {
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    if (gpioPWM(FAN_GPIO, duty) != 0) {
        fprintf(stderr, "gpioPWM failed for duty %d\n", duty);
        return -1;
    }
    return 0;
}

static int log_data(float temp, int duty) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return -1;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,%.2f,%d\n", ts, temp, duty) < 0) {
        fprintf(stderr, "fprintf log failed\n");
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        perror("fclose log");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency failed\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "gpioSetPWMrange failed\n");
        gpioTerminate();
        return 1;
    }

    if (set_fan_speed(0) != 0) {
        gpioTerminate();
        return 1;
    }

    while (running) {
        float temp;
        if (read_cpu_temp(&temp) != 0) {
            fprintf(stderr, "Temperature read failed; keeping last duty\n");
        } else {
            int duty;
            if (temp < MIN_TEMP) {
                duty = 0;
            } else if (temp > MAX_TEMP) {
                duty = PWM_RANGE;
            } else {
                duty = (int)(((temp - MIN_TEMP) / (MAX_TEMP - MIN_TEMP)) * PWM_RANGE);
            }
            if (set_fan_speed(duty) != 0) {
                fprintf(stderr, "Failed to set fan speed\n");
            }
        }

        if (log_data(temp, duty) != 0) {
            fprintf(stderr, "Logging failed\n");
        }

        sleep(SLEEP_SEC);
    }

    set_fan_speed(0);
    gpioTerminate();
    return 0;
}

