#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BMP280_ADDR_1 0x76
#define BMP280_ADDR_2 0x77
#define BMP280_CHIP_ID_REG 0xD0
#define BMP280_CHIP_ID 0x58
#define BMP280_RESET_REG 0xE0
#define BMP280_RESET_CMD 0xB6
#define BMP280_STATUS_REG 0xF3
#define BMP280_CTRL_MEAS_REG 0xF4
#define BMP280_CONFIG_REG 0xF5
#define BMP280_PRESS_MSB_REG 0xF7
#define BMP280_CALIB_START 0x88
#define BMP280_CALIB_LEN 24

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_t;

static int i2c_write(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int bmp280_init(int fd, bmp280_calib_t *cal) {
    uint8_t id;
    if (i2c_read(fd, BMP280_CHIP_ID_REG, &id, 1) < 0) return -1;
    if (id != BMP280_CHIP_ID) {
        fprintf(stderr, "Chip ID mismatch: got 0x%02X, expected 0x%02X\n", id, BMP280_CHIP_ID);
        return -1;
    }
    uint8_t calib[BMP280_CALIB_LEN];
    if (i2c_read(fd, BMP280_CALIB_START, calib, BMP280_CALIB_LEN) < 0) return -1;
    cal->dig_T1 = (uint16_t)(calib[0] | (calib[1] << 8));
    cal->dig_T2 = (int16_t)(calib[2] | (calib[3] << 8));
    cal->dig_T3 = (int16_t)(calib[4] | (calib[5] << 8));
    cal->dig_P1 = (uint16_t)(calib[6] | (calib[7] << 8));
    cal->dig_P2 = (int16_t)(calib[8] | (calib[9] << 8));
    cal->dig_P3 = (int16_t)(calib[10] | (calib[11] << 8));
