#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <pthread.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS        "/dev/i2c-1"
#define LM75_ADDR      0x48
#define LM75_TEMP_REG  0x00
#define GPIO_CHIP      "gpiochip4"
#define GPIO_OFFSET    18
#define BUFFER_SIZE    60
#define TEMP_THRESHOLD 28.0f
#define POLL_DELAY_US  1000000

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, LM75_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", LM75_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }
    led_line = gpiod_chip_get_line(chip, GPIO_OFFSET);
    if (!led_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    if (gpiod_line_request_output(led_line, "lm75_monitor", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        led_line = NULL;
        return -1;
    }
    return 0;
}

static float read_temperature(void) {
    uint8_t reg = LM75_TEMP_REG;
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing temperature register address: %s\n", strerror(errno));
        return -999.0f;
    }
    uint8_t buf[2];
    if (read(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading temperature data: %s\n", strerror(errno));
        return -999.0f;
    }
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    raw >>= 5;
    return (float)raw / 256.0f;
}

static void add_to_buffer(CircularBuffer *cb, float temp) {
    pthread_mutex_lock(&buffer_mutex);
    cb->buffer[cb->head] = temp;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
    pthread_mutex_unlock(&buffer_mutex);
}

static float calculate_average(const CircularBuffer *cb) {
    float sum = 0.0f;
    int count = 0;
    pthread_mutex_lock(&buffer_mutex);
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
        count++;
    }
    pthread_mutex_unlock(&buffer_mutex);
    return (count > 0) ? (sum / count) : 0.0f;
}

static void control_led(float temp) {
    int val = (temp > TEMP_THRESHOLD) ? 1 : 0;
    if (gpiod_line_set_value(led_line, val) < 0) {
        fprintf(stderr, "Error setting LED value: %s\n", strerror(errno));
    }
}

static void *data_acquisition_thread(void *arg) {
    (void)arg;
    while (running) {
        if (init_i2c() < 0) {
            fprintf(stderr, "I2C re-init failed, retrying in 1s...\n");
            sleep(1);
            continue;
        }
        float temp = read_temperature();
        if (temp <= -999.0f) {
            fprintf(stderr, "Temperature read failed, retrying in 1s...\n");
            sleep(1);
            continue;
        }
        add_to_buffer(&circular_buffer, temp);
        control_led(temp);
        printf("Temperature: %.2f°C\n", temp);
        usleep(POLL_DELAY_US);
    }
    return NULL;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO init failed, exiting.\n");
        return 1;
    }

    memset(&circular_buffer, 0, sizeof(circular_buffer));

    pthread_t thread;
    if (pthread_create(&thread, NULL, data_acquisition_thread, NULL) != 0) {
        fprintf(stderr, "Error creating data acquisition thread: %s\n", strerror(errno));
        if (led_line) gpiod_line_release(led_line);
        if (chip) gpiod_chip_close(chip);
        return 1;
    }

    while (running) {
        sleep(1);
    }

    pthread_join(thread, NULL);
    pthread_mutex_destroy(&buffer_mutex);

    if (led_line) gpiod_line_release(led_line);
    if (chip) gpiod_chip_close(chip);
    if (i2c_fd >= 0) close(i2c_fd);

    printf("Program terminated gracefully.\n");
    return 0;
}

CircularBuffer circular_buffer;

