        fprintf(stderr, "Error reading temperature data: %s\n", strerror(errno));
        return -999.0f;
    }
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    raw >>= 5;
    return (float)raw / 256.0f;
}

static void add_to_buffer(CircularBuffer *cb, float temp) {
    pthread_mutex_lock(&buffer_mutex);
    cb->buffer[cb->head] = temp;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
    pthread_mutex_unlock(&buffer_mutex);
}

static float calculate_average(const CircularBuffer *cb) {
    float sum = 0.0f;
    int count = 0;
    pthread_mutex_lock(&buffer_mutex);
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
        count++;
    }
    pthread_mutex_unlock(&buffer_mutex);
    return (count > 0) ? (sum / count) : 0.0f;
}

static void control_led(float temp) {
    int val = (temp > TEMP_THRESHOLD) ? 1 : 0;
    if (gpiod_line_set_value(led_line, val) < 0) {
        fprintf(stderr, "Error setting LED value: %s\n", strerror(errno));
    }
}

static void *data_acquisition_thread(void *arg) {
    (void)arg;
    while (running) {
        if (init_i2c() < 0) {
            fprintf(stderr, "I2C re-init failed, retrying in 1s...\n");
            sleep(1);
            continue;
        }
        float temp = read_temperature();
        if (temp <= -999.0f) {
            fprintf(stderr, "Temperature read failed, retrying in 1s...\n");
            sleep(1);
            continue;
        }
        add_to_buffer(&circular_buffer, temp);
        control_led(temp);
        printf("Temperature: %.2f°C\n", temp);
        usleep(POLL_DELAY_US);
    }
    return NULL;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO init failed, exiting.\n");
        return 1;
    }

    memset(&circular_buffer, 0, sizeof(circular_buffer));

    pthread_t thread;
    if (pthread_create(&thread, NULL, data_acquisition_thread, NULL) != 0) {
        fprintf(stderr, "Error creating data acquisition thread: %s\n", strerror(errno));
        if (led_line) gpiod_line_release(led_line);
        if (chip) gpiod_chip_close(chip);
        return 1;
    }

    while (running) {
        sleep(1);
    }

    pthread_join(thread, NULL);
    pthread_mutex_destroy(&buffer_mutex);

    if (led_line) gpiod_line_release(led_line);
    if (chip) gpiod_chip_close(chip);
    if (i2c_fd >= 0) close(i2c_fd);

    printf("Program terminated gracefully.\n");
    return 0;
}

