#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_FLAGS 0x00000001  /* pigpio SPI mode 1: CE0 active low */
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000
#define SAMPLE_INTERVAL_US 100000
#define MAX31865_CONFIG_REG 0x80
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_FAULT_REG 0x07
#define R_REF 430.0
#define R0 100.0
#define A 0.0039083
#define B -0.0000005775
#define TARGET_TEMP_DEFAULT 25.0
#define KP_DEFAULT 1.0
#define KI_DEFAULT 0.1
#define KD_DEFAULT 0.01
#define MAX_TEMP 80.0
#define CONFIG_FILE "heater_config.json"

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static double target_temperature = TARGET_TEMP_DEFAULT;
static double kp = KP_DEFAULT;
static double ki = KI_DEFAULT;
static double kd = KD_DEFAULT;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int load_config(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open %s; using defaults\n", filename);
        return 0;
    }
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *p = line;
        while (*p == ' ' || *p == '\t') p++;
        if (*p == '\0' || *p == '#') continue;
        char *eq = strchr(p, '=');
        if (!eq) continue;
        *eq = '\0';
        char *key = p;
        char *val = eq + 1;
        while (*key == ' ' || *key == '\t') key++;
        char *ke = key + strlen(key) - 1;
        while (ke > key && *ke == ' ' && *ke == '\t') { *ke = '\0'; ke--; }
        while (*val == ' ' || *val == '\t') val++;
        char *ve = val + strlen(val) - 1;
        while (ve > val && (*ve == ' ' || *ve == '\t')) { *ve = '\0'; ve--; }
        if (strcmp(key, "target_temperature") == 0) {
            target_temperature = atof(val);
        } else if (strcmp(key, "kp") == 0) {
            kp = atof(val);
        } else if (strcmp(key, "ki") == 0) {
            ki = atof(val);
        } else if (strcmp(key, "kd") == 0) {
            kd = atof(val);
        }
    }
    fclose(fp);
    printf("Config loaded: target=%.2f Kp=%.3f Ki=%.3f Kd=%.3f\n",
           target_temperature, kp, ki, kd);
    return 0;
}

static int init_max31865(void) {
    unsigned char tx[2] = { (MAX31865_CONFIG_REG >> 1) & 0xFF, 0xC1 };
    unsigned char rx[2];
    if (spiXfer(spi_handle, tx, rx, 2) < 0) {
        fprintf(stderr, "SPI write to config failed\n");
        return -1;
    }
    gpioDelay(10000);
    return 0;
}

static int read_rtd(double *temp_out) {
    unsigned char tx[4] = { (MAX31865_RTD_MSB_REG >> 1) & 0xFF, 0x00, 0x00, 0x00 };
    unsigned char rx[4];
    if (spiXfer(spi_handle, tx, rx, 4) < 0) {
        fprintf(stderr, "SPI read of RTD failed\n");
        return -1;
    }
    unsigned int rtd_code = ((rx[0] << 8) | rx[1]) & 0x7FFF;
    if (rtd_code == 0) {
        fprintf(stderr, "RTD code is zero (sensor absent or open)\n");
        return -1;
    }
    if (rx[0] & 0x01) {
        unsigned char fault_tx[2] = { (MAX31865_FAULT_REG >> 1) & 0xFF, 0x00 };
        unsigned char fault_rx[2];
        if (spiXfer(spi_handle, fault_tx, fault_rx, 2) < 0) {
            fprintf(stderr, "SPI read of fault status failed\n");
            return -1;
        }
        unsigned int fault = fault_rx[0];
        if (fault & 0x01) fprintf(stderr, "MAX31865 fault: open circuit\n");
        if (fault & 0x02) fprintf(stderr, "MAX31865 fault: overvoltage\n");
        if (fault & 0x04) fprintf(stderr, "MAX31865 fault: undervoltage\n");
        return -1;
    }
    double r_rtd = (rtd_code / 32768.0) * R_REF;
    double t = (-A + sqrt(A * A - 4 * B * (1.0 - r_rtd / R0))) / (2.0 * B);
    if (t < 0.0) t = (-A - sqrt(A * A - 4 * B * (1.0 - r_rtd / R0))) / (2.0 * B);
    *temp_out = t;
    return 0;
}

static double pid_control(double current_temp) {
    static double integral = 0.0;
    double error = target_temperature - current_temp;
    double derivative = error - integral;
    double output = kp * error + ki * integral + kd * derivative;
    integral += error;
    if (output < 0.0) output = 0.0;
    if (output > 100.0) output = 100.0;
    return output;
}

static void set_heater_pwm(double duty) {
    int pwm = (int)(duty * 10.0);
    if (pwm < 0) pwm = 0;
    if (pwm > PWM_RANGE) pwm = PWM_RANGE;
    gpioPWM(HEATER_GPIO, pwm);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }
    if (init_max31865() < 0) {
        fprintf(stderr, "MAX31865 init failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);
    set_heater_pwm(0.0);
    load_config(CONFIG_FILE);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    printf("Starting PID control loop...\n");
    while (running) {
        double temp;
        if (read_rtd(&temp) < 0) {
            fprintf(stderr, "Temperature read failed — heater OFF, exiting\n");
            set_heater_pwm(0.0);
            break;
        }
        double duty = pid_control(temp);
        set_heater_pwm(duty);
        printf("Temp=%.2f°C  Duty=%.1f%%\n", temp, duty);
        if (temp > MAX_TEMP || duty == 0.0) {
            fprintf(stderr, "Failsafe: temp=%.2f > %.1f or duty=0 — heater OFF, exiting\n",
                    temp, MAX_TEMP);
            break;
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    set_heater_pwm(0.0);
    spiClose(spi_handle);
    gpioTerminate();
    printf("Shutdown complete.\n");
    return 0;
}

