#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HEATER_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000
#define PWM_RANGE 1000
#define MAX_DUTY_CYCLE 800
#define TARGET_TEMP 25.0
#define SAMPLE_INTERVAL_US 100000
#define LOG_FILE "heater_log.csv"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_max31855(int handle, float *temp) {
    char buf[4] = {0};
    int ret = spiRead(handle, buf, 4);
    if (ret != 4) {
        fprintf(stderr, "SPI read failed (ret=%d)\n", ret);
        return -1;
    }
    uint32_t raw = ((uint32_t)(uint8_t)buf[0] << 24) |
                   ((uint32_t)(uint8_t)buf[1] << 16) |
                   ((uint32_t)(uint8_t)buf[2] << 8)  |
                   ((uint32_t)(uint8_t)buf[3]);
    if (raw & 0x00010000) {
        fprintf(stderr, "MAX31855 fault: ");
        if (raw & 0x00000004) fprintf(stderr, "open circuit\n");
        if (raw & 0x00000002) fprintf(stderr, "short to GND\n");
        if (raw & 0x00000001) fprintf(stderr, "short to VCC\n");
        return -1;
    }
    int16_t thermocouple = (int16_t)(raw >> 18);
    *temp = thermocouple * 0.25;
    return 0;
}

static int set_heater_pwm(int duty) {
    if (duty < 0) duty = 0;
    if (duty > MAX_DUTY_CYCLE) duty = MAX_DUTY_CYCLE;
    int pwm = (duty * PWM_RANGE) / MAX_DUTY_CYCLE;
    if (gpioPWM(HEATER_GPIO, pwm) != 0) {
        fprintf(stderr, "gpioPWM failed\n");
        return -1;
    }
    return 0;
}

static void log_data(float temp, int duty) {
    time_t now = time(NULL);
    struct tm tm_info;
    localtime_r(&now, &tm_info);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);
    fprintf(log_file, "%s,%.2f,%d\n", ts, temp, duty);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    if (gpioSetMode(HEATER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", HEATER_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMrange(HEATER_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return 1;
    }
    if (gpioPWM(HEATER_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialize PWM to 0\n");
        gpioTerminate();
        return 1;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Temperature(DegC),DutyCycle(%%)\n");
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    float integral = 0.0f;
    int last_duty = 0;
    while (running) {
        float temp;
        if (read_max31855(spi_handle, &temp) != 0) {
            fprintf(stderr, "Sensor read error — heater off\n");
            set_heater_pwm(0);
            log_data(-999.0f, 0);
            integral = 0.0f;
            last_duty = 0;
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }
        float error = TARGET_TEMP - temp;
        float Kp = 1.0f, Ki = 0.1f;
        float new_integral = integral + error;
        float output = Kp * error + Ki * new_integral;
        if (output < 0.0f) output = 0.0f;
        if (output > MAX_DUTY_CYCLE) output = MAX_DUTY_CYCLE;
        int duty = (int)(output + 0.5f);
        if (duty != last_duty) {
            if (set_heater_pwm(duty) == 0) {
                last_duty = duty;
            }
        }
        log_data(temp, duty);
        integral = new_integral;
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    set_heater_pwm(0);
    if (log_file) fclose(log_file);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

