        if (output < 0.0f) output = 0.0f;
        if (output > MAX_DUTY_CYCLE) output = MAX_DUTY_CYCLE;
        int duty = (int)(output + 0.5f);
        if (duty != last_duty) {
            if (set_heater_pwm(duty) == 0) {
                last_duty = duty;
            }
        }
        log_data(temp, duty);
        integral = new_integral;
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    set_heater_pwm(0);
    if (log_file) fclose(log_file);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

