#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define POLL_INTERVAL_US 500000  /* 0.5 seconds */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_rgb(int r, int g, int b)
{
    if (gpioPWM(RED_PIN,   255 - r) < 0) return -1;
    if (gpioPWM(GREEN_PIN, 255 - g) < 0) return -1;
    if (gpioPWM(BLUE_PIN,  255 - b) < 0) return -1;
    return 0;
}

static int read_cpu_temp(void)
{
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        perror("fopen(" TEMP_FILE ")");
        return -1;
    }

    int temp = -1;
    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "fscanf: failed to parse temperature from %s\n", TEMP_FILE);
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose(" TEMP_FILE ")");
        return -1;
    }

    return temp;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN,   PI_OUTPUT) < 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(BLUE_PIN,  PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN,   255) < 0 ||
        gpioSetPWMrange(GREEN_PIN, 255) < 0 ||
        gpioSetPWMrange(BLUE_PIN,  255) < 0) {
        fprintf(stderr, "gpioSetPWMrange failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int temp = read_cpu_temp();
        if (temp < 0) {
            /* Error already reported; skip this cycle. */
            usleep(POLL_INTERVAL_US);
            continue;
        }

        if (temp < 40000) {
            if (set_rgb(0, 0, 255) < 0) {
                fprintf(stderr, "gpioPWM failed\n");
                break;
            }
            printf("Temp: %d m°C -> Blue\n", temp);
        } else if (temp < 60000) {
            if (set_rgb(0, 255, 0) < 0) {
                fprintf(stderr, "gpioPWM failed\n");
                break;
            }
            printf("Temp: %d m°C -> Green\n", temp);
        } else {
            if (set_rgb(255, 0, 0) < 0) {
                fprintf(stderr, "gpioPWM failed\n");
                break;
            }
            printf("Temp: %d m°C -> Red\n", temp);
        }

        fflush(stdout);
        usleep(POLL_INTERVAL_US);
    }

    /* Clean shutdown: turn LED off (common anode: duty 255 = off) */
    gpioPWM(RED_PIN,   255);
    gpioPWM(GREEN_PIN, 255);
    gpioPWM(BLUE_PIN,  255);
    gpioTerminate();
    return EXIT_SUCCESS;
}

