#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define SERVER_URL "http://yourserver.com/api/humidity"

static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

typedef struct {
    float temperature;
    float humidity;
} DHT22Data;

int read_dht22(DHT22Data *data) {
    int i, j;
    int data_bits[40];
    int last_state = PI_HIGH;
    int counter = 0;
    int bits_read = 0;

    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, PI_LOW);
    gpioDelay(2000);
    gpioWrite(DHT22_GPIO, PI_HIGH);
    gpioDelay(30);
    gpioSetMode(DHT22_GPIO, PI_INPUT);

    for (i = 0; i < 85; i++) {
        counter = 0;
        while (gpioRead(DHT22_GPIO) == last_state) {
            counter++;
            gpioDelay(1);
            if (counter == 255) break;
        }
        last_state = gpioRead(DHT22_GPIO);

        if (counter == 255) break;

        if ((i >= 4) && (i % 2 == 0)) {
            data_bits[i / 2] = counter;
        }
    }

    if (i < 83) {
        fprintf(stderr, "DHT22 read failed: sensor not responding\n");
        return -1;
    }

    int humidity_raw = 0;
    int temperature_raw = 0;
    int checksum = 0;

    for (j = 0; j < 16; j++) {
        humidity_raw = (humidity_raw << 1) | (data_bits[j] > 50 ? 1 : 0);
    }
    for (j = 16; j < 32; j++) {
        temperature_raw = (temperature_raw << 1) | (data_bits[j] > 50 ? 1 : 0);
    }
    for (j = 32; j < 40; j++) {
        checksum = (checksum << 1) | (data_bits[j] > 50 ? 1 : 0);
    }

    int calculated_checksum = (humidity_raw + temperature_raw) & 0xFF;

    if (checksum != calculated_checksum) {
        fprintf(stderr, "DHT22 checksum error: %d != %d\n", checksum, calculated_checksum);
        return -2;
    }

    data->humidity = (float)humidity_raw / 10.0;
    data->temperature = (float)(temperature_raw & 0x7FFF) / 10.0;
    if (temperature_raw & 0x8000) {
        data->temperature = -data->temperature;
    }

    return 0;
}

char* format_json(DHT22Data data) {
    char *json_string = malloc(128);
    if (json_string == NULL) {
        perror("Failed to allocate memory for JSON string");
        return NULL;
    }
    snprintf(json_string, 128, "{\"temperature\": %.1f, \"humidity\": %.1f}", data.temperature, data.humidity);
    return json_string;
}

int send_data(const char *json_string) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;
    long http_code = 0;

    curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Failed to initialize libcurl\n");
        return -1;
    }

    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        fprintf(stderr, "Failed to set HTTP headers\n");
        curl_easy_cleanup(curl);
        return -1;
    }

    curl_easy_setopt(curl, CURLOPT_URL, SERVER_URL);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_string);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);

    res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
        return -1;
    }

    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
    if (http_code != 200) {
        fprintf(stderr, "HTTP request failed with code: %ld\n", http_code);
        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
        return -1;
    }

    curl_easy_cleanup(curl);
    curl_slist_free_all(headers);
    return 0;
}

int main() {
    DHT22Data data;
    char *json_string;
    int retries;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (curl_global_init(CURL_GLOBAL_ALL) != CURLE_OK) {
        fprintf(stderr, "libcurl global initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    while (running) {
        retries = 0;
        while (retries < MAX_RETRIES && running) {
            if (read_dht22(&data) == 0) {
                json_string = format_json(data);
                if (json_string != NULL) {
                    if (send_data(json_string) != 0) {
                        fprintf(stderr, "Failed to send data after %d retries\n", MAX_RETRIES);
                    } else {
                        printf("Data sent successfully\n");
                    }
                    free(json_string);
                }
                break;
            } else {
                fprintf(stderr, "DHT22 read failed, retrying (%d/%d)...\n", retries + 1, MAX_RETRIES);
                retries++;
                gpioDelay(2000000);
            }
        }

        if (retries == MAX_RETRIES && running) {
            fprintf(stderr, "DHT22 read failed after %d retries, skipping cycle\n", MAX_RETRIES);
        }

        if (running) {
            gpioDelay(5000000);
        }
    }

    gpioTerminate();
    curl_global_cleanup();
    return 0;
}

