#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define BMP180_ADDR 0x77
#define BUTTON_GPIO 4
#define LOG_FILE "pressure_log.txt"
#define DEBOUNCE_US 200000
#define SAMPLE_INTERVAL_S 2

#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE_OSS3 0xF4

static volatile sig_atomic_t logging_enabled = 0;
static volatile uint32_t last_interrupt_tick = 0;
static volatile int button_state = 0;
static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

typedef struct {
    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

static bmp180_cal_t cal;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int handle, uint8_t reg, uint8_t *val) {
    if (i2cWriteByte(handle, reg) < 0) return -1;
    int b = i2cReadByte(handle);
    if (b < 0) return -1;
    *val = (uint8_t)b;
    return 0;
}

static int i2c_read_reg16(int handle, uint8_t reg, int16_t *val) {
    uint8_t buf[2];
    if (i2cWriteByte(handle, reg) < 0) return -1;
    if (i2cReadDevice(handle, (char *)buf, 2) != 2) return -1;
    *val = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int i2c_read_reg16u(int handle, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (i2cWriteByte(handle, reg) < 0) return -1;
    if (i2cReadDevice(handle, (char *)buf, 2) != 2) return -1;
    *val = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_calibration(int handle) {
    if (i2c_read_reg16(handle, BMP180_REG_CAL_AC1, &cal.ac1) < 0) return -1;
    if (i2c_read_reg16(handle, BMP180_REG_CAL_AC2, &cal.ac2) < 0) return -1;
    if (i2c_read_reg16(handle, BMP180_REG_CAL_AC3, &cal.ac3) < 0) return -1;
    if (i2c_read_reg16u(handle, BMP180_REG_CAL_AC4, &cal.ac4) < 0) return -1;
    if (i2c_read_reg16u(handle, BMP180_REG_CAL_AC5, &cal.ac5) < 0) return -1;
    if (i2c_read_reg16u(handle, BMP180_REG_CAL_AC6, &cal.ac6) < 0) return -1;
    if (i2c_read_reg16(handle, BMP180_REG_CAL_B1, &cal.b1) < 0) return -1;
    if (i2c_read_reg16(handle, BMP180_REG_CAL_B2, &cal.b2) < 0) return -1;
    if (i2c_read_reg16(handle, BMP180_REG_CAL_MB, &cal.mb) < 0) return -1;
    if (i2c_read_reg16(handle, BMP180_REG_CAL_MC, &cal.mc) < 0) return -1;
    if (i2c_read_reg16(handle, BMP180_REG_CAL_MD, &cal.md) < 0) return -1;
    return 0;
}

static int read_raw_temp(int handle, int32_t *ut) {
    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP) < 0) return -1;
    gpioDelay(5000);
    int16_t raw;
