#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_PIN 4
#define MAX_RETRIES 3
#define READ_INTERVAL 10
#define DHT22_TIMEOUT_US 100000
#define DHT22_START_LOW_US 1000
#define DHT22_START_HIGH_US 30
#define DHT22_BIT_THRESHOLD_US 50

static volatile sig_atomic_t terminate = 0;
static char *server_url = "http://your-server.com/api/humidity";

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int wait_for_level(int pin, int level, uint32_t timeout_us) {
    uint32_t start = gpioTick();
    while (gpioRead(pin) != level) {
        if (terminate) return -1;
        if ((gpioTick() - start) > timeout_us) return -1;
    }
    return 0;
}

static int read_dht22(float *humidity) {
    uint8_t data[5] = {0};
    int i;
    uint32_t start_tick, edge_tick;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        memset(data, 0, sizeof(data));

        if (gpioSetMode(DHT22_PIN, PI_OUTPUT) < 0) {
            syslog(LOG_ERR, "Failed to set DHT22 pin %d as output", DHT22_PIN);
            return -1;
        }
        gpioWrite(DHT22_PIN, 0);
        gpioDelay(DHT22_START_LOW_US);
        gpioWrite(DHT22_PIN, 1);
        gpioDelay(DHT22_START_HIGH_US);
        gpioSetMode(DHT22_PIN, PI_INPUT);

        if (wait_for_level(DHT22_PIN, 0, DHT22_TIMEOUT_US) < 0) {
            syslog(LOG_ERR, "DHT22 start signal timeout (attempt %d)", attempt + 1);
            continue;
        }
        if (wait_for_level(DHT22_PIN, 1, DHT22_TIMEOUT_US) < 0) {
            syslog(LOG_ERR, "DHT22 response timeout (attempt %d)", attempt + 1);
            continue;
        }

        for (i = 0; i < 40; i++) {
            if (wait_for_level(DHT22_PIN, 0, DHT22_TIMEOUT_US) < 0) {
                syslog(LOG_ERR, "DHT22 bit %d low timeout (attempt %d)", i, attempt + 1);
                continue;
            }
            start_tick = gpioTick();
            if (wait_for_level(DHT22_PIN, 1, DHT22_TIMEOUT_US) < 0) {
                syslog(LOG_ERR, "DHT22 bit %d high timeout (attempt %d)", i, attempt + 1);
                continue;
            }
            edge_tick = gpioTick();
            uint32_t pulse_us = edge_tick - start_tick;
            data[i / 8] <<= 1;
            if (pulse_us > DHT22_BIT_THRESHOLD_US) {
                data[i / 8] |= 1;
            }
        }

        if (data[4] == ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
            uint16_t raw_humidity = (data[0] << 8) | data[1];
            *humidity = (float)raw_humidity / 10.0f;
            return 0;
        }
        syslog(LOG_ERR, "DHT22 checksum failed (attempt %d)", attempt + 1);
    }
    syslog(LOG_ERR, "DHT22 read failed after %d attempts", MAX_RETRIES);
    return -1;
}

static int post_humidity(const char *url, float humidity) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        syslog(LOG_ERR, "curl_easy_init() failed");
        return -1;
    }

    char json[128];
    snprintf(json, sizeof(json), "{\"humidity\": %.1f}", humidity);

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        syslog(LOG_ERR, "curl_slist_append() failed");
        curl_easy_cleanup(curl);
        return -1;
    }

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);

    CURLcode res = CURLE_OK;
    int ret = -1;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        res = curl_easy_perform(curl);
        if (res == CURLE_OK) {
            long http_code = 0;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
            if (http_code >= 200 && http_code < 300) {
                ret = 0;
                break;
            }
            syslog(LOG_ERR, "HTTP POST returned %ld (attempt %d)", http_code, attempt + 1);
        } else {
            syslog(LOG_ERR, "curl_easy_perform() failed: %s (attempt %d)", curl_easy_strerror(res), attempt + 1);
        }
        if (attempt < MAX_RETRIES - 1) {
            sleep(2);
        }
    }

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
    return ret;
}

int main(int argc, char *argv[]) {
    openlog("dht22_humidity", LOG_PID | LOG_CONS, LOG_USER);

    if (argc > 1) {
        server_url = argv[1];
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (curl_global_init(CURL_GLOBAL_ALL) != CURLE_OK) {
        syslog(LOG_ERR, "curl_global_init() failed");
        gpioTerminate();
        closelog();
        return 1;
    }

    while (!terminate) {
        float humidity;
        if (read_dht22(&humidity) == 0) {
            syslog(LOG_INFO, "Humidity: %.1f%%", humidity);
            if (post_humidity(server_url, humidity) != 0) {
                syslog(LOG_ERR, "Failed to post humidity data");
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity from DHT22");
        }
        sleep(READ_INTERVAL);
    }

    gpioTerminate();
    curl_global_cleanup();
    closelog();
    return 0;
}

