            *humidity = (float)raw_humidity / 10.0f;
            return 0;
        }
        syslog(LOG_ERR, "DHT22 checksum failed (attempt %d)", attempt + 1);
    }
    syslog(LOG_ERR, "DHT22 read failed after %d attempts", MAX_RETRIES);
    return -1;
}

static int post_humidity(const char *url, float humidity) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        syslog(LOG_ERR, "curl_easy_init() failed");
        return -1;
    }

    char json[128];
    snprintf(json, sizeof(json), "{\"humidity\": %.1f}", humidity);

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        syslog(LOG_ERR, "curl_slist_append() failed");
        curl_easy_cleanup(curl);
        return -1;
    }

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);

    CURLcode res = CURLE_OK;
    int ret = -1;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        res = curl_easy_perform(curl);
        if (res == CURLE_OK) {
            long http_code = 0;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
            if (http_code >= 200 && http_code < 300) {
                ret = 0;
                break;
            }
            syslog(LOG_ERR, "HTTP POST returned %ld (attempt %d)", http_code, attempt + 1);
        } else {
            syslog(LOG_ERR, "curl_easy_perform() failed: %s (attempt %d)", curl_easy_strerror(res), attempt + 1);
        }
        if (attempt < MAX_RETRIES - 1) {
            sleep(2);
        }
    }

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
    return ret;
}

int main(int argc, char *argv[]) {
    openlog("dht22_humidity", LOG_PID | LOG_CONS, LOG_USER);

    if (argc > 1) {
        server_url = argv[1];
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (curl_global_init(CURL_GLOBAL_ALL) != CURLE_OK) {
        syslog(LOG_ERR, "curl_global_init() failed");
        gpioTerminate();
        closelog();
        return 1;
    }

    while (!terminate) {
        float humidity;
        if (read_dht22(&humidity) == 0) {
            syslog(LOG_INFO, "Humidity: %.1f%%", humidity);
            if (post_humidity(server_url, humidity) != 0) {
                syslog(LOG_ERR, "Failed to post humidity data");
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity from DHT22");
        }
        sleep(READ_INTERVAL);
    }

    gpioTerminate();
    curl_global_cleanup();
    closelog();
    return 0;
}

