#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define CPU_TEMP_PATH "/sys/class/thermal/thermal_zone0/temp"
#define FAN_STATE_PATH "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_FILE "/var/log/fan_control.log"
#define POLL_INTERVAL_SEC 5
#define MAX_RETRIES 3

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_cpu_temp(void) {
    FILE *fp = fopen(CPU_TEMP_PATH, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", CPU_TEMP_PATH, strerror(errno));
        return -1;
    }

    char buffer[16];
    if (!fgets(buffer, sizeof(buffer), fp)) {
        fprintf(stderr, "Error reading %s: %s\n", CPU_TEMP_PATH, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    char *endptr;
    long temp = strtol(buffer, &endptr, 10);
    if (endptr == buffer) {
        fprintf(stderr, "Error parsing temperature from %s\n", CPU_TEMP_PATH);
        return -1;
    }
    return (int)temp;
}

static int write_fan_state(int state) {
    FILE *fp = fopen(FAN_STATE_PATH, "w");
    if (!fp) {
        fprintf(stderr, "Error opening %s for writing: %s\n", FAN_STATE_PATH, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%d", state) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", FAN_STATE_PATH, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", FAN_STATE_PATH, strerror(errno));
        return -1;
    }
    return 0;
}

static int log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[unknown time] %s\n", message);
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

static int get_max_fan_state(void) {
    FILE *fp = fopen(FAN_STATE_PATH, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s for reading: %s\n", FAN_STATE_PATH, strerror(errno));
        return -1;
    }

    char buffer[16];
    if (!fgets(buffer, sizeof(buffer), fp)) {
        fprintf(stderr, "Error reading max state from %s: %s\n", FAN_STATE_PATH, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    char *endptr;
    long max_state = strtol(buffer, &endptr, 10);
    if (endptr == buffer) {
        fprintf(stderr, "Error parsing max state from %s\n", FAN_STATE_PATH);
        return -1;
    }
    return (int)max_state;
}

static int set_fan_speed(int cpu_temp) {
    int max_state = get_max_fan_state();
    if (max_state < 0) {
        return -1;
    }

    int state;
    if (cpu_temp < 45000) {
        state = 0;
    } else if (cpu_temp < 55000) {
        state = 1;
    } else if (cpu_temp < 65000) {
        state = 2;
    } else {
        state = 3;
    }

    if (state < 0 || state > max_state) {
        fprintf(stderr, "Invalid fan state %d (max state %d)\n", state, max_state);
        return -1;
    }

    if (write_fan_state(state) != 0) {
        return -1;
    }

    char log_msg[128];
    snprintf(log_msg, sizeof(log_msg), "Fan speed set to state %d (CPU temp: %d mC)", state, cpu_temp);
    if (log_message(log_msg) != 0) {
        fprintf(stderr, "Warning: failed to log fan speed change\n");
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    printf("Fan control started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int cpu_temp = read_cpu_temp();
        if (cpu_temp < 0) {
            fprintf(stderr, "Failed to read CPU temperature. Retrying in %d seconds.\n", POLL_INTERVAL_SEC);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        if (set_fan_speed(cpu_temp) != 0) {
            fprintf(stderr, "Failed to set fan speed.\n");
        }

        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    if (write_fan_state(0) != 0) {
        fprintf(stderr, "Failed to stop fan during shutdown.\n");
    }
    log_message("Fan stopped (shutdown).");

    printf("Fan control stopped.\n");
    return 0;
}

