#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define SAMPLE_INTERVAL_US 1000000
#define MAX_RETRIES 3

#define Kp 1.0
#define Ki 0.1
#define Kd 0.01
#define TARGET_TEMP 50.0

#define TEMP_MIN 0.0
#define TEMP_MAX 100.0

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *msg) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fflush(log_file);
}

static int read_max31855(float *temp, int *fault) {
    char rx[4] = {0};
    int retries = 0;
    while (retries < MAX_RETRIES) {
        int bytes = spiRead(spi_handle, rx, 4);
        if (bytes == 4) {
            uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                           ((uint32_t)(uint8_t)rx[1] << 16) |
                           ((uint32_t)(uint8_t)rx[2] << 8)  |
                           ((uint32_t)(uint8_t)rx[3]);
            *fault = 0;
            if (raw & 0x00010000) {
                *fault = 1;
                if (raw & 0x00000004) log_message("MAX31855: Open circuit");
                else if (raw & 0x00000002) log_message("MAX31855: Short to GND");
                else if (raw & 0x00000001) log_message("MAX31855: Short to VCC");
                else log_message("MAX31855: Unknown fault");
            } else {
                int16_t thermocouple = (int16_t)(raw >> 18);
                *temp = thermocouple * 0.25;
            }
            return 0;
        }
        retries++;
        gpioDelay(1000);
    }
    log_message("MAX31855: SPI read failed after retries");
    return -1;
}

static void set_heater_pwm(int duty) {
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    gpioPWM(HEATER_GPIO, duty);
}

static void cleanup(void) {
    set_heater_pwm(0);
    if (spi_handle >= 0) spiClose(spi_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    log_file = fopen("heater_log.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        log_message("SPI initialisation failed");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);
    set_heater_pwm(0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float integral = 0.0, previous_error = 0.0;
    int heater_on = 0;

    while (running) {
        float temp = 0.0;
        int fault = 0;

        if (read_max31855(&temp, &fault) != 0) {
            set_heater_pwm(0);
            integral = 0.0;
            previous_error = 0.0;
            heater_on = 0;
            log_message("Temperature read failed, heater disabled");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (fault) {
            set_heater_pwm(0);
            integral = 0.0;
            previous_error = 0.0;
            heater_on = 0;
            continue;
        }

        if (temp < TEMP_MIN || temp > TEMP_MAX) {
            set_heater_pwm(0);
            integral = 0.0;
            previous_error = 0.0;
            heater_on = 0;
            log_message("Temperature out of range, heater disabled");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (!heater_on) {
            set_heater_pwm(50);
            heater_on = 1;
        }

        float error = TARGET_TEMP - temp;
        integral += error;
        float derivative = error - previous_error;
        float output = Kp * error + Ki * integral + Kd * derivative;
        previous_error = error;

        int duty = (int)(output + 0.5);
        if (duty < 0) duty = 0;
        if (duty > PWM_RANGE) duty = PWM_RANGE;
        set_heater_pwm(duty);

        char log_buf[256];
        snprintf(log_buf, sizeof(log_buf),
                 "Temp: %.2f C, Duty: %d%%, PID: %.2f, Heater: %s",
                 temp, duty, output, heater_on ? "ON" : "OFF");
        log_message(log_buf);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

