    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);
    set_heater_pwm(0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float integral = 0.0, previous_error = 0.0;
    int heater_on = 0;

    while (running) {
        float temp = 0.0;
        int fault = 0;

        if (read_max31855(&temp, &fault) != 0) {
            set_heater_pwm(0);
            integral = 0.0;
            previous_error = 0.0;
            heater_on = 0;
            log_message("Temperature read failed, heater disabled");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (fault) {
            set_heater_pwm(0);
            integral = 0.0;
            previous_error = 0.0;
            heater_on = 0;
            continue;
        }

        if (temp < TEMP_MIN || temp > TEMP_MAX) {
            set_heater_pwm(0);
            integral = 0.0;
            previous_error = 0.0;
            heater_on = 0;
            log_message("Temperature out of range, heater disabled");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (!heater_on) {
            set_heater_pwm(50);
            heater_on = 1;
        }

        float error = TARGET_TEMP - temp;
        integral += error;
        float derivative = error - previous_error;
        float output = Kp * error + Ki * integral + Kd * derivative;
        previous_error = error;

        int duty = (int)(output + 0.5);
        if (duty < 0) duty = 0;
        if (duty > PWM_RANGE) duty = PWM_RANGE;
        set_heater_pwm(duty);

        char log_buf[256];
        snprintf(log_buf, sizeof(log_buf),
                 "Temp: %.2f C, Duty: %d%%, PID: %.2f, Heater: %s",
                 temp, duty, output, heater_on ? "ON" : "OFF");
        log_message(log_buf);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

