#define LOG_FILE "cooling_log.csv"
#define MIN_TEMP 40.0
#define MAX_TEMP 70.0
#define PWM_FREQ 25000
#define POLL_INTERVAL 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static float read_cpu_temp(void) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        perror("Error opening temperature file");
        return -1.0f;
    }
    int temp_milli;
    if (fscanf(fp, "%d", &temp_milli) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1.0f;
    }
    fclose(fp);
    return (float)temp_milli / 1000.0f;
}

static int calculate_duty_cycle(float temp) {
    if (temp <= MIN_TEMP) return 0;
    if (temp >= MAX_TEMP) return 100;
    return (int)((temp - MIN_TEMP) / (MAX_TEMP - MIN_TEMP) * 100.0f);
}

static int set_fan_speed(int duty_cycle) {
    if (gpioPWM(FAN_GPIO, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle to %d\n", duty_cycle);
        return -1;
    }
    return 0;
}

static int log_data(float temp, int duty_cycle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%.2f,%d\n", timestamp, temp, duty_cycle);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ) != 0) {
        fprintf(stderr, "Error setting PWM frequency to %d Hz\n", PWM_FREQ);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(FAN_GPIO, 100) != 0) {
        fprintf(stderr, "Error setting PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error setting up signal handlers");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(LOG_FILE, "r");
    if (!fp) {
        fp = fopen(LOG_FILE, "w");
        if (fp) {
            fprintf(fp, "Timestamp,Temperature(C),DutyCycle(%%)\n");
            fclose(fp);
        } else {
            perror("Error creating log file");
            gpioTerminate();
            return EXIT_FAILURE;
        }
    } else {
        fclose(fp);
    }

    while (running) {
        float temp = read_cpu_temp();
        if (temp < 0.0f) {
            fprintf(stderr, "Error reading temperature, skipping cycle\n");
        } else {
            int duty = calculate_duty_cycle(temp);
            if (set_fan_speed(duty) != 0) {
                fprintf(stderr, "Error setting fan speed\n");
            }
            if (log_data(temp, duty) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        }
        sleep(POLL_INTERVAL);
    }

    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

