#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define MEASUREMENT_CMD 0x3608
#define READ_LEN 3
#define RETRY_COUNT 3
#define RETRY_DELAY_US 10000
#define LOG_FILE "flow_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else crc <<= 1;
        }
    }
    return crc;
}

static int read_flow_rate(int handle, float *flow_rate) {
    char cmd[2] = {(MEASUREMENT_CMD >> 8) & 0xFF, MEASUREMENT_CMD & 0xFF};
    char buf[READ_LEN];
    int retries = 0;

    while (retries < RETRY_COUNT) {
        if (i2cWriteDevice(handle, cmd, 2) != 0) {
            fprintf(stderr, "I2C write failed (attempt %d)\n", retries + 1);
            retries++;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        gpioDelay(2000);

        if (i2cReadDevice(handle, buf, READ_LEN) != READ_LEN) {
            fprintf(stderr, "I2C read failed (attempt %d)\n", retries + 1);
            retries++;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        if (crc8((uint8_t *)buf, 2) != (uint8_t)buf[2]) {
            fprintf(stderr, "CRC mismatch (attempt %d)\n", retries + 1);
            retries++;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        int16_t raw = (buf[0] << 8) | buf[1];
        *flow_rate = raw * 0.01f;
        return 0;
    }

    fprintf(stderr, "Failed to read flow rate after %d retries\n", RETRY_COUNT);
    return -1;
}

static void log_flow_rates(float flow1, float flow2) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, flow1, flow2);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open I2C device 1 (addr 0x%02X): %d\n", SENSOR1_ADDR, i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C device 2 (addr 0x%02X): %d\n", SENSOR2_ADDR, i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Logging flow rates to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (running) {
        float flow1 = 0.0f, flow2 = 0.0f;

        if (read_flow_rate(i2c_handle1, &flow1) != 0) {
            fprintf(stderr, "Sensor 1 read error, skipping cycle\n");
        } else if (read_flow_rate(i2c_handle2, &flow2) != 0) {
            fprintf(stderr, "Sensor 2 read error, skipping cycle\n");
        } else {
            log_flow_rates(flow1, flow2);
            printf("Flow1: %.2f ml/min, Flow2: %.2f ml/min\n", flow1, flow2);
        }

        sleep(1);
    }

    printf("\nShutting down...\n");
    if (i2c_handle1 >= 0) i2cClose(i2c_handle1);
    if (i2c_handle2 >= 0) i2cClose(i2c_handle2);
    gpioTerminate();
    return 0;
}

