#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 18
#define PULSES_PER_REV 360
#define LOG_FILE "encoder_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int pin) {
    return gpioRead(pin);
}

static int update_state(int a, int b, int *prev_a, int *prev_b, int *state) {
    int new_state = *state;
    if (a == 1 && b == 0) {
        new_state++;
    } else if (a == 0 && b == 1) {
        new_state--;
    }
    if (new_state < 0) new_state = PULSES_PER_REV - 1;
    if (new_state >= PULSES_PER_REV) new_state = 0;
    if (new_state != *state) {
        *state = new_state;
        *prev_a = a;
        *prev_b = b;
        return 1;
    }
    return 0;
}

static double calculate_angle(int state) {
    return ((double)state / PULSES_PER_REV) * 360.0;
}

static void log_data(int state, double angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, State: %d, Angle: %.2f\n", timestamp, state, angle);
    fflush(log_file);
}

int main(void) {
    int prev_a = 0, prev_b = 0, state = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_A_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_A_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_B_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_B_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_A_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", SENSOR_A_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_B_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", SENSOR_B_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to set signal handlers");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Encoder monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int a = read_sensor(SENSOR_A_PIN);
        int b = read_sensor(SENSOR_B_PIN);

        if (update_state(a, b, &prev_a, &prev_b, &state)) {
            double angle = calculate_angle(state);
            log_data(state, angle);
        }
        gpioDelay(1000);
    }

    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

