#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#define SENSOR_GPIO 18
#define PULSES_PER_REVOLUTION 1
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_INTERVAL_SEC 1

static volatile int pulse_count = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void pulse_counter(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; (void)level; (void)tick; (void)user_data;
    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

static double calculate_rpm(int pulses, double interval_sec) {
    if (interval_sec <= 0.0) return 0.0;
    return ((double)pulses / (double)PULSES_PER_REVOLUTION) * (60.0 / interval_sec);
}

static void log_rpm(double rpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed\n");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, RPM: %.2f\n", timestamp, rpm);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

int main(void) {
    int ret;

    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed with code %d\n", ret);
        return EXIT_FAILURE;
    }

    ret = gpioSetMode(SENSOR_GPIO, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input (code %d)\n", SENSOR_GPIO, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetPullUpDown(SENSOR_GPIO, PI_PUD_DOWN);
    if (ret != 0) {
        fprintf(stderr, "Error: Failed to set pull-down on GPIO %d (code %d)\n", SENSOR_GPIO, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetISRFuncEx(SENSOR_GPIO, RISING_EDGE, 0, pulse_counter, NULL);
    if (ret != 0) {
        fprintf(stderr, "Error: Failed to set ISR on GPIO %d (code %d)\n", SENSOR_GPIO, ret);
        fclose(log_file);
        log_file = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set signal handlers\n");
        gpioSetISRFuncEx(SENSOR_GPIO, RISING_EDGE, 0, NULL, NULL);
        fclose(log_file);
        log_file = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("RPM monitoring started on GPIO %d. Press Ctrl+C to exit.\n", SENSOR_GPIO);

    while (running) {
        sleep(SAMPLE_INTERVAL_SEC);
        if (!running) break;

        int pulses = 0;
        pthread_mutex_lock(&pulse_mutex);
        pulses = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        double rpm = calculate_rpm(pulses, (double)SAMPLE_INTERVAL_SEC);
        log_rpm(rpm);
    }

    printf("\nShutting down...\n");

    gpioSetISRFuncEx(SENSOR_GPIO, RISING_EDGE, 0, NULL, NULL);
    gpioTerminate();

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    pthread_mutex_destroy(&pulse_mutex);

    printf("RPM monitoring stopped.\n");
    return EXIT_SUCCESS;
}

