#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x70
#define LOG_FILE "air_quality_log.csv"
#define READ_INTERVAL_SEC 5
#define READ_LEN 7
#define TVOC_REG 0x00
#define ECO2_REG 0x02

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_sensor_data(int handle, unsigned char *data) {
    char reg = TVOC_REG;
    int result = i2cWriteDevice(handle, &reg, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing register address: %d\n", result);
        return -1;
    }
    result = i2cReadDevice(handle, (char *)data, READ_LEN);
    if (result != READ_LEN) {
        fprintf(stderr, "Error reading sensor data: expected %d bytes, got %d\n", READ_LEN, result);
        return -1;
    }
    return 0;
}

static int calculate_iaq(int tvoc, int eco2) {
    int iaq = 100 - (tvoc / 10) - ((eco2 - 400) / 50);
    if (iaq < 0) iaq = 0;
    if (iaq > 100) iaq = 100;
    return iaq;
}

static int log_data(FILE *fp, int iaq, int tvoc, int eco2) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, iaq, tvoc, eco2) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,IAQ,TVOC,eco2\n");
        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    unsigned char data[READ_LEN];
    while (!terminate) {
        if (read_sensor_data(i2c_handle, data) == 0) {
            int tvoc = (data[1] << 8) | data[2];
            int eco2 = (data[5] << 8) | data[6];
            int iaq = calculate_iaq(tvoc, eco2);
            if (log_data(log_file, iaq, tvoc, eco2) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed, retrying...\n");
        }
        sleep(READ_INTERVAL_SEC);
    }

    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file != NULL) fclose(log_file);
    gpioTerminate();
    return 0;
}

