#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME   "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define POLL_INTERVAL_MS 100
#define INTRUSION_TIME_S 5

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(line, "ttp223_tamper") < 0) {
        fprintf(stderr, "Failed to request line %d as input: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    printf("Monitoring TTP223B touch sensor on GPIO %d. Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET);

    int intrusion_active = 0;
    struct timespec intrusion_start;
    struct timespec now;
    long elapsed_ms;

    while (program_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            fprintf(stderr, "Failed to read GPIO %d: %s\n",
                    GPIO_LINE_OFFSET, strerror(errno));
            goto cleanup;
        }

        if (val == 1) {
            if (!intrusion_active) {
                intrusion_active = 1;
                clock_gettime(CLOCK_MONOTONIC, &intrusion_start);
                printf("Intrusion detected! Sensor touched for > %d s.\n",
                       INTRUSION_TIME_S);
            } else {
                clock_gettime(CLOCK_MONOTONIC, &now);
                elapsed_ms = (now.tv_sec - intrusion_start.tv_sec) * 1000L +
                             (now.tv_nsec - intrusion_start.tv_nsec) / 1000000L;

                if (elapsed_ms > INTRUSION_TIME_S * 1000L) {
                    printf("Intrusion confirmed! Sensor touched for > %d s.\n",
                           INTRUSION_TIME_S);
                }
            }
        } else {
            if (intrusion_active) {
                intrusion_active = 0;
                printf("Sensor released.\n");
            }
        }

        struct timespec ts = { 0, POLL_INTERVAL_MS * 1000000L };
        nanosleep(&ts, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line != NULL)
        gpiod_line_release(line);
    if (chip != NULL)
        gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("Exiting gracefully.\n");

    return ret;
}

