#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <gpiod.h>

#define I2S_DEVICE "/dev/snd/pcmC0D0c"
#define GPIO_CHIP "gpiochip4"
#define GPIO_PIN 17
#define SAMPLE_RATE 16000
#define NUM_CHANNELS 1
#define BITS_PER_SAMPLE 16
#define BUFFER_SIZE 1024
#define FILENAME "audio_capture.pcm"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int open_i2s_device(void) {
    int fd = open(I2S_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2S device %s: %s\n", I2S_DEVICE, strerror(errno));
        return -1;
    }
    return fd;
}

static int configure_i2s(int fd) {
    uint32_t format = SND_PCM_FORMAT_S16_LE;
    uint32_t rate = SAMPLE_RATE;
    uint32_t channels = NUM_CHANNELS;

    if (ioctl(fd, SND_PCM_SET_FORMAT, &format) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        return -1;
    }
    if (ioctl(fd, SND_PCM_SET_RATE, &rate) < 0) {
        fprintf(stderr, "Error setting rate: %s\n", strerror(errno));
        return -1;
    }
    if (ioctl(fd, SND_PCM_SET_CHANNELS, &channels) < 0) {
        fprintf(stderr, "Error setting channels: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int acquire_i2s_data(int fd, int16_t *buffer, int num_samples) {
    static uint8_t read_buf[BUFFER_SIZE * 4];
    static int read_len = 0;
    static int write_len = 0;

    if (read_len >= (int)sizeof(read_buf)) {
        read_len = 0;
    }

    ssize_t bytes = read(fd, read_buf + read_len, sizeof(read_buf) - read_len);
    if (bytes < 0) {
        if (errno == EINTR) return 0;
        fprintf(stderr, "Error reading I2S data: %s\n", strerror(errno));
        return -1;
    }
    if (bytes == 0) {
        return 0;
    }
    read_len += (int)bytes;

    int32_t *int32_buf = (int32_t *)read_buf;
    for (int i = 0; i < num_samples; i++) {
        int32_t sample = int32_buf[write_len / 4];
        write_len += 4;

        if (write_len >= (int)sizeof(read_buf)) {
            write_len = 0;
        }

        int32_t raw = sample >> 8;
        int32_t pcm = (raw >> 8) | (raw << 16);
        buffer[i] = (int16_t)(pcm >> 8);
    }
    return 1;
}

static int write_pcm_file(const char *filename, const int16_t *data, int num_samples) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    size_t written = fwrite(data, sizeof(int16_t), num_samples, fp);
    if (written != (size_t)num_samples) {
        fprintf(stderr, "Error writing to file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line, "inmp441-lr-select", 1) < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    int i2s_fd = open_i2s_device();
    if (i2s_fd < 0) {
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (configure_i2s(i2s_fd) < 0) {
        close(i2s_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    int16_t *buffer = (int16_t *)malloc(BUFFER_SIZE * sizeof(int16_t));
    if (!buffer) {
        fprintf(stderr, "Error allocating memory: %s\n", strerror(errno));
        close(i2s_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    int num_samples = BUFFER_SIZE;
    int samples_written = 0;

    while (running) {
        if (gpiod_line_set_value(line, 1) < 0) {
            fprintf(stderr, "Error setting GPIO value: %s\n", strerror(errno));
            break;
        }

        int ret = acquire_i2s_data(i2s_fd, buffer, num_samples);
        if (ret < 0) {
            break;
        }
        if (ret == 0) {
            continue;
        }

        if (write_pcm_file(FILENAME, buffer, num_samples) < 0) {
            fprintf(stderr, "Error writing PCM file\n");
            break;
        }
        samples_written += num_samples;
        printf("Samples written: %d\n", samples_written);
    }

