#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18
#define PWM_FREQUENCY 100
#define PWM_RANGE 255
#define DEBOUNCE_DELAY_US 50000
#define POLL_DELAY_US 50000
#define LOG_FILE "flame_log.txt"
#define FLAME_TIMEOUT_SEC 30

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s: %s\n", timestamp, message);
    } else {
        fprintf(fp, "[timestamp error]: %s\n", message);
    }
    fclose(fp);
}

static int read_flame_sensor(void) {
    int val = gpioRead(FLAME_SENSOR_PIN);
    if (val < 0) {
        log_event("Error reading flame sensor GPIO");
        return -1;
    }
    return val;
}

static void control_fan(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    if (gpioPWM(FAN_PIN, duty_cycle) < 0) {
        log_event("Error setting PWM duty cycle");
    }
}

static void cleanup(void) {
    control_fan(0);
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(FAN_PIN, PI_OUTPUT);
    gpioTerminate();
    log_event("Cleanup complete. Exiting.");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set flame sensor pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(FAN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set fan pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(FAN_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(FAN_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("System started");

    time_t flame_start_time = 0;
    int flame_active = 0;
    int last_stable_state = 1;

    while (running) {
        int sensor_value = read_flame_sensor();
        if (sensor_value < 0) {
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (sensor_value == 0 && last_stable_state == 1) {
            gpioDelay(DEBOUNCE_DELAY_US);
            sensor_value = read_flame_sensor();
            if (sensor_value == 0) {
                flame_start_time = time(NULL);
                flame_active = 1;
                log_event("Flame detected");
            }
        } else if (sensor_value == 1 && last_stable_state == 0) {
            gpioDelay(DEBOUNCE_DELAY_US);
            sensor_value = read_flame_sensor();
            if (sensor_value == 1) {
                flame_active = 0;
                log_event("Flame ended");
            }
        }

        if (flame_active) {
            time_t current_time = time(NULL);
            if (difftime(current_time, flame_start_time) > FLAME_TIMEOUT_SEC) {
                log_event("Flame timeout (sensor absent or stuck)");
                flame_active = 0;
            } else {
                int duty_cycle = (int)(((float)difftime(current_time, flame_start_time) / FLAME_TIMEOUT_SEC) * 80.0f);
                control_fan(duty_cycle);
            }
        } else {
            control_fan(0);
        }

        last_stable_state = sensor_value;
        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

