typedef struct {
    uint32_t magic;
    uint32_t version;
    uint32_t timestamp;
    uint32_t num_frames;
    uint32_t frame_size;
    uint32_t start_freq;
    uint32_t end_freq;
    uint32_t num_chirps;
    uint32_t num_samples;
    uint32_t frame_period;
} __attribute__((packed)) Header;

typedef struct {
    uint32_t start_freq;
    uint32_t end_freq;
    uint32_t num_chirps;
    uint32_t num_samples;
    uint32_t frame_period;
} Config;

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_header(FILE *f, const Header *h) {
    uint8_t buf[HEADER_SIZE];
    memcpy(buf, &h->magic, 4);
    memcpy(buf + 4, &h->version, 4);
    memcpy(buf + 8, &h->timestamp, 4);
    memcpy(buf + 12, &h->num_frames, 4);
    memcpy(buf + 16, &h->frame_size, 4);
    memcpy(buf + 20, &h->start_freq, 4);
    memcpy(buf + 24, &h->end_freq, 4);
    memcpy(buf + 28, &h->num_chirps, 4);
    memcpy(buf + 32, &h->num_samples, 4);
    memcpy(buf + 36, &h->frame_period, 4);
    if (fwrite(buf, 1, HEADER_SIZE, f) != HEADER_SIZE) {
        perror("fwrite header");
        return -1;
    }
    return 0;
}

static int read_frame(FILE *f, uint8_t *data, uint32_t size) {
    uint32_t total = 0;
    while (total < size) {
        ssize_t n = fread(data + total, 1, size - total, f);
        if (n <= 0) {
            if (feof(f)) {
                fprintf(stderr, "Unexpected EOF reading frame\n");
                return -1;
            }
            perror("fread frame");
            return -1;
        }
        total += (uint32_t)n;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode trigger failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(DATA_READY_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode data_ready failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite trigger low failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("radar_data.bin", "wb");
    if (!log_file) {
        perror("fopen");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    Header header;
    header.magic = MAGIC_WORD;
    header.version = 1;
    header.timestamp = (uint32_t)time(NULL);
    header.num_frames = NUM_FRAMES;
    header.frame_size = DATA_SIZE;
    header.start_freq = 7700000000U;
    header.end_freq = 7900000000U;
    header.num_chirps = 64;
    header.num_samples = 256;
    header.frame_period = FRAME_PERIOD_US;

    if (write_header(log_file, &header) < 0) {
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Logging %d frames to radar_data.bin\n", NUM_FRAMES);

    uint8_t data[DATA_SIZE];
    uint32_t frame_num = 0;
    uint32_t elapsed = 0;

    while (running && frame_num < NUM_FRAMES) {
        if (gpioWrite(TRIGGER_PIN, 1) < 0) {
            fprintf(stderr, "gpioWrite trigger high failed\n");
            break;
        }
        gpioDelay(100);
        if (gpioWrite(TRIGGER_PIN, 0) < 0) {
            fprintf(stderr, "gpioWrite trigger low failed\n");
            break;
        }

        while (running && gpioRead(DATA_READY_PIN) == 0) {
            gpioDelay(1000);
        }
        if (!running) break;

        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        uint32_t ts_val = (uint32_t)ts.tv_sec | ((uint32_t)ts.tv_nsec / 1000);

        if (read_frame(log_file, data, DATA_SIZE) < 0) {
            break;
        }

        if (fwrite(data, 1, DATA_SIZE, log_file) != DATA_SIZE) {
            perror("fwrite data");
            break;
        }

        if (fwrite(&ts_val, sizeof(ts_val), 1, log_file) != 1) {
            perror("fwrite timestamp");
            break;
        }

        frame_num++;
        elapsed += FRAME_PERIOD_US;
        if (elapsed > 1000000) {
            elapsed = 0;
            printf("Frame %u logged\n", frame_num);
        }
    }

    if (log_file) fclose(log_file);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    printf("Program finished\n");
    return 0;
}

