#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

#define OPT3001_ADDR 0x44
#define REG_RESULT 0x00
#define REG_CONFIG 0x01
#define CONFIG_CONTINUOUS 0x0000
#define CONFIG_100MS 0x0000
#define CONFIG_AUTO_RANGE 0x0000
#define CONFIG_DEFAULT (CONFIG_CONTINUOUS | CONFIG_100MS | CONFIG_AUTO_RANGE)

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int opt3001_init(int handle) {
    char config[2];
    config[0] = (CONFIG_DEFAULT >> 8) & 0xFF;
    config[1] = CONFIG_DEFAULT & 0xFF;

    if (i2cWriteI2CBlockData(handle, REG_CONFIG, config, 2) < 0) {
        fprintf(stderr, "Error writing config register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int opt3001_read_lux(int handle, float *lux_out) {
    char data[2];
    int result;

    result = i2cReadI2CBlockData(handle, REG_RESULT, data, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading result register: %s\n", strerror(errno));
        return -1;
    }

    uint16_t raw = ((uint16_t)(data[0] & 0xFF) << 8) | (uint8_t)(data[1] & 0xFF);
    uint8_t exponent = (raw >> 12) & 0x0F;
    uint16_t mantissa = raw & 0x0FFF;

    *lux_out = 0.01f * (float)(1 << exponent) * (float)mantissa;
    return 0;
}

static int log_data(float lux) {
    FILE *fp = fopen("light_data.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f\n", timestamp, lux);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (opt3001_init(i2c_handle) < 0) {
        fprintf(stderr, "OPT3001 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("OPT3001 logging started. Press Ctrl+C to stop.\n");

    while (running) {
        float lux;
        if (opt3001_read_lux(i2c_handle, &lux) == 0) {
            if (log_data(lux) < 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }
        gpioDelay(1000000);
    }

    printf("\nShutting down...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

