#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 50
#define CONSUMER_NAME "ttp226_touch"

static const unsigned int gpio_pins[NUM_CHANNELS] = {2, 3, 4, 17, 27, 22, 10, 9};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char buf[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S", &timeinfo);
        printf("%s", buf);
    } else {
        printf("UNKNOWN");
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_request *request = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_line_settings *settings = NULL;
    struct gpiod_request_config *req_cfg = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    settings = gpiod_line_settings_new();
    if (settings == NULL) {
        fprintf(stderr, "Failed to allocate line settings: %s\n", strerror(errno));
        goto cleanup;
    }

    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);
    gpiod_line_settings_set_bias(settings, GPIOD_LINE_BIAS_DISABLED);

    line_cfg = gpiod_line_config_new();
    if (line_cfg == NULL) {
        fprintf(stderr, "Failed to allocate line config: %s\n", strerror(errno));
        goto cleanup;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpiod_line_config_add_line_settings(line_cfg, &gpio_pins[i], 1, settings) != 0) {
            fprintf(stderr, "Failed to add line settings for GPIO %u: %s\n",
                    gpio_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    req_cfg = gpiod_request_config_new();
    if (req_cfg == NULL) {
        fprintf(stderr, "Failed to allocate request config: %s\n", strerror(errno));
        goto cleanup;
    }
    gpiod_request_config_set_consumer(req_cfg, CONSUMER_NAME);

    request = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (request == NULL) {
        fprintf(stderr, "Failed to request GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("TTP226 Touch Sensor Array Reader\n");
    printf("Pins: GPIO %u, %u, %u, %u, %u, %u, %u, %u\n",
           gpio_pins[0], gpio_pins[1], gpio_pins[2], gpio_pins[3],
           gpio_pins[4], gpio_pins[5], gpio_pins[6], gpio_pins[7]);
    printf("Poll interval: %d ms. Press Ctrl+C to exit.\n\n", POLL_INTERVAL_MS);

    while (program_running) {
        int values[NUM_CHANNELS];
        int read_ret = gpiod_line_request_get_values(request, values);
        if (read_ret != 0) {
            fprintf(stderr, "Failed to read GPIO values: %s\n", strerror(errno));
            break;
        }

        print_timestamp();
        for (int i = 0; i < NUM_CHANNELS; i++) {
            printf("%d", values[i]);
            if (i < NUM_CHANNELS - 1) {
                printf(",");
            }
        }
        printf("\n");
        fflush(stdout);

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (request != NULL) {
        gpiod_line_request_release(request);
    }
    if (req_cfg != NULL) {
        gpiod_request_config_free(req_cfg);
    }
    if (line_cfg != NULL) {
        gpiod_line_config_free(line_cfg);
    }
    if (settings != NULL) {
        gpiod_line_settings_free(settings);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    return ret;
}

