#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define TILT_GPIO 4          /* BCM pin 4, physical pin 7 */
#define POLL_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void log_tilt_state(int gpio, int level)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        snprintf(ts, sizeof(ts), "unknown-time");
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    }

    const char *state = (level == 0) ? "Tilted" : "Not Tilted";
    printf("[%s] GPIO %d: %s\n", ts, gpio, state);
    fflush(stdout);
}

int main(void)
{
    int last_state = -1;   /* unknown initial state forces first-read logging */

    /* --- Install SIGINT handler for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n", gpioInitialise());
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO 4 as input with internal pull-up --- */
    if (gpioSetMode(TILT_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed.\n", TILT_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(TILT_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(%d, PI_PUD_UP) failed.\n", TILT_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Tilt sensor monitoring started on GPIO %d.\n", TILT_GPIO);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* --- Main polling loop --- */
    while (g_running) {
        int level = gpioRead(TILT_GPIO);

        if (level < 0) {
            fprintf(stderr, "Error: gpioRead(%d) failed (code %d).\n", TILT_GPIO, level);
            break;
        }

        if (level != last_state) {
            log_tilt_state(TILT_GPIO, level);
            last_state = level;
        }

        usleep(POLL_INTERVAL_US);
    }

    /* --- Clean shutdown --- */
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

