#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_UVINDEX0 0x24
#define SI1145_REG_UVINDEX1 0x25
#define SI1145_REG_COMMAND 0x30
#define SI1145_REG_CHLIST 0x01
#define SI1145_REG_ALS_VIS_ADC_GAIN 0x0F
#define SI1145_REG_ALS_IR_ADC_GAIN 0x10
#define SI1145_REG_UV_ADC_GAIN 0x11

#define SI1145_CMD_RESET 0x01
#define SI1145_CMD_ALS_FORCE 0x06
#define SI1145_CMD_PS_FORCE 0x05
#define SI1145_CMD_PSALS_FORCE 0x07
#define SI1145_CMD_PS_PAUSE 0x0B
#define SI1145_CMD_PS_START 0x0E
#define SI1145_CMD_PS_STOP 0x0D

#define SI1145_PARTID 0x45
#define SI1145_HW_KEY_VAL 0x17

#define I2C_BUS 1
#define LOG_FILE "uv_als_log.csv"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(uint8_t reg, uint8_t val) {
    if (i2cWriteByteData(i2c_handle, reg, val) < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %s\n", reg, pigpio_error(i2c_handle));
        return -1;
    }
    return 0;
}

static int read_reg(uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %s\n", reg, pigpio_error(rc));
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int init_si1145(void) {
    uint8_t partid = 0;
    if (read_reg(SI1145_REG_PARTID, &partid) < 0) {
        fprintf(stderr, "Cannot read PART ID - sensor absent or bus error\n");
        return -1;
    }
    if (partid != SI1145_PARTID) {
        fprintf(stderr, "Unexpected PART ID: 0x%02X (expected 0x%02X)\n", partid, SI1145_PARTID);
        return -1;
    }

    if (write_reg(SI1145_REG_COMMAND, SI1145_CMD_RESET) < 0) return -1;
    gpioDelay(10000);

    if (write_reg(SI1145_REG_HW_KEY, SI1145_HW_KEY_VAL) < 0) return -1;

    if (write_reg(SI1145_REG_CHLIST, 0x01) < 0) return -1;

    if (write_reg(SI1145_REG_MEASRATE0, 0x00) < 0) return -1;
    if (write_reg(SI1145_REG_MEASRATE1, 0x00) < 0) return -1;

    if (write_reg(SI1145_REG_ALS_VIS_ADC_GAIN, 0x00) < 0) return -1;
