#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define SENSOR1_ADDR   0x36
#define SENSOR2_ADDR   0x37
#define GPIO_CHIP       "gpiochip4"
#define GPIO_LINE       17
#define FLOW_SCALE      0.036f
#define FLOW_THRESHOLD  0.5f
#define LOG_FILE        "flow_log.txt"
#define MEAS_DELAY_MS   100
#define POLL_DELAY_MS   1000

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t sensirion_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t cmd_reg, uint16_t cmd) {
    uint8_t buf[3] = { cmd_reg, (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write cmd 0x%02X failed: %s\n", cmd_reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_sensor(int fd) {
    if (i2c_write_cmd(fd, 0x08, 0x3608) < 0) return -1;
    usleep(MEAS_DELAY_MS * 1000);
    return 0;
}

static int read_flow_rate(int fd, float *flow_out) {
    uint8_t buf[9];
    if (i2c_read_bytes(fd, 0x00, buf, sizeof(buf)) < 0) return -1;

    for (int i = 0; i < 3; i++) {
        if (sensirion_crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "CRC mismatch on flow word %d\n", i);
            return -1;
        }
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_out = (float)raw * FLOW_SCALE;
    return 0;
}

static void log_flow(FILE *fp, float f1, float f2, float avg) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Sensor1: %.3f ml/min, Sensor2: %.3f ml/min, Avg: %.3f ml/min\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, f1, f2, avg);
    fflush(fp);
}

int main(void) {
    struct sigaction sa = { .sa_handler = sig_handler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd1 = open(I2C_BUS, O_RDWR);
    if (fd1 < 0) { perror("open i2c"); return 1; }
    int fd2 = open(I2C_BUS, O_RDWR);
    if (fd2 < 0) { perror("open i2c"); close(fd1); return 1; }

    if (ioctl(fd1, I2C_SLAVE, SENSOR1_ADDR) < 0) { perror("ioctl1"); goto cleanup; }
    if (ioctl(fd2, I2C_SLAVE, SENSOR2_ADDR) < 0) { perror("ioctl2"); goto cleanup; }

    if (init_sensor(fd1) < 0 || init_sensor(fd2) < 0) {
        fprintf(stderr, "Sensor init failed\n");
        goto cleanup;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) { perror("gpiod_chip_open"); goto cleanup; }
    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) { perror("gpiod_get_line"); gpiod_chip_close(chip); goto cleanup; }
    if (gpiod_line_request_output(line, "flow_alarm", 0) < 0) {
        perror("gpiod_request_output");
        gpiod_chip_close(chip);
        goto cleanup;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) { perror("fopen log"); gpiod_chip_close(chip); goto cleanup; }

    while (g_running) {
        float f1 = 0.0f, f2 = 0.0f;
        int ok1 = read_flow_rate(fd1, &f1);
        int ok2 = read_flow_rate(fd2, &f2);

        if (ok1 == 0 && ok2 == 0) {
            float avg = (f1 + f2) / 2.0f;
            log_flow(fp, f1, f2, avg);
            int alarm = (avg < FLOW_THRESHOLD) ? 1 : 0;
            gpiod_line_set_value(line, alarm);
        } else {
            fprintf(stderr, "Read error: sensor1=%s sensor2=%s\n", ok1 ? "ok" : "fail", ok2 ? "ok" : "fail");
        }

        usleep(POLL_DELAY_MS * 1000);
    }

cleanup:
    gpiod_line_set_value(line, 0);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(fd1);
    close(fd2);
    fclose(fp);
    return 0;
}

