#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x55
#define MODE_CONTROL   0x1D
#define MODE_ACTIVE    0x10
#define STATUS_REG     0x1B
#define STATUS_ACTIVE  0x01
#define X_REG_L        0x2A
#define X_REG_H        0x2B
#define Y_REG_L        0x2C
#define Y_REG_H        0x2D
#define Z_REG_L        0x2E
#define Z_REG_H        0x2F
#define SCALE_FACTOR   0.0009765625f
#define SAMPLE_MS      500
#define INIT_TIMEOUT   1000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_csv = NULL;

static void sighandler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg_l, int16_t *out) {
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, reg_l, &lo) < 0) return -1;
    if (i2c_read_reg8(fd, reg_l + 1, &hi) < 0) return -1;
    *out = (int16_t)((hi << 8) | lo);
    return 0;
}

static int init_sensor(int fd) {
    if (i2c_write_reg8(fd, MODE_CONTROL, MODE_ACTIVE) < 0) return -1;
    for (int i = 0; i < INIT_TIMEOUT; i++) {
        uint8_t status;
        if (i2c_read_reg8(fd, STATUS_REG, &status) < 0) return -1;
        if (status & STATUS_ACTIVE) return 0;
        usleep(1000);
    }
    fprintf(stderr, "Sensor did not become active within %d ms\n", INIT_TIMEOUT);
    return -1;
}

static void log_sample(FILE *f, float xg, float yg, float zg) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(f, "%s,%.6f,%.6f,%.6f\n", ts, xg, yg, zg);
    fflush(f);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", D7S_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    if (init_sensor(g_i2c_fd) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        close(g_i2c_fd);
        return 1;
    }

    g_csv = fopen("fan_health.csv", "a");
    if (!g_csv) {
        fprintf(stderr, "Cannot open fan_health.csv: %s\n", strerror(errno));
        close(g_i2c_fd);
        return 1;
    }
    fseek(g_csv, 0, SEEK_END);
    if (ftell(g_csv) == 0) {
        fprintf(g_csv, "timestamp,x_g,y_g,z_g\n");
        fflush(g_csv);
    }

    printf("Fan vibration monitoring started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t raw_x, raw_y, raw_z;
        if (i2c_read_reg16(g_i2c_fd, X_REG_L, &raw_x) < 0 ||
            i2c_read_reg16(g_i2c_fd, Y_REG_L, &raw_y) < 0 ||
            i2c_read_reg16(g_i2c_fd, Z_REG_L, &raw_z) < 0) {
            fprintf(stderr, "Read error; retrying next cycle\n");
            usleep(SAMPLE_MS * 1000);
            continue;
        }
        float xg = raw_x * SCALE_FACTOR;
        float yg = raw_y * SCALE_FACTOR;
        float zg = raw_z * SCALE_FACTOR;
        log_sample(g_csv, xg, yg, zg);
        usleep(SAMPLE_MS * 1000);
    }

    printf("\nShutting down...\n");
    if (g_csv) fclose(g_csv);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return 0;
}

