#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* TMAG5170-Q1 I2C address (A0=A1=0) */
#define TMAG5170_ADDR 0x0E

/* TMAG5170-Q1 register addresses */
#define TMAG5170_REG_DEVICE_ID 0x00
#define TMAG5170_REG_X_MSB 0x01
#define TMAG5170_REG_X_LSB 0x02
#define TMAG5170_REG_Y_MSB 0x03
#define TMAG5170_REG_Y_LSB 0x04
#define TMAG5170_REG_Z_MSB 0x05
#define TMAG5170_REG_Z_LSB 0x06
#define TMAG5170_REG_CONFIG 0x0F

/* Expected device ID for TMAG5170-Q1 */
#define TMAG5170_DEVICE_ID 0x8D

/* Configuration: continuous-conversion mode, 50 mT range, all axes enabled */
#define TMAG5170_CONFIG_50MT 0x0000

/* 50 mT range: 16-bit two's complement, LSB = 0.5 mT */
#define TMAG5170_LSB_50MT 0.5f

/* Sampling interval in microseconds (100 ms) */
#define SAMPLE_INTERVAL_US 100000

/* Global resources for signal-handler cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Write a 16-bit value to a TMAG5170 register (pigpio i2cWriteWordData sends MSB first) */
static int write_register(int handle, uint8_t reg, uint16_t value) {
    int rc = i2cWriteWordData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing register 0x%02X (rc=%d)\n", reg, rc);
    }
    return rc;
}

/* Read a 16-bit value from a TMAG5170 register (pigpio i2cReadWordData returns MSB first) */
static int read_register(int handle, uint8_t reg, uint16_t *value) {
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X (rc=%d)\n", reg, rc);
        return -1;
    }
    *value = (uint16_t)rc;
    return 0;
}

/* Read a signed 16-bit magnetic field axis in mT */
static int read_axis(int handle, uint8_t msb_reg, uint8_t lsb_reg, float *value) {
    uint16_t raw;
    if (read_register(handle, msb_reg, &raw) < 0) return -1;
    uint16_t lsb;
    if (read_register(handle, lsb_reg, &lsb) < 0) return -1;
    int16_t signed_raw = (int16_t)((raw << 8) | lsb);
    *value = (float)signed_raw * TMAG5170_LSB_50MT;
    return 0;
}

/* Log one data row with ISO-8601 timestamp */
static int log_data(FILE *fp, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    if (fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at TMAG5170 address */
    i2c_handle = i2cOpen(1, TMAG5170_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X (rc=%d)\n",
                TMAG5170_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify device ID */
    uint16_t device_id;
    if (read_register(i2c_handle, TMAG5170_REG_DEVICE_ID, &device_id) < 0) {
        fprintf(stderr, "Cannot read device ID - sensor may be absent\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (device_id != TMAG5170_DEVICE_ID) {
        fprintf(stderr, "Unexpected device ID 0x%04X (expected 0x%04X)\n",
                device_id, TMAG5170_DEVICE_ID);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure sensor: continuous mode, 50 mT range, all axes enabled */
    if (write_register(i2c_handle, TMAG5170_REG_CONFIG, TMAG5170_CONFIG_50MT) < 0) {
        fprintf(stderr, "Error configuring TMAG5170\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("magnetic_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,x_mT,y_mT,z_mT\n");
        fflush(log_file);
    }

    /* Register signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering signal handlers\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("TMAG5170 logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (!terminate) {
        float x, y, z;
        if (read_axis(i2c_handle, TMAG5170_REG_X_MSB, TMAG5170_REG_X_LSB, &x) < 0 ||
            read_axis(i2c_handle, TMAG5170_REG_Y_MSB, TMAG5170_REG_Y_LSB, &y) < 0 ||
            read_axis(i2c_handle, TMAG5170_REG_Z_MSB, TMAG5170_REG_Z_LSB, &z) < 0) {
            fprintf(stderr, "Error reading magnetic field data\n");
        } else {
            if (log_data(log_file, x, y, z) < 0) {
                fprintf(stderr, "Error logging data\n");
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

