#define POLL_INTERVAL_SEC 2
#define REINIT_DELAY_SEC 60

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s %s\n", timestamp, message);
    } else {
        fprintf(fp, "[timestamp error] %s\n", message);
    }

    fclose(fp);
    return 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(SENSOR_GPIO, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", SENSOR_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_sensor(void) {
    int value = gpioRead(SENSOR_GPIO);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d\n", SENSOR_GPIO);
        return -1;
    }
    return value;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        log_message("FATAL: GPIO initialization failed");
        return EXIT_FAILURE;
    }

    printf("Water level monitoring started on GPIO %d. Press Ctrl+C to exit.\n", SENSOR_GPIO);

