#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <stdatomic.h>
#include <pigpio.h>

#define SENSOR_PIN 4          /* BCM GPIO 4, physical pin 7 */
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_INTERVAL_US 1000000  /* 1 second */

static atomic_int g_pulse_count = 0;
static FILE *g_log_fp = NULL;
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback — counts rising edges                         */
/* ------------------------------------------------------------------ */
static void pulse_counter(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)tick;
    (void)userdata;

    if (level == 1) {            /* rising edge */
        atomic_fetch_add(&g_pulse_count, 1);
    }
}

/* ------------------------------------------------------------------ */
/* Compute RPM from pulses counted in the last 1-second window         */
/* ------------------------------------------------------------------ */
static double calculate_rpm(int pulses)
{
    return (double)pulses * 60.0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped RPM line to the log file and stdout            */
/* ------------------------------------------------------------------ */
static void log_rpm(double rpm)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (g_log_fp) {
        fprintf(g_log_fp, "%s %.2f\n", ts, rpm);
        fflush(g_log_fp);
    }
    printf("%s %.2f\n", ts, rpm);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call from any exit path                    */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioSetAlertFuncEx(SENSOR_PIN, NULL, NULL);   /* disable callback */
    gpioSetTimerFuncEx(0, 0, NULL, NULL);          /* disable timer   */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen(" LOG_FILE ")");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- configure sensor pin ---- */
    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for pin %d\n", SENSOR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for pin %d\n", SENSOR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- register alert callback ---- */
    if (gpioSetAlertFuncEx(SENSOR_PIN, pulse_counter, NULL) != 0) {
        fprintf(stderr, "gpioSetAlertFuncEx failed for pin %d\n", SENSOR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("RPM monitoring started on BCM GPIO %d. Press Ctrl+C to exit.\n",
           SENSOR_PIN);

    /* ---- main sampling loop ---- */
    while (g_running) {
        gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_US, NULL, NULL);  /* reset timer */

        /* sleep until the timer fires (or interrupted) */
        while (g_running) {
            gpioDelay(10000);  /* 10 ms poll */
            if (gpioGetTimerFuncEx(0, NULL) == 0) break;  /* timer fired */
        }

        if (!g_running) break;

        int pulses = atomic_exchange(&g_pulse_count, 0);
        double rpm = calculate_rpm(pulses);
        log_rpm(rpm);
    }

    /* ---- graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

