#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 27
#define LOG_FILE "rotation_log.txt"

/* Quadrature state machine states */
typedef enum {
    STATE_A_LOW_B_LOW = 0,
    STATE_A_LOW_B_HIGH,
    STATE_A_HIGH_B_LOW,
    STATE_A_HIGH_B_HIGH
} QuadratureState;

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static pthread_mutex_t state_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
static volatile int current_state = STATE_A_LOW_B_LOW;
static volatile int prev_state = STATE_A_LOW_B_LOW;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_rotation(const char *direction) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        return;
    }
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    long milliseconds = ts.tv_nsec / 1000000L;

    pthread_mutex_lock(&log_mutex);
    if (log_file) {
        fprintf(log_file, "%s.%03ld: %s\n", timestamp, milliseconds, direction);
        fflush(log_file);
    }
    pthread_mutex_unlock(&log_mutex);
}

static void sensor_a_isr(int gpio, int level, uint32_t tick) {
    (void)gpio;
    (void)tick;
    int new_state;
    if (level == 1) {
        new_state = STATE_A_LOW_B_LOW;
    } else {
        new_state = STATE_A_HIGH_B_HIGH;
    }

    pthread_mutex_lock(&state_mutex);
    int prev = current_state;
    current_state = new_state;
    pthread_mutex_unlock(&state_mutex);

    if (new_state != prev_state) {
        pthread_mutex_lock(&state_mutex);
        prev_state = current_state;
        pthread_mutex_unlock(&state_mutex);

        if (new_state == STATE_A_LOW_B_LOW) {
            log_rotation("CW");
        } else if (new_state == STATE_A_HIGH_B_HIGH) {
            log_rotation("CCW");
        }
    }
}

static void sensor_b_isr(int gpio, int level, uint32_t tick) {
    (void)gpio;
    (void)tick;
    int new_state;
    if (level == 1) {
        new_state = STATE_A_LOW_B_HIGH;
    } else {
        new_state = STATE_A_HIGH_B_LOW;
    }

    pthread_mutex_lock(&state_mutex);
    int prev = current_state;
    current_state = new_state;
    pthread_mutex_unlock(&state_mutex);

    if (new_state != prev_state) {
        pthread_mutex_lock(&state_mutex);
        prev_state = current_state;
        pthread_mutex_unlock(&state_mutex);

        if (new_state == STATE_A_LOW_B_HIGH) {
            log_rotation("CW");
