    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(SENSOR_A_PIN, sensor_a_isr) != 0) {
        fprintf(stderr, "Failed to set alert for sensor A\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(SENSOR_B_PIN, sensor_b_isr) != 0) {
        fprintf(stderr, "Failed to set alert for sensor B\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_A_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up for sensor A\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_B_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up for sensor B\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction failed");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Rotation detection started. Press Ctrl+C to exit.\n");

    while (running) {
        sleep(1);
    }

    printf("\nShutting down...\n");
    pthread_mutex_lock(&log_mutex);
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    pthread_mutex_unlock(&log_mutex);
    gpioTerminate();
    return EXIT_SUCCESS;
}

