#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define TOUCH_PIN  17
#define LED_PIN    18
#define DEBOUNCE_MS 50

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *touch = NULL;
    struct gpiod_line *led   = NULL;
    int led_state = 0;
    int ret;

    /* Open the default gpiochip (gpiochip0 on RPi 3B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    touch = gpiod_chip_get_line(chip, TOUCH_PIN);
    if (!touch) {
        perror("gpiod_chip_get_line(touch)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    led = gpiod_chip_get_line(chip, LED_PIN);
    if (!led) {
        perror("gpiod_chip_get_line(led)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request touch line as input with rising-edge event detection */
    ret = gpiod_line_request_rising_edge_events(touch, "ttp223b-touch");
    if (ret < 0) {
        perror("gpiod_line_request_rising_edge_events(touch)");
        goto cleanup;
    }

    /* Request LED line as output, initial value LOW */
    ret = gpiod_line_request_output(led, "ttp223b-led", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(led)");
        goto cleanup;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        goto cleanup;
    }

    printf("Touch sensor ready. Touch GPIO %d to toggle LED on GPIO %d.\n", TOUCH_PIN, LED_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        /* Block up to 1 s waiting for a rising edge on the touch line */
        ret = gpiod_line_event_wait(touch, &(struct timespec){1, 0});
        if (ret < 0) {
            if (running) perror("gpiod_line_event_wait");
            break;
        }
        if (ret == 0) {
            /* Timeout, no event — loop back and check running flag */
            continue;
        }

        /* Event detected — read it to confirm */
        ret = gpiod_line_event_read(touch, NULL);
        if (ret < 0) {
            if (running) perror("gpiod_line_event_read");
            continue;
        }

        /* Debounce: wait DEBOUNCE_MS, then re-read to confirm still HIGH */
        usleep(DEBOUNCE_MS * 1000);
        ret = gpiod_line_get_value(touch);
        if (ret < 0) {
            if (running) perror("gpiod_line_get_value(touch)");
            continue;
        }
        if (ret != 1) {
            /* Touch released during debounce — ignore */
            continue;
        }

        /* Toggle LED */
        led_state = !led_state;
        ret = gpiod_line_set_value(led, led_state);
        if (ret < 0) {
            if (running) perror("gpiod_line_set_value(led)");
        } else {
            printf("Touch detected — LED %s\n", led_state ? "ON" : "OFF");
        }
    }

cleanup:
    if (led) {
        gpiod_line_set_value(led, 0);
        gpiod_line_release(led);
    }
    if (touch) gpiod_line_release(touch);
    if (chip)  gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

