#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN   27
#define LED_2_PIN   22

#define BUFFER_SIZE 100
#define POLL_DELAY_US 50000  /* 50 ms */

typedef struct {
    int sensor_pin;
    time_t timestamp;
    int state;  /* 1 = touched, 0 = released */
} Event;

static Event event_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int overflow_count = 0;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(int sensor_pin, int state) {
    event_buffer[buffer_index].sensor_pin = sensor_pin;
    event_buffer[buffer_index].timestamp  = time(NULL);
    event_buffer[buffer_index].state      = state;

    buffer_index++;
    if (buffer_index >= BUFFER_SIZE) {
        buffer_index = 0;
        overflow_count++;
    }
}

static void print_buffer(void) {
    printf("\n--- Event Log (%d entries, %d overflow) ---\n",
           BUFFER_SIZE, overflow_count);
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (buffer_index + i) % BUFFER_SIZE;
        char time_str[32];
        struct tm tm_info;
        if (localtime_r(&event_buffer[idx].timestamp, &tm_info) != NULL) {
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S",
                     &tm_info);
        } else {
            snprintf(time_str, sizeof(time_str), "INVALID");
        }
        printf("  [%d] Pin %d: %s, State: %s\n",
               idx, event_buffer[idx].sensor_pin, time_str,
               event_buffer[idx].state ? "Touched" : "Released");
    }
    printf("--- End of Log ---\n");
}

static int safe_set_mode(unsigned pin, unsigned mode) {
    if (gpioSetMode(pin, mode) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level) {
    if (gpioWrite(pin, level) < 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

static int safe_read(unsigned pin) {
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Error: gpioRead(%u) failed\n", pin);
    }
    return v;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (safe_set_mode(SENSOR_1_PIN, PI_INPUT)  < 0 ||
        safe_set_mode(SENSOR_2_PIN, PI_INPUT)  < 0 ||
        safe_set_mode(LED_1_PIN,   PI_OUTPUT)  < 0 ||
        safe_set_mode(LED_2_PIN,   PI_OUTPUT)  < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (safe_write(LED_1_PIN, 0) < 0 || safe_write(LED_2_PIN, 0) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install signal handlers\n");
    }

    printf("Touch sensor program started. Press Ctrl+C to exit.\n");

    int prev1 = safe_read(SENSOR_1_PIN);
    int prev2 = safe_read(SENSOR_2_PIN);
    if (prev1 < 0 || prev2 < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int cur1 = safe_read(SENSOR_1_PIN);
        int cur2 = safe_read(SENSOR_2_PIN);

        if (cur1 < 0 || cur2 < 0) {
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (cur1 != prev1) {
            log_event(SENSOR_1_PIN, cur1);
            if (safe_write(LED_1_PIN, cur1) < 0) {
                gpioDelay(POLL_DELAY_US);
                continue;
            }
            prev1 = cur1;
        }

        if (cur2 != prev2) {
            log_event(SENSOR_2_PIN, cur2);
            if (safe_write(LED_2_PIN, cur2) < 0) {
                gpioDelay(POLL_DELAY_US);
                continue;
            }
            prev2 = cur2;
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    safe_write(LED_1_PIN, 0);
    safe_write(LED_2_PIN, 0);
    print_buffer();
    gpioTerminate();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

