#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define RAIN_SENSOR_GPIO 17
#define LOG_FILE "/var/log/rain_events.log"
#define POLL_DELAY_US 500000  /* 500 ms */

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (log_fp != NULL) {
        if (fprintf(log_fp, "%s: %s\n", timestamp, message) < 0) {
            fprintf(stderr, "fprintf() to log failed: %s\n", strerror(errno));
        }
        if (fflush(log_fp) != 0) {
            fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        }
    } else {
        fprintf(stderr, "Log file not open; event lost: %s\n", message);
    }
}

int main(void) {
    /* Install signal handlers early so we can clean up even if init fails partway */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO 17 as input with internal pull-up */
    if (gpioSetMode(RAIN_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", RAIN_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(RAIN_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_UP) failed\n", RAIN_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int last_state = gpioRead(RAIN_SENSOR_GPIO);
    if (last_state < 0) {
        fprintf(stderr, "Initial gpioRead(%d) failed\n", RAIN_SENSOR_GPIO);
        fclose(log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event(last_state == 0 ? "Rain Detected" : "No Rain");

    /* Main polling loop */
    while (running) {
        int current_state = gpioRead(RAIN_SENSOR_GPIO);
        if (current_state < 0) {
            fprintf(stderr, "gpioRead(%d) failed\n", RAIN_SENSOR_GPIO);
            break;
        }

        if (current_state != last_state) {
            log_event(current_state == 0 ? "Rain Detected" : "No Rain");
            last_state = current_state;
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Cleanup */
    if (log_fp != NULL) {
        if (fclose(log_fp) != 0) {
            fprintf(stderr, "fclose() failed: %s\n", strerror(errno));
        }
        log_fp = NULL;
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

