#include <errno.h>
#include <unistd.h>

#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18
#define DEBOUNCE_DELAY_US 5000
#define PULSES_PER_REV 2
#define LOG_FILE "shaft_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_data(int s1, int s2) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s,%d,%d\n", ts, s1, s2);
    fflush(log_file);
}

static void pulse_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)tick;
    (void)userdata;
    static int s1_state = 0, s2_state = 0;
    static uint32_t s1_last_tick = 0, s2_last_tick = 0;
    uint32_t now = gpioTick();

    if (level == 1) {
        if (gpio == SENSOR1_GPIO) {
            if (s1_state == 0) {
                s1_state = 1;
                s1_last_tick = now;
            }
        } else if (gpio == SENSOR2_GPIO) {
            if (s2_state == 0) {
                s2_state = 1;
                s2_last_tick = now;
            }
        }
    } else if (level == 0) {
        if (gpio == SENSOR1_GPIO) {
            if (s1_state == 1) {
                s1_state = 0;
                s1_last_tick = now;
            }
        } else if (gpio == SENSOR2_GPIO) {
            if (s2_state == 1) {
                s2_state = 0;
                s2_last_tick = now;
            }
        }
    }

    if (s1_state == 1 && s2_state == 1) {
        uint32_t diff1 = now - s1_last_tick;
        uint32_t diff2 = now - s2_last_tick;
        if (diff1 > DEBOUNCE_DELAY_US && diff2 > DEBOUNCE_DELAY_US) {
            s1_state = 0;
            s2_state = 0;
            log_data(0, 0);
        }
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SENSOR1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR1_GPIO);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SENSOR2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR2_GPIO);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", SENSOR1_GPIO);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", SENSOR2_GPIO);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFuncEx(SENSOR1_GPIO, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert for GPIO %d\n", SENSOR1_GPIO);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    if (gpioSetAlertFuncEx(SENSOR2_GPIO, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert for GPIO %d\n", SENSOR2_GPIO);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Monitoring shaft RPM on GPIO %d and %d. Press Ctrl+C to exit.\n", SENSOR1_GPIO, SENSOR2_GPIO);

    while (running) {
        sleep(1);
    }

    printf("\nShutting down...\n");
    gpioSetAlertFuncEx(SENSOR1_GPIO, NULL, NULL);
    gpioSetAlertFuncEx(SENSOR2_GPIO, NULL, NULL);
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    return 0;
}

