#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>

#define I2C_BUS 1
#define SI1182_ADDR 0x28
#define PART_ID_REG 0x00
#define HR_REG 0x02
#define SPO2_REG 0x04
#define CONFIG_REG 0x30
#define LOG_FILE "biometric_log.txt"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

static int initialize_sensor(int handle) {
    uint8_t part_id = 0;
    if (read_register(handle, PART_ID_REG, &part_id) != 0) {
        fprintf(stderr, "Failed to read PART_ID. Sensor not present?\n");
        return -1;
    }
    printf("Si1182 PART_ID: 0x%02X\n", part_id);

    /* Configure sensor for continuous measurement */
    if (write_register(handle, CONFIG_REG, 0x01) != 0) {
        fprintf(stderr, "Failed to configure sensor\n");
        return -1;
    }
    return 0;
}

static int read_sensor_data(int handle, int *heart_rate, int *spo2) {
    uint8_t hr = 0, spo2_val = 0;

    if (read_register(handle, HR_REG, &hr) != 0) return -1;
    if (read_register(handle, SPO2_REG, &spo2_val) != 0) return -1;

    *heart_rate = (int)hr;
    *spo2 = (int)spo2_val;
    return 0;
}

static void log_data(FILE *fp, int heart_rate, int spo2) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", timestamp, heart_rate, spo2);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (initialize_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    int heart_rate, spo2;
