#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define ALARM_PIN    27
#define POLL_DELAY_US 100000   /* 100 ms */
#define THRESHOLD_SEC 2

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    if (log_file) {
        fprintf(log_file, "%s: %s\n", ts, event);
        fflush(log_file);
    }
    printf("%s: %s\n", ts, event);
}

static void cleanup(void) {
    if (log_file) {
        log_event("Program terminated");
        fclose(log_file);
        log_file = NULL;
    }
    /* Ensure alarm is off before terminating pigpio */
    gpioWrite(ALARM_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen("bridge_integrity.log", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0 ||
        gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0 ||
        gpioSetMode(ALARM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN) != 0 ||
        gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down resistors\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioWrite(ALARM_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize alarm pin LOW\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("Program started");

    int alarm_active = 0;
    time_t alarm_start_time = 0;
    int s1_active = 0, s2_active = 0;

    while (running) {
        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Error reading sensor GPIOs\n");
            break;
        }

        if (s1 == 1 && !s1_active) {
            log_event("Sensor 1 tilted beyond threshold");
            s1_active = 1;
            if (!alarm_active) {
                if (gpioWrite(ALARM_PIN, 1) == 0) {
                    alarm_active = 1;
                    alarm_start_time = time(NULL);
                    log_event("Alarm activated");
                } else {
                    fprintf(stderr, "Failed to activate alarm\n");
                }
            }
        }

        if (s2 == 1 && !s2_active) {
            log_event("Sensor 2 tilted beyond threshold");
            s2_active = 1;
            if (!alarm_active) {
                if (gpioWrite(ALARM_PIN, 1) == 0) {
                    alarm_active = 1;
                    alarm_start_time = time(NULL);
                    log_event("Alarm activated");
                } else {
                    fprintf(stderr, "Failed to activate alarm\n");
                }
            }
        }

        if (s1 == 0 && s1_active) {
            log_event("Sensor 1 returned to normal");
            s1_active = 0;
            if (alarm_active) {
                if (gpioWrite(ALARM_PIN, 0) == 0) {
                    alarm_active = 0;
                    log_event("Alarm deactivated");
                } else {
                    fprintf(stderr, "Failed to deactivate alarm\n");
                }
            }
        }

        if (s2 == 0 && s2_active) {
            log_event("Sensor 2 returned to normal");
            s2_active = 0;
            if (alarm_active) {
                if (gpioWrite(ALARM_PIN, 0) == 0) {
                    alarm_active = 0;
                    log_event("Alarm deactivated");
                } else {
                    fprintf(stderr, "Failed to deactivate alarm\n");
                }
            }
        }

        if (alarm_active) {
            time_t now = time(NULL);
            if (difftime(now, alarm_start_time) > THRESHOLD_SEC) {
                log_event("Threshold exceeded for 2 seconds");
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

