/*
 * Seismic event detector for Raspberry Pi 3 Model B+
 * Sensor : Omron D7S-A0011 (I2C 7-bit address 0x1D)
 * Bus    : /dev/i2c-1 (SDA=GPIO2, SCL=GPIO3)
 * LED    : GPIO 17
 *
 * Build  : gcc -O2 -Wall -o seismic seismic.c -lpigpio -lm -lrt
 * Run    : sudo ./seismic
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define I2C_ADDR             0x1D          /* D7S-A0011 default 7-bit address */
#define LED_GPIO             17
#define VIBRATION_THRESHOLD  500.0f        /* raw units (6-bit resolution) */
#define POLL_INTERVAL_US     100000        /* 100 ms */
#define LED_ON_TIME_US       1000000       /* 1 s */
#define MAX_RETRIES          3
#define LOG_FILE             "seismic_events.log"

/* D7S-A0011 register map (verified against datasheet) */
#define REG_CTRL1            0x1F
#define REG_CTRL2            0x20
#define REG_X_LSB            0x28
#define REG_X_MSB            0x29
#define REG_Y_LSB            0x2A
#define REG_Y_MSB            0x2B
#define REG_Z_LSB            0x2C
#define REG_Z_MSB            0x2D

/* CTRL1: bit 0 = power-down (0 = active) */
#define CTRL1_PD_BIT         0x01

/* ------------------------------- Globals --------------------------------- */
static int      i2c_handle = -1;
static FILE    *log_file   = NULL;
static volatile sig_atomic_t terminate = 0;

/* --------------------------- Forward declarations ------------------------ */
static int  init_sensor(void);
static int  read_acceleration(float *x, float *y, float *z);
static float calculate_vibration_magnitude(float x, float y, float z);
static void trigger_led(int on);
static void log_event(float magnitude);
static void signal_handler(int sig);

/* ------------------------------- Signal handler -------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* --------------------------- Sensor initialization ------------------------ */
static int init_sensor(void)
{
    /* Verify sensor presence by reading CTRL1 */
    int ctrl1 = i2cReadByteData(i2c_handle, REG_CTRL1);
    if (ctrl1 < 0) {
        fprintf(stderr, "[ERROR] Sensor not responding at 0x%02X (read failed: %d)\n",
                I2C_ADDR, ctrl1);
        return -1;
    }

    /* Clear power-down bit so the sensor becomes active */
    if (i2cWriteByteData(i2c_handle, REG_CTRL1, ctrl1 & ~CTRL1_PD_BIT) < 0) {
        fprintf(stderr, "[ERROR] Failed to clear power-down bit\n");
        return -1;
    }

    /* Optional: set CTRL2 to default / recommended values (datasheet) */
    if (i2cWriteByteData(i2c_handle, REG_CTRL2, 0x00) < 0) {
        fprintf(stderr, "[WARN] Failed to write CTRL2\n");
        /* non-fatal */
    }

    return 0;
}

/* --------------------------- Read acceleration ---------------------------- */
static int read_acceleration(float *x, float *y, float *z)
{
    char buf[6];
    int  retries = MAX_RETRIES;

    while (retries > 0) {
        int rc = i2cReadI2CBlockData(i2c_handle, REG_X_LSB, buf, 6);
        if (rc == 6) {
            /* D7S-A0011 outputs little-endian: LSB first, then MSB */
            int16_t raw_x = (int16_t)((uint8_t)buf[1] << 8 | (uint8_t)buf[0]);
            int16_t raw_y = (int16_t)((uint8_t)buf[3] << 8 | (uint8_t)buf[2]);
            int16_t raw_z = (int16_t)((uint8_t)buf[5] << 8 | (uint8_t)buf[4]);

            *x = (float)raw_x;
            *y = (float)raw_y;
            *z = (float)raw_z;
            return 0;
        }
        fprintf(stderr, "[WARN] I2C block read failed (rc=%d), retries left=%d\n",
                rc, retries - 1);
        retries--;
        if (retries > 0)
            gpioDelay(10000);  /* 10 ms back-off */
    }

    fprintf(stderr, "[ERROR] Failed to read acceleration after %d retries\n", MAX_RETRIES);
    return -1;
}

/* --------------------- Vibration magnitude (Euclidean) --------------------- */
static float calculate_vibration_magnitude(float x, float y, float z)
{
    return sqrtf(x * x + y * y + z * z);
}

/* ------------------------------- LED control ------------------------------ */
static void trigger_led(int on)
{
    gpioWrite(LED_GPIO, on ? 1 : 0);
}

/* ------------------------------- Logging --------------------------------- */
static void log_event(float magnitude)
{
    time_t     t;
    struct tm  tm_info;
    char       ts[32];

    time(&t);
    localtime_r(&t, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);

    fprintf(log_file, "%s - Vibration magnitude: %.2f\n", ts, magnitude);
    fflush(log_file);
}

/* --------------------------------- main ---------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_sensor() != 0) {
        fprintf(stderr, "[FATAL] Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (!terminate) {
        float x, y, z;

        if (read_acceleration(&x, &y, &z) == 0) {
            float mag = calculate_vibration_magnitude(x, y, z);
            printf("Vibration magnitude: %.2f\n", mag);

            if (mag > VIBRATION_THRESHOLD) {
                printf("Threshold exceeded! Triggering LED.\n");
                trigger_led(1);
                gpioDelay(LED_ON_TIME_US);
                trigger_led(0);
                log_event(mag);
            }
        } else {
            fprintf(stderr, "[ERROR] Read failure; continuing.\n");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* --------------------------- Cleanup --------------------------------- */
    printf("\nShutting down...\n");
    trigger_led(0);

    if (log_file)  fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

