}

/* --------------------------- Sensor initialization ------------------------ */
static int init_sensor(void)
{
    /* Verify sensor presence by reading CTRL1 */
    int ctrl1 = i2cReadByteData(i2c_handle, REG_CTRL1);
    if (ctrl1 < 0) {
        fprintf(stderr, "[ERROR] Sensor not responding at 0x%02X (read failed: %d)\n",
                I2C_ADDR, ctrl1);
        return -1;
    }

    /* Clear power-down bit so the sensor becomes active */
    if (i2cWriteByteData(i2c_handle, REG_CTRL1, ctrl1 & ~CTRL1_PD_BIT) < 0) {
        fprintf(stderr, "[ERROR] Failed to clear power-down bit\n");
        return -1;
    }

    /* Optional: set CTRL2 to default / recommended values (datasheet) */
    if (i2cWriteByteData(i2c_handle, REG_CTRL2, 0x00) < 0) {
        fprintf(stderr, "[WARN] Failed to write CTRL2\n");
        /* non-fatal */
    }

    return 0;
}

/* --------------------------- Read acceleration ---------------------------- */
static int read_acceleration(float *x, float *y, float *z)
{
    char buf[6];
    int  retries = MAX_RETRIES;

    while (retries > 0) {
        int rc = i2cReadI2CBlockData(i2c_handle, REG_X_LSB, buf, 6);
        if (rc == 6) {
            /* D7S-A0011 outputs little-endian: LSB first, then MSB */
            int16_t raw_x = (int16_t)((uint8_t)buf[1] << 8 | (uint8_t)buf[0]);
            int16_t raw_y = (int16_t)((uint8_t)buf[3] << 8 | (uint8_t)buf[2]);
            int16_t raw_z = (int16_t)((uint8_t)buf[5] << 8 | (uint8_t)buf[4]);

            *x = (float)raw_x;
            *y = (float)raw_y;
            *z = (float)raw_z;
            return 0;
        }
        fprintf(stderr, "[WARN] I2C block read failed (rc=%d), retries left=%d\n",
                rc, retries - 1);
        retries--;
        if (retries > 0)
            gpioDelay(10000);  /* 10 ms back-off */
    }

    fprintf(stderr, "[ERROR] Failed to read acceleration after %d retries\n", MAX_RETRIES);
    return -1;
}

/* --------------------- Vibration magnitude (Euclidean) --------------------- */
static float calculate_vibration_magnitude(float x, float y, float z)
{
    return sqrtf(x * x + y * y + z * z);
}

/* ------------------------------- LED control ------------------------------ */
static void trigger_led(int on)
{
    gpioWrite(LED_GPIO, on ? 1 : 0);
}

/* ------------------------------- Logging --------------------------------- */
static void log_event(float magnitude)
{
    time_t     t;
    struct tm  tm_info;
    char       ts[32];

    time(&t);
    localtime_r(&t, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);

    fprintf(log_file, "%s - Vibration magnitude: %.2f\n", ts, magnitude);
    fflush(log_file);
}

/* --------------------------------- main ---------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_sensor() != 0) {
        fprintf(stderr, "[FATAL] Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (!terminate) {
        float x, y, z;

        if (read_acceleration(&x, &y, &z) == 0) {
            float mag = calculate_vibration_magnitude(x, y, z);
            printf("Vibration magnitude: %.2f\n", mag);

            if (mag > VIBRATION_THRESHOLD) {
                printf("Threshold exceeded! Triggering LED.\n");
                trigger_led(1);
                gpioDelay(LED_ON_TIME_US);
                trigger_led(0);
                log_event(mag);
            }
        } else {
            fprintf(stderr, "[ERROR] Read failure; continuing.\n");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* --------------------------- Cleanup --------------------------------- */
    printf("\nShutting down...\n");
    trigger_led(0);

    if (log_file)  fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

