#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27
#define SENSOR4_PIN 22
#define LED_PIN    18
#define POLL_MS    50

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *s1 = NULL, *s2 = NULL, *s3 = NULL, *s4 = NULL;
    struct gpiod_line *led = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    s1 = gpiod_chip_get_line(chip, SENSOR1_PIN);
    s2 = gpiod_chip_get_line(chip, SENSOR2_PIN);
    s3 = gpiod_chip_get_line(chip, SENSOR3_PIN);
    s4 = gpiod_chip_get_line(chip, SENSOR4_PIN);
    led = gpiod_chip_get_line(chip, LED_PIN);
    if (!s1 || !s2 || !s3 || !s4 || !led) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_input(s1, "ky032-s1") < 0 ||
        gpiod_line_request_input(s2, "ky032-s2") < 0 ||
        gpiod_line_request_input(s3, "ky032-s3") < 0 ||
        gpiod_line_request_input(s4, "ky032-s4") < 0) {
        perror("gpiod_line_request_input");
        goto cleanup;
    }

    if (gpiod_line_request_output(led, "ky032-led", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    while (running) {
        int v1 = gpiod_line_get_value(s1);
        int v2 = gpiod_line_get_value(s2);
        int v3 = gpiod_line_get_value(s3);
        int v4 = gpiod_line_get_value(s4);

        if (v1 < 0 || v2 < 0 || v3 < 0 || v4 < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        int any = (v1 == 0 || v2 == 0 || v3 == 0 || v4 == 0) ? 1 : 0;

        if (gpiod_line_set_value(led, any) < 0) {
            perror("gpiod_line_set_value");
            break;
        }

        usleep(POLL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led) gpiod_line_release(led);
    if (s1) gpiod_line_release(s1);
    if (s2) gpiod_line_release(s2);
    if (s3) gpiod_line_release(s3);
    if (s4) gpiod_line_release(s4);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

