/*
 * flame_monitor.c - KY-026 flame sensor monitor using libgpiod
 *
 * Build:  gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lgpiod
 * Run:    sudo ./flame_monitor
 *
 * Hardware (Raspberry Pi 3 Model B+):
 *   5x Keyes KY-026 flame sensors, digital OUT -> BCM GPIO 2, 3, 4, 17, 27
 *   VCC -> 3.3 V, GND -> GND
 *   (LOW = flame detected, HIGH = no flame)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/file.h>
#include <syslog.h>
#include <gpiod.h>

#define NUM_SENSORS      5
#define DEBOUNCE_MS      50
#define POLL_INTERVAL_S  1
#define LOG_FILE         "/var/log/flame_events.log"
#define CHIP_NAME        "gpiochip0"

static const unsigned int sensor_pins[NUM_SENSORS] = {2, 3, 4, 17, 27};

static volatile sig_atomic_t program_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(int sensor_id, unsigned int pin)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        syslog(LOG_ERR, "fopen(%s): %s", LOG_FILE, strerror(errno));
        return;
    }

    int fd = fileno(fp);
    if (flock(fd, LOCK_EX) == -1) {
        syslog(LOG_ERR, "flock(LOCK_EX): %s", strerror(errno));
        fclose(fp);
        return;
    }

    time_t now = time(NULL);
    struct tm tm_utc;
    char ts[32];
    if (gmtime_r(&now, &tm_utc) != NULL &&
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) > 0) {
        if (fprintf(fp, "%s - Sensor ID: %d (GPIO %u) - Flame Detected\n",
                    ts, sensor_id, pin) < 0) {
            syslog(LOG_ERR, "fprintf: %s", strerror(errno));
        }
    } else {
        syslog(LOG_ERR, "gmtime_r/strftime failed");
    }

    if (fflush(fp) != 0) {
        syslog(LOG_ERR, "fflush: %s", strerror(errno));
    }

    if (flock(fd, LOCK_UN) == -1) {
        syslog(LOG_ERR, "flock(LOCK_UN): %s", strerror(errno));
    }

    if (fclose(fp) != 0) {
        syslog(LOG_ERR, "fclose: %s", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_SENSORS];
    int prev_state[NUM_SENSORS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = NULL;
        prev_state[i] = 1;  /* assume no flame at startup */
    }

    /* ---- signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGINT): %s", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGTERM): %s", strerror(errno));
        goto cleanup;
    }

    /* ---- open syslog ---- */
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting flame sensor monitor (libgpiod)");

    /* ---- open GPIO chip ---- */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        syslog(LOG_ERR, "gpiod_chip_open_by_name(%s): %s",
               CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    /* ---- acquire lines ---- */
    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!lines[i]) {
            syslog(LOG_ERR, "gpiod_chip_get_line(%u): %s",
                   sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* Request each line as input (active-high, no pull-up needed). */
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (gpiod_line_request_input(lines[i], "flame_monitor") < 0) {
            syslog(LOG_ERR, "gpiod_line_request_input(%u): %s",
                   sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    syslog(LOG_INFO, "Monitoring %d flame sensors on GPIO %u, %u, %u, %u, %u",
           NUM_SENSORS, sensor_pins[0], sensor_pins[1], sensor_pins[2],
           sensor_pins[3], sensor_pins[4]);

    /* ---- main poll loop ---- */
    while (program_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                syslog(LOG_ERR, "gpiod_line_get_value(%u): %s",
                       sensor_pins[i], strerror(errno));
                continue;  /* skip this sensor on read error */
            }

            /* Rising edge: LOW (0) means flame detected */
            if (val == 0 && prev_state[i] == 1) {
                /* Debounce: re-read after 50 ms */
                usleep(DEBOUNCE_MS * 1000);
                int debounced = gpiod_line_get_value(lines[i]);
                if (debounced < 0) {
                    syslog(LOG_ERR, "debounce read on GPIO %u: %s",
                           sensor_pins[i], strerror(errno));
                    continue;
                }
                if (debounced == 0) {
                    log_event(i, sensor_pins[i]);
                }
            }
            prev_state[i] = val;
        }
        sleep(POLL_INTERVAL_S);
    }

    syslog(LOG_INFO, "Shutting down flame sensor monitor");
    ret = EXIT_SUCCESS;

cleanup:
    /* Release all lines we acquired */
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    closelog();
    return ret;
}

