                    log_event(i, sensor_pins[i]);
                }
            }
            prev_state[i] = val;
        }
        sleep(POLL_INTERVAL_S);
    }

    syslog(LOG_INFO, "Shutting down flame sensor monitor");
    ret = EXIT_SUCCESS;

cleanup:
    /* Release all lines we acquired */
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    closelog();
    return ret;
}

