#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x10
#define LED_GPIO       18
#define PWM_FREQ       1000
#define PWM_RANGE      100
#define LOG_FILE       "grow_log.txt"

#define REG_ALS_CONF   0x00
#define REG_ALS_DATA   0x04

#define LUX_THRESHOLD_1 100.0f
#define LUX_THRESHOLD_2 500.0f
#define LUX_THRESHOLD_3 1000.0f

#define ERROR_NONE     0
#define ERROR_I2C      1
#define ERROR_CONFIG   2
#define ERROR_READ     3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int veml7700_write_config(int handle, uint8_t low, uint8_t high) {
    uint16_t value = (uint16_t)((high << 8) | low);
    int rc = i2cWriteWordData(handle, REG_ALS_CONF, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing config register: %d\n", rc);
        return -1;
    }
    return 0;
}

static int veml7700_read_lux(int handle, float *lux_out) {
    int raw = i2cReadWordData(handle, REG_ALS_DATA);
    if (raw < 0) {
        fprintf(stderr, "Error reading ALS data: %d\n", raw);
        return ERROR_READ;
    }
    uint16_t raw_u = (uint16_t)raw;
    *lux_out = (float)raw_u * 0.0576f;
    return ERROR_NONE;
}

static int calculate_brightness(float lux) {
    if (lux < LUX_THRESHOLD_1) return 100;
    if (lux < LUX_THRESHOLD_2) return 75;
    if (lux < LUX_THRESHOLD_3) return 50;
    return 25;
}

static int log_data(FILE *fp, float lux, int brightness, int error_code) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    if (fprintf(fp, "%s,%.2f,%d,%d\n", timestamp, lux, brightness, error_code) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioPWM(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n", I2C_BUS, I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (veml7700_write_config(i2c_handle, 0x00, 0x00) != 0) {
        fprintf(stderr, "Error configuring VEML7700\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQ);
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handlers\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Grow light system started. Logging to %s\n", LOG_FILE);

    while (running) {
        float lux = 0.0f;
        int error_code = ERROR_NONE;

        int rc = veml7700_read_lux(i2c_handle, &lux);
        if (rc != ERROR_NONE) {
            error_code = rc;
            lux = -1.0f;
        }

        int brightness = calculate_brightness(lux);

        if (gpioPWM(LED_GPIO, brightness) != 0) {
            fprintf(stderr, "Error setting PWM on GPIO %d\n", LED_GPIO);
            error_code = ERROR_READ;
        }

        if (log_data(log_file, lux, brightness, error_code) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

