#include <unistd.h>
#include <pigpio.h>

#define OPT3001_ADDR        0x44
#define OPT3001_RESULT_REG  0x00
#define OPT3001_CONFIG_REG  0x01
#define OPT3001_CONFIG_WORD 0xC810  /* Continuous, auto-range, 100 ms */
#define I2C_BUS             1
#define LOG_FILE            "light_data.txt"
#define SAMPLE_INTERVAL_US  1000000  /* 1 second */
#define CONV_WAIT_US        100000   /* 100 ms for first conversion */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Swap bytes: OPT3001 is big-endian, pigpio i2cReadWordData/i2cWriteWordData
 * are little-endian on the wire. */
static uint16_t swap16(uint16_t v)
{
    return (uint16_t)((v >> 8) | (v << 8));
}

static int opt3001_write_config(int handle)
{
    uint16_t config = swap16(OPT3001_CONFIG_WORD);
    int rc = i2cWriteWordData(handle, OPT3001_CONFIG_REG, config);
    if (rc < 0) {
        fprintf(stderr, "Error writing OPT3001 config register: %d\n", rc);
        return -1;
    }
    return 0;
}

static int opt3001_read_lux(int handle, float *lux_out)
{
    int rc = i2cReadWordData(handle, OPT3001_RESULT_REG);
    if (rc < 0) {
        fprintf(stderr, "Error reading OPT3001 result register: %d\n", rc);
        return -1;
    }

    uint16_t raw = swap16((uint16_t)rc);
    uint16_t exponent = (raw >> 12) & 0x0F;
    uint16_t mantissa = raw & 0x0FFF;
    *lux_out = (float)mantissa * 0.01f * (float)(1u << exponent);
    return 0;
}

static int log_data(float lux)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r failed");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, %.2f\n", timestamp, lux) < 0) {
        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("Error flushing log file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT) failed");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, OPT3001_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (opt3001_write_config(g_i2c_handle) != 0) {
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Wait for first conversion to complete */
    gpioDelay(CONV_WAIT_US);

    while (g_running) {
        float lux = 0.0f;

        if (opt3001_read_lux(g_i2c_handle, &lux) == 0) {
            if (log_data(lux) != 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
            printf("Lux: %.2f\n", lux);
        } else {
            fprintf(stderr, "Sensor read failed; skipping iteration\n");
        }

        /* Sleep in small increments so SIGINT is caught promptly */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

