    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioWrite(ALERT_GPIO, 0);
        gpioTerminate();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int sensor_value = gpioRead(FLAME_SENSOR_GPIO);
        if (sensor_value < 0) {
            fprintf(stderr, "Failed to read flame sensor GPIO %d\n", FLAME_SENSOR_GPIO);
            if (log_event("ERROR: Failed to read flame sensor") != 0) {
                fprintf(stderr, "Failed to log read error\n");
