        if (sensor_value == 0) {
            printf("Flame detected!\n");
            if (log_event("Flame detected") != 0) {
                fprintf(stderr, "Failed to log flame detection\n");
            }
            if (trigger_alert() != 0) {
                fprintf(stderr, "Alert trigger failed\n");
            }
        } else {
            printf("No flame detected\n");
            if (log_event("No flame detected") != 0) {
                fprintf(stderr, "Failed to log no-flame event\n");
            }
        }

        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    if (log_event("Program terminated") != 0) {
        fprintf(stderr, "Failed to log termination\n");
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(ALERT_GPIO, 0);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return 0;
}

