#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x08
#define FLOW_CMD_MSB   0x36
#define FLOW_CMD_LSB   0x08
#define FLOW_SCALE     90.0f
#define FLOW_MIN       0.0f
#define FLOW_MAX       100.0f
#define LOG_FILE       "cooling_log.csv"
#define SAMPLE_US      1000000
#define STARTUP_US     2000

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int init_i2c(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static int start_continuous_measurement(void)
{
    uint8_t cmd[2] = { FLOW_CMD_MSB, FLOW_CMD_LSB };
    int rc = i2cWriteDevice(g_i2c_handle, (char *)cmd, 2);
    if (rc < 0) {
        fprintf(stderr, "Error sending continuous measurement command: %d\n", rc);
        return -1;
    }
    gpioDelay(STARTUP_US);
    return 0;
}

static int read_flow_rate(float *flow_rate, uint16_t *raw_flags)
{
    uint8_t buf[3];
    int rc = i2cReadDevice(g_i2c_handle, (char *)buf, 3);
    if (rc != 3) {
        fprintf(stderr, "I2C read failed: expected 3 bytes, got %d\n", rc);
        return -1;
    }
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on flow data\n");
        return -1;
    }
    uint16_t raw = (uint16_t)((buf[0] << 8) | buf[1]);
    *raw_flags = raw;
    *flow_rate = (float)raw / FLOW_SCALE;
    return 0;
}

static void log_data(float flow_rate, uint16_t raw_flags, const char *status)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(g_log_file, "%s,%.2f,0x%04X,%s\n", ts, flow_rate, raw_flags, status);
    fflush(g_log_file);
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "Timestamp,Flow Rate (ml/min),Status\n");
        fflush(g_log_file);
    }

    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }
    if (start_continuous_measurement() != 0) {
        cleanup();
        return 1;
    }

    while (g_running) {
        float flow_rate = 0.0f;
        uint16_t raw_flags = 0;
        int rc = read_flow_rate(&flow_rate, &raw_flags);

        if (rc != 0) {
            fprintf(stderr, "Read error, re-initializing I2C...\n");
            if (init_i2c() != 0) {
                fprintf(stderr, "Re-init failed, exiting.\n");
                break;
            }
            if (start_continuous_measurement() != 0) {
                fprintf(stderr, "Re-start failed, exiting.\n");
                break;
            }
            continue;
        }

        if (flow_rate < FLOW_MIN || flow_rate > FLOW_MAX) {
            fprintf(stderr, "Flow out of range: %.2f ml/min\n", flow_rate);
            log_data(flow_rate, raw_flags, "INVALID");
        } else {
            log_data(flow_rate, raw_flags, "OK");
        }

        gpioDelay(SAMPLE_US);
    }

    cleanup();
    return 0;
}

