#include <gpiod.h>

#define GPIO_LEFT   17
#define GPIO_MIDDLE 27
#define GPIO_RIGHT  22
#define CHIP_NAME   "gpiochip0"
#define LOG_FILE    "path_log.csv"
#define POLL_MS     50

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
