    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    lines[0] = gpiod_chip_get_line(chip, GPIO_LEFT);
    lines[1] = gpiod_chip_get_line(chip, GPIO_MIDDLE);
    lines[2] = gpiod_chip_get_line(chip, GPIO_RIGHT);
    if (lines[0] == NULL || lines[1] == NULL || lines[2] == NULL) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    for (int i = 0; i < 3; i++) {
        if (gpiod_line_request_input(lines[i], "ky033_sensor") != 0) {
            fprintf(stderr, "Failed to request line %d as input: %s\n",
                    gpiod_line_offset(lines[i]), strerror(errno));
            goto cleanup;
        }
