        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    while (g_running) {
        int left   = gpiod_line_get_value(lines[0]);
        int middle = gpiod_line_get_value(lines[1]);
        int right  = gpiod_line_get_value(lines[2]);

        if (left < 0 || middle < 0 || right < 0) {
            fprintf(stderr, "Error reading GPIO values: %s\n", strerror(errno));
            break;
        }

        if (log_data(fp, left, middle, right) != 0) {
            fprintf(stderr, "Error logging data\n");
            break;
        }

        usleep(POLL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        fflush(fp);
        fclose(fp);
    }
    for (int i = 0; i < 3; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

