/*
 * Flame detection safety system for Raspberry Pi 3 Model B+
 * Sensor : Keyes KY-026 flame sensor (digital output, active-low)
 * Wiring : KY-026 DO  -> GPIO17 (physical pin 11)
 *          Buzzer     -> GPIO18 (physical pin 12)
 *          KY-026 VCC -> 3.3 V, GND -> GND
 *          Buzzer +  -> 3.3 V, - -> GPIO18
 *
 * Build : gcc -Wall -Wextra -O2 -o flame_alert flame_alert.c -lgpiod
 */

#include <errno.h>
#include <gpiod.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#define FLAME_PIN  17
#define BUZZER_PIN 18
#define LOG_FILE   "alert_log.txt"
#define POLL_MS    500
#define BUZZER_MS  2000
#define STEP_MS    100

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void log_event(FILE *logf, const char *msg)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }
    if (fprintf(logf, "[%s] %s\n", ts, msg) < 0)
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
    if (fflush(logf) != 0)
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *flame = NULL;
    struct gpiod_line *buzzer = NULL;
    FILE *logf = NULL;
    int prev = 1;          /* assume no flame at startup (active-low) */
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    logf = fopen(LOG_FILE, "a");
    if (!logf) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }
    log_event(logf, "System started");

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name: %s\n", strerror(errno));
        goto cleanup;
    }

    flame = gpiod_chip_get_line(chip, FLAME_PIN);
    if (!flame) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", FLAME_PIN, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(flame, "flame_alert") != 0) {
        fprintf(stderr, "gpiod_line_request_input(%d): %s\n", FLAME_PIN, strerror(errno));
        goto cleanup;
    }

    buzzer = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", BUZZER_PIN, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(buzzer, "flame_alert", 0) != 0) {
        fprintf(stderr, "gpiod_line_request_output(%d): %s\n", BUZZER_PIN, strerror(errno));
        goto cleanup;
    }

    log_event(logf, "GPIO initialized");

    while (g_running) {
