        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", FLAME_PIN, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(flame, "flame_alert") != 0) {
        fprintf(stderr, "gpiod_line_request_input(%d): %s\n", FLAME_PIN, strerror(errno));
        goto cleanup;
    }

    buzzer = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", BUZZER_PIN, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(buzzer, "flame_alert", 0) != 0) {
        fprintf(stderr, "gpiod_line_request_output(%d): %s\n", BUZZER_PIN, strerror(errno));
        goto cleanup;
    }

    log_event(logf, "GPIO initialized");

    while (g_running) {
        int v = gpiod_line_get_value(flame);
        if (v < 0) {
            fprintf(stderr, "gpiod_line_get_value: %s\n", strerror(errno));
            break;
