            if (gpiod_line_set_value(buzzer, 1) != 0)
                fprintf(stderr, "buzzer ON: %s\n", strerror(errno));
            for (int i = 0; i < BUZZER_MS && g_running; i += STEP_MS)
                usleep(STEP_MS * 1000);
            if (gpiod_line_set_value(buzzer, 0) != 0)
                fprintf(stderr, "buzzer OFF: %s\n", strerror(errno));
        }
        prev = v;
        for (int i = 0; i < POLL_MS && g_running; i += STEP_MS)
            usleep(STEP_MS * 1000);
    }

    log_event(logf, "System stopped");
