#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define TOUCH_SENSOR_PIN 4
#define LED_PIN 17
#define LOG_FILE "touch_log.txt"
#define POLL_DELAY_US 10000   /* 10 ms */
#define DEBOUNCE_DELAY_US 200000 /* 200 ms */

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", LED_PIN);
        gpioTerminate();
        return -1;
    }

    /* Start with LED off */
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED state on GPIO%d\n", LED_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void log_touch_event(void) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (gmtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Warning: gmtime_r failed; logging without timestamp\n");
        fprintf(log_file, "UNKNOWN_TIME: Touch detected\n");
    } else {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &timeinfo);
        fprintf(log_file, "%s: Touch detected\n", timestamp);
    }
    fflush(log_file);
}

int main(void) {
    int last_touch_state = 0;
    int led_state = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGTERM handler: %s\n", strerror(errno));
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioWrite(LED_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int touch_state = gpioRead(TOUCH_SENSOR_PIN);
        if (touch_state < 0) {
            fprintf(stderr, "Error: failed to read GPIO%d\n", TOUCH_SENSOR_PIN);
            break;
        }

        /* Detect rising edge: LOW -> HIGH */
        if (touch_state == 1 && last_touch_state == 0) {
            led_state = !led_state;
            if (gpioWrite(LED_PIN, led_state) != 0) {
                fprintf(stderr, "Error: failed to write GPIO%d\n", LED_PIN);
                break;
            }
            log_touch_event();
            gpioDelay(DEBOUNCE_DELAY_US);
        }

        last_touch_state = touch_state;
        gpioDelay(POLL_DELAY_US);
    }

    /* Cleanup */
    gpioWrite(LED_PIN, 0);
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();

    printf("Touch sensor monitoring stopped.\n");
    return EXIT_SUCCESS;
}

