#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI1182_ADDR 0x4A

#define REG_PART_ID 0x00
#define REG_HW_REV 0x01
#define REG_LED_CURRENT 0x3F
#define REG_AVG 0x04
#define REG_ENABLE 0x01
#define REG_HR_DATA 0x2A

#define EXPECTED_PART_ID 0x02
#define EXPECTED_HW_REV 0x01

#define MIN_BPM 30
#define MAX_BPM 220
#define MOVING_AVG_SIZE 5
#define SAMPLE_DELAY_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static int heart_rate_data[MOVING_AVG_SIZE];
static int data_index = 0;
static int samples_collected = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        return -1;
    }
