/*
 * touch_counter.c — Raspberry Pi Zero W
 *
 * Reads an 8-channel TTP226 capacitive touch sensor (active-high, 3.3 V) on
 * GPIO 5..12 (BCM) and displays an 8-bit binary counter on GPIO 17..24.
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_counter touch_counter.c -lgpiod
 * Run:    sudo ./touch_counter   (or ensure user has gpio access)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <gpiod.h>

#define NUM_CHANNELS 8
#define NUM_DISPLAY_BITS 8
#define POLL_INTERVAL_US 10000   /* 10 ms */
#define STABILIZE_DELAY_US 200000 /* 200 ms */

/* Sensor input lines (BCM) */
static const unsigned int sensor_lines[NUM_CHANNELS] = {5, 6, 7, 8, 9, 10, 11, 12};

/* Display output lines (BCM) */
static const unsigned int display_lines[NUM_DISPLAY_BITS] = {17, 18, 19, 20, 21, 22, 23, 24};

/* libgpiod resources */
static struct gpiod_chip *chip = NULL;
static struct gpiod_line_request *sensor_req = NULL;
static struct gpiod_line_request *display_req = NULL;

/* Previous sensor states for edge detection */
static int prev_state[NUM_CHANNELS];

/* Volatile flag for signal-driven shutdown */
static volatile sig_atomic_t shutdown_requested = 0;

/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    shutdown_requested = 1;
}

static void cleanup(void)
{
    /* Reset all display outputs to 0 */
    if (display_req) {
        for (int i = 0; i < NUM_DISPLAY_BITS; i++) {
            enum gpiod_line_value v = gpiod_line_request_set_value(
                display_req, display_lines[i], GPIOD_LINE_VALUE_INACTIVE);
            if (v != GPIOD_LINE_VALUE_INACTIVE) {
                fprintf(stderr, "Warning: failed to reset display line %u: %s\n",
                        display_lines[i], strerror(errno));
            }
        }
    }

    /* Release all requests */
    if (sensor_req) {
        gpiod_line_request_release(sensor_req);
        sensor_req = NULL;
    }
    if (display_req) {
        gpiod_line_request_release(display_req);
        display_req = NULL;
    }

    /* Close chip */
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static void log_touch_event(int channel, int counter_value)
{
    FILE *fp = fopen("touch_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open touch_log.txt: %s\n",
                strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm);
        fprintf(fp, "%s, Channel: %d, Counter: %d\n", ts, channel, counter_value);
    } else {
        fprintf(fp, "(no-time), Channel: %d, Counter: %d\n", channel, counter_value);
    }

    fclose(fp);
}

static void print_touch_event(int channel, int counter_value)
{
    printf("Touch on channel %d | Counter: %d\n", channel, counter_value);
    fflush(stdout);
}

/*
 * Request all sensor lines as inputs.
 * Returns 0 on success, -1 on failure.
 */
static int request_sensor_lines(void)
{
    struct gpiod_line_settings *settings = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_request_config *req_cfg = NULL;
    int ret = -1;

    settings = gpiod_line_settings_new();
    if (!settings) {
        fprintf(stderr, "Failed to create line settings: %s\n", strerror(errno));
        goto out;
    }

    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);

    line_cfg = gpiod_line_config_new();
    if (!line_cfg) {
        fprintf(stderr, "Failed to create line config: %s\n", strerror(errno));
        goto out;
    }

    if (gpiod_line_config_add_line_settings(line_cfg, sensor_lines, NUM_CHANNELS, settings) != 0) {
        fprintf(stderr, "Failed to add sensor line settings: %s\n", strerror(errno));
        goto out;
    }

    req_cfg = gpiod_request_config_new();
    if (!req_cfg) {
        fprintf(stderr, "Failed to create request config: %s\n", strerror(errno));
        goto out;
    }
    gpiod_request_config_set_consumer(req_cfg, "ttp226-sensor");

    sensor_req = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (!sensor_req) {
        fprintf(stderr, "Failed to request sensor lines: %s\n", strerror(errno));
        goto out;
    }

    ret = 0;

out:
    if (req_cfg)
        gpiod_request_config_free(req_cfg);
