#define GPIO_18 18
#define LOG_FILE "/var/log/tilt_events.log"
#define POLL_INTERVAL_US 100000
#define DEBOUNCE_MS 50

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_event(FILE *log_fp, int sensor_id) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_fp, "%s, Sensor %d tilted\n", timestamp, sensor_id) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line17 = NULL;
    struct gpiod_line *line18 = NULL;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_17, strerror(errno));
        goto cleanup;
    }

    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line18) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_18, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input_flags(line17, "tilt-monitor",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Failed to request line %d as input: %s\n",
                GPIO_17, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input_flags(line18, "tilt-monitor",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Failed to request line %d as input: %s\n",
                GPIO_18, strerror(errno));
        goto cleanup;
    }

    printf("Monitoring tilt sensors on GPIO %d and %d. Press Ctrl+C to exit.\n",
           GPIO_17, GPIO_18);

    int prev17 = gpiod_line_get_value(line17);
    int prev18 = gpiod_line_get_value(line18);
    if (prev17 < 0 || prev18 < 0) {
        fprintf(stderr, "Initial read failed: %s\n", strerror(errno));
        goto cleanup;
    }

    struct timespec last_event17 = {0, 0};
    struct timespec last_event18 = {0, 0};

    while (program_running) {
        int val17 = gpiod_line_get_value(line17);
        int val18 = gpiod_line_get_value(line18);

        if (val17 < 0) {
            fprintf(stderr, "Read error on GPIO %d: %s\n", GPIO_17, strerror(errno));
            usleep(POLL_INTERVAL_US);
            continue;
        }

        if (val18 < 0) {
            fprintf(stderr, "Read error on GPIO %d: %s\n", GPIO_18, strerror(errno));
            usleep(POLL_INTERVAL_US);
            continue;
        }

        if (val17 == 0 && prev17 == 1) {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            long elapsed_ms = (now.tv_sec - last_event17.tv_sec) * 1000L +
                              (now.tv_nsec - last_event17.tv_nsec) / 1000000L;

            if (elapsed_ms >= DEBOUNCE_MS) {
                if (log_event(log_fp, 1) == 0) {
                    printf("Event logged for sensor 1\n");
                }
                last_event17 = now;
            }
        }

        if (val18 == 0 && prev18 == 1) {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            long elapsed_ms = (now.tv_sec - last_event18.tv_sec) * 1000L +
                              (now.tv_nsec - last_event18.tv_nsec) / 1000000L;

            if (elapsed_ms >= DEBOUNCE_MS) {
                if (log_event(log_fp, 2) == 0) {
                    printf("Event logged for sensor 2\n");
                }
                last_event18 = now;
            }
        }

        prev17 = val17;
        prev18 = val18;

        usleep(POLL_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (line17) gpiod_line_release(line17);
    if (line18) gpiod_line_release(line18);
    if (chip) gpiod_chip_close(chip);
    if (log_fp) fclose(log_fp);

    return ret;
}

