#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define LEFT_SENSOR_PIN 17
#define CENTER_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *left_line = NULL;
    struct gpiod_line *center_line = NULL;
    struct gpiod_line *right_line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi 4) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get lines for the sensor pins */
    left_line = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    if (!left_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LEFT_SENSOR_PIN, strerror(errno));
        goto cleanup;
    }
    center_line = gpiod_chip_get_line(chip, CENTER_SENSOR_PIN);
    if (!center_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", CENTER_SENSOR_PIN, strerror(errno));
        goto cleanup;
    }
    right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);
    if (!right_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", RIGHT_SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request all three lines as inputs with pull-up and active-low configuration */
    struct gpiod_line_request_config config = {
        .consumer = "sunfounder-tracing-sensor",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
        .flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP | GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW
    };

    if (gpiod_line_request(left_line, &config, 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d: %s\n", LEFT_SENSOR_PIN, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request(center_line, &config, 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d: %s\n", CENTER_SENSOR_PIN, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request(right_line, &config, 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d: %s\n", RIGHT_SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    printf("SunFounder 3-Way Tracing Sensor Reader (libgpiod)\n");
    printf("Pins: Left=GPIO%d, Center=GPIO%d, Right=GPIO%d\n", LEFT_SENSOR_PIN, CENTER_SENSOR_PIN, RIGHT_SENSOR_PIN);
    printf("Press Ctrl+C to exit.\n\n");

    /* Main polling loop */
    while (program_running) {
        int left_val = gpiod_line_get_value(left_line);
        int center_val = gpiod_line_get_value(center_line);
        int right_val = gpiod_line_get_value(right_line);

        if (left_val < 0 || center_val < 0 || right_val < 0) {
            fprintf(stderr, "Error reading sensor values: %s\n", strerror(errno));
            /* Brief pause to avoid tight error loop on persistent read failures */
            usleep(100000);
            continue;
        }

        /* Convert active-low digital values to human-readable state strings */
        const char *left_state = (left_val == 0) ? "Tracing" : "Not Tracing";
        const char *center_state = (center_val == 0) ? "Tracing" : "Not Tracing";
        const char *right_state = (right_val == 0) ? "Tracing" : "Not Tracing";

        printf("Left: [%-8s] Center: [%-8s] Right: [%-8s]\n", left_state, center_state, right_state);
        fflush(stdout);

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (left_line) gpiod_line_release(left_line);
    if (center_line) gpiod_line_release(center_line);
    if (right_line) gpiod_line_release(right_line);
    if (chip) gpiod_chip_close(chip);

    return ret;
}

