#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define LEFT_PIN      2
#define MIDDLE_PIN    3
#define RIGHT_PIN     4
#define POLL_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3];
    const unsigned int offsets[3] = { LEFT_PIN, MIDDLE_PIN, RIGHT_PIN };
    int values[3];
    int ret;

    /* Install signal handler for SIGINT (Ctrl+C) */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire and configure each line individually for maximum portability */
    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, offsets[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to get line %u: %s\n", offsets[i], strerror(errno));
            goto cleanup;
        }

        ret = gpiod_line_request_input(lines[i], "keywish-tracker");
        if (ret < 0) {
            fprintf(stderr, "Failed to request line %u as input: %s\n",
                    offsets[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("Keywish 3-Way Tracking Sensor Reader\n");
    printf("Pins: L=%u M=%u R=%u  |  Poll interval: %d ms\n",
           LEFT_PIN, MIDDLE_PIN, RIGHT_PIN, POLL_INTERVAL_US / 1000);
    printf("Press Ctrl+C to exit.\n\n");

    /* Main polling loop */
