 *
 * Wiring (Raspberry Pi 3 Model B+):
 *   TTP226 TP1 -> BCM GPIO 5
 *   TTP226 TP2 -> BCM GPIO 6
 *   TTP226 TP3 -> BCM GPIO 13
 *   TTP226 TP4 -> BCM GPIO 19
 *   TTP226 TP5 -> BCM GPIO 26
 *   TTP226 TP6 -> BCM GPIO 12
 *   TTP226 TP7 -> BCM GPIO 16
 *   TTP226 TP8 -> BCM GPIO 20
 *
 * Compile:
 *   gcc -O2 -Wall -Wextra -o ttp226_reader ttp226_reader.c -lgpiod
 *
 * Run:
 *   ./ttp226_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 200

static const unsigned int channel_pins[NUM_CHANNELS] = {
    5, 6, 13, 19, 26, 12, 16, 20
};

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void print_timestamp(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) == 0) {
        printf("[%ld.%03ld] ", (long)ts.tv_sec, ts.tv_nsec / 1000000L);
    } else {
        printf("[?time?] ");
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int i;
    int ret = EXIT_FAILURE;

    for (i = 0; i < NUM_CHANNELS; i++)
        lines[i] = NULL;

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on RPi 3B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get and request each line as input */
    for (i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, channel_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to get line for BCM GPIO %u: %s\n",
                    channel_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(lines[i], "ttp226-reader") < 0) {
            fprintf(stderr, "Failed to request line for BCM GPIO %u as input: %s\n",
                    channel_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("TTP226 reader started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int values[NUM_CHANNELS];
        int read_failed = 0;

        for (i = 0; i < NUM_CHANNELS; i++) {
            int v = gpiod_line_get_value(lines[i]);
            if (v < 0) {
                fprintf(stderr, "Failed to read line for BCM GPIO %u: %s\n",
                        channel_pins[i], strerror(errno));
                read_failed = 1;
                break;
            }
            values[i] = v;
        }

        if (read_failed) {
            /* Brief pause before retrying to avoid log flooding on persistent errors */
            struct timespec ts = { 0, 500 * 1000000L };
            nanosleep(&ts, NULL);
            continue;
