            printf("CH%d=%d", i + 1, values[i]);
        printf("\n");
        fflush(stdout);

        struct timespec ts = { 0, POLL_INTERVAL_MS * 1000000L };
        nanosleep(&ts, NULL);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    for (i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i] != NULL)
            gpiod_line_release(lines[i]);
    }
    if (chip != NULL)
        gpiod_chip_close(chip);

    return ret;
}

