#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

#define PWM_FREQ  1000
#define PWM_RANGE 255

#define FADE_STEPS 50
#define FADE_DELAY_US 5000000 / FADE_STEPS

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *msg) {
    syslog(LOG_ERR, "%s", msg);
    fprintf(stderr, "%s\n", msg);
}

static void set_color(int r, int g, int b) {
    if (gpioPWM(RED_PIN,   PWM_RANGE - r) < 0) log_error("gpioPWM(RED_PIN) failed");
    if (gpioPWM(GREEN_PIN, PWM_RANGE - g) < 0) log_error("gpioPWM(GREEN_PIN) failed");
    if (gpioPWM(BLUE_PIN,  PWM_RANGE - b) < 0) log_error("gpioPWM(BLUE_PIN) failed");
}

static void led_off(void) {
    set_color(0, 0, 0);
}

static void fade_to_color(int r, int g, int b) {
    int dr = r, dg = g, db = b;
    int step = 255 / FADE_STEPS;

    for (int i = 0; i <= FADE_STEPS && running; i++) {
        int r_val = dr - (dr * i * step) / 255;
        int g_val = dg - (dg * i * step) / 255;
        int b_val = db - (db * i * step) / 255;

        if (r_val < 0) r_val = 0; if (r_val > 255) r_val = 255;
        if (g_val < 0) g_val = 0; if (g_val > 255) g_val = 255;
        if (b_val < 0) b_val = 0; if (b_val > 255) b_val = 255;

        set_color(r_val, g_val, b_val);
        gpioDelay(FADE_DELAY_US);
    }
}

static int rand_range(int min, int max) {
    return min + (rand() % (max - min + 1));
}

static void generate_hue(int *h, int *s, int *v) {
    *h = rand_range(0, 360);
    *s = 255;
    *v = 255;
}

static void hsv_to_rgb(int h, int s, int v, int *r, int *g, int *b) {
    if (s == 0) {
        *r = *g = *b = v;
        return;
    }
    h = h * 6;
    int sector = h / 60;
    int fract = (h % 60) * 6;
    int n = v * (1 - s / 255.0);
    int m = v * (1 - fract * s / 255.0 / 6.0);
    int q = v * (1 - (60 - fract) * s / 255.0 / 6.0);
    switch (sector) {
        case 0: *r = v; *g = m; *b = n; break;
        case 1: *r = q; *g = v; *b = n; break;
        case 2: *r = n; *g = v; *b = m; break;
        case 3: *r = n; *g = q; *b = v; break;
        case 4: *r = m; *g = n; *b = v; break;
        default: *r = v; *g = n; *b = q; break;
    }
}

int main(void) {
    openlog("moodlamp", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        log_error("sigaction failed");
        closelog();
        return 1;
    }

    if (gpioInitialise() < 0) {
        log_error("pigpio initialization failed");
        closelog();
        return 1;
    }

    if (gpioSetMode(RED_PIN,   PI_OUTPUT) < 0) log_error("gpioSetMode(RED_PIN) failed");
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0) log_error("gpioSetMode(GREEN_PIN) failed");
    if (gpioSetMode(BLUE_PIN,  PI_OUTPUT) < 0) log_error("gpioSetMode(BLUE_PIN) failed");

    if (gpioSetPWMfrequency(RED_PIN,   PWM_FREQ) < 0) log_error("gpioSetPWMfrequency(RED_PIN) failed");
    if (gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) < 0) log_error("gpioSetPWMfrequency(GREEN_PIN) failed");
    if (gpioSetPWMfrequency(BLUE_PIN,  PWM_FREQ) < 0) log_error("gpioSetPWMfrequency(BLUE_PIN) failed");

    if (gpioSetPWMrange(RED_PIN,   PWM_RANGE) < 0) log_error("gpioSetPWMrange(RED_PIN) failed");
    if (gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0) log_error("gpioSetPWMrange(GREEN_PIN) failed");
    if (gpioSetPWMrange(BLUE_PIN,  PWM_RANGE) < 0) log_error("gpioSetPWMrange(BLUE_PIN) failed");

    srand((unsigned int)time(NULL));
    srand((unsigned int)urandom());

    int hue, sat, val, r, g, b;
    generate_hue(&hue, &sat, &val);
    hsv_to_rgb(hue, sat, val, &r, &g, &b);
    fade_to_color(r, g, b);

    while (running) {
        gpioDelay(5000000);
        if (!running) break;

        generate_hue(&hue, &sat, &val);
        hsv_to_rgb(hue, sat, val, &r, &g, &b);
        fade_to_color(r, g, b);
    }

    led_off();
    gpioTerminate();
    closelog();
    return 0;
}

