        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read16 from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int tcs34725_init(int fd) {
    uint8_t id;
    if (i2c_read_reg(fd, TCS34725_ID, &id) < 0) return -1;
    if (id != 0x44) {
        fprintf(stderr, "Unexpected TCS34725 ID: 0x%02X (expected 0x44)\n", id);
        return -1;
    }
    if (i2c_write_reg(fd, TCS34725_ENABLE, TCS34725_PON) < 0) return -1;
    usleep(3000);
    if (i2c_write_reg(fd, TCS34725_ATIME, 0x00) < 0) return -1;
    if (i2c_write_reg(fd, TCS34725_CONTROL, TCS34725_GAIN_1X) < 0) return -1;
