#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define NUM_LEDS 10
#define I2C_ADDR 0x23
#define I2C_BUS 1
#define BH1750_CONT_HIGH_RES 0x10
#define BH1750_MEAS_DELAY_MS 180
#define MAX_LUX 1000.0f
#define PWM_FREQ 800
#define PWM_RANGE 255

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void set_led_brightness(uint8_t brightness) {
    if (brightness > 255) brightness = 255;
    if (brightness == 0) {
        gpioWaveClear();
        gpioWaveTxSend(NULL, PI_WAVE_TX_MODE_ONE_SHOT);
        return;
    }

    gpioPulse_t pulses[NUM_LEDS * 24 + 1];
    int idx = 0;

    for (int i = 0; i < NUM_LEDS; i++) {
        for (int bit = 7; bit >= 0; bit--) {
            int bit_val = (brightness >> bit) & 1;
            pulses[idx].gpioOn = (1 << 18);
            pulses[idx].gpioOff = 0;
            pulses[idx].usDelay = bit_val ? 1 : 1;
            idx++;

            pulses[idx].gpioOn = 0;
            pulses[idx].gpioOff = (1 << 18);
            pulses[idx].usDelay = bit_val ? 1 : 1;
            idx++;
        }
    }

    pulses[idx].gpioOn = 0;
    pulses[idx].gpioOff = 0;
    pulses[idx].usDelay = 60;
    idx++;

    gpioWaveClear();
    if (gpioWaveAddGeneric(idx, pulses) < 0) {
        fprintf(stderr, "Error: gpioWaveAddGeneric failed\n");
        return;
    }
    int wave_id = gpioWaveCreate();
    if (wave_id < 0) {
        fprintf(stderr, "Error: gpioWaveCreate failed\n");
        return;
    }
    gpioWaveTxSend(wave_id, PI_WAVE_TX_MODE_ONE_SHOT);
    while (gpioWaveTxBusy()) usleep(100);
    gpioWaveDelete(wave_id);
}

static float read_light_level(void) {
    if (i2cWriteByte(i2c_handle, BH1750_CONT_HIGH_RES) < 0) {
        fprintf(stderr, "Error: Failed to write BH1750 command\n");
        return -1.0f;
    }
    usleep(BH1750_MEAS_DELAY_MS * 1000);

    char buf[2];
    int bytes = i2cReadDevice(i2c_handle, buf, 2);
    if (bytes != 2) {
        fprintf(stderr, "Error: Failed to read BH1750 data (got %d bytes)\n", bytes);
        return -1.0f;
    }
    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return (float)raw / 1.2f;
}

static uint8_t map_light_to_brightness(float lux) {
    if (lux < 0.0f) lux = 0.0f;
    if (lux > MAX_LUX) lux = MAX_LUX;
    float log_lux = log10f(lux + 1.0f);
    float log_max = log10f(MAX_LUX + 1.0f);
    float norm = log_lux / log_max;
    return (uint8_t)(norm * 255.0f);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at addr 0x%02X\n", I2C_BUS, I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting light-to-LED control. Press Ctrl+C to exit.\n");

    while (running) {
        float lux = read_light_level();
        if (lux < 0.0f) {
            fprintf(stderr, "Warning: Sensor read failed, retrying...\n");
            usleep(500000);
            continue;
        }

        uint8_t brightness = map_light_to_brightness(lux);
        set_led_brightness(brightness);
        printf("Lux: %.2f, Brightness: %u\n", lux, brightness);

        usleep(500000);
    }

    set_led_brightness(0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return 0;
}

