    uint8_t bits = 8;
    uint32_t speed = SPI_SPEED_HZ;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to configure SPI: %s\n", strerror(errno));
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }

    while (running) {
        float lux = 0.0f;
        if (read_bh1750(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Sensor read error, skipping cycle.\n");
            usleep(100000);
            continue;
        }

        if (lux < MIN_LUX) lux = MIN_LUX;
        if (lux > MAX_LUX) lux = MAX_LUX;

        float normalized = (lux - MIN_LUX) / (MAX_LUX - MIN_LUX);
        uint8_t brightness = (uint8_t)(normalized * 31.0f);

        if (set_apa102_brightness(spi_fd, brightness) < 0) {
            fprintf(stderr, "LED update error.\n");
        }

        usleep(100000);
    }

    set_apa102_brightness(spi_fd, 0);
    close(spi_fd);
    close(i2c_fd);
    return 0;
}

