#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define BH1750_ADDR_LOW 0x23
#define BH1750_ADDR_HIGH 0x5C
#define BH1750_CMD_OT_HRES2 0x21
#define BH1750_CONV_MS 180
#define NUM_SENSORS 3
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define APA102_STRIP_LEN 100
#define FADE_MS 500
#define LOOP_DELAY_MS 100
#define MAX_LUX 1000.0f

static int i2c_handles[NUM_SENSORS];
static int spi_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_bh1750(int handle) {
    if (i2cWriteByte(handle, BH1750_CMD_OT_HRES2) < 0) {
        fprintf(stderr, "Error: BH1750 at handle %d not responding to init command.\n", handle);
        return -1;
    }
    gpioDelay(BH1750_CONV_MS * 1000);
    return 0;
}

static int read_bh1750(int handle, float *lux_out) {
    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error: I2C read failed on handle %d.\n", handle);
        return -1;
    }
    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int init_apa102(int strip_len) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (pigpio error %d).\n", spi_handle);
        return -1;
    }
    uint8_t start_frame[4] = {0x00, 0x00, 0x00, 0x00};
    if (spiWrite(spi_handle, (char *)start_frame, 4) != 4) {
        fprintf(stderr, "Error: Failed to send start frame to APA102.\n");
        spiClose(spi_handle);
        spi_handle = -1;
        return -1;
    }
    return 0;
}

static void set_apa102_brightness(int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > 31) brightness = 31;
    uint8_t frame[4] = {0xE0, (uint8_t)brightness, (uint8_t)brightness, (uint8_t)brightness};
    uint8_t data[APA102_STRIP_LEN * 4];
    for (int i = 0; i < APA102_STRIP_LEN; i++) {
        for (int c = 0; c < 4; c++) {
            data[i * 4 + c] = frame[c];
        }
    }
    if (spiWrite(spi_handle, (char *)data, APA102_STRIP_LEN * 4) != APA102_STRIP_LEN * 4) {
        fprintf(stderr, "Error: SPI write failed during brightness update.\n");
    }
}

static void fade_apa102(int target_brightness, int current_brightness) {
    if (current_brightness == target_brightness) return;
    int step = (target_brightness > current_brightness) ? 1 : -1;
    for (int i = 0; i < FADE_MS * 10 && running; i++) {
        current_brightness += step;
        if (current_brightness < 0) current_brightness = 0;
        if (current_brightness > 31) current_brightness = 31;
        set_apa102_brightness(current_brightness);
        gpioDelay(10000);
    }
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        uint8_t off[4] = {0x00, 0x00, 0x00, 0x00};
        spiWrite(spi_handle, (char *)off, 4);
        spiClose(spi_handle);
        spi_handle = -1;
    }
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_handles[i] >= 0) {
            i2cClose(i2c_handles[i]);
            i2c_handles[i] = -1;
        }
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_handles[i] = i2cOpen(I2C_BUS, BH1750_ADDR_LOW + i * 2, 0);
        if (i2c_handles[i] < 0) {
            fprintf(stderr, "Error: Could not open I2C device at address 0x%02X.\n", BH1750_ADDR_LOW + i * 2);
            cleanup();
            return 1;
        }
    }

    if (init_bh1750(i2c_handles[0]) < 0 || init_bh1750(i2c_handles[1]) < 0) {
        cleanup();
        return 1;
    }

    if (init_apa102(APA102_STRIP_LEN) < 0) {
        cleanup();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    int current_brightness = 31;
    while (running) {
        float total_lux = 0.0f;
        int valid_count = 0;
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (i2c_handles[i] >= 0) {
                float lux;
                if (read_bh1750(i2c_handles[i], &lux) == 0) {
                    total_lux += lux;
                    valid_count++;
                }
            }
        }
        if (valid_count > 0) {
            float avg_lux = total_lux / valid_count;
            int target_brightness = (int)((1.0f - avg_lux / MAX_LUX) * 31.0f);
            if (target_brightness < 0) target_brightness = 0;
            if (target_brightness > 31) target_brightness = 31;
            fade_apa102(target_brightness, current_brightness);
            current_brightness = target_brightness;
        } else {
            fprintf(stderr, "Warning: No valid sensor readings. Keeping current brightness.\n");
        }
        gpioDelay(LOOP_DELAY_MS * 1000);
    }

    cleanup();
    return 0;
}

