#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <math.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define VEML7700_ADDR 0x10
#define VEML7700_ALS_CONF_REG 0x00
#define VEML7700_ALS_DATA_REG 0x04
#define GPIO_CHIP "gpiochip4"
#define GPIO_PIN 18
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define LOOP_DELAY_MS 200
#define LUX_MAX 120000.0f
#define GAMMA 2.2f

// Global variables for cleanup
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t running = 1;

// Function prototypes
int veml7700_init(int fd);
int veml7700_read_als(int fd, uint16_t *als_value);
float als_to_lux(uint16_t als_value);
int map_lux_to_brightness(float lux);
void ws2812b_set_brightness(int brightness);
void cleanup();
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

// Cleanup resources
void cleanup() {
    if (line) {
        gpiod_line_set_value(line, 0); // Turn off LED
        gpiod_line_release(line);
        line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

// Initialize VEML7700 sensor
int veml7700_init(int fd) {
    uint8_t buf[3];
    buf[0] = VEML7700_ALS_CONF_REG;
    buf[1] = 0x00; // Integration time 100ms, gain 1/8
    buf[2] = 0x00;

    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "Error writing to VEML7700 config register: %s\n", strerror(errno));
        return -1;
    }
    usleep(10000); // Wait for configuration to take effect
    return 0;
}

// Read ALS data from VEML7700
int veml7700_read_als(int fd, uint16_t *als_value) {
    uint8_t reg = VEML7700_ALS_DATA_REG;
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
        return -1;
    }

    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading ALS data: %s\n", strerror(errno));
        return -1;
    }

    *als_value = (buf[0] << 8) | buf[1];
    return 0;
}

