#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18

#define POLL_INTERVAL_MS 50
#define SELF_TEST_SAMPLES 5
#define SELF_TEST_INTERVAL_MS 100
#define FAULT_BLINK_CYCLES 5
#define FAULT_BLINK_MS 100
#define FAULT_BUZZER_PATTERN_MS 200, 200, 600, 200
#define FAULT_REPEATS 3

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *msg) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", ts, msg);
    fflush(stdout);
}

static void self_test(struct gpiod_line *flame, struct gpiod_line *buzzer, struct gpiod_line *led) {
    log_event("Starting self-test...");

    /* LED blink twice (500 ms on, 500 ms off) */
    for (int i = 0; i < 2; i++) {
        if (gpiod_line_set_value(led, 1) < 0) {
            log_event("ERROR: Failed to set LED on");
            return;
        }
        usleep(500000);
        if (gpiod_line_set_value(led, 0) < 0) {
            log_event("ERROR: Failed to set LED off");
            return;
        }
        usleep(500000);
    }

    /* Read flame sensor 5 times; if all LOW, treat as sensor fault */
    int fault = 0;
    for (int i = 0; i < SELF_TEST_SAMPLES; i++) {
        int val = gpiod_line_get_value(flame);
        if (val < 0) {
            log_event("ERROR: Failed to read flame sensor");
            return;
        }
        if (val == 0) {
            fault = 1;
        }
        usleep(SELF_TEST_INTERVAL_MS * 1000);
    }

    if (fault) {
        log_event("SELF-TEST: Flame sensor reads LOW consistently - potential sensor fault!");
        /* Distinct error pattern: LED blink rapidly 5 times */
        for (int i = 0; i < FAULT_BLINK_CYCLES; i++) {
            if (gpiod_line_set_value(led, 1) < 0) {
                log_event("ERROR: Failed to set LED on during fault pattern");
                return;
            }
            usleep(Fault_BLINK_MS * 1000);
            if (gpiod_line_set_value(led, 0) < 0) {
                log_event("ERROR: Failed to set LED off during fault pattern");
                return;
            }
            usleep(Fault_BLINK_MS * 1000);
        }
        /* Buzzer pattern: short-short-long-short */
        for (int r = 0; r < FAULT_REPEATS; r++) {
            if (gpiod_line_set_value(buzzer, 1) < 0) {
                log_event("ERROR: Failed to activate buzzer during fault pattern");
                return;
            }
            usleep(Fault_BUZZER_PATTERN_MS[0] * 1000);
            if (gpiod_line_set_value(buzzer, 0) < 0) {
                log_event("ERROR: Failed to deactivate buzzer during fault pattern");
                return;
            }
            usleep(Fault_BUZZER_PATTERN_MS[1] * 1000);
            if (gpiod_line_set_value(buzzer, 1) < 0) {
                log_event("ERROR: Failed to activate buzzer during fault pattern");
                return;
            }
            usleep(Fault_BUZZER_PATTERN_MS[2] * 1000);
            if (gpiod_line_set_value(buzzer, 0) < 0) {
                log_event("ERROR: Failed to deactivate buzzer during fault pattern");
                return;
            }
            usleep(Fault_BUZZER_PATTERN_MS[3] * 1000);
        }
        exit(1);
    } else {
        log_event("SELF-TEST: Passed - flame sensor reads HIGH consistently.");
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *flame = NULL, *buzzer = NULL, *led = NULL;
    int ret = 1;

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Open GPIO chip 0 (gpiochip0 on Raspberry Pi 5) */
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return 1;
    }

    /* Get lines */
    flame = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    buzzer = gpiod_chip_get_line(chip, BUZZER_PIN);
    led = gpiod_chip_get_line(chip, LED_PIN);
    if (!flame || !buzzer || !led) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request lines: flame as input, buzzer and LED as output (initial low) */
    if (gpiod_line_request_input(flame, "flame_sensor") < 0) {
        fprintf(stderr, "Failed to request flame sensor line: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(buzzer, "buzzer", 0) < 0) {
        fprintf(stderr, "Failed to request buzzer line: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(led, "led", 0) < 0) {
        fprintf(stderr, "Failed to request LED line: %s\n", strerror(errno));
        goto cleanup;
    }

    log_event("Flame sensor monitoring started.");

    /* Run self-test */
    self_test(flame, buzzer, led);

    /* Main loop: poll flame sensor every 50 ms */
    while (running) {
        int val = gpiod_line_get_value(flame);
        if (val < 0) {
            log_event("ERROR: Failed to read flame sensor in main loop");
            break;
        }

        if (val == 0) {
            log_event("Flame detected!");
            if (gpiod_line_set_value(buzzer, 1) < 0) {
                log_event("ERROR: Failed to activate buzzer");
                break;
            }
            if (gpiod_line_set_value(led, 1) < 0) {
                log_event("ERROR: Failed to activate LED");
                break;
            }
        } else {
            if (gpiod_line_set_value(buzzer, 0) < 0) {
                log_event("ERROR: Failed to deactivate buzzer");
                break;
            }
            if (gpiod_line_set_value(led, 0) < 0) {
                log_event("ERROR: Failed to deactivate LED");
                break;
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    /* Ensure outputs are off on exit */
    if (buzzer) gpiod_line_set_value(buzzer, 0);
    if (led) gpiod_line_set_value(led, 0);
    ret = 0;

cleanup:
    if (flame) gpiod_line_release(flame);
    if (buzzer) gpiod_line_release(buzzer);
    if (led) gpiod_line_release(led);
    if (chip) gpiod_chip_close(chip);
    log_event("Program terminated.");
    return ret;
}

