#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <sys/stat.h>
#include <sys/types.h>

#define BH1750_ADDR 0x23
#define I2C_DEV "/dev/i2c-1"
#define GPIO_PIN 17
#define BUFFER_SIZE 60
#define MIN_BLINK_RATE 0.5
#define MAX_BLINK_RATE 5.0
#define LUX_DIVISOR 1.2f
#define READ_DELAY_MS 1000
#define BLINK_PERIOD_US (1000000 / 2)

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int gpio_exported = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int init_bh1750(int fd) {
    if (i2c_write_byte(fd, 0x10) < 0) {
        fprintf(stderr, "Failed to set BH1750 to continuous high-res mode\n");
        return -1;
    }
    usleep(180000);
    return 0;
}

static int read_lux(int fd, float *lux) {
    uint8_t buf[2];
    if (i2c_read_bytes(fd, buf, 2) < 0) {
        return -1;
    }
    uint16_t raw = (buf[0] << 8) | buf[1];
    *lux = (float)raw / LUX_DIVISOR;
    return 0;
}

static void update_circular_buffer(float *buffer, int *index, float new_value, int size) {
    buffer[*index] = new_value;
    *index = (*index + 1) % size;
}

static float calculate_average_lux(const float *buffer, int size) {
    float sum = 0.0f;
    for (int i = 0; i < size; i++) {
        sum += buffer[i];
    }
    return sum / size;
}

static float calculate_blink_rate(float avg_lux) {
    float rate = MIN_BLINK_RATE + (avg_lux / 1000.0f) * (MAX_BLINK_RATE - MIN_BLINK_RATE);
    if (rate < MIN_BLINK_RATE) rate = MIN_BLINK_RATE;
    if (rate > MAX_BLINK_RATE) rate = MAX_BLINK_RATE;
    return rate;
}

static int set_gpio_value(int pin, int value) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open GPIO value file: %s\n", strerror(errno));
        return -1;
    }
    if (write(fd, &value, 1) != 1) {
        fprintf(stderr, "Failed to write GPIO value: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int export_gpio(int pin) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/export");
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open GPIO export file: %s\n", strerror(errno));
        return -1;
    }
    char pin_str[4];
    snprintf(pin_str, sizeof(pin_str), "%d", pin);
    if (write(fd, pin_str, strlen(pin_str)) != (ssize_t)strlen(pin_str)) {
        fprintf(stderr, "Failed to export GPIO %d: %s\n", pin, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int unexport_gpio(int pin) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/unexport");
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open GPIO unexport file: %s\n", strerror(errno));
        return -1;
    }
    char pin_str[4];
    snprintf(pin_str, sizeof(pin_str), "%d", pin);
    if (write(fd, pin_str, strlen(pin_str)) != (ssize_t)strlen(pin_str)) {
        fprintf(stderr, "Failed to unexport GPIO %d: %s\n", pin, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    if (export_gpio(GPIO_PIN) < 0) {
        fprintf(stderr, "GPIO export failed\n");
        return 1;
    }
    gpio_exported = 1;

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device %s: %s\n", I2C_DEV, strerror(errno));
        if (gpio_exported) unexport_gpio(GPIO_PIN);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(i2c_fd);
        if (gpio_exported) unexport_gpio(GPIO_PIN);
        return 1;
    }

    if (init_bh1750(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 initialization failed\n");
        close(i2c_fd);
        if (gpio_exported) unexport_gpio(GPIO_PIN);
        return 1;
    }

    float lux_buffer[BUFFER_SIZE];
    int buffer_index = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        lux_buffer[i] = 0.0f;
    }

    while (running) {
        float lux;
        if (read_lux(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Read failed, skipping sample\n");
            usleep(READ_DELAY_MS * 1000);
            continue;
        }

        update_circular_buffer(lux_buffer, &buffer_index, lux, BUFFER_SIZE);
        float avg_lux = calculate_average_lux(lux_buffer, BUFFER_SIZE);
        float blink_rate = calculate_blink_rate(avg_lux);

        int on_time_us = (int)(BLINK_PERIOD_US * blink_rate);
        int off_time_us = BLINK_PERIOD_US - on_time_us;

        if (on_time_us > 0) {
            if (set_gpio_value(GPIO_PIN, 1) < 0) break;
            usleep(on_time_us);
        }
        if (off_time_us > 0) {
            if (set_gpio_value(GPIO_PIN, 0) < 0) break;
            usleep(off_time_us);
        }
    }

    set_gpio_value(GPIO_PIN, 0);
    if (i2c_fd >= 0) close(i2c_fd);
    if (gpio_exported) unexport_gpio(GPIO_PIN);

    printf("Program terminated gracefully.\n");
    return 0;
}

