#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <gpiod.h>

#define DATA_PIN  17
#define CLOCK_PIN 18
#define LATCH_PIN 27

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *data_line = NULL;
static struct gpiod_line *clock_line = NULL;
static struct gpiod_line *latch_line = NULL;

static void cleanup(void) {
    if (data_line) gpiod_line_release(data_line);
    if (clock_line) gpiod_line_release(clock_line);
    if (latch_line) gpiod_line_release(latch_line);
    if (chip) gpiod_chip_close(chip);
}

static int shift_out(unsigned char data) {
    for (int i = 0; i < 8; i++) {
        int bit = (data >> (7 - i)) & 1;
        if (gpiod_line_set_value(data_line, bit) < 0) {
            perror("Failed to set data line");
            return -1;
        }
        if (gpiod_line_set_value(clock_line, 1) < 0) {
            perror("Failed to set clock high");
            return -1;
        }
        usleep(1);
        if (gpiod_line_set_value(clock_line, 0) < 0) {
            perror("Failed to set clock low");
            return -1;
        }
    }
    if (gpiod_line_set_value(latch_line, 1) < 0) {
        perror("Failed to set latch high");
        return -1;
    }
    usleep(1);
    if (gpiod_line_set_value(latch_line, 0) < 0) {
        perror("Failed to set latch low");
        return -1;
    }
    return 0;
}

int main(void) {
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    data_line = gpiod_chip_get_line(chip, DATA_PIN);
    clock_line = gpiod_chip_get_line(chip, CLOCK_PIN);
    latch_line = gpiod_chip_get_line(chip, LATCH_PIN);
    if (!data_line || !clock_line || !latch_line) {
        perror("Failed to get GPIO lines");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(data_line, "seven-seg", 0) < 0 ||
        gpiod_line_request_output(clock_line, "seven-seg", 0) < 0 ||
        gpiod_line_request_output(latch_line, "seven-seg", 0) < 0) {
        perror("Failed to request GPIO lines as outputs");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        if (shift_out(0x3F) < 0) {
            cleanup();
            return EXIT_FAILURE;
        }
        usleep(500000);
        if (shift_out(0x00) < 0) {
            cleanup();
            return EXIT_FAILURE;
        }
        usleep(500000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

