#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define LED_LINE 17
#define BUTTON_LINE 18
#define CONSUMER "blink-button"

static volatile sig_atomic_t keep_running = 1;

static void handle_sigint(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_line = NULL;
    struct gpiod_line *button_line = NULL;
    struct gpiod_line_event event;
    int ret;

    /* Open GPIO chip 0 */
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("gpiod_chip_open_by_number");
        return EXIT_FAILURE;
    }

    /* Get LED line (BCM 17, physical pin 11) */
    led_line = gpiod_chip_get_line(chip, LED_LINE);
    if (!led_line) {
        perror("gpiod_chip_get_line (LED)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Get button line (BCM 18, physical pin 12) */
    button_line = gpiod_chip_get_line(chip, BUTTON_LINE);
    if (!button_line) {
        perror("gpiod_chip_get_line (button)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request LED as output, initially low */
    ret = gpiod_line_request_output(led_line, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (LED)");
        goto cleanup;
    }

    /* Request button as input with pull-up and falling-edge events */
    ret = gpiod_line_request_falling_edge_events_flags(button_line,
            CONSUMER, GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        perror("gpiod_line_request_falling_edge_events_flags (button)");
        goto cleanup;
    }

    /* Install signal handler for graceful shutdown */
    signal(SIGINT, handle_sigint);

    /* Main loop: blink LED while monitoring button */
    while (keep_running) {
        /* Turn LED on */
        ret = gpiod_line_set_value(led_line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (LED on)");
            break;
        }
