#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>
#include <time.h>

#define RED_PIN   24
#define GREEN_PIN 23
#define BLUE_PIN  18
#define PWM_PERIOD_NS 10000000  /* 10 ms = 100 Hz */
#define LOOP_DELAY_NS 100000000 /* 100 ms between color changes */

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_pwm(struct gpiod_line *line, int duty_percent) {
    if (duty_percent < 0) duty_percent = 0;
    if (duty_percent > 100) duty_percent = 100;

    long on_ns = (PWM_PERIOD_NS * duty_percent) / 100;
    long off_ns = PWM_PERIOD_NS - on_ns;

    struct timespec ts_on = {0, on_ns};
    struct timespec ts_off = {0, off_ns};

    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Failed to set line high: %s\n", strerror(errno));
        return -1;
    }
    if (clock_nanosleep(CLOCK_MONOTONIC, 0, &ts_on, NULL) != 0) {
        fprintf(stderr, "clock_nanosleep on failed: %s\n", strerror(errno));
        return -1;
    }

    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Failed to set line low: %s\n", strerror(errno));
        return -1;
    }
    if (clock_nanosleep(CLOCK_MONOTONIC, 0, &ts_off, NULL) != 0) {
        fprintf(stderr, "clock_nanosleep off failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *red_line = NULL, *green_line = NULL, *blue_line = NULL;
    int ret = EXIT_FAILURE;

    srand((unsigned int)time(NULL));

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    red_line = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);
    if (!red_line || !green_line || !blue_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(red_line, "rgb-led", 0) < 0 ||
        gpiod_line_request_output(green_line, "rgb-led", 0) < 0 ||
        gpiod_line_request_output(blue_line, "rgb-led", 0) < 0) {
        fprintf(stderr, "Failed to request output lines: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("RGB LED control started. Press Ctrl+C to exit.\n");

    while (running) {
        int red   = rand() % 101;
        int green = rand() % 101;
        int blue  = rand() % 101;

        if (set_pwm(red_line, red) < 0) goto cleanup;
        if (set_pwm(green_line, green) < 0) goto cleanup;
        if (set_pwm(blue_line, blue) < 0) goto cleanup;

        struct timespec delay = {0, LOOP_DELAY_NS};
        while (nanosleep(&delay, &delay) == -1 && errno == EINTR && running) {
            /* interrupted by signal; continue if still running */
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (red_line) gpiod_line_release(red_line);
    if (green_line) gpiod_line_release(green_line);
    if (blue_line) gpiod_line_release(blue_line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

