#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* LSM303DLHC accelerometer I2C address (SA0 tied to VDD on Adafruit breakout) */
#define LSM303_ACCEL_ADDR 0x19

/* LSM303DLHC accelerometer register addresses */
#define LSM303_ACCEL_CTRL_REG1_A 0x20
#define LSM303_ACCEL_CTRL_REG4_A 0x23
#define LSM303_ACCEL_OUT_X_L_A   0x28

/* GPIO pin for impact indicator */
#define IMPACT_GPIO 17

/* Default G-force threshold (2.0G) */
#define DEFAULT_G_THRESHOLD 2.0f

/* Impact duration in milliseconds */
#define IMPACT_DURATION_MS 50

/* Sampling interval in microseconds (10 Hz) */
#define SAMPLE_INTERVAL_US 100000

/* Sensitivity for +/-2g full-scale: 16384 LSB/G */
#define ACCEL_SENSITIVITY 16384.0f

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static float g_g_threshold = DEFAULT_G_THRESHOLD;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown                                */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an accelerometer register                         */
/* ------------------------------------------------------------------ */
static int accel_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error: I2C write failed (reg=0x%02X, val=0x%02X, rc=%d)\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a block of bytes from the accelerometer starting at reg        */
/* (auto-increment bit 0x80)                                           */
/* ------------------------------------------------------------------ */
static int accel_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "Error: I2C block read failed (reg=0x%02X, len=%u, rc=%d)\n",
                reg, len, rc);
        return -1;
    }
    if ((uint32_t)rc != len) {
        fprintf(stderr, "Error: I2C block read short read (reg=0x%02X, expected=%u, got=%d)\n",
                reg, len, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the LSM303DLHC accelerometer                              */
/* ------------------------------------------------------------------ */
static int init_accelerometer(int handle)
{
    /* CTRL_REG1_A: enable X/Y/Z axes, ODR = 100 Hz, normal mode */
    if (accel_write_reg(handle, LSM303_ACCEL_CTRL_REG1_A, 0x27) < 0)
        return -1;

    /* CTRL_REG4_A: full-scale = +/-2g, high-resolution disabled */
    if (accel_write_reg(handle, LSM303_ACCEL_CTRL_REG4_A, 0x00) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read accelerometer data (6 bytes, little-endian)                     */
/* ------------------------------------------------------------------ */
static int read_accelerometer(int handle, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];

    /* Set MSB of register address for auto-increment */
    if (accel_read_block(handle, LSM303_ACCEL_OUT_X_L_A | 0x80, buf, sizeof(buf)) < 0)
        return -1;

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

/* ------------------------------------------------------------------ */
/* Convert raw LSB to G-force                                         */
/* ------------------------------------------------------------------ */
static float raw_to_g(int16_t raw)
{
    return (float)raw / ACCEL_SENSITIVITY;
}

/* ------------------------------------------------------------------ */
/* Calculate total G-force magnitude                                   */
/* ------------------------------------------------------------------ */
static float calc_total_g(int16_t x, int16_t y, int16_t z)
{
    float gx = raw_to_g(x);
    float gy = raw_to_g(y);
    float gz = raw_to_g(z);
    return sqrtf(gx * gx + gy * gy + gz * gz);
}

/* ------------------------------------------------------------------ */
/* Log impact data to file                                             */
/* ------------------------------------------------------------------ */
static void log_impact(int16_t x, int16_t y, int16_t z, float g)
{
    FILE *fp = fopen("impact_log.txt", "a");
    if (!fp) {
        perror("Error opening impact_log.txt");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, X=%d, Y=%d, Z=%d, G=%.3f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                x, y, z, g);
    } else {
        fprintf(fp, "timestamp_error, X=%d, Y=%d, Z=%d, G=%.3f\n", x, y, z, g);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Pulse GPIO17 HIGH for IMPACT_DURATION_MS                             */
/* ------------------------------------------------------------------ */
static void trigger_impact_gpio(void)
{
    if (gpioWrite(IMPACT_GPIO, 1) < 0) {
        fprintf(stderr, "Warning: failed to set GPIO%d HIGH\n", IMPACT_GPIO);
        return;
    }
    gpioDelay(IMPACT_DURATION_MS * 1000); /* gpioDelay takes microseconds */
    if (gpioWrite(IMPACT_GPIO, 0) < 0) {
        fprintf(stderr, "Warning: failed to set GPIO%d LOW\n", IMPACT_GPIO);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup resources                                                   */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int opt;

    /* Parse command-line arguments */
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                g_g_threshold = (float)atof(optarg);
                if (g_g_threshold <= 0.0f) {
                    fprintf(stderr, "Error: G-force threshold must be positive\n");
                    return EXIT_FAILURE;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold_g]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at LSM303DLHC accelerometer address */
    g_i2c_handle = i2cOpen(1, LSM303_ACCEL_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (addr=0x%02X, rc=%d)\n",
                LSM303_ACCEL_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize accelerometer */
    if (init_accelerometer(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: accelerometer initialization failed (sensor absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure GPIO17 as output, initially LOW */
    if (gpioSetMode(IMPACT_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", IMPACT_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(IMPACT_GPIO, 0);

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Impact detection started. Threshold: %.2f G. Press Ctrl+C to exit.\n",
           g_g_threshold);

    /* Main sampling loop */
    while (g_running) {
        int16_t x, y, z;

        if (read_accelerometer(g_i2c_handle, &x, &y, &z) < 0) {
            fprintf(stderr, "Warning: accelerometer read failed, retrying...\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float g = calc_total_g(x, y, z);

        if (g > g_g_threshold) {
            printf("Impact detected! G-force: %.3f G (X=%d, Y=%d, Z=%d)\n",
                   g, x, y, z);
            log_impact(x, y, z, g);
            trigger_impact_gpio();
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

