#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x39
#define LED_GPIO 18
#define PWM_RANGE 255
#define SAMPLE_INTERVAL_US 500000
#define RETRY_DELAY_US 100000

#define REG_MODE 0x0D
#define MODE_NORMAL 0x01
#define REG_ALS_LSB 0x64
#define REG_ALS_MSB 0x65
#define REG_RED_LSB 0x66
#define REG_RED_MSB 0x67
#define REG_GREEN_LSB 0x68
#define REG_GREEN_MSB 0x69
#define REG_BLUE_LSB 0x6A
#define REG_BLUE_MSB 0x6B

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write error: reg=0x%02X, val=0x%02X, rc=%d (%s)\n",
                reg, value, rc, strerror(errno));
    }
    return rc;
}

static int i2c_read_byte(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error: reg=0x%02X, rc=%d (%s)\n",
                reg, rc, strerror(errno));
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int read_16bit(int handle, uint8_t lsb_reg, uint8_t msb_reg, uint16_t *out) {
    uint8_t lsb, msb;
    if (i2c_read_byte(handle, lsb_reg, &lsb) < 0) return -1;
    if (i2c_read_byte(handle, msb_reg, &msb) < 0) return -1;
    *out = ((uint16_t)msb << 8) | lsb;
    return 0;
}

static int initialize_sensor(int handle) {
    if (i2c_write_byte(handle, REG_MODE, MODE_NORMAL) < 0) {
        fprintf(stderr, "Failed to set normal mode\n");
        return -1;
    }
    return 0;
}

static int read_sensor_data(int handle, uint16_t *als, uint16_t *r, uint16_t *g, uint16_t *b) {
    if (read_16bit(handle, REG_ALS_LSB, REG_ALS_MSB, als) < 0) return -1;
    if (read_16bit(handle, REG_RED_LSB, REG_RED_MSB, r) < 0) return -1;
    if (read_16bit(handle, REG_GREEN_LSB, REG_GREEN_MSB, g) < 0) return -1;
    if (read_16bit(handle, REG_BLUE_LSB, REG_BLUE_MSB, b) < 0) return -1;
    return 0;
}

static void log_data(FILE *fp, uint16_t als, uint16_t r, uint16_t g, uint16_t b) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%u,%u,%u,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            als, r, g, b);
    fflush(fp);
}

static void set_led_brightness(int gpio, uint16_t als) {
    int duty = (int)((float)als / 65535.0f * PWM_RANGE);
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    gpioPWM(gpio, duty);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioPWM(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d (%s)\n",
                I2C_BUS, I2C_ADDR, i2c_handle, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (initialize_sensor(i2c_handle) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,ALS,R,G,B\n");
        fflush(log_file);
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint16_t als, r, g, b;
    while (!terminate) {
        if (read_sensor_data(i2c_handle, &als, &r, &g, &b) == 0) {
            log_data(log_file, als, r, g, b);
            set_led_brightness(LED_GPIO, als);
        } else {
            fprintf(stderr, "Sensor read error, retrying...\n");
        }
        gpioDelay(RETRY_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

