#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* FXOS8700CQ I2C address (SA0 tied high on Adafruit breakout) */
#define FXOS8700_ADDRESS 0x1F

/* FXOS8700CQ register addresses */
#define FXOS8700_WHO_AM_I    0x0D
#define FXOS8700_WHO_AM_I_VAL 0xC7
#define FXOS8700_CTRL_REG1   0x2A
#define FXOS8700_XYZ_DATA_CFG 0x0E
#define FXOS8700_OUT_X_MSB   0x01

/* ±2g range: 4096 counts/g, 14-bit left-justified => divide by 4096, then by 4 */
#define ACCEL_SENSITIVITY 4096.0f
#define ACCEL_LSB_TO_G  (1.0f / ACCEL_SENSITIVITY)  /* g per LSB */
#define ACCEL_LSB_TO_G_FULL (ACCEL_LSB_TO_G / 4.0f) /* 14-bit: divide by 4 */

/* Impact threshold: 2g in m/s^2 */
#define IMPACT_THRESHOLD_MPS2 19.62f

/* Sampling interval */
#define SAMPLE_INTERVAL_US 50000  /* 50 ms */

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int fxos8700_read_reg(int handle, uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error: reg 0x%02X, rc=%d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int fxos8700_write_reg(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write error: reg 0x%02X, val 0x%02X, rc=%d\n",
                reg, val, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int fxos8700_init(int handle)
{
    uint8_t who_am_i = 0;

    /* Verify device identity */
    if (fxos8700_read_reg(handle, FXOS8700_WHO_AM_I, &who_am_i) != 0)
        return -1;

    if (who_am_i != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr,
                "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, FXOS8700_WHO_AM_I_VAL);
        return -1;
    }

    /* Standby mode (clear ACTIVE bit in CTRL_REG1) */
    if (fxos8700_write_reg(handle, FXOS8700_CTRL_REG1, 0x00) != 0)
        return -1;

    /* ±2g range */
    if (fxos8700_write_reg(handle, FXOS8700_XYZ_DATA_CFG, 0x00) != 0)
        return -1;

    /* Active mode, 200 Hz ODR (CTRL_REG1 = 0x01) */
    if (fxos8700_write_reg(handle, FXOS8700_CTRL_REG1, 0x01) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read acceleration (6 bytes from OUT_X_MSB)                          */
/* ------------------------------------------------------------------ */
static int fxos8700_read_accel(int handle, float *x, float *y, float *z)
{
    uint8_t buf[6];
    int16_t raw_x, raw_y, raw_z;

    /* Read 6 bytes starting at OUT_X_MSB (0x01) */
    int rc = i2cReadI2CBlockData(handle, FXOS8700_OUT_X_MSB, (char *)buf, 6);
    if (rc != 6) {
        fprintf(stderr, "I2C block read error: rc=%d\n", rc);
        return -1;
    }

    /* 14-bit left-justified: shift right by 2 */
    raw_x = (int16_t)((buf[0] << 8) | buf[1]) >> 2;
    raw_y = (int16_t)((buf[2] << 8) | buf[3]) >> 2;
    raw_z = (int16_t)((buf[4] << 8) | buf[5]) >> 2;

    /* Convert to g: raw is in counts, sensitivity = 4096 counts/g */
    *x = (float)raw_x * ACCEL_LSB_TO_G;
    *y = (float)raw_y * ACCEL_LSB_TO_G;
    *z = (float)raw_z * ACCEL_LSB_TO_G;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log impact to file                                                 */
/* ------------------------------------------------------------------ */
static void log_impact(float x, float y, float z, float magnitude)
{
    FILE *fp = fopen("impact_log.txt", "a");
    if (!fp) {
        perror("fopen(impact_log.txt)");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f,%.3f,%.3f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            x, y, z, magnitude);

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at FXOS8700_ADDRESS */
    g_i2c_handle = i2cOpen(1, FXOS8700_ADDRESS, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (fxos8700_init(g_i2c_handle) != 0) {
        fprintf(stderr, "FXOS8700CQ initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Impact detection started. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        float x, y, z, magnitude;

        if (fxos8700_read_accel(g_i2c_handle, &x, &y, &z) == 0) {
            magnitude = sqrtf(x * x + y * y + z * z);

            if (magnitude > IMPACT_THRESHOLD_MPS2) {
                log_impact(x, y, z, magnitude);
                printf("Impact detected: magnitude=%.3f m/s^2\n", magnitude);
            }
        } else {
            fprintf(stderr, "Read error, continuing...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Graceful cleanup */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

