/*
 * GY-50 L3G4200D Gyroscope reader for Raspberry Pi Zero W
 * Uses Linux i2c-dev ioctl interface (no wiringPi).
 *
 * Wiring:
 *   L3G4200D SDA -> GPIO2 (pin 3, I2C bus 1)
 *   L3G4200D SCL -> GPIO3 (pin 5, I2C bus 1)
 *   L3G4200D VDD -> 3.3 V
 *   L3G4200D GND -> GND
 *   SA0 tied high -> I2C address 0x69
 *
 * Build: gcc -O2 -Wall -o gyro gyro.c
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- L3G4200D constants ---- */
#define L3G4200D_ADDR        0x69
#define L3G4200D_WHO_AM_I    0x0F
#define L3G4200D_WHO_AM_I_ID 0xD3
#define L3G4200D_CTRL_REG1   0x20
#define L3G4200D_CTRL_REG4   0x23
#define L3G4200D_OUT_X_L     0x28
#define L3G4200D_OUT_X_H     0x29
#define L3G4200D_OUT_Y_L     0x2A
#define L3G4200D_OUT_Y_H     0x2B
#define L3G4200D_OUT_Z_L     0x2C
#define L3G4200D_OUT_Z_H     0x2D

#define SENSITIVITY_DPS_LSB  0.00875f   /* 250 dps / 32768 LSB */
#define THRESHOLD_DPS       50.0f
#define CAL_SAMPLES         100
#define SAMPLE_PERIOD_US    50000      /* 50 ms -> 20 Hz */
#define LOG_FILE            "gyro_log.txt"

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: read(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_block: write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "i2c_read_block: read(0x%02X, %zu) failed: %s\n",
                reg, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Gyro ---- */

typedef struct {
    float x, y, z;
} gyro_t;

static int gyro_init(int fd)
{
    uint8_t id;
    if (i2c_read_reg8(fd, L3G4200D_WHO_AM_I, &id) < 0)
        return -1;
    if (id != L3G4200D_WHO_AM_I_ID) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                id, L3G4200D_WHO_AM_I_ID);
        return -1;
    }

    if (i2c_write_reg8(fd, L3G4200D_CTRL_REG1, 0x0F) < 0)  /* normal mode, 100 Hz */
        return -1;
    if (i2c_write_reg8(fd, L3G4200D_CTRL_REG4, 0x00) < 0)  /* 250 dps, continuous */
        return -1;

    return 0;
}

static int gyro_read(int fd, gyro_t *g)
{
    uint8_t buf[6];
    if (i2c_read_block(fd, L3G4200D_OUT_X_L, buf, sizeof(buf)) < 0)
        return -1;

    int16_t x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t z = (int16_t)((buf[5] << 8) | buf[4]);

    g->x = (float)x * SENSITIVITY_DPS_LSB;
    g->y = (float)y * SENSITIVITY_DPS_LSB;
    g->z = (float)z * SENSITIVITY_DPS_LSB;
    return 0;
}

static void gyro_calibrate(int fd, gyro_t *offset)
{
    gyro_t sum = {0.0f, 0.0f, 0.0f};
    gyro_t sample;

    printf("Calibrating %d samples (keep sensor still)...\n", CAL_SAMPLES);
    for (int i = 0; i < CAL_SAMPLES; i++) {
        if (gyro_read(fd, &sample) < 0) {
            fprintf(stderr, "Calibration read failed at sample %d\n", i);
            return;
        }
        sum.x += sample.x;
        sum.y += sample.y;
        sum.z += sample.z;
        usleep(1000);
    }

    offset->x = sum.x / CAL_SAMPLES;
    offset->y = sum.y / CAL_SAMPLES;
    offset->z = sum.z / CAL_SAMPLES;

    printf("Calibration complete. Offsets: X=%.2f Y=%.2f Z=%.2f dps\n",
           offset->x, offset->y, offset->z);
}

static void log_data(FILE *fp, const gyro_t *g, const gyro_t *o)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];
    localtime_r(&t, &tm);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
            ts, g->x, g->y, g->z,
            (g->x - o->x), (g->y - o->y), (g->z - o->z));
    fflush(fp);
}

static void check_threshold(const gyro_t *g, const gyro_t *o)
{
    if (fabsf(g->x - o->x) > THRESHOLD_DPS ||
        fabsf(g->y - o->y) > THRESHOLD_DPS ||
        fabsf(g->z - o->z) > THRESHOLD_DPS) {
        fprintf(stderr, "WARNING: motion detected (X=%.2f Y=%.2f Z=%.2f)\n",
                g->x, g->y, g->z);
        fprintf(fp, "%s,WARNING: motion detected (X=%.2f Y=%.2f Z=%.2f)\n",
                ts, g->x, g->y, g->z);
        fflush(fp);
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open /dev/i2c-1");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, L3G4200D_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return EXIT_FAILURE;
    }

    if (gyro_init(fd) < 0) {
        fprintf(stderr, "Gyroscope initialization failed.\n");
        close(fd);
        return EXIT_FAILURE;
    }

    gyro_t offset = {0.0f, 0.0f, 0.0f};
    gyro_calibrate(fd, &offset);

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen " LOG_FILE);
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Logging to %s at 20 Hz. Press Ctrl+C to stop.\n", LOG_FILE);

    while (g_running) {
        gyro_t gyro;
        if (gyro_read(fd, &gyro) < 0) {
            fprintf(stderr, "Read error, continuing...\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        log_data(fp, &gyro, &offset);
        check_threshold(&gyro, &offset);

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    fclose(fp);
    close(fd);
    return EXIT_SUCCESS;
}

