#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ADXL345 I2C address (ALT ADDRESS tied to GND) */
#define ADXL345_ADDRESS 0x53

/* ADXL345 registers */
#define ADXL345_DEVID       0x00
#define ADXL345_POWER_CTL   0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0      0x32
#define ADXL345_DATAX1      0x33
#define ADXL345_DATAY0      0x34
#define ADXL345_DATAY1      0x35
#define ADXL345_DATAZ0      0x36
#define ADXL345_DATAZ1      0x37

/* Expected device ID */
#define ADXL345_DEVID_VALUE 0xE5

/* GPIO pin for LED */
#define LED_PIN 17

/* I2C bus on Raspberry Pi 4 */
#define I2C_BUS 1

/* Sampling interval in microseconds (100 ms) */
#define SAMPLE_INTERVAL_US 100000

/* Acceleration threshold in g */
#define ACCEL_THRESHOLD 2.0f

/* Full-resolution, ±2g range: 4 mg/LSB */
#define SCALE_FACTOR 0.004f

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an ADXL345 register; return 0 on success, -1 err  */
/* ------------------------------------------------------------------ */
static int adxl_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an ADXL345 register; return 0 on success, -1 err */
/* ------------------------------------------------------------------ */
static int adxl_read_reg(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the ADXL345: verify device ID, set power control, format*/
/* ------------------------------------------------------------------ */
static int adxl345_init(int handle)
{
    uint8_t devid = 0;

    /* Verify device identity */
    if (adxl_read_reg(handle, ADXL345_DEVID, &devid) != 0) {
        fprintf(stderr, "Error: cannot read DEVID register\n");
        return -1;
    }
    if (devid != ADXL345_DEVID_VALUE) {
        fprintf(stderr, "Error: DEVID mismatch (got 0x%02X, expected 0x%02X)\n",
                devid, ADXL345_DEVID_VALUE);
        return -1;
    }

    /* Standby mode before configuration */
    if (adxl_write_reg(handle, ADXL345_POWER_CTL, 0x00) != 0)
        return -1;

    /* Full-resolution, ±2g range, right-justified, 4-wire SPI off */
    if (adxl_write_reg(handle, ADXL345_DATA_FORMAT, 0x0B) != 0)
        return -1;

    /* Enable measurement mode */
    if (adxl_write_reg(handle, ADXL345_POWER_CTL, 0x08) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read acceleration in g; returns 0 on success, -1 on error          */
/* ------------------------------------------------------------------ */
static int read_acceleration(int handle, float *x, float *y, float *z)
{
    uint8_t buf[6];

    /* Read 6 bytes starting at DATAX0 (0x32) */
    int rc = i2cReadI2CBlockData(handle, ADXL345_DATAX0, (char *)buf, 6);
    if (rc != 6) {
        fprintf(stderr, "Error: i2cReadI2CBlockData failed: %d\n", rc);
        return -1;
    }

    /* Combine little-endian bytes into signed 20-bit values */
    int32_t raw_x = (int32_t)((uint32_t)buf[1] << 8 | (uint32_t)buf[0]) << 4;
    int32_t raw_y = (int32_t)((uint32_t)buf[3] << 8 | (uint32_t)buf[2]) << 4;
    int32_t raw_z = (int32_t)((uint32_t)buf[5] << 8 | (uint32_t)buf[4]) << 4;

    /* Sign-extend from 20 bits to 32 bits */
    if (raw_x & 0x800) raw_x |= 0xFFF00000;
    if (raw_y & 0x800) raw_y |= 0xFFF00000;
    if (raw_z & 0x800) raw_z |= 0xFFF00000;

    /* Convert to g: 4 mg/LSB => divide by 256, then by 1000 */
    *x = (float)raw_x / 256.0f / 1000.0f;
    *y = (float)raw_y / 256.0f / 1000.0f;
    *z = (float)raw_z / 256.0f / 1000.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one sample to the CSV file                                      */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float x, float y, float z)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return -1;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.3f,%.3f,%.3f\n", ts, x, y, z) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    float x = 0.0f, y = 0.0f, z = 0.0f;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at ADXL345 address */
    g_i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDRESS, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, ADXL345_ADDRESS, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize ADXL345 */
    if (adxl345_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: ADXL345 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LED pin as output and ensure it is off */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Open log file in append mode */
    g_log_file = fopen("accel_log.txt", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open accel_log.txt for appending\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,x,y,z\n");
        fflush(g_log_file);
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADXL345 logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        if (read_acceleration(g_i2c_handle, &x, &y, &z) == 0) {
            if (log_data(g_log_file, x, y, z) != 0) {
                fprintf(stderr, "Warning: logging failed for this sample\n");
            }

            /* Threshold check on any axis */
            int exceed = (fabsf(x) > ACCEL_THRESHOLD ||
                          fabsf(y) > ACCEL_THRESHOLD ||
                          fabsf(z) > ACCEL_THRESHOLD);

            if (gpioWrite(LED_PIN, exceed ? 1 : 0) != 0) {
                fprintf(stderr, "Warning: gpioWrite(LED) failed\n");
            }
        } else {
            /* I2C read error: ensure LED is off and log the failure */
            gpioWrite(LED_PIN, 0);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

