#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

/* LSM303DLHC I2C addresses */
#define LSM303_ACCEL_ADDR 0x19
#define LSM303_MAG_ADDR   0x1E

/* LSM303DLHC register addresses */
#define LSM303_ACCEL_CTRL_REG1_A 0x20
#define LSM303_ACCEL_OUT_X_L_A   0x28
#define LSM303_MAG_MR_REG_M      0x02
#define LSM303_MAG_OUT_X_H_M     0x03

/* Scaling factors */
#define ACCEL_SCALE 0.000061f  /* 1 mg/LSB -> g */
#define MAG_SCALE   0.00014f   /* 1.3 mg/LSB -> gauss */

static int i2c_handle_accel = -1;
static int i2c_handle_mag   = -1;
static volatile sig_atomic_t running = 1;

typedef struct {
    float x, y, z;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_lsm303(void) {
    i2c_handle_accel = i2cOpen(1, LSM303_ACCEL_ADDR, 0);
    if (i2c_handle_accel < 0) {
        fprintf(stderr, "Error opening I2C for accelerometer: %d\n", i2c_handle_accel);
        return -1;
    }

    i2c_handle_mag = i2cOpen(1, LSM303_MAG_ADDR, 0);
    if (i2c_handle_mag < 0) {
        fprintf(stderr, "Error opening I2C for magnetometer: %d\n", i2c_handle_mag);
        i2cClose(i2c_handle_accel);
        i2c_handle_accel = -1;
        return -1;
    }

    /* Accelerometer: 50 Hz, all axes enabled */
    if (i2cWriteByteData(i2c_handle_accel, LSM303_ACCEL_CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Error writing to accelerometer CTRL_REG1_A\n");
        return -1;
    }

    /* Magnetometer: continuous-conversion mode */
    if (i2cWriteByteData(i2c_handle_mag, LSM303_MAG_MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Error writing to magnetometer MR_REG_M\n");
        return -1;
    }

    return 0;
}

static int read_accelerometer(sensor_data_t *data) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle_accel, LSM303_ACCEL_OUT_X_L_A | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }

    int16_t x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t z = (int16_t)((buffer[5] << 8) | buffer[4]);

    data->x = (float)x * ACCEL_SCALE;
    data->y = (float)y * ACCEL_SCALE;
    data->z = (float)z * ACCEL_SCALE;
    return 0;
}

static int read_magnetometer(sensor_data_t *data) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle_mag, LSM303_MAG_OUT_X_H_M, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    int16_t x = (int16_t)((buffer[0] << 8) | buffer[1]);
    int16_t z = (int16_t)((buffer[2] << 8) | buffer[3]);
    int16_t y = (int16_t)((buffer[4] << 8) | buffer[5]);

    data->x = (float)x * MAG_SCALE;
    data->y = (float)y * MAG_SCALE;
    data->z = (float)z * MAG_SCALE;
    return 0;
}

static float calculate_heading(sensor_data_t accel, sensor_data_t mag) {
    float pitch = atan2f(accel.x, sqrtf(accel.y * accel.y + accel.z * accel.z));
    float roll  = atan2f(accel.y, accel.z);

    float mag_x_comp = mag.x * cosf(pitch) + mag.z * sinf(pitch);
    float mag_y_comp = mag.x * sinf(roll) * sinf(pitch) +
                       mag.y * cosf(roll) -
                       mag.z * sinf(roll) * cosf(pitch);

    float heading = atan2f(mag_y_comp, mag_x_comp) * 180.0f / M_PI;
    if (heading < 0) heading += 360.0f;
    return heading;
}

static void log_data(float heading, sensor_data_t accel, sensor_data_t mag) {
    FILE *fp = fopen("compass_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "Timestamp,Heading,Accel_X,Accel_Y,Accel_Z,Mag_X,Mag_Y,Mag_Z\n");
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n",
            timestamp, heading, accel.x, accel.y, accel.z, mag.x, mag.y, mag.z);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_lsm303() != 0) {
        fprintf(stderr, "LSM303 initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    sensor_data_t accel, mag;
    float heading;

    while (running) {
        if (read_accelerometer(&accel) != 0) {
            gpioDelay(100000);
            continue;
        }

        if (read_magnetometer(&mag) != 0) {
            gpioDelay(100000);
            continue;
        }

        heading = calculate_heading(accel, mag);
        log_data(heading, accel, mag);

        gpioDelay(100000);
    }

    if (i2c_handle_accel >= 0) i2cClose(i2c_handle_accel);
    if (i2c_handle_mag >= 0)   i2cClose(i2c_handle_mag);
    gpioTerminate();
    return 0;
}

