#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VL6180X_ADDR 0x29
#define I2C_BUS 1
#define LOG_FILE "distance_log.txt"
#define SAMPLE_INTERVAL_US 100000
#define PROXIMITY_THRESHOLD_MM 100

#define REG_IDENTIFICATION_MODEL_ID 0x016
#define REG_SYSTEM_FRESH_OUT_OF_RESET 0x016
#define REG_SYSRANGE_START 0x000
#define REG_RESULT_RANGE_STATUS 0x04d
#define REG_RESULT_RANGE_VAL 0x062
#define REG_RESULT_INT_STATUS 0x04f
#define REG_RESULT_INT_CLEAR 0x015

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int vl6180x_write_reg(uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(i2c_handle, buf, 3);
}

static int vl6180x_read_reg(uint16_t reg, uint8_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(i2c_handle, buf, 2) < 0) return -1;
    if (i2cReadDevice(i2c_handle, (char *)value, 1) != 1) return -1;
    return 0;
}

static int vl6180x_read_reg16(uint16_t reg, uint16_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(i2c_handle, buf, 2) < 0) return -1;
    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) return -1;
