#include <unistd.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69
#define CTRL_REG 0x00
#define DATA_REG 0x01
#define SAMPLE_INTERVAL_US 10000
#define LOG_FILE "audio_log.dat"

static volatile sig_atomic_t running = 1;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_sensor(int handle) {
    if (i2cWriteByteData(handle, CTRL_REG, 0x80) < 0) {
        fprintf(stderr, "Error writing control register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sensor(int handle, int16_t *sample) {
    int raw = i2cReadWordData(handle, DATA_REG);
    if (raw < 0) {
        fprintf(stderr, "Error reading data register: %s\n", strerror(errno));
        return -1;
    }
    *sample = (int16_t)raw;
    return 0;
}

static void cleanup(void) {
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
        i2c_handle1 = -1;
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
        i2c_handle2 = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register signal handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open I2C device for sensor 1 (0x%02X): %s\n", SENSOR1_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C device for sensor 2 (0x%02X): %s\n", SENSOR2_ADDR, strerror(errno));
        i2cClose(i2c_handle1);
        i2c_handle1 = -1;
        gpioTerminate();
        return 1;
    }

    if (init_sensor(i2c_handle1) < 0 || init_sensor(i2c_handle2) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    fprintf(log_file, "sec,nsec,sensor1,sensor2,tdoa\n");
    fflush(log_file);

    while (running) {
        int16_t s1 = 0, s2 = 0;
        struct timespec ts;
        long long tdoa = 0;

        if (read_sensor(i2c_handle1, &s1) < 0) {
            fprintf(stderr, "Error reading sensor 1, skipping sample\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (read_sensor(i2c_handle2, &s2) < 0) {
            fprintf(stderr, "Error reading sensor 2, skipping sample\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
            fprintf(stderr, "Error getting time: %s\n", strerror(errno));
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        tdoa = (long long)s2 - (long long)s1;

        fprintf(log_file, "%ld,%ld,%d,%d,%lld\n",
                ts.tv_sec, ts.tv_nsec, s1, s2, tdoa);
        fflush(log_file);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

