#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADIS16488A register addresses (7-bit) */
#define X_GYRO_REG    0x04
#define Y_GYRO_REG    0x06
#define Z_GYRO_REG    0x08
#define X_ACCEL_REG   0x0A
#define Y_ACCEL_REG   0x0C
#define Z_ACCEL_REG   0x0E

/* Sensitivities (from ADIS16488A datasheet) */
#define GYRO_SENSITIVITY  0.005f   /* deg/sec/LSB */
#define ACCEL_SENSITIVITY 0.00025f /* g/LSB */

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000      /* 1 MHz */
#define SPI_FLAGS   0b11000000000 /* mode 3: CPHA=1, CPOL=1, aux off */
#define SAMPLE_US   100000       /* 100 ms */
#define STALL_US    40           /* stall between request and data read */

static int spi_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t running = 1;

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (fp != NULL) {
        fclose(fp);
        fp = NULL;
    }
    gpioTerminate();
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Read a 16-bit register from the ADIS16488A.
 * The device returns the requested register's data on the *next*
 * 16-bit transfer after the request word is sent.  We stall for
 * STALL_US microseconds between the request and the data read. */
static int read_register(uint8_t reg, int16_t *out) {
    char tx[2] = { 0x00, (char)(reg & 0x7F) };
    char rx[2] = { 0, 0 };

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X\n", reg);
        return -1;
    }

    gpioDelay(STALL_US);

    tx[0] = 0x00;
    tx[1] = 0x00;
    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI transfer failed for data read of register 0x%02X\n", reg);
        return -1;
    }

    *out = (int16_t)(((uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

static int read_gyro(int16_t *gx, int16_t *gy, int16_t *gz) {
    if (read_register(X_GYRO_REG, gx) != 0) return -1;
    if (read_register(Y_GYRO_REG, gy) != 0) return -1;
    if (read_register(Z_GYRO_REG, gz) != 0) return -1;
    return 0;
}

static int read_accel(int16_t *ax, int16_t *ay, int16_t *az) {
    if (read_register(X_ACCEL_REG, ax) != 0) return -1;
    if (read_register(Y_ACCEL_REG, ay) != 0) return -1;
    if (read_register(Z_ACCEL_REG, az) != 0) return -1;
    return 0;
}

static void log_data(int16_t gx, int16_t gy, int16_t gz,
                     int16_t ax, int16_t ay, int16_t az) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    long ms = ts.tv_nsec / 1000000L;

