/*
 * ADIS16448 IMU reader for Raspberry Pi 4 Model B
 *
 * SPI: bus 0, chip-select GPIO8 (SPI0 CE0), mode 3, up to 1 MHz
 * CS control via libgpiod (gpiochip0 line 8)
 * ADIS16448 single-register read protocol: send addr|0x80, then read data
 *
 * Build: gcc -O2 -Wall -o adis16448 adis16448.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP       "gpiochip0"
#define CS_LINE_OFFSET  8          /* GPIO8 = SPI0 CE0 */

#define SPI_SPEED_HZ    1000000    /* 1 MHz */
#define SPI_MODE        SPI_MODE_3
#define SPI_BITS        8

#define SAMPLE_PERIOD_MS 100

/* ADIS16448 register addresses */
#define XGYRO_OUT  0x04
#define YGYRO_OUT  0x06
#define ZGYRO_OUT  0x08
#define XACCL_OUT  0x0A
#define YACCL_OUT  0x0C
#define ZACCL_OUT  0x0E

/* Scale factors */
#define GYRO_SCALE  0.02f   /* dps per LSB */
#define ACCL_SCALE  0.00025f /* g per LSB */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);
}

/*
 * ADIS16448 single-register read: send [addr|0x80], then read 2 bytes.
 * Returns 0 on success, -1 on error.
 */
static int adis_read_reg16(int spi_fd, struct gpiod_line *cs_line,
                           uint8_t addr, int16_t *out)
{
    uint8_t tx[2] = { (uint8_t)(addr | 0x80), 0x00 };
    uint8_t rx[2] = { 0, 0 };

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "CS low failed: %s\n", strerror(errno));
        return -1;
    }

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 2,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "CS high failed: %s\n", strerror(errno));
        return -1;
    }

    *out = (int16_t)((rx[0] << 8) | rx[1]);
    return 0;
}

static void log_data(float gx, float gy, float gz,
                     float ax, float ay, float az)
{
    printf("Gyro: X=%.2f, Y=%.2f, Z=%.2f dps | "
           "Accel: X=%.4f, Y=%.4f, Z=%.4f g\n",
           gx, gy, gz, ax, ay, az);
    fflush(stdout);
}

int main(void)
{
    int spi_fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *cs_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa = { .sa_handler = sig_handler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open SPI device */
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        goto cleanup;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        goto cleanup;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Open GPIO chip and request CS line */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open(%s) failed: %s\n", GPIO_CHIP, strerror(errno));
        goto cleanup;
    }

    cs_line = gpiod_chip_get_line(chip, CS_LINE_OFFSET);
    if (!cs_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n", CS_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(cs_line, "adis16448-cs", 1) < 0) {
        fprintf(stderr, "gpiod_line_request_output failed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("ADIS16448 IMU reader started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t raw_gx = 0, raw_gy = 0, raw_gz = 0;
        int16_t raw_ax = 0, raw_ay = 0, raw_az = 0;

        if (adis_read_reg16(spi_fd, cs_line, XGYRO_OUT, &raw_gx) < 0) goto cleanup;
        if (adis_read_reg16(spi_fd, cs_line, YGYRO_OUT, &raw_gy) < 0) goto cleanup;
        if (adis_read_reg16(spi_fd, cs_line, ZGYRO_OUT, &raw_gz) < 0) goto cleanup;
        if (adis_read_reg16(spi_fd, cs_line, XACCL_OUT, &raw_ax) < 0) goto cleanup;
        if (adis_read_reg16(spi_fd, cs_line, YACCL_OUT, &raw_ay) < 0) goto cleanup;
        if (adis_read_reg16(spi_fd, cs_line, ZACCL_OUT, &raw_az) < 0) goto cleanup;

        float gx = (float)raw_gx * GYRO_SCALE;
        float gy = (float)raw_gy * GYRO_SCALE;
        float gz = (float)raw_gz * GYRO_SCALE;
        float ax = (float)raw_ax * ACCL_SCALE;
        float ay = (float)raw_ay * ACCL_SCALE;
        float az = (float)raw_az * ACCL_SCALE;

        log_data(gx, gy, gz, ax, ay, az);
        sleep_ms(SAMPLE_PERIOD_MS);
    }

    printf("\nShutting down cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (cs_line) gpiod_line_release(cs_line);
    if (chip)   gpiod_chip_close(chip);
    if (spi_fd >= 0) close(spi_fd);
    return ret;
}

