static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * ADIS16448 SPI read requires two 16-bit transfers.
 * Transfer 1: send read command (reg | 0x8000) then stall for >= 40 us.
 * Transfer 2: send 0x0000 to clock out the 16-bit data.
