    gpioDelay(40);

    /* Perform second transfer: dummy to clock out data */
    tx[0] = 0x00;
    tx[1] = 0x00;
    ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI transfer failed (ret=%d)\n", ret);
        return -1;
    }

