    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADIS16448 IMU Data Acquisition (Ctrl+C to exit)\n");
    printf("------------------------------------------------\n");

    while (running) {
        int16_t gx, gy, gz, ax, ay, az;

