#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

/* ADXL345 I2C address (ALT ADDRESS tied to GND) */
#define ADXL345_ADDRESS 0x53

/* ADXL345 registers */
#define ADXL345_DEVID       0x00
#define ADXL345_POWER_CTL   0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0      0x32
#define ADXL345_DATAX1      0x33
#define ADXL345_DATAY0      0x34
#define ADXL345_DATAY1      0x35
#define ADXL345_DATAZ0      0x36
#define ADXL345_DATAZ1      0x37

/* Expected device ID */
#define ADXL345_DEVID_VALUE 0xE5

/* Full-resolution, +/-2g range -> 256 LSB/g */
#define ADXL345_SCALE_FACTOR 256.0f

/* Impact threshold in g */
#define IMPACT_THRESHOLD 2.5f

/* LED GPIO pin */
#define LED_PIN 17

/* Log file path */
#define LOG_FILE "impact_log.txt"

/* I2C bus on Raspberry Pi Zero W */
#define I2C_BUS 1

/* Polling interval in microseconds */
#define POLL_INTERVAL_US 10000

/* LED on duration in microseconds */
#define LED_ON_DURATION_US 500000

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a byte to an ADXL345 register; returns 0 on success, -1 on   */
/* error.                                                             */
/* ------------------------------------------------------------------ */
static int adxl345_write_reg(uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(g_i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a byte from an ADXL345 register; returns 0 on success, -1 on  */
/* error.                                                             */
/* ------------------------------------------------------------------ */
static int adxl345_read_reg(uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(g_i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the ADXL345: verify device ID, set full-resolution mode  */
/* and measure mode.                                                  */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int adxl345_init(void)
{
    uint8_t devid = 0;

    /* Verify device identity */
    if (adxl345_read_reg(ADXL345_DEVID, &devid) != 0) {
        fprintf(stderr, "Cannot read DEVID register - sensor absent or bus error\n");
