    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an ICM-20602 register; returns 0 on success,    */
/* -1 on failure.                                                    */
/* ------------------------------------------------------------------ */
static int read_reg(uint8_t reg, uint8_t *out)
{
    int v = i2cReadByteData(i2c_handle, reg);
    if (v < 0) {
        fprintf(stderr, "Error: i2cReadByteData failed for reg 0x%02X\n", reg);
        return -1;
    }
    *out = (uint8_t)v;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Burst-read N bytes starting at reg; returns 0 on success, -1 on    */
/* failure.                                                          */
/* ------------------------------------------------------------------ */
static int read_block(uint8_t reg, uint8_t *buf, uint8_t len)
{
    int n = i2cReadI2CBlockData(i2c_handle, reg, (char *)buf, len);
    if (n != len) {
        fprintf(stderr, "Error: i2cReadI2CBlockData failed for reg 0x%02X (got %d, expected %d)\n",
                reg, n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the ICM-20602: verify identity, then wake + configure.  */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int init_icm20602(void)
{
    uint8_t who = 0;

    /* Verify device identity */
    if (read_reg(WHO_AM_I, &who) < 0)
        return -1;
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n",
                who, WHO_AM_I_VAL);
        return -1;
    }

    /* Wake up: clear SLEEP bit in PWR_MGMT_1 */
    if (write_reg(PWR_MGMT_1, 0x00) < 0)
        return -1;
    gpioDelay(10000); /* 10 ms settle */

    /* Accelerometer: +/-2g (AFS_SEL = 0) */
    if (write_reg(ACCEL_CONFIG, 0x00) < 0)
        return -1;

    /* Gyroscope: +/-250 dps (FS_SEL = 0) */
    if (write_reg(GYRO_CONFIG, 0x00) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of accelerometer data (14-bit left-justified).        */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int read_accel(int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (read_block(ACCEL_XOUT_H, buf, 6) < 0)
        return -1;

    /* 14-bit left-justified: shift right 2 to get signed 16-bit */
    *x = (int16_t)((buf[0] << 8) | buf[1]) >> 2;
    *y = (int16_t)((buf[2] << 8) | buf[3]) >> 2;
    *z = (int16_t)((buf[4] << 8) | buf[5]) >> 2;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of gyroscope data (16-bit).                            */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int read_gyro(int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (read_block(GYRO_XOUT_H, buf, 6) < 0)
        return -1;

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one CSV row: timestamp,ax,ay,az,gx,gy,gz                       */
/* ------------------------------------------------------------------ */
static void log_data(int16_t ax, int16_t ay, int16_t az,
                     int16_t gx, int16_t gy, int16_t gz)
{
    time_t rawtime;
    struct tm timeinfo;
    char ts[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%d,%d,%d\n",
            ts, ax, ay, az, gx, gy, gz);
    fflush(log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int16_t ax, ay, az, gx, gy, gz;

    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the ICM-20602 address */
    i2c_handle = i2cOpen(1, ICM20602_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle %d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialise the sensor */
    if (init_icm20602() < 0) {
        fprintf(stderr, "Error: ICM-20602 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open CSV log file in append mode */
    log_file = fopen("imu_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Error: cannot open imu_log.csv for writing\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,accel_x,accel_y,accel_z,gyro_x,gyro_y,gyro_z\n");
        fflush(log_file);
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed\n");
    }

    printf("ICM-20602 logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop at 10 Hz (100 ms interval) */
    while (running) {
        if (read_accel(&ax, &ay, &az) < 0) {
            fprintf(stderr, "Warning: accelerometer read failed, skipping sample\n");
            gpioDelay(100000);
            continue;
        }
        if (read_gyro(&gx, &gy, &gz) < 0) {
            fprintf(stderr, "Warning: gyroscope read failed, skipping sample\n");
            gpioDelay(100000);
            continue;
        }

        log_data(ax, ay, az, gx, gy, gz);
        gpioDelay(100000); /* 100 ms -> 10 Hz */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

