#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <math.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define MMA8451_ADDRESS 0x1D
#define WHO_AM_I 0x0D
#define WHO_AM_I_VAL 0x1A
#define CTRL_REG1 0x2A
#define OUT_X_MSB 0x01
#define LED_PIN 17
#define ACCEL_THRESHOLD 2.0f
#define GYRO_THRESHOLD 0.0f
#define SCALE_FACTOR 1024.0f
#define POLL_DELAY_MS 100
#define LED_ON_MS 500

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read 16-bit from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int init_mma8451(int fd) {
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(fd, WHO_AM_I, &who_am_i) < 0) return -1;
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who_am_i, WHO_AM_I_VAL);
        return -1;
    }
    if (i2c_write_reg8(fd, CTRL_REG1, 0x00) < 0) return -1;
    usleep(10000);
    if (i2c_write_reg8(fd, CTRL_REG1, 0x01) < 0) return -1;
    usleep(10000);
    return 0;
}

static int read_accel(int fd, float *x, float *y, float *z) {
    int16_t raw_x, raw_y, raw_z;
    if (i2c_read_reg16(fd, OUT_X_MSB, &raw_x) < 0) return -1;
    if (i2c_read_reg16(fd, OUT_X_MSB + 2, &raw_y) < 0) return -1;
    if (i2c_read_reg16(fd, OUT_X_MSB + 4, &raw_z) < 0) return -1;
    *x = (float)raw_x / SCALE_FACTOR;
    *y = (float)raw_y / SCALE_FACTOR;
    *z = (float)raw_z / SCALE_FACTOR;
    return 0;
}

static void log_impact(float x, float y, float z) {
    FILE *fp = fopen("impact_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Failed to open impact_log.txt: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s - Impact detected: X=%.2fg, Y=%.2fg, Z=%.2fg\n", ts, x, y, z);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return 1;
    }
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(led_line, "mma8451_led", 0) < 0) {
        fprintf(stderr, "Failed to request LED line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MMA8451_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MMA8451_ADDRESS, strerror(errno));
        close(i2c_fd);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (init_mma8451(i2c_fd) < 0) {
        fprintf(stderr, "MMA8451 initialization failed.\n");
        close(i2c_fd);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("MMA8451 initialized. Monitoring for impacts (threshold: %.1fg)...\n", ACCEL_THRESHOLD);

    while (running) {
        float x, y, z;
        if (read_accel(i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Read error, continuing...\n");
            usleep(POLL_DELAY_MS * 1000);
            continue;
        }
        float mag = sqrtf(x * x + y * y + z * z);
        if (mag > ACCEL_THRESHOLD) {
            printf("Impact detected! Magnitude: %.2fg\n", mag);
            gpiod_line_set_value(led_line, 1);
            log_impact(x, y, z);
            usleep(LED_ON_MS * 1000);
            gpiod_line_set_value(led_line, 0);
        }
        usleep(POLL_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    gpiod_line_set_value(led_line, 0);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

