#define TMAG5273_ADDR 0x35
#define X_REG 0x10
#define Y_REG 0x11
#define Z_REG 0x12
#define I2C_DEV "/dev/i2c-1"
#define LOG_FILE "magnetic_field_log.csv"

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (int16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static int log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int ensure_log_header(FILE *fp) {
    long pos = ftell(fp);
    if (pos < 0) {
        fprintf(stderr, "ftell failed: %s\n", strerror(errno));
        return -1;
    }
    if (pos == 0) {
        if (fprintf(fp, "timestamp,x,y,z\n") < 0) {
            fprintf(stderr, "fprintf header failed: %s\n", strerror(errno));
            return -1;
