#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADIS16266 SPI configuration */
#define SPI_CHANNEL    0
#define SPI_SPEED      1000000  /* 1 MHz */
#define SPI_FLAGS      0x3      /* mode 3: CPOL=1, CPHA=1 */
#define WHO_AM_I_REG   0x00
#define WHO_AM_I_VAL   0x3F5A
#define GYRO_XOUT_REG  0x14
#define GYRO_SCALE     0.0305f  /* degrees/sec per LSB */
#define SAMPLE_PERIOD  10000    /* microseconds (10 ms) */

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* Read a 16-bit register from the ADIS16266.
 * Returns 0 on success, -1 on SPI error, -2 on unexpected data. */
static int read_register(uint8_t reg, uint16_t *value)
{
