#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* GY-50 L3G4200D I2C address (SA0 tied to GND) */
#define GYRO_ADDR 0x69

/* L3G4200D register addresses */
#define WHO_AM_I   0x0F
#define CTRL_REG1  0x20
#define CTRL_REG4  0x23
#define OUT_X_L    0x28

/* Expected device ID */
#define WHO_AM_I_VAL 0xD3

/* Sensitivity for +/- 250 dps full-scale: 8.75 mdps/LSB */
#define SENSITIVITY 114.285f

/* Sampling interval in microseconds */
#define SAMPLE_INTERVAL_US 10000

static volatile sig_atomic_t terminate = 0;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_retry(int handle, uint8_t reg, uint8_t val, int retries) {
    for (int i = 0; i < retries; i++) {
        if (i2cWriteByteData(handle, reg, val) == 0) return 0;
        gpioDelay(1000); /* 1 ms backoff */
    }
    return -1;
}

static int init_gyro(void) {
    int id = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (id < 0) {
        fprintf(stderr, "Error: I2C read failed for WHO_AM_I (pigpio error %d)\n", id);
        return -1;
    }
    if (id != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X). Sensor absent or wrong device.\n",
                id, WHO_AM_I_VAL);
        return -1;
    }

    /* Normal mode, all axes enabled, ODR = 100 Hz (0x0F) */
    if (i2c_write_retry(i2c_handle, CTRL_REG1, 0x0F, 3) != 0) {
        fprintf(stderr, "Error: Failed to write CTRL_REG1\n");
        return -1;
    }

    /* Full-scale = +/- 250 dps (0x00) */
    if (i2c_write_retry(i2c_handle, CTRL_REG4, 0x00, 3) != 0) {
        fprintf(stderr, "Error: Failed to write CTRL_REG4\n");
        return -1;
    }

    return 0;
}

static int read_gyro_data(float *x, float *y, float *z) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error: I2C block read failed (pigpio error %d)\n", result);
        return -1;
    }

    int16_t raw_x = (int16_t)((buffer[1] << 8) | (uint8_t)buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | (uint8_t)buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | (uint8_t)buffer[4]);

    *x = (float)raw_x / SENSITIVITY;
    *y = (float)raw_y / SENSITIVITY;
    *z = (float)raw_z / SENSITIVITY;
    return 0;
}

static void log_data(float x, float y, float z) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[40];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%09ld", ts.tv_nsec);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, GYRO_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (pigpio error %d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_gyro() != 0) {
        fprintf(stderr, "Error: Gyroscope initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("gyro_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open gyro_log.csv\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp,X,Y,Z\n");
    fflush(log_file);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float x, y, z;
    while (!terminate) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            log_data(x, y, z);
        } else {
            fprintf(stderr, "Warning: Read failed, continuing...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    fprintf(stderr, "\nShutting down gracefully...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

