#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MMA8452Q_ADDR        0x1D
#define MMA8452Q_WHO_AM_I    0x0D
#define MMA8452Q_WHO_AM_I_VAL 0x2A
#define MMA8452Q_CTRL_REG1   0x2A
#define MMA8452Q_OUT_X_MSB   0x01
#define MMA8452Q_OUT_X_LSB   0x02
#define MMA8452Q_OUT_Y_MSB   0x03
#define MMA8452Q_OUT_Y_LSB   0x04
#define MMA8452Q_OUT_Z_MSB   0x05
#define MMA8452Q_OUT_Z_LSB   0x06
#define FALL_THRESHOLD       45.0
#define I2C_BUS             "/dev/i2c-1"
#define LOG_FILE            "fall_log.txt"
#define POLL_DELAY_US       10000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (block reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C block read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_mma8452q(int fd) {
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(fd, MMA8452Q_WHO_AM_I, &who_am_i) < 0) {
        return -1;
    }
    if (who_am_i != MMA8452Q_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who_am_i, MMA8452Q_WHO_AM_I_VAL);
        return -1;
    }

    /* Standby mode, 100 Hz data rate (bits 3-5 = 0b010) */
    uint8_t ctrl1 = 0x00 | (0x04 << 3);
    if (i2c_write_reg8(fd, MMA8452Q_CTRL_REG1, ctrl1) < 0) {
        return -1;
    }
    usleep(1000);

    /* Active mode */
    ctrl1 |= 0x01;
    if (i2c_write_reg8(fd, MMA8452Q_CTRL_REG1, ctrl1) < 0) {
        return -1;
    }
    usleep(1000);

    return 0;
}

static int read_accel(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_block(fd, MMA8452Q_OUT_X_MSB, buf, 6) < 0) {
        return -1;
    }

    *x = (int16_t)(((uint16_t)buf[0] << 8) | buf[1]) >> 4;
    *y = (int16_t)(((uint16_t)buf[2] << 8) | buf[3]) >> 4;
    *z = (int16_t)(((uint16_t)buf[4] << 8) | buf[5]) >> 4;

    return 0;
}

static double calc_tilt_angle(int16_t x, int16_t y, int16_t z) {
    double x_d = (double)x / 2048.0;
    double y_d = (double)y / 2048.0;
    double z_d = (double)z / 2048.0;
    return atan2(x_d, sqrt(y_d * y_d + z_d * z_d)) * 180.0 / M_PI;
}

static void log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, X: %d, Y: %d, Z: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MMA8452Q_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MMA8452Q_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    if (init_mma8452q(g_i2c_fd) < 0) {
        fprintf(stderr, "MMA8452Q initialization failed.\n");
        close(g_i2c_fd);
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    printf("MMA8452Q initialized. Monitoring for tilt > %.1f degrees...\n", FALL_THRESHOLD);

    while (g_running) {
        int16_t x, y, z;
        if (read_accel(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Read error, continuing...\n");
            usleep(POLL_DELAY_US);
            continue;
        }

        double angle = calc_tilt_angle(x, y, z);
        if (fabs(angle) > FALL_THRESHOLD) {
            printf("Tilt angle: %.2f degrees (X: %d, Y: %d, Z: %d)\n", angle, x, y, z);
            log_data(g_log_fp, x, y, z);
        }

        usleep(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
    }
    return 0;
}

