#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define LIS3MDL_ADDR   0x1E
#define WHO_AM_I       0x0F
#define WHO_AM_I_VAL   0x3D
#define CTRL_REG1      0x20
#define CTRL_REG2      0x21
#define CTRL_REG3      0x22
#define CTRL_REG4      0x23
#define OUT_X_L        0x28
#define OUT_X_H        0x29
#define OUT_Y_L        0x2A
#define OUT_Y_H        0x2B
#define OUT_Z_L        0x2C
#define OUT_Z_H        0x2D
#define MAG_SENSITIVITY 0.146f  /* mG/LSB at +/-4 gauss */
#define METAL_THRESHOLD 800.0f  /* mG */
#define LOG_FILE       "magnetic_log.txt"
#define SAMPLE_PERIOD  100000   /* 100 ms = 10 Hz */
#define MAX_INIT_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_regs(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_lis3mdl(void) {
    uint8_t who;
    for (int attempt = 0; attempt < MAX_INIT_RETRIES; attempt++) {
        i2c_fd = open(I2C_BUS, O_RDWR);
        if (i2c_fd < 0) {
            fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
            usleep(100000);
            continue;
        }
        if (ioctl(i2c_fd, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
            fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n", LIS3MDL_ADDR, strerror(errno));
            close(i2c_fd);
            i2c_fd = -1;
            usleep(100000);
            continue;
        }
        if (i2c_read_regs(i2c_fd, WHO_AM_I, &who, 1) < 0) {
            close(i2c_fd);
            i2c_fd = -1;
            usleep(100000);
            continue;
        }
        if (who != WHO_AM_I_VAL) {
            fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who, WHO_AM_I_VAL);
            close(i2c_fd);
            i2c_fd = -1;
            usleep(100000);
            continue;
        }
        if (i2c_write_reg(i2c_fd, CTRL_REG1, 0x70) < 0) { close(i2c_fd); i2c_fd = -1; usleep(100000); continue; }
        if (i2c_write_reg(i2c_fd, CTRL_REG2, 0x00) < 0) { close(i2c_fd); i2c_fd = -1; usleep(100000); continue; }
        if (i2c_write_reg(i2c_fd, CTRL_REG3, 0x00) < 0) { close(i2c_fd); i2c_fd = -1; usleep(100000); continue; }
        if (i2c_write_reg(i2c_fd, CTRL_REG4, 0x0C) < 0) { close(i2c_fd); i2c_fd = -1; usleep(100000); continue; }
        printf("LIS3MDL initialized (WHO_AM_I=0x%02X).\n", who);
        return 0;
    }
    fprintf(stderr, "LIS3MDL init failed after %d attempts.\n", MAX_INIT_RETRIES);
    return -1;
}

static int read_magnetometer(float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_regs(i2c_fd, OUT_X_L, buf, 6) < 0) return -1;
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)raw_x * MAG_SENSITIVITY;
    *y = (float)raw_y * MAG_SENSITIVITY;
    *z = (float)raw_z * MAG_SENSITIVITY;
    return 0;
}

static void log_data(FILE *fp, float x, float y, float z) {
    fprintf(fp, "%.2f,%.2f,%.2f\n", x, y, z);
    fflush(fp);
}

static void check_metal_detector(float x, float y, float z) {
    float mag = sqrtf(x * x + y * y + z * z);
    if (mag > METAL_THRESHOLD) {
        fprintf(stderr, "METAL DETECTED! Mag=%.2f mG (X=%.2f Y=%.2f Z=%.2f)\n", mag, x, y, z);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_lis3mdl() < 0) return EXIT_FAILURE;

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("Logging to %s at 10 Hz. Press Ctrl+C to stop.\n", LOG_FILE);

    while (running) {
        float x, y, z;
        if (read_magnetometer(&x, &y, &z) < 0) {
            fprintf(stderr, "Read error; re-initializing sensor.\n");
            init_lis3mdl();
            if (i2c_fd < 0) {
                fprintf(stderr, "Re-init failed; exiting.\n");
                break;
            }
            continue;
        }
        log_data(log_fp, x, y, z);
        check_metal_detector(x, y, z);
        usleep(SAMPLE_PERIOD);
    }

    if (log_fp) fclose(log_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

