#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// ADXL354B Register Addresses
#define ADXL354B_REG_DEVID_AD   0x00
#define ADXL354B_REG_PARTID     0x01
#define ADXL354B_REG_XDATA_L    0x08
#define ADXL354B_REG_XDATA_H    0x09
#define ADXL354B_REG_XDATA_XL   0x0A
#define ADXL354B_REG_YDATA_L    0x0B
#define ADXL354B_REG_YDATA_H    0x0C
#define ADXL354B_REG_YDATA_YL   0x0D
#define ADXL354B_REG_ZDATA_L    0x0E
#define ADXL354B_REG_ZDATA_H    0x0F
#define ADXL354B_REG_ZDATA_ZL   0x10
#define ADXL354B_REG_STATUS     0x04
#define ADXL354B_REG_POWER_CTL  0x2D
#define ADXL354B_REG_RESET      0x1F

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000 // 1 MHz
#define SPI_FLAGS   0       // Mode 0, active low CS

// ADXL354B Constants
#define ADXL354B_PARTID 0x1D
#define ADXL354B_SENSITIVITY 0.0000039f // 3.9 microg/LSB for +-2g range
#define ADXL354B_RESET_CMD 0x52
#define ADXL354B_MEAS_DELAY_US 1000 // 1 ms
#define ADXL354B_STABLE_TIMEOUT_US 100000 // 100 ms

// Global variables for cleanup
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Function to read a single register from the ADXL354B
int read_register(int handle, uint8_t reg, uint8_t *value) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg | 0x80; // Set MSB for read
    tx_buf[1] = 0x00;       // Dummy byte

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 2) {
        return -1;
    }

    *value = (uint8_t)rx_buf[1];
    return 0;
}

// Function to write a single register to the ADXL354B
int write_register(int handle, uint8_t reg, uint8_t value) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg & 0x7F; // Clear MSB for write
    tx_buf[1] = value;

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 2) {
        return -1;
    }

    return 0;
}

// Function to read multiple bytes from the ADXL354B
int read_multi_bytes(int handle, uint8_t reg, uint8_t *data, int len) {
    char tx_buf[1 + 3];
    char rx_buf[1 + 3];

    tx_buf[0] = reg | 0x80 | 0x40; // Set MSB for read, bit 6 for multi-byte
    memset(tx_buf + 1, 0x00, 3);

    if (spiXfer(handle, tx_buf, rx_buf, 4) != 4) {
        return -1;
    }

    memcpy(data, rx_buf + 1, len);
    return 0;
}

// Function to initialize the ADXL354B
int initialize_adxl354b(int handle) {
    uint8_t part_id;

    // Check sensor presence by reading PARTID
    if (read_register(handle, ADXL354B_REG_PARTID, &part_id) != 0) {
        fprintf(stderr, "Error: Failed to read PARTID\n");
        return -1;
    }

    if (part_id != ADXL354B_PARTID) {
        fprintf(stderr, "Error: Incorrect PARTID (0x%02X, expected 0x%02X)\n", part_id, ADXL354B_PARTID);
        return -1;
    }

    printf("ADXL354B detected (PARTID: 0x%02X)\n", part_id);

    // Reset the device
    if (write_register(handle, ADXL354B_REG_RESET, ADXL354B_RESET_CMD) != 0) {
        fprintf(stderr, "Error: Failed to reset ADXL354B\n");
        return -1;
    }
    gpioDelay(ADXL354B_MEAS_DELAY_US);

    // Wait for device to become stable
    uint8_t status;
    int timeout = 0;
    do {
        if (read_register(handle, ADXL354B_REG_STATUS, &status) != 0) {
            fprintf(stderr, "Error: Failed to read STATUS\n");
            return -1;
        }
        gpioDelay(1000); // 1 ms
        timeout += 1;
    } while ((status & 0x02) == 0 && timeout < ADXL354B_STABLE_TIMEOUT_US);

    if (timeout >= ADXL354B_STABLE_TIMEOUT_US) {
        fprintf(stderr, "Error: ADXL354B did not become stable\n");
        return -1;
    }

    // Set measurement mode (clear RUN bit, then set RUN bit)
    if (write_register(handle, ADXL354B_REG_POWER_CTL, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to clear RUN bit\n");
        return -1;
    }
    gpioDelay(1000);
    if (write_register(handle, ADXL354B_REG_POWER_CTL, 0x02) != 0) {
        fprintf(stderr, "Error: Failed to set RUN bit\n");
        return -1;
    }
    gpioDelay(ADXL354B_MEAS_DELAY_US);

    return 0;
}

// Function to read acceleration data from the ADXL354B
int read_acceleration(int handle, float *x, float *y, float *z) {
    uint8_t x_data[3];
    uint8_t y_data[3];
    uint8_t z_data[3];

    if (read_multi_bytes(handle, ADXL354B_REG_XDATA_L, x_data, 3) != 0) {
        fprintf(stderr, "Error: Failed to read X data\n");
        return -1;
    }
    if (read_multi_bytes(handle, ADXL354B_REG_YDATA_L, y_data, 3) != 0) {
        fprintf(stderr, "Error: Failed to read Y data\n");
        return -1;
    }
    if (read_multi_bytes(handle, ADXL354B_REG_ZDATA_L, z_data, 3) != 0) {
        fprintf(stderr, "Error: Failed to read Z data\n");
        return -1;
    }

    // Combine the 3 bytes into a 20-bit signed integer
    int32_t x_raw = (int32_t)((x_data[1] << 8) | x_data[0]) << 4;
    int32_t y_raw = (int32_t)((y_data[1] << 8) | y_data[0]) << 4;
    int32_t z_raw = (int32_t)((z_data[1] << 8) | z_data[0]) << 4;

    // Sign extend the 20-bit value to 32-bit
    if (x_raw & 0x80000) x_raw |= 0xFFF00000;
    if (y_raw & 0x80000) y_raw |= 0xFFF00000;
    if (z_raw & 0x80000) z_raw |= 0xFFF00000;

    // Convert to g's
    *x = (float)x_raw * ADXL354B_SENSITIVITY;
    *y = (float)y_raw * ADXL354B_SENSITIVITY;
    *z = (float)z_raw * ADXL354B_SENSITIVITY;

    return 0;
}

// Function to log data to a file
void log_data(FILE *fp, float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s, X: %.6f g, Y: %.6f g, Z: %.6f g\n", timestamp, x, y, z);
    fflush(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL354B
    if (initialize_adxl354b(spi_handle) != 0) {
        fprintf(stderr, "Error: ADXL354B initialisation failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("vibration_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float x, y, z;

    // Main loop
    while (!terminate) {
        if (read_acceleration(spi_handle, &x, &y, &z) == 0) {
            log_data(log_file, x, y, z);
        } else {
            fprintf(stderr, "Error: Failed to read acceleration data\n");
        }
        gpioDelay(100000); // 100 ms
    }

    // Cleanup
    if (log_file) fclose(log_file);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

