/* ADIS16362 Register Addresses */
#define X_GYRO   0x04
#define Y_GYRO   0x06
#define Z_GYRO   0x08
#define X_ACCL   0x0A
#define Y_ACCL   0x0C
#define Z_ACCL   0x0E

/* Scaling factors */
#define GYRO_SCALE  0.05f   /* deg/sec/LSB */
#define ACCL_SCALE  0.0025f /* g/LSB */

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_BAUD    1000000 /* 1 MHz */
#define SPI_FLAGS   0x03    /* Mode 3: active-high clock, sampled on trailing edge */

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Read a 16-bit register from the ADIS16362 via SPI.
 * The ADIS16362 read protocol: send (reg | 0x80), dummy byte, then read 2 bytes.
 * Returns 0 on success, -1 on SPI transfer failure. */
static int read_adis16362_register(uint8_t reg, int16_t *value) {
    char tx_buf[3];
    char rx_buf[3];
    int ret;

    /* Build the read command: register address with MSB set */
    tx_buf[0] = (char)(reg | 0x80);
    tx_buf[1] = 0x00; /* dummy byte to trigger conversion */
    tx_buf[2] = 0x00; /* dummy byte for clocking out data */

    /* Perform the 3-byte transfer to read the 16-bit register */
    ret = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI read error for register 0x%02X: spiXfer returned %d\n", reg, ret);
        return -1;
    }

    /* The 16-bit data is returned in the last two bytes of the response */
    *value = (int16_t)(((uint8_t)rx_buf[2] << 8) | (uint8_t)rx_buf[1]);
    return 0;
}

/* Read a specific register and scale the raw value */
static int read_scaled_data(uint8_t reg, float scale, float *value) {
    int16_t raw;
    if (read_adis16362_register(reg, &raw) != 0) {
        return -1;
    }
    *value = (float)raw * scale;
    return 0;
}

/* Log data to the CSV file */
static int log_data(float x_gyro, float y_gyro, float z_gyro,
                    float x_accl, float y_accl, float z_accl) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return -1;
    }

    if (fprintf(log_file, "%ld.%09ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
                (long)ts.tv_sec, ts.tv_nsec,
                x_gyro, y_gyro, z_gyro,
                x_accl, y_accl, z_accl) < 0) {
        fprintf(stderr, "fprintf to log file failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
