    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open imu_log.csv: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header if the file is newly created (size == 0) */
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");
        fflush(log_file);
    }

    /* Register signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("ADIS16362 IMU logging started. Press Ctrl+C to stop.\n");

    /* Main loop */
    while (!terminate) {
        float x_gyro, y_gyro, z_gyro, x_accl, y_accl, z_accl;

        if (read_scaled_data(X_GYRO, GYRO_SCALE, &x_gyro) != 0 ||
            read_scaled_data(Y_GYRO, GYRO_SCALE, &y_gyro) != 0 ||
            read_scaled_data(Z_GYRO, GYRO_SCALE, &z_gyro) != 0 ||
            read_scaled_data(X_ACCL, ACCL_SCALE, &x_accl) != 0 ||
            read_scaled_data(Y_ACCL, ACCL_SCALE, &y_accl) != 0 ||
            read_scaled_data(Z_ACCL, ACCL_SCALE, &z_accl) != 0) {
            fprintf(stderr, "Error reading sensor data, skipping log entry.\n");
        } else {
            if (log_data(x_gyro, y_gyro, z_gyro, x_accl, y_accl, z_accl) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        }

        gpioDelay(10000); /* 10 ms delay for ~100 Hz sampling */
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

