/*
 * KY-032 IR Obstacle Avoidance Sensor Reader (libgpiod v2)
 * Board:  Raspberry Pi 3 Model B+
 * Sensors: Keyes KY-032 x2 (active-low: 0 = obstacle, 1 = clear)
 * Pins:    GPIO17 (BCM 11, physical pin 11) and GPIO27 (BCM 13, physical pin 13)
 * Build:   gcc -Wall -Wextra -O2 -o ky032_reader ky032_reader.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO17          17
#define GPIO27          27
#define POLL_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void print_timestamp(void)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char buf[32];

    if (localtime_r(&now, &tm_info) != NULL &&
        strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info) > 0) {
        printf("[%s] ", buf);
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_request *request = NULL;
    struct gpiod_line_settings *settings = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_request_config *req_cfg = NULL;
    unsigned int offsets[2] = { GPIO17, GPIO27 };
    int ret = EXIT_FAILURE;

    /* --- Install SIGINT handler for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open the GPIO chip --- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Configure both lines as inputs --- */
    settings = gpiod_line_settings_new();
    if (settings == NULL) {
        fprintf(stderr, "gpiod_line_settings_new() failed: %s\n", strerror(errno));
        goto cleanup;
    }

    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);

    line_cfg = gpiod_line_config_new();
    if (line_cfg == NULL) {
        fprintf(stderr, "gpiod_line_config_new() failed: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_config_add_line_settings(line_cfg, offsets, 2, settings) != 0) {
        fprintf(stderr, "gpiod_line_config_add_line_settings() failed: %s\n", strerror(errno));
        goto cleanup;
    }

    req_cfg = gpiod_request_config_new();
    if (req_cfg == NULL) {
        fprintf(stderr, "gpiod_request_config_new() failed: %s\n", strerror(errno));
        goto cleanup;
    }
    gpiod_request_config_set_consumer(req_cfg, "ky032-reader");

    request = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (request == NULL) {
        fprintf(stderr, "Failed to request GPIO lines %u and %u: %s\n",
                GPIO17, GPIO27, strerror(errno));
        goto cleanup;
    }

    printf("KY-032 obstacle avoidance reader started (GPIO17, GPIO27).\n");
    printf("Press Ctrl+C to exit.\n");

    /* --- Main polling loop --- */
    while (g_running) {
        enum gpiod_line_value values[2];
        int rc = gpiod_line_request_get_values(request, values);
        if (rc != 0) {
            fprintf(stderr, "gpiod_line_request_get_values() failed: %s\n",
                    strerror(errno));
            break;
        }

        /* KY-032 is active-low: 0 => obstacle detected */
        int obstacle17 = (values[0] == GPIOD_LINE_VALUE_INACTIVE) ? 1 : 0;
        int obstacle27 = (values[1] == GPIOD_LINE_VALUE_INACTIVE) ? 1 : 0;

        print_timestamp();
        printf("GPIO17: %s  GPIO27: %s\n",
               obstacle17 ? "OBSTACLE" : "clear",
               obstacle27 ? "OBSTACLE" : "clear");
        fflush(stdout);

        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (request) gpiod_line_request_release(request);
    if (req_cfg)  gpiod_request_config_free(req_cfg);
    if (line_cfg) gpiod_line_config_free(line_cfg);
    if (settings) gpiod_line_settings_free(settings);
    if (chip)     gpiod_chip_close(chip);

    return ret;
}

