#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* LSM6DSR I2C 7-bit address (SA0 tied to GND) */
#define LSM6DSR_ADDR 0x6B

/* LSM6DSR register addresses */
#define WHO_AM_I       0x0F
#define CTRL1_XL       0x10
#define CTRL2_G        0x11
#define OUTX_L_G       0x22
#define WHO_AM_I_VAL   0x6B

/* Sensitivities at default full-scale ranges */
#define GYRO_SENSITIVITY 0.00875f   /* dps/LSB  (+/-250 dps, 16-bit) */
#define ACCEL_SENSITIVITY 0.000061f /* g/LSB  (+/-2g, 16-bit) */

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

static int i2c_write_reg(uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

static int i2c_read_burst(uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(i2c_handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "Error: i2cReadI2CBlockData(reg=0x%02X, len=%u) returned %d\n",
                reg, len, rc);
        return -1;
    }
    return 0;
}

static int init_lsm6dsr(void)
{
    int who = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error: failed to read WHO_AM_I register: %d\n", who);
        return -1;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, WHO_AM_I_VAL);
        return -1;
    }

    /* Accelerometer: 104 Hz, +/-2g (ODR_XL=0100, FS_XL=00) -> 0x42 */
    if (i2c_write_reg(CTRL1_XL, 0x42) < 0)
        return -1;

    /* Gyroscope: 104 Hz, +/-250 dps (ODR_G=0100, FS_G=00) -> 0x42 */
    if (i2c_write_reg(CTRL2_G, 0x42) < 0)
        return -1;

    return 0;
}

static int read_sensor_data(float *gx, float *gy, float *gz,
                            float *ax, float *ay, float *az)
{
    uint8_t buf[12];

    /* Burst read 12 bytes: G_X_L, G_X_H, G_Y_L, G_Y_H, G_Z_L, G_Z_H,
       A_X_L, A_X_H, A_Y_L, A_Y_H, A_Z_L, A_Z_H */
    if (i2c_read_burst(OUTX_L_G, buf, sizeof(buf)) < 0)
        return -1;

    int16_t raw_gx = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_gy = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_gz = (int16_t)((buf[5] << 8) | buf[4]);
    int16_t raw_ax = (int16_t)((buf[7] << 8) | buf[6]);
    int16_t raw_ay = (int16_t)((buf[9] << 8) | buf[8]);
    int16_t raw_az = (int16_t)((buf[11] << 8) | buf[10]);

    *gx = (float)raw_gx * GYRO_SENSITIVITY;
    *gy = (float)raw_gy * GYRO_SENSITIVITY;
    *gz = (float)raw_gz * GYRO_SENSITIVITY;
    *ax = (float)raw_ax * ACCEL_SENSITIVITY;
    *ay = (float)raw_ay * ACCEL_SENSITIVITY;
    *az = (float)raw_az * ACCEL_SENSITIVITY;

    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
