#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* FXOS8700 I2C address (SA0 tied to GND on Adafruit breakout) */
#define FXOS8700_ADDR 0x1D

/* FXOS8700 register addresses */
#define FXOS8700_WHO_AM_I   0x0D
#define FXOS8700_WHO_AM_I_VAL 0xC7
#define FXOS8700_CTRL_REG1  0x2A
#define FXOS8700_CTRL_REG2  0x2B
#define FXOS8700_M_CTRL_REG1 0x5B
#define FXOS8700_M_CTRL_REG2 0x5C
#define FXOS8700_OUT_X_MSB  0x01

/* I2C bus on Raspberry Pi 4 Model B (GPIO2 = SDA, GPIO3 = SCL) */
#define I2C_BUS 1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* Write one byte to an FXOS8700 register; returns 0 on success, -1 on error. */
static int fxos_write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to reg 0x%02X (pigpio rc=%d)\n",
                value, reg, rc);
        return -1;
    }
    return 0;
}

/* Read one byte from an FXOS8700 register; returns byte value (0-255) or -1 on error. */
static int fxos_read_reg(int handle, uint8_t reg) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X (pigpio rc=%d)\n", reg, rc);
        return -1;
    }
    return rc;
}

/* Initialize the FXOS8700 in hybrid mode (accelerometer + magnetometer). */
static int fxos_init(int handle) {
    /* Verify device identity */
    int who = fxos_read_reg(handle, FXOS8700_WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Cannot read WHO_AM_I — sensor not present or bus error\n");
        return -1;
    }
    if (who != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, FXOS8700_WHO_AM_I_VAL);
        return -1;
    }

    /* Standby mode so configuration changes take effect */
    if (fxos_write_reg(handle, FXOS8700_CTRL_REG1, 0x00) < 0) return -1;
    if (fxos_write_reg(handle, FXOS8700_M_CTRL_REG1, 0x1F) < 0) return -1;
    if (fxos_write_reg(handle, FXOS8700_M_CTRL_REG2, 0x20) < 0) return -1;
    if (fxos_write_reg(handle, FXOS8700_CTRL_REG1, 0x01) < 0) return -1; /* Active mode */

    return 0;
}

/* Read 12 bytes of combined accelerometer + magnetometer data. */
static int fxos_read_data(int handle, int16_t *ax, int16_t *ay, int16_t *az,
                          int16_t *mx, int16_t *my, int16_t *mz) {
    char buffer[12];

    int rc = i2cReadI2CBlockData(handle, FXOS8700_OUT_X_MSB, buffer, 12);
    if (rc != 12) {
        fprintf(stderr, "Error reading data block (rc=%d)\n", rc);
        return -1;
    }

    /* Accel: 14-bit left-aligned, two's complement, 6 bytes */
    *ax = (int16_t)(((uint16_t)buffer[0] << 8) | (uint8_t)buffer[1]) >> 2;
    *ay = (int16_t)(((uint16_t)buffer[2] << 8) | (uint8_t)buffer[3]) >> 2;
    *az = (int16_t)(((uint16_t)buffer[4] << 8) | (uint8_t)buffer[5]) >> 2;

    /* Mag: 16-bit two's complement, 6 bytes starting at buffer[6] */
    *mx = (int16_t)(((uint16_t)buffer[6] << 8) | (uint8_t)buffer[7]);
    *my = (int16_t)(((uint16_t)buffer[8] << 8) | (uint8_t)buffer[9]);
    *mz = (int16_t)(((uint16_t)buffer[10] << 8) | (uint8_t)buffer[11]);

    return 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the FXOS8700 address */
    g_i2c_handle = i2cOpen(I2C_BUS, FXOS8700_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X (rc=%d)\n",
                I2C_BUS, FXOS8700_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (fxos_init(g_i2c_handle) < 0) {
        fprintf(stderr, "FXOS8700 initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("FXOS8700 ready. Logging every 100 ms. Press Ctrl+C to stop.\n");

    int consecutive_errors = 0;

    while (g_running) {
        int16_t ax, ay, az, mx, my, mz;

        if (fxos_read_data(g_i2c_handle, &ax, &ay, &az, &mx, &my, &mz) == 0) {
            consecutive_errors = 0;
            printf("Accel: X=%6d  Y=%6d  Z=%6d  |  Mag: X=%6d  Y=%6d  Z=%6d\n",
                   ax, ay, az, mx, my, mz);
        } else {
            consecutive_errors++;
            fprintf(stderr, "Read failed (%d consecutive)\n", consecutive_errors);
            if (consecutive_errors >= 10) {
                fprintf(stderr, "Too many consecutive errors — attempting reinit\n");
                fxos_init(g_i2c_handle);
                consecutive_errors = 0;
            }
        }

        gpioDelay(100000); /* 100 ms in microseconds */
    }

    /* Clean shutdown */
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

