        fprintf(stderr, "Error: Failed to set I2C slave address 0x%02X: %s\n", ADXL345_ADDRESS, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (init_adxl345(i2c_fd) < 0) {
        fprintf(stderr, "Error: ADXL345 initialization failed. Sensor may be absent or bus error.\n");
        close(i2c_fd);
        return 1;
