#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define SOUND_SENSOR_GPIO 17
#define SAMPLE_INTERVAL_US 1000
#define WINDOW_DURATION_S 5
#define WINDOW_SAMPLES (WINDOW_DURATION_S * 1000 / SAMPLE_INTERVAL_US)
#define ALERT_DELAY_S 1

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }
    if (gpioSetMode(SOUND_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SOUND_SENSOR_GPIO);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int read_sound_level(void) {
    return gpioRead(SOUND_SENSOR_GPIO);
}

static int calculate_sound_level(void) {
    int high_count = 0;
    for (int i = 0; i < WINDOW_SAMPLES && program_running; i++) {
        if (read_sound_level() == 1) {
            high_count++;
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    return high_count;
}

static void check_threshold(int sound_level, int threshold) {
    if (sound_level > threshold) {
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("%s - ALERT: Sound level exceeded threshold!\n", timestamp);
        fflush(stdout);
    } else {
        printf("Sound level within normal range.\n");
        fflush(stdout);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return EXIT_FAILURE;
    }

    char *endptr;
    long threshold = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0' || threshold <= 0) {
        fprintf(stderr, "Error: threshold must be a positive integer.\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Sound monitoring started. Threshold: %ld high readings in %d seconds.\n",
           threshold, WINDOW_DURATION_S);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (program_running) {
        int sound_level = calculate_sound_level();
        check_threshold(sound_level, threshold);
        if (program_running) {
            sleep(ALERT_DELAY_S);
        }
    }

    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

