/*
 * door_access.c — Raspberry Pi 4 Model B
 *
 * Controls two 12V electromagnetic door locks via 5V relay modules
 * (TIP120 + relay on GPIO17 = Door A, GPIO27 = Door B) using libgpiod.
 *
 * Build:  gcc -Wall -o door_access door_access.c -lgpiod
 * Run:    ./door_access
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <gpiod.h>

#define DOOR_A_PIN  17
#define DOOR_B_PIN  27
#define CODE_LEN    6
#define UNLOCK_SEC  5
#define LOG_FILE    "access_log.txt"

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int generate_code(char *buf, size_t len)
{
    if (len < CODE_LEN) return -1;
    for (int i = 0; i < CODE_LEN; i++)
        buf[i] = '0' + (rand() % 10);
    buf[CODE_LEN] = '\0';
    return 0;
}

static int unlock_door(struct gpiod_line *line, const char *name)
{
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO %d HIGH for %s\n", gpiod_line_offset(line), name);
        return -1;
    }
    sleep(UNLOCK_SEC);
    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Failed to set GPIO %d LOW for %s\n", gpiod_line_offset(line), name);
        return -1;
    }
    return 0;
}

static int log_access(const char *code)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, code);
    fclose(fp);
    return 0;
}

int main(void)
{
    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    srand((unsigned)time(NULL));

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    struct gpiod_line *line_a = gpiod_chip_get_line(chip, DOOR_A_PIN);
    if (!line_a) {
        perror("gpiod_chip_get_line(DOOR_A_PIN)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct gpiod_line *line_b = gpiod_chip_get_line(chip, DOOR_B_PIN);
    if (!line_b) {
        perror("gpiod_chip_get_line(DOOR_B_PIN)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line_a, "door_access", 0) < 0) {
        perror("gpiod_line_request_output(DOOR_A_PIN)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line_b, "door_access", 0) < 0) {
        perror("gpiod_line_request_output(DOOR_B_PIN)");
        gpiod_line_release(line_a);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    char code[CODE_LEN + 1];
    if (generate_code(code, sizeof(code)) != 0) {
        fprintf(stderr, "Failed to generate initial code\n");
        gpiod_line_release(line_a);
        gpiod_line_release(line_b);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    printf("Generated security code: %s\n", code);

    while (g_running) {
        printf("Enter %d-digit code: ", CODE_LEN);
        fflush(stdout);

        char input[CODE_LEN + 1];
        if (!fgets(input, sizeof(input), stdin)) {
            if (feof(stdin)) {
                printf("\nEOF received, exiting.\n");
                break;
            }
            perror("fgets");
            continue;
        }

        /* Strip trailing newline */
        input[strcspn(input, "\r\n")] = '\0';

        if (strlen(input) != CODE_LEN) {
            printf("Invalid length, please enter %d digits.\n", CODE_LEN);
            continue;
        }

        for (int i = 0; input[i]; i++) {
            if (!isdigit((unsigned char)input[i])) {
                printf("Invalid character '%c' at position %d\n", input[i], i + 1);
                continue;
            }
        }

        if (strcmp(input, code) == 0) {
            printf("Access granted!\n");
            if (unlock_door(line_a, "Door A") != 0)
                fprintf(stderr, "Warning: unlock failed for Door A\n");
            if (unlock_door(line_b, "Door B") != 0)
                fprintf(stderr, "Warning: unlock failed for Door B\n");
            if (log_access(code) != 0)
                fprintf(stderr, "Warning: failed to log access\n");
            if (generate_code(code, sizeof(code)) != 0) {
                fprintf(stderr, "Warning: failed to generate new code\n");
                code[0] = '0';
            } else {
                printf("New code: %s\n", code);
            }
        } else {
            printf("Access denied.\n");
        }
    }

    /* Clean shutdown: lock both doors */
    gpiod_line_set_value(line_a, 0);
    gpiod_line_set_value(line_b, 0);

    gpiod_line_release(line_a);
    gpiod_line_release(line_b);
    gpiod_chip_close(chip);

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

