#include <errno.h>
#include <string.h>

#define BH1750_ADDR 0x23
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "light_log.txt"
#define CONVERSION_TIME_MS 180
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_bh1750(int fd, float *lux) {
    uint8_t cmd = 0x21; // One-Time High-Resolution Mode 2
    uint8_t buf[2];
    struct timespec ts = {0, CONVERSION_TIME_MS * 1000000L};

    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    nanosleep(&ts, NULL);

    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

int log_data(const char *filename, float lux) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "Timestamp: %s, Lux: %.2f\n", timestamp, lux);
    fclose(fp);
    return 0;
}

int main() {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    printf("Starting BH1750 light sensor logging. Press Ctrl+C to exit.\n");

    while (running) {
        float lux;
        if (read_bh1750(fd, &lux) == 0) {
            if (log_data(LOG_FILE, lux) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }
        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nExiting gracefully.\n");
    close(fd);
    return 0;
}

