#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HMC5883L_ADDR 0x1E

#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE     0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Y_MSB 0x07

#define SAMPLE_WINDOW_SIZE 100
#define SAMPLE_DELAY_US 500000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int hmc5883l_write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to reg 0x%02X (rc=%d)\n", value, reg, rc);
    }
    return rc;
}

static int hmc5883l_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "Error reading block from reg 0x%02X (rc=%d)\n", reg, rc);
    }
    return rc;
}

static int init_hmc5883l(int handle) {
    if (hmc5883l_write_reg(handle, HMC5883L_CONFIG_A, 0x70) < 0) return -1;
    if (hmc5883l_write_reg(handle, HMC5883L_CONFIG_B, 0x20) < 0) return -1;
    if (hmc5883l_write_reg(handle, HMC5883L_MODE, 0x00) < 0) return -1;
    return 0;
}

static void compute_offsets(int handle, int *x_off, int *y_off, int *z_off) {
    int32_t x_sum = 0, y_sum = 0, z_sum = 0;
    int valid = 0;

    for (int i = 0; i < SAMPLE_WINDOW_SIZE; i++) {
        uint8_t buf[6];
        if (hmc5883l_read_block(handle, HMC5883L_DATA_X_MSB, buf, 6) < 0) {
            continue;
        }
        int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
        int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
        int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);

        x_sum += raw_x;
        y_sum += raw_y;
        z_sum += raw_z;
        valid++;
        if (i == SAMPLE_WINDOW_SIZE - 1) break;
        gpioDelay(10000);
    }

    if (valid == 0) {
        fprintf(stderr, "Warning: no valid samples for offset computation\n");
        return;
    }

    *x_off = x_sum / valid;
    *y_off = y_sum / valid;
    *z_off = z_sum / valid;
}

static void correct_reading(int handle, int x_off, int y_off, int z_off, int *cx, int *cy, int *cz) {
    uint8_t buf[6];
    if (hmc5883l_read_block(handle, HMC5883L_DATA_X_MSB, buf, 6) < 0) {
        *cx = *cy = *cz = 0;
        return;
    }
    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    *cx = raw_x - x_off;
    *cy = raw_y - y_off;
    *cz = raw_z - z_off;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at 0x%02X (rc=%d)\n", HMC5883L_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_hmc5883l(i2c_handle) < 0) {
        fprintf(stderr, "Error initializing HMC5883L\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int x_off = 0, y_off = 0, z_off = 0;
    int cx, cy, cz;

    while (running) {
        compute_offsets(i2c_handle, &x_off, &y_off, &z_off);
        correct_reading(i2c_handle, x_off, y_off, z_off, &cx, &cy, &cz);
        printf("Corrected: X=%d, Y=%d, Z=%d\n", cx, cy, cz);
        fflush(stdout);
        gpioDelay(SAMPLE_DELAY_US);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

