code:
/*
 * LSM303D accelerometer monitor with GPIO interrupt line event handling.
 *
 * Board:  Raspberry Pi Zero W
 * I2C:    /dev/i2c-1, LSM303D @ 0x1D (SA0 tied high)
 * INT1:   GPIO23 (BCM 23, physical pin 16) — rising-edge interrupt
 *
 * Build:  gcc -O2 -Wall -Wextra -o lsm303d_mon lsm303d_mon.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

/* ---- LSM303D constants ---- */
#define LSM303D_ADDR        0x1D
#define WHO_AM_I            0x0F
#define WHO_AM_I_VAL        0x49
#define CTRL_REG1_A         0x20
#define CTRL_REG4_A         0x23
#define INT1_CFG            0x30
#define INT1_THS_A          0x31
#define INT1_DURATION_A     0x32
#define OUT_X_L_A           0x28

/* CTRL_REG1: ODR=50 Hz (0x50), all axes enabled (0x07) -> 0x57 */
#define CTRL_REG1_VAL       0x57
/* CTRL_REG4: FS=+-2g (0x00), HR off, BW=50 Hz, ST off -> 0x00 */
#define CTRL_REG4_VAL       0x00
/* INT1_CFG: enable all axes, active-high, push-pull, latching -> 0x2A */
#define INT1_CFG_VAL        0x2A
/* INT1_THS: threshold 2000 mg (0x7D = 2000/16) */
#define INT1_THS_VAL        0x7D
/* INT1_DURATION: 0 = immediate, no latch */
#define INT1_DURATION_VAL   0x00

/* ---- Application constants ---- */
#define I2C_DEV             "/dev/i2c-1"
#define GPIO_CHIP           "gpiochip4"   /* BCM GPIO 23 on Pi Zero W */
#define GPIO_OFFSET         23            /* BCM 23 */
#define BUFFER_SIZE         64
#define PRINT_COUNT         10
#define POLL_DELAY_US       10000         /* 10 ms */

/* ---- Data structures ---- */
typedef struct {
    int16_t x, y, z;
} accel_data_t;

typedef struct {
    accel_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static struct gpiod_chip  *g_chip = NULL;
static struct gpiod_line  *g_line = NULL;

/* ---- Signal handler ---- */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    if (i2c_smbus_write_byte_data(fd, reg, val) < 0) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    int r = i2c_smbus_read_byte_data(fd, reg);
    if (r < 0) {
        fprintf(stderr, "I2C read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint8_t)r;
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len)
{
    struct i2c_smbus_ioctl_data args;
    union i2c_smbus_data data;

    args.read_write = I2C_SMBUS_READ;
    args.command    = reg;
    args.size       = I2C_SMBUS_BLOCK_DATA;
    args.data       = &data;

    if (ioctl(fd, I2C_SMBUS, &args) < 0) {
        fprintf(stderr, "I2C block read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    int n = data.block[0];
    if (n != len) {
        fprintf(stderr, "I2C block read: expected %d bytes, got %d\n", len, n);
        return -1;
    }
    memcpy(buf, data.block + 1, len);
    return 0;
}

/* ---- LSM303D init ---- */
static int lsm303d_init(int fd)
{
    uint8_t who;
    if (i2c_read_reg8(fd, WHO_AM_I, &who) < 0)
        return -1;
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, WHO_AM_I_VAL);
        return -1;
    }

    if (i2c_write_reg8(fd, CTRL_REG1_A, CTRL_REG1_VAL) < 0)
        return -1;
    if (i2c_write_reg8(fd, CTRL_REG4_A, CTRL_REG4_VAL) < 0)
        return -1;
    if (i2c_write_reg8(fd, INT1_CFG, INT1_CFG_VAL) < 0)
        return -1;
    if (i2c_write_reg8(fd, INT1_THS_A, INT1_THS_VAL) < 0)
        return -1;
    if (i2c_write_reg8(fd, INT1_DURATION_A, INT1_DURATION_VAL) < 0)
        return -1;

    return 0;
}

/* ---- Read acceleration ---- */
static int read_acceleration(int fd, accel_data_t *out)
{
    uint8_t raw[6];
    if (i2c_read_block(fd, OUT_X_L_A | 0x80, raw, 6) < 0)
        return -1;

    out->x = (int16_t)((raw[1] << 8) | raw[0]);
    out->y = (int16_t)((raw[3] << 8) | raw[2]);
    out->z = (int16_t)((raw[5] << 8) | raw[4]);
    return 0;
}

/* ---- Circular buffer ---- */
static void cb_init(circular_buffer_t *cb)
{
    cb->head = 0;
    cb->count = 0;
}

static void cb_push(circular_buffer_t *cb, accel_data_t d)
{
    cb->data[cb->head] = d;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

static void cb_dump(const circular_buffer_t *cb, int count)
{
    int start = (cb->count < count) ? 0 : cb->head;
    printf("--- Last %d samples ---\n", count);
    for (int i = 0; i < count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        printf("  [%2d] X=%6d  Y=%6d  Z=%6d\n",
               i, cb->data[idx].x, cb->data[idx].y, cb->data[idx].z);
    }
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        (void)i2c_write_reg8(g_i2c_fd, CTRL_REG1_A, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_line) {
        gpiod_line_release(g_line);
        g_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

/* ---- Main ---- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_DEV, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_DEV, strerror(errno));
        return EXIT_FAILURE;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303D_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                LSM303D_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (lsm303d_init(g_i2c_fd) < 0) {
        fprintf(stderr, "LSM303D init failed\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Open GPIO chip and request INT1 line */
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!g_chip) {
        fprintf(stderr, "Cannot open %s: %s\n", GPIO_CHIP, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }
    g_line = gpiod_chip_get_line(g_chip, GPIO_OFFSET);
    if (!g_line) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n",
                GPIO_OFFSET, strerror(errno));
        gpiod_chip_close(g_chip);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_rising_edge_events(g_line, "lsm303d_mon") < 0) {
        fprintf(stderr, "Cannot request rising-edge events on GPIO %d: %s\n",
                GPIO_OFFSET, strerror(errno));
        gpiod_chip_close(g_chip);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("LSM303D monitoring started (INT1 on GPIO%d). Ctrl-C to exit.\n",
           GPIO_OFFSET);

    circular_buffer_t cb;
    cb_init(&cb);

    while (g_running) {
        struct timespec ts = { 0, POLL_DELAY_US * 1000 };
        nanosleep(&ts, NULL);

        if (gpiod_line_event_wait(g_line, &ts) > 0) {
            struct gpiod_line_event ev;
            if (gpiod_line_event_read(g_line, &ev) == 0) {
                if (ev.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                    printf("INT1 rising edge — printing last %d samples:\n",
                           PRINT_COUNT);
                    cb_dump(&cb, PRINT_COUNT);
                }
            }
        }

        accel_data_t d;
        if (read_acceleration(g_i2c_fd, &d) == 0) {
            cb_push(&cb, d);
        } else {
            fprintf(stderr, "Warning: acceleration read failed, skipping sample\n");
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

