}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }
    if (gpioSetMode(LOCK1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LOCK1_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(LOCK2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LOCK2_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(LOCK1_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize GPIO%d LOW.\n", LOCK1_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(LOCK2_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize GPIO%d LOW.\n", LOCK2_GPIO);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int init_uart(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        fprintf(stderr, "Error: cannot open %s: %s\n", port, strerror(errno));
        return -1;
    }
    if (fcntl(fd, F_SETFL, 0) < 0) {
        fprintf(stderr, "Error: cannot clear O_NDELAY on %s: %s\n", port, strerror(errno));
        close(fd);
        return -1;
    }
    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error: tcgetattr failed on %s: %s\n", port, strerror(errno));
        close(fd);
        return -1;
    }
    cfsetispeed(&tty, BAUD_RATE);
    cfsetospeed(&tty, BAUD_RATE);
    tty.c_cflag = CS8 | CLOCAL | CREAD;
    tty.c_iflag = IGNPAR;
    tty.c_oflag = 0;
    tty.c_lflag = 0;
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 1;
    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error: tcsetattr failed on %s: %s\n", port, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int read_code(int fd, char *out, size_t out_len) {
    static char buf[256];
    static size_t idx = 0;
    static int timeout = 0;
    char ch;
    ssize_t n;
    out[0] = '\0';
    idx = 0;
    timeout = 0;
    while (g_running && idx < out_len - 1) {
        n = read(fd, &ch, 1);
        if (n < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                timeout++;
                if (timeout > TIMEOUT_SEC) {
                    return -1;
                }
                usleep(10000);
                continue;
            }
            fprintf(stderr, "Error: UART read failed on fd %d: %s\n", fd, strerror(errno));
            return -1;
        } else if (n == 0) {
            timeout++;
            if (timeout > TIMEOUT_SEC) {
                return -1;
            }
            usleep(10000);
            continue;
        }
        if (ch >= '0' && ch <= '9') {
            buf[idx++] = ch;
        } else {
            idx = 0;
        }
    }
    buf[idx] = '\0';
    if (idx > 0) {
        strncpy(out, buf, out_len);
        out[out_len - 1] = '\0';
    }
    return 0;
}

static int unlock_doors(void) {
    if (gpioWrite(LOCK1_GPIO, 1) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d HIGH.\n", LOCK1_GPIO);
        return -1;
    }
    if (gpioWrite(LOCK2_GPIO, 1) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d HIGH.\n", LOCK2_GPIO);
        gpioWrite(LOCK1_GPIO, 0);
        return -1;
    }
    printf("Doors unlocked.\n");
    sleep(UNLOCK_DURATION);
    if (gpioWrite(LOCK1_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d LOW.\n", LOCK1_GPIO);
        return -1;
    }
    if (gpioWrite(LOCK2_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d LOW.\n", LOCK2_GPIO);
        return -1;
    }
    printf("Doors re-locked.\n");
    return 0;
}

static void cleanup(void) {
    if (g_primary_fd >= 0) {
        close(g_primary_fd);
        g_primary_fd = -1;
    }
    if (g_secondary_fd >= 0) {
        close(g_secondary_fd);
        g_secondary_fd = -1;
    }
    gpioWrite(LOCK1_GPIO, 0);
    gpioWrite(LOCK2_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    char primary_code[CODE_LENGTH + 1];
    char secondary_code[CODE_LENGTH + 1];
    const char *expected_code = "123456";
    int rc = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    g_primary_fd = init_uart(PRIMARY_UART_PORT);
    if (g_primary_fd < 0) {
        gpioTerminate();
        return 1;
    }

    g_secondary_fd = init_uart(SECONDARY_UART_PORT);
    if (g_secondary_fd < 0) {
        close(g_primary_fd);
        g_primary_fd = -1;
        gpioTerminate();
        return 1;
    }

    printf("Dual-factor authentication system started.\n");
    printf("Primary UART: %s, Secondary UART: %s\n", PRIMARY_UART_PORT, SECONDARY_UART_PORT);
    printf("Expected code: %s\n", expected_code);
    printf("Enter 'q' on either port to quit.\n");

    while (g_running) {
        char pcode[CODE_LENGTH + 1];
        char scode[CODE_LENGTH + 1];

        if (read_code(g_primary_fd, pcode, sizeof(pcode)) == 0) {
            printf("Primary: %s\n", pcode);
            if (strcmp(pcode, expected_code) == 0) {
                strncpy(primary_code, pcode, CODE_LENGTH);
                primary_code[CODE_LENGTH] = '\0';
            } else {
                fprintf(stderr, "Primary: invalid code '%s'\n", pcode);
            }
        } else if (read_code(g_secondary_fd, scode, sizeof(scode)) == 0) {
            printf("Secondary: %s\n", scode);
            if (strcmp(scode, expected_code) == 0) {
                strncpy(secondary_code, scode, CODE_LENGTH);
                secondary_code[CODE_LENGTH] = '\0';
            } else {
                fprintf(stderr, "Secondary: invalid code '%s'\n", scode);
            }
        }

        if (strcmp(primary_code, expected_code) == 0 && strcmp(secondary_code, expected_code) == 0) {
            printf("Both codes match. Unlocking doors...\n");
            if (unlock_doors() != 0) {
                rc = 1;
            }
            memset(primary_code, 0, sizeof(primary_code));
            memset(secondary_code, 0, sizeof(secondary_code));
        }

        usleep(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return rc;
}

