#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define PIR_PIN  4
#define RELAY_PIN 17
#define CHIP_NAME "gpiochip0"
#define STRIKE_DURATION_SEC 1
#define FAILSAFE_THRESHOLD_SEC 10
#define POLL_INTERVAL_MS 50

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(int priority, const char *message) {
    syslog(priority, "%s", message);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pir_line = NULL;
    struct gpiod_line *relay_line = NULL;
    int ret = EXIT_FAILURE;

    openlog("door_strike", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to install signal handlers: %s", strerror(errno));
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        syslog(LOG_ERR, "Failed to open %s: %s", CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        syslog(LOG_ERR, "Failed to get PIR line %d: %s", PIR_PIN, strerror(errno));
        goto cleanup;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        syslog(LOG_ERR, "Failed to get relay line %d: %s", RELAY_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(pir_line, "door_strike_pir") < 0) {
        syslog(LOG_ERR, "Failed to request PIR line as input: %s", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(relay_line, "door_strike_relay", 0) < 0) {
        syslog(LOG_ERR, "Failed to request relay line as output: %s", strerror(errno));
        goto cleanup;
    }

    log_event(LOG_INFO, "Door strike system started.");

    time_t motion_start_time = 0;
    int relay_state = 0;
    int failsafe_triggered = 0;

    while (program_running) {
        int pir_value = gpiod_line_get_value(pir_line);
        if (pir_value < 0) {
            syslog(LOG_ERR, "Failed to read PIR line: %s", strerror(errno));
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (pir_value == 1) {
            if (motion_start_time == 0) {
                motion_start_time = time(NULL);
                log_event(LOG_INFO, "Motion detected.");
            }

            if (!relay_state) {
                if (gpiod_line_set_value(relay_line, 1) < 0) {
                    syslog(LOG_ERR, "Failed to energize relay: %s", strerror(errno));
                } else {
                    relay_state = 1;
                    log_event(LOG_INFO, "Relay energized (strike activated).");
                }
            }

            if (failsafe_triggered) {
                if (gpiod_line_set_value(relay_line, 0) < 0) {
                    syslog(LOG_ERR, "Failed to de-energize relay during failsafe: %s", strerror(errno));
                } else {
                    relay_state = 0;
                    log_event(LOG_INFO, "Failsafe de-energized relay.");
                }
                failsafe_triggered = 0;
            }

            int elapsed = (int)(time(NULL) - motion_start_time);
            if (elapsed >= FAILSAFE_THRESHOLD_SEC) {
                if (!failsafe_triggered) {
                    log_event(LOG_WARNING, "Potential malfunction: PIR HIGH for >10s. De-energizing relay as failsafe.");
                    if (gpiod_line_set_value(relay_line, 0) < 0) {
                        syslog(LOG_ERR, "Failed to de-energize relay during failsafe: %s", strerror(errno));
                    } else {
                        relay_state = 0;
                    }
                    failsafe_triggered = 1;
                }
            }
        } else {
            if (motion_start_time != 0) {
                motion_start_time = 0;
                log_event(LOG_INFO, "Motion stopped.");
            }

            if (relay_state && !failsafe_triggered) {
                if (gpiod_line_set_value(relay_line, 0) < 0) {
                    syslog(LOG_ERR, "Failed to de-energize relay: %s", strerror(errno));
                } else {
                    relay_state = 0;
                    log_event(LOG_INFO, "Relay de-energized.");
                }
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    log_event(LOG_INFO, "Shutting down gracefully.");
    ret = EXIT_SUCCESS;

cleanup:
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    closelog();
    return ret;
}

