#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <string.h>

#define RELAY1_GPIO 4
#define RELAY2_GPIO 17
#define RELAY3_GPIO 27
#define RELAY4_GPIO 22

#define RELAY_ON_TIME_SEC 300
#define RELAY_OFF_TIME_SEC 60
#define TIMER_ID 0

static volatile sig_atomic_t g_running = 1;

static const int relay_gpios[] = {RELAY1_GPIO, RELAY2_GPIO, RELAY3_GPIO, RELAY4_GPIO};
static const int num_relays = sizeof(relay_gpios) / sizeof(relay_gpios[0]);

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_message(int priority, const char *message) {
    syslog(priority, "%s", message);
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    for (int i = 0; i < num_relays; i++) {
        if (gpioSetMode(relay_gpios[i], PI_OUTPUT) != 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Failed to set GPIO %d as output", relay_gpios[i]);
            log_message(LOG_ERR, msg);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(relay_gpios[i], 1) != 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Failed to set GPIO %d HIGH (initial OFF)", relay_gpios[i]);
            log_message(LOG_ERR, msg);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static void activate_relay(int gpio) {
    if (gpioWrite(gpio, 0) != 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Failed to activate relay on GPIO %d", gpio);
        log_message(LOG_ERR, msg);
        return;
    }
    char msg[128];
    snprintf(msg, sizeof(msg), "Relay activated on GPIO %d", gpio);
    log_message(LOG_INFO, msg);
}

static void deactivate_relay(int gpio) {
    if (gpioWrite(gpio, 1) != 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Failed to deactivate relay on GPIO %d", gpio);
        log_message(LOG_ERR, msg);
        return;
    }
    char msg[128];
    snprintf(msg, sizeof(msg), "Relay deactivated on GPIO %d", gpio);
    log_message(LOG_INFO, msg);
}

static void timer_callback(void *user_data) {
    (void)user_data;
    static int current_relay_index = 0;
    static int relay_state = 0; /* 0=off, 1=on, 2=pause */
    static time_t last_relay_change_time = 0;

    time_t current_time = time(NULL);
    if (current_time == (time_t)-1) {
        log_message(LOG_ERR, "time() failed in timer callback");
        return;
    }

    if (relay_state == 0) {
        /* Pause: activate relay */
        activate_relay(relay_gpios[current_relay_index]);
        relay_state = 1;
        last_relay_change_time = current_time;
    } else if (relay_state == 1) {
        /* Active: deactivate relay */
        deactivate_relay(relay_gpios[current_relay_index]);
        relay_state = 0;
        last_relay_change_time = current_time;
    }

    current_relay_index = (current_relay_index + 1) % num_relays;

    if (relay_state == 0) {
        /* Pause: sleep RELAY_OFF_TIME_SEC seconds */
        time_t remaining = current_time + RELAY_OFF_TIME_SEC;
        while (remaining > current_time && g_running) {
            remaining = current_time + RELAY_OFF_TIME_SEC;
            sleep(1);
        }
    } else {
        /* Active: sleep RELAY_ON_TIME_SEC seconds */
        time_t remaining = current_time + RELAY_ON_TIME_SEC;
        while (remaining > current_time && g_running) {
            remaining = current_time + RELAY_ON_TIME_SEC;
            sleep(1);
        }
    }
}

static void cleanup(void) {
    log_message(LOG_INFO, "Cleaning up GPIO resources...");
    for (int i = 0; i < num_relays; i++) {
        gpioWrite(relay_gpios[i], 1);
    }
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        log_message(LOG_ERR, "Failed to register signal handlers");
        closelog();
        return 1;
    }

    if (initialize_gpio() != 0) {
        closelog();
        return 1;
    }

    if (gpioSetTimerFuncEx(TIMER_ID, RELAY_OFF_TIME_SEC, timer_callback, NULL) != 0) {
        log_message(LOG_ERR, "Failed to set timer function");
        cleanup();
        return 1;
    }

    log_message(LOG_INFO, "Irrigation system started");

    while (g_running) {
        sleep(1);
    }

    gpioSetTimerFuncEx(TIMER_ID, 0, NULL, NULL);
    cleanup();
    log_message(LOG_INFO, "Irrigation system stopped");
    return 0;
}

