#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6050_ADDR   0x68
#define MPU6050_WHO_AM_I 0x75
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_ACCEL_CONFIG 0x1C
#define MPU6050_ACCEL_XOUT_H 0x3B

#define ACCEL_SCALE 16384.0f
#define BUFFER_SIZE 100
#define SAMPLE_PERIOD_NS 10000000L  /* 100 Hz */

typedef struct {
    float x, y, z;
    struct timespec timestamp;
} accel_data_t;

static accel_data_t circular_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static int i2c_fd = -1;
static volatile sig_atomic_t running = 1;
static struct sigevent timer_event;
static struct sigaction timer_action;
static struct itimerspec timer_spec;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_mpu6050(int fd) {
    uint8_t who_am_i = 0;
    if (i2c_read_burst(fd, MPU6050_WHO_AM_I, &who_am_i, 1) < 0) {
        fprintf(stderr, "Cannot read WHO_AM_I — sensor absent or bus error\n");
        return -1;
    }
    if (who_am_i != 0x68) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x68\n", who_am_i);
        return -1;
    }
    if (i2c_write_reg8(fd, MPU6050_PWR_MGMT_1, 0x00) < 0) return -1;
    usleep(100000);
    if (i2c_write_reg8(fd, MPU6050_ACCEL_CONFIG, 0x00) < 0) return -1;
    return 0;
}

static int read_accel(int fd, float *x, float *y, float *z) {
    uint8_t raw[6];
    if (i2c_read_burst(fd, MPU6050_ACCEL_XOUT_H, raw, 6) < 0) return -1;
    int16_t rx = (int16_t)((raw[0] << 8) | raw[1]);
    int16_t ry = (int16_t)((raw[2] << 8) | raw[3]);
    int16_t rz = (int16_t)((raw[4] << 8) | raw[5]);
    *x = (float)rx / ACCEL_SCALE;
    *y = (float)ry / ACCEL_SCALE;
    *z = (float)rz / ACCEL_SCALE;
    return 0;
}

static void timer_callback(int sig, siginfo_t *si, void *uc) {
    (void)sig; (void)si; (void)uc;
    float x, y, z;
    if (read_accel(i2c_fd, &x, &y, &z) == 0) {
        circular_buffer[buffer_index].x = x;
        circular_buffer[buffer_index].y = y;
        circular_buffer[buffer_index].z = z;
        circular_buffer[buffer_index].timestamp = clock_gettime(CLOCK_MONOTONIC);
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        if (buffer_count < BUFFER_SIZE) buffer_count++;
    }
}

static int create_timer(void) {
    memset(&timer_event, 0, sizeof(timer_event));
    timer_event.sigev_notify = SIGEV_SIGNAL;
    timer_event.sigev_signo = SIGRTMIN;
    timer_event.sigev_value.sival_ptr = NULL;

    memset(&timer_action, 0, sizeof(timer_action));
    timer_action.sa_flags = 0;
    timer_action.sa_mask = 0;
    timer_action.sa_handler = timer_callback;
    if (sigaction(SIGRTMIN, &timer_action, NULL) < 0) {
        perror("sigaction");
        return -1;
    }
    timer_spec.it_value.tv_sec = 0;
    timer_spec.it_value.tv_nsec = SAMPLE_PERIOD_NS;
    timer_spec.it_interval.tv_sec = 0;
    timer_spec.it_interval.tv_nsec = SAMPLE_PERIOD_NS;
    if (timer_settime(SIGRTMIN, 0, &timer_spec, NULL) < 0) {
        perror("timer_settime");
        return -1;
    }
    return 0;
}

static void write_latest_to_file(const char *path, const accel_data_t *latest) {
    FILE *fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", path, strerror(errno));
        return;
    }
    fprintf(fp, "%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            latest->timestamp.tv_sec, latest->timestamp.tv_nsec,
            latest->x, latest->y, latest->z, 0.0);
    fclose(fp);
}

int main(void) {
    struct sigaction int_handler;
    int latest_fd = -1;

    memset(&int_handler, 0, sizeof(int_handler));
    int_handler.sa_handler = signal_handler;
    sigaction(SIGINT, &int_handler, NULL);
    sigaction(SIGTERM, &int_handler, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }
    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "MPU6050 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    if (create_timer() < 0) {
        fprintf(stderr, "Failed to create timer\n");
        close(i2c_fd);
        return 1;
    }

    latest_fd = open("/sys/kernel/mpu6050_accel/latest", O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (latest_fd < 0) {
        fprintf(stderr, "Cannot create /sys/kernel/mpu6050_accel/latest: %s\n", strerror(errno));
        timer_delete(SIGRTMIN);
        close(i2c_fd);
        return 1;
    }

    while (running) {
        sleep(1);
        if (buffer_count > 0) {
            accel_data_t latest = circular_buffer[(buffer_index - 1 + BUFFER_SIZE) % BUFFER_SIZE];
            write_latest_to_file("/sys/kernel/mpu6050_accel/latest", &latest);
        }
    }

    timer_delete(SIGRTMIN);
    close(i2c_fd);
    if (latest_fd >= 0) close(latest_fd);
    printf("\nShutdown complete.\n");
    return 0;
}

