#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define CONSUMER "smart-lighting"

static const int relay_pins[NUM_RELAYS] = {18, 23, 24, 25};
static const int prime_intervals[NUM_RELAYS] = {2, 3, 5, 7};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static bool is_prime(int num) {
    if (num <= 1) return false;
    if (num <= 3) return true;
    if (num % 2 == 0 || num % 3 == 0) return false;
    int i = 5;
    while (i * i <= num) {
        if (num % i == 0 || num % (i + 2) == 0) return false;
        i += 6;
    }
    return true;
}

static int next_prime(int num) {
    num++;
    while (!is_prime(num)) num++;
    return num;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_RELAYS];
    bool line_acquired[NUM_RELAYS] = {false};
    struct timespec last_time[NUM_RELAYS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = NULL;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d: %s\n", relay_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], CONSUMER, 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", relay_pins[i], strerror(errno));
            goto cleanup;
        }
        line_acquired[i] = true;
        if (clock_gettime(CLOCK_MONOTONIC, &last_time[i]) == -1) {
            perror("Failed to initialize clock time");
            goto cleanup;
        }
    }

    printf("Smart lighting system started. Press Ctrl+C to exit.\n");

    while (running) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            struct timespec now;
            if (clock_gettime(CLOCK_MONOTONIC, &now) == -1) {
                perror("Failed to get current time");
                continue;
            }

            long elapsed_ms = (now.tv_sec - last_time[i].tv_sec) * 1000L +
                              (now.tv_nsec - last_time[i].tv_nsec) / 1000000L;

            if (elapsed_ms >= prime_intervals[i] * 1000L) {
                int val = !line_acquired[i];
                if (gpiod_line_set_value(lines[i], val) < 0) {
                    fprintf(stderr, "Failed to set GPIO line %d: %s\n", relay_pins[i], strerror(errno));
                    continue;
                }
                printf("Light %d toggled (interval: %d seconds)\n", i + 1, prime_intervals[i]);

                last_time[i] = now;
                int next_prime_val = next_prime(prime_intervals[i]);
                prime_intervals[i] = next_prime_val;
            }
        }
        struct timespec sleep_time = {0, 100000000L}; // 100ms
        nanosleep(&sleep_time, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (line_acquired[i] && lines[i]) {
            gpiod_line_set_value(lines[i], 0);
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    printf("Smart lighting system stopped.\n");
    return ret;
}

