#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define MPU6050_WHO_AM_I 0x75
#define MPU6050_WHO_AM_I_VAL 0x68
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_GYRO_XOUT_H 0x43

// Gyroscope sensitivity (LSB/(deg/s)) for default +-250 dps range
#define GYRO_SENSITIVITY 131.0f

// Angular velocity threshold (degrees/second)
#define ANGULAR_VELOCITY_THRESHOLD 50.0f

// Circular buffer size
#define BUFFER_SIZE 100

// I2C device path for Raspberry Pi 3 Model B+
#define I2C_DEVICE "/dev/i2c-1"

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Circular buffer structure
typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
static int i2c_fd = -1;
static circular_buffer_t gyro_buffer;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
static int i2c_write_byte(uint8_t reg, uint8_t value);
static int i2c_read_bytes(uint8_t reg, uint8_t *buf, size_t len);
static int init_mpu6050(void);
static int read_gyro_data(gyro_data_t *data);
static void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data);
static gyro_data_t get_from_buffer(circular_buffer_t *buffer, int index);
static float calculate_magnitude(gyro_data_t data);
static void check_threshold(float magnitude);
static void signal_handler(int signal);

// I2C write function
static int i2c_write_byte(uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// I2C read function
static int i2c_read_bytes(uint8_t reg, uint8_t *buf, size_t len) {
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(i2c_fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "Error reading %zu bytes from register 0x%02X: %s\n", len, reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Initialize MPU-6050
static int init_mpu6050(void) {
    uint8_t who_am_i = 0;

    // Read WHO_AM_I register to verify device
    if (i2c_read_bytes(MPU6050_WHO_AM_I, &who_am_i, 1) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }

    if (who_am_i != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: expected 0x%02X, got 0x%02X\n", MPU6050_WHO_AM_I_VAL, who_am_i);
        return -1;
    }

    printf("MPU-6050 detected (WHO_AM_I = 0x%02X)\n", who_am_i);

    // Wake up the MPU-6050 (clear sleep bit in PWR_MGMT_1)
    if (i2c_write_byte(MPU6050_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake up MPU-6050\n");
        return -1;
    }

    // Allow time for the sensor to stabilize after waking up
    usleep(100000); // 100 ms

    return 0;
}

// Read gyroscope data
static int read_gyro_data(gyro_data_t *data) {
    uint8_t buf[6];

    // Read 6 bytes starting from GYRO_XOUT_H (0x43)
    if (i2c_read_bytes(MPU6050_GYRO_XOUT_H, buf, 6) < 0) {
        return -1;
    }

    // Combine high and low bytes for each axis
    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    // Convert to degrees/second
    data->x = (float)raw_x / GYRO_SENSITIVITY;
    data->y = (float)raw_y / GYRO_SENSITIVITY;
    data->z = (float)raw_z / GYRO_SENSITIVITY;

    return 0;
}

// Add data to the circular buffer
static void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Get data from the circular buffer
static gyro_data_t get_from_buffer(circular_buffer_t *buffer, int index) {
    if (index < 0 || index >= buffer->count) {
        gyro_data_t zero = {0.0f, 0.0f, 0.0f};
        return zero;
    }
    int actual_index = (buffer->head - buffer->count + index + BUFFER_SIZE) % BUFFER_SIZE;
    return buffer->data[actual_index];
}

// Calculate the magnitude of the angular velocity vector
static float calculate_magnitude(gyro_data_t data) {
    return sqrtf(data.x * data.x + data.y * data.y + data.z * data.z);
}

// Check if the angular velocity exceeds the threshold
static void check_threshold(float magnitude) {
    if (magnitude > ANGULAR_VELOCITY_THRESHOLD) {
        gyro_data_t data = get_from_buffer(&gyro_buffer, gyro_buffer.head - 1);
        printf("Threshold exceeded! Magnitude: %.2f deg/s, X: %.2f, Y: %.2f, Z: %.2f\n", 
               magnitude, data.x, data.y, data.z);
    }
}

// Signal handler for graceful shutdown
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

int main(void) {
    // Initialize circular buffer
    gyro_buffer.head = 0;
    gyro_buffer.count = 0;

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device %s: %s\n", I2C_DEVICE, strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() < 0) {
        fprintf(stderr, "MPU-6050 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Set up signal handler for Ctrl+C
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    printf("Gyroscope data acquisition started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        gyro_data_t gyro_data;

        // Read gyroscope data
        if (read_gyro_data(&gyro_data) < 0) {
            fprintf(stderr, "Error reading gyroscope data, retrying...\n");
            usleep(100000); // 100 ms delay before retry
            continue;
        }

        // Add data to the circular buffer
        add_to_buffer(&gyro_buffer, gyro_data);

        // Calculate and check magnitude
        float magnitude = calculate_magnitude(gyro_data);
        check_threshold(magnitude);

        // Print gyroscope data
        printf("X: %.2f, Y: %.2f, Z: %.2f, Magnitude: %.2f\n", 
               gyro_data.x, gyro_data.y, gyro_data.z, magnitude);

        // Delay for 10 ms (100 Hz sampling rate)
        usleep(10000);
    }

    // Clean up
    printf("\nExiting program...\n");
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    return 0;
}

