#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 9600
#define LOG_FILE "co2_log.json"
#define ERROR_LOG_FILE "co2_error.log"
#define READ_INTERVAL_SEC 5
#define READ_TIMEOUT_MS 1000
#define CO2_READ_CMD_LEN 9
#define RESP_LEN 9

static const unsigned char CO2_READ_CMD[CO2_READ_CMD_LEN] = {
    0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79
};

static int uart_handle = -1;
static FILE *log_file = NULL;
static FILE *error_log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void log_error(const char *message) {
    if (!error_log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(error_log_file, "%s: %s (errno: %d - %s)\n", ts, message, errno, strerror(errno));
    fflush(error_log_file);
}

static int init_uart(void) {
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0);
    if (uart_handle < 0) {
        log_error("Failed to open UART");
        return -1;
    }
    return 0;
}

static int read_co2(int *co2_ppm) {
    unsigned char response[RESP_LEN];
    int bytes_read = 0;
    int elapsed = 0;

    if (serWrite(uart_handle, (char *)CO2_READ_CMD, CO2_READ_CMD_LEN) != CO2_READ_CMD_LEN) {
        log_error("Failed to write CO2 read command");
        return -1;
    }

    while (elapsed < READ_TIMEOUT_MS) {
        bytes_read = serDataAvailable(uart_handle);
        if (bytes_read < 0) {
            log_error("serDataAvailable failed");
            return -1;
        }
        if (bytes_read >= RESP_LEN) break;
        gpioDelay(10000);
        elapsed += 10;
    }

    if (bytes_read < RESP_LEN) {
        log_error("Timeout waiting for CO2 response");
        return -1;
    }

    for (int i = 0; i < RESP_LEN; i++) {
        response[i] = (unsigned char)serRead(uart_handle, &response[i], 1);
        if (response[i] < 0) {
            log_error("serRead failed");
            return -1;
        }
    }

    unsigned char checksum = 0;
    for (int i = 1; i < RESP_LEN - 1; i++) {
        checksum += response[i];
    }
    checksum = (0xFF - checksum) + 1;

    if (checksum != response[RESP_LEN - 1]) {
        log_error("CO2 checksum mismatch");
        return -1;
    }

    *co2_ppm = (response[2] << 8) | response[3];
    return 0;
}

static int log_data(int co2_ppm, int error_flag) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        log_error("clock_gettime failed");
        return -1;
    }

    char timestamp[64];
    struct tm *t = localtime(&ts.tv_sec);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%06ld", ts.tv_nsec / 1000);

    if (fprintf(log_file, "{\"timestamp\": \"%s\", \"co2_ppm\": %d, \"error\": %d}\n",
                timestamp, co2_ppm, error_flag) < 0) {
        log_error("Failed to write to log file");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void cleanup(void) {
    if (uart_handle >= 0) {
        serClose(uart_handle);
        uart_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (error_log_file) {
        fclose(error_log_file);
        error_log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (!error_log_file) {
        fprintf(stderr, "Failed to open error log file: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (init_uart() != 0) {
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("CO2 monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int co2_ppm = 0;
        int error_flag = 0;

        if (read_co2(&co2_ppm) != 0) {
            error_flag = 1;
        }

        if (log_data(co2_ppm, error_flag) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        for (int i = 0; i < READ_INTERVAL_SEC && !terminate; i++) {
            gpioDelay(1000000);
        }
    }

    cleanup();
    printf("CO2 monitoring stopped.\n");
    return 0;
}

