#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

#define HMC5883L_ADDR 0x1E
#define CONFIG_A 0x00
#define CONFIG_B 0x01
#define MODE 0x02
#define DATA_START 0x03
#define GPIO_ALERT 17
#define TARGET_HEADING 90.0
#define HEADING_THRESHOLD 10.0
#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL_US 100000

typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static int i2c_handle = -1;
static CircularBuffer heading_buffer;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

static void add_to_circular_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static int init_hmc5883l(void) {
    if (i2cWriteByteData(i2c_handle, CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing CONFIG_A\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing CONFIG_B\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing MODE\n");
        return -1;
    }
    return 0;
}

static int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char data[6];
    if (i2cReadI2CBlockData(i2c_handle, DATA_START, data, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }
    *x = (int16_t)((data[0] << 8) | data[1]);
    *z = (int16_t)((data[2] << 8) | data[3]);
    *y = (int16_t)((data[4] << 8) | data[5]);
    return 0;
}

static void compensate_for_hard_iron(int16_t x, int16_t y, float *heading) {
    const float x_offset = 100.0f;
    const float y_offset = -50.0f;
    float compensated_x = (float)x - x_offset;
    float compensated_y = (float)y - y_offset;
    *heading = atan2f(compensated_y, compensated_x) * 180.0f / M_PI;
    if (*heading < 0) *heading += 360.0f;
}

static void control_gpio(int alert) {
    gpioWrite(GPIO_ALERT, alert);
}

static void log_heading(float heading) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s - Heading: %.2f degrees\n", timestamp, heading);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GPIO_ALERT, PI_OUTPUT);
    gpioWrite(GPIO_ALERT, 0);

    init_circular_buffer(&heading_buffer);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int16_t x, y, z;
    float heading;

    while (running) {
        if (read_magnetometer_data(&x, &y, &z) == 0) {
            compensate_for_hard_iron(x, y, &heading);
            int alert = (fabsf(heading - TARGET_HEADING) > HEADING_THRESHOLD) ? 1 : 0;
            control_gpio(alert);
            add_to_circular_buffer(&heading_buffer, heading);
            log_heading(heading);
        } else {
            gpioWrite(GPIO_ALERT, 0);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioWrite(GPIO_ALERT, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

