#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define RED_PIN   17
#define GREEN_PIN 27
#define BLUE_PIN  22
#define BH1750_ADDR 0x23
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "lighting_log.txt"
#define LUX_CONTINUOUS_HIGH_RES 0x10
#define CONVERSION_DELAY_MS 120
#define POLL_INTERVAL_MS 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int bh1750_write_cmd(int fd, unsigned char cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "Error writing BH1750 command 0x%02X: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_read_lux(int fd, float *lux_out) {
    unsigned char buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading BH1750 data: %s\n", strerror(errno));
        return -1;
    }
    unsigned int raw = ((unsigned int)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void set_relay(struct gpiod_line *line, int pin, int state) {
    if (gpiod_line_set_value(line, state) < 0) {
        fprintf(stderr, "Error setting GPIO %d to %d: %s\n", pin, state, strerror(errno));
    }
}

static void log_data(FILE *fp, float lux, int red, int green, int blue) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, Lux: %.2f, RED: %s, GREEN: %s, BLUE: %s\n",
            timestamp, lux,
            red ? "ON" : "OFF",
            green ? "ON" : "OFF",
            blue ? "ON" : "OFF");
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip4: %s\n", strerror(errno));
        return 1;
    }

    struct gpiod_line *red_line = gpiod_chip_get_line(chip, RED_PIN);
    struct gpiod_line *green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    struct gpiod_line *blue_line = gpiod_chip_get_line(chip, BLUE_PIN);
    if (!red_line || !green_line || !blue_line) {
        fprintf(stderr, "Error getting GPIO lines: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(red_line, "smart_lighting", 0) < 0 ||
        gpiod_line_request_output(green_line, "smart_lighting", 0) < 0 ||
        gpiod_line_request_output(blue_line, "smart_lighting", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO lines as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    int i2c_fd = init_i2c(I2C_BUS, BH1750_ADDR);
    if (i2c_fd < 0) {
        gpiod_chip_close(chip);
        return 1;
    }

    if (bh1750_write_cmd(i2c_fd, LUX_CONTINUOUS_HIGH_RES) < 0) {
        close(i2c_fd);
        gpiod_chip_close(chip);
        return 1;
    }
    usleep(CONVERSION_DELAY_MS * 1000);

    FILE *log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("Smart Lighting System started. Press Ctrl+C to exit.\n");

    while (running) {
        float lux;
        if (bh1750_read_lux(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Sensor read error, retrying...\n");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        int red_state = 0, green_state = 0, blue_state = 0;
        if (lux < 50.0f) {
            red_state = 1;
        } else if (lux < 150.0f) {
            green_state = 1;
        } else if (lux < 300.0f) {
            blue_state = 1;
        } else {
            red_state = 1;
            green_state = 1;
            blue_state = 1;
        }

        set_relay(red_line, RED_PIN, red_state);
        set_relay(green_line, GREEN_PIN, green_state);
        set_relay(blue_line, BLUE_PIN, blue_state);

        log_data(log_fp, lux, red_state, green_state, blue_state);

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    set_relay(red_line, RED_PIN, 0);
    set_relay(green_line, GREEN_PIN, 0);
    set_relay(blue_line, BLUE_PIN, 0);

    fclose(log_fp);
    close(i2c_fd);
    gpiod_chip_close(chip);

    printf("Smart Lighting System stopped.\n");
    return 0;
}

