#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define LOOP_DELAY_US 100000
#define DISTANCE_THRESHOLD 50

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_motor_speed(int in1, int in2, int duty) {
    if (gpioWrite(in1, 1) < 0) return -1;
    if (gpioWrite(in2, 0) < 0) return -1;
    if (gpioPWM(in2, duty) < 0) return -1;
    return 0;
}

static int set_motor_direction(int in1, int in2, int direction) {
    if (direction == 1) {
        if (gpioWrite(in1, 1) < 0) return -1;
        if (gpioWrite(in2, 1) < 0) return -1;
    } else {
        if (gpioWrite(in1, 0) < 0) return -1;
        if (gpioWrite(in2, 0) < 0) return -1;
    }
    return 0;
}

static int motor_control(int motor_a_distance, int motor_b_distance) {
    int motor_a_duty = 0;
    int motor_b_duty = 0;

    if (motor_a_distance < DISTANCE_THRESHOLD) {
        motor_a_duty = 255 - (motor_a_distance * 2);
        if (motor_a_duty < 0) motor_a_duty = 0;
        if (motor_a_duty > 255) motor_a_duty = 255;
    } else {
        motor_a_duty = 0;
    }

    if (motor_b_distance < DISTANCE_THRESHOLD) {
        motor_b_duty = 255 - (motor_b_distance * 2);
        if (motor_b_duty < 0) motor_b_duty = 0;
        if (motor_b_duty > 255) motor_b_duty = 255;
    } else {
        motor_b_duty = 0;
    }

    if (set_motor_speed(MOTOR_A_IN1, MOTOR_A_IN2, motor_a_duty) < 0) {
        fprintf(stderr, "Error setting Motor A speed\n");
        return -1;
    }
    if (set_motor_speed(MOTOR_B_IN3, MOTOR_B_IN4, motor_b_duty) < 0) {
        fprintf(stderr, "Error setting Motor B speed\n");
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR_A_IN1, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_A_IN2, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_IN3, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_IN4, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(MOTOR_A_IN2, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR_B_IN4, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int motor_a_distance = 50;
    int motor_b_distance = 50;

    while (running) {
        if (motor_control(motor_a_distance, motor_b_distance) < 0) {
            fprintf(stderr, "Motor control error, stopping motors\n");
            gpioWrite(MOTOR_A_IN1, 0);
            gpioWrite(MOTOR_A_IN2, 0);
            gpioWrite(MOTOR_B_IN3, 0);
            gpioWrite(MOTOR_B_IN4, 0);
            break;
        }
        gpioDelay(LOOP_DELAY_US);
    }

    gpioWrite(MOTOR_A_IN1, 0);
    gpioWrite(MOTOR_A_IN2, 0);
    gpioWrite(MOTOR_B_IN3, 0);
    gpioWrite(MOTOR_B_IN4, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

