static int init_servo_pwm(void) {
    char path[128];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d", PWM_CHIP, PWM_CHANNEL);
    if (access(path, F_OK) != 0) {
        if (mkdir(path, 0755) != 0) {
            if (errno != EEXIST) return -1;
        }
    }
    snprintf(path, sizeof(path), "%s/enable", path);
    FILE *en = fopen(path, "w");
    if (!en) return -1;
    fprintf(en, "1");
    fclose(en);
    snprintf(path, sizeof(path), "%s/duty_cycle", path);
    FILE *duty = fopen(path, "w");
    if (!duty) return -1;
    fprintf(duty, "0");
    fclose(duty);
    snprintf(path, sizeof(path), "%s/period", path);
    FILE *per = fopen(path, "w");
    if (!per) return -1;
    fprintf(per, "%d", PWM_PERIOD_NS);
    fclose(per);
    return 0;
}

static int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) return -1;
