#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define NUM_RELAYS 4
#define PWM_FREQUENCY 100
#define FADE_DURATION 1800
#define SCHEDULE_FILE "lighting_schedule.txt"

static const int relay_pins[NUM_RELAYS] = {4, 17, 27, 22};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_schedule(const char *filename, int schedule[][4]) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error opening schedule file: %s\n", strerror(errno));
        return -1;
    }

    char line[256];
    int count = 0;
    while (fgets(line, sizeof(line), fp) && count < NUM_RELAYS) {
        int hour, minute, second, relay, on;
        if (sscanf(line, "%d:%d:%d,%d,%d", &hour, &minute, &second, &relay, &on) == 5) {
            if (relay < 1 || relay > NUM_RELAYS) {
                fprintf(stderr, "Invalid relay number %d in schedule\n", relay);
                continue;
            }
            schedule[count][0] = hour;
            schedule[count][1] = minute;
            schedule[count][2] = second;
            schedule[count][3] = on;
            count++;
        } else {
            fprintf(stderr, "Invalid schedule format: %s", line);
        }
    }

    fclose(fp);
    return count;
}

static int is_time_match(int hour, int minute, int second, int schedule[][4], int num_entries) {
    for (int i = 0; i < num_entries; i++) {
        if (schedule[i][0] == hour && schedule[i][1] == minute && schedule[i][2] == second) {
            return schedule[i][3];
        }
    }
    return 0;
}

static void fade_lamp(int relay_pin, int target_brightness) {
    if (target_brightness < 0) target_brightness = 0;
    if (target_brightness > 100) target_brightness = 100;

    int current_brightness = 0;
    int step = 5;
    int direction = (target_brightness >= current_brightness) ? 1 : -1;

    while (current_brightness != target_brightness && running) {
        current_brightness += step * direction;
        if (current_brightness < 0) current_brightness = 0;
        if (current_brightness > 100) current_brightness = 100;

        if (gpioPWM(relay_pin, current_brightness) != 0) {
            fprintf(stderr, "Error setting PWM on GPIO %d\n", relay_pin);
            return;
        }
        gpioDelay(100000);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", relay_pins[i]);
            gpioTerminate();
            return 1;
        }
        if (gpioSetPWMfrequency(relay_pins[i], PWM_FREQUENCY) < 0) {
            fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", relay_pins[i]);
            gpioTerminate();
            return 1;
        }
        if (gpioPWM(relay_pins[i], 0) != 0) {
            fprintf(stderr, "Failed to initialise PWM on GPIO %d\n", relay_pins[i]);
            gpioTerminate();
            return 1;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int schedule[NUM_RELAYS][4];
    int num_entries = read_schedule(SCHEDULE_FILE, schedule);
    if (num_entries < 0) {
        gpioTerminate();
        return 1;
    }

    time_t last_check_time = 0;
    int last_target_brightness[NUM_RELAYS] = {0};

    while (running) {
        time_t current_time = time(NULL);
        if (current_time == (time_t)-1) {
            fprintf(stderr, "Error getting current time: %s\n", strerror(errno));
            sleep(1);
            continue;
        }

        if (difftime(current_time, last_check_time) >= 1.0) {
            last_check_time = current_time;

            int hour = 0, minute = 0, second = 0;
            if (localtime(&current_time) != NULL) {
                hour = localtime(&current_time)->tm_hour;
                minute = localtime(&current_time)->tm_min;
                second = localtime(&current_time)->tm_sec;
            } else {
                fprintf(stderr, "localtime failed: %s\n", strerror(errno));
            }

            int target_brightness = is_time_match(hour, minute, second, schedule, num_entries);
            if (target_brightness != 0 && target_brightness != last_target_brightness[0]) {
                fade_lamp(relay_pins[0], target_brightness);
                last_target_brightness[0] = target_brightness;
            }
            if (target_brightness != 0 && target_brightness != last_target_brightness[1]) {
                fade_lamp(relay_pins[1], target_brightness);
                last_target_brightness[1] = target_brightness;
            }
            if (target_brightness != 0 && target_brightness != last_target_brightness[2]) {
                fade_lamp(relay_pins[2], target_brightness);
                last_target_brightness[2] = target_brightness;
            }
            if (target_brightness != 0 && target_brightness != last_target_brightness[3]) {
                fade_lamp(relay_pins[3], target_brightness);
                last_target_brightness[3] = target_brightness;
            }
        }

        gpioDelay(100000);
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioPWM(relay_pins[i], 0);
    }
    gpioTerminate();
    return 0;
}

