#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define BUZZER_PIN  18

#define MIN_DISTANCE_CM  2.0f
#define MAX_DISTANCE_CM  30.0f
#define MIN_FREQUENCY_HZ 200
#define MAX_FREQUENCY_HZ 2000

#define TRIGGER_PULSE_US  10
#define ECHO_TIMEOUT_US   30000   /* 30 ms max echo wait (~5 m round trip) */
#define LOOP_DELAY_US     60000   /* 60 ms between measurements */
#define SOUND_SPEED_CM_US 0.0343f /* 343 m/s in cm/us */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        return -1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set BUZZER_PIN %d as output.\n", BUZZER_PIN);
        return -1;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise TRIGGER_PIN low.\n");
        return -1;
    }
    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise BUZZER_PIN low.\n");
        return -1;
    }

    return 0;
}

static int trigger_sensor(void) {
    if (gpioWrite(TRIGGER_PIN, 1) < 0) return -1;
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) return -1;
    return 0;
}

/*
 * Returns distance in cm, or -1.0 on timeout / error.
 * Uses gpioTick() for microsecond-precision timing.
 */
static float read_distance(void) {
    uint32_t start_tick, end_tick, timeout_tick;

    /* Wait for echo to go high (sensor responds) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo start timeout (sensor absent or not responding).\n");
            return -1.0f;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo to go low (pulse ends) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo end timeout (stuck high).\n");
            return -1.0f;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    float distance = (pulse_us * SOUND_SPEED_CM_US) / 2.0f;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of range [%.1f, %.1f], clamping.\n",
                distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        if (distance < MIN_DISTANCE_CM) distance = MIN_DISTANCE_CM;
        if (distance > MAX_DISTANCE_CM) distance = MAX_DISTANCE_CM;
    }

    return distance;
}

static int set_buzzer_frequency(int frequency_hz) {
    if (frequency_hz < MIN_FREQUENCY_HZ) frequency_hz = MIN_FREQUENCY_HZ;
    if (frequency_hz > MAX_FREQUENCY_HZ) frequency_hz = MAX_FREQUENCY_HZ;

    int pwm_range = 1000000 / frequency_hz; /* 1 000 000 / 200 = 5000 */
    if (gpioSetPWMfrequency(BUZZER_PIN, frequency_hz) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on BUZZER_PIN %d.\n", BUZZER_PIN);
        return -1;
    }
    if (gpioSetPWMrange(BUZZER_PIN, pwm_range) < 0) {
        fprintf(stderr, "Error: failed to set PWM range on BUZZER_PIN %d.\n", BUZZER_PIN);
        return -1;
    }
    if (gpioPWM(BUZZER_PIN, pwm_range / 2) < 0) {
        fprintf(stderr, "Error: failed to start PWM on BUZZER_PIN %d.\n", BUZZER_PIN);
        return -1;
    }
    return 0;
}

static void silence_buzzer(void) {
    gpioPWM(BUZZER_PIN, 0);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (running) {
        if (trigger_sensor() != 0) {
            fprintf(stderr, "Error: failed to trigger sensor.\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        float distance = read_distance();
        if (distance < 0.0f) {
            fprintf(stderr, "Error: distance read failed, skipping cycle.\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        int frequency = (int)((distance - MIN_DISTANCE_CM) *
                              (MAX_FREQUENCY_HZ - MIN_FREQUENCY_HZ) /
                              (MAX_DISTANCE_CM - MIN_DISTANCE_CM) + MIN_FREQUENCY_HZ);

        if (set_buzzer_frequency(frequency) != 0) {
            fprintf(stderr, "Error: failed to set buzzer frequency.\n");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    silence_buzzer();
    gpioTerminate();
    printf("\nTheremin stopped.\n");
    return EXIT_SUCCESS;
}

