#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27
#define PWM_FREQ  1000
#define PWM_RANGE 255

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_led_color(int r, int g, int b) {
    if (gpioPWM(RED_PIN,   PWM_RANGE - r) < 0) return -1;
    if (gpioPWM(GREEN_PIN, PWM_RANGE - g) < 0) return -1;
    if (gpioPWM(BLUE_PIN,  PWM_RANGE - b) < 0) return -1;
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN,   PI_OUTPUT) < 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(BLUE_PIN,  PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RED_PIN,   PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(BLUE_PIN,  PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN,   PWM_RANGE) < 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(BLUE_PIN,  PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (set_led_color(0, 0, 0) < 0) {
        fprintf(stderr, "Failed to initialise LED to off\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        double t = (double)time(NULL) * 0.1;
        double p = 0.5 * (1.0 + sin(t * 2.0 * M_PI));

        int r = (int)(p * 255.0);
        int g = (int)((1.0 - abs(p - 1.0)) * 255.0);
        int b = 0;

        if (set_led_color(r, g, b) < 0) {
            fprintf(stderr, "PWM write failed\n");
            break;
        }
        usleep(10000);
    }

    set_led_color(0, 0, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

