#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BUTTON_PIN 17
#define BUZZER_PIN 18

#define DEBOUNCE_US 50000   /* 50 ms debounce */
#define TONE_DUTY  500000   /* 50% of 1M range (pigpio hardware PWM) */

#define NOTE_C4 262
#define NOTE_D4 294
#define NOTE_E4 330
#define NOTE_F4 349
#define NOTE_G4 392
#define NOTE_A4 440
#define NOTE_B4 494
#define NOTE_C5 523

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t play_note = 0;
static volatile uint32_t last_press_tick = 0;

/* Musical doorbell melody: play each note for 500 ms */
static const int melody[] = {
    NOTE_C4, NOTE_C4, NOTE_G4, NOTE_A4, NOTE_G4, NOTE_F4,
    NOTE_E4, NOTE_E4, NOTE_G4, NOTE_A4, NOTE_G4, NOTE_F4,
    NOTE_E4, NOTE_E4, NOTE_G4, NOTE_A4, NOTE_G4, NOTE_F4,
    NOTE_E4, NOTE_C4, NOTE_C4, NOTE_G4, NOTE_A4, NOTE_G4,
    NOTE_F4, NOTE_E4, NOTE_E4, NOTE_G4, NOTE_A4, NOTE_G4,
    NOTE_F4, NOTE_E4, NOTE_C4, NOTE_C4, NOTE_G4, NOTE_A4,
    NOTE_G4, NOTE_F4, NOTE_E4, NOTE_E4, NOTE_G4, NOTE_A4,
    NOTE_G4, NOTE_F4, NOTE_E4, NOTE_C4, NOTE_C4, NOTE_G4,
    NOTE_A4, NOTE_G4, NOTE_F4, NOTE_E4, NOTE_E4, NOTE_G4,
    NOTE_A4, NOTE_G4, NOTE_F4, NOTE_E4, NOTE_C4, NOTE_C4,
    NOTE_G4, NOTE_A4, NOTE_G4, NOTE_F4, NOTE_E4, NOTE_E4,
    NOTE_G4, NOTE_A4, NOTE_G4, NOTE_F4, NOTE_E4, NOTE_C4
};
static const int melody_len = sizeof(melody) / sizeof(melody[0]);

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void button_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;

    if (level != 0) {            /* active-low: 0 = pressed */
        return;
    }

    uint32_t elapsed = tick - last_press_tick;
    if (elapsed < DEBOUNCE_US) {
        return;
    }
    last_press_tick = tick;

    if (play_note) {
        /* Second press: stop melody */
        play_note = 0;
        gpioHardwarePWM(BUZZER_PIN, 0, 0);
        printf("Doorbell stopped.\n");
    } else {
        /* First press: start melody */
        play_note = 1;
        printf("Doorbell ringing...\n");
        for (int i = 0; i < melody_len && running; i++) {
            if (gpioHardwarePWM(BUZZER_PIN, melody[i], TONE_DUTY) < 0) {
                fprintf(stderr, "gpioHardwarePWM failed for note %d\n", melody[i]);
                break;
            }
            gpioDelay(500000);     /* 500 ms per note */
        }
        play_note = 0;
        gpioHardwarePWM(BUZZER_PIN, 0, 0);
        printf("Doorbell stopped.\n");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set button pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set buzzer pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on button pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioHardwarePWM(BUZZER_PIN, 0, 0) < 0) {
        fprintf(stderr, "Failed to initialise buzzer PWM to 0\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, button_isr, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioHardwarePWM(BUZZER_PIN, 0, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        gpioHardwarePWM(BUZZER_PIN, 0, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Musical doorbell ready. Press the button (GPIO17) to play.\n");
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(100000);       /* 100 ms sleep */
    }

    /* Clean shutdown */
    gpioHardwarePWM(BUZZER_PIN, 0, 0);
    gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, NULL, NULL);
    gpioTerminate();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

