#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* LSM303DLHC magnetometer 7-bit I2C address */
#define LSM303_MAG_ADDR 0x1E

/* LSM303DLHC magnetometer register addresses */
#define CRA_REG_M 0x00
#define MR_REG_M  0x02
#define OUT_X_H_M 0x03
#define OUT_X_L_M 0x04
#define OUT_Z_H_M 0x05
#define OUT_Z_L_M 0x06
#define OUT_Y_H_M 0x07
#define OUT_Y_L_M 0x08

/* Hard-iron calibration offsets (adjust for your sensor) */
#define X_OFFSET 10.0f
#define Y_OFFSET -5.0f
#define Z_OFFSET 20.0f

#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "mag_log.csv"
#define SAMPLE_INTERVAL_US 1000000  /* 1 second */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write one byte to an 8-bit register via SMBus block write */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read N bytes starting from an 8-bit register via SMBus block read */
static int i2c_read_reg(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg: write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "i2c_read_reg: read %zu bytes from 0x%02X failed: %s\n",
                len, reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_magnetometer(int fd)
{
    /* Set output data rate to 15 Hz (CRA_REG_M = 0x14) */
    if (i2c_write_reg8(fd, CRA_REG_M, 0x14) < 0)
        return -1;

    /* Continuous-conversion mode (MR_REG_M = 0x00) */
    if (i2c_write_reg8(fd, MR_REG_M, 0x00) < 0)
        return -1;

    return 0;
}

static int read_magnetometer(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t data[6];
    if (i2c_read_reg(fd, OUT_X_H_M, data, sizeof(data)) < 0)
        return -1;

    *x = (int16_t)((data[0] << 8) | data[1]);
    *z = (int16_t)((data[2] << 8) | data[3]);
    *y = (int16_t)((data[4] << 8) | data[5]);
    return 0;
}

static void calibrate_data(int16_t x, int16_t y, int16_t z,
                           float *cx, float *cy, float *cz)
{
    *cx = (float)(x - X_OFFSET);
    *cy = (float)(y - Y_OFFSET);
    *cz = (float)(z - Z_OFFSET);
}

static float calculate_heading(float cx, float cy)
{
    float heading = atan2f(cy, cx) * 180.0f / (float)M_PI;
    if (heading < 0.0f)
        heading += 360.0f;
    return heading;
}

static const char *determine_direction(float heading)
{
    if (heading >= 337.5f || heading < 22.5f) return "N";
    if (heading < 67.5f) return "NE";
    if (heading < 112.5f) return "E";
    if (heading < 157.5f) return "SE";
    if (heading < 202.5f) return "S";
    if (heading < 247.5f) return "SW";
    if (heading < 292.5f) return "W";
    return "NW";
}

static int log_data(FILE *fp, float cx, float cy, float cz, float heading)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(fp, "%s,%.2f,%.2f,%.2f,%.2f,%s\n",
                timestamp, cx, cy, cz, heading,
                determine_direction(heading)) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

static int ensure_log_header(FILE *fp)
{
    long pos = ftell(fp);
    if (pos < 0) {
        fprintf(stderr, "ftell failed: %s\n", strerror(errno));
        return -1;
    }
    if (pos == 0) {
        if (fprintf(fp, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading,Direction\n") < 0) {
            fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
            return -1;
        }
        fflush(fp);
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303_MAG_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                LSM303_MAG_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }

    if (init_magnetometer(g_i2c_fd) < 0) {
        fprintf(stderr, "Magnetometer initialization failed.\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }

    if (ensure_log_header(g_log_fp) < 0) {
        fclose(g_log_fp);
        g_log_fp = NULL;
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }

    printf("Magnetometer logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t x, y, z;
        float cx, cy, cz, heading;

        if (read_magnetometer(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Magnetometer read error, skipping sample.\n");
        } else {
            calibrate_data(x, y, z, &cx, &cy, &cz);
            heading = calculate_heading(cx, cy);
            printf("Heading: %.2f degrees (%s)\n",
                   heading, determine_direction(heading));

            if (log_data(g_log_fp, cx, cy, cz, heading) < 0) {
                fprintf(stderr, "Logging error, continuing.\n");
            }
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down cleanly...\n");
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return 0;
}

