#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_MS 200
#define LOG_FILE "relay_log.json"

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t last_touch_tick = 0;
static volatile sig_atomic_t relay_state = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_relay_state(int state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"}\n",
                ts, state ? "ON" : "OFF");
    }
    fclose(fp);
}

static void touch_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level != 1) return; /* only act on rising edge */

    uint32_t now = tick;
    uint32_t last = last_touch_tick;
    if (last == 0 || (now - last) >= DEBOUNCE_MS * 1000) {
        last_touch_tick = now;
        relay_state = !relay_state;
        if (gpioWrite(RELAY_PIN, relay_state) < 0) {
            fprintf(stderr, "gpioWrite failed on pin %d\n", RELAY_PIN);
        }
        log_relay_state(relay_state);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed on pin %d\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "gpioSetPullUpDown failed on pin %d\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed on pin %d\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(RELAY_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite failed on pin %d\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFunc(TOUCH_SENSOR_PIN, RISING_EDGE, 0, touch_callback) < 0) {
        fprintf(stderr, "gpioSetISRFunc failed on pin %d\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        gpioSetISRFunc(TOUCH_SENSOR_PIN, RISING_EDGE, 0, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch sensor relay control started. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(100 * 1000); /* 100 ms */
    }

    /* Graceful shutdown */
    gpioWrite(RELAY_PIN, 0);
    log_relay_state(0);
    gpioSetISRFunc(TOUCH_SENSOR_PIN, RISING_EDGE, 0, NULL);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

