#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define MOISTURE_THRESHOLD 30
#define RELAY_ON_TIME 5
#define RELAY_GAP 1
#define LOG_FILE "irrigation_log.txt"
#define CHIP_NAME "gpiochip0"
#define CONSUMER "smart_irrigation"

static const unsigned int relay_pins[NUM_RELAYS] = {17, 23, 24, 25};

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_RELAYS];

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(int relay_num, int moisture) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (!t) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }
    if (fprintf(log_fp, "%s - Relay %d activated (moisture: %d)\n", ts, relay_num, moisture) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 1);
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return 1;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s) failed: %s\n", CHIP_NAME, strerror(errno));
        cleanup();
        return 1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line(%u) failed: %s\n", relay_pins[i], strerror(errno));
            cleanup();
            return 1;
        }
        if (gpiod_line_request_output(lines[i], CONSUMER, 1) < 0) {
            fprintf(stderr, "gpiod_line_request_output(%u) failed: %s\n", relay_pins[i], strerror(errno));
            cleanup();
            return 1;
        }
    }

    srand((unsigned int)time(NULL));

    while (running) {
        int moisture = rand() % 101;
        printf("Simulated moisture level: %d\n", moisture);

        if (moisture < MOISTURE_THRESHOLD) {
            printf("Moisture below threshold. Activating relays.\n");
            for (int i = 0; i < NUM_RELAYS && running; i++) {
                if (gpiod_line_set_value(lines[i], 0) < 0) {
                    fprintf(stderr, "gpiod_line_set_value(%u, 0) failed: %s\n", relay_pins[i], strerror(errno));
                    cleanup();
                    return 1;
                }
                if (log_event(i + 1, moisture) != 0) {
                    cleanup();
                    return 1;
                }
                sleep(RELAY_ON_TIME);
                if (gpiod_line_set_value(lines[i], 1) < 0) {
                    fprintf(stderr, "gpiod_line_set_value(%u, 1) failed: %s\n", relay_pins[i], strerror(errno));
                    cleanup();
                    return 1;
                }
                if (i < NUM_RELAYS - 1 && running) {
                    sleep(RELAY_GAP);
                }
            }
        }
        sleep(10);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

