/*
 * Automated Plant Watering System (Raspberry Pi Zero W, pigpio)
 *
 * Servos:
 *   Valve  : GPIO17 (physical pin 11)  - 0 deg = closed, 90 deg = open
 *   Nozzle : GPIO18 (physical pin 12)  - 0, 45, 90, 135, 180 deg
 *
 * Moisture threshold: 50
 * Cycle: if moisture < 50, open valve, sweep nozzle, hold 5 s, close valve.
 *        else skip.  Wait 5 s between cycles.
 *
 * Build: gcc -Wall -Wextra -O2 -o watering watering.c -lpigpio -lrt
 * Run  : sudo ./watering
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_PIN        17
#define NOZZLE_PIN       18

#define MOISTURE_THRESHOLD 50
#define VALVE_OPEN_US     1500   /* ~90 deg */
#define VALVE_CLOSED_US   500    /* ~0 deg   */
#define NOZZLE_MIN_US     500    /* ~0 deg   */
#define NOZZLE_MAX_US     2500   /* ~180 deg */
#define STEP_DELAY_US     2000000 /* 2 s per nozzle angle */
#define HOLD_DELAY_US     5000000 /* 5 s hold after watering */
#define CYCLE_DELAY_US    5000000 /* 5 s between cycles */
#define SERVO_RETRY_MAX   3
#define SERVO_RETRY_MS    100

static volatile sig_atomic_t g_stop = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_stop = 1;
}

/* Drive a servo once; returns 0 on success, -1 on failure. */
static int servo_once(int pin, int pulse_us)
{
    for (int attempt = 0; attempt < SERVO_RETRY_MAX; ++attempt) {
        if (gpioServo(pin, pulse_us) == 0)
            return 0;
        fprintf(stderr, "gpioServo(pin=%d, pulse=%d us) failed (attempt %d/%d)\n",
                pin, pulse_us, attempt + 1, SERVO_RETRY_MAX);
        if (attempt < SERVO_RETRY_MAX - 1)
            gpioDelay(SERVO_RETRY_MS * 1000);
    }
    return -1;
}

/* Drive a servo to the given pulse width, aborting on failure. */
static int servo_set(int pin, int pulse_us)
{
    if (servo_once(pin, pulse_us) != 0) {
        fprintf(stderr, "Failed to set servo pin %d to %d us\n", pin, pulse_us);
        return -1;
    }
    return 0;
}

/* Stop a servo (pulse 0) and release pigpio. */
static void servo_stop(int pin)
{
    gpioServo(pin, 0);
}

/* Simulated soil moisture reading (0-100). */
static int get_soil_moisture(void)
{
    static int state = 0;
    static const int values[] = {20, 40, 60, 80, 100};
    static const int n = sizeof(values) / sizeof(values[0]);
    int v = values[state];
    state = (state + 1) % n;
    return v;
}

int main(void)
{
    /* --- Signal handling (async-signal-safe) --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Main loop --- */
    while (!g_stop) {
        int moisture = get_soil_moisture();
        printf("Soil moisture: %d%%\n", moisture);

        if (moisture < MOISTURE_THRESHOLD) {
            printf("Moisture below threshold. Watering...\n");

            /* Open valve */
            if (servo_set(VALVE_PIN, VALVE_OPEN_US) != 0) {
                fprintf(stderr, "Valve open failed - aborting watering cycle.\n");
                break;
            }

            /* Sweep nozzle through 5 angles */
            for (int angle = 0; angle <= 180 && !g_stop; angle += 45) {
                int pulse = NOZZLE_MIN_US + (angle * (NOZZLE_MAX_US - NOZZLE_MIN_US)) / 180;
                if (servo_set(NOZZLE_PIN, pulse) != 0) {
                    fprintf(stderr, "Nozzle position %d deg failed - aborting watering cycle.\n", angle);
                    break;
                }
                if (angle < 180)
                    gpioDelay(STEP_DELAY_US);
            }

            /* Hold after watering */
            gpioDelay(HOLD_DELAY_US);

            /* Close valve */
            if (servo_set(VALVE_PIN, VALVE_CLOSED_US) != 0) {
                fprintf(stderr, "Warning: failed to close valve after watering.\n");
            }
        } else {
            printf("Moisture above threshold. Skipping watering.\n");
        }

        /* Wait before next cycle */
        gpioDelay(CYCLE_DELAY_US);
    }

    /* --- Cleanup --- */
    printf("Shutting down...\n");
    servo_stop(VALVE_PIN);
    servo_stop(NOZZLE_PIN);
    gpioTerminate();
    return EXIT_SUCCESS;
}

