#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define IN1 4
#define IN2 17
#define IN3 27
#define IN4 22
#define LOCK_BUTTON 24
#define UNLOCK_BUTTON 23
#define STEPS_PER_ROTATION 512
#define STEP_DELAY_US 3000
#define DEBOUNCE_US 200000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_write(unsigned gpio, int level) {
    if (gpioWrite(gpio, level) < 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %d) failed\n", gpio, level);
        return -1;
    }
    return 0;
}

static int safe_set_mode(unsigned gpio, unsigned mode) {
    if (gpioSetMode(gpio, mode) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", gpio, mode);
        return -1;
    }
    return 0;
}

static int safe_set_pull(unsigned gpio, unsigned pud) {
    if (gpioSetPullUpDown(gpio, pud) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(%u, %u) failed\n", gpio, pud);
        return -1;
    }
    return 0;
}

static void deenergize(void) {
    safe_write(IN1, 0);
    safe_write(IN2, 0);
    safe_write(IN3, 0);
    safe_write(IN4, 0);
}

static void full_step(int a, int b, int c, int d) {
    safe_write(IN1, a);
    safe_write(IN2, b);
    safe_write(IN3, c);
    safe_write(IN4, d);
}

static void rotate(int steps, int direction) {
    for (int i = 0; i < steps && running; i++) {
        int a = (i % 4) == 0 ? 1 : 0;
        int b = (i + 1) % 4 == 0 ? 1 : 0;
        int c = (i + 2) % 4 == 0 ? 1 : 0;
        int d = (i + 3) % 4 == 0 ? 1 : 0;
        if (direction > 0) {
            full_step(a, b, c, d);
        } else {
            full_step(d, c, b, a);
        }
        gpioDelay(STEP_DELAY_US);
    }
    deenergize();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int pins[] = {IN1, IN2, IN3, IN4};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (safe_set_mode(pins[i], PI_OUTPUT) < 0) goto cleanup;
        if (safe_write(pins[i], 0) < 0) goto cleanup;
    }

    if (safe_set_mode(LOCK_BUTTON, PI_INPUT) < 0) goto cleanup;
    if (safe_set_mode(UNLOCK_BUTTON, PI_INPUT) < 0) goto cleanup;
    if (safe_set_pull(LOCK_BUTTON, PI_PUD_UP) < 0) goto cleanup;
    if (safe_set_pull(UNLOCK_BUTTON, PI_PUD_UP) < 0) goto cleanup;

    printf("Automatic Door Lock System\n");
    printf("Press LOCK (GPIO24) to lock, UNLOCK (GPIO23) to unlock.\n");
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        if (gpioRead(LOCK_BUTTON) == 0) {
            printf("Locking...\n");
            rotate(STEPS_PER_ROTATION, 1);
            gpioDelay(DEBOUNCE_US);
        } else if (gpioRead(UNLOCK_BUTTON) == 0) {
            printf("Unlocking...\n");
            rotate(STEPS_PER_ROTATION, -1);
            gpioDelay(DEBOUNCE_US);
        }
        gpioDelay(10000);
    }

cleanup:
    deenergize();
    gpioTerminate();
    return EXIT_SUCCESS;
}

