#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define LOG_FILE    "distance_log.txt"
#define TIMEOUT_US  50000   /* 50 ms timeout for echo edges */
#define GUARD_MS    60      /* min guard time between measurements */
#define TRIGGER_PULSE_US 10
#define SPEED_OF_SOUND_CM_PER_US 0.01715

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);
}

/*
 * Measure the echo pulse width in microseconds.
 * Returns >= 0 on success, -1 on timeout, -2 on GPIO read error.
 */
static long measure_echo(struct gpiod_line *echo_line)
{
    struct timespec t_start, t_now;
    long elapsed_us;

    /* Wait for echo rising edge (timeout) */
    clock_gettime(CLOCK_MONOTONIC, &t_start);
    while (gpiod_line_get_value(echo_line) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &t_now);
        elapsed_us = (t_now.tv_sec - t_start.tv_sec) * 1000000L +
                     (t_now.tv_nsec - t_start.tv_nsec) / 1000L;
        if (elapsed_us > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo rising edge\n");
            return -1;
        }
    }

    /* Wait for echo falling edge (timeout) */
    clock_gettime(CLOCK_MONOTONIC, &t_start);
    while (gpiod_line_get_value(echo_line) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &t_now);
        elapsed_us = (t_now.tv_sec - t_start.tv_sec) * 1000000L +
                     (t_now.tv_nsec - t_start.tv_nsec) / 1000L;
        if (elapsed_us > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo falling edge\n");
            return -1;
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &t_now);
    elapsed_us = (t_now.tv_sec - t_start.tv_sec) * 1000000L +
                 (t_now.tv_nsec - t_start.tv_nsec) / 1000L;
    return elapsed_us;
}

static void log_distance(FILE *fp, long distance_cm)
{
    if (fp == NULL) {
        fprintf(stderr, "Log file not open\n");
        return;
    }
    fprintf(fp, "%ld\n", distance_cm);
    fflush(fp);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger_line = NULL;
    struct gpiod_line *echo_line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip (gpiochip4 on Pi 4/5 with 64-bit kernel) */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (trigger_line == NULL) {
        fprintf(stderr, "Failed to get trigger line %d: %s\n",
                TRIGGER_PIN, strerror(errno));
        goto cleanup;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (echo_line == NULL) {
        fprintf(stderr, "Failed to get echo line %d: %s\n",
                ECHO_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request trigger as output, initial value LOW */
    if (gpiod_line_request_output(trigger_line, "hcsr04-trigger", 0) < 0) {
        fprintf(stderr, "Failed to request trigger line as output: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* Request echo as input */
    if (gpiod_line_request_input(echo_line, "hcsr04-echo") < 0) {
        fprintf(stderr, "Failed to request echo line as input: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* Open log file once in append mode */
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("HC-SR04 distance logger started. Logging to %s\n", LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    while (running) {
        /* Ensure trigger is LOW before pulse */
        if (gpiod_line_set_value(trigger_line, 0) < 0) {
            fprintf(stderr, "Failed to set trigger LOW: %s\n", strerror(errno));
            break;
        }
        sleep_ms(2);

        /* Generate 10 us trigger pulse */
        if (gpiod_line_set_value(trigger_line, 1) < 0) {
            fprintf(stderr, "Failed to set trigger HIGH: %s\n", strerror(errno));
            break;
        }
        sleep_ms(0);
        if (gpiod_line_set_value(trigger_line, 0) < 0) {
            fprintf(stderr, "Failed to set trigger LOW: %s\n", strerror(errno));
            break;
        }

        /* Measure echo pulse width */
        long duration_us = measure_echo(echo_line);
        if (duration_us < 0) {
            fprintf(stderr, "Measurement error, logging -1\n");
            log_distance(log_fp, -1);
        } else {
            float distance_cm = (float)duration_us * SPEED_OF_SOUND_CM_PER_US;
            printf("Distance: %.2f cm\n", distance_cm);
            log_distance(log_fp, (long)distance_cm);
        }

        /* Guard time to avoid false echoes */
        sleep_ms(GUARD_MS);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (log_fp != NULL) {
        fclose(log_fp);
        log_fp = NULL;
    }
    if (trigger_line != NULL) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line != NULL) {
        gpiod_line_release(echo_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    printf("\nResources released. Exiting.\n");
    return ret;
}

