#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L1X_ADDR   0x29
#define RELAY_GPIO     18
#define DISTANCE_THRESHOLD 50
#define POLL_DELAY_US  100000

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define REG_SOFT_RESET              0x0000
#define REG_SYSTEM_INTERRUPT_CLEAR  0x0086
#define REG_SYSTEM_INTERRUPT_STATUS 0x0044
#define REG_RESULT_RANGE_STATUS     0x0089
#define REG_RESULT_DISTANCE_MSB     0x0096
#define REG_RESULT_DISTANCE_LSB     0x0097
#define REG_SYSTEM_RANGE_START      0x0080

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit register address + 8-bit value using pigpio's i2cWriteI2CBlockData */
static int vl53l1x_write_reg8(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteI2CBlockData(handle, buf[0], &buf[1], 2);
}

/* Read an 8-bit register from a 16-bit address */
static int vl53l1x_read_reg8(int handle, uint16_t reg, uint8_t *out)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (i2cWriteI2CBlockData(handle, addr[0], &addr[1], 1) < 0)
        return -1;
    char val;
    if (i2cReadI2CBlockData(handle, addr[0], &val, 1) != 1)
        return -1;
    *out = (uint8_t)val;
    return 0;
}

/* Read a 16-bit register from a 16-bit address (big-endian on the bus) */
static int vl53l1x_read_reg16(int handle, uint16_t reg, uint16_t *out)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (i2cWriteI2CBlockData(handle, addr[0], &addr[1], 1) < 0)
        return -1;
    char buf[2];
    if (i2cReadI2CBlockData(handle, addr[0], buf, 2) != 2)
        return -1;
    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int vl53l1x_init(int handle)
{
    /* Software reset */
    if (vl53l1x_write_reg8(handle, REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write soft reset register\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle */

    /* Clear any pending interrupts */
    if (vl53l1x_write_reg8(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
        fprintf(stderr, "Error: failed to clear interrupts\n");
        return -1;
    }

    /* Start continuous ranging */
    if (vl53l1x_write_reg8(handle, REG_SYSTEM_RANGE_START, 0x01) < 0) {
        fprintf(stderr, "Error: failed to start ranging\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms for first measurement */
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status;
    if (vl53l1x_read_reg8(handle, REG_SYSTEM_INTERRUPT_STATUS, &status) < 0) {
        fprintf(stderr, "Error: failed to read interrupt status\n");
        return -1;
    }
    if ((status & 0x01) == 0) {
        return 1; /* no new data yet */
    }

    uint16_t range_status;
    if (vl53l1x_read_reg16(handle, REG_RESULT_RANGE_STATUS, &range_status) < 0) {
        fprintf(stderr, "Error: failed to read range status\n");
        return -1;
    }

    if ((range_status & 0x07) != 0x01) {
        /* Data not ready or error */
        return 1;
    }

    uint16_t dist_mm;
    if (vl53l1x_read_reg16(handle, REG_RESULT_DISTANCE_MSB, &dist_mm) < 0) {
        fprintf(stderr, "Error: failed to read distance registers\n");
        return -1;
    }

    *distance_mm = dist_mm;
    /* Clear interrupt so next measurement can be flagged */
    if (vl53l1x_write_reg8(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
        fprintf(stderr, "Warning: failed to clear interrupt\n");
    }
    return 0;
}

static void control_relay(int gpio_pin, int distance_mm)
{
    int level = (distance_mm <= (DISTANCE_THRESHOLD * 10)) ? 1 : 0;
    if (gpioWrite(gpio_pin, level) < 0) {
        fprintf(stderr, "Warning: failed to write relay GPIO %d\n", gpio_pin);
    }
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at addr 0x%02X (code %d)\n",
                I2C_BUS, VL53L1X_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed (sensor absent or bus error)\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", RELAY_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Proximity-based automated door system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t distance_mm;
        int rc = vl53l1x_read_distance(g_i2c_handle, &distance_mm);

        if (rc == 0) {
            printf("Distance: %u mm\n", distance_mm);
            control_relay(RELAY_GPIO, distance_mm);
        } else if (rc < 0) {
            fprintf(stderr, "Error: I2C read failure, continuing...\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown */
    gpioWrite(RELAY_GPIO, 0);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

