/*
 * Automated Plant Watering System (libgpiod v1)
 * Board:  Raspberry Pi 4 Model B
 * Relays: 4 x 5V relay modules on BCM GPIO17, GPIO18, GPIO27, GPIO22
 * Timing:  Every 86400 s (24 h) — first cycle starts immediately
 * Log:     watering_log.txt  (YYYY-MM-DD HH:MM:SS)
 *
 * Build:  gcc -O2 -Wall -Wextra -o watering watering.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_RELAYS      4
#define WATERING_SEC    5
#define POLL_SEC        60
#define LOG_FILE        "watering_log.txt"
#define CHIP_NAME       "gpiochip0"

static const unsigned int relay_pins[NUM_RELAYS] = {17, 18, 27, 22};

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int log_watering_start(void)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time");
        fclose(fp);
        return -1;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s\n", ts) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }

    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_RELAYS];
    int lines_requested = 0;
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_RELAYS; i++)
        lines[i] = NULL;

    /* --- Signal handling ---------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        goto cleanup;
    }

    /* --- Open GPIO chip ---------------------------------------------- */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name(" CHIP_NAME ")");
        goto cleanup;
    }

    /* --- Request relay lines as outputs (active-low) ----------------- */
    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for BCM %u: %s\n",
                    relay_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_output(lines[i], "watering", 1) < 0) {
            fprintf(stderr, "gpiod_line_request_output failed for BCM %u: %s\n",
                    relay_pins[i], strerror(errno));
            goto cleanup;
        }
        lines_requested++;
    }

    printf("Automated Plant Watering System started.\n");
    printf("Relays on BCM GPIO17, GPIO18, GPIO27, GPIO22.  Watering every %d s.\n",
           WATERING_SEC);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop ---------------------------------------------------- */
    while (g_running) {
        time_t now = time(NULL);
        if (now == (time_t)-1) {
            perror("time");
            break;
        }

        struct tm tm;
        if (localtime_r(&now, &tm) == NULL) {
            perror("localtime_r");
            break;
        }

        char ts[32];
        if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
            fprintf(stderr, "strftime failed\n");
            break;
        }

        printf("[%s] Watering cycle started.\n", ts);

        if (log_watering_start() < 0) {
            fprintf(stderr, "Warning: failed to log start time.\n");
        }

        for (int i = 0; i < NUM_RELAYS && g_running; i++) {
            if (gpiod_line_set_value(lines[i], 0) < 0) {
                fprintf(stderr, "gpiod_line_set_value failed for BCM %u: %s\n",
                        relay_pins[i], strerror(errno));
                goto cleanup;
            }
            printf("[%s] Relay BCM %u activated.\n", ts, relay_pins[i]);

            /* Sleep WATERING_SEC, but wake early on signal */
            for (int s = 0; s < WATERING_SEC && g_running; s++)
                sleep(1);
            if (g_running) {
                if (gpiod_line_set_value(lines[i], 1) < 0) {
                    fprintf(stderr, "gpiod_line_set_value failed for BCM %u: %s\n",
                            relay_pins[i], strerror(errno));
                    goto cleanup;
                }
                printf("[%s] Relay BCM %u deactivated.\n", ts, relay_pins[i]);
            }
        }

        /* Sleep POLL_SEC between cycles, but wake early on signal */
        for (int s = 0; s < POLL_SEC && g_running; s++)
            sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* --- Release lines and close chip -------------------------------- */
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }

    if (ret == EXIT_SUCCESS)
        printf("Shutdown complete.\n");

    return ret;
}

