#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

#define PWM_FREQUENCY 1000
#define SUNRISE_DURATION 1800
#define STEP_DELAY_US 1000000

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

void log_event(const char *message) {
    FILE *fp = fopen("smart_lighting.log", "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }

    if (gpioSetPWMfrequency(RELAY1_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", RELAY1_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMfrequency(RELAY2_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", RELAY2_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMfrequency(RELAY3_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", RELAY3_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMfrequency(RELAY4_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", RELAY4_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

void cleanup() {
    gpioPWM(RELAY1_PIN, 0);
    gpioPWM(RELAY2_PIN, 0);
    gpioPWM(RELAY3_PIN, 0);
    gpioPWM(RELAY4_PIN, 0);
    gpioTerminate();
    log_event("Program terminated gracefully.");
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    log_event("Smart lighting system started.");

    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    int num_relays = sizeof(pins) / sizeof(pins[0]);

    for (int i = 0; i < SUNRISE_DURATION && program_running; i += STEP_DELAY_US / 1000) {
        int duty_cycle = (int)(((float)i / SUNRISE_DURATION) * 255.0f);
        if (duty_cycle > 255) duty_cycle = 255;

        for (int j = 0; j < num_relays; j++) {
            if (gpioPWM(pins[j], duty_cycle) != 0) {
                fprintf(stderr, "Failed to set PWM on GPIO %d\n", pins[j]);
                cleanup();
                return 1;
            }
        }

        char log_message[128];
        snprintf(log_message, sizeof(log_message), "Sunrise step %d: Duty cycle = %d", i / 1000, duty_cycle);
        log_event(log_message);

        gpioDelay(STEP_DELAY_US);
    }

    cleanup();
    return 0;
}

