    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    int num_relays = sizeof(pins) / sizeof(pins[0]);

    for (int i = 0; i < SUNRISE_DURATION && program_running; i += STEP_DELAY_US / 1000) {
        int duty_cycle = (int)(((float)i / SUNRISE_DURATION) * 255.0f);
        if (duty_cycle > 255) duty_cycle = 255;

        for (int j = 0; j < num_relays; j++) {
            if (gpioPWM(pins[j], duty_cycle) != 0) {
                fprintf(stderr, "Failed to set PWM on GPIO %d\n", pins[j]);
                cleanup();
                return 1;
            }
        }

        char log_message[128];
        snprintf(log_message, sizeof(log_message), "Sunrise step %d: Duty cycle = %d", i / 1000, duty_cycle);
        log_event(log_message);

        gpioDelay(STEP_DELAY_US);
    }

