#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <math.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define MPU6050_WHO_AM_I   0x75
#define MPU6050_WHO_AM_I_VAL 0x68
#define MPU6050_PWR_MGMT_1  0x6B
#define MPU6050_SMPLRT_DIV  0x19
#define MPU6050_GYRO_CONFIG 0x1B
#define MPU6050_GYRO_XOUT_H 0x43

/* GPIO pin for LED */
#define LED_PIN 17

/* Threshold for angular velocity (degrees/second) */
#define THRESHOLD 250.0

/* Circular buffer size */
#define BUFFER_SIZE 100

/* I2C bus on Raspberry Pi 3 Model B+ */
#define I2C_BUS 1

/* Sample period in microseconds (20 Hz) */
#define SAMPLE_PERIOD_US 50000

/* Number of consecutive read failures before giving up */
#define MAX_REINIT_ATTEMPTS 3

/* Gyroscope sensitivity for ±250 deg/s range: 131 LSB/deg/s */
#define GYRO_SENSITIVITY 131.0

typedef struct {
    struct timespec timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

static gyro_data_t gyro_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int init_mpu6050(void) {
    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, MPU6050_ADDR, i2c_handle);
        return -1;
    }

    /* Verify sensor identity */
    int who = i2cReadByteData(i2c_handle, MPU6050_WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }
    if (who != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, MPU6050_WHO_AM_I_VAL);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    /* Wake up the MPU-6050 (clear sleep bit) */
    if (i2cWriteByteData(i2c_handle, MPU6050_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error writing PWR_MGMT_1\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }
    gpioDelay(100000); /* 100 ms settle time */

    /* Set sample rate divider: 1 kHz / (1 + 7) = 125 Hz internal, 1 kHz output */
    if (i2cWriteByteData(i2c_handle, MPU6050_SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Error writing SMPLRT_DIV\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    /* Set gyroscope full-scale range to ±250 deg/s */
    if (i2cWriteByteData(i2c_handle, MPU6050_GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing GYRO_CONFIG\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    return 0;
}

static int read_gyro_data(float *x, float *y, float *z) {
    char buf[6];

    int bytes = i2cReadI2CBlockData(i2c_handle, MPU6050_GYRO_XOUT_H, buf, 6);
    if (bytes != 6) {
        fprintf(stderr, "Error reading gyroscope data: got %d bytes, expected 6\n", bytes);
        return -1;
    }

    int16_t raw_x = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | (uint8_t)buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | (uint8_t)buf[5]);

    *x = (float)raw_x / GYRO_SENSITIVITY;
    *y = (float)raw_y / GYRO_SENSITIVITY;
    *z = (float)raw_z / GYRO_SENSITIVITY;

    return 0;
}

static void add_to_buffer(float x, float y, float z) {
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;
    gyro_buffer[buffer_index].timestamp = clock_gettime(CLOCK_MONOTONIC);

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

static bool threshold_exceeded(float x, float y, float z) {
    return (fabsf(x) > THRESHOLD) ||
           (fabsf(y) > THRESHOLD) ||
           (fabsf(z) > THRESHOLD);
}

static void control_led(bool on) {
    gpioWrite(LED_PIN, on ? 1 : 0);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    if (init_mpu6050() != 0) {
        fprintf(stderr, "MPU-6050 initialisation failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float x, y, z;
    int reinit_attempts = 0;

    while (program_running) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            reinit_attempts = 0;
            add_to_buffer(x, y, z);
            bool exceeded = threshold_exceeded(x, y, z);
            control_led(exceeded);
        } else {
            reinit_attempts++;
            fprintf(stderr, "Gyro read failed (%d/%d)\n", reinit_attempts, MAX_REINIT_ATTEMPTS);
            if (reinit_attempts >= MAX_REINIT_ATTEMPTS) {
                fprintf(stderr, "Max re-initialisation attempts reached. Exiting.\n");
                break;
            }
            if (i2c_handle >= 0) {
                i2cClose(i2c_handle);
                i2c_handle = -1;
            }
            gpioDelay(100000); /* 100 ms back-off before retry */
            if (init_mpu6050() != 0) {
                fprintf(stderr, "Re-initialisation failed. Exiting.\n");
                break;
            }
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

