/*
 * MPU-6050 Gyroscope Stability Monitor (SPI, libgpiod)
 * Board: Raspberry Pi 3 Model B+
 * SPI:  /dev/spidev0.0  (CE0 on GPIO8), ~3.9 MHz, mode 0
 * LED:  GPIO17 (physical pin 11)
 *
 * Build: gcc -O2 -Wall -o mpu6050_mon mpu6050_mon.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

/* ---- Configuration ---- */
#define SPI_DEVICE        "/dev/spidev0.0"
#define SPI_SPEED_HZ      3900000U   /* ~3.9 MHz — well within MPU-6050 spec */
#define SPI_MODE          SPI_MODE_0
#define SPI_BITS_PER_WORD 8

#define CS_GPIO_LINE      8          /* GPIO8 = CE0 */
#define LED_GPIO_LINE     17         /* GPIO17 */

#define GYRO_XOUT_H_REG   0x43
#define GYRO_YOUT_H_REG   0x45
#define GYRO_ZOUT_H_REG   0x47

#define THRESHOLD_DEG_S   200.0f
#define LED_ON_MS         500
#define LED_OFF_MS        500
#define SAMPLE_PERIOD_MS  100
#define BUFFER_SIZE       64

/* ---- Data structures ---- */
typedef struct {
    struct timespec timestamp;
    float x, y, z;
} gyro_data_t;

typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_cs_line = NULL;
static struct gpiod_line *g_led_line = NULL;

/* ---- Signal handler ---- */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- SPI helpers ---- */
static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        goto fail;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        goto fail;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        goto fail;
    }

    return 0;

fail:
    close(g_spi_fd);
    g_spi_fd = -1;
    return -1;
}

static void spi_close(void)
{
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

/* ---- GPIO helpers (libgpiod) ---- */
static int gpio_init(void)
{
    g_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!g_chip) {
        fprintf(stderr, "gpiod_chip_open: %s\n", strerror(errno));
        return -1;
    }

    g_cs_line = gpiod_chip_get_line(g_chip, CS_GPIO_LINE);
    if (!g_cs_line) {
        fprintf(stderr, "gpiod get CS line %d: %s\n", CS_GPIO_LINE, strerror(errno));
        return -1;
    }

    g_led_line = gpiod_chip_get_line(g_chip, LED_GPIO_LINE);
    if (!g_led_line) {
        fprintf(stderr, "gpiod get LED line %d: %s\n", LED_GPIO_LINE, strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(g_cs_line, "mpu6050-cs", 1) < 0) {
        fprintf(stderr, "gpiod request CS output: %s\n", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(g_led_line, "mpu6050-led", 0) < 0) {
        fprintf(stderr, "gpiod request LED output: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void gpio_close(void)
{
    if (g_cs_line) {
        gpiod_line_set_value(g_cs_line, 1);
        gpiod_line_release(g_cs_line);
        g_cs_line = NULL;
    }
    if (g_led_line) {
        gpiod_line_set_value(g_led_line, 0);
        gpiod_line_release(g_led_line);
        g_led_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

/* ---- MPU-6050 register read (single byte, manual CS) ---- */
static int mpu_read_reg(uint8_t reg, uint8_t *val)
{
    if (g_cs_line == NULL || val == NULL)
        return -1;

    /* Pull CS low */
    if (gpiod_line_set_value(g_cs_line, 0) < 0) {
        fprintf(stderr, "CS low: %s\n", strerror(errno));
        return -1;
    }

    /* Small delay to ensure CS settles */
    usleep(10);

    /* SPI transfer: send register address, receive data */
    uint8_t tx[2] = { reg, 0x00 };
    uint8_t rx[2] = { 0, 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 2;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS_PER_WORD;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE (reg 0x%02X): %s\n", reg, strerror(errno));
        gpiod_line_set_value(g_cs_line, 1);
        return -1;
    }

    /* Pull CS high */
    if (gpiod_line_set_value(g_cs_line, 1) < 0) {
        fprintf(stderr, "CS high: %s\n", strerror(errno));
        return -1;
    }

    *val = rx[1];
    return 0;
}

/* ---- Read 16-bit gyroscope axis (high byte first) ---- */
static int read_gyro_axis(uint8_t reg, float *out)
{
    uint8_t hi, lo;
    if (mpu_read_reg(reg, &hi) < 0)
        return -1;
    if (mpu_read_reg(reg + 1, &lo) < 0)
        return -1;

    int16_t raw = (int16_t)((hi << 8) | lo);
    *out = (float)raw / 131.0f;   /* ±131.0 LSB/(deg/s) */
    return 0;
}

/* ---- Circular buffer ---- */
static void cb_init(circular_buffer_t *cb)
{
    memset(cb, 0, sizeof(*cb));
}

static void cb_add(circular_buffer_t *cb, const gyro_data_t *d)
{
    cb->data[cb->head] = *d;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

static void cb_print(const circular_buffer_t *cb)
{
    printf("\n--- Gyroscope Data (sorted by timestamp) ---\n");
    printf("Timestamp,X(d/s),Y(d/s),Z(d/s)\n");
    for (int i = 0; i < cb->count; i++) {
        int idx = (cb->head - cb->count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char ts[40];
        struct tm tm_info;
        localtime_r(&cb->data[idx].timestamp.tv_sec, &tm_info);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        printf("%s.%03ld,%+.2f,%+.2f,%+.2f\n",
               ts, cb->data[idx].timestamp.tv_nsec / 1000000L,
               cb->data[idx].x, cb->data[idx].y, cb->data[idx].z);
    }
    printf("--- End of data ---\n\n");
}

/* ---- Threshold check ---- */
static bool check_threshold(float x, float y, float z)
{
    return (x >  THRESHOLD_DEG_S || x < -THRESHOLD_DEG_S ||
            y >  THRESHOLD_DEG_S || y < -THRESHOLD_DEG_S ||
            z >  THRESHOLD_DEG_S || z < -THRESHOLD_DEG_S);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    gpio_close();
    spi_close();
    cb_print(NULL);   /* prints buffer contents */
}

/* ---- Main ---- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialisation failed.\n");
        return 1;
    }

    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialisation failed.\n");
        spi_close();
        return 1;
    }

    circular_buffer_t gyro_buffer;
    cb_init(&gyro_buffer);

    printf("MPU-6050 Gyroscope Stability Monitor\n");
    printf("SPI: %s @ %u Hz, CS=GPIO%d, LED=GPIO%d\n",
           SPI_DEVICE, SPI_SPEED_HZ, CS_GPIO_LINE, LED_GPIO_LINE);
    printf("Threshold: ±%.1f deg/s. Press Ctrl+C to exit.\n\n", THRESHOLD_DEG_S);

    while (g_running) {
        gyro_data_t sample;
        sample.x = sample.y = sample.z = 0.0f;
        sample.timestamp = clock_gettime(CLOCK_MONOTONIC);

        if (read_gyro_axis(GYRO_XOUT_H_REG, &sample.x) < 0 ||
            read_gyro_axis(GYRO_YOUT_H_REG, &sample.y) < 0 ||
            read_gyro_axis(GYRO_ZOUT_H_REG, &sample.z) < 0) {
            fprintf(stderr, "Sensor read error — skipping sample.\n");
            usleep(SAMPLE_PERIOD_MS * 1000);
            continue;
        }

        cb_add(&gyro_buffer, &sample);

        if (check_threshold(sample.x, sample.y, sample.z)) {
            printf("[ALERT] Threshold exceeded: X=%.2f Y=%.2f Z=%.2f deg/s\n",
                   sample.x, sample.y, sample.z);
            if (g_led_line) {
                gpiod_line_set_value(g_led_line, 1);
                usleep(LED_ON_MS * 1000);
                gpiod_line_set_value(g_led_line, 0);
                usleep(LED_OFF_MS * 1000);
            }
        }

        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

