        fprintf(stderr, "SPI_IOC_MESSAGE (reg 0x%02X): %s\n", reg, strerror(errno));
        gpiod_line_set_value(g_cs_line, 1);
        return -1;
    }

    /* Pull CS high */
    if (gpiod_line_set_value(g_cs_line, 1) < 0) {
        fprintf(stderr, "CS high: %s\n", strerror(errno));
        return -1;
    }

    *val = rx[1];
    return 0;
}

/* ---- Read 16-bit gyroscope axis (high byte first) ---- */
static int read_gyro_axis(uint8_t reg, float *out)
{
    uint8_t hi, lo;
    if (mpu_read_reg(reg, &hi) < 0)
        return -1;
    if (mpu_read_reg(reg + 1, &lo) < 0)
        return -1;

    int16_t raw = (int16_t)((hi << 8) | lo);
    *out = (float)raw / 131.0f;   /* ±131.0 LSB/(deg/s) */
    return 0;
}

/* ---- Circular buffer ---- */
static void cb_init(circular_buffer_t *cb)
{
    memset(cb, 0, sizeof(*cb));
}

static void cb_add(circular_buffer_t *cb, const gyro_data_t *d)
{
    cb->data[cb->head] = *d;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

static void cb_print(const circular_buffer_t *cb)
{
    printf("\n--- Gyroscope Data (sorted by timestamp) ---\n");
    printf("Timestamp,X(d/s),Y(d/s),Z(d/s)\n");
    for (int i = 0; i < cb->count; i++) {
        int idx = (cb->head - cb->count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char ts[40];
        struct tm tm_info;
        localtime_r(&cb->data[idx].timestamp.tv_sec, &tm_info);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        printf("%s.%03ld,%+.2f,%+.2f,%+.2f\n",
               ts, cb->data[idx].timestamp.tv_nsec / 1000000L,
               cb->data[idx].x, cb->data[idx].y, cb->data[idx].z);
    }
    printf("--- End of data ---\n\n");
}

/* ---- Threshold check ---- */
static bool check_threshold(float x, float y, float z)
{
    return (x >  THRESHOLD_DEG_S || x < -THRESHOLD_DEG_S ||
            y >  THRESHOLD_DEG_S || y < -THRESHOLD_DEG_S ||
            z >  THRESHOLD_DEG_S || z < -THRESHOLD_DEG_S);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    gpio_close();
    spi_close();
    cb_print(NULL);   /* prints buffer contents */
}

/* ---- Main ---- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialisation failed.\n");
        return 1;
    }

    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialisation failed.\n");
        spi_close();
        return 1;
    }

    circular_buffer_t gyro_buffer;
    cb_init(&gyro_buffer);

    printf("MPU-6050 Gyroscope Stability Monitor\n");
    printf("SPI: %s @ %u Hz, CS=GPIO%d, LED=GPIO%d\n",
           SPI_DEVICE, SPI_SPEED_HZ, CS_GPIO_LINE, LED_GPIO_LINE);
    printf("Threshold: ±%.1f deg/s. Press Ctrl+C to exit.\n\n", THRESHOLD_DEG_S);

    while (g_running) {
        gyro_data_t sample;
        sample.x = sample.y = sample.z = 0.0f;
        sample.timestamp = clock_gettime(CLOCK_MONOTONIC);

        if (read_gyro_axis(GYRO_XOUT_H_REG, &sample.x) < 0 ||
            read_gyro_axis(GYRO_YOUT_H_REG, &sample.y) < 0 ||
            read_gyro_axis(GYRO_ZOUT_H_REG, &sample.z) < 0) {
            fprintf(stderr, "Sensor read error — skipping sample.\n");
            usleep(SAMPLE_PERIOD_MS * 1000);
            continue;
        }

        cb_add(&gyro_buffer, &sample);

        if (check_threshold(sample.x, sample.y, sample.z)) {
            printf("[ALERT] Threshold exceeded: X=%.2f Y=%.2f Z=%.2f deg/s\n",
                   sample.x, sample.y, sample.z);
            if (g_led_line) {
                gpiod_line_set_value(g_led_line, 1);
                usleep(LED_ON_MS * 1000);
                gpiod_line_set_value(g_led_line, 0);
                usleep(LED_OFF_MS * 1000);
            }
        }

        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

