#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define PWR_MGMT_1   0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B
#define ACCEL_XOUT_L 0x3C
#define ACCEL_YOUT_H 0x3D
#define ACCEL_YOUT_L 0x3E
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_ZOUT_L 0x40

/* GPIO pin for LED */
#define LED_PIN 21

/* Tilt threshold in degrees */
#define TILT_THRESHOLD 45.0

/* Sampling interval in microseconds (100 ms) */
#define SAMPLE_INTERVAL_US 100000

/* Global variables for cleanup */
static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

/* Function prototypes */
static int init_mpu6050(void);
static int read_accelerometer(int16_t *x, int16_t *y, int16_t *z);
static double calculate_roll(int16_t x, int16_t y, int16_t z);
static double calculate_pitch(int16_t x, int16_t y, int16_t z);
static void control_led(double roll, double pitch);
static void log_tilt_data(double roll, double pitch);
static void signal_handler(int signal);
static void cleanup(void);

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* Initialize MPU-6050: wake up and set accelerometer range to ±2g */
static int init_mpu6050(void) {
    /* Wake up: clear sleep bit (bit 6) in PWR_MGMT_1 */
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write PWR_MGMT_1 (wake up MPU-6050)\n");
        return -1;
    }
    /* Allow time for oscillator to stabilise after wake-up */
    gpioDelay(100000); /* 100 ms */

    /* Set accelerometer full-scale range to ±2g (AFS_SEL = 0) */
    if (i2cWriteByteData(i2c_handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write ACCEL_CONFIG\n");
        return -1;
    }

    /* Verify configuration by reading back PWR_MGMT_1 */
    int pwr_mg1 = i2cReadByteData(i2c_handle, PWR_MGMT_1);
    if (pwr_mg1 < 0) {
        fprintf(stderr, "Error: Failed to read back PWR_MGMT_1\n");
        return -1;
    }
    if ((pwr_mg1 & 0x40) == 0) {
        fprintf(stderr, "Error: MPU-6050 not responding at 0x%02X\n", MPU6050_ADDR);
        return -1;
    }

    return 0;
}

/* Read 6 bytes of accelerometer data (X, Y, Z) */
static int read_accelerometer(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buffer, 6) != 6) {
        fprintf(stderr, "Error: Failed to read accelerometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

/* Calculate roll angle in degrees */
static double calculate_roll(int16_t x, int16_t y, int16_t z) {
    return atan2((double)y, (double)z) * 180.0 / M_PI;
}

/* Calculate pitch angle in degrees */
static double calculate_pitch(int16_t x, int16_t y, int16_t z) {
    return atan2(-(double)x, sqrt((double)y * y + (double)z * z)) * 180.0 / M_PI;
}

/* Control LED based on tilt threshold */
static void control_led(double roll, double pitch) {
    if (fabs(roll) > TILT_THRESHOLD || fabs(pitch) > TILT_THRESHOLD) {
        gpioWrite(LED_PIN, 1);
    } else {
        gpioWrite(LED_PIN, 0);
    }
}

/* Log tilt data to file */
static void log_tilt_data(double roll, double pitch) {
    FILE *fp = fopen("tilt_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open tilt_log.txt for appending\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, roll, pitch);
    fclose(fp);
}

int main(void) {
    /* Register signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C bus 1 at MPU-6050 address */
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X\n", MPU6050_ADDR);
        gpioTerminate();
        return 1;
    }

    /* Initialize MPU-6050 */
    if (init_mpu6050() < 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        cleanup();
        return 1;
    }

    /* Configure LED pin as output */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    int16_t x, y, z;
    double roll, pitch;

    /* Main loop */
    while (running) {
        if (read_accelerometer(&x, &y, &z) == 0) {
            roll = calculate_roll(x, y, z);
            pitch = calculate_pitch(x, y, z);

            control_led(roll, pitch);
            log_tilt_data(roll, pitch);

            printf("Roll: %.2f degrees, Pitch: %.2f degrees\n", roll, pitch);
        } else {
            fprintf(stderr, "Warning: Sensor read failed, continuing...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Graceful shutdown */
    cleanup();
    return 0;
}

