#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1145_ADDR    0x5A
#define REG_ALS_DATA   0x20
#define REG_PS_DATA    0x22
#define PROX_THRESHOLD 100
#define LED_PIN        17
#define LOG_FILE       "biometric_log.txt"
#define SAMPLE_MS      100
#define I2C_RETRIES    3
#define I2C_RETRY_MS   10

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    for (int i = 0; i < I2C_RETRIES; i++) {
        if (write(fd, buf, 2) == 2) return 0;
        usleep(I2C_RETRY_MS * 1000);
    }
    return -1;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    for (int i = 0; i < I2C_RETRIES; i++) {
        if (write(fd, &reg, 1) != 1) { usleep(I2C_RETRY_MS * 1000); continue; }
        uint8_t buf[2];
        if (read(fd, buf, 2) != 2) { usleep(I2C_RETRY_MS * 1000); continue; }
        *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
        return 0;
    }
    return -1;
}

static void log_data(uint16_t als, uint16_t ps) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(log_fp, "%s,AmbientLight:%04X,Proximity:%04X\n", ts, als, ps);
    fflush(log_fp);
}

static void cleanup(void) {
    if (led_line) { gpiod_line_set_value(led_line, 0); gpiod_line_release(led_line); led_line = NULL; }
    if (chip) { gpiod_chip_close(chip); chip = NULL; }
    if (log_fp) { fclose(log_fp); log_fp = NULL; }
    if (i2c_fd >= 0) { close(i2c_fd); i2c_fd = -1; }
}

int main(void) {
    struct sigaction sa = { .sa_handler = sig_handler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) { perror("open i2c"); return 1; }
    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) { perror("fopen log"); cleanup(); return 1; }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) { perror("gpiod_chip_open"); cleanup(); return 1; }
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) { perror("gpiod_chip_get_line"); cleanup(); return 1; }
    if (gpiod_line_request_output(led_line, "si1145_led", 0) < 0) {
        perror("gpiod_line_request_output"); cleanup(); return 1;
    }

    while (running) {
        uint16_t als = 0, ps = 0;
        if (i2c_read_reg16(i2c_fd, REG_ALS_DATA, &als) < 0) {
            fprintf(stderr, "ALS read error\n");
        }
        if (i2c_read_reg16(i2c_fd, REG_PS_DATA, &ps) < 0) {
            fprintf(stderr, "PS read error\n");
        }
        log_data(als, ps);
        gpiod_line_set_value(led_line, ps > PROX_THRESHOLD ? 1 : 0);
        usleep(SAMPLE_MS * 1000);
    }

    cleanup();
    return 0;
}

