#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADXRS290 register addresses */
#define ADXRS290_REG_XGYRO_OUT 0x02
#define ADXRS290_REG_YGYRO_OUT 0x04

/* SPI configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* mode 0, active-low CE */

/* Sampling */
#define SAMPLE_PERIOD_US 10000  /* 10 ms -> ~100 Hz */
#define MAX_REINIT_ATTEMPTS 3

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    int16_t x_rate;
    int16_t y_rate;
} gyro_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Read a 16-bit register (two's complement, high byte first) */
static int read_register(int handle, uint8_t reg, int16_t *out) {
    char tx[2] = { (char)(reg | 0x80), 0x00 };
    char rx[2] = { 0, 0 };

    if (spiXfer(handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X\n", reg);
        return -1;
    }
    *out = (int16_t)(((uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

static int read_gyro_data(int handle, gyro_data_t *data) {
    if (read_register(handle, ADXRS290_REG_XGYRO_OUT, &data->x_rate) != 0)
        return -1;
    if (read_register(handle, ADXRS290_REG_YGYRO_OUT, &data->y_rate) != 0)
        return -1;
    return 0;
}

static int log_data(FILE *f, const gyro_data_t *data) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }
    if (fprintf(f, "%ld.%06ld,%d,%d\n",
                (long)ts.tv_sec, ts.tv_nsec / 1000,
                data->x_rate, data->y_rate) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(f) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (fp != NULL) {
        fflush(fp);
        fclose(fp);
        fp = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, %d Hz): %d\n",
                SPI_CHANNEL, SPI_SPEED, spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fp = fopen("gyro_data.csv", "w");
    if (fp == NULL) {
        perror("fopen");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (fprintf(fp, "timestamp,x_rate,y_rate\n") < 0 || fflush(fp) != 0) {
        perror("initial fprintf/fflush");
        cleanup();
        return EXIT_FAILURE;
    }

    gyro_data_t gyro_data;
    int reinit_attempts = 0;

    while (!terminate) {
        if (read_gyro_data(spi_handle, &gyro_data) != 0) {
            fprintf(stderr, "Gyro read failed; reinitialising SPI...\n");
            spiClose(spi_handle);
            spi_handle = -1;
            if (++reinit_attempts > MAX_REINIT_ATTEMPTS) {
                fprintf(stderr, "Max reinitialisation attempts reached; exiting.\n");
                break;
            }
            spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
            if (spi_handle < 0) {
                fprintf(stderr, "SPI re-open failed: %d\n", spi_handle);
                break;
            }
            continue;
        }

        if (log_data(fp, &gyro_data) != 0) {
            fprintf(stderr, "Logging failed; exiting.\n");
            break;
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

