#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define ALERT_PIN    17
#define SEISMIC_THRESHOLD_MS 500
#define ALERT_DURATION_US  2000000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s - %s\n", timestamp, message);
    fflush(log_file);
}

static void sensor_callback(int gpio, int level, uint32_t tick) {
    (void)tick;
    static int s1_state = 0, s2_state = 0;
    static uint32_t s1_start_tick = 0, s2_start_tick = 0;
    static int s1_rising = 0, s2_rising = 0;

    if (gpio == SENSOR_1_PIN) {
        if (level == 1) {
            s1_state = 1;
            s1_rising = 1;
            s1_start_tick = gpioTick();
        } else if (level == 0) {
            s1_state = 0;
            s1_rising = 0;
        }
    } else if (gpio == SENSOR_2_PIN) {
        if (level == 1) {
            s2_state = 1;
            s2_rising = 1;
            s2_start_tick = gpioTick();
        } else if (level == 0) {
            s2_state = 0;
            s2_rising = 0;
        }
    }

    if (s1_rising && s2_rising) {
        uint32_t s1_duration = gpioTick() - s1_start_tick;
        uint32_t s2_duration = gpioTick() - s2_start_tick;
        if (s1_duration >= SEISMIC_THRESHOLD_MS * 1000 && s2_duration >= SEISMIC_THRESHOLD_MS * 1000) {
            s1_rising = 0;
            s2_rising = 0;
            gpioWrite(ALERT_PIN, 1);
            log_event("Seismic event detected!");
            gpioDelay(ALERT_DURATION_US);
            gpioWrite(ALERT_PIN, 0);
        }
    }
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_1_PIN);
        return -1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_2_PIN);
        return -1;
    }
    if (gpioSetMode(ALERT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", ALERT_PIN);
        return -1;
    }

    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO%d\n", SENSOR_1_PIN);
        return -1;
    }
    if (gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO%d\n", SENSOR_2_PIN);
        return -1;
    }

    if (gpioWrite(ALERT_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise alert pin LOW\n");
        return -1;
    }

    if (gpioSetAlertFunc(SENSOR_1_PIN, sensor_callback) != 0) {
        fprintf(stderr, "Failed to set alert function for GPIO%d\n", SENSOR_1_PIN);
        return -1;
    }
    if (gpioSetAlertFunc(SENSOR_2_PIN, sensor_callback) != 0) {
        fprintf(stderr, "Failed to set alert function for GPIO%d\n", SENSOR_2_PIN);
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(ALERT_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    log_file = fopen("seismic_events.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        return 1;
    }

    if (initialize_gpio() != 0) {
        fclose(log_file);
        log_file = NULL;
        return 1;
    }

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

