#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LAMP1_GPIO 17
#define LAMP2_GPIO 18
#define LAMP3_GPIO 27
#define PWM_RANGE 255
#define PWM_FREQ 100
#define DEFAULT_DURATION 60

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    int gpios[] = {LAMP1_GPIO, LAMP2_GPIO, LAMP3_GPIO};
    for (size_t i = 0; i < sizeof(gpios) / sizeof(gpios[0]); ++i) {
        if (gpioSetMode(gpios[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output.\n", gpios[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPWMrange(gpios[i], PWM_RANGE) < 0) {
            fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", gpios[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPWMfrequency(gpios[i], PWM_FREQ) < 0) {
            fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", gpios[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioPWM(gpios[i], 0) < 0) {
            fprintf(stderr, "Error: failed to initialise PWM on GPIO %d.\n", gpios[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static void fade_lamp(int gpio, int duration_seconds) {
    if (duration_seconds <= 0) {
        fprintf(stderr, "Error: invalid fade duration %d for GPIO %d.\n", duration_seconds, gpio);
        return;
    }

    int step_delay_us = (int)((duration_seconds * 1000000.0) / PWM_RANGE);
    if (step_delay_us < 1000) step_delay_us = 1000;

    for (int duty = PWM_RANGE; duty >= 0 && running; --duty) {
        if (gpioPWM(gpio, duty) < 0) {
            fprintf(stderr, "Error: failed to set PWM on GPIO %d.\n", gpio);
            return;
        }
        gpioDelay(step_delay_us);
    }
}

static void cleanup(void) {
    int gpios[] = {LAMP1_GPIO, LAMP2_GPIO, LAMP3_GPIO};
    for (size_t i = 0; i < sizeof(gpios) / sizeof(gpios[0]); ++i) {
        gpioPWM(gpios[i], 0);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <fade_duration_seconds>\n", argv[0]);
        return EXIT_FAILURE;
    }

    char *endptr = NULL;
    long duration = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0' || duration < 1 || duration > 3600) {
        fprintf(stderr, "Error: invalid duration '%s'. Must be 1-3600.\n", argv[1]);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Error: failed to register signal handler");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() < 0) {
        return EXIT_FAILURE;
    }

    printf("Smart Sunset Simulator started. Fading lamps over %ld seconds.\n", duration);
    printf("Press Ctrl+C to exit early.\n");

    fade_lamp(LAMP1_GPIO, duration);
    if (!running) {
        printf("\nInterrupted before lamp 1 completed.\n");
        cleanup();
        return EXIT_SUCCESS;
    }

    fade_lamp(LAMP2_GPIO, duration);
    if (!running) {
        printf("\nInterrupted before lamp 2 completed.\n");
        cleanup();
        return EXIT_SUCCESS;
    }

    fade_lamp(LAMP3_GPIO, duration);
    if (!running) {
        printf("\nInterrupted before lamp 3 completed.\n");
        cleanup();
        return EXIT_SUCCESS;
    }

    printf("Smart Sunset Simulator complete. All lamps off.\n");
    cleanup();
    return EXIT_SUCCESS;
}

