#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define RED_PIN   17
#define YELLOW_PIN 22
#define GREEN_PIN  23
#define BLUE_PIN   24

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[4] = {NULL, NULL, NULL, NULL};
    const unsigned int pins[4] = {RED_PIN, YELLOW_PIN, GREEN_PIN, BLUE_PIN};
    int ret;

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %u\n", pins[i]);
            goto cleanup;
        }
    }

    ret = gpiod_line_request_output(lines[0], "traffic-light", 1);
    if (ret) { perror("request RED"); goto cleanup; }
    ret = gpiod_line_request_output(lines[1], "traffic-light", 1);
    if (ret) { perror("request YELLOW"); goto cleanup; }
    ret = gpiod_line_request_output(lines[2], "traffic-light", 1);
    if (ret) { perror("request GREEN"); goto cleanup; }
    ret = gpiod_line_request_output(lines[3], "traffic-light", 1);
    if (ret) { perror("request BLUE"); goto cleanup; }

    while (running) {
        /* Red */
        ret = gpiod_line_set_value(lines[0], 0);
        if (ret) { perror("set RED"); break; }
        ret = gpiod_line_set_value(lines[1], 1);
        if (ret) { perror("set YELLOW"); break; }
        ret = gpiod_line_set_value(lines[2], 1);
        if (ret) { perror("set GREEN"); break; }
        ret = gpiod_line_set_value(lines[3], 1);
        if (ret) { perror("set BLUE"); break; }
        printf("Red\n");
        fflush(stdout);
        for (int i = 0; i < 10 && running; i++) sleep(1);

        if (!running) break;

        /* Red + Yellow */
        ret = gpiod_line_set_value(lines[0], 0);
        if (ret) { perror("set RED"); break; }
        ret = gpiod_line_set_value(lines[1], 0);
        if (ret) { perror("set YELLOW"); break; }
        ret = gpiod_line_set_value(lines[2], 1);
        if (ret) { perror("set GREEN"); break; }
        ret = gpiod_line_set_value(lines[3], 1);
        if (ret) { perror("set BLUE"); break; }
        printf("Red + Yellow\n");
        fflush(stdout);
        for (int i = 0; i < 2 && running; i++) sleep(1);

        if (!running) break;

        /* Green */
        ret = gpiod_line_set_value(lines[0], 1);
        if (ret) { perror("set RED"); break; }
        ret = gpiod_line_set_value(lines[1], 1);
        if (ret) { perror("set YELLOW"); break; }
        ret = gpiod_line_set_value(lines[2], 0);
        if (ret) { perror("set GREEN"); break; }
        ret = gpiod_line_set_value(lines[3], 1);
        if (ret) { perror("set BLUE"); break; }
        printf("Green\n");
        fflush(stdout);
        for (int i = 0; i < 10 && running; i++) sleep(1);

        if (!running) break;

        /* Yellow */
        ret = gpiod_line_set_value(lines[0], 1);
        if (ret) { perror("set RED"); break; }
        ret = gpiod_line_set_value(lines[1], 0);
        if (ret) { perror("set YELLOW"); break; }
        ret = gpiod_line_set_value(lines[2], 1);
        if (ret) { perror("set GREEN"); break; }
        ret = gpiod_line_set_value(lines[3], 1);
        if (ret) { perror("set BLUE"); break; }
        printf("Yellow\n");
        fflush(stdout);
        for (int i = 0; i < 3 && running; i++) sleep(1);
    }

cleanup:
    for (int i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 1);
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

