#define RELAY_GPIO 17
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define LOG_FILE "touch_relay.log"
#define DEBOUNCE_DELAY_MS 100
#define POLL_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void log_message(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "I2C write failed: reg=0x%02X, val=0x%02X, rc=%d", reg, value, rc);
        log_message(msg);
    }
    return rc;
}

static int mpr121_init(int handle) {
    if (mpr121_write(handle, 0x80, 0x63) < 0) return -1;  // Reset
    gpioDelay(1000);
    if (mpr121_write(handle, 0x5E, 0x00) < 0) return -1;  // Stop mode
    if (mpr121_write(handle, 0x5D, 0x01) < 0) return -1;  // Enable electrode 0
    if (mpr121_write(handle, 0x41, 0x0A) < 0) return -1;  // Touch threshold
    if (mpr121_write(handle, 0x42, 0x08) < 0) return -1;  // Release threshold
    if (mpr121_write(handle, 0x5B, 0x21) < 0) return -1;  // Debounce
    if (mpr121_write(handle, 0x5C, 0x0D) < 0) return -1;  // Charge time
    if (mpr121_write(handle, 0x5E, 0x0D) < 0) return -1;  // Run mode
    return 0;
}

static int read_touch_status(int handle) {
    int lsb = i2cReadByteData(handle, 0x00);
    if (lsb < 0) {
        log_message("I2C read failed: electrode 0 LSB");
        return -1;
    }
    int msb = i2cReadByteData(handle, 0x01);
    if (msb < 0) {
        log_message("I2C read failed: electrode 0 MSB");
        return -1;
    }
    return (msb << 8) | lsb;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    if (log_file) {
        log_message("Cleanup complete.");
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }
    log_message("Program started.");

    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        fclose(log_file);
        return 1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        char msg[128];
