    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int relay_state = 0;
    int last_touch = 0;

    while (running) {
        int touch = read_touch_status(i2c_handle);
        if (touch < 0) {
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (touch & 0x01) {
            if (last_touch != 1) {
                gpioDelay(DEBOUNCE_DELAY_MS * 1000);
                if (relay_state == 0) {
                    gpioWrite(RELAY_GPIO, 1);
                    relay_state = 1;
                    log_message("Relay turned ON");
                } else {
                    gpioWrite(RELAY_GPIO, 0);
                    relay_state = 0;
                    log_message("Relay turned OFF");
                }
                last_touch = touch;
            }
        } else {
            last_touch = 0;
        }

        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return 0;
}

