#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18
#define LED_PIN 23
#define DEBOUNCE_SAMPLES 3
#define DEBOUNCE_DELAY_MS 50
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *flame_line = NULL;
static struct gpiod_line *buzzer_line = NULL;
static struct gpiod_line *led_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_event(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file);
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

static int read_flame_sensor(void) {
    int low_count = 0;
    int high_count = 0;
    int value;

    for (int i = 0; i < DEBOUNCE_SAMPLES; i++) {
        value = gpiod_line_get_value(flame_line);
        if (value < 0) {
            fprintf(stderr, "Error reading flame sensor: %s\n", strerror(errno));
            return -1;
        }
        if (value == 0) {
            low_count++;
        } else {
            high_count++;
        }
        usleep(DEBOUNCE_DELAY_MS * 1000);
    }

    return (low_count >= 2) ? 0 : 1;
}

static int activate_output(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Error setting %s line value: %s\n", (value == 0) ? "output" : "input", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (buzzer_line != NULL) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
        buzzer_line = NULL;
    }
    if (led_line != NULL) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (flame_line != NULL) {
        gpiod_line_release(flame_line);
        flame_line = NULL;
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    log_file = fopen("flame_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error opening gpiochip0: %s\n", strerror(errno));
        goto cleanup_log;
    }

    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (flame_line == NULL) {
        fprintf(stderr, "Error getting flame sensor line %d: %s\n", FLAME_SENSOR_PIN, strerror(errno));
        goto cleanup_chip;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (buzzer_line == NULL) {
        fprintf(stderr, "Error getting buzzer line %d: %s\n", BUZZER_PIN, strerror(errno));
        goto cleanup_chip;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (led_line == NULL) {
        fprintf(stderr, "Error getting LED line %d: %s\n", LED_PIN, strerror(errno));
        goto cleanup_chip;
    }

    if (gpiod_line_request_input(flame_line, "flame_sensor") < 0) {
        fprintf(stderr, "Error requesting flame sensor line as input: %s\n", strerror(errno));
        goto cleanup_chip;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        fprintf(stderr, "Error requesting buzzer line as output: %s\n", strerror(errno));
        goto cleanup_chip;
    }

    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        fprintf(stderr, "Error requesting LED line as output: %s\n", strerror(errno));
        goto cleanup_chip;
    }

    printf("Flame detection system started. Press Ctrl+C to exit.\n");
    log_event("System started");

    while (program_running) {
        int flame_detected = read_flame_sensor();

        if (flame_detected < 0) {
            fprintf(stderr, "Error reading flame sensor, exiting.\n");
            break;
        }

        if (flame_detected == 0) {
            printf("Flame detected!\n");
            if (activate_output(buzzer_line, 1) < 0 || activate_output(led_line, 1) < 0) {
                fprintf(stderr, "Error activating outputs, exiting.\n");
                break;
            }
            log_event("Flame Detected");
        } else {
            if (activate_output(buzzer_line, 0) < 0 || activate_output(led_line, 0) < 0) {
                fprintf(stderr, "Error deactivating outputs, exiting.\n");
                break;
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup_chip:
    cleanup();
    return ret;

cleanup_log:
    cleanup();
    return ret;
}

