#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define ENABLE_A 24
#define ENABLE_B 25

#define KP 1.0
#define KI 0.01
#define KD 0.1
#define OBSTACLE_THRESHOLD 20.0
#define OBSTACLE_REDUCE 0.5
#define PWM_RANGE 255
#define LOOP_DELAY_US 50000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file);
}

static void set_motor_speed(int forward_pin, int backward_pin, int speed) {
    if (speed > PWM_RANGE) speed = PWM_RANGE;
    if (speed < -PWM_RANGE) speed = -PWM_RANGE;
    if (speed > 0) {
        gpioWrite(forward_pin, 1);
        gpioWrite(backward_pin, 0);
        gpioPWM(forward_pin, speed);
    } else if (speed < 0) {
        gpioWrite(forward_pin, 0);
        gpioWrite(backward_pin, 1);
        gpioPWM(backward_pin, -speed);
    } else {
        gpioWrite(forward_pin, 0);
        gpioWrite(backward_pin, 0);
    }
}

static void stop_motors(void) {
    gpioWrite(MOTOR_A_FORWARD, 0);
    gpioWrite(MOTOR_A_BACKWARD, 0);
    gpioWrite(MOTOR_B_FORWARD, 0);
    gpioWrite(MOTOR_B_BACKWARD, 0);
    gpioPWM(MOTOR_A_FORWARD, 0);
    gpioPWM(MOTOR_A_BACKWARD, 0);
    gpioPWM(MOTOR_B_FORWARD, 0);
    gpioPWM(MOTOR_B_BACKWARD, 0);
}

static void cleanup(void) {
    stop_motors();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    float integral = 0.0f;
    float previous_error = 0.0f;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    log_file = fopen("balance_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(ENABLE_A, PI_OUTPUT);
    gpioSetMode(ENABLE_B, PI_OUTPUT);

    gpioWrite(ENABLE_A, 1);
    gpioWrite(ENABLE_B, 1);

    gpioSetPWMrange(MOTOR_A_FORWARD, PWM_RANGE);
    gpioSetPWMrange(MOTOR_A_BACKWARD, PWM_RANGE);
    gpioSetPWMrange(MOTOR_B_FORWARD, PWM_RANGE);
    gpioSetPWMrange(MOTOR_B_BACKWARD, PWM_RANGE);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    while (running) {
        float tilt_error = (float)(rand() % 2000 - 1000) / 100.0f;
        float distance = (float)(rand() % 4000 + 2) / 10.0f;

        int motor_a_speed = 0;
        int motor_b_speed = 0;

        if (distance < OBSTACLE_THRESHOLD) {
            motor_a_speed = (int)(OBSTACLE_REDUCE * PWM_RANGE);
            motor_b_speed = (int)(OBSTACLE_REDUCE * PWM_RANGE);
            printf("Obstacle detected! Speed reduced.\n");
        } else {
            float error = tilt_error;
            integral += error;
            float derivative = error - previous_error;
            float output = KP * error + KI * integral + KD * derivative;
            previous_error = error;

            if (output > PWM_RANGE) output = PWM_RANGE;
            if (output < -PWM_RANGE) output = -PWM_RANGE;

            if (output > 0) {
                motor_a_speed = (int)output;
                motor_b_speed = 0;
            } else if (output < 0) {
                motor_a_speed = 0;
                motor_b_speed = (int)(-output);
            } else {
                motor_a_speed = 0;
                motor_b_speed = 0;
            }
        }

        set_motor_speed(MOTOR_A_FORWARD, MOTOR_A_BACKWARD, motor_a_speed);
        set_motor_speed(MOTOR_B_FORWARD, MOTOR_B_BACKWARD, motor_b_speed);

        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);
        printf("Tilt Error: %.2f, Distance: %.2f, Motor A Speed: %d, Motor B Speed: %d\n",
               tilt_error, distance, motor_a_speed, motor_b_speed);

        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    return 0;
}

