#define PERIOD_FRAMES    1024
#define UPDATE_DELAY_US  10000   /* 10 ms */

#define DEFAULT_SENSITIVITY 1.0f

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static float g_sensitivity = DEFAULT_SENSITIVITY;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static void cleanup(void);
static int  init_gpio(void);
static int  init_alsa(void);
static void set_led_color(int r, int g, int b);
static void map_noise_to_color(float noise, int *r, int *g, int *b);
static void simulate_audio(float *buffer, int num_frames);

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    /* Turn off LED before terminating pigpio */
    gpioWrite(RED_PIN, 0);
    gpioWrite(GREEN_PIN, 0);
    gpioWrite(BLUE_PIN, 0);
    gpioTerminate();
}

/* ----------------------------- GPIO init --------------------------------- */
static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n",
                gpioInitialise());
        return -1;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO mode for RGB pins.\n");
        gpioTerminate();
        return -1;
    }

    /* Start with LED off */
    gpioWrite(RED_PIN, 0);
    gpioWrite(GREEN_PIN, 0);
    gpioWrite(BLUE_PIN, 0);

    return 0;
}

