    if (err < 0) {
        fprintf(stderr, "Error: snd_pcm_hw_params_set_rate_near failed: %s\n", snd_strerror(err));
        goto fail;
    }

    err = snd_pcm_hw_params_set_channels(handle, params, 1);
    if (err < 0) {
