/* ----------------------------- LED control -------------------------------- */
static void set_led_color(int r, int g, int b)
{
    gpioPWM(RED_PIN,   r);
    gpioPWM(GREEN_PIN, g);
    gpioPWM(BLUE_PIN,  b);
}

/* ----------------------------- Noise -> color mapping ---------------------- */
static void map_noise_to_color(float noise, int *r, int *g, int *b)
{
    /* Non-linear mapping: cool (low) -> blue, warm (high) -> red */
    float norm = fabsf(noise) / (float)SAMPLE_RATE;
    float t = norm * 0.5f;          /* 0 .. 0.5 */

    if (noise < 0.0f) {
        /* Negative amplitude -> cool colors */
        *r = (int)(255.0f * (1.0f - t * t));
        *g = (int)(255.0f * (1.0f - t * t));
        *b = (int)(255.0f * t * t);
    } else {
        /* Positive amplitude -> warm colors */
        *r = (int)(255.0f * t * t);
        *g = (int)(255.0f * t * t);
        *b = (int)(255.0f * (1.0f - t * t));
    }

    /* Clamp to valid range */
    if (*r < 0)   *r = 0;   if (*r > 255) *r = 255;
    if (*g < 0)   *g = 0;   if (*g > 255) *g = 255;
    if (*b < 0)   *b = 0;   if (*b > 255) *b = 255;
}

/* ----------------------------- Sine-wave simulation ----------------------- */
static void simulate_audio(float *buffer, int num_frames)
{
    for (int i = 0; i < num_frames; i++) {
        float t = (float)i / (float)num_frames;
        buffer[i] = 32767.0f * 0.5f * (float)sin(2.0f * M_PI * 440.0f * t);
    }
}

/* ----------------------------- Main --------------------------------------- */
int main(int argc, char *argv[])
{
    if (argc > 1) {
        char *endptr;
        float s = strtof(argv[1], &endptr);
        if (*endptr != '\0' || s <= 0.0f || s > 100.0f) {
            fprintf(stderr, "Warning: invalid sensitivity '%s', using default %.2f.\n",
                    argv[1], DEFAULT_SENSITIVITY);
            g_sensitivity = DEFAULT_SENSITIVITY;
        } else {
            g_sensitivity = s;
        }
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize GPIO */
    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

#ifdef ALSA_AVAILABLE
    /* Initialize ALSA capture */
    snd_pcm_t *alsa_handle = init_alsa();
    if (alsa_handle == NULL) {
        fprintf(stderr, "Warning: ALSA capture unavailable; simulating sine wave.\n");
        /* Continue with simulation mode — no resource leak */
    } else {
        printf("ALSACapture initialized: %d Hz, %d frames, S16_LE, 1 channel.\n",
               SAMPLE_RATE, PERIOD_FRAMES);
    }
#endif

    /* Main loop */
    while (g_running) {
        float *buffer = malloc((size_t)PERIOD_FRAMES * sizeof(float));
        if (buffer == NULL) {
            fprintf(stderr, "Error: malloc failed: %s\n", strerror(errno));
            break;
        }

        int frames_read = 0;

#ifdef ALSA_AVAILABLE
        if (alsa_handle != NULL) {
            int err = snd_pcm_readi(alsa_handle, buffer, PERIOD_FRAMES);
            if (err < 0) {
                fprintf(stderr, "ALSA read error: %s\n", snd_strerror(err));
                if (err == EPIPE) {
                    fprintf(stderr, "ALSA buffer overrun — reinitializing.\n");
                    snd_pcm_prepare(alsa_handle);
                } else if (err == ESTRPIPE) {
                    fprintf(stderr, "ALSA stream suspended — resuming.\n");
                    snd_pcm_resume(alsa_handle);
                } else {
                    break;
                }
            } else if (err == -EPIPE) {
                /* EPIPE (overrun) — reinitialize */
                snd_pcm_prepare(alsa_handle);
            } else if (err == -ESTRPIPE) {
                /* ESTRPIPE (suspended) — resume */
                snd_pcm_resume(alsa_handle);
            } else {
                frames_read = err;
            }
        } else {
            /* Simulate capture */
            simulate_audio(buffer, PERIOD_FRAMES);
            frames_read = PERIOD_FRAMES;
        }
#else
        /* Simulate capture */
        simulate_audio(buffer, PERIOD_FRAMES);
        frames_read = PERIOD_FRAMES;
#endif

        /* Compute RMS amplitude of the buffer */
        float sum_sq = 0.0f;
        for (int i = 0; i < frames_read; i++) {
            sum_sq += buffer[i] * buffer[i];
        }
        float rms = sqrtf(sum_sq / (float)frames_read);

        /* Map noise to color */
        int r, g, b;
        map_noise_to_color(rms, &r, &g, &b);

        /* Drive LED */
        set_led_color(r, g, b);

        /* Delay */
        usleep(UPDATE_DELAY_US);

        free(buffer);
    }

    /* Cleanup */
    cleanup();

#ifdef ALSA_AVAILABLE
    if (alsa_handle != NULL) {
        snd_pcm_drain(alsa_handle);
        snd_pcm_close(alsa_handle);
    }
#endif

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

