#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>

#define NUM_LAMPS 4
#define SUNRISE_DURATION 3600
#define DAYTIME_DURATION 21600
#define SUNSET_DURATION 3600
#define NIGHTTIME_DURATION 12960
#define PHASE_DURATION (SUNRISE_DURATION + DAYTIME_DURATION + SUNSET_DURATION + NIGHTTIME_DURATION)
#define RELAY_ON 0
#define RELAY_OFF 1

static const int lamp_pins[NUM_LAMPS] = {17, 27, 22, 23};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_all_lamps(struct gpiod_line *lines[], int value) {
    for (int i = 0; i < NUM_LAMPS; i++) {
        if (lines[i] && gpiod_line_set_value(lines[i], value) < 0) {
            perror("gpiod_line_set_value");
            return -1;
        }
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_LAMPS] = {NULL};
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_LAMPS; i++) {
        lines[i] = gpiod_chip_get_line(chip, lamp_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line for BCM GPIO%d\n", lamp_pins[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], "sunrise-sunset", RELAY_OFF) < 0) {
            fprintf(stderr, "Failed to request output for BCM GPIO%d\n", lamp_pins[i]);
            goto cleanup;
        }
    }

    while (running) {
        time_t start_time = time(NULL);
        if (start_time == (time_t)-1) {
            perror("time");
            break;
        }

        /* Sunrise: 1 hour of increasing brightness */
        if (set_all_lamps(lines, RELAY_ON) < 0) break;
        sleep(SUNRISE_DURATION);
        if (!running) break;

        /* Daytime: 6 hours at full brightness */
        if (set_all_lamps(lines, RELAY_ON) < 0) break;
        sleep(DAYTIME_DURATION);
        if (!running) break;

        /* Sunset: 1 hour of decreasing brightness */
        for (int i = 0; i < SUNSET_DURATION && running; i += 60) {
            if (set_all_lamps(lines, RELAY_ON) < 0) break;
            sleep(60);
        }
        if (!running) break;

        /* Nighttime: 14.4 hours off */
        for (int i = 0; i < NIGHTTIME_DURATION && running; i += 60) {
            if (set_all_lamps(lines, RELAY_OFF) < 0) break;
            sleep(60);
        }
        if (!running) break;
    }

    /* Ensure all lamps are off on exit */
    set_all_lamps(lines, RELAY_OFF);
    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_LAMPS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

