#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_PIN 17
#define VIDEO_DIR "/home/pi/videos/"
#define LOG_FILE "/home/pi/logs/motion_log.txt"
#define DEBOUNCE_MS 200
#define VIDEO_DURATION_SEC 5

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }
    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP);
    return 0;
}

static int read_sensor(void) {
    return gpioRead(SENSOR_PIN);
}

static int get_timestamp(char *buf, size_t len) {
    time_t now = time(NULL);
    if (now == (time_t)-1) return -1;
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) return -1;
    if (strftime(buf, len, "%Y%m%d_%H%M%S", &tm_info) == 0) return -1;
    return 0;
}

static int log_motion(const char *timestamp) {
    if (log_fp == NULL) {
        log_fp = fopen(LOG_FILE, "a");
        if (log_fp == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }
    if (fprintf(log_fp, "%s Motion detected\n", timestamp) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(log_fp);
    return 0;
}

static int record_video(const char *timestamp) {
    char command[512];
    int ret = snprintf(command, sizeof(command),
                       "raspivid -o %s%s.h264 -t %d -w 640 -h 480",
                       VIDEO_DIR, timestamp, VIDEO_DURATION_SEC);
    if (ret < 0 || (size_t)ret >= sizeof(command)) {
        fprintf(stderr, "Error: command buffer too small.\n");
        return -1;
    }
    int status = system(command);
    if (status == -1) {
        perror("Error executing raspivid");
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Error: raspivid exited with status %d.\n", status);
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Error installing signal handler");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Motion detection started on GPIO %d. Press Ctrl+C to exit.\n", SENSOR_PIN);

    uint32_t last_trigger_tick = 0;
    while (running) {
        int sensor_value = read_sensor();
        if (sensor_value < 0) {
            fprintf(stderr, "Error: failed to read sensor.\n");
            break;
        }

        if (sensor_value == 0) {
            uint32_t now_tick = gpioTick();
            if (now_tick == 0) {
                fprintf(stderr, "Error: gpioTick returned 0.\n");
                break;
            }
            if (now_tick - last_trigger_tick >= DEBOUNCE_MS * 1000) {
                char timestamp[32];
                if (get_timestamp(timestamp, sizeof(timestamp)) == 0) {
                    printf("Motion detected at %s\n", timestamp);
                    if (log_motion(timestamp) != 0) {
                        fprintf(stderr, "Warning: failed to log motion event.\n");
                    }
                    if (record_video(timestamp) != 0) {
                        fprintf(stderr, "Warning: failed to record video.\n");
                    }
                    last_trigger_tick = now_tick;
                } else {
                    fprintf(stderr, "Error: failed to get timestamp.\n");
                }
            }
        }
        gpioDelay(10000);
    }

    if (log_fp != NULL) {
        fclose(log_fp);
        log_fp = NULL;
    }
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

