        perror("Error installing signal handler");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Motion detection started on GPIO %d. Press Ctrl+C to exit.\n", SENSOR_PIN);

    uint32_t last_trigger_tick = 0;
    while (running) {
        int sensor_value = read_sensor();
        if (sensor_value < 0) {
            fprintf(stderr, "Error: failed to read sensor.\n");
            break;
        }

        if (sensor_value == 0) {
            uint32_t now_tick = gpioTick();
            if (now_tick == 0) {
                fprintf(stderr, "Error: gpioTick returned 0.\n");
                break;
            }
            if (now_tick - last_trigger_tick >= DEBOUNCE_MS * 1000) {
                char timestamp[32];
                if (get_timestamp(timestamp, sizeof(timestamp)) == 0) {
                    printf("Motion detected at %s\n", timestamp);
                    if (log_motion(timestamp) != 0) {
                        fprintf(stderr, "Warning: failed to log motion event.\n");
                    }
                    if (record_video(timestamp) != 0) {
                        fprintf(stderr, "Warning: failed to record video.\n");
                    }
                    last_trigger_tick = now_tick;
                } else {
                    fprintf(stderr, "Error: failed to get timestamp.\n");
                }
            }
        }
        gpioDelay(10000);
    }

    if (log_fp != NULL) {
        fclose(log_fp);
        log_fp = NULL;
    }
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

