#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* MPU-6050 I2C address (AD0 low) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define MPU6050_SMPLRT_DIV   0x19
#define MPU6050_CONFIG       0x1A
#define MPU6050_GYRO_CONFIG  0x1B
#define MPU6050_GYRO_XOUT_H  0x43
#define MPU6050_PWR_MGMT_1   0x6B

/* Sensitivity scale factor for ±250°/s range */
#define GYRO_SCALE 131.0f

/* I2C bus on Raspberry Pi 4 */
#define I2C_BUS 1

/* Sampling interval in microseconds (10 ms = 100 Hz) */
#define SAMPLE_INTERVAL_US 10000

/* Maximum re-initialization attempts */
#define MAX_REINIT_ATTEMPTS 3

/* Global resources for signal handler */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an MPU-6050 register                              */
/* ------------------------------------------------------------------ */
static int mpu_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %s\n",
                reg, value, strerror(errno));
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Initialize the MPU-6050 sensor                                      */
/* ------------------------------------------------------------------ */
static int mpu_init(int handle)
{
    /* Wake up the device (clear SLEEP bit) */
    if (mpu_write_reg(handle, MPU6050_PWR_MGMT_1, 0x00) < 0)
        return -1;

    /* Set sample rate divider: 1 kHz / (1 + 7) = 125 Hz */
    if (mpu_write_reg(handle, MPU6050_SMPLRT_DIV, 0x07) < 0)
        return -1;

    /* Set gyroscope full-scale range to ±250°/s */
    if (mpu_write_reg(handle, MPU6050_GYRO_CONFIG, 0x00) < 0)
        return -1;

    /* Allow time for the first sample to be ready */
    gpioDelay(5000); /* 5 ms */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read gyroscope data (6 bytes starting at GYRO_XOUT_H)                */
/* ------------------------------------------------------------------ */
static int mpu_read_gyro(int handle, float *x, float *y, float *z)
{
    char buf[6];
    int rc = i2cReadI2CBlockData(handle, MPU6050_GYRO_XOUT_H, buf, 6);
    if (rc != 6) {
        fprintf(stderr, "i2cReadI2CBlockData failed: expected 6 bytes, got %d: %s\n",
                rc, strerror(errno));
        return -1;
    }

    int16_t raw_x = (int16_t)(((uint8_t)buf[0] << 8) | (uint8_t)buf[1]);
    int16_t raw_y = (int16_t)(((uint8_t)buf[2] << 8) | (uint8_t)buf[3]);
    int16_t raw_z = (int16_t)(((uint8_t)buf[4] << 8) | (uint8_t)buf[5]);

    *x = (float)raw_x / GYRO_SCALE;
    *y = (float)raw_y / GYRO_SCALE;
    *z = (float)raw_z / GYRO_SCALE;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one data row to the CSV file                                    */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float x, float y, float z)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return -1;
    }

    long long timestamp_ms = (long long)ts.tv_sec * 1000LL + ts.tv_nsec / 1000000LL;

    if (fprintf(fp, "%lld,%.2f,%.2f,%.2f\n", timestamp_ms, x, y, z) < 0) {
        fprintf(stderr, "fprintf to log file failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Re-initialize the sensor after a read failure                        */
/* ------------------------------------------------------------------ */
static int mpu_reinit(int handle)
{
    int attempts = 0;
    while (attempts < MAX_REINIT_ATTEMPTS) {
        fprintf(stderr, "Re-initializing MPU-6050 (attempt %d/%d)...\n",
                attempts + 1, MAX_REINIT_ATTEMPTS);
        if (mpu_init(handle) == 0) {
            fprintf(stderr, "Re-initialization successful.\n");
            return 0;
        }
        fprintf(stderr, "Re-initialization failed (attempt %d/%d).\n",
                attempts + 1, MAX_REINIT_ATTEMPTS);
        gpioDelay(100000); /* 100 ms before retry */
        attempts++;
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at address 0x68 */
    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, MPU6050_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (mpu_init(i2c_handle) != 0) {
        fprintf(stderr, "MPU-6050 initialisation failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "fopen(gyro_log.csv) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp_ms,X_degps,Y_degps,Z_degps\n");
        fflush(log_file);
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(stderr, "Gyroscope monitoring started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (!terminate) {
        float x, y, z;

        if (mpu_read_gyro(i2c_handle, &x, &y, &z) == 0) {
            if (log_data(log_file, x, y, z) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Gyroscope read failed; attempting re-initialization.\n");
            if (mpu_reinit(i2c_handle) != 0) {
                fprintf(stderr, "Re-initialization failed after %d attempts; continuing.\n",
                        MAX_REINIT_ATTEMPTS);
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    fprintf(stderr, "\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

