#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "irrigation_log.txt"
#define POLL_INTERVAL_US 5000000  /* 5 seconds */

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static const int relay_pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
static const int num_relays = 4;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    for (int i = 0; i < num_relays; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
        /* Deactivate all relays: drive HIGH (active-low relays OFF) */
        if (gpioWrite(relay_pins[i], 1) < 0) {
            fprintf(stderr, "Failed to write GPIO %d\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static int read_moisture_sensor(int zone) {
    if (zone < 1 || zone > num_relays) {
        fprintf(stderr, "Invalid zone number: %d\n", zone);
        return -1;
    }
    int reading = rand() % 101;
    printf("Zone %d moisture level: %d\n", zone, reading);
    return reading;
}

static int control_relay(int zone, int moisture_level) {
    if (zone < 1 || zone > num_relays) {
        fprintf(stderr, "Invalid zone number: %d\n", zone);
        return -1;
    }

    int pin = relay_pins[zone - 1];
    int state = (moisture_level < MOISTURE_THRESHOLD) ? 0 : 1;  /* Active-low: 0 = ON, 1 = OFF */

    if (gpioWrite(pin, state) < 0) {
        fprintf(stderr, "Failed to write GPIO %d\n", pin);
        return -1;
    }
    printf("Zone %d relay state: %s\n", zone, state ? "OFF" : "ON");
    return 0;
}

static int log_data(int zone, int moisture_level, int relay_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s - Zone %d - Moisture: %d, Relay: %s\n",
                timestamp, zone, moisture_level,
                relay_state ? "OFF" : "ON") < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    /* Deactivate all relays (HIGH = OFF for active-low relays) */
    for (int i = 0; i < num_relays; i++) {
        gpioWrite(relay_pins[i], 1);
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    srand((unsigned int)time(NULL));

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (initialize_gpio() < 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Smart Greenhouse Irrigation System started. Press Ctrl+C to exit.\n");

    while (running) {
        for (int i = 1; i <= num_relays; i++) {
            int moisture_level = read_moisture_sensor(i);
            if (moisture_level < 0) {
                fprintf(stderr, "Error reading moisture sensor for zone %d\n", i);
                continue;
            }

            if (control_relay(i, moisture_level) < 0) {
                fprintf(stderr, "Error controlling relay for zone %d\n", i);
            }

            int relay_state = gpioRead(relay_pins[i - 1]);
            if (relay_state < 0) {
                fprintf(stderr, "Failed to read relay state for zone %d\n", i);
            } else {
                if (log_data(i, moisture_level, relay_state) < 0) {
                    fprintf(stderr, "Error logging data for zone %d\n", i);
                }
            }
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

