#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <math.h>

/* ADXL345 I2C address (ALT ADDRESS tied to GND) */
#define ADXL345_ADDRESS 0x53

/* ADXL345 registers */
#define ADXL345_POWER_CTL   0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0      0x32
#define ADXL345_DATAX1      0x33
#define ADXL345_DATAY0      0x34
#define ADXL345_DATAY1      0x35
#define ADXL345_DATAZ0      0x36
#define ADXL345_DATAZ1      0x37

/* Freefall thresholds (±2g, 256 LSB/g) */
#define FREEFALL_THRESHOLD  0.2f
#define FREEFALL_DURATION   0.5f  /* seconds */

/* GPIO pin for alarm */
#define ALARM_GPIO 27

/* I2C handle */
static int i2c_handle = -1;

/* Volatile flag for graceful shutdown */
static volatile sig_atomic_t program_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Initialize ADXL345: ±2g, full resolution, measurement mode          */
/* ------------------------------------------------------------------ */
static int adxl345_init(void)
{
    /* DATA_FORMAT: 0x0B = full resolution, ±2g, right-justified */
    if (i2cWriteByteData(i2c_handle, ADXL345_DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Error: failed to write DATA_FORMAT register\n");
        return -1;
    }

    /* POWER_CTL: 0x08 = measurement mode */
    if (i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error: failed to write POWER_CTL register\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of accelerometer data and convert to g-force          */
/* ------------------------------------------------------------------ */
static int read_accelerometer(float *x, float *y, float *z)
{
    char data[6];
    int16_t raw_x, raw_y, raw_z;

    /* Read 6 bytes starting at DATAX0 (0x32) */
    if (i2cReadI2CBlockData(i2c_handle, ADXL345_DATAX0, data, 6) != 6) {
        fprintf(stderr, "Error: failed to read accelerometer data\n");
        return -1;
    }

    /* Combine high and low bytes (little-endian) */
    raw_x = (int16_t)((data[1] << 8) | (uint8_t)data[0]);
    raw_y = (int16_t)((data[3] << 8) | (uint8_t)data[2]);
    raw_z = (int16_t)((data[5] << 8) | (uint8_t)data[4]);

    /* Convert to g-force: 256 LSB/g for ±2g full-resolution mode */
    *x = (float)raw_x / 256.0f;
    *y = (float)raw_y / 256.0f;
    *z = (float)raw_z / 256.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Detect freefall: all axes |x|, |y|, |z| < FREEFALL_THRESHOLD        */
/* ------------------------------------------------------------------ */
static int is_freefall(float x, float y, float z)
{
    return (fabsf(x) < FREEFALL_THRESHOLD &&
            fabsf(y) < FREEFALL_THRESHOLD &&
            fabsf(z) < FREEFALL_THRESHOLD);
}

/* ------------------------------------------------------------------ */
/* Log freefall event to CSV file                                      */
/* ------------------------------------------------------------------ */
static void log_freefall(float x, float y, float z)
{
    FILE *fp;
    time_t t;
    struct tm tm_info;
    char timestamp[64];

    t = time(NULL);
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return;
    }

    fp = fopen("freefall.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: cannot open freefall.log for appending\n");
        return;
    }

    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Trigger alarm on GPIO27 for 5 seconds                              */
/* ------------------------------------------------------------------ */
static void trigger_alarm(void)
{
    if (gpioWrite(ALARM_GPIO, 1) < 0) {
        fprintf(stderr, "Warning: failed to set alarm GPIO high\n");
        return;
    }
    printf("ALARM TRIGGERED!\n");
    fflush(stdout);

    /* Sleep in 100 ms increments so we can respond to signals */
    for (int i = 0; i < 50 && program_running; i++) {
        gpioDelay(100000); /* 100 ms */
    }

    if (gpioWrite(ALARM_GPIO, 0) < 0) {
        fprintf(stderr, "Warning: failed to set alarm GPIO low\n");
    }
    printf("Alarm stopped.\n");
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Cleanup resources                                                   */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(ALARM_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    float x, y, z;
    int freefall_count = 0;
    int consecutive_ok = 0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at ADXL345 address */
    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: cannot open I2C device at address 0x%02X\n",
                ADXL345_ADDRESS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize ADXL345 */
    if (adxl345_init() < 0) {
        fprintf(stderr, "Error: ADXL345 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure alarm GPIO */
    if (gpioSetMode(ALARM_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set GPIO %d as output\n", ALARM_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(ALARM_GPIO, 0);

    /* Register signal handler for graceful shutdown */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Freefall detection started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* Main loop */
    while (program_running) {
        if (read_accelerometer(&x, &y, &z) == 0) {
            consecutive_ok++;

            if (is_freefall(x, y, z)) {
                freefall_count++;
                printf("Freefall detected (%d/%d)\n", freefall_count,
                       (int)FREEFALL_DURATION);
                fflush(stdout);

                if (freefall_count >= (int)(FREEFALL_DURATION * 10.0f)) {
                    log_freefall(x, y, z);
                    trigger_alarm();
                    freefall_count = 0;
                }
            } else {
                freefall_count = 0;
            }
        } else {
            consecutive_ok = 0;
        }

        /* Sleep 100 ms in 10 ms increments for responsive shutdown */
        for (int i = 0; i < 10 && program_running; i++) {
            gpioDelay(10000); /* 10 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

