#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pthread.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 18
#define TRIGGER_PULSE_US 10
#define MEASUREMENT_INTERVAL_US 200000
#define ECHO_TIMEOUT_US 100000
#define MAX_DISTANCE_CM 400.0
#define ECHO_MAX_PULSE_US 23200
#define SPEED_OF_SOUND_CM_PER_US 0.0343

static volatile uint32_t pulse_start = 0;
static volatile uint32_t pulse_end = 0;
static volatile int echo_received = 0;
static FILE *log_file = NULL;
static pthread_mutex_t mutex;
static volatile sig_atomic_t running = 1;

static void trigger_sensor(void) {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static void echo_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 1) {
        pulse_start = tick;
        echo_received = 0;
    } else if (level == 0) {
        pulse_end = tick;
        echo_received = 1;
    }
}

static double calculate_distance_cm(uint32_t pulse_width_us) {
    return (double)pulse_width_us * SPEED_OF_SOUND_CM_PER_US / 2.0;
}

static void log_distance(double distance_cm) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    long long timestamp_ns = (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;
    if (fprintf(log_file, "%lld,%.2f\n", timestamp_ns, distance_cm) < 0) {
        perror("fprintf");
    } else {
        fflush(log_file);
    }
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    gpioSetAlertFunc(TRIGGER_PIN, NULL, NULL);
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    pthread_mutex_destroy(&mutex);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (pthread_mutex_init(&mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        pthread_mutex_destroy(&mutex);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set TRIGGER_PIN mode\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set ECHO_PIN mode\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set ECHO_PIN pull-down\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ECHO_PIN alert callback\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        echo_received = 0;
        pulse_start = 0;
        pulse_end = 0;

        trigger_sensor();

        uint32_t start_tick = gpioTick();
        while (!echo_received && running) {
            if ((gpioTick() - start_tick) > ECHO_TIMEOUT_US) {
                break;
            }
            gpioDelay(100);
        }

        if (!running) {
            break;
        }

        if (!echo_received) {
            fprintf(stderr, "Echo timeout: no echo received within %d us\n", ECHO_TIMEOUT_US);
        } else if (pulse_end == 0 || pulse_start == 0) {
            fprintf(stderr, "Invalid pulse timing: start=%u, end=%u\n", pulse_start, pulse_end);
        } else {
            uint32_t pulse_width = pulse_end - pulse_start;
            if (pulse_width > ECHO_MAX_PULSE_US) {
                fprintf(stderr, "Distance out of range: pulse width %u us\n", pulse_width);
            } else {
                double distance = calculate_distance_cm(pulse_width);
                if (distance > MAX_DISTANCE_CM) {
                    fprintf(stderr, "Distance %.2f cm exceeds max range %.1f cm\n", distance, MAX_DISTANCE_CM);
                } else {
                    log_distance(distance);
                    printf("Distance: %.2f cm\n", distance);
                }
            }
        }

        if (running) {
            gpioDelay(MEASUREMENT_INTERVAL_US);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

