#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <string.h>

/* LIS3DH I2C address (SA0 tied to GND) */
#define LIS3DH_ADDR 0x18

/* LIS3DH register addresses */
#define CTRL_REG1   0x20
#define CTRL_REG4   0x23
#define OUT_X_L     0x28
#define OUT_X_H     0x29
#define OUT_Y_L     0x2A
#define OUT_Y_H     0x2B
#define OUT_Z_L     0x2C
#define OUT_Z_H     0x2D

/* Buzzer GPIO pin */
#define BUZZER_PIN 17

/* Default thresholds (in g) */
#define DEFAULT_FREEFALL_THRESHOLD 0.2
#define DEFAULT_IMPACT_THRESHOLD   1.5

/* Sensitivity for ±2g full scale: 16384 LSB/g */
#define SENSITIVITY 16384.0f

/* I2C bus on Raspberry Pi 5 */
#define I2C_BUS 1

/* Global variables for signal handling and cleanup */
static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;

/* Structure to hold accelerometer data */
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

/* Function prototypes */
static int initialize_i2c(void);
static int configure_lis3dh(void);
static accelerometer_data_t read_accelerometer_data(void);
static float calculate_magnitude(accelerometer_data_t data);
static void detect_fall(float magnitude, float freefall_threshold, float impact_threshold);
static void activate_buzzer(int duration_ms);
static void cleanup(void);
static void signal_handler(int signal);

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
}

/* Initialize I2C communication */
static int initialize_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, LIS3DH_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, LIS3DH_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

/* Configure LIS3DH: 100 Hz data rate, ±2g full scale, normal mode */
static int configure_lis3dh(void) {
    /* CTRL_REG1: 0x77 = 0b01110111
     *   bit 6-4: 100 = 100 Hz data rate
     *   bit 1-0: 11 = ±2g full scale
     *   bit 7:   0 = normal mode
     */
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x77) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    /* CTRL_REG4: 0x00 = 0b00000000
     *   bit 3:   0 = no high-resolution mode
     *   bit 2:   0 = no high-pass filter
     *   bit 1:   0 = no FIFO
     *   bit 0:   0 = no self-test
     */
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

/* Read accelerometer data from LIS3DH */
static accelerometer_data_t read_accelerometer_data(void) {
    accelerometer_data_t data = {0, 0, 0};
    char buffer[6];

    /* Read 6 bytes starting from OUT_X_L (0x28) */
    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return data;
    }

    /* Combine low and high bytes (little-endian) */
    data.x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data.y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data.z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return data;
}

/* Calculate the magnitude of the acceleration vector in g */
static float calculate_magnitude(accelerometer_data_t data) {
    float x_g = (float)data.x / SENSITIVITY;
    float y_g = (float)data.y / SENSITIVITY;
    float z_g = (float)data.z / SENSITIVITY;
    return sqrtf(x_g * x_g + y_g * y_g + z_g * z_g);
}

/* Detect fall and impact */
static void detect_fall(float magnitude, float freefall_threshold, float impact_threshold) {
    if (magnitude < freefall_threshold) {
        printf("Freefall detected! Magnitude: %.3f g\n", magnitude);
        activate_buzzer(1000);
    } else if (magnitude > impact_threshold) {
        printf("Impact detected! Magnitude: %.3f g\n", magnitude);
        activate_buzzer(1000);
    }
}

/* Activate the buzzer for a specified duration in milliseconds */
static void activate_buzzer(int duration_ms) {
    gpioWrite(BUZZER_PIN, 1);
    gpioDelay(duration_ms * 1000);
    gpioWrite(BUZZER_PIN, 0);
}

int main(int argc, char *argv[]) {
    float freefall_threshold = DEFAULT_FREEFALL_THRESHOLD;
    float impact_threshold = DEFAULT_IMPACT_THRESHOLD;

    /* Parse command-line arguments */
    if (argc > 1) {
        freefall_threshold = (float)atof(argv[1]);
        if (argc > 2) {
            impact_threshold = (float)atof(argv[2]);
        }
    }
    printf("Using freefall threshold: %.3f g, impact threshold: %.3f g\n",
           freefall_threshold, impact_threshold);

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Set buzzer pin as output */
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioWrite(BUZZER_PIN, 0);

    /* Initialize I2C */
    if (initialize_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    /* Configure LIS3DH */
    if (configure_lis3dh() < 0) {
        cleanup();
        return 1;
    }

    /* Set up signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        cleanup();
        return 1;
    }

    printf("Fall detection system started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (program_running) {
        accelerometer_data_t data = read_accelerometer_data();
        float magnitude = calculate_magnitude(data);
        detect_fall(magnitude, freefall_threshold, impact_threshold);

        gpioDelay(10000); /* 10 ms delay */
    }

    /* Cleanup */
    cleanup();
    printf("Program terminated gracefully.\n");
    return 0;
}

