#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define DEFAULT_I2C_ADDRESS 0x18
#define DEFAULT_THRESHOLD 2.0f
#define LOG_FILE "/var/log/high_acceleration.log"
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define NUM_SENSORS 1
#define SAMPLE_INTERVAL_US 100000

static int i2c_handles[NUM_SENSORS];
static int i2c_addresses[NUM_SENSORS];
static float thresholds[NUM_SENSORS];
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int init_lis3dh(int handle) {
    if (write_reg(handle, CTRL_REG1, 0x57) < 0) return -1;
    if (write_reg(handle, CTRL_REG4, 0x88) < 0) return -1;
    return 0;
}

static int read_acceleration(int handle, float *x, float *y, float *z) {
    char buffer[6];
    int rc = i2cReadI2CBlockData(handle, OUT_X_L, buffer, 6);
    if (rc != 6) {
        fprintf(stderr, "Error reading acceleration data: %d\n", rc);
        return -1;
    }
    int16_t raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);
    *x = (float)raw_x >> 4;
    *y = (float)raw_y >> 4;
    *z = (float)raw_z >> 4;
    return 0;
}

static void log_event(float x, float y, float z, float threshold) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Threshold exceeded: X=%.3f, Y=%.3f, Z=%.3f g\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    fclose(fp);
}

static void shutdown_system(void) {
    printf("Threshold exceeded! Shutting down system...\n");
    int rc = system("sudo shutdown -h now");
    if (rc != 0) {
        fprintf(stderr, "Error executing shutdown command: %d\n", rc);
    }
}

static void cleanup(void) {
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_handles[i] >= 0) {
            i2cClose(i2c_handles[i]);
            i2c_handles[i] = -1;
        }
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                if (sscanf(optarg, "%x", &i2c_addresses[0]) != 1) {
                    fprintf(stderr, "Invalid I2C address: %s\n", optarg);
                    return 1;
                }
                if (i2c_addresses[0] < 0x08 || i2c_addresses[0] > 0x77) {
                    fprintf(stderr, "I2C address must be between 0x08 and 0x77\n");
                    return 1;
                }
                break;
            case 't':
                float t;
                if (sscanf(optarg, "%f", &t) != 1 || t <= 0.0f) {
                    fprintf(stderr, "Invalid threshold: %s\n", optarg);
                    return 1;
                }
                thresholds[0] = t;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold_g]\n", argv[0]);
                return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 0;
    }

    i2c_handles[0] = -1;
    i2c_addresses[0] = DEFAULT_I2C_ADDRESS;
    thresholds[0] = DEFAULT_THRESHOLD;

    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_handles[i] = i2cOpen(i2c_addresses[i], 0, 0);
        if (i2c_handles[i] < 0) {
            fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", i2c_addresses[i], i2c_handles[i]);
            cleanup();
            return 0;
        }
        if (init_lis3dh(i2c_handles[i]) < 0) {
            fprintf(stderr, "Error initializing LIS3DH at address 0x%02X\n", i2c_addresses[i]);
            cleanup();
            return 0;
        }
    }

    signal(SIGINT, signal_handler);

    float x, y, z;
    while (!terminate) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (read_acceleration(i2c_handles[i], &x, &y, &z) == 0) {
                if (fabsf(x) > thresholds[i] || fabsf(y) > thresholds[i] || fabsf(z) > thresholds[i]) {
                    log_event(x, y, z, thresholds[i]);
                    shutdown_system();
                    return 0;
                }
            } else {
                fprintf(stderr, "Error reading sensor %d, continuing...\n", i);
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

