    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return -1;
    }

    left_line = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    center_line = gpiod_chip_get_line(chip, CENTER_SENSOR_PIN);
    right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);
    alert_line = gpiod_chip_get_line(chip, ALERT_PIN);
    if (!left_line || !center_line || !right_line || !alert_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_input(left_line, "line_follower") < 0 ||
        gpiod_line_request_input(center_line, "line_follower") < 0 ||
        gpiod_line_request_input(right_line, "line_follower") < 0) {
        fprintf(stderr, "Failed to request sensor lines as input: %s\n", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(alert_line, "line_follower", 0) < 0) {
        fprintf(stderr, "Failed to request alert line as output: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int read_sensor(struct gpiod_line *line, int pin) {
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", pin, strerror(errno));
        return -1;
    }
    return val;
}

static void log_sensor_data(int left, int center, int right) {
    sensor_buffer[buffer_index].left = left;
    sensor_buffer[buffer_index].center = center;
    sensor_buffer[buffer_index].right = right;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void check_alert(void) {
    static int no_line_count = 0;
    int center = read_sensor(center_line, CENTER_SENSOR_PIN);
    if (center < 0) return;
    if (center == NO_LINE) {
        no_line_count++;
        if (no_line_count >= ALERT_THRESHOLD) {
            printf("Alert: No line detected for %d readings!\n", ALERT_THRESHOLD);
            if (gpiod_line_set_value(alert_line, 1) < 0) {
                fprintf(stderr, "Failed to set alert HIGH: %s\n", strerror(errno));
            }
            sleep(ALERT_DURATION_SEC);
            if (gpiod_line_set_value(alert_line, 0) < 0) {
                fprintf(stderr, "Failed to set alert LOW: %s\n", strerror(errno));
            }
            no_line_count = 0;
        }
    } else {
        no_line_count = 0;
    }
}

static void move_forward(void) {
    printf("Moving forward...\n");
}

static void turn_left(void) {
    printf("Turning left...\n");
}

static void turn_right(void) {
    printf("Turning right...\n");
}

static void stop_robot(void) {
    printf("Stopping...\n");
}

static void line_following_algorithm(int left, int center, int right) {
    if (center == LINE_DETECTED) {
        move_forward();
    } else if (left == LINE_DETECTED) {
        turn_left();
    } else if (right == LINE_DETECTED) {
        turn_right();
    } else {
        stop_robot();
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }

    printf("Line following robot started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int left = read_sensor(left_line, LEFT_SENSOR_PIN);
        int center = read_sensor(center_line, CENTER_SENSOR_PIN);
        int right = read_sensor(right_line, RIGHT_SENSOR_PIN);

        if (left < 0 || center < 0 || right < 0) {
            fprintf(stderr, "Sensor read error, exiting.\n");
            break;
        }

        log_sensor_data(left, center, right);
        check_alert();
        line_following_algorithm(left, center, right);

        usleep(POLL_INTERVAL_US);
    }

    cleanup();
    printf("Program finished.\n");
    return 0;
}

