#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI7210_ADDR    0x30
#define RELAY_GPIO     17
#define THRESHOLD_MT   5.0f
#define SAMPLE_US      100000   /* 100 ms */
#define CONV_TIMEOUT   50       /* poll attempts */
#define CONV_POLL_US   1000     /* 1 ms between polls */

/* Si7210 register addresses */
#define REG_CONV_CTRL  0xC1
#define REG_FIELD_LSB  0xC0
#define REG_FIELD_MSB  0xC1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_event(const char *msg)
{
    FILE *fp = fopen("magnetic_events.txt", "a");
    if (!fp) {
        perror("fopen(magnetic_events.txt)");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s %s\n", ts, msg);
    } else {
        fprintf(fp, "<unknown-time> %s\n", msg);
    }
    fclose(fp);
}

static int read_field_raw(int handle, int *raw_out)
{
    char buf[2];
    int rc;

    /* Start a one-shot conversion */
    rc = i2cWriteByteData(handle, REG_CONV_CTRL, 0x01);
    if (rc < 0) {
        log_event("I2C write error: start conversion");
        return -1;
    }

    /* Poll until conversion completes (0x00) or timeout */
    for (int i = 0; i < CONV_TIMEOUT; i++) {
        rc = i2cReadByteData(handle, REG_CONV_CTRL);
        if (rc < 0) {
            log_event("I2C read error: conv Ctrl");
            return -1;
        }
        if (rc == 0x00)
            break;
        gpioDelay(CONV_POLL_US);
    }
    if (rc != 0x00) {
        char m[128];
        snprintf(m, sizeof(m), "Conversion timeout (rc=0x%02X)", rc);
        log_event(m);
        return -1;
    }

    /* Read LSB (0xC0) then MSB (0xC1) */
    rc = i2cReadByteData(handle, REG_FIELD_LSB);
    if (rc < 0) {
        log_event("I2C read error: FIELD_LSB");
        return -1;
    }
    buf[0] = (char)rc;

    rc = i2cReadByteData(handle, REG_FIELD_MSB);
    if (rc < 0) {
        log_event("I2C read error: FIELD_MSB");
        return -1;
    }
    buf[1] = (char)rc;

    *raw_out = (int)((unsigned char)buf[1] << 8 | (unsigned char)buf[0]);
    return 0;
}

static int control_relay(int gpio, int state)
{
    int rc = gpioWrite(gpio, state);
    if (rc < 0) {
        char m[64];
        snprintf(m, sizeof(m), "gpioWrite(%d, %d) failed: %d", gpio, state, rc);
        log_event(m);
        return -1;
    }
    return 0;
}

int main(void)
{
    int raw, field_mt;
    int relay_state = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (g_i2c_handle < 0) {
        char m[128];
        snprintf(m, sizeof(m), "i2cOpen(bus=%d, addr=0x%02X) failed: %d",
                 I2C_BUS, SI7210_ADDR, g_i2c_handle);
        log_event(m);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        log_event("gpioSetMode(RELAY_GPIO) failed");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }
    control_relay(RELAY_GPIO, 0);

    log_event("Si7210 magnetic field monitor started");

    while (g_running) {
        if (read_field_raw(g_i2c_handle, &raw) != 0) {
            control_relay(RELAY_GPIO, 0);
            gpioDelay(SAMPLE_US);
            continue;
        }

        /* Si7210: 25 mT range, 0.01 mT per LSB */
        field_mt = (int)((float)raw * 25.0f / 1000.0f);

        char msg[128];
        snprintf(msg, sizeof(msg), "Field: %d mT", field_mt);
        log_event(msg);

        if (field_mt > (int)(THRESHOLD_MT * 100.0f)) {
            if (relay_state == 0) {
                if (control_relay(RELAY_GPIO, 1) == 0) {
                    relay_state = 1;
                    log_event("Relay activated");
                }
            }
        } else {
            if (relay_state == 1) {
                if (control_relay(RELAY_GPIO, 0) == 0) {
                    relay_state = 0;
                    log_event("Relay deactivated");
                }
            }
        }

        gpioDelay(SAMPLE_US);
    }

    /* Graceful shutdown */
    log_event("Shutting down");
    control_relay(RELAY_GPIO, 0);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    return 0;
}

