#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define PORT 5000
#define GPIO_PIN 18
#define BUFFER_SIZE 1024
#define LOG_FILE "relay_log.txt"

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

static void log_event(const char *event) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
}

static int set_relay(int state) {
    if (gpioWrite(GPIO_PIN, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", GPIO_PIN);
        return -1;
    }
    return 0;
}

static int handle_client(int client_socket) {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_received;

    while ((bytes_received = recv(client_socket, buffer, BUFFER_SIZE - 1, 0)) > 0) {
        buffer[bytes_received] = '\0';
        buffer[strcspn(buffer, "\r\n")] = '\0';

        char command[32];
        char *token = strtok(buffer, " \r\n");
        if (token) {
            strncpy(command, token, sizeof(command) - 1);
            command[sizeof(command) - 1] = '\0';
        }

        char log_msg[256];
        if (strcmp(command, "ON") == 0) {
            if (set_relay(1) == 0) {
                log_event("Relay ON");
                send(client_socket, "OK ON\n", 5, 0);
            } else {
                log_event("Error: Failed to set relay ON");
                send(client_socket, "ERROR ON\n", 7, 0);
            }
        } else if (strcmp(command, "OFF") == 0) {
            if (set_relay(0) == 0) {
                log_event("Relay OFF");
                send(client_socket, "OK OFF\n", 6, 0);
            } else {
                log_event("Error: Failed to set relay OFF");
                send(client_socket, "ERROR OFF\n", 8, 0);
            }
        } else {
            log_event("Invalid command received");
            send(client_socket, "ERROR INVALID\n", 13, 0);
        }
    }

    if (bytes_received < 0) {
        perror("recv failed");
    }

    close(client_socket);
    return 0;
}

static void cleanup(void) {
    if (server_fd != -1) {
        close(server_fd);
        server_fd = -1;
    }
    if (log_file) {
        log_event("Server shutting down");
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sockaddr_in address;
    int opt = 1;
    socklen_t addrlen = sizeof(address);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction failed");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("socket failed");
        cleanup();
        return 1;
    }

    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt failed");
        cleanup();
        return 1;
    }

    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        cleanup();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        perror("listen failed");
        cleanup();
        return 1;
    }

    printf("Listening on port %d...\n", PORT);
    log_event("Server started");

    while (running) {
        int client_socket = accept(server_fd, (struct sockaddr *)&address, &addrlen);
        if (client_socket < 0) {
            if (errno == EINTR && !running) break;
            perror("accept failed");
            continue;
        }
        printf("Connection accepted from %s:%d\n",
               inet_ntoa(address.sin_addr), ntohs(address.sin_port));
        handle_client(client_socket);
    }

    cleanup();
    return 0;
}

