#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define RELAY_GPIO 18
#define FLOW_THRESHOLD 5.0f
#define SCALE_FACTOR (1.0f / 1500.0f)
#define I2C_BUS 1
#define LOG_FILE "flow_log.txt"
#define POLL_DELAY_US 100000
#define START_CMD_LEN 2
#define READ_LEN 3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_h1 = -1;
static int g_i2c_h2 = -1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int init_relay(void) {
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d) failed\n", RELAY_GPIO);
        return -1;
    }
    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(%d, 0) failed\n", RELAY_GPIO);
        return -1;
    }
    return 0;
}

static int init_sensor(int handle) {
    uint8_t cmd[START_CMD_LEN] = {0x36, 0x08};
    if (i2cWriteDevice(handle, (char *)cmd, START_CMD_LEN) != 0) {
        fprintf(stderr, "Error: i2cWriteDevice failed for handle %d\n", handle);
        return -1;
    }
    return 0;
}

static int read_flow(int handle, float *flow_out) {
    uint8_t buf[READ_LEN];
    int n = i2cReadDevice(handle, (char *)buf, READ_LEN);
    if (n != READ_LEN) {
        fprintf(stderr, "Warning: i2cReadDevice returned %d (expected %d)\n", n, READ_LEN);
        return -1;
    }
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Warning: CRC mismatch on handle %d\n", handle);
        return -1;
    }
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_out = (float)raw * SCALE_FACTOR;
    return 0;
}

static void log_flow(float f1, float f2) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open %s for append\n", LOG_FILE);
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm;
    localtime_r(&ts.tv_sec, &tm);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s.%03ld, Sensor1: %.2f ml/min, Sensor2: %.2f ml/min\n",
            tbuf, ts.tv_nsec / 1000000L, f1, f2);
    fflush(fp);
    fclose(fp);
}

static void cleanup(void) {
    if (g_i2c_h1 >= 0) {
        i2cClose(g_i2c_h1);
        g_i2c_h1 = -1;
    }
    if (g_i2c_h2 >= 0) {
        i2cClose(g_i2c_h2);
        g_i2c_h2 = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_relay() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_i2c_h1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (g_i2c_h1 < 0) {
        fprintf(stderr, "Error: i2cOpen failed for sensor 1 (addr 0x%02X)\n", SENSOR1_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    g_i2c_h2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (g_i2c_h2 < 0) {
        fprintf(stderr, "Error: i2cOpen failed for sensor 2 (addr 0x%02X)\n", SENSOR2_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_sensor(g_i2c_h1) != 0 || init_sensor(g_i2c_h2) != 0) {
        fprintf(stderr, "Error: sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    while (g_running) {
        float f1 = 0.0f, f2 = 0.0f;
        int ok1 = read_flow(g_i2c_h1, &f1);
        int ok2 = read_flow(g_i2c_h2, &f2);

        if (ok1 == 0 && ok2 == 0) {
            if (f1 < FLOW_THRESHOLD || f2 < FLOW_THRESHOLD) {
                gpioWrite(RELAY_GPIO, 1);
            } else {
                gpioWrite(RELAY_GPIO, 0);
            }
            log_flow(f1, f2);
        } else {
            if (ok1 != 0) fprintf(stderr, "Warning: sensor 1 read error\n");
            if (ok2 != 0) fprintf(stderr, "Warning: sensor 2 read error\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    fprintf(stderr, "Shutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

