#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENABLE_PIN 22
#define MOTOR_INPUT_1_PIN 23
#define MOTOR_INPUT_2_PIN 24

#define POLL_INTERVAL_US 200000   /* 200 ms */
#define MOTOR_RUN_US 5000000      /* 5 s   */
#define DRY_RECOVERY_POLLS 3      /* 3 x 200 ms = 600 ms dry window after rain */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a single GPIO pin; return 0 on success, -1 on failure. */
static int safe_gpio_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) != 0) {
        syslog(LOG_ERR, "gpioWrite(pin=%u, level=%u) failed", pin, level);
        return -1;
    }
    return 0;
}

/* Stop the motor: enable LOW, then drive both inputs LOW. */
static void motor_stop(void)
{
    safe_gpio_write(MOTOR_ENABLE_PIN, 0);
    safe_gpio_write(MOTOR_INPUT_1_PIN, 0);
    safe_gpio_write(MOTOR_INPUT_2_PIN, 0);
}

/* Run the close-window sequence: enable motor, drive IN1, IN2, hold, then stop. */
static void run_motor(void)
{
    syslog(LOG_INFO, "Starting close-window motor sequence");

    if (safe_gpio_write(MOTOR_ENABLE_PIN, 1) != 0 ||
        safe_gpio_write(MOTOR_INPUT_1_PIN, 1) != 0 ||
        safe_gpio_write(MOTOR_INPUT_2_PIN, 0) != 0) {
        syslog(LOG_ERR, "Motor GPIO setup failed during run");
        motor_stop();
        return;
    }

    gpioDelay(MOTOR_RUN_US);

    motor_stop();
    syslog(LOG_INFO, "Close-window motor sequence complete");
}

int main(void)
{
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    /* Configure rain sensor pin as input with pull-up (DO is active-low). */
    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set rain sensor pin mode");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP) != 0) {
        syslog(LOG_ERR, "Failed to set rain sensor pull-up");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    /* Configure motor control pins as outputs. */
    if (gpioSetMode(MOTOR_ENABLE_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_INPUT_1_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_INPUT_2_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set motor pin modes");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    /* Ensure motor is stopped at startup. */
    motor_stop();

    /* Install signal handlers for graceful shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to install signal handlers");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Rain window controller started (poll=%d ms, dry-recovery=%d polls)",
           POLL_INTERVAL_US / 1000, DRY_RECOVERY_POLLS);

    int last_rain_state = 0;   /* 0 = dry (HIGH), 1 = wet (LOW) */
    int dry_count = 0;

    while (g_running) {
        int level = gpioRead(RAIN_SENSOR_PIN);
        if (level < 0) {
            syslog(LOG_ERR, "gpioRead(rain_sensor) failed");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        int current_rain_state = (level == 0) ? 1 : 0;  /* wet = 1, dry = 0 */

        if (current_rain_state == 1 && last_rain_state == 0) {
            /* Rising edge: dry -> wet. */
            dry_count = 0;
            syslog(LOG_INFO, "Rain detected (DO LOW)");
        } else if (current_rain_state == 0 && last_rain_state == 1) {
            /* Falling edge: wet -> dry. */
            dry_count++;
            if (dry_count >= DRY_RECOVERY_POLLS) {
                dry_count = 0;  /* reset to avoid re-triggering on brief dry spells */
            }
        }

        last_rain_state = current_rain_state;

        if (current_rain_state == 1) {
            /* Rain present — no motor action needed. */
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        /* Dry and dry for long enough: trigger close-window sequence. */
        if (dry_count >= DRY_RECOVERY_POLLS) {
            run_motor();
            dry_count = 0;  /* reset so we don't re-trigger immediately */
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* Graceful shutdown. */
    syslog(LOG_INFO, "Shutting down");
    motor_stop();
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

