        int current_rain_state = (level == 0) ? 1 : 0;  /* wet = 1, dry = 0 */

        if (current_rain_state == 1 && last_rain_state == 0) {
            /* Rising edge: dry -> wet. */
            dry_count = 0;
            syslog(LOG_INFO, "Rain detected (DO LOW)");
        } else if (current_rain_state == 0 && last_rain_state == 1) {
            /* Falling edge: wet -> dry. */
            dry_count++;
            if (dry_count >= DRY_RECOVERY_POLLS) {
                dry_count = 0;  /* reset to avoid re-triggering on brief dry spells */
            }
        }

        last_rain_state = current_rain_state;

        if (current_rain_state == 1) {
            /* Rain present — no motor action needed. */
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        /* Dry and dry for long enough: trigger close-window sequence. */
        if (dry_count >= DRY_RECOVERY_POLLS) {
            run_motor();
            dry_count = 0;  /* reset so we don't re-trigger immediately */
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* Graceful shutdown. */
    syslog(LOG_INFO, "Shutting down");
    motor_stop();
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

