#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN      18
#define BUTTON_LOCK    21
#define BUTTON_UNLOCK  22

#define LOCKED_PULSE_US 2000
#define UNLOCKED_PULSE_US 1000
#define DEBOUNCE_US     50000   /* 50 ms debounce */
#define POLL_DELAY_US   10000   /* 10 ms poll interval */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_servo(int pulse_us)
{
    if (gpioServo(SERVO_PIN, pulse_us) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pulse %d us\n", pulse_us);
        return -1;
    }
    return 0;
}

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure button pins as inputs with pull-ups --- */
    if (gpioSetMode(BUTTON_LOCK, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for BUTTON_LOCK\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUTTON_UNLOCK, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for BUTTON_UNLOCK\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(BUTTON_LOCK, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for BUTTON_LOCK\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(BUTTON_UNLOCK, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for BUTTON_UNLOCK\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Set initial servo position to unlocked --- */
    if (set_servo(UNLOCKED_PULSE_US) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    printf("Door lock system started. Initial state: UNLOCKED\n");
    fflush(stdout);

    /* --- Main polling loop --- */
    int last_lock_state = 1;   /* released (pull-up high) */
    int last_unlock_state = 1;
    int lock_pressed = 0;
    int unlock_pressed = 0;

    while (g_running) {
        int lock = gpioRead(BUTTON_LOCK);
        int unlock = gpioRead(BUTTON_UNLOCK);

        /* Detect rising edge on lock button */
        if (lock == 0 && last_lock_state == 1 && !lock_pressed) {
            if (set_servo(LOCKED_PULSE_US) == 0) {
                printf("Lock pressed. Door locked.\n");
                fflush(stdout);
            }
            lock_pressed = 1;
        }

        /* Detect rising edge on unlock button */
        if (unlock == 0 && last_unlock_state == 1 && !unlock_pressed) {
            if (set_servo(UNLOCKED_PULSE_US) == 0) {
                printf("Unlock pressed. Door unlocked.\n");
                fflush(stdout);
            }
            unlock_pressed = 1;
        }

        /* Debounce: wait for both buttons to release */
        if (lock_pressed && lock == 1) {
            lock_pressed = 0;
        }
        if (unlock_pressed && unlock == 1) {
            unlock_pressed = 0;
        }

        last_lock_state = lock;
        last_unlock_state = unlock;

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Clean shutdown: stop servo pulses and release pigpio --- */
    gpioServo(SERVO_PIN, 0);   /* stop PWM signal */
    gpioTerminate();
    printf("\nDoor lock system stopped.\n");
    fflush(stdout);
    return EXIT_SUCCESS;
}

