#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define PIR_PIN 4
#define FLOODLIGHT_PIN 17
#define FLOODLIGHT_DURATION_SEC 60
#define POLL_INTERVAL_US 100000
#define LOG_FILE "security_log.txt"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int log_event(const char *event_type, int duration_sec) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (duration_sec >= 0) {
        if (fprintf(fp, "%s - %s - Duration: %d seconds\n", timestamp, event_type, duration_sec) < 0) {
            fprintf(stderr, "fprintf failed: %s\n", strerror(errno));
            fclose(fp);
            return -1;
        }
    } else {
        if (fprintf(fp, "%s - %s\n", timestamp, event_type) < 0) {
            fprintf(stderr, "fprintf failed: %s\n", strerror(errno));
            fclose(fp);
            return -1;
        }
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int activate_floodlight(int duration_sec) {
    if (gpioWrite(FLOODLIGHT_PIN, 1) != 0) {
        fprintf(stderr, "Failed to turn on floodlight\n");
        return -1;
    }

    for (int i = 0; i < duration_sec && g_running; i++) {
        gpioDelay(POLL_INTERVAL_US);
    }

    if (gpioWrite(FLOODLIGHT_PIN, 0) != 0) {
        fprintf(stderr, "Failed to turn off floodlight\n");
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set PIR_PIN %d as input\n", PIR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOODLIGHT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set FLOODLIGHT_PIN %d as output\n", FLOODLIGHT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(FLOODLIGHT_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize floodlight to OFF\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        gpioWrite(FLOODLIGHT_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        gpioWrite(FLOODLIGHT_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Smart Security Light System started. Press Ctrl+C to exit.\n");

    int last_pir_state = gpioRead(PIR_PIN);
    if (last_pir_state < 0) {
        fprintf(stderr, "Failed to read initial PIR state\n");
        gpioWrite(FLOODLIGHT_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int pir_state = gpioRead(PIR_PIN);
        if (pir_state < 0) {
            fprintf(stderr, "Failed to read PIR_PIN %d\n", PIR_PIN);
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (pir_state == 1 && last_pir_state == 0) {
            printf("Motion detected! Activating floodlight for %d seconds.\n", FLOODLIGHT_DURATION_SEC);
            if (activate_floodlight(FLOODLIGHT_DURATION_SEC) == 0) {
                if (log_event("ACTIVATED", FLOODLIGHT_DURATION_SEC) != 0) {
                    fprintf(stderr, "Failed to log activation event\n");
                }
            } else {
                fprintf(stderr, "Floodlight activation failed\n");
            }
        }

        last_pir_state = pir_state;
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(FLOODLIGHT_PIN, 0);
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
    return EXIT_SUCCESS;
}

