#define RELAY_GPIO 17
#define I2C_BUS 1
#define MPR121_ADDR 0x5A

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_MHD_RISING    0x2B
#define MPR121_NHD_RISING    0x2C
#define MPR121_NCL_RISING    0x2D
#define MPR121_FDL_RISING    0x2E
#define MPR121_DEBOUNCE      0x5B
#define MPR121_CONFIG1       0x5C
#define MPR121_CONFIG2       0x5D
#define MPR121_ECR           0x5E
#define MPR121_AUTO_CONFIG0  0x7B
#define MPR121_AUTO_CONFIG1  0x7C
#define MPR121_AUTO_CONFIG2  0x7D

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %s\n",
                reg, value, pigpio_error(rc));
    }
    return rc;
}

static int mpr121_read16(uint8_t reg, uint16_t *out) {
    int rc = i2cReadWordData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %s\n",
                reg, pigpio_error(rc));
        return -1;
    }
    *out = (uint16_t)rc;
    return 0;
}

static int mpr121_init(void) {
    /* Soft reset: write 0x63 to ECR to put MPR121 in stop mode, then 0x00 to enable */
    if (mpr121_write(MPR121_ECR, 0x63) < 0) return -1;
    gpioDelay(1000); /* 1 ms settle */
    if (mpr121_write(MPR121_ECR, 0x00) < 0) return -1;
    gpioDelay(1000);

    /* Baseline filtering – rising */
    if (mpr121_write(MPR121_MHD_RISING, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NHD_RISING, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NCL_RISING, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_FDL_RISING, 0x00) < 0) return -1;

    /* Debounce: 3 samples for touch, 3 for release */
    if (mpr121_write(MPR121_DEBOUNCE, 0x33) < 0) return -1;

    /* FFI=6 samples, CDC=16 µA, CDT=0.5 µs */
    if (mpr121_write(MPR121_CONFIG1, 0x10) < 0) return -1;

    /* SFI=4 samples, ESI=4 ms */
    if (mpr121_write(MPR121_CONFIG2, 0x20) < 0) return -1;

    /* Auto-config registers */
    if (mpr121_write(MPR121_AUTO_CONFIG0, 0x0B) < 0) return -1;
    if (mpr121_write(MPR121_AUTO_CONFIG1, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_AUTO_CONFIG2, 0x00) < 0) return -1;

    /* Enable 12 electrodes, baseline tracking */
    if (mpr121_write(MPR121_ECR, 0x0C) < 0) return -1;
    gpioDelay(1000);

