    uint16_t lo, hi;
    if (mpr121_read16(MPR121_TOUCHSTATUS_L, &lo) < 0) return -1;
    if (mpr121_read16(MPR121_TOUCHSTATUS_H, &hi) < 0) return -1;
    *status = (uint16_t)((hi << 8) | lo);
    return 0;
}

