#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <stdarg.h>
#include <gpiod.h>

#define SERVO_PIN 17
#define PIR_PIN 4
#define PORT 5000
#define LOG_FILE "security.log"
#define MAX_BUFFER 1024

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *servo_line = NULL;
static struct gpiod_line *pir_line = NULL;
static pthread_t pwm_thread;

static void log_message(int priority, const char *format, ...) {
    va_list args;
    va_start(args, format);
    char buf[MAX_BUFFER];
    vsnprintf(buf, sizeof(buf), format, args);
    va_end(args);
    syslog(priority, "%s", buf);
    if (log_file) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
        fprintf(log_file, "%s %s\n", ts, buf);
        fflush(log_file);
    }
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void *pwm_thread_func(void *arg) {
    (void)arg;
    struct timespec ts;
    int period_us = 20000; /* 50 Hz */
    int pulse_us = 0;
    int direction = 1;

    while (running) {
        if (gpiod_line_set_value(servo_line, 1) < 0) {
            log_message(LOG_ERR, "Failed to set servo high");
            break;
        }
        usleep(pulse_us);
        if (gpiod_line_set_value(servo_line, 0) < 0) {
            log_message(LOG_ERR, "Failed to set servo low");
            break;
        }
        usleep(period_us - pulse_us);
        pulse_us += 1000;
        if (pulse_us > 2000) { pulse_us = 1000; direction = 1; }
        if (pulse_us < 1000) { pulse_us = 2000; direction = -1; }
        pulse_us += direction;
    }
    return NULL;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        log_message(LOG_ERR, "Failed to open gpiochip4: %s", strerror(errno));
        return -1;
    }
    servo_line = gpiod_chip_get_line(chip, SERVO_PIN);
    if (!servo_line) {
        log_message(LOG_ERR, "Failed to get servo line: %s", strerror(errno));
        return -1;
    }
    if (gpiod_line_request_output(servo_line, "servo", 0) < 0) {
        log_message(LOG_ERR, "Failed to request servo line as output: %s", strerror(errno));
        return -1;
    }
    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        log_message(LOG_ERR, "Failed to get PIR line: %s", strerror(errno));
        return -1;
    }
    if (gpiod_line_request_input(pir_line, "pir") < 0) {
        log_message(LOG_ERR, "Failed to request PIR line as input: %s", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup_gpio(void) {
    if (servo_line) gpiod_line_release(servo_line);
    if (pir_line) gpiod_line_release(pir_line);
    if (chip) gpiod_chip_close(chip);
    servo_line = NULL;
    pir_line = NULL;
    chip = NULL;
}

static int init_socket(void) {
    struct sockaddr_in address;
    int opt = 1;

    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        log_message(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        return -1;
    }
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        log_message(LOG_ERR, "Setsockopt failed: %s", strerror(errno));
        close(server_fd);
        server_fd = -1;
        return -1;
    }
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_message(LOG_ERR, "Bind failed: %s", strerror(errno));
        close(server_fd);
        server_fd = -1;
        return -1;
    }
    if (listen(server_fd, 3) < 0) {
        log_message(LOG_ERR, "Listen failed: %s", strerror(errno));
        close(server_fd);
        server_fd = -1;
        return -1;
    }
    log_message(LOG_INFO, "Listening on port %d", PORT);
    return 0;
}

static void handle_client(int client_socket) {
    char buffer[MAX_BUFFER];
    ssize_t read_size;
    while ((read_size = recv(client_socket, buffer, MAX_BUFFER - 1, 0)) > 0) {
        buffer[read_size] = '\0';
        buffer[strcspn(buffer, "\r\n")] = '\0';
        log_message(LOG_INFO, "Received: %s", buffer);
        if (strncmp(buffer, "SERVO", 5) == 0) {
            int angle = atoi(buffer + 5);
            if (angle >= 0 && angle <= 180) {
                int pulse = (angle * 2000) / 180;
                if (pulse < 1000) pulse = 1000;
                if (pulse > 2000) pulse = 2000;
                if (gpiod_line_set_value(servo_line, 1) < 0) {
                    log_message(LOG_ERR, "Failed to set servo high");
                } else {
                    usleep(pulse);
                    if (gpiod_line_set_value(servo_line, 0) < 0) {
                        log_message(LOG_ERR, "Failed to set servo low");
                    }
                }
                send(client_socket, "OK", 2, 0);
            } else {
                send(client_socket, "Invalid angle", 14, 0);
            }
        } else if (strcmp(buffer, "PIR") == 0) {
            int val = gpiod_line_get_value(pir_line);
            if (val < 0) {
                log_message(LOG_ERR, "Failed to read PIR");
                send(client_socket, "Error", 5, 0);
            } else {
                char resp[8];
                snprintf(resp, sizeof(resp), "PIR:%d", val);
                send(client_socket, resp, strlen(resp), 0);
            }
        } else {
            send(client_socket, "Invalid command", 16, 0);
        }
    }
    if (read_size == 0) {
        log_message(LOG_INFO, "Client disconnected");
    } else if (read_size < 0) {
        log_message(LOG_ERR, "Recv failed: %s", strerror(errno));
    }
    close(client_socket);
}

int main(void) {
    openlog("security_server", LOG_PID | LOG_CONS, LOG_USER);
    log_message(LOG_INFO, "Starting security server");

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_message(LOG_ERR, "Failed to open log file: %s", strerror(errno));
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_gpio() != 0) {
        log_message(LOG_ERR, "GPIO initialization failed, exiting");
        if (log_file) fclose(log_file);
        closelog();
        return 1;
    }

    if (init_socket() != 0) {
        log_message(LOG_ERR, "Socket initialization failed, exiting");
        cleanup_gpio();
        if (log_file) fclose(log_file);
        closelog();
        return 1;
    }

    if (pthread_create(&pwm_thread, NULL, pwm_thread_func, NULL) != 0) {
        log_message(LOG_ERR, "Failed to create PWM thread: %s", strerror(errno));
        close(server_fd);
        cleanup_gpio();
        if (log_file) fclose(log_file);
        closelog();
        return 1;
    }

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t addrlen = sizeof(client_addr);
        int client_socket = accept(server_fd, (struct sockaddr *)&client_addr, &addrlen);
        if (client_socket < 0) {
            if (errno == EINTR && !running) break;
            log_message(LOG_ERR, "Accept failed: %s", strerror(errno));
            continue;
        }
        handle_client(client_socket);
    }

    log_message(LOG_INFO, "Shutting down");
    running = 0;
    pthread_join(pwm_thread, NULL);
    if (server_fd >= 0) close(server_fd);
    cleanup_gpio();
    if (log_file) fclose(log_file);
    closelog();
    return 0;
}

