    } else if (read_size < 0) {
        log_message(LOG_ERR, "Recv failed: %s", strerror(errno));
    }
    close(client_socket);
}

int main(void) {
    openlog("security_server", LOG_PID | LOG_CONS, LOG_USER);
    log_message(LOG_INFO, "Starting security server");

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_message(LOG_ERR, "Failed to open log file: %s", strerror(errno));
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_gpio() != 0) {
        log_message(LOG_ERR, "GPIO initialization failed, exiting");
        if (log_file) fclose(log_file);
        closelog();
        return 1;
    }

    if (init_socket() != 0) {
        log_message(LOG_ERR, "Socket initialization failed, exiting");
        cleanup_gpio();
        if (log_file) fclose(log_file);
        closelog();
        return 1;
    }

    if (pthread_create(&pwm_thread, NULL, pwm_thread_func, NULL) != 0) {
        log_message(LOG_ERR, "Failed to create PWM thread: %s", strerror(errno));
        close(server_fd);
        cleanup_gpio();
        if (log_file) fclose(log_file);
        closelog();
        return 1;
    }

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t addrlen = sizeof(client_addr);
        int client_socket = accept(server_fd, (struct sockaddr *)&client_addr, &addrlen);
        if (client_socket < 0) {
            if (errno == EINTR && !running) break;
            log_message(LOG_ERR, "Accept failed: %s", strerror(errno));
            continue;
        }
        handle_client(client_socket);
    }

    log_message(LOG_INFO, "Shutting down");
    running = 0;
    pthread_join(pwm_thread, NULL);
    if (server_fd >= 0) close(server_fd);
    cleanup_gpio();
    if (log_file) fclose(log_file);
    closelog();
    return 0;
}

