#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <getopt.h>
#include <errno.h>
#include <gpiod.h>

#define HX711_DOUT_PIN  23
#define HX711_SCK_PIN   24
#define SOLENOID_PIN    25

#define DEFAULT_THRESHOLD  1000.0f
#define DEFAULT_SCALE      100.0f
#define DEFAULT_DURATION   200
#define NUM_READINGS       5
#define TARE_READINGS      10
#define DATA_READY_TIMEOUT 1000000  /* microseconds */
#define POLL_INTERVAL_US   500000   /* 500 ms */
#define SCK_PULSE_US       1
#define MAX_RETRIES        3

static volatile sig_atomic_t program_running = 1;

static float tare_offset = 0.0f;
static float threshold   = DEFAULT_THRESHOLD;
static float scale       = DEFAULT_SCALE;
static int   duration_ms = DEFAULT_DURATION;

static struct gpiod_chip  *chip  = NULL;
static struct gpiod_line  *dout  = NULL;
static struct gpiod_line  *sck   = NULL;
static struct gpiod_line  *sol   = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void cleanup(void)
{
    if (sol) {
        gpiod_line_set_value(sol, 0);
        gpiod_line_release(sol);
    }
    if (sck) gpiod_line_release(sck);
    if (dout) gpiod_line_release(dout);
    if (chip) gpiod_chip_close(chip);
    closelog();
}

static int init_gpio(void)
{
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open gpiochip0: %s", strerror(errno));
        return -1;
    }

    dout = gpiod_chip_get_line(chip, HX711_DOUT_PIN);
    if (!dout) {
        syslog(LOG_ERR, "Failed to get DOUT line %d: %s", HX711_DOUT_PIN, strerror(errno));
        return -1;
    }
    if (gpiod_line_request_input(dout, "hx711_dout") < 0) {
        syslog(LOG_ERR, "Failed to request DOUT as input: %s", strerror(errno));
        return -1;
    }

    sck = gpiod_chip_get_line(chip, HX711_SCK_PIN);
    if (!sck) {
        syslog(LOG_ERR, "Failed to get SCK line %d: %s", HX711_SCK_PIN, strerror(errno));
        return -1;
    }
    if (gpiod_line_request_output(sck, "hx711_sck", 0) < 0) {
        syslog(LOG_ERR, "Failed to request SCK as output: %s", strerror(errno));
        return -1;
    }

    sol = gpiod_chip_get_line(chip, SOLENOID_PIN);
    if (!sol) {
        syslog(LOG_ERR, "Failed to get solenoid line %d: %s", SOLENOID_PIN, strerror(errno));
        return -1;
    }
    if (gpiod_line_request_output(sol, "solenoid", 0) < 0) {
        syslog(LOG_ERR, "Failed to request solenoid as output: %s", strerror(errno));
        return -1;
    }

    syslog(LOG_INFO, "GPIO initialized: DOUT=GPIO%d, SCK=GPIO%d, Solenoid=GPIO%d",
           HX711_DOUT_PIN, HX711_SCK_PIN, SOLENOID_PIN);
    return 0;
}

static int wait_for_dout_low(void)
{
    int elapsed = 0;
    while (elapsed < DATA_READY_TIMEOUT) {
        int val = gpiod_line_get_value(dout);
        if (val < 0) {
            syslog(LOG_ERR, "DOUT read failed: %s", strerror(errno));
            return -1;
        }
        if (val == 0) return 0;
        usleep(100);
        elapsed += 100;
    }
    syslog(LOG_ERR, "Timeout waiting for HX711 data ready");
    return -1;
}

static int read_hx711_raw(int32_t *out)
{
    if (wait_for_dout_low() < 0) return -1;

    int32_t value = 0;
    for (int i = 0; i < 24; i++) {
        if (gpiod_line_set_value(sck, 1) < 0) {
            syslog(LOG_ERR, "SCK high failed: %s", strerror(errno));
            return -1;
        }
        usleep(SCK_PULSE_US);
        value <<= 1;
        int bit = gpiod_line_get_value(dout);
        if (bit < 0) {
            syslog(LOG_ERR, "DOUT read failed: %s", strerror(errno));
            return -1;
        }
        if (bit) value |= 1;
        if (gpiod_line_set_value(sck, 0) < 0) {
            syslog(LOG_ERR, "SCK low failed: %s", strerror(errno));
            return -1;
        }
        usleep(SCK_PULSE_US);
    }

    /* 25th pulse: select Channel A / Gain 128 */
    if (gpiod_line_set_value(sck, 1) < 0) {
        syslog(LOG_ERR, "SCK high (25th) failed: %s", strerror(errno));
        return -1;
    }
    usleep(SCK_PULSE_US);
    if (gpiod_line_set_value(sck, 0) < 0) {
        syslog(LOG_ERR, "SCK low (25th) failed: %s", strerror(errno));
        return -1;
    }
    usleep(SCK_PULSE_US);

    /* Convert 24-bit two's complement to signed 32-bit */
    if (value & 0x800000) value |= 0xFF000000;
    *out = value;
    return 0;
}

static int read_average(int32_t *out)
{
    long sum = 0;
    int valid = 0;
    for (int i = 0; i < NUM_READINGS; i++) {
        int32_t v;
        if (read_hx711_raw(&v) == 0) {
            sum += v;
            valid++;
        }
        usleep(10000);
    }
    if (valid == 0) {
        syslog(LOG_ERR, "No valid HX711 readings in average");
        return -1;
    }
    *out = (int32_t)(sum / valid);
    return 0;
}

static int tare_sensor(void)
{
    long sum = 0;
    int valid = 0;
    syslog(LOG_INFO, "Taring sensor (remove all weight)...");
    for (int i = 0; i < TARE_READINGS; i++) {
        int32_t v;
        if (read_hx711_raw(&v) == 0) {
            sum += v;
            valid++;
        }
        usleep(10000);
    }
    if (valid == 0) {
        syslog(LOG_ERR, "Tare failed: no valid readings");
        return -1;
    }
    tare_offset = (float)sum / valid;
    syslog(LOG_INFO, "Tare complete. Offset = %.2f", tare_offset);
    return 0;
}

static void activate_solenoid(int ms)
{
    if (gpiod_line_set_value(sol, 1) < 0) {
        syslog(LOG_ERR, "Failed to set solenoid HIGH: %s", strerror(errno));
        return;
    }
    usleep((useconds_t)ms * 1000);
    if (gpiod_line_set_value(sol, 0) < 0) {
        syslog(LOG_ERR, "Failed to set solenoid LOW: %s", strerror(errno));
    }
}

static void usage(const char *prog)
{
    fprintf(stderr,
        "Usage: %s [options]\n"
        "  --threshold <g>   Weight threshold in grams (default %.1f)\n"
        "  --scale <f>       Conversion factor (default %.1f)\n"
        "  --duration <ms>   Solenoid activation duration in ms (default %d)\n",
        prog, DEFAULT_THRESHOLD, DEFAULT_SCALE, DEFAULT_DURATION);
}

int main(int argc, char *argv[])
{
    openlog("load_cell_monitor", LOG_PID | LOG_CONS, LOG_USER);

    struct option opts[] = {
        {"threshold",  required_argument, 0, 't'},
        {"scale",      required_argument, 0, 's'},
        {"duration",   required_argument, 0, 'd'},
        {"help",       no_argument,       0, 'h'},
        {0, 0, 0, 0}
    };

    int opt;
    while ((opt = getopt_long(argc, argv, "t:s:d:h", opts, NULL)) != -1) {
        switch (opt) {
            case 't': threshold = atof(optarg); break;
            case 's': scale = atof(optarg); break;
            case 'd': duration_ms = atoi(optarg); break;
            case 'h': usage(argv[0]); cleanup(); return 0;
            default:  usage(argv[0]); cleanup(); return 1;
        }
    }

    if (threshold <= 0.0f || scale <= 0.0f) {
        fprintf(stderr, "Error: threshold and scale must be positive\n");
        usage(argv[0]); cleanup(); return 1;
    }

    if (init_gpio() < 0) {
        cleanup(); return 1;
    }

    if (tare_sensor() < 0) {
        syslog(LOG_ERR, "Tare failed; exiting");
        cleanup(); return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction failed: %s", strerror(errno));
        cleanup(); return 1;
    }

    syslog(LOG_INFO, "Monitoring started. Threshold=%.1f g, Scale=%.2f, Duration=%d ms",
           threshold, scale, duration_ms);

    while (program_running) {
        int32_t raw;
        if (read_average(&raw) < 0) {
            syslog(LOG_ERR, "Read failed; retrying in 1 s");
            sleep(1);
            continue;
        }

        float weight = ((float)raw - tare_offset) / scale;
        syslog(LOG_INFO, "Weight: %.2f g (raw=%d)", weight, raw);

        if (weight > threshold) {
            syslog(LOG_INFO, "Threshold exceeded; activating solenoid for %d ms",
                   duration_ms);
            activate_solenoid(duration_ms);
        }

        usleep(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down");
    cleanup();
    return 0;
}

