/*
 * relay_controller.c — MQTT relay controller for Raspberry Pi 4 Model B
 *
 * Build:  gcc -O2 -Wall -Wextra -o relay_controller relay_controller.c -lmosquitto -lpigpio -lrt
 * Run:    sudo ./relay_controller
 *
 * Hardware:
 *   - Relay module on GPIO17 (BCM 17, physical pin 11)
 *   - Relay control pin tied to GPIO17, common tied to a 5 V or 3 V logic-safe
 *     load (e.g., a lamp or LED via a suitable driver).
 *
 * MQTT:
 *   - Broker:  localhost:1883
 *   - Topic:    home/lights/control
 *   - QoS:      0
 *   - Client ID: relay_controller_1
 *
 * Behaviour:
 *   - On startup: relay OFF (GPIO17 LOW).
 *   - On connect: subscribe to home/lights/control.
 *   - On message:  "ON"  -> relay ON (GPIO17 HIGH)
 *                  "OFF" -> relay OFF (GPIO17 LOW)
 *                  any other payload -> syslog error, relay unchanged.
 *   - On disconnection: wait 5 s, reconnect and resubscribe.
 *   - On SIGINT/SIGTERM: graceful shutdown (relay OFF, cleanup).
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_BROKER_ADDRESS   "localhost"
#define MQTT_BROKER_PORT      1883
#define MQTT_CLIENT_ID        "relay_controller_1"
#define MQTT_TOPIC            "home/lights/control"
#define MQTT_KEEPALIVE        60
#define GPIO_RELAY            17
#define RECONNECT_DELAY_SEC   5

static volatile sig_atomic_t g_running = 1;
static struct mosquitto *g_mosq = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int gpio_init(void)
{
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    if (gpioSetMode(GPIO_RELAY, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode(%d, PI_OUTPUT) failed", GPIO_RELAY);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(GPIO_RELAY, 0) != 0) {   /* relay OFF at startup */
        syslog(LOG_ERR, "gpioWrite(%d, 0) failed", GPIO_RELAY);
        gpioTerminate();
        return -1;
    }
    syslog(LOG_INFO, "GPIO%d initialised as output (relay OFF)", GPIO_RELAY);
    return 0;
}

static void relay_set(int state)
{
    if (gpioWrite(GPIO_RELAY, state) != 0) {
        syslog(LOG_ERR, "gpioWrite(%d, %d) failed", GPIO_RELAY, state);
    } else {
        syslog(LOG_INFO, "Relay set to %s (GPIO%d=%d)", state ? "ON" : "OFF", GPIO_RELAY, state);
    }
}

/* ------------------------------------------------------------------ */
/* MQTT helpers                                                        */
/* ------------------------------------------------------------------ */
static void on_connect(struct mosquitto *mosq, void *userdata, int result)
{
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "Connected to MQTT broker (result=0)");
        int rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Subscribe to %s failed: %s",
                   MQTT_TOPIC, mosquitto_strerror(rc));
        } else {
            syslog(LOG_INFO, "Subscribed to %s (QoS 0)", MQTT_TOPIC);
        }
    } else {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(result));
    }
}

static void on_disconnect(struct mosquitto *mosq, void *userdata, int rc)
{
    (void)mosq;
    (void)userdata;
    if (rc == 0) {
        syslog(LOG_INFO, "Disconnected cleanly (rc=0)");
    } else {
        syslog(LOG_WARNING, "Unexpected MQTT disconnect (rc=%d): %s",
               rc, mosquitto_strerror(rc));
    }
}

static void on_message(struct mosquitto *mosq, void *userdata,
                        const struct mosquitto_message *message)
{
    (void)mosq;
    (void)userdata;

    if (message->payloadlen <= 0) {
        syslog(LOG_ERR, "Empty payload on topic %s", message->topic);
        return;
    }

    /* Treat payload as NUL-terminated string */
    char payload[32];
    size_t len = (size_t)message->payloadlen;
    if (len >= sizeof(payload))
        len = sizeof(payload) - 1;
    memcpy(payload, message->payload, len);
    payload[len] = '\0';

    syslog(LOG_INFO, "Received on %s: %s", message->topic, payload);

    if (strcmp(payload, "ON") == 0) {
        relay_set(1);
    } else if (strcmp(payload, "OFF") == 0) {
        relay_set(0);
    } else {
        syslog(LOG_ERR, "Invalid payload '%s' — expected ON or OFF", payload);
    }
}

static int mqtt_init(void)
{
    g_mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!g_mosq) {
        syslog(LOG_ERR, "mosquitto_new failed: out of memory");
        return -1;
    }

    mosquitto_connect_callback_set(g_mosq, on_connect);
    mosquitto_disconnect_callback_set(g_mosq, on_disconnect);
    mosquitto_message_callback_set(g_mosq, on_message);

    int rc = mosquitto_connect(g_mosq, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT,
                               MQTT_KEEPALIVE);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "mosquitto_connect failed: %s", mosquitto_strerror(rc));
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
        return -1;
    }
    return 0;
}

static void mqtt_loop(void)
{
    int rc = mosquitto_loop(g_mosq, -1, 1);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "mosquitto_loop error: %s", mosquitto_strerror(rc));
        /* Attempt to reconnect on transient failure */
        sleep(RECONNECT_DELAY_SEC);
        if (g_mosq) {
            mosquitto_destroy(g_mosq);
            g_mosq = NULL;
        }
        mqtt_init();
    }
}

static void cleanup(void)
{
    syslog(LOG_INFO, "Shutting down relay controller...");

    /* Stop relay first for safety */
    relay_set(0);

    if (g_mosq) {
        mosquitto_disconnect(g_mosq);
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
    }
    mosquitto_lib_cleanup();

    gpioTerminate();
    closelog();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction failed: %m");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpio_init() != 0) {
        closelog();
        return EXIT_FAILURE;
    }

    if (mqtt_init() != 0) {
        relay_set(0);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Relay controller started (GPIO%d, topic %s)",
           GPIO_RELAY, MQTT_TOPIC);

    while (g_running) {
        mqtt_loop();
    }

    cleanup();
    return EXIT_SUCCESS;
}

