        if (gpioSetPWMfrequency(pins[i], 50) != 50) {
            fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(pins[i], 20000) != 20000) {
            fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < num_servos; i++) {
        if (gpioServo(pins[i], pulses[i]) != 0) {
            fprintf(stderr, "Error: failed to set servo pulse on GPIO %d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("Servos moving to positions...\n");
    gpioDelay(HOLD_MS * 1000);

    for (int i = 0; i < num_servos; i++) {
        gpioServo(pins[i], 0);
    }

    gpioTerminate();
    printf("Servos stopped.\n");
    return EXIT_SUCCESS;
}

