#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments ---- */
#define MOTOR_A_PWM  17
#define MOTOR_A_DIR  18
#define MOTOR_B_PWM  22
#define MOTOR_B_DIR  23

#define ENCODER_A_A  4
#define ENCODER_A_B  5
#define ENCODER_B_A  6
#define ENCODER_B_B  12

/* ---- Hardware constants ---- */
#define ENCODER_TICKS_PER_REV 64
#define TARGET_SPEED_RPM      50.0
#define PWM_FREQ_HZ           10000
#define PWM_RANGE             255
#define CONTROL_PERIOD_US     100000   /* 100 ms */
#define STALL_TIMEOUT_S       2.0

/* ---- PI controller ---- */
#define KP 0.5
#define KI 0.05

/* ---- Globals ---- */
static volatile int g_running = 1;
static volatile int g_encoder_a = 0;
static volatile int g_encoder_b = 0;

/* ---- Prototypes ---- */
static void signal_handler(int sig);
static void encoder_a_isr(int gpio, int level, uint32_t tick, void *userdata);
static void encoder_b_isr(int gpio, int level, uint32_t tick, void *userdata);
static void set_motor_speed(int motor, int pwm_duty);
static void stop_motors(void);
static double calculate_error(double target, double actual);
static double pi_control(double error, double *integral, double *prev_error);
static void check_stall(double dt);
static void cleanup(void);

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure motor control pins */
    if (gpioSetMode(MOTOR_A_PWM, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_A_DIR, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_PWM, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_DIR, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set motor GPIO modes.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure encoder pins (inputs with pull-ups) */
    if (gpioSetMode(ENCODER_A_A, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER_A_B, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER_B_A, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER_B_B, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set encoder GPIO modes.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioSetPullUpDown(ENCODER_A_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_A_B, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_B_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_B_B, PI_PUD_UP);

    /* Register ISR callbacks (rising edge only) */
    if (gpioSetISRFuncEx(ENCODER_A_A, RISING_EDGE, 0, encoder_a_isr, NULL) != 0 ||
        gpioSetISRFuncEx(ENCODER_A_B, RISING_EDGE, 0, encoder_a_isr, NULL) != 0 ||
        gpioSetISRFuncEx(ENCODER_B_A, RISING_EDGE, 0, encoder_b_isr, NULL) != 0 ||
        gpioSetISRFuncEx(ENCODER_B_B, RISING_EDGE, 0, encoder_b_isr, NULL) != 0) {
        fprintf(stderr, "Error: failed to register ISR callbacks.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Set PWM frequency and range */
    if (gpioSetPWMfrequency(MOTOR_A_PWM, PWM_FREQ_HZ) < 0 ||
        gpioSetPWMfrequency(MOTOR_B_PWM, PWM_FREQ_HZ) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(MOTOR_A_PWM, PWM_RANGE) != 0 ||
        gpioSetPWMrange(MOTOR_B_PWM, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Closed-loop speed control started. Target: %.1f RPM\n", TARGET_SPEED_RPM);
    printf("Press Ctrl+C to stop.\n");

    /* Main control loop */
    double integral_a = 0.0, prev_error_a = 0.0;
    double integral_b = 0.0, prev_error_b = 0.0;
    double last_tick = gpioTick();
    int   last_a = 0, last_b = 0;
    int   stall_a = 0, stall_b = 0;

    while (g_running) {
        double now = (double)gpioTick() / 1.0e6;
        double dt = now - last_tick;
        last_tick = now;

        /* Atomically read and update encoder counts */
        int a = g_encoder_a;
        int b = g_encoder_b;
        g_encoder_a = 0;
        g_encoder_b = 0;

        /* Detect stall: no ticks for STALL_TIMEOUT_S seconds */
        if (dt >= STALL_TIMEOUT_S) {
            if (a == last_a && a == 0) stall_a = 1;
            if (b == last_b && b == 0) stall_b = 1;
            last_a = a;
            last_b = b;
        }

        /* Calculate actual RPM from delta counts */
        double da = (double)(a - last_a);
        double db = (double)(b - last_b);
        double rpm_a = da * (60.0 / ENCODER_TICKS_PER_REV) / dt;
        double rpm_b = db * (60.0 / ENCODER_TICKS_PER_REV) / dt;

        /* PI controller */
        double err_a = calculate_error(TARGET_SPEED_RPM, rpm_a);
        double out_a = pi_control(err_a, &integral_a, &prev_error_a);
        double err_b = calculate_error(TARGET_SPEED_RPM, rpm_b);
        double out_b = pi_control(err_b, &integral_b, &prev_error_b);

        /* Clamp output to [0, 255] */
        if (out_a < 0.0) out_a = 0.0;
        if (out_a > 255.0) out_a = 255.0;
        if (out_b < 0.0) out_b = 0.0;
        if (out_b > 255.0) out_b = 255.0;

        /* Drive motors: forward = PWM on IN1/IN3, direction on IN2/IN4 */
        set_motor_speed(0, (int)out_a);
        set_motor_speed(1, (int)out_b);

        /* Stall warning */
        if (stall_a) {
            fprintf(stderr, "Warning: Motor A stall detected (no ticks for %.0f s)\n",
                    STALL_TIMEOUT_S);
            stall_a = 0; /* avoid repeated warnings */
        }
        if (stall_b) {
            fprintf(stderr, "Warning: Motor B stall detected (no ticks for %.0f s)\n",
                    STALL_TIMEOUT_S);
            stall_b = 0;
        }

        /* Debug output */
        printf("Motor A: RPM=%.2f  PWM=%d  |  Motor B: RPM=%.2f  PWM=%d\n",
               rpm_a, (int)out_a, rpm_b, (int)out_b);

        gpioDelay(CONTROL_PERIOD_US);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    stop_motors();
    cleanup();
    return EXIT_SUCCESS;
}

/* ------------------------------------------------------------------ */
static void encoder_a_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)level; (void)tick; (void)userdata;
    g_encoder_a++;
}

static void encoder_b_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)level; (void)tick; (void)userdata;
    g_encoder_b++;
}

/* ------------------------------------------------------------------ */
static void set_motor_speed(int motor, int pwm_duty)
{
    int in1, in2;
    if (motor == 0) {
        in1 = MOTOR_A_PWM; in2 = MOTOR_A_DIR;
    } else {
        in1 = MOTOR_B_PWM; in2 = MOTOR_B_DIR;
    }
    gpioWrite(in1, 1);
    gpioWrite(in2, 0);
    gpioPWM(in1, pwm_duty);
}

static void stop_motors(void)
{
    gpioPWM(MOTOR_A_PWM, 0);
    gpioPWM(MOTOR_B_PWM, 0);
    gpioWrite(MOTOR_A_DIR, 0);
    gpioWrite(MOTOR_B_DIR, 0);
}

/* ------------------------------------------------------------------ */
static double calculate_error(double target, double actual)
{
    return target - actual;
}

static double pi_control(double error, double *integral, double *prev_error)
{
    double out = KP * error + KI * (*integral);
    *integral += error;
    if (*integral > 255.0) { *integral = 255.0; out = 255.0; }
    if (*integral < 0.0)   { *integral = 0.0;   out = 0.0;   }
    return out;
}

static void check_stall(double dt)
{
    static double last_zero_a = 0.0, last_zero_b = 0.0;
    static int    stall_a = 0, stall_b = 0;

    if (dt >= STALL_TIMEOUT_S) {
        if (g_encoder_a == 0) {
            if (last_zero_a == 0.0) last_zero_a = dt;
            else if (dt - last_zero_a > STALL_TIMEOUT_S) {
                if (!stall_a) {
                    fprintf(stderr, "Warning: Motor A stall detected (no ticks for %.0f s)\n",
                            STALL_TIMEOUT_S);
                    stall_a = 1;
                }
            }
        } else {
            last_zero_a = 0.0;
        }
        if (g_encoder_b == 0) {
            if (last_zero_b == 0.0) last_zero_b = dt;
            else if (dt - last_zero_b > STALL_TIMEOUT_S) {
                if (!stall_b) {
                    fprintf(stderr, "Warning: Motor B stall detected (no ticks for %.0f s)\n",
                            STALL_TIMEOUT_S);
                    stall_b = 1;
                }
            }
        } else {
            last_zero_b = 0.0;
        }
    }
}

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    stop_motors();
    gpioTerminate();
}

