#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_US 50000  /* 50 ms */
#define LOOP_DELAY_US 10000      /* 10 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_relay_state(int state) {
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) != NULL &&
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) > 0) {
        printf("[%s] Relay toggled to %s\n", ts, state ? "ON" : "OFF");
    } else {
        printf("[unknown] Relay toggled to %s\n", state ? "ON" : "OFF");
    }
    fflush(stdout);
}

int main(void) {
    int relay_state = 0;
    int prev_touch = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: could not register SIGINT handler.\n");
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize relay to OFF.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch sensor relay control started.\n");
    printf("  Touch sensor : GPIO %d (physical pin 7)\n", TOUCH_SENSOR_PIN);
    printf("  Relay        : GPIO %d (physical pin 11)\n", RELAY_PIN);
    printf("  Toggle       : each valid touch toggles the relay.\n");
    printf("  Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (running) {
        int touch = gpioRead(TOUCH_SENSOR_PIN);

        if (touch < 0) {
            fprintf(stderr, "Error: failed to read GPIO %d.\n", TOUCH_SENSOR_PIN);
            break;
        }

        if (touch == 1 && prev_touch == 1) {
            gpioDelay(DEBOUNCE_DELAY_US);
            touch = gpioRead(TOUCH_SENSOR_PIN);
            if (touch < 0) {
                fprintf(stderr, "Error: failed to read GPIO %d during debounce.\n", TOUCH_SENSOR_PIN);
                break;
            }
            if (touch == 1) {
                relay_state = !relay_state;
                if (gpioWrite(RELAY_PIN, relay_state) != 0) {
                    fprintf(stderr, "Error: failed to write GPIO %d.\n", RELAY_PIN);
                    break;
                }
                log_relay_state(relay_state);
            }
        }

        prev_touch = touch;
        gpioDelay(LOOP_DELAY_US);
    }

    /* Graceful shutdown */
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Warning: failed to turn relay OFF during shutdown.\n");
    }
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

