#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

#define FLOW_SENSOR_PIN 17
#define SOLENOID_PIN 27
#define PULSES_PER_LITER 450.0
#define FLOW_THRESHOLD 5.0
#define FLOW_HYSTERESIS 0.5
#define SAMPLE_INTERVAL_US 1000000
#define DEBOUNCE_US 1000000

static volatile int pulse_count = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", ts, message);
    fflush(log_file);
}

static void flow_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (log_file) {
        log_event("Shutting down, reopening solenoid.");
        gpioWrite(SOLENOID_PIN, 1);
        fclose(log_file);
        log_file = NULL;
    }
    pthread_mutex_destroy(&pulse_mutex);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set flow sensor pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set solenoid pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(SOLENOID_PIN, 1) != 0) {
        fprintf(stderr, "Failed to initialize solenoid state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, DEBOUNCE_US, flow_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set flow sensor ISR\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("water_flow.log", "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, DEBOUNCE_US, NULL, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("Water flow monitoring started.");

    int solenoid_state = 1;
    while (running) {
        int pulses;
        pthread_mutex_lock(&pulse_mutex);
        pulses = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        double flow_rate = (pulses / PULSES_PER_LITER) * 60.0;

        char log_msg[128];
        snprintf(log_msg, sizeof(log_msg), "Flow rate: %.2f L/min (pulses: %d)", flow_rate, pulses);
        log_event(log_msg);

        if (flow_rate > FLOW_THRESHOLD && solenoid_state == 1) {
            if (gpioWrite(SOLENOID_PIN, 0) == 0) {
                solenoid_state = 0;
                log_event("Solenoid closed (flow > threshold).");
            } else {
                log_event("Error: failed to close solenoid.");
            }
        } else if (flow_rate < (FLOW_THRESHOLD - FLOW_HYSTERESIS) && solenoid_state == 0) {
            if (gpioWrite(SOLENOID_PIN, 1) == 0) {
                solenoid_state = 1;
                log_event("Solenoid opened (flow < hysteresis).");
            } else {
                log_event("Error: failed to open solenoid.");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

