#define CONFIG_FILE "config.ini"
#define HX711_TIMEOUT_ATTEMPTS 1000
#define SERVO_MIN_PULSE_WIDTH 1000
#define SERVO_MAX_PULSE_WIDTH 2000
#define SERVO_SETTLE_US 500000
#define SERVO_OPEN_US 1500
#define SERVO_CLOSED_US 1000
#define SERVO_MIN_ANGLE 0
#define SERVO_MAX_ANGLE 180
#define SERVO_OPEN_ANGLE 90
#define SERVO_CLOSED_ANGLE 0
#define SERVO_SETTLE_ANGLE 90
#define SERVO_OPEN_DELAY_MS 1000
#define SERVO_CLOSE_DELAY_MS 1000
#define SERVO_SETTLE_DELAY_MS 500

static volatile sig_atomic_t running = 1;
static double calibration_factor = DEFAULT_CALIBRATION_FACTOR;
static char server_ip[32] = DEFAULT_SERVER_IP;
static int server_port = DEFAULT_SERVER_PORT;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int *out_value) {
    int data = 0;
    int timeout = 0;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_SCK_PIN, PI_OUTPUT);
    gpioWrite(HX711_SCK_PIN, 0);

    while (gpioRead(HX711_DATA_PIN) == 1) {
        if (++timeout > HX711_TIMEOUT_ATTEMPTS) {
            fprintf(stderr, "HX711 timeout: sensor not ready or absent\n");
            return -1;
        }
        gpioDelay(1);
    }

    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK_PIN, 1);
        gpioDelay(1);
        data <<= 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data |= 1;
        }
        gpioWrite(HX711_SCK_PIN, 0);
        gpioDelay(1);
    }

    gpioWrite(HX711_SCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_SCK_PIN, 0);
    gpioDelay(1);

    if (data & 0x800000) {
        data |= ~0xFFFFFF;
    }

    *out_value = data;
    return 0;
}

static int calibrate_hx711(void) {
    double known_weight = 100.0;
    double measured_weight = 0.0;
    int raw_value;

    printf("Place a known weight on the load cell and enter its weight in grams: ");
    fflush(stdout);
    if (scanf("%lf", &known_weight) != 1 || known_weight <= 0.0) {
        fprintf(stderr, "Invalid known weight. Using default calibration factor.\n");
        return -1;
    }
    printf("Calibrating...\n");

    if (read_hx711(&raw_value) != 0) {
        fprintf(stderr, "HX711 calibration failed: sensor not ready.\n");
        return -1;
    }

    measured_weight = (double)raw_value / calibration_factor;
    calibration_factor = known_weight / measured_weight;
    printf("Calibration factor: %.2f\n", calibration_factor);
    return 0;
}

static int control_servo(int angle) {
    if (angle < SERVO_MIN_ANGLE || angle > SERVO_MAX_ANGLE) {
        fprintf(stderr, "Invalid servo angle: %d\n", angle);
        return -1;
    }
    int pulse_width = SERVO_MIN_PULSE_WIDTH + (angle * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) / SERVO_MAX_ANGLE);
    gpioServo(SERVO_PIN, pulse_width);
    return 0;
}

static int log_event(double target_weight, double actual_weight, const char *error_msg) {
    FILE *fp = fopen(LOG_FILE, "r");
    int is_empty = 1;
    if (fp) {
        fseek(fp, 0, SEEK_END);
        if (ftell(fp) > 0) {
            is_empty = 0;
        }
        fclose(fp);
    }

    fp = fopen(LOG_FILE, "w");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    if (is_empty) {
        fprintf(fp, "[\n");
    } else {
        fseek(fp, -2, SEEK_END);
        if (ftell(fp) < 2) {
            fseek(fp, -1, SEEK_END);
            if (fgetc(fp) != ']') {
                fseek(fp, 0, SEEK_END);
            }
        }
        fprintf(fp, ",\n");
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "  {\"timestamp\":\"%s\",\"target_weight\":%.2f,\"actual_weight\":%.2f,\"error\":\"%s\"}\n",
            timestamp, target_weight, actual_weight, error_msg ? error_msg : "none");
    fprintf(fp, "]\n");
    fclose(fp);
    return 0;
}

static int send_data(int sock, double actual_weight) {
    char buffer[64];
    int len = snprintf(buffer, sizeof(buffer), "%.2f", actual_weight);
    if (send(sock, buffer, len, 0) < 0) {
        fprintf(stderr, "Error sending data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int receive_data(int sock, double *target_weight) {
    char buffer[64];
    int n = recv(sock, buffer, sizeof(buffer) - 1, 0);
    if (n < 0) {
        fprintf(stderr, "Error receiving data: %s\n", strerror(errno));
        return -1;
    }
    if (n == 0) {
        fprintf(stderr, "Client disconnected\n");
        return -1;
    }
    buffer[n] = '\0';
    char *endptr;
    double val = strtod(buffer, &endptr);
    if (endptr == buffer || *endptr != '\0') {
        fprintf(stderr, "Invalid weight received: %s\n", buffer);
        return -1;
    }
    *target_weight = val;
    return 0;
}

static int read_config(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: config file not found, using defaults.\n");
        return 0;
    }
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        line[strcspn(line, "\n")] = 0;
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");
        if (key && value) {
            if (strcmp(key, "calibration_factor") == 0) {
                calibration_factor = atof(value);
            } else if (strcmp(key, "server_ip") == 0) {
                strncpy(server_ip, value, sizeof(server_ip) - 1);
                server_ip[sizeof(server_ip) - 1] = '\0';
            } else if (strcmp(key, "server_port") == 0) {
                server_port = atoi(value);
            }
        }
    }
    fclose(fp);
    printf("Config loaded: calibration_factor=%.2f, server_ip=%s, server_port=%d\n",
           calibration_factor, server_ip, server_port);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (read_config(CONFIG_FILE) != 0) {
        fprintf(stderr, "Using default config values.\n");
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (calibrate_hx711() != 0) {
        fprintf(stderr, "Calibration failed. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        fprintf(stderr, "Socket creation failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        fprintf(stderr, "setsockopt failed: %s\n", strerror(errno));
        close(server_fd);
        gpioTerminate();
        return 1;
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = inet_addr(server_ip);
    address.sin_port = htons(server_port);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        fprintf(stderr, "Bind failed: %s\n", strerror(errno));
        close(server_fd);
        gpioTerminate();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        fprintf(stderr, "Listen failed: %s\n", strerror(errno));
        close(server_fd);
        gpioTerminate();
        return 1;
    }

    printf("Server listening on %s:%d\n", server_ip, server_port);

    while (running) {
        int client_fd = accept(server_fd, NULL, NULL);
        if (client_fd < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Accept failed: %s\n", strerror(errno));
            continue;
        }

        double target_weight;
        if (receive_data(client_fd, &target_weight) != 0) {
            close(client_fd);
            continue;
        }

        printf("Target weight: %.2f g\n", target_weight);

        if (control_servo(SERVO_OPEN_ANGLE) != 0) {
            fprintf(stderr, "Failed to open servo\n");
            send_data(client_fd, target_weight);
            close(client_fd);
            continue;
        }

        gpioDelay(SERVO_OPEN_DELAY_MS * 1000);

        int raw_value;
        if (read_hx711(&raw_value) != 0) {
            fprintf(stderr, "Failed to read HX711\n");
            send_data(client_fd, target_weight);
            control_servo(SERVO_CLOSED_ANGLE);
            close(client_fd);
            continue;
        }

        double actual_weight = (double)raw_value / calibration_factor;
        printf("Actual weight: %.2f g\n", actual_weight);

        if (log_event(target_weight, actual_weight, NULL) != 0) {
            fprintf(stderr, "Failed to log event\n");
        }

        if (send_data(client_fd, actual_weight) != 0) {
            fprintf(stderr, "Failed to send data\n");
        }

        if (control_servo(SERVO_CLOSED_ANGLE) != 0) {
            fprintf(stderr, "Failed to close servo\n");
        }

        gpioDelay(SERVO_CLOSE_DELAY_MS * 1000);

        close(client_fd);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    close(server_fd);
    printf("Server shut down cleanly.\n");
    return 0;
}

