#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <termios.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define PWM_FREQ 50
#define PWM_RANGE 20000
#define MIN_PULSE 500
#define MAX_PULSE 2500
#define START_ANGLE 90
#define ANGLE_STEP 10

static volatile sig_atomic_t running = 1;
static int angle = START_ANGLE;
static struct termios orig_termios;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_pigpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

static int init_terminal(void) {
    struct termios termios;
    if (tcgetattr(STDIN_FILENO, &termios) != 0) {
        perror("tcgetattr");
        return -1;
    }
    orig_termios = termios;
    termios.c_lflag &= ~(ICANON | ECHO);
    termios.c_cc[VMIN] = 1;
    termios.c_cc[VTIME] = 0;
    if (tcsetattr(STDIN_FILENO, TCSANOW, &termios) != 0) {
        perror("tcsetattr");
        return -1;
    }
    return 0;
}

static void restore_terminal(void) {
    if (orig_termios.c_lflag & (ICANON | ECHO)) {
        tcsetattr(STDIN_FILENO, TCSANOW, &orig_termios);
    }
}

static int set_servo_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    int pulse = (int)(((float)angle / 180.0f) * (MAX_PULSE - MIN_PULSE) + MIN_PULSE);
    if (pulse < MIN_PULSE) pulse = MIN_PULSE;
    if (pulse > MAX_PULSE) pulse = MAX_PULSE;
    if (gpioServo(SERVO_PIN, pulse) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pin %d\n", SERVO_PIN);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    restore_terminal();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (init_pigpio() != 0) {
        return 1;
    }

    if (init_terminal() != 0) {
        cleanup();
        return 1;
    }

    printf("Servo control on GPIO%d. Initial angle: %d degrees\n", SERVO_PIN, angle);
    printf("Press '+' to increase, '-' to decrease, 'q' to quit.\n");
    fflush(stdout);

    while (running) {
        int c = getchar();
        if (c == EOF) {
            break;
        }
        if (c == '+') {
            angle += ANGLE_STEP;
            if (angle > 180) angle = 180;
        } else if (c == '-') {
            angle -= ANGLE_STEP;
            if (angle < 0) angle = 0;
        } else if (c == 'q') {
            break;
        }
        if (set_servo_angle(angle) != 0) {
            break;
        }
        printf("Angle: %d degrees\n", angle);
        fflush(stdout);
    }

    cleanup();
    return 0;
}

