#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define LOG_FILE "motor_rpm.log"
#define DEBOUNCE_US 2000
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static double calculate_rpm(long long pulse_count, double elapsed_seconds) {
    if (elapsed_seconds <= 0.0) return 0.0;
    return ((double)pulse_count / elapsed_seconds) * 60.0;
}

static int log_rpm(double rpm_value) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%.2f\n", timestamp, rpm_value) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    struct timespec last_pulse_time, current_time;
    long long pulse_count = 0;
    int ret;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input_flags(line, "conveyor-monitor",
                                          GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret != 0) {
        fprintf(stderr, "Failed to request line %d as input with pull-up: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (clock_gettime(CLOCK_MONOTONIC, &last_pulse_time) == -1) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        fclose(log_file);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Monitoring conveyor belt on GPIO %d. Press Ctrl+C to exit.\n", GPIO_LINE_OFFSET);

    while (program_running) {
        struct timespec ts = {0, DEBOUNCE_US * 1000};
        ret = gpiod_line_event_wait(line, &ts);

        if (ret < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "gpiod_line_event_wait failed: %s\n", strerror(errno));
            break;
        }

        if (ret == 0) {
            continue;
        }

        struct gpiod_line_event event;
        ret = gpiod_line_event_read(line, &event);
        if (ret != 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "gpiod_line_event_read failed: %s\n", strerror(errno));
            break;
        }

        if (event.event_type != GPIOD_LINE_EVENT_RISING_EDGE) {
            continue;
        }

        if (clock_gettime(CLOCK_MONOTONIC, &current_time) == -1) {
            fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
            break;
        }

        long long diff_us = (current_time.tv_sec - last_pulse_time.tv_sec) * 1000000LL +
                            (current_time.tv_nsec - last_pulse_time.tv_nsec) / 1000LL;

        if (diff_us < DEBOUNCE_US) {
            continue;
        }

        pulse_count++;
        last_pulse_time = current_time;
    }

    if (clock_gettime(CLOCK_MONOTONIC, &current_time) == -1) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        goto cleanup;
    }

    double elapsed = (double)(current_time.tv_sec - last_pulse_time.tv_sec) +
                     (double)(current_time.tv_nsec - last_pulse_time.tv_nsec) / 1e9;

    double rpm = calculate_rpm(pulse_count, elapsed);

    if (log_rpm(rpm) != 0) {
        fprintf(stderr, "Failed to log RPM.\n");
    }

    printf("RPM: %.2f\n", rpm);

cleanup:
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

