        fprintf(stderr, "Failed to log RPM.\n");
    }

    printf("RPM: %.2f\n", rpm);

cleanup:
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

