#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN        17
#define POLL_DELAY_US    50000   /* 50 ms */
#define FAILSAFE_TIMEOUT_S 10

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int safe_read(int pin)
{
    int v = gpioRead(pin);
    if (v == PI_BAD_GPIO) {
        fprintf(stderr, "Error: gpioRead(%d) returned PI_BAD_GPIO\n", pin);
        return -1;
    }
    return v;
}

static int safe_write(int pin, int level)
{
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(%d, %d) failed\n", pin, level);
        return -1;
    }
    return 0;
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", RELAY_PIN);
        gpioTerminate();
        return -1;
    }

    /* Start with relay OFF */
    if (safe_write(RELAY_PIN, 0) != 0) {
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup(void)
{
    /* Ensure relay is OFF before terminating pigpio */
    safe_write(RELAY_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    int relay_state = 0;
    int relay_off_count = 0;
    int last_touch = 0;
    int failsafe_active = 0;

    printf("Touch sensor relay control started. Press Ctrl+C to exit.\n");

    while (running) {
        int touch = safe_read(TOUCH_SENSOR_PIN);
        if (touch < 0) {
            break;
        }

        if (touch == 1 && last_touch == 0) {
            relay_state = !relay_state;
            if (safe_write(RELAY_PIN, relay_state) != 0) {
                break;
            }
            printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
            relay_off_count = 0;
            failsafe_active = 0;
        }

        if (touch == 1) {
            last_touch = 1;
            relay_off_count++;
            if (relay_off_count >= (FAILSAFE_TIMEOUT_S * 1000000) / POLL_DELAY_US) {
                if (!failsafe_active) {
                    printf("Failsafe triggered: sensor HIGH for > %d s. Relay forced OFF.\n",
                           FAILSAFE_TIMEOUT_S);
                    if (safe_write(RELAY_PIN, 0) != 0) {
                        break;
                    }
                    failsafe_active = 1;
                    relay_off_count = 0;
                }
            }
        } else {
            last_touch = 0;
            relay_off_count = 0;
            if (failsafe_active) {
                printf("Sensor released. Relay restored to last state.\n");
                if (safe_write(RELAY_PIN, relay_state) != 0) {
                    break;
                }
                failsafe_active = 0;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

