#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_PWM_PIN 18
#define VALVE_ENABLE_PIN 23
#define FLOW_SENSOR_PIN 24
#define PULSES_PER_LITER 450.0
#define SAMPLE_INTERVAL_US 100000
#define PWM_RANGE 255
#define PWM_FREQ 1000
#define LOG_FILE "flow_log.csv"

static volatile int pulse_count = 0;
static volatile int running = 1;
static FILE *log_file = NULL;
static double target_flow_rate = 0.0;
static double Kp = 1.0;

static void pulse_counter(int gpio, int level, uint32_t tick, void *user_data);
static double calculate_flow_rate(int pulses, double dt_sec);
static int set_valve_position(double flow_rate);
static void log_data(double flow_rate, double valve_position);
static void signal_handler(int signal);
static int initialize_gpio(void);
static void cleanup(void);

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                target_flow_rate = atof(optarg);
                if (target_flow_rate <= 0.0) {
                    fprintf(stderr, "Error: Target flow rate must be positive.\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s -t <target_flow_rate_L_min>\n", argv[0]);
                return 1;
        }
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp_ms,flow_rate_L_min,valve_position\n");
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        gpioDelay(SAMPLE_INTERVAL_US);

        int current_pulses = pulse_count;
        pulse_count = 0;

        double dt = (double)SAMPLE_INTERVAL_US / 1000000.0;
        double flow_rate = calculate_flow_rate(current_pulses, dt);

        int valve_position = set_valve_position(flow_rate);
        log_data(flow_rate, (double)valve_position);
    }

    cleanup();
    return 0;
}

static void pulse_counter(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; (void)level; (void)tick; (void)user_data;
    pulse_count++;
}

static double calculate_flow_rate(int pulses, double dt) {
    return (double)pulses / PULSES_PER_LITER / dt;
}

static int set_valve_position(double flow_rate) {
    int valve_position = (int)(Kp * (target_flow_rate - flow_rate));
    if (valve_position < 0) valve_position = 0;
    if (valve_position > PWM_RANGE) valve_position = PWM_RANGE;
    if (gpioPWM(VALVE_PWM_PIN, valve_position) != 0) {
        fprintf(stderr, "Error: Failed to set PWM duty cycle.\n");
        return -1;
    }
    return valve_position;
}

static void log_data(double flow_rate, double valve_position) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);
    fprintf(log_file, "%ld,%.4f,%.0f\n", timestamp_ms, flow_rate, valve_position);
    fflush(log_file);
}

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    if (gpioSetMode(VALVE_PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set PWM pin mode.\n");
        return 1;
    }
    if (gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set enable pin mode.\n");
        return 1;
    }
    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set sensor pin mode.\n");
        return 1;
    }

    if (gpioSetPWMrange(VALVE_PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: Failed to set PWM range.\n");
        return 1;
    }
    if (gpioSetPWMfrequency(VALVE_PWM_PIN, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency.\n");
        return 1;
    }
    if (gpioPWM(VALVE_PWM_PIN, 0) != 0) {
        fprintf(stderr, "Error: Failed to initialize PWM to 0.\n");
        return 1;
    }
    if (gpioWrite(VALVE_ENABLE_PIN, 1) != 0) {
        fprintf(stderr, "Error: Failed to enable valve.\n");
        return 1;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, pulse_counter, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set ISR function.\n");
        return 1;
    }

    return 0;
}

static void cleanup(void) {
    gpioPWM(VALVE_PWM_PIN, 0);
    gpioWrite(VALVE_ENABLE_PIN, 0);
    gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, NULL, NULL);
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

