#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LOCK_1_PIN 17
#define LOCK_2_PIN 27
#define BUTTON_PIN 22
#define SPI_CHANNEL 0
#define SPI_SPEED 100000
#define LOG_FILE "/var/log/door_access.log"
#define DEBOUNCE_US 50000
#define LOCK_RELEASE_US 5000000
#define POLL_US 100000

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;
static int spi_handle = -1;

static const unsigned char valid_tag[10] = {
    0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A
};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *msg) {
    if (!log_fp) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(log_fp, "%04d-%02d-%02dT%02d:%02d:%02d %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
        fflush(log_fp);
    }
}

static void release_locks(void) {
    if (gpioWrite(LOCK_1_PIN, 0) < 0) {
        log_event("ERROR: failed to write LOCK_1_PIN");
    }
    if (gpioWrite(LOCK_2_PIN, 0) < 0) {
        log_event("ERROR: failed to write LOCK_2_PIN");
    }
    gpioDelay(LOCK_RELEASE_US);
    if (gpioWrite(LOCK_1_PIN, 1) < 0) {
        log_event("ERROR: failed to re-engage LOCK_1_PIN");
    }
    if (gpioWrite(LOCK_2_PIN, 1) < 0) {
        log_event("ERROR: failed to re-engage LOCK_2_PIN");
    }
}

static void engage_locks(void) {
    if (gpioWrite(LOCK_1_PIN, 1) < 0) {
        log_event("ERROR: failed to engage LOCK_1_PIN");
    }
    if (gpioWrite(LOCK_2_PIN, 1) < 0) {
        log_event("ERROR: failed to engage LOCK_2_PIN");
    }
}

static int read_rfid_tag(unsigned char *tag) {
    unsigned char rx[10] = {0};
    int bytes = spiXfer(spi_handle, (char *)tag, (char *)rx, 10);
    if (bytes != 10) {
        return -1;
    }
    if (memcmp(rx, valid_tag, 10) == 0) {
        return 0;
    }
    return -2;
}

static int read_button(void) {
    if (gpioRead(BUTTON_PIN) == 0) {
        gpioDelay(DEBOUNCE_US);
        if (gpioRead(BUTTON_PIN) == 0) {
            return 1;
        }
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LOCK_1_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(LOCK_2_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(BUTTON_PIN, PI_INPUT) < 0) {
        log_event("ERROR: gpioSetMode failed");
        fclose(log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) < 0) {
        log_event("ERROR: gpioSetPullUpDown failed");
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        log_event("ERROR: spiOpen failed");
        fclose(log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        log_event("ERROR: sigaction failed");
        spiClose(spi_handle);
        fclose(log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    engage_locks();
    log_event("System started: locks engaged");

    while (running) {
        unsigned char rfid_tag[10] = {0};

        int rfid_rc = read_rfid_tag(rfid_tag);
        if (rfid_rc == 0) {
            log_event("RFID tag read successfully");
            if (read_button() == 1) {
                log_event("Button pressed - authentication successful");
                release_locks();
                log_event("Locks released");
            } else {
                log_event("Button press without valid RFID tag - denied");
            }
        } else if (rfid_rc == -1) {
            log_event("RFID read failure (SPI transfer error)");
        } else {
            log_event("Invalid RFID tag");
        }

        gpioDelay(POLL_US);
    }

    release_locks();
    log_event("System shutting down: locks re-engaged");
    spiClose(spi_handle);
    fclose(log_fp);
    gpioTerminate();
    return EXIT_SUCCESS;
}

