#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <gpiod.h>
#include <errno.h>

#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20
#define ENCODER1_A 5
#define ENCODER1_B 6
#define ENCODER2_A 26
#define ENCODER2_B 19
#define KP 1.0
#define KI 0.1
#define KD 0.01
#define SAMPLE_TIME_MS 100
#define PWM_FREQ_HZ 100
#define PWM_PERIOD_US (1000000 / PWM_FREQ_HZ)
#define PULSES_PER_REV 600
#define LOG_FILE "motor_log.csv"

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;
static pthread_mutex_t enc1_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_mutex_t enc2_mutex = PTHREAD_MUTEX_INITIALIZER;
static int enc1_count = 0;
static int enc2_count = 0;

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *motor_lines[6] = {NULL};
static struct gpiod_line *enc_a_lines[2] = {NULL};
static struct gpiod_line *enc_b_lines[2] = {NULL};
static struct gpiod_line *enc_a_events[2] = {NULL};
static struct gpiod_line *enc_b_events[2] = {NULL};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_motor_speed(int motor, int speed) {
    if (speed > 0) {
        motor_lines[motor * 3 + 1]->set_value(1);
        motor_lines[motor * 3 + 2]->set_value(0);
    } else if (speed < 0) {
        motor_lines[motor * 3 + 1]->set_value(0);
        motor_lines[motor * 3 + 2]->set_value(1);
    } else {
        motor_lines[motor * 3 + 1]->set_value(0);
        motor_lines[motor * 3 + 2]->set_value(0);
    }
    return 0;
}

static int motor_pwm(int motor, int duty) {
    if (duty < 0) duty = 0;
    if (duty > 100) duty = 100;
    int on_us = (duty * PWM_PERIOD_US) / 100;
    int off_us = PWM_PERIOD_US - on_us;
    if (on_us > 0) {
        gpiod_line_set_value(motor_lines[motor * 3 + 1], 1);
        usleep(on_us);
    }
    if (off_us > 0) {
        gpiod_line_set_value(motor_lines[motor * 3 + 1], 0);
        usleep(off_us);
    }
    return 0;
}

static void *encoder_thread(void *arg) {
    (void)arg;
    int idx = *(int *)arg;
    struct gpiod_line *a = enc_a_events[idx];
    struct gpiod_line *b = enc_b_events[idx];
    int last_a = gpiod_line_get_value(a);
    int last_b = gpiod_line_get_value(b);
    if (last_a < 0 || last_b < 0) {
        fprintf(stderr, "Error reading encoder %d initial state\n", idx + 1);
        return NULL;
    }
    while (running) {
        struct timespec ts = {0, 100000};
        int ret = gpiod_line_event_wait(a, &ts);
        if (ret < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Error waiting on encoder %d A: %s\n", idx + 1, strerror(errno));
            break;
        }
        if (ret == 0) continue;
        struct gpiod_line_event ev;
        if (gpiod_line_event_read(a, &ev) < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Error reading encoder %d A event: %s\n", idx + 1, strerror(errno));
            continue;
        }
        if (ev.event_type != GPIOD_LINE_EVENT_RISING_EDGE) continue;
        int a_val = gpiod_line_get_value(a);
        int b_val = gpiod_line_get_value(b);
        if (a_val < 0 || b_val < 0) {
            fprintf(stderr, "Error reading encoder %d pins: %s\n", idx + 1, strerror(errno));
            continue;
        }
        if (a_val == last_a && b_val == last_b) continue;
        last_a = a_val;
        last_b = b_val;
        pthread_mutex_lock(&((idx == 0) ? enc1_mutex : enc2_mutex));
        if (idx == 0) enc1_count += (b_val == last_b) ? 1 : -1;
        else enc2_count += (b_val == last_b) ? 1 : -1;
        pthread_mutex_unlock(&((idx == 0) ? enc1_mutex : enc2_mutex));
    }
    return NULL;
}

static double calculate_pid(double setpoint, double actual, double *integral, double *prev_error, double Kp, double Ki, double Kd, double dt) {
    double error = setpoint - actual;
    *integral += error * dt;
    if (*integral > 100.0) *integral = 100.0;
    if (*integral < -100.0) *integral = -100.0;
    double derivative = (error - *prev_error) / dt;
    double output = Kp * error + Ki * (*integral) + Kd * derivative;
    *prev_error = error;
    return output;
}

static void log_data(double speed1, double speed2, double pid1, double pid2, double integral1, double integral2, double prev_err1, double prev_err2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_fp, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
            timestamp, speed1, speed2, pid1, pid2, integral1, integral2, prev_err1, prev_err2);
    fflush(log_fp);
}

static void cleanup(void) {
    if (log_fp) { fclose(log_fp); log_fp = NULL; }
    for (int i = 0; i < 6; i++) {
        if (motor_lines[i]) { gpiod_line_release(motor_lines[i]); motor_lines[i] = NULL; }
    }
    for (int i = 0; i < 2; i++) {
        if (enc_a_lines[i]) { gpiod_line_release(enc_a_lines[i]); enc_a_lines[i] = NULL; }
        if (enc_b_lines[i]) { gpiod_line_release(enc_b_lines[i]); enc_b_lines[i] = NULL; }
        if (enc_a_events[i]) { gpiod_line_release(enc_a_events[i]); enc_a_events[i] = NULL; }
        if (enc_b_events[i]) { gpiod_line_release(enc_b_events[i]); enc_b_events[i] = NULL; }
    }
    if (chip) { gpiod_chip_close(chip); chip = NULL; }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return 1;
    }

    int motor_pins[6] = {MOTOR1_ENA, MOTOR1_IN1, MOTOR1_IN2, MOTOR2_ENB, MOTOR2_IN3, MOTOR2_IN4};
    for (int i = 0; i < 6; i++) {
        motor_lines[i] = gpiod_chip_get_line(chip, motor_pins[i]);
        if (!motor_lines[i]) {
            fprintf(stderr, "Failed to get motor line %d: %s\n", motor_pins[i], strerror(errno));
            cleanup();
            return 1;
        }
        if (gpiod_line_request_output(motor_lines[i], "l298n-motor", 0) < 0) {
            fprintf(stderr, "Failed to request motor line %d as output: %s\n", motor_pins[i], strerror(errno));
            cleanup();
            return 1;
        }
    }

    int enc_a_pins[2] = {ENCODER1_A, ENCODER2_A};
    int enc_b_pins[2] = {ENCODER1_B, ENCODER2_B};
    for (int i = 0; i < 2; i++) {
        enc_a_lines[i] = gpiod_chip_get_line(chip, enc_a_pins[i]);
        enc_b_lines[i] = gpiod_chip_get_line(chip, enc_b_pins[i]);
        if (!enc_a_lines[i] || !enc_b_lines[i]) {
            fprintf(stderr, "Failed to get encoder lines %d or %d: %s\n", enc_a_pins[i], enc_b_pins[i], strerror(errno));
            cleanup();
            return 1;
        }
        if (gpiod_line_request_input(enc_a_lines[i], "l298n-enc-a") < 0) {
            fprintf(stderr, "Failed to request encoder A line %d: %s\n", enc_a_pins[i], strerror(errno));
            cleanup();
            return 1;
        }
        if (gpiod_line_request_input(enc_b_lines[i], "l298n-enc-b") < 0) {
            fprintf(stderr, "Failed to request encoder B line %d: %s\n", enc_b_pins[i], strerror(errno));
            cleanup();
            return 1;
        }
        if (gpiod_line_request_both_edges_events(enc_a_lines[i], "l298n-enc-a-event") < 0) {
            fprintf(stderr, "Failed to request edge events on encoder A line %d: %s\n", enc_a_pins[i], strerror(errno));
            cleanup();
            return 1;
        }
        if (gpiod_line_request_both_edges_events(enc_b_lines[i], "l298n-enc-b-event") < 0) {
            fprintf(stderr, "Failed to request edge events on encoder B line %d: %s\n", enc_b_pins[i], strerror(errno));
            cleanup();
            return 1;
        }
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }
    fprintf(log_fp, "Timestamp,Motor1_RPM,Motor2_RPM,PID1,PID2,Integral1,Integral2,PrevError1,PrevError2\n");
    fflush(log_fp);

    int thread_ids[2];
    thread_ids[0] = ENCODER1_A;
    thread_ids[1] = ENCODER2_A;
    pthread_t enc_threads[2];
    for (int i = 0; i < 2; i++) {
        if (pthread_create(&enc_threads[i], NULL, encoder_thread, &thread_ids[i]) != 0) {
            fprintf(stderr, "Failed to create encoder thread %d: %s\n", i + 1, strerror(errno));
            cleanup();
            return 1;
        }
    }
    for (int i = 0; i < 2; i++) pthread_join(enc_threads[i], NULL);

    double setpoint1 = 60.0;
    double setpoint2 = 60.0;
    double integral1 = 0.0, integral2 = 0.0;
    double prev_err1 = 0.0, prev_err2 = 0.0;
    double dt = SAMPLE_TIME_MS / 1000.0;
    double speed1 = 0.0, speed2 = 0.0;
    double pid1 = 0.0, pid2 = 0.0;

    while (running) {
        pthread_mutex_lock(&enc1_mutex);
        int enc1 = enc1_count;
        enc1_count = 0;
        pthread_mutex_unlock(&enc1_mutex);
        pthread_mutex_lock(&enc2_mutex);
        int enc2 = enc2_count;
        enc2_count = 0;
        pthread_mutex_unlock(&enc2_mutex);

        speed1 = (enc1 * 60.0) / PULSES_PER_REV;
        speed2 = (enc2 * 60.0) / PULSES_PER_REV;

        pid1 = calculate_pid(setpoint1, speed1, &integral1, &prev_err1, KP, KI, KD, dt);
        pid2 = calculate_pid(setpoint2, speed2, &integral2, &prev_err2, KP, KI, KD, dt);

        int motor1_speed = (int)pid1;
        int motor2_speed = (int)pid2;
        set_motor_speed(0, motor1_speed);
        set_motor_speed(2, motor2_speed);

        log_data(speed1, speed2, pid1, pid2, integral1, integral2, prev_err1, prev_err2);
        usleep(SAMPLE_TIME_MS * 1000);
    }

    set_motor_speed(0, 0);
    set_motor_speed(2, 0);
    cleanup();
    return 0;
}

