#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define VALVE1_GPIO 17
#define VALVE2_GPIO 18
#define LOG_FILE "valve_log.txt"
#define GPIO_CHIP_NAME "gpiochip0"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *valve1_line = NULL;
static struct gpiod_line *valve2_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    if (tstruct == NULL) {
        fprintf(stderr, "Error: localtime failed\n");
        return;
    }
    if (strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S", tstruct) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return;
    }
    if (log_file != NULL) {
        if (fprintf(log_file, "%s: %s\n", buf, message) < 0) {
            fprintf(stderr, "Error: failed to write to log file\n");
        }
        if (fflush(log_file) != 0) {
            fprintf(stderr, "Error: failed to flush log file\n");
        }
    } else {
        fprintf(stderr, "Error: log file is not open\n");
    }
}

static void cleanup(void) {
    if (valve1_line != NULL) {
        gpiod_line_set_value(valve1_line, 0);
        gpiod_line_release(valve1_line);
        valve1_line = NULL;
    }
    if (valve2_line != NULL) {
        gpiod_line_set_value(valve2_line, 0);
        gpiod_line_release(valve2_line);
        valve2_line = NULL;
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        perror("Error opening GPIO chip");
        log_event("Error: failed to open GPIO chip");
        cleanup();
        return EXIT_FAILURE;
    }

    valve1_line = gpiod_chip_get_line(chip, VALVE1_GPIO);
    if (valve1_line == NULL) {
        perror("Error getting GPIO line for valve 1");
        log_event("Error: failed to get GPIO line for valve 1");
        cleanup();
        return EXIT_FAILURE;
    }

    valve2_line = gpiod_chip_get_line(chip, VALVE2_GPIO);
    if (valve2_line == NULL) {
        perror("Error getting GPIO line for valve 2");
        log_event("Error: failed to get GPIO line for valve 2");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(valve1_line, "valve1", 0) < 0) {
        perror("Error requesting GPIO line as output for valve 1");
        log_event("Error: failed to request GPIO line as output for valve 1");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(valve2_line, "valve2", 0) < 0) {
        perror("Error requesting GPIO line as output for valve 2");
        log_event("Error: failed to request GPIO line as output for valve 2");
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("Greenhouse water distribution system started");

    while (running) {
        log_event("Activating valve 1");
        if (gpiod_line_set_value(valve1_line, 1) < 0) {
            perror("Error setting valve 1 GPIO HIGH");
            log_event("Error: failed to activate valve 1");
        }
        usleep(500000);
        if (gpiod_line_set_value(valve1_line, 0) < 0) {
            perror("Error setting valve 1 GPIO LOW");
            log_event("Error: failed to deactivate valve 1");
        }
        log_event("Valve 1 deactivated");

        if (!running) break;

        log_event("Pausing 5 seconds");
        sleep(5);
        if (!running) break;

        log_event("Activating valve 2");
        if (gpiod_line_set_value(valve2_line, 1) < 0) {
            perror("Error setting valve 2 GPIO HIGH");
            log_event("Error: failed to activate valve 2");
        }
        usleep(1000000);
        if (gpiod_line_set_value(valve2_line, 0) < 0) {
            perror("Error setting valve 2 GPIO LOW");
            log_event("Error: failed to deactivate valve 2");
        }
        log_event("Valve 2 deactivated");

        if (!running) break;

        log_event("Pausing 10 seconds");
        sleep(10);
    }

    log_event("Shutting down greenhouse water distribution system");
    cleanup();
    return EXIT_SUCCESS;
}

