    if (rc != 2) {
        fprintf(stderr, "I2C read failed: rc=%d\n", rc);
        return -1;
    }
    *status = ((uint16_t)(uint8_t)buf[1] << 8) | (uint8_t)buf[0];
    return 0;
}

static void relay_toggle(void) {
    int level = gpioRead(RELAY_PIN);
    if (level < 0) {
        fprintf(stderr, "GPIO read failed on pin %d\n", RELAY_PIN);
        return;
    }
    if (gpioWrite(RELAY_PIN, !level) < 0) {
        fprintf(stderr, "GPIO write failed on pin %d\n", RELAY_PIN);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, MPR121_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_PIN);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPR121 touch relay controller running. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t touch_status = 0;
        if (mpr121_read_touch_status(&touch_status) == 0) {
            if (touch_status > 0) {
                relay_toggle();
                printf("Relay toggled (touch_status=0x%04X)\n", touch_status);
            }
        }
        gpioDelay(100000);  /* 100 ms */
    }

    printf("\nShutting down...\n");
    gpioWrite(RELAY_PIN, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

