#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define MIN_DUTY 0
#define MAX_DUTY 255
#define MIN_DELAY_MS 50
#define MAX_DELAY_MS 200
#define MIN_PATTERN_LENGTH 5
#define MAX_PATTERN_LENGTH 15

static volatile sig_atomic_t shutdown_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    shutdown_flag = 1;
}

static int generate_pattern(int *pattern, int length) {
    for (int i = 0; i < length; i++) {
        pattern[i * 2] = (rand() % (MAX_DUTY - MIN_DUTY + 1)) + MIN_DUTY;
        pattern[i * 2 + 1] = (rand() % (MAX_DELAY_MS - MIN_DELAY_MS + 1)) + MIN_DELAY_MS;
    }
    return 0;
}

static int play_pattern(const int *pattern, int length) {
    for (int i = 0; i < length; i++) {
        if (gpioPWM(MOTOR1_PIN, pattern[i * 2]) < 0) {
            fprintf(stderr, "Error setting PWM for motor 1\n");
            return -1;
        }
        if (gpioPWM(MOTOR2_PIN, pattern[i * 2 + 1]) < 0) {
            fprintf(stderr, "Error setting PWM for motor 2\n");
            return -1;
        }
        gpioDelay(pattern[i * 2]);
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR1_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR2_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR2_PIN);
        gpioTerminate();
        return 1;
    }

    srand((unsigned int)time(NULL));
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler\n");
        gpioTerminate();
        return 1;
    }

    int pattern_length = (rand() % (MAX_PATTERN_LENGTH - MIN_PATTERN_LENGTH + 1)) + MIN_PATTERN_LENGTH;
    int *pattern = (int *)malloc(pattern_length * 2 * sizeof(int));
    if (pattern == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        gpioTerminate();
        return 1;
    }

    while (!shutdown_flag) {
        generate_pattern(pattern, pattern_length);
        if (play_pattern(pattern, pattern_length) < 0) {
            fprintf(stderr, "Pattern playback error\n");
            break;
        }
    }

    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);
    free(pattern);
    gpioTerminate();
    return 0;
}

