#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27
#define CALIBRATION_FILE "calibration.txt"
#define CALIBRATION_SAMPLES 100
#define WEIGHT_THRESHOLD 10.0
#define READ_TIMEOUT_US 500000
#define LOOP_DELAY_US 500000

static volatile sig_atomic_t running = 1;
static double scale_factor = 1.0;
static double offset = 0.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int data_pin, int clock_pin, long *out_value) {
    long value = 0;
    int i;

    gpioSetMode(data_pin, PI_INPUT);
    gpioSetMode(clock_pin, PI_OUTPUT);
    gpioWrite(clock_pin, 0);

    for (i = 0; i < 24; i++) {
        gpioWrite(clock_pin, 1);
        gpioDelay(1);
        value <<= 1;
        if (gpioRead(data_pin)) {
            value |= 1;
        }
        gpioWrite(clock_pin, 0);
        gpioDelay(1);
    }

    gpioWrite(clock_pin, 1);
    gpioDelay(1);
    gpioWrite(clock_pin, 0);
    gpioDelay(1);

    if (value & 0x800000) {
        value |= 0xFF000000;
    }

    *out_value = value;
    return 0;
}

static double calibrate_hx711(int data_pin, int clock_pin) {
    long sum = 0;
    int i;

    printf("Calibrating HX711 (zero load)...\n");
    for (i = 0; i < CALIBRATION_SAMPLES; i++) {
        long raw;
        if (read_hx711(data_pin, clock_pin, &raw) != 0) {
            fprintf(stderr, "HX711 read failed during calibration\n");
            return -1.0;
        }
        sum += raw;
        gpioDelay(1000);
    }
    return (double)sum / CALIBRATION_SAMPLES;
}

static int save_calibration(double scale, double offset) {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (!fp) {
        perror("fopen calibration.txt");
        return -1;
    }
    fprintf(fp, "%.6f %.6f\n", scale, offset);
    fclose(fp);
    return 0;
}

static int load_calibration(void) {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Calibration file not found; using defaults\n");
        return -1;
    }
    if (fscanf(fp, "%lf %lf", &scale_factor, &offset) != 2) {
        fprintf(stderr, "Invalid calibration file; using defaults\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    printf("Loaded calibration: scale=%.6f offset=%.6f\n", scale_factor, offset);
    return 0;
}

static double read_weight(int data_pin, int clock_pin) {
    long raw;
    if (read_hx711(data_pin, clock_pin, &raw) != 0) {
        return -1.0;
    }
    return ((double)raw - offset) / scale_factor;
}

static void control_solenoid(int pin, int state) {
    gpioWrite(pin, state);
}

static void log_weight(double weight) {
    FILE *fp = fopen("weight_log.txt", "a");
    if (!fp) {
        perror("fopen weight_log.txt");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, weight);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    if (load_calibration() != 0) {
        scale_factor = 1.0;
        offset = 0.0;
    }

    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    control_solenoid(SOLENOID_PIN, 0);

    if (calibrate_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN) < 0) {
        fprintf(stderr, "Calibration failed\n");
        gpioTerminate();
        return 1;
    }

    if (save_calibration(scale_factor, offset) != 0) {
        fprintf(stderr, "Warning: could not save calibration\n");
    }

    printf("Starting weight monitoring (threshold %.1f kg)...\n", WEIGHT_THRESHOLD);

    while (running) {
        double weight = read_weight(HX711_DATA_PIN, HX711_CLOCK_PIN);
        if (weight < 0) {
            fprintf(stderr, "HX711 read error; skipping iteration\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        log_weight(weight);

        if (weight > WEIGHT_THRESHOLD) {
            control_solenoid(SOLENOID_PIN, 1);
            printf("Weight %.2f kg > %.1f kg; locking\n", weight, WEIGHT_THRESHOLD);
        } else {
            control_solenoid(SOLENOID_PIN, 0);
            printf("Weight %.2f kg <= %.1f kg; unlocking\n", weight, WEIGHT_THRESHOLD);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    control_solenoid(SOLENOID_PIN, 0);
    gpioTerminate();
    return 0;
}

