#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

#define HX711_DT 23
#define HX711_SCK 24
#define SOLENOID_PIN 17
#define WEIGHT_THRESHOLD 100.0
#define LOCK_DURATION 5
#define READ_INTERVAL 1
#define HX711_TIMEOUT_US 1000000
#define HX711_SETTLE_US 1
#define HX711_READY_THRESHOLD 100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int hx711_read(int dt_pin, int sck_pin, long *out) {
    if (out == NULL) return -1;

    if (gpioSetMode(dt_pin, PI_INPUT) < 0) return -2;
    if (gpioSetMode(sck_pin, PI_OUTPUT) < 0) return -2;
    if (gpioWrite(sck_pin, 0) < 0) return -2;

    uint32_t start = gpioTick();
    while (gpioRead(dt_pin) == 1) {
        if ((gpioTick() - start) > HX711_TIMEOUT_US) return -1;
    }

    long count = 0;
    for (int i = 0; i < 24; i++) {
        if (gpioWrite(sck_pin, 1) < 0) return -2;
        gpioDelay(HX711_SETTLE_US);
        count <<= 1;
        if (gpioWrite(sck_pin, 0) < 0) return -2;
        gpioDelay(HX711_SETTLE_US);
        if (gpioRead(dt_pin) == 1) count++;
    }

    if (gpioWrite(sck_pin, 1) < 0) return -2;
    gpioDelay(HX711_SETTLE_US);
    if (gpioWrite(sck_pin, 0) < 0) return -2;
    gpioDelay(HX711_SETTLE_US);

    if (count & 0x800000) count |= 0xFF000000;
    *out = count;
    return 0;
}

static double hx711_calibrate(long raw) {
    return (double)raw / 1000.0;
}

static int log_event(const char *event) {
    FILE *fp = fopen("stock_events.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening stock_events.txt: %s\n", strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s: %s\n", ts, event);
    } else {
        fprintf(fp, "(unknown time): %s\n", event);
    }
    fclose(fp);
    return 0;
}

static int activate_lock(int pin, int duration) {
    if (gpioWrite(pin, 1) < 0) {
        fprintf(stderr, "Error activating solenoid on GPIO%d\n", pin);
        return -1;
    }
    gpioDelay(duration * 1000000);
    if (gpioWrite(pin, 0) < 0) {
        fprintf(stderr, "Error deactivating solenoid on GPIO%d\n", pin);
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SOLENOID_PIN);
        gpioTerminate();
        return 1;
    }
    gpioWrite(SOLENOID_PIN, 0);

    printf("Kitchen ingredient stock monitor started. Press Ctrl+C to exit.\n");

    while (running) {
        long raw;
        if (hx711_read(HX711_DT, HX711_SCK, &raw) != 0) {
            fprintf(stderr, "HX711 read error (timeout or GPIO failure)\n");
            gpioDelay(READ_INTERVAL * 1000000);
            continue;
        }

        double weight = hx711_calibrate(raw);
        printf("Weight: %.2f g\n", weight);

        if (weight < WEIGHT_THRESHOLD) {
            printf("Weight below threshold. Activating solenoid lock.\n");
            if (activate_lock(SOLENOID_PIN, LOCK_DURATION) == 0) {
                if (log_event("Solenoid lock activated") != 0) {
                    fprintf(stderr, "Failed to log event\n");
                }
            }
        }

        gpioDelay(READ_INTERVAL * 1000000);
    }

    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return 0;
}

