#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "security.log"
#define CALIBRATION_KG 5.0
#define WEIGHT_THRESHOLD 5.0
#define UNLOCK_DURATION 5
#define HX711_TIMEOUT_US 100000
#define CLOCK_HIGH_US 1
#define CLOCK_LOW_US 1

static volatile sig_atomic_t running = 1;
static double calibration_factor = 1.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int32_t *out) {
    int i;
    uint32_t start, now;

    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(HX711_DATA_PIN, PI_INPUT);

    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(CLOCK_LOW_US);

    start = gpioTick();
    while (gpioRead(HX711_DATA_PIN) == 1) {
        now = gpioTick();
        if ((now - start) > HX711_TIMEOUT_US) {
            fprintf(stderr, "HX711 timeout waiting for data line low\n");
            return -1;
        }
    }

    int32_t value = 0;
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(CLOCK_HIGH_US);
        value = (value << 1) | (gpioRead(HX711_DATA_PIN) & 1);
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(CLOCK_LOW_US);
    }

    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(CLOCK_HIGH_US);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(CLOCK_LOW_US);

    if (value & 0x800000) {
        value |= 0xFF000000;
    }

    *out = value;
    return 0;
}

static double get_weight(int32_t raw) {
    return (double)raw / calibration_factor;
}

static int calibrate_hx711(void) {
    int32_t raw;
    double weight;

    printf("Place a known weight on the load cell and enter its weight in kg: ");
    fflush(stdout);
    if (scanf("%lf", &weight) != 1) {
        fprintf(stderr, "Invalid input for weight\n");
        return -1;
    }
    while (getchar() != '\n');

    if (weight <= 0.0) {
        fprintf(stderr, "Weight must be positive\n");
        return -1;
    }

    if (read_hx711(&raw) != 0) {
        fprintf(stderr, "Failed to read HX711 during calibration\n");
        return -1;
    }

    calibration_factor = (double)raw / weight;
    printf("Calibration factor: %f\n", calibration_factor);

    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (!fp) {
        perror("Error opening calibration file");
        return -1;
    }
    fprintf(fp, "%f", calibration_factor);
    fclose(fp);

    return 0;
}

static int load_calibration(void) {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Calibration file not found, using default factor 1.0\n");
        return -1;
    }
    if (fscanf(fp, "%lf", &calibration_factor) != 1) {
        fprintf(stderr, "Error reading calibration factor from file\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    printf("Loaded calibration factor: %f\n", calibration_factor);
    return 0;
}

static void log_event(double weight) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Weight: %.2f kg\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, weight);
    fclose(fp);
}

static void unlock_solenoid(void) {
    gpioWrite(SOLENOID_PIN, 1);
    printf("Solenoid locked\n");
    gpioDelay(UNLOCK_DURATION * 1000000);
    gpioWrite(SOLENOID_PIN, 0);
    printf("Solenoid unlocked\n");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    gpioWrite(SOLENOID_PIN, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        gpioTerminate();
        return 1;
    }

    if (load_calibration() != 0) {
        if (calibrate_hx711() != 0) {
            gpioTerminate();
            return 1;
        }
    }

    printf("Weight monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int32_t raw;
        if (read_hx711(&raw) != 0) {
            fprintf(stderr, "HX711 read error, retrying...\n");
            gpioDelay(1000000);
            continue;
        }

        double weight = get_weight(raw);
        printf("Weight: %.2f kg\n", weight);

        if (weight > WEIGHT_THRESHOLD) {
            log_event(weight);
            unlock_solenoid();
        }

        gpioDelay(100000);
    }

    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

