#define SENSOR_PIN 16
#define RELAY_PIN 20
#define LOG_FILE "relay_events.log"
#define CHIP_NAME "gpiochip0"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(int relay_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Relay toggled to %s\n", timestamp, relay_state ? "ON" : "OFF") < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor_line = NULL;
    struct gpiod_line *relay_line = NULL;
    int relay_state = 0;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip '%s': %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        fprintf(stderr, "Failed to get sensor line %d: %s\n", SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        fprintf(stderr, "Failed to get relay line %d: %s\n", RELAY_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(sensor_line, "ky022_sensor") < 0) {
        fprintf(stderr, "Failed to request sensor line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(relay_line, "srd05_relay", 0) < 0) {
        fprintf(stderr, "Failed to request relay line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Monitoring KY-022 sensor on GPIO%d, controlling Songle relay on GPIO%d.\n", SENSOR_PIN, RELAY_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int sensor_val = gpiod_line_get_value(sensor_line);
        if (sensor_val < 0) {
            fprintf(stderr, "Error reading sensor value: %s\n", strerror(errno));
            usleep(100000);
            continue;
        }

        /* KY-022 is active-low: LOW (0) means obstacle detected */
        if (sensor_val == 0) {
            relay_state = !relay_state;
            if (gpiod_line_set_value(relay_line, relay_state) < 0) {
                fprintf(stderr, "Error setting relay state: %s\n", strerror(errno));
            } else {
                if (log_event(relay_state) < 0) {
                    fprintf(stderr, "Warning: failed to log relay event.\n");
                }
            }
        }

        usleep(100000); /* 100 ms polling interval */
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
    }
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Cleanup complete. Exiting.\n");
    return ret;
}

