#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define CONFIG_FILE "watering.conf"
#define GPIO_CHIP_NAME "gpiochip0"
#define VALVE_LINE_OFFSET 18
#define MIN_DURATION 1
#define MAX_DURATION 3600

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int parse_config(const char *filename, int *duration)
{
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error opening config file '%s': %s\n",
                filename, strerror(errno));
        return -1;
    }

    char line[256];
    int found = 0;
    int val;

    while (fgets(line, sizeof(line), fp)) {
        /* Strip trailing newline */
        line[strcspn(line, "\r\n")] = '\0';

        /* Skip blank lines */
        if (line[0] == '\0')
            continue;

        if (sscanf(line, "duration=%d", &val) == 1) {
            if (val >= MIN_DURATION && val <= MAX_DURATION) {
                *duration = val;
                found = 1;
                break;
            }
            fprintf(stderr,
                    "Invalid duration '%d' in config (must be %d-%d)\n",
                    val, MIN_DURATION, MAX_DURATION);
            fclose(fp);
            return -1;
        }
        fprintf(stderr, "Warning: ignoring unknown config line: '%s'\n", line);
    }

    if (!found) {
