#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_LEFT  4
#define SENSOR_MIDDLE 17
#define SENSOR_RIGHT 27
#define MOTOR_L_PWM  22
#define MOTOR_L_IN1  23
#define MOTOR_L_IN2  24
#define MOTOR_R_PWM  25
#define MOTOR_R_IN1  26
#define MOTOR_R_IN2  27
#define BASE_SPEED   150
#define PWM_FREQ     1000
#define LOOP_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_data(int sL, int sM, int sR, int lSpeed, int rSpeed) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    if (log_file) {
        fprintf(log_file, "%s, S:%d,%d,%d, L:%d, R:%d\n",
                timestamp, sL, sM, sR, lSpeed, rSpeed);
        fflush(log_file);
    }
}

static int set_motor(int pwmPin, int speed) {
    if (speed < 0) speed = 0;
    if (speed > 255) speed = 255;
    if (gpioPWM(pwmPin, speed) < 0) return -1;
    if (speed > 0) {
        if (gpioWrite(pwmPin, 1) < 0) return -1;
    } else {
        if (gpioWrite(pwmPin, 0) < 0) return -1;
    }
    return 0;
}

static void stop_motors(void) {
    set_motor(MOTOR_L_PWM, 0);
    set_motor(MOTOR_R_PWM, 0);
    gpioWrite(MOTOR_L_IN1, 0);
    gpioWrite(MOTOR_L_IN2, 0);
    gpioWrite(MOTOR_R_IN1, 0);
    gpioWrite(MOTOR_R_IN2, 0);
}

static void drive_straight(int speed) {
    set_motor(MOTOR_L_PWM, speed);
    set_motor(MOTOR_R_PWM, speed);
    gpioWrite(MOTOR_L_IN1, 1);
    gpioWrite(MOTOR_L_IN2, 0);
    gpioWrite(MOTOR_R_IN1, 1);
    gpioWrite(MOTOR_R_IN2, 0);
}

static void turn_right(int speed) {
    set_motor(MOTOR_L_PWM, speed);
    set_motor(MOTOR_R_PWM, speed / 2);
    gpioWrite(MOTOR_L_IN1, 1);
    gpioWrite(MOTOR_L_IN2, 0);
    gpioWrite(MOTOR_R_IN1, 0);
    gpioWrite(MOTOR_R_IN2, 1);
}

static void turn_left(int speed) {
    set_motor(MOTOR_L_PWM, speed / 2);
    set_motor(MOTOR_R_PWM, speed);
    gpioWrite(MOTOR_L_IN1, 0);
    gpioWrite(MOTOR_L_IN2, 1);
    gpioWrite(MOTOR_R_IN1, 1);
    gpioWrite(MOTOR_R_IN2, 0);
}

int main(void) {
    int sensor_left, sensor_middle, sensor_right;
    int left_motor_speed, right_motor_speed;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_LEFT, PI_INPUT) < 0 ||
        gpioSetMode(SENSOR_MIDDLE, PI_INPUT) < 0 ||
        gpioSetMode(SENSOR_RIGHT, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set sensor GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR_L_PWM, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_L_IN1, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_L_IN2, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_R_PWM, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_R_IN1, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_R_IN2, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set motor GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(MOTOR_L_PWM, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(MOTOR_R_PWM, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("trace_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Line following robot started. Press Ctrl+C to stop.\n");

    while (running) {
        sensor_left = gpioRead(SENSOR_LEFT);
        sensor_middle = gpioRead(SENSOR_MIDDLE);
        sensor_right = gpioRead(SENSOR_RIGHT);

        if (sensor_left < 0 || sensor_middle < 0 || sensor_right < 0) {
            fprintf(stderr, "Error reading sensor GPIOs\n");
            break;
        }

        if (sensor_middle == 0) {
            drive_straight(BASE_SPEED);
        } else if (sensor_left == 0 && sensor_right == 1) {
            turn_right(BASE_SPEED);
        } else if (sensor_right == 0 && sensor_left == 1) {
            turn_left(BASE_SPEED);
        } else {
            stop_motors();
        }

        log_data(sensor_left, sensor_middle, sensor_right,
                 (sensor_middle == 0) ? BASE_SPEED : 0,
                 (sensor_middle == 0) ? BASE_SPEED : 0);

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    stop_motors();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

