    struct tm tm;
    localtime_r(&ts.tv_sec, &tm);
    char tbuf[64];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s.%03ld: %s, lux=%d\n", tbuf, ts.tv_nsec / 1000000, event, lux);
    fclose(fp);
}

static int read_bh1750(int handle, float *lux_out) {
    if (i2cWriteByte(handle, 0x10) < 0) {
        log_event("I2C write error (power on)", -1);
        return -1;
    }
    gpioDelay(180000);

    char buf[2];
    int n = i2cReadDevice(handle, buf, 2);
    if (n != 2) {
        log_event("I2C read error", -1);
        return -1;
    }
    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    int relay_state = 0;
    while (running) {
        float lux;
        if (read_bh1750(i2c_handle, &lux) == 0) {
            printf("Lux: %.2f\n", lux);
            if (lux < LUX_THRESHOLD && relay_state == 0) {
                gpioWrite(RELAY_GPIO, 1);
                relay_state = 1;
                log_event("Grow lamp ON", (int)lux);
            } else if (lux >= LUX_THRESHOLD && relay_state == 1) {
                gpioWrite(RELAY_GPIO, 0);
                relay_state = 0;
                log_event("Grow lamp OFF", (int)lux);
            }
        } else {
            log_event("Sensor read error", -1);
        }
        gpioDelay(5000000);
    }

    gpioWrite(RELAY_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

