    }
    if (gpiod_line_request_input(*line, "sound_sensor") < 0) {
        log_msg("Failed to request sound sensor line as input");
        gpiod_chip_close(*chip);
        *chip = NULL;
        *line = NULL;
        return -1;
    }
    return 0;
}

static int init_alarm_led(struct gpiod_chip **chip, struct gpiod_line **line) {
    *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!*chip) {
        log_msg("Failed to open gpiochip4 for alarm LED");
        return -1;
    }
    *line = gpiod_chip_get_line(*chip, ALARM_LED_GPIO);
    if (!*line) {
        log_msg("Failed to get alarm LED line");
        gpiod_chip_close(*chip);
        *chip = NULL;
        *line = NULL;
        return -1;
    }
    if (gpiod_line_request_output(*line, "alarm_led", 0) < 0) {
        log_msg("Failed to request alarm LED line as output");
        gpiod_chip_close(*chip);
        *chip = NULL;
        *line = NULL;
        return -1;
    }
    return 0;
}

static void trigger_alarm(struct gpiod_line *led) {
    if (gpiod_line_set_value(led, 1) < 0) {
        log_msg("Failed to turn on alarm LED");
        return;
    }
    sleep_us(ALARM_DURATION_S * 1000000);
    if (gpiod_line_set_value(led, 0) < 0) {
        log_msg("Failed to turn off alarm LED");
    }
}

static void *sound_sensor_thread(void *arg) {
    struct gpiod_chip *chip = (struct gpiod_chip *)arg;
    struct gpiod_line *line = NULL;
    int ret = 0;
    int last_val = 1;

    while (running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            log_msg("Error reading sound sensor");
            ret = -1;
            break;
        }
        if (val == 0 && last_val == 1) {
            log_msg("Sound detected!");
            zmq_msg_t msg;
            zmq_msg_init(&msg);
            if (zmq_msg_init_size(&msg, 256) < 0) {
                log_msg("zmq_msg_init_size failed");
                zmq_msg_close(&msg);
                ret = -1;
                break;
            }
            zmq_msg_recv(&msg, zmq_ctx_t *ctx, 0);
            zmq_msg_send(&msg, zmq_ctx_t *ctx, 0);
            zmq_msg_close(&msg);
        }
        last_val = val;
        sleep_us(POLL_INTERVAL_US);
    }
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return NULL;
}

static void *alarm_node_thread(void *arg) {
    zmq_ctx_t *ctx = zmq_ctx_new();
    if (!ctx) {
        log_msg("zmq_ctx_new failed");
        return NULL;
    }
    zmq_ctx_set_option(ctx, ZMQ_IDENTITY, "alarm_node");
    zmq_ctx_set_option(ctx, ZMQ_SUBSCRIBE, ZMQ_TOPIC);

    int rc = zmq_connect(ctx, ZMQ_HOST, ZMQ_PORT);
    if (rc != 0) {
        log_msg("zmq_connect failed");
        zmq_ctx_destroy(ctx);
        return NULL;
    }

    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led = NULL;
    if (init_alarm_led(&chip, &led) < 0) {
        log_msg("Failed to init alarm LED");
        zmq_disconnect(ctx, ZMQ_HOST, ZMQ_PORT);
        zmq_ctx_destroy(ctx);
        return NULL;
    }

    while (running) {
        zmq_msg_t msg;
        int rc = zmq_recvmsg(ctx, &msg, 0);
        if (rc == 0) {
            trigger_alarm(led);
        } else if (rc == EINTR) {
            continue;
        } else {
            log_msg("zmq_recvmsg failed");
        }
    }

    gpiod_line_release(led);
    gpiod_chip_close(chip);
    zmq_disconnect(ctx, ZMQ_HOST, ZMQ_PORT);
    zmq_ctx_destroy(ctx);
    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <sound_sensor|alarm_node>\n", argv[0]);
        return 1;
    }

    const char *mode = argv[1];
    if (strcmp(mode, "sound_sensor") == 0) {
        struct gpiod_chip *chip = NULL;
        struct gpiod_line *line = NULL;
        if (init_gpio(&chip, &line) < 0) {
            return 1;
        }

        zmq_ctx_t *ctx = zmq_ctx_new();
        if (!ctx) {
            log_msg("zmq_ctx_new failed");
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return 1;
        }

        zmq_ctx_set_option(ctx, ZMQ_IDENTITY, "sound_sensor");
        zmq_ctx_set_option(ctx, ZMQ_PUB, ZMQ_TOPIC);

        int rc = zmq_bind(ctx, ZMQ_HOST, ZMQ_PORT);
        if (rc != 0) {
            log_msg("zmq_bind failed");
            zmq_ctx_destroy(ctx);
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return 1;
        }

        pthread_t tid;
        if (pthread_create(&tid, NULL, sound_sensor_thread, chip) != 0) {
            log_msg("Failed to create sound sensor thread");
            zmq_unbind(ctx, ZMQ_HOST, ZMQ_PORT);
            zmq_ctx_destroy(ctx);
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return 1;
        }
        pthread_detach(tid);

        while (running) {
            sleep(1);
        }

        zmq_unbind(ctx, ZMQ_HOST, ZMQ_PORT);
        zmq_ctx_destroy(ctx);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 0;
    } else if (strcmp(mode, "alarm_node") == 0) {
        pthread_t tid;
        if (pthread_create(&tid, NULL, alarm_node_thread, NULL) != 0) {
            log_msg("Failed to create alarm node thread");
            return 1;
        }
        pthread_detach(tid);

        while (running) {
            sleep(1);
        }
        return 0;
    } else {
        fprintf(stderr, "Invalid mode: %s\n", mode);
        return 1;
    }
}

