#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define IR_GPIO 17
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"
#define MAX_PULSES 68
#define PULSE_TIMEOUT_US 150000

static volatile sig_atomic_t running = 1;
static volatile uint32_t pulse_times[MAX_PULSES];
static volatile int pulse_count = 0;
static volatile uint32_t last_tick = 0;
static volatile bool decoding = false;
static volatile bool frame_ready = false;
static volatile uint32_t last_frame = 0;
static MQTTClient mqtt_client;
static MQTTClient_connectOptions mqtt_opts;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void ir_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 0) {
        uint32_t diff = tick - last_tick;
        if (diff > PULSE_TIMEOUT_US) {
            if (pulse_count < MAX_PULSES) {
                pulse_times[pulse_count++] = diff;
            }
        }
        last_tick = tick;
        if (pulse_count >= 68) {
            decoding = true;
            frame_ready = true;
            last_frame = tick;
        }
    }
}

static bool decode_nec(uint32_t *addr, uint32_t *cmd) {
    if (pulse_count < 68) return false;
    if (pulse_times[0] < 8000 || pulse_times[0] > 10000) return false;
    if (pulse_times[1] < 4000 || pulse_times[1] > 5000) return false;
    uint32_t addr_raw = 0, cmd_raw = 0;
    for (int i = 0; i < 32; i++) {
        int idx = 2 + i * 2;
        if (pulse_times[idx] < 400 || pulse_times[idx] > 700) return false;
        if (pulse_times[idx + 1] > 1400) {
            addr_raw |= (1u << i);
        } else if (pulse_times[idx + 1] > 500) {
            return false;
        }
    }
    for (int i = 0; i < 32; i++) {
        int idx = 34 + i * 2;
        if (pulse_times[idx] < 400 || pulse_times[idx] > 700) return false;
        if (pulse_times[idx + 1] > 1400) {
            cmd_raw |= (1u << i);
        } else if (pulse_times[idx + 1] > 500) {
            return false;
        }
    }
    uint8_t addr_lo = addr_raw & 0xFF;
    uint8_t addr_hi = (addr_raw >> 8) & 0xFF;
    uint8_t cmd_lo = cmd_raw & 0xFF;
    uint8_t cmd_hi = (cmd_raw >> 8) & 0xFF;
    if ((uint8_t)(~addr_lo) != addr_hi) return false;
    if ((uint8_t)(~cmd_lo) != cmd_hi) return false;
    *addr = addr_raw;
    *cmd = cmd_raw;
    return true;
}

static void publish_message(const char *message) {
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    pubmsg.payload = (void *)message;
    pubmsg.payloadlen = (int)strlen(message);
    pubmsg.qos = 0;
    pubmsg.retained = 0;
    MQTTClient_deliveryToken token;
    int rc = MQTTClient_publishMessage(mqtt_client, MQTT_TOPIC, &pubmsg, &token);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "Failed to publish message: %s", MQTTClient_strerror(rc));
    }
}

int main(void) {
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return 1;
    }

    if (gpioSetMode(IR_GPIO, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as input", IR_GPIO);
        gpioTerminate();
        closelog();
        return 1;
    }

    if (gpioSetPullUpDown(IR_GPIO, PI_PUD_UP) != 0) {
        syslog(LOG_ERR, "Failed to set pull-up on GPIO %d", IR_GPIO);
        gpioTerminate();
        closelog();
        return 1;
    }

    if (gpioSetAlertFunc(IR_GPIO, ir_callback) != 0) {
        syslog(LOG_ERR, "Failed to set alert function on GPIO %d", IR_GPIO);
        gpioTerminate();
        closelog();
        return 1;
    }

    int rc = MQTTClient_create(&mqtt_client, MQTT_BROKER, "ir_decoder", MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "Failed to create MQTT client: %s", MQTTClient_strerror(rc));
        gpioTerminate();
        closelog();
        return 1;
    }

    mqtt_opts.keepAliveInterval = 60;
    mqtt_opts.cleansession = 1;
    rc = MQTTClient_connect(mqtt_client, &mqtt_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", MQTTClient_strerror(rc));
        MQTTClient_destroy(&mqtt_client);
        gpioTerminate();
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "IR decoder started on GPIO %d", IR_GPIO);

    while (running) {
        if (decoding && frame_ready) {
            decoding = false;
            frame_ready = false;
            uint32_t addr = 0, cmd = 0;
            if (decode_nec(&addr, &cmd)) {
                char json[128];
                snprintf(json, sizeof(json),
                         "{\"address\":0x%02X,\"command\":0x%02X}",
                         addr & 0xFF, cmd & 0xFF);
                publish_message(json);
                syslog(LOG_INFO, "Decoded: %s", json);
            } else {
                syslog(LOG_WARNING, "Invalid NEC frame received");
            }
        }
        MQTTClient_yield();
    }

    syslog(LOG_INFO, "Shutting down...");
    MQTTClient_disconnect(mqtt_client, 1000);
    MQTTClient_destroy(&mqtt_client);
    gpioTerminate();
    closelog();
    return 0;
}

