#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <math.h>
#include <stdint.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define I2C_BUS        "/dev/i2c-1"
#define NUM_SENSORS    4
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define BH1750_CMD_OT_HRES 0x20
#define BH1750_CONV_MS  180
#define SAMPLE_MS      1000

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

typedef struct {
    uint8_t addr;
    int fd;
} sensor_t;

static int i2c_open(sensor_t *s) {
    s->fd = open(I2C_BUS, O_RDWR);
    if (s->fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(s->fd, I2C_SLAVE, s->addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", s->addr, strerror(errno));
        close(s->fd);
        s->fd = -1;
        return -1;
    }
    return 0;
}

static int bh1750_read_lux(sensor_t *s, float *lux_out) {
    if (s->fd < 0) return -1;
    uint8_t cmd = BH1750_CMD_OT_HRES;
    ssize_t w = write(s->fd, &cmd, 1);
    if (w != 1) {
        fprintf(stderr, "write(0x%02X): %s\n", cmd, w < 0 ? strerror(errno) : "short write");
        return -1;
    }
    usleep(BH1750_CONV_MS * 1000);
    uint8_t buf[2];
    ssize_t r = read(s->fd, buf, sizeof(buf));
    if (r != 2) {
        fprintf(stderr, "read: %s\n", r < 0 ? strerror(errno) : "short read");
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void broadcast(float lux[NUM_SENSORS]) {
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket");
        return;
    }
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);
    char msg[256];
    int n = snprintf(msg, sizeof(msg), "%d,%.1f;%d,%.1f;%d,%.1f;%d,%.1f",
                     1, lux[0], 2, lux[1], 3, lux[2], 4, lux[3]);
    if (n > 0) {
        if (sendto(sockfd, msg, (size_t)n, 0,
                   (struct sockaddr *)&addr, sizeof(addr)) < 0)
            perror("sendto");
    }
    close(sockfd);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    sensor_t sensors[NUM_SENSORS] = {
        {0x23, -1}, {0x24, -1}, {0x25, -1}, {0x26, -1}
    };

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_open(&sensors[i]) != 0) {
            fprintf(stderr, "Sensor 0x%02X init failed\n", sensors[i].addr);
            for (int j = 0; j < i; j++) close(sensors[j].fd);
            return 1;
        }
    }

    while (g_running) {
        float lux[NUM_SENSORS];
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (bh1750_read_lux(&sensors[i], &lux[i]) != 0)
                lux[i] = NAN;
        }
        broadcast(lux);
        usleep(SAMPLE_MS * 1000);
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (sensors[i].fd >= 0) close(sensors[i].fd);
    }
    return 0;
}

