#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define I2C_ADDR       0x28
#define LOG_FILE       "airflow_log.txt"
#define SAMPLE_PERIOD  1
#define MAX_RETRIES    3
#define RETRY_DELAY_MS 100

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int i2c_read_flow(int fd, float *flow_out)
{
    uint8_t buf[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        ssize_t n = read(fd, buf, sizeof(buf));
        if (n == 2) {
            uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
            raw &= 0x3FFF;
            *flow_out = (float)(raw - 3277) * 0.1f;
            return 0;
        }
        if (n < 0) {
            if (errno == ENXIO) {
                fprintf(stderr, "Sensor absent (ENXIO)\n");
                return -1;
            }
            if (errno == EIO) {
                fprintf(stderr, "I2C bus error (EIO)\n");
                return -1;
            }
            fprintf(stderr, "read: %s (retry %d/%d)\n", strerror(errno), retries + 1, MAX_RETRIES);
        } else {
            fprintf(stderr, "read: short read (%zd bytes, retry %d/%d)\n", n, retries + 1, MAX_RETRIES);
        }
        retries++;
        if (retries < MAX_RETRIES) {
            usleep(RETRY_DELAY_MS * 1000);
        }
    }
    return -1;
}

static void log_flow(FILE *fp, float flow)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, %.2f\n", ts, flow);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = i2c_open(I2C_BUS, I2C_ADDR);
    if (g_i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float flow;
        if (i2c_read_flow(g_i2c_fd, &flow) == 0) {
            log_flow(g_log_fp, flow);
        } else {
            fprintf(stderr, "Failed to read flow after %d retries.\n", MAX_RETRIES);
        }
        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
    }
    return EXIT_SUCCESS;
}

