#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define AS7341_ADDR 0x39
#define I2C_BUS "/dev/i2c-1"

#define AS7341_REG_ENABLE 0x80
#define AS7341_REG_CFG6 0xAF
#define AS7341_REG_WHO_AM_I 0x24
#define AS7341_REG_F1DATAL 0x60
#define AS7341_REG_F2DATAL 0x62
#define AS7341_REG_F3DATAL 0x64
#define AS7341_REG_F4DATAL 0x66
#define AS7341_REG_F5DATAL 0x68
#define AS7341_REG_F6DATAL 0x6A
#define AS7341_REG_F7DATAL 0x6C
#define AS7341_REG_F8DATAL 0x6E
#define AS7341_REG_CDATAL 0x70
#define AS7341_REG_NIRDATAL 0x72

#define AS7341_WHO_AM_I_VAL 0x19

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read 16-bit from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int init_as7341(int fd) {
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(fd, AS7341_REG_WHO_AM_I, &who_am_i) < 0) {
        return -1;
    }
    if (who_am_i != AS7341_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who_am_i, AS7341_WHO_AM_I_VAL);
        return -1;
    }

    if (i2c_write_reg8(fd, AS7341_REG_ENABLE, 0x01) < 0) return -1;
    usleep(10000);

    if (i2c_write_reg8(fd, AS7341_REG_CFG6, 0x00) < 0) return -1;

    if (i2c_write_reg8(fd, AS7341_REG_ENABLE, 0x01 | 0x08) < 0) return -1;
    usleep(10000);

    return 0;
}

static int read_spectral_data(int fd, uint16_t *f1, uint16_t *f2, uint16_t *f3, uint16_t *f4,
                              uint16_t *f5, uint16_t *f6, uint16_t *f7, uint16_t *f8,
                              uint16_t *clear, uint16_t *nir) {
    if (i2c_read_reg16(fd, AS7341_REG_F1DATAL, f1) < 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_F2DATAL, f2) < 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_F3DATAL, f3) < 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_F4DATAL, f4) < 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_F5DATAL, f5) < 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_F6DATAL, f6) < 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_F7DATAL, f7) < 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_F8DATAL, f8) < 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_CDATAL, clear) < 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_NIRDATAL, nir) < 0) return -1;
    return 0;
}

static float calculate_lux(uint16_t f1, uint16_t f2, uint16_t f3, uint16_t f4,
                           uint16_t f5, uint16_t f6, uint16_t f7, uint16_t f8,
                           uint16_t clear, uint16_t nir) {
    float sum = (float)(f1 + f2 + f3 + f4 + f5 + f6 + f7 + f8);
    float ratio = (float)clear / (sum + 1.0f);
    float lux = ratio * 0.1f;
    return lux;
}

static void log_data(FILE *fp, float lux) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, lux);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AS7341_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", AS7341_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (init_as7341(i2c_fd) < 0) {
        fprintf(stderr, "AS7341 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen("spectral_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    while (running) {
        uint16_t f1, f2, f3, f4, f5, f6, f7, f8, clear, nir;
        if (read_spectral_data(i2c_fd, &f1, &f2, &f3, &f4, &f5, &f6, &f7, &f8, &clear, &nir) == 0) {
            float lux = calculate_lux(f1, f2, f3, f4, f5, f6, f7, f8, clear, nir);
            log_data(log_file, lux);
        } else {
            fprintf(stderr, "Failed to read spectral data.\n");
        }
        sleep(5);
    }

    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

