#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define DEFAULT_I2C_ADDRESS 0x37
#define DEFAULT_INTERVAL 1
#define DEFAULT_FILENAME "seismic_data.csv"
#define I2C_BUS "/dev/i2c-1"
#define ERROR_LOG "seismic_error.log"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define NUM_AXES 6
#define ACCEL_SCALE 0.000244f

static int i2c_fd = -1;
static FILE *csv_fp = NULL;
static FILE *err_fp = NULL;
static volatile sig_atomic_t running = 1;

static void log_error(const char *msg) {
    if (!err_fp) return;
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(err_fp, "%04d-%02d-%02d %02d:%02d:%02d: %s (errno=%d: %s)\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            msg, errno, strerror(errno));
    fflush(err_fp);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) return -1;
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

static int read_acceleration(int fd, float *x, float *y, float *z) {
    uint8_t buf[NUM_AXES];
    int16_t raw_x, raw_y, raw_z;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_write_byte(fd, 0x28) < 0) {
            log_error("I2C write (register select) failed");
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        if (i2c_read_bytes(fd, buf, NUM_AXES) < 0) {
            log_error("I2C read (acceleration data) failed");
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        raw_x = (int16_t)((buf[1] << 8) | buf[0]);
        raw_y = (int16_t)((buf[3] << 8) | buf[2]);
        raw_z = (int16_t)((buf[5] << 8) | buf[4]);
        *x = (float)raw_x * ACCEL_SCALE;
        *y = (float)raw_y * ACCEL_SCALE;
        *z = (float)raw_z * ACCEL_SCALE;
        return 0;
    }
    return -1;
}

static void cleanup(void) {
    if (csv_fp) { fclose(csv_fp); csv_fp = NULL; }
    if (err_fp) { fclose(err_fp); err_fp = NULL; }
    if (i2c_fd >= 0) { close(i2c_fd); i2c_fd = -1; }
}

int main(int argc, char *argv[]) {
    int i2c_address = DEFAULT_I2C_ADDRESS;
    int interval = DEFAULT_INTERVAL;
    const char *filename = DEFAULT_FILENAME;

    int opt;
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a': i2c_address = (int)strtol(optarg, NULL, 0); break;
            case 'i': interval = atoi(optarg); break;
            case 'f': filename = optarg; break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_addr] [-i interval_sec] [-f filename]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    err_fp = fopen(ERROR_LOG, "a");
    if (!err_fp) {
        fprintf(stderr, "Warning: cannot open error log %s: %s\n", ERROR_LOG, strerror(errno));
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, i2c_address) < 0) {
        log_error("Failed to set I2C slave address");
        cleanup();
        return EXIT_FAILURE;
    }

    csv_fp = fopen(filename, "a");
    if (!csv_fp) {
        log_error("Failed to open CSV file");
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(csv_fp, 0, SEEK_END);
    if (ftell(csv_fp) == 0) {
        fprintf(csv_fp, "timestamp,x_g,y_g,z_g\n");
        fflush(csv_fp);
    }

    printf("Logging seismic data to %s every %d seconds (I2C 0x%02X). Ctrl+C to stop.\n",
           filename, interval, i2c_address);

    while (running) {
        float x, y, z;
        if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
            time_t t = time(NULL);
            struct tm tm;
            localtime_r(&t, &tm);
            fprintf(csv_fp, "%04d-%02d-%02d %02d:%02d:%02d,%.6f,%.6f,%.6f\n",
                    tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                    tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
            fflush(csv_fp);
        } else {
            log_error("Failed to read acceleration after retries");
        }
        sleep(interval);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

