#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define BH1750_POWER_ON 0x01
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define MULTICAST_TTL 1
#define READ_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int sockfd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device %s: %s\n", I2C_DEVICE, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int init_udp_multicast(void) {
    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        fprintf(stderr, "Error creating socket: %s\n", strerror(errno));
        return -1;
    }
    int ttl = MULTICAST_TTL;
    if (setsockopt(sockfd, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        fprintf(stderr, "Error setting multicast TTL: %s\n", strerror(errno));
        close(sockfd);
        sockfd = -1;
        return -1;
    }
    return 0;
}

static int read_bh1750(float *lux_out) {
    unsigned char cmd = BH1750_POWER_ON;
    if (write(i2c_fd, &cmd, 1) != 1) {
        fprintf(stderr, "Error sending power-on command: %s\n", strerror(errno));
        return -1;
    }
    usleep(10000);
    cmd = BH1750_CONTINUOUS_HIGH_RES_MODE;
    if (write(i2c_fd, &cmd, 1) != 1) {
        fprintf(stderr, "Error sending measurement command: %s\n", strerror(errno));
        return -1;
    }
    usleep(180000);
    unsigned char buf[2];
    if (read(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading light value: %s\n", strerror(errno));
        return -1;
    }
    unsigned int raw = ((unsigned int)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int send_multicast(float lux) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);
    char buffer[32];
    int len = snprintf(buffer, sizeof(buffer), "%.2f", lux);
    if (sendto(sockfd, buffer, len, 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "Error sending multicast: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_i2c() != 0) {
        return EXIT_FAILURE;
    }
    if (init_udp_multicast() != 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        float lux;
        if (read_bh1750(&lux) == 0) {
            if (send_multicast(lux) != 0) {
                fprintf(stderr, "Failed to send multicast data\n");
            }
        } else {
            fprintf(stderr, "Failed to read BH1750 sensor\n");
        }
        sleep(READ_INTERVAL_SEC);
    }

    if (i2c_fd >= 0) close(i2c_fd);
    if (sockfd >= 0) close(sockfd);
    return EXIT_SUCCESS;
}

