        uint32_t w2 = (uint32_t)buf[i+4] | ((uint32_t)buf[i+5] << 8);
        uint32_t w3 = (uint32_t)buf[i+6] | ((uint32_t)buf[i+7] << 8);
        if (w0 == MAGIC_WORD_0 && w1 == MAGIC_WORD_1 && w2 == MAGIC_WORD_2 && w3 == MAGIC_WORD_3) {
            return i;
        }
    }
    return -1;
}

static int parse_frame(const uint8_t *buf, int len, int *objects, int *range, int *velocity) {
