                                ((uint32_t)buf[18] << 16) | ((uint32_t)buf[19] << 24);
    uint32_t subframe_num = (uint32_t)buf[20] | ((uint32_t)buf[21] << 8) |
                            ((uint32_t)buf[22] << 16) | ((uint32_t)buf[23] << 24);
    uint32_t time_stamp = (uint32_t)buf[24] | ((uint32_t)buf[25] << 8) |
                          ((uint32_t)buf[26] << 16) | ((uint32_t)buf[27] << 24);
    uint32_t chirp_profile = (uint32_t)buf[28] | ((uint32_t)buf[29] << 8) |
                             ((uint32_t)buf[30] << 16) | ((uint32_t)buf[31] << 24);
    uint32_t frame_number = (uint32_t)buf[32] | ((uint32_t)buf[33] << 8) |
                            ((uint32_t)buf[34] << 16) | ((uint32_t)buf[35] << 24);
    uint32_t num_tlvs = (uint32_t)buf[36] | ((uint32_t)buf[37] << 8) |
                        ((uint32_t)buf[38] << 16) | ((uint32_t)buf[39] << 24);
    if (total_packet_len > MAX_FRAME_SIZE || total_packet_len > len) return -1;
    int offset = 40;
    *objects = 0;
    *range = 0;
    *velocity = 0;
    for (uint32_t t = 0; t < num_tlvs; t++) {
        uint32_t tlv_type = (uint32_t)buf[offset] | ((uint32_t)buf[offset+1] << 8) |
                            ((uint32_t)buf[offset+2] << 16) | ((uint32_t)buf[offset+3] << 24);
        uint32_t tlv_len = (uint32_t)buf[offset+4] | ((uint32_t)buf[offset+5] << 8) |
                           ((uint32_t)buf[offset+6] << 16) | ((uint32_t)buf[offset+7] << 24);
        offset += 8;
        if (offset + tlv_len > total_packet_len) return -1;
        if (tlv_type == 1 && tlv_len >= 12) {
            int obj_idx = 0;
            while (obj_idx < MAX_OBJECTS && offset + 12 <= total_packet_len) {
                uint16_t range_idx = (uint16_t)buf[offset] | ((uint16_t)buf[offset+1] << 8);
                uint16_t doppler_idx = (uint16_t)buf[offset+2] | ((uint16_t)buf[offset+3] << 8);
                uint16_t peak_val = (uint16_t)buf[offset+4] | ((uint16_t)buf[offset+5] << 8);
                uint16_t x = (uint16_t)buf[offset+6] | ((uint16_t)buf[offset+7] << 8);
                uint16_t y = (uint16_t)buf[offset+8] | ((uint16_t)buf[offset+9] << 8);
                uint16_t z = (uint16_t)buf[offset+10] | ((uint16_t)buf[offset+11] << 8);
                if (peak_val > 0) {
                    objects[obj_idx] = obj_idx;
                    range[obj_idx] = range_idx;
                    velocity[obj_idx] = doppler_idx;
                }
                obj_idx++;
                offset += 12;
            }
            *objects = obj_idx;
        }
        offset += tlv_len;
    }
    return 0;
}

static void log_data(const int *objects, int range, int velocity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    for (int i = 0; i < MAX_OBJECTS; i++) {
        if (objects[i] >= 0) {
            fprintf(csv_fp, "%s,%d,%d,%d\n", ts, objects[i], range, velocity);
        }
    }
    fflush(csv_fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_uart() != 0) {
        gpioTerminate();
        return 1;
    }
    if (init_csv() != 0) {
        cleanup();
        return 1;
    }

    uint8_t frame_buf[MAX_FRAME_SIZE];
    int frame_len = 0;
    int objects[MAX_OBJECTS];
    int range, velocity;

    while (running) {
        int space = MAX_FRAME_SIZE - frame_len;
        if (space <= 0) {
            memmove(frame_buf, frame_buf + frame_len - 1, 1);
            frame_len = 1;
            space = MAX_FRAME_SIZE - 1;
        }
        int n = serRead(uart_fd, (char *)(frame_buf + frame_len), space);
        if (n < 0) {
            log_error("UART read error");
            gpioDelay(100000);
            continue;
        }
        if (n == 0) {
            gpioDelay(10000);
            continue;
        }
        frame_len += n;
        while (frame_len >= 8) {
            int idx = find_magic_word(frame_buf, frame_len);
            if (idx < 0) {
                memmove(frame_buf, frame_buf + 1, frame_len - 1);
                frame_len--;
                continue;
            }
            if (idx > 0) {
                memmove(frame_buf, frame_buf + idx, frame_len - idx);
                frame_len -= idx;
            }
            if (frame_len < 40) break;
            if (parse_frame(frame_buf, frame_len, objects, &range, &velocity) == 0) {
                log_data(objects, range, velocity);
            }
            int remaining = frame_len - 40;
            if (remaining > 0) {
                memmove(frame_buf, frame_buf + 40, remaining);
            }
            frame_len = remaining;
        }
    }

    cleanup();
    return 0;
}

