#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>
#include <sys/select.h>
#include <signal.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define LINE_BUF_SIZE 256
#define READ_TIMEOUT_SEC 2

static volatile sig_atomic_t program_running = 1;
static int uart_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int init_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error from tcgetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;
    tty.c_cflag |= CREAD | CLOCAL;

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 5; /* 0.5 s inter-byte timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int parse_radar_line(const char *line, float *range) {
    char *endptr = NULL;
    errno = 0;
    float val = strtof(line, &endptr);
    if (errno != 0 || endptr == line || *endptr != ',') {
        return -1;
    }
    char *range_str = endptr + 1;
    errno = 0;
    val = strtof(range_str, &endptr);
    if (errno != 0 || endptr == range_str || (*endptr != '\0' && *endptr != '\n' && *endptr != '\r')) {
        return -1;
    }
    *range = val;
    return 0;
}

static void log_detection(float range) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return;
    }
    printf("Timestamp: %s, Range: %.2f meters\n", timestamp, range);
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    uart_fd = init_uart(UART_DEVICE);
    if (uart_fd < 0) {
        return 1;
    }

    char line_buf[LINE_BUF_SIZE];
    size_t line_len = 0;
    char read_buf[128];

    printf("Radar data acquisition started on %s. Press Ctrl+C to exit.\n", UART_DEVICE);

    while (program_running) {
        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(uart_fd, &readfds);

        struct timeval timeout;
        timeout.tv_sec = READ_TIMEOUT_SEC;
        timeout.tv_usec = 0;

        int retval = select(uart_fd + 1, &readfds, NULL, NULL, &timeout);
        if (retval < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error from select: %s\n", strerror(errno));
            break;
        }
        if (retval == 0) {
            fprintf(stderr, "Timeout: no data from radar sensor\n");
            continue;
        }

        ssize_t bytes_read = read(uart_fd, read_buf, sizeof(read_buf) - 1);
        if (bytes_read < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                continue;
            }
            fprintf(stderr, "Error from read: %s\n", strerror(errno));
            break;
        }
        if (bytes_read == 0) {
            fprintf(stderr, "UART closed by peer\n");
            break;
        }

        read_buf[bytes_read] = '\0';

        for (ssize_t i = 0; i < bytes_read; i++) {
            char c = read_buf[i];
            if (c == '\n') {
                line_buf[line_len] = '\0';
                if (line_len > 0) {
                    float range;
                    if (parse_radar_line(line_buf, &range) == 0) {
                        log_detection(range);
                    } else {
                        fprintf(stderr, "Invalid radar data: %s\n", line_buf);
                    }
                }
                line_len = 0;
            } else if (c != '\r') {
                if (line_len < LINE_BUF_SIZE - 1) {
                    line_buf[line_len++] = c;
                } else {
                    fprintf(stderr, "Line too long, discarding\n");
                    line_len = 0;
                }
            }
        }
    }

    if (uart_fd >= 0) {
        close(uart_fd);
        uart_fd = -1;
    }
    printf("Radar data acquisition stopped.\n");
    return 0;
}

