#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <termios.h>
#include <fcntl.h>
#include <errno.h>

#define LEFT_SENSOR   4
#define MIDDLE_SENSOR 17
#define RIGHT_SENSOR  27
#define SERIAL_PORT   "/dev/ttyAMA0"
#define BAUD_RATE     B115200
#define POLL_DELAY_US 100000  /* 100 ms -> 10 Hz */

static volatile sig_atomic_t running = 1;
static int serial_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }
    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);
    gpioSetPullUpDown(LEFT_SENSOR, PI_PUD_UP);
    gpioSetPullUpDown(MIDDLE_SENSOR, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_SENSOR, PI_PUD_UP);
    return 0;
}

static int init_serial(void) {
    serial_fd = open(SERIAL_PORT, O_RDWR | O_NOCTTY | O_NDELAY);
    if (serial_fd < 0) {
        fprintf(stderr, "Error: cannot open %s: %s\n", SERIAL_PORT, strerror(errno));
        return -1;
    }
    /* Clear O_NDELAY so reads block */
    if (fcntl(serial_fd, F_SETFL, 0) < 0) {
        fprintf(stderr, "Error: cannot clear O_NDELAY: %s\n", strerror(errno));
        close(serial_fd);
        serial_fd = -1;
        return -1;
    }
    struct termios tty;
    if (tcgetattr(serial_fd, &tty) != 0) {
        fprintf(stderr, "Error: tcgetattr failed: %s\n", strerror(errno));
        close(serial_fd);
        serial_fd = -1;
        return -1;
    }
    cfsetispeed(&tty, BAUD_RATE);
    cfsetospeed(&tty, BAUD_RATE);
    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);
    tty.c_cc[VMIN]  = 0;
    tty.c_cc[VTIME] = 5;  /* 0.5 s inter-byte timeout */
    if (tcsetattr(serial_fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error: tcsetattr failed: %s\n", strerror(errno));
        close(serial_fd);
        serial_fd = -1;
        return -1;
    }
    return 0;
}

static int read_sensor(int pin) {
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Error: gpioRead(%d) failed.\n", pin);
        return -1;
    }
    return v;
}

static void log_sensor_states(int l, int m, int r) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] Left=%d Middle=%d Right=%d\n", ts, l, m, r);
}

static void send_emergency_stop(void) {
    const char *msg = "EMERGENCY STOP!\n";
    size_t len = strlen(msg);
    ssize_t written = write(serial_fd, msg, len);
    if (written < 0) {
        fprintf(stderr, "Error: write to serial port failed: %s\n", strerror(errno));
    } else if ((size_t)written != len) {
        fprintf(stderr, "Error: partial serial write (%zd of %zu bytes).\n", written, len);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }
    if (init_serial() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("KY-033 sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int l = read_sensor(LEFT_SENSOR);
        int m = read_sensor(MIDDLE_SENSOR);
        int r = read_sensor(RIGHT_SENSOR);

        if (l < 0 || m < 0 || r < 0) {
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        log_sensor_states(l, m, r);

        if (l == 0 && m == 0 && r == 0) {
            send_emergency_stop();
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    if (serial_fd >= 0) {
        close(serial_fd);
        serial_fd = -1;
    }
    gpioTerminate();
    return 0;
}

